-- Sources: data/i18n/svSE. Lore text adapted from warcraft.wiki.gg (CC BY-SA 4.0); the core add-on's src fields name the articles.
local P = LoreForeverPacks.Begin("LoreForever_Lang_svSE")
P.entries["topic:skyborne"] = {n="Skyborne",s="Skyborne, eller shen'dorei, är en utlöpare av högalverna, ättlingar till rebeller som flydde från Eldre'Thalas efter att ha motsatt sig prins Tortheldrins demoniska pakter. Deras förfäder slöt en desperat överenskommelse med vindandar och flydde från Azeroth för att bo på den flytande ön Zephras Isle i Skywall. I dag har deras elementära välgörare plötsligt försvunnit, och deras flytande fristad hotas av inre splittring och fysisk kollaps.",h="Skyborne, eller shen'dorei, är en utlöpare av högalverna, ättlingar till rebeller som flydde från...",kw={"al'aketh","eldre'thalas","high order","shal'nan","shen'dorei","sky-touched","skyborne","skywall","windshapers","zephras isle"},ang={["class:Mage"]="High Order bland Skyborne bevarar forntida högborne trolldomskonst som fördes ut ur Eldre'Thalas och försöker rädda sin sönderfallande ö genom sträng arkanisk mästarkonst.",["class:Shaman"]="Windshapers representerar en alvisk ättelinje som är djupt sammanflätad med Skywalls vindandar och förlitar sig på elementär gemenskap snarare än sina högborne förfäders arkaniska traditioner.",["race:NightElf"]="Skyborne delar direkta blodsband med de forntida Shen'dralar och de nordliga nattalverna, även om årtusenden i Skywall har förändrat deras kroppar till högalver med allt vanligare elementär blå hud."},sec={{t="Flykt från Eldre'Thalas",b="Efter Sunderingen tynade Shen'dralar i Eldre'Thalas bort utan Evighetens brunn. Prins Tortheldrin utformade en mörk räddning: att kalla på demonen Immol'thar och suga åt sig dess kraft. Förfärade adelsmän och invånare gjorde motstånd, rädda för ännu en invasion från Legion. Som svar lät Tortheldrin genomföra en blodig utrensning av dussintals hus. Ur skuggorna bland de överlevande växte ett motstånd lett av en maskerad gestalt som bara var känd som Shal'nan, den beslöjade. När ett desperat rebellanfall mot Tortheldrins ritualhelgedom övergick i kaotisk magi med katastrofala följder, samlade Shal'nan de överlevande och flydde västerut till hamnen Eldre'narr. De gav sig ut till havs, förföljda av prinsens flotta."},{t="Fristad i skyn",b="När de landsförvisade trängdes in på öppet hav slöt de en pakt med ursprungliga vindandar. Dessa väsen lyfte Zephras Isle rakt upp i skyn och förankrade den tryggt i Skywall, luftens elementplan. Befriad från enväldet avgick Shal'nan under invigningen av De fyra vindarnas helgedom och överlät styret åt ett valt råd. Under årtusenden i denna främmande värld utvecklades nattalverna i exil till ljusa, slanka högalver. Under de senaste generationerna har ett elementärt inflytande kallat Sky-Touched Blessing uppstått, vilket gör att allt fler barn föds med blekblå hud."},{t="Ett bräckligt lugn",b="I århundraden blomstrade livet i Skywall i isolering. Vindandarna förbjöd strängt att man nämnde Vindherren Al'Akir och avfärdade frågor med en kuslig oro. För några århundraden sedan inträffade en katastrof: de elementära välgörarna försvann utan förklaring, och Shal'nan försvann tillsammans med dem. Utan sina beskyddare började de arkaniska pelarna som förankrade Zephras Isle svikta. Avlägsna landmassor bröts loss, flyktingar strömmade till det som återstod och desperation drev fram banditer och Al'Aketh, en fanatisk kult hängiven Al'Akir. I dag splittras samhället mellan High Order, som söker räddning genom att återta förfädernas arkaniska magi, och Windshapers, som håller fast vid elementära riter."}},faq={{q="Vilka är Skyborne?",a="Skyborne, eller shen'dorei, de dolda folket, är högalver som härstammar från forntida nattalver som gjorde uppror mot prins Tortheldrin i Eldre'Thalas. För att undkomma hans hämndlystna flotta slöt de en pakt med vindandar, som flyttade deras ö Zephras Isle till luftens elementplan.",al={"vad är skyborne","vilka är shen'dorei","shen'dorei","skybornes bakgrund"}},{q="Varför har vissa Skyborne blå hud?",a="Årtusenden på luftens elementplan har subtilt omformat deras biologi. Ett nyligen uppkommet fenomen kallat Sky-Touched Blessing gör att en allt större andel barn, nu ungefär tre av tio, föds med blå hud. Lärda förutspår att deras ursprungliga nattalvsdrag snart kommer att vara helt undanträngda.",al={"sky-touched blessing","varför är de blå","blå alver","sky-touched"}},{q="Vem var Shal'nan?",a="Shal'nan, den beslöjade, var den maskerade ledaren som stod i spetsen för motståndet mot prins Tortheldrins demoninkallande i Eldre'Thalas. Efter att ha lett de överlevande i säkerhet i Skywall abdikerade han för att inrätta ett demokratiskt råd och tjänade sitt folk tills han försvann under mystiska omständigheter för flera århundraden sedan, tillsammans med deras elementära välgörare.",al={"vem är den beslöjade","shal'nan","den maskerade rebellen","skybornes ledare"}},{q="Vad händer med Zephras Isle?",a="Zephras Isle hålls svävande i Skywall av magiska pelare inställda på elementär kraft. När vindandarna som underhöll dem plötsligt försvann för flera århundraden sedan började förankringspelarna svikta. Delar av landmassan har brutits loss och fallit ut i tomrummet, där överlevande blivit strandsatta och fördrivna alver drivits till banditliv.",al={"varför faller zephras isle sönder","zephras isle faller","vad hände med ön i skywall"}},{q="Vad är High Order och Windshapers?",a="De är Skybornes två främsta kulturella fraktioner. High Order härstammar från högborne magister och försöker återuppbygga sitt sönderfallande samhälle genom disciplinerad arkanisk mästarkonst. Windshapers spårar sina rötter till vanliga nattalvsinvånare och vördar de elementära och andliga sedvänjor som utvecklades under tiden i Skywall.",al={"skybornes fraktioner","high order mot windshapers","windshapers bakgrund"}},{q="Vilka är Al'Aketh?",a="Al'Aketh är en desperat kult av Skyborne som dyrkar Vindherren Al'Akir. Medan deras förfäders elementära välgörare fruktade Al'Akir och undvek att tala om honom, fick Zephras Isles sammanbrott hemlösa och marginaliserade flyktingar att vända sig till elementarherren för räddning och kraft.",al={"al'aketh-kulten","al'akirs kult","skybornes kult"}}},fx={["10ab7a6f"]={q="Vilken ställning har Skyborne i världen i dag?",a="Deras civilisation står inför en långsam kollaps. För århundraden sedan försvann vindandarna och Shal'nan, vilket destabiliserade de uråldriga pelare som håller Zephras Isle samman. När delar av deras rike faller i ruiner, kontakten med andra bebodda öar brutits och flyktingar strömmar till ön har de överlevande Skyborne splittrats. The High Order och Windshapers strider om huruvida det arkaniska arvet eller de elementära traditionerna kan rädda dem, medan desperata landsflyktiga vänder sig till banditliv eller ansluter sig till Al'Aketh-kulten, som dyrkar Al'Akir.",al={"skybornes nuvarande situation","skybornes läge","var skyborne finns nu"}}},fp="8,336,24.614.0,20.529.0,17.636.1,21.321.0,36.242.0,21.333.0,34.281.0,44.333.0,21.253.0"}
P.entries["topic:skywall"] = {n="Skywall",s="Skywall är luftandelementarernas vidsträckta, stormpinade domän i Elemental Plane. Titanerna förvisade dem hit i urminnes tider, och vindens, molnens och blixtarnas varelser lever under Al'Akir the Windlords styre.",h="Skywall är luftandelementarernas vidsträckta, stormpinade domän i Elemental Plane.",kw={"luftandelementar","al'akir","elemental plane","shen'dorei","skywall","stormwall","thunderaan","windlord","zephras isle"},ang={["class:Mage"]="Besvärjare och arkanister har genom historien försökt utnyttja Skywalls gränslösa krafter i atmosfären, men försök att suga åt sig Al'Akirs stormar slutar ofta i förödelse.",["class:Shaman"]="Skywall är ursprungskällan till de råa, våldsamma vindar och blixtar som schamaner vördar och åkallar när de kommunicerar med luftens andar."},sec={{t="Ett fängelse i himlen",b="När titanerna störtade Old Gods för evigheter sedan skapade de Elemental Plane som ett säkert, dimensionellt fängelse för att hålla Azeroths oregerliga elementandar inspärrade. Elementarherrarna stred våldsamt sinsemellan och skapade till slut egna domäner. Vindens och stormens rike blev känt som Skywall och styrdes av Al'Akir the Windlord. Även om det är avskilt från ytvärlden fortsätter dess stormar att virvla i evig ensamhet."},{t="Elementarkriget",b="Förvisningen gjorde inte slut på den urgamla fiendskapen mellan elementarhärskarna. Skywall har länge utkämpat gränsstrider mot grannriken som Firelands. En av de mest ökända sammandrabbningarna var Elemental Sundering, då prins Thunderaan the Windseeker överfölls och förråddes av Garr och Baron Geddon, Ragnaros the Firelords främsta löjtnanter. Ragnaros slukade prinsens essens och band fragmenten i en krossad talisman."},{t="Dimhöljda öar",b="Skywall består inte bara av rasande vindar och djinncitadell. Bland molnbankarna driver Zephras Isle, en fristad där Shen'dorei bor. Dödliga på Azeroth tränger sällan igenom slöjan till luftens domän, men vårdslösa besvärjare och vapensmeder har genom historien trotsat faran i försök att suga åt sig Windlords levande stormar."}},faq={{q="Vad är Skywall?",a="Skywall är luftandelementarernas domän i det dimensionella Elemental Plane. Titanerna skapade det för att fängsla Old Gods tjänare. Det är ett rike som helt består av ändlösa himlar, stormar, moln och blixtar.",al={"vad är skywall","skywalls historia","luftens domän"}},{q="Vem styr Skywall?",a="Skywall styrs av Al'Akir the Windlord, luftens främste Elemental Lord. Från sitt stormiga rike härskar han över djinn, cykloner och levande stormar.",al={"vem leder skywall","skywall-boss","luftens härskare"}},{q="Hur skapades Skywall?",a="Efter att ha besegrat Old Gods i Azeroths urtid skapade titanerna Elemental Plane för att försegla de kaotiska elementarerna. I detta dimensionella fängelse tog luftandelementarerna ett eget vidsträckt territorium i besittning. Det blev Skywall.",al={"skywalls ursprung","hur skapades skywall"}},{q="Vad hände med prins Thunderaan?",a="Under Elemental Sundering överfölls prins Thunderaan av Ragnaros the Firelords löjtnanter, Garr och Baron Geddon. Ragnaros förtärde luftprinsens essens och fängslade det som återstod i en krossad talisman för elementarbindning.",al={"thunderraans historia","vad hände med thunderaan","windseekers öde"}},{q="Vilka bor i Skywall?",a="I Skywall bor luftandelementarer, mäktiga djinnherrar, blixtrevenanter och elementära stormdrakar. Där finns också Zephras Isle, en fristad där Shen'dorei bor.",al={"skywalls invånare","skywalls befolkning","vem finns i skywall"}},{q="Kan dödliga nå Skywall?",a="Dödliga kan inte lätt nå Skywall, eftersom det ligger i ett separat dimensionellt fängelse. Historiskt har bara mäktiga magiker som manipulerat elementarsprickor, eller de som sökt upp de isolerade Shen'dorei på Zephras Isle, nått dess himlar.",al={"hur tar man sig till skywall","resa till skywall","portal till skywall"}}},fp="7,156,23.326.0,19.379.0,17.314.0,16.180.0,18.133.0,24.179.0,35.230.0,21.155.0,26.207.0"}
P.entries["topic:steamwheedle-cartel"] = {n="Steamwheedle Cartel",s="Steamwheedle Cartel är den största och mest inflytelserika goblinverksamheten i dagens Azeroth. Kartellen är stenhårt neutral och styr livliga handelsnav som Booty Bay, Ratchet och Gadgetzan. Där betjänar de både Alliansen och Horden, så länge betalningen är äkta. Deras vidsträckta verksamhet omfattar sjöfart mellan kontinenterna, alkemi, bärgning och hänsynslös legosoldatsuthyrning.",h="Steamwheedle Cartel är den största och mest inflytelserika goblinverksamheten i dagens Azeroth.",kw={"booty bay","slagskämpar","kartell","gadgetzan","gazlowe","gobliner","ratchet","revilgaz","steamwheedle","undermine"},ang={["class:Rogue"]="De laglösa utkanterna av Booty Bay och Ratchet erbjuder gott om arbete åt tjuvar, låstjuvar och hemliga uppdragstagare som vill lura pirater och rivaler.",["faction:Alliance"]="För resenärer från Alliansen erbjuder Steamwheedles färjelinjer och ökenutposter oumbärliga rastplatser och flygrutter genom avlägsen vildmark där Horden dominerar.",["faction:Horde"]="Gazlowe och hans besättning har sedan länge arbetsrelationer med orcherna i Durotar, men kartellen kräver fortfarande hårda kontanter för sina tjänster och sin neutralitet.",["profession:Engineering"]="Kartellnav som Ratchet och Gadgetzan är utmärkta mötesplatser för ritningar till goblinteknik, flistuggsdelar och experimentella mekaniska komponenter."},sec={{t="En lönsam neutralitet",b="Steamwheedle Cartel hade sitt ursprung i goblinernas underjordiska huvudstad Undermine. Till en början allierade sig kartellen med Old Horde under det andra kriget och levererade krigsmaskiner, sabotageexperter och marin ingenjörskonst. När stoftet lagt sig insåg kartellens ledare att det kostade mer än det smakade att välja sida. De omfamnade total neutralitet och spred sig över båda kontinenterna med handelsnätverk öppna för både Alliansen och Horden. I dag, när öppna motsättningar pyr, erbjuder Steamwheedles hamnar en viktig mötesplats där alla med guld kan köpa passage, sätta in resurser och anlita lokala specialister."},{t="Hamnar och utposter",b="Kartellens inflytande vilar på strategiska hamnar och gränsstäder. I Stranglethorn Vale styr Baron Revilgaz Booty Bay, en befäst hamnstad uthuggen i klipporna intill Blackwater Raiders. På andra sidan Stora havet leder chefsingenjören Gazlowe Ratchet vid The Barrens kust. Därifrån driver han en djupgående färjelinje direkt till Booty Bay. Djupt inne i Tanaris öknar ligger den snabbt växande staden Gadgetzan. Mindre verksamheter som Steamwheedle Port och avlägsna utposter i Desolace, Azshara och Stonetalon Mountains säkrar resurser i regionen."},{t="Rivaler och plundrare",b="Steamwheedles handel hotas ständigt av hänsynslösa lycksökare. I de södra haven hotar Bloodsail Buccaneers gång på gång Booty Bays sjöleder, medan Southsea Freebooters plundrar kusterna nära Ratchet. På land drabbar kartellen ofta samman med sina främsta företagsrivaler, Venture Company, i våldsam kamp om skogsavverkning, oljefält och flistuggsteknik i Stonetalon och The Barrens. För att upprätthålla ordningen och driva igenom handelsavtal anlitar kartellens baroner regelbundet förbipasserande legosoldater som får lösa tvister med hårda metoder."}},faq={{q="Vad är Steamwheedle Cartel?",a="Steamwheedle Cartel är ett enormt, neutralt handelskonglomerat av gobliner med bas i Undermine. De driver flera stora, självständiga städer i Azeroth, däribland Booty Bay, Ratchet och Gadgetzan. Där erbjuder de banktjänster, ingenjörskonst, transporter och auktionshus till alla fraktioner.",al={"vilka är steamwheedle","steamwheedles gobliner","vad är steamwheedle"}},{q="Tillhör Steamwheedles gobliner Horden eller Alliansen?",a="Ingendera. Kartellen håller fast vid strikt politisk neutralitet. De samarbetade tidigare med Old Horde under det andra kriget, men bröt sina formella band till fraktionerna för att maximera vinsten. I dag handlar de gärna med både Alliansen och Horden och håller fred i sina städer med beväpnade slagskämpar.",al={"är steamwheedle horden","är steamwheedle cartel neutrala","steamwheedle-fraktion"}},{q="Vilka större städer tillhör Steamwheedle Cartel?",a="Deras fyra främsta städer är Booty Bay i södra Stranglethorn Vale, Ratchet på östra stranden av The Barrens, Gadgetzan i Tanaris och Everlook i Winterspring. De har också mindre nav som Steamwheedle Port och avskilda handelsutposter.",al={"steamwheedles städer","kartellens städer","lista över goblinstäder"}},{q="Vem leder Steamwheedle Cartel?",a="Kartellen styrs från Undermine, men dess städer lyder under lokala chefer som Baron Revilgaz i Booty Bay och chefsingenjören Gazlowe i Ratchet.",al={"steamwheedles ledare","handelsfurste steamwheedle","vem styr steamwheedle"}},{q="Varför är Steamwheedles gobliner fiender med Venture Company?",a="Venture Company är ett konkurrerande goblinföretag känt för hänsynslös dagbrottsbrytning och skogsskövling. De två fraktionerna tävlar ständigt om samma territoriella rättigheter, industriella ritningar och naturresurser i Kalimdor och Eastern Kingdoms.",al={"venture company mot steamwheedle","varför hatar de venture company","rivalitet mellan venture company och steamwheedle"}},{q="Vad händer om man slåss i en hamn som tillhör Steamwheedle?",a="Steamwheedles städer har beväpnade goblinslagskämpar som håller ordning. Om du angriper andra resenärer kan vakterna ge sig på dig, och om du dödar kartellens vakter eller invånare försämras ditt anseende hos kartellen.",al={"vakter i booty bay","pvp i ratchet","slagskämpar i ratchet"}}},fx={ae8eebbb={q="Varifrån kommer Steamwheedle Cartel?",a="Steamwheedle Cartel har sitt ursprung i den underjordiska metropolen Undermine på Kezan och är det äldsta och största köpmannasyndikatet i goblinsamhället. De tog kontroll över Blackwater Cove i Stranglethorn Vale och förvandlade platsen till den livliga fristaden Booty Bay. Under det andra kriget sålde kartellen sina tjänster till Orgrim Doomhammer's Horde och tillhandahöll zeppelinare, alkemister och ingenjörer för vinst. När konflikten var över insåg kartellen att strikt neutralitet i Azeroth gav vida bättre handelsmöjligheter. Därför öppnade de neutrala hamnar och handelsstationer på båda kontinenterna.",al={"steamwheedles historia","steamwheedle cartels ursprung","bakgrund till steamwheedle"}},["02088509"]={q="Varför finns Steamwheedle Cartel på så många avlägsna platser?",a="Steamwheedle Cartel söker vinst där handelsvägar, sällsynta resurser eller regional oro uppstår. Genom att grunda bosättningar som Booty Bay i Stranglethorn Vale, Ratchet längs The Barrens kust och Gadgetzan i Tanaris får de kontroll över sjövägar och gränshandel mellan kontinenterna. Deras självständiga utposter och företag låter dem handla öppet med både Alliansen och Horden, samtidigt som de utvinner mineraler, förmedlar bärgning och finansierar lukrativa uppdrag oavsett farorna i området.",al={"varför steamwheedle finns överallt","varför gobliner finns i ratchet och booty bay","varför steamwheedle finns på olika platser"}}},fp="19,258,23.502.0,18.492.0,18.446.0,32.221.0,59.228.0,53.259.0,34.144.0,66.228.0,53.184.0"}
P.entries["topic:stonefield-family"] = {n="Stonefieldfamiljen",s="Stonefieldfamiljen är en släkt av mänskliga bönder som bor på The Stonefield Farm i västra Elwynn Forest. De är kända för sina sedan länge rotade lantliga traditioner och sköter sitt hemman samtidigt som de dras in i en pågående rivalitet med sina grannar, familjen Maclure. Trots fientligheten mellan de två hushållen finner sig yngre generationer indragna över familjegränsen.",h="Stonefieldfamiljen är en släkt av mänskliga bönder som bor på The Stonefield Farm i västra Elwynn Forest.",kw={"elwynn forest","gramma stonefield","maclure","mildred stonefield","stonefield","stonefieldfamiljen","the stonefield farm","tommy joe"},ang={["faction:Alliance"]="Alliansens äventyrare på väg mot Westfall sköter ofta Stonefieldfamiljens vardagssysslor och personliga gräl för att hålla Elwynns kornbod stabil.",["race:Human"]="För Stormwinds människor är familjen Stonefield ett exempel på den motståndskraftiga arbetarklass som förser riket med spannmål och andra grödor."},sec={{t="Livet på gården",b="Familjen Stonefield är typiska bönder från Elwynn och brukar jorden söder om vägen mot Westfall. Hemmanet kretsar kring Gramma Mildred Stonefield, Ma Stonefield och unge Tommy Joe Stonefield. Till vardags på gården sköter de grödorna och boskapen, samtidigt som de håller lokala skadedjur borta och hanterar koboldintrång i traktens gruvor och gränsområden."},{t="Fejden med Maclure",b="Stonefieldfamiljen och grannarna, familjen Maclure, skiljs bara åt av en smal remsa skog och betesmark, men hyser ett bittert och långvarigt agg mot varandra. De äldre generationerna i de båda familjerna hyser föga värme för varandra, och smågräl och revirhävdande färgar varje möte. Trots den hätska grannfejden har en hemlig romans spirat mellan unge Tommy Joe Stonefield och Maybell Maclure, vilket får sympatiserande resenärer att agera diskreta budbärare."}},faq={{q="Var bor Stonefieldfamiljen?",a="Stonefieldfamiljen bor på The Stonefield Farm i sydvästra Elwynn Forest, strax söder om huvudvägen mot gränsen till Westfall.",al={"var ligger the stonefield farm","var bor stonefieldfamiljen","stenfältsfamiljens plats"}},{q="Vilka kända medlemmar har Stonefieldfamiljen?",a="Bland de framträdande medlemmarna i hushållet finns matriarken Gramma Mildred Stonefield, Ma Stonefield och unge Tommy Joe Stonefield.",al={"vilka ingår i stonefieldfamiljen","medlemmar i stonefieldfamiljen","stonefieldfamiljens släktträd"}},{q="Varför hatar Stonefieldfamiljen familjen Maclure?",a="Stonefieldfamiljen och familjen Maclure är indragna i en klassisk lantlig släktfejd, driven av gammalt agg om mark och grannarnas envishet. Båda hushållen vägrar envist att försonas.",al={"fejden mellan stonefield och maclure","varför bråkar stonefield och maclure","rivaliteten med maclure"}},{q="Hur påverkar fejden Tommy Joe Stonefield?",a="Tommy Joe Stonefield är i hemlighet förälskad i Maybell Maclure från gården som tillhör den rivaliserande familjen. På grund av den öppna fientligheten mellan deras släkter måste de förlita sig på diskreta mellanhänder för att utbyta brev och kärleksgåvor.",al={"tommy joe och maclure","tommy joes romans","vem är tommy joe förälskad i"}},{q="Är familjen allierad med Stormwind?",a="Ja. Som mänskliga invånare i Elwynn Forest står de under beskydd av kungariket Stormwind och Alliansen, även om de främst bekymrar sig om gårdens dagliga överlevnad och hoten i trakten.",al={"är stonefieldfamiljen med i alliansen","stonefieldfamiljens lojalitet"}},{q="Vilka hot står Stonefieldfamiljen inför?",a="Förutom slitningarna med familjen Maclure måste Stonefieldfamiljen hantera kobolder som tränger sig på, kringströvande vilda djur och att Stormwinds vakter sällan patrullerar landsbygdens gårdar.",al={"faror för stonefieldfamiljen","problem på the stonefield farm"}}},fx={e2a78cbe={q="Vilka är Stonefield-familjen?",a="Stonefield-familjen är en etablerad familj av människor som brukar jord i Elwynn Forest. Från The Stonefield Farm sydväst om Goldshire arbetar de med marken och hanterar hoten från vildmarken omkring dem, samtidigt som en långvarig och bitter fejd med grannarna Maclure pågår.",al={"stonefield-familjens historia","vilka stonefield är","stonefield-familjen"}}},fp="17,158,21.282.0,16.359.1,38.126.0,51.123.0,41.92.0,46.177.0,37.181.0,45.128.0"}
P.entries["topic:stonemasons-guild"] = {n="Stonemasons Guild",s="Stonemasons Guild var ett förbund av mästerbyggare och hantverkare som ansvarade för återuppbyggnaden av Stormwind City efter det andra kriget. Efter en bitter tvist om betalning med House of Nobles, som slutade i dödliga upplopp, upplöstes förbundet med tvång. Dess rättslösa medlemmar drevs i exil, och de utspridda hantverkarnas verkliga öde förblev ett mysterium.",h="Stonemasons Guild var ett förbund av mästerbyggare och hantverkare som ansvarade för återuppbyggnaden av...",kw={"alexston","defias","nethergarde","adelsmän","stenhuggare","stormwind","thredd","vancleef"},ang={["class:Rogue"]="Att mästerhantverkare förvandlades till dödliga stråtrövare, låstjuvar och lönnmördare visar hur långt VanCleefs taktiska list nådde.",["faction:Alliance"]="Förbundets sammanbrott lämnade Westfalls kornbod försvarslös och överväldigad av laglösa, vilket ansträngde Alliansens försörjningslinjer alldeles utanför huvudstaden.",["race:Dwarf"]="Dvärgiska stenhuggare hyste stor respekt för Stonemasons Guild och noterade att deras precision och höga försvarsmurar kunde mäta sig med Ironforges egen Royal Stonecutters Union.",["race:Human"]="Stormwinds vackra vita sten står som ett bittert vittnesbörd om kungarikets största inre tragedi och påminner mänskliga resenärer om priset för aristokratisk hybris."},sec={{t="Rikets byggmästare",b="Under ledning av den valda förbundsmästaren Edwin VanCleef visade hantverkarna i Stonemasons Guild upp en skicklighet i stenhuggeri som kunde mäta sig med dvärgarnas Royal Stonecutters Union. Efter förödelsen under det första och andra kriget anlitade House of Nobles förbundet för det väldiga arbetet med att återuppbygga Stormwind City från ruinerna, med förtroende för att de skulle återställa huvudstadens forna prakt."},{t="Slit och svek",b="I åratal arbetade VanCleef och en armé av hantverkare hårt genom Elwynn och reste Stormwind Keeps skyhöga spiror och Cathedral of Lights massiva valv. Men kungakassan tömdes av tunga militärskulder från fälttåg i söder. Påverkade av aristokratisk politik vägrade House of Nobles att betala förbundets avtalade löner och arvoden. När VanCleef begärde ersättning svarade adelsmännen med att ensidigt upplösa förbundet, vilket väckte stor vrede bland arbetarna som hade blött för att återuppbygga staden."},{t="Blod på gatorna",b="Lönetvisten utlöste våldsamma oroligheter i hela Stormwind. Kronan slog skoningslöst till och grep nyckelpersoner bland de sammansvurna, som VanCleefs löjtnant Bazil Thredd, medan VanCleef och hundratals ruinerade stenhuggare flydde ut på landsbygden i Westfall. De landsförvisade hantverkarna, som stämplats som förrädare, omvandlade sin fackförening till det militanta Defias Brotherhood."},{t="Den dolda handen",b="Dödläget mellan adeln och byggarna handlade inte bara om tomma kassakistor. Bakom kulisserna underblåste hovrådgivaren Lady Katrana Prestor aktivt osämjan. Hon övertygade aristokratin om att räkningarna från Stonemasons var orimligt höga och deras arbete undermåligt, samtidigt som hon hetsade hantverkarna till öppet uppror. Genom att lamslå Stormwind med inre stridigheter och stoppa förnödenheter till Westfall lyckades den svarta draken Onyxia splittra kungariket inifrån."}},faq={{q="Vad var Stonemasons Guild?",a="Stonemasons Guild var en sammanslutning av mänskliga hantverkare, arkitekter och stenhuggare under ledning av förbundsmästaren Edwin VanCleef. De var kända för att ha återuppbyggt Stormwind City efter det andra kriget.",al={"vilka var stenhuggarna","stonemasons guilds historia","vad gjorde stenhuggarna"}},{q="Varför blev Stonemasons Guild Defias Brotherhood?",a="När återuppbyggnaden av Stormwind var färdig vägrade House of Nobles att betala förbundets löner på grund av förlamande skulder och intriger vid hovet. Protesterna övergick i dödliga upplopp, och de landsförvisade arbetarna organiserade Defias Brotherhood för att med våld återta sin stulna rikedom.",al={"varför blev defias arga","varför blev stenhuggarna onda","defias brotherhoods ursprung"}},{q="Vem ledde Stonemasons Guild?",a="Edwin VanCleef var förbundets valda förbundsmästare. Under hans ledning blev förbundet berömt för sitt otroliga stenhuggeri, innan han landsförvisades och grundade Defias Brotherhood.",al={"stonemasons guilds förbundsmästare","vancleefs förbund","vem ledde stenhuggarna"}},{q="Vilka byggnadsverk uppförde Stonemasons?",a="Förbundet återuppbyggde hela Stormwind City efter det första kriget, däribland Cathedral of Light och Stormwind Keep.",al={"vad byggde stenhuggarna","byggde stenhuggarna stormwind"}},{q="Gick alla stenhuggare med i Defias Brotherhood?",a="Alla gick inte med i upproret. Mästerhantverkaren Baros Alexston bröt banden med Edwin VanCleef och stannade i Stormwind för att ta posten som stadsarkitekt, vilket väckte hans tidigare förbundskamraters bestående hat.",al={"blev alla stenhuggare banditer","baros alexston stenhuggare","stannade några stenhuggare i stormwind"}},{q="Vad hände under stenhuggarnas upplopp?",a="När adelsmännen upplöste förbundet i stället för att betala det gjorde stenhuggarna uppror på Stormwinds gator. Kronan slog till och grep VanCleefs löjtnant Bazil Thredd, medan VanCleef och de andra stenhuggarna flydde till Westfall.",al={"stenhuggarnas upplopp","vad hände under upploppen","stenhuggarna gör uppror i stormwind"}},{q="Vem var Bazil Thredd i Stonemasons Guild?",a="Bazil Thredd var Edwin VanCleefs betrodda assistent och främste löjtnant under deras tid i förbundet. Till skillnad från VanCleef greps Thredd efter upploppen och sitter fortfarande inlåst i Stormwind Stockade.",al={"bazil thredds bakgrund","thredd stenhuggare","vancleefs löjtnant"}}},fx={["1a605800"]={q="Vad är Stonemasons Guilds historia?",a="Efter det andra kriget fick Stonemasons Guild i uppdrag av House of Nobles att återuppbygga Stormwind City från ruinerna som Orcish Horde lämnat efter sig. Skrået bestod av skickliga ingenjörer och hantverkare, som under flera år återställde kungarikets storhet och formade landmärken som Cathedral of Light och Stormwind Keep. Men växande kungliga skulder och politiska intriger fick adeln att vägra betala. Det ledde till upplopp och att skrået förvisades till Westfall.",al={"stonemasons historia","stonemasons bakgrund","stonemasons ursprung"}},f8ddb796={q="Varför kallas de Stonemasons?",a="De fick sitt namn efter sitt yrke som professionella stenhuggare, byggmästare och arkitekter. Skrået fungerade som ett stadgat hantverkarsamfund, likt Ironforge's Royal Stonecutters Union, och samlade murare och hantverkare vars mästerliga stenarbeten kunde bygga väldiga stenfästningar, katedraler och stadsmurar.",al={"varför de kallas stonemasons","vad stonemasons guilds namn betyder"}}},fp="17,236,23.295.0,17.475.0,20.365.1,15.401.2,31.205.0,60.248.1,44.174.1,50.106.0,52.193.1,42.209.0,46.179.0"}
P.entries["topic:stormwind-army"] = {n="Stormwinds armé",s="Stormwinds armé är den stående militärstyrka som har i uppdrag att försvara kungariket Stormwind och bevara Grand Alliances säkerhet i söder. Armén är berömd för sina uthålliga riddare och marskalkar, men är nu svårt försvagad av kungens frånvaro, politiska stridigheter och akut brist på soldater i provinserna.",h="Stormwinds armé är den stående militärstyrka som har i uppdrag att försvara kungariket Stormwind och bevara...",kw={"anduin lothar","bolvar fordragon","defias","vice","garnison","stormwinds riddare","marskalkar","stormwinds armé","stormwind guard"},ang={["class:Paladin"]="Arméns tunga kavalleri och ledning samarbetar nära med Order of the Silver Hand och Highlord Bolvar Fordragon för att skipa Light's Justice i laglösa trakter.",["class:Warrior"]="För mänskliga krigare står Stormwinds riddare och Lothars infanteri som idealet för disciplinerad militärtjänst, även om många kämpar med att adeln har övergett gränslandet.",["faction:Alliance"]="Sedan Lordaeron krossades av Scourge är Stormwinds armé den livsviktiga defensiva ryggraden i Grand Alliance i Eastern Kingdoms.",["race:Human"]="För Stormwinds invånare är den kungliga armén både en bestående symbol för överlevnad mot omöjliga odds och en frustrerande påminnelse om byråkratisk försummelse i avlägsna småbyar."},sec={{t="Ett arv av järn och blod",b="Arméns militära tradition sträcker sig över århundraden av hårda strider, från tidiga sammandrabbningar vid gränsen mot gnoller till det desperata försvaret mot Gurubashitroll. Under första kriget ledde kung Llane Wrynn I och sir Anduin Lothar Stormwinds riddare i legendariska bakhåll mot orchernas Horde, men armén föll när huvudstaden brann. De överlevande flydde till Lordaeron, där de blev drivande i bildandet av Alliance of Lordaeron och stred genom andra kriget. Efter att The Dark Portal föll byggdes Stormwinds militär upp på nytt tillsammans med det återupprättade kungariket."},{t="Organisation och grader",b="Militären har sitt högkvarter i Stormwind Keep och förlitar sig på regionala garnisoner under Stormwind Marshals ledning. Innanför huvudstadens stenmurar upprätthåller Stormwind City Guard den civila ordningen, medan elitstyrkan Royal Guard skyddar pojkkungen Anduin Wrynn och Highlord Bolvar Fordragon. Utanför portarna skickar armén ut förposter för att patrullera Elwynn Forest, hålla ordning längs handelsvägarna och bemanna försvarsvärn ända bort till Redridge Mountains, med stöd till sjöss från Stormwind Fleet."},{t="En tunn försvarslinje",b="Trots sina stolta traditioner är den moderna armén nära bristningsgränsen. Skulder som House of Nobles drog på sig för att utöka den militära närvaron i Stranglethorn ledde till den bittra brytningen med Stonemasons Guild, som kulminerade i upplopp och bildandet av Defias Brotherhood. Sedan kung Varian försvann har House of Nobles regelbundet hållit inne soldater, pengar och förnödenheter från avlägsna bosättningar som Westfall, Lakeshire och Duskwood. Därför tvingas lokala marskalkar ge kringvandrande äventyrare tillfälliga uppdrag för att bära rikets bördor."}},faq={{q="Varför skickas inte fler soldater till Lakeshire och Sentinel Hill?",a="Stormwinds styrkor är utspridda, och begäran om förstärkningar till provinserna har inte hörsammats. Westfall förlitar sig på People's Militia, medan soldater i Lakeshire överlevde förlusten av Stonewatch Keep. Med för få försvarare och krympande förråd vänder sig officerarna till resande äventyrare för att få hjälp.",al={"var finns stormwinds armé","varför finns inga soldater i westfall","varför hjälper inte stormwind"}},{q="Vad är skillnaden mellan Stormwinds armé och Stormwind Guard?",a="Stormwinds armé omfattar hela rikets militär, däribland marskalkar vid gränsen, garnisoner och riddare på fälttåg. Stormwind Guard är den särskilda gren som upprätthåller lagen, patrullerar gatorna och försvarar portarna i Stormwind City och de omgivande landsbygdsområdena.",al={"vakt eller armé","vilka är stormwinds vakter","stormwinds militära grenar"}},{q="Vem leder Stormwinds armé just nu?",a="Med kung Varian Wrynn försvunnen vilar den militära makten officiellt hos pojkkungen Anduin Wrynn, som får direkt vägledning av regenten Highlord Bolvar Fordragon. Deras strategiska beslut ifrågasätts dock ständigt och motarbetas av politiska intriger i House of Nobles.",al={"vem leder stormwinds armé","stormwinds arméchef","stormwinds högste befälhavare"}},{q="Varför ger marskalkar äventyrare vicebrickor?",a="Stormwinds armé har kritisk personalbrist och nekas förstärkningar från huvudstaden. Därför ger regionala marskalkar som McBride i Northshire och Dughan i Goldshire kompetenta utomstående tillfällig ställning som vice, så att de lagligt kan röja undan laglösa och försvara gränserna.",al={"ställning som vice","varför får spelare viceuppdrag","stormwinds vice"}},{q="Vad hände med armén under första kriget?",a="Under sir Anduin Lothars ledning höll armén orchernas Horde stången med disciplinerade kavallerianfall, men övermannades när kung Llane mördades. Lothar samlade de överlevande soldaterna och civila och flydde över Great Sea till Lordaeron, där veteranerna blev kärnan i Alliance-styrkorna.",al={"stormwinds armé under första kriget","förlorade stormwinds armé","lothar och stormwinds armé"}},{q="Var har armén aktiva garnisoner just nu?",a="Armén har formella garnisoner runtom i Elwynn Forest, bland annat i Northshire, Goldshire och Westbrook Garrison. Westfall och Duskwood förlitar sig på lokala miliser, medan soldater fortfarande finns i Lakeshire efter förlusten av Stonewatch Keep och väntar på förstärkningar.",al={"stormwinds garnisoner","var är armén stationerad","stormwinds soldaters platser"}}},fx={bbf0b2a6={q="Vad är Stormwind Army?",a="Stormwind Army är den främsta militära styrkan i människornas kungarike Stormwind och en av Grand Alliances grundpelare. Armén har sitt högkvarter i Stormwind City och består av fotsoldater, tungt bepansrade riddare och officerare som kallas marskalkar. Utöver att försvara rikets kärnområden i södra Azeroth leder dess befälhavare garnisoner i provinserna och ger lokala miliser och äventyrande ombud i uppdrag att upprätthålla ordningen.",al={"vad stormwind army är","vilka stormwind army är","stormwinds militär"}},b7687992={q="Vilka är Stormwind Army allierade med?",a="Armén tjänar Stormwinds krona och upprätthåller House of Wrynns och det styrande rådets auktoritet. Utanför kungarikets gränser är den formellt knuten till Grand Alliance och försvarar tillsammans med Ironforge, Gnomeregan's gnomes och Kalimdor's night elves. På hemmaplan samarbetar den med Stormwind Fleet och huvudstadens stadsvakt.",al={"stormwind armys allierade","vem armén tjänar","vem de arbetar för"}}},fp="14,233,26.445.0,19.425.0,16.495.1,59.297.0,74.238.0,42.211.0,54.242.0,47.309.0,56.250.0"}
P.entries["topic:stormwind-guard"] = {n="Stormwinds garde",s="Stormwinds garde består av regionala garnisoner och vakter som har i uppgift att upprätthålla rikets lagar och försvara dess omgivande territorier. Den är farligt hårt pressad av politiskt dödläge och avlägsna fälttåg, och dess utspridda marskalkar kämpar för att hålla gnoller, orcher och banditer stången i Elwynn och Redridge.",h="Stormwinds garde består av regionala garnisoner och vakter som har i uppgift att upprätthålla rikets lagar...",kw={"garnison","goldshire","lakeshire","marshal dughan","marshal marris","marshal mcbride","stonewatch","stormwinds garde","westbrook garrison"},ang={["class:Warrior"]="Från rekryter i Northshire till härdade veteraner på Westbrook Garrison får mänskliga krigare sin första erfarenhet genom att marschera sida vid sida med regionala marskalkar mot gnoller och banditer.",["faction:Alliance"]="Stormwind Guard utgör rikets främsta försvarslinje, men övergivandet av allierade bosättningar blottar de djupa politiska sprickor som hotar hjärtat av Alliansen.",["profession:Blacksmithing"]="En garnisons styrka beror på dess rustning. På platser som Lakeshire tömmer lokala smeder hela järnförråd bara för att hålla garnisonens klingor och sköldar i brukbart skick.",["race:Human"]="För människorna på de södra jordbruksmarkerna var gardets blå tabarder en gång en garanti för trygghet. Därför kändes dess plötsliga frånvaro i Westfall och Duskwood som ett bittert svek."},sec={{t="Kronans sköld",b="Stormwinds garde är en viktig del av Stormwind-armén och patrullerar landsvägarna, vägskälen och stenvakttornen som håller ihop riket. I avlägsna bosättningar sköts styret och försvaret av utsedda marskalkar, som Marshal McBride i Northshire Valley, Marshal Dughan i Goldshire och Marshal Marris i Lakeshire. De här officerarna samlar rekryter och upprätthåller ordningen, och förlitar sig på pålitliga bruna hästar med god uthållighet för att ta sig mellan befästa utposter som Westbrook Garrison."},{t="En hårt pressad gräns",b="Efter det tredje kriget höll garden Elwynn Forest tryggt och lugnt, men de senaste åren har krisen tilltagit. Kung Varian Wrynn har försvunnit och rikets stående armé är bunden utomlands, så de regionala garnisonerna har fått lite hjälp. På Westbrook Garrison kan Deputy Rainer knappt hålla den västra gränsen mot Riverpaw-gnoller och Defias-tjuvar, vilket tvingar lokala befälhavare att lägga ut viktiga säkerhetsuppdrag och belöningar på äventyrare på genomresa."},{t="De övergivna territorierna",b="Gardens verkliga kris bottnar i beslut som fattats vid hovet i huvudstaden. Under Lady Katrana Prestors inflytande ansåg riket att det kostade för mycket att hålla en garnison i Westfall, drog tillbaka alla trupper och lät Edwin VanCleefs Defias Brotherhood ta över regionen. Duskwood gick samma öde till mötes. Soldaterna kallades tillbaka, till Darkshires förtvivlan, och de övergivna invånarna tvingades bilda den illa utrustade Night Watch för att försvara sig."},{t="Belägringen i öster",b="Medan Duskwood och Westfall övergavs behöll kronan en bräcklig militär närvaro i Redridge Mountains. Trots det är gardens läge desperat. Soldaterna övermannades av Shadowhide-gnoller och Blackrock-orcher som kom ner från Burning Steppes och tvingades lämna Stonewatch Keep. I Lakeshire går smeden Verner Osgood åt järn bara för att hålla vakterna utrustade, medan utmattade vaktposter spanar utmed vägen och väntar på en andra bataljon som aldrig kommer."}},faq={{q="Vad är skillnaden mellan Stormwind Guard och stadsvakten?",a="Medan Stormwind City Guard upprätthåller ordningen i huvudstaden innanför dess befästa murar ansvarar Stormwind Guard, ofta organiserad som regionala garnisoner, för att försvara kronans yttre territorier, patrullera vägarna och hålla vakt i tornen runt Elwynn Forest och Redridge.",al={"stormwind guard jämfört med stadsvakten","är det samma vakter","stadsvakten"}},{q="Varför finns det inga vakter från Stormwind i Westfall?",a="På Lady Katrana Prestors inrådan om rikets utgifter beslutade hovet att underhållet blev för kostsamt och drog tillbaka alla officiella garnisoner. Den totala avsaknaden av militärt skydd gjorde att Edwin VanCleefs Defias Brotherhood snabbt kunde ta över områdets gårdar och vägar.",al={"varför lämnade vakterna westfall","westfalls armé","var finns westfalls vakter"}},{q="Varför lämnade garden Duskwood?",a="Precis som i Westfall kallades garnisonerna i Duskwood tillbaka mot huvudstaden när resurserna sinade. Utan kronans officiella skydd, medan mörk magi och fasor blev allt vanligare, tvingades de kvarvarande stadsborna i Darkshire att bilda en egen milis, Night Watch, för att överleva.",al={"duskwoods vakter","varför övergav stormwind darkshire","darkshires garnison"}},{q="Vem leder de lokala garnisonerna?",a="Det lokala försvaret leds av utsedda regionala marskalkar. Marshal McBride ansvarar för Northshire Valley, Marshal Dughan för styrkorna i och kring Goldshire, och Marshal Marris leder det desperata försvaret av Lakeshire i Redridge Mountains.",al={"vem har befälet","gardets ledare","marskalkar"}},{q="Varför är vakterna i Lakeshire i så dåligt skick?",a="Garnisonen i Redridge drevs bort från Stonewatch Keep av invaderande Blackrock-orcher och lokala gnoller. De är instängda i Lakeshire och lider av akut brist på utrustning. Smeden Verner Osgood förbrukar nästan allt tillgängligt järn bara för att rusta upp vaktposterna, och de väntar på förstärkningar som rikets ledare har fördröjt.",al={"redridges vakter förlorar","vad hände vid stonewatch","problem med lakeshires garnison"}},{q="Vem är Marshal Haggard?",a="Marshal Haggard är en vördnadsvärd pensionerad befälhavare som en gång ledde Stormwind Guard under lugnare tider, då lediga soldater fortfarande kunde resa söderut och dricka tillsammans på Scarlet Raven Tavern i Darkshire.",al={"marshal haggards historia","pensionerad marskalk","gammal marskalk i garden"}}},fx={["8131ff5c"]={q="Vad är Stormwind Guard?",a="Stormwind Guard, ofta kallad Stormwind Garrisons, är Stormwind Armys territoriella militära gren. Till skillnad från Stormwind City Guard, som skyddar huvudstadens gator, patrullerar dessa vakter kungarikets ytterområden. De bemannar vakttorn, håller vägar säkra och upprätthåller kunglig lag i Elwynn Forest och Redridge Mountains.",al={"vilka stormwind guards är","stormwind-garnisonen","vad stormwind guards är"}},fe3d1e2d={q="Varför är Stormwind Guard stationerad där den är?",a="De är stationerade vid utposter och spaningstorn med några kilometers mellanrum längs huvudvägarna för att skydda bosättningar och resande mot hot som gnoller, kobolder och banditer. En gång upprätthöll de ordningen i Westfall och Duskwood, men hovpolitik och resursbrist tvingade dem att dra sig tillbaka. Nu finns aktiva garnisoner främst i Elwynn Forest och Redridge.",al={"var stormwind guards finns","vaktstyrkornas platser","varför det finns vakttorn"}},b4df286f={q="Vem slåss Stormwind Guard för?",a="De tjänar kungariket Stormwind och Alliansen under kronans och Highlord Bolvar Fordragons myndighet. Lokalt lyder de under utsedda marskalkar och samarbetar nära med stadens magistrater, lokala miliser och äventyrare från Alliansen som är villiga att förstärka deras hårt pressade utposter.",al={"stormwind guards lojaliteter","vem vakterna tjänar","stormwind armys fraktion"}},["7b82470a"]={q="Vad är Stormwind Guards historia?",a="Efter det tredje kriget upprätthöll gardet stabiliteten i stora områden och höll vakttornen bemannade för att skydda Elwynn, Duskwood och Westfall. Men politiska intriger och manövrer vid det kungliga hovet, ledda av Lady Katrana Prestor, ledde till att trupper och finansiering drogs in från avlägsna områden. Med stora delar av armén utomlands eller tillbakahållen kämpar de kvarvarande garnisonerna nu för att hålla grundläggande gränsposter som Westbrook och Lakeshire.",al={"stormwind guards historia","vaktstyrkans ursprung","stormwind-garnisonens historia"}},["8669b7db"]={q="Varför kallas de Stormwind Guard?",a="De bär namnet efter kungariket Stormwind och företräder kunglig auktoritet och militär lag utanför huvudstadens murar. De kallas också Stormwind Garrisons eftersom styrkorna är uppdelade i regionala utposter i befästa torn och städer runtom i riket.",al={"varför stormwind guard","vad stormwind guards namn betyder","varför garnisonen kallas så"}}},fp="15,214,19.365.0,23.450.0,25.381.1,21.432.0,70.221.0,50.264.0,33.172.0,30.233.0,50.303.0,23.195.0"}
P.entries["topic:stormwind-kingdom"] = {n="Stormwind (kungarike)",s="Kungariket Stormwind är Azeroths sydligaste och för närvarande främsta mänskliga rike. Det härskar över Elwynn Forest, Westfall, Duskwood och Redridge Mountains. Under det första kriget plundrades riket och lades i ruiner. Efter det andra kriget byggdes det upp igen med blod och hårt arbete. Efter Lordaerons tragiska fall i norr blev det Alliansens militära och kulturella centrum. I dag är riket ansatt både inifrån och utifrån. Den tioårige kung Anduin Wrynn styr under Highlord Bolvar Fordragons vakande ledning, medan den krönte monarken fortfarande är försvunnen.",h="Kungariket Stormwind är Azeroths sydligaste och för närvarande främsta mänskliga rike.",kw={"anduin","azeroth","bolvar","elwynn","första kriget","adelsrådet","prestor","stenhuggare","stormwind","varian","wrynn"},ang={["class:Paladin"]="Riket vördar den heliga traditionen från Church of the Holy Light och arvet efter Silver Hand. I Cathedral of Light finns helgade ordnar.",["class:Rogue"]="Stormwinds bittra inre konflikter och skuggan från Defias-upproret har fyllt bakgator, kloaker och landsbygd med ficktjuvar som tar tillfället i akt och politiska spioner.",["faction:Alliance"]="Som den moderna Alliansens främsta militära och ekonomiska stöd ger Stormwind skydd, ledarskap och resurser åt sina dvärgiska, gnomiska och nattalviska allierade.",["race:Human"]="Stormwind är mänsklighetens bultande hjärta och sista suveräna fäste efter att Lordaeron, Alterac och Dalaran i norr gått under."},sec={{t="Ett trotsigt arv",b="Stormwind grundades för över tusen år sedan av ättlingar till det forntida Arathi-imperiet, som färdades söderut bortom Khaz Modans klippor till bördiga, skogsklädda dalar. Långt från de nordliga rikena utvecklades landet till en kultur som är djupt stolt över sin självständighet och Ljuset."},{t="Aska och återuppbyggnad",b="Självständigheten var nära att utplånas när orchernas hord strömmade genom The Dark Portal. Stormwind City brändes till aska under det första kriget och kung Llane dödades. Sir Anduin Lothar ledde de överlevande norrut över Stora havet. Där samlade de de nordliga rikena i Lordaerons allians. När orchhotet krossades i det andra kriget återvände flyktingarna hem. De anlitade Stonemasons Guild för att återuppbygga sin magnifika huvudstad av vit sten och blå baner. När gisslet utplånade Lordaeron under det tredje kriget blev Stormwind mänsklighetens främsta återstående fäste."},{t="Ett splittrat rike",b="Under sina höga torn kämpar Stormwind med att styra sina vidsträckta sydliga besittningar. Elwynn Forest är fortfarande relativt tryggt, men grannområden som Westfall vimlar av laglösa. Redridge utsätts för ständiga intrång från orcher och gnoller, och de mörka skogarna i Duskwood har fallit utanför rikets kontroll. En bitter tvist mellan adelsrådet och Stonemasons utlöste våldsamma upplopp i huvudstaden. Fördrivna arbetare gick då i öppet uppror i provinserna."},{t="Den tomma tronen",b="Rikets instabilitet förvärrades när kung Varian Wrynn plötsligt och obemärkt försvann under en seglats till ett diplomatiskt möte med Horden i Theramore. För att bevara den bräckliga ordningen bland folket sattes kronan på hans tioårige son Anduin Wrynn, och Highlord Bolvar Fordragon utsågs till lordregent. Den kungliga makten är dock splittrad och förlamad. Adelsrådet, som står under Lady Katrana Prestors nära inflytande, lägger gång på gång in sitt veto mot militära insatser. Lokala städer tvingas försvara sig själva medan farliga hemligheter gror inom Stormwind Keep."}},faq={{q="Vem styr Stormwind just nu?",a="Formellt tillhör kronan kung Anduin Wrynn, som besteg tronen som tioårigt barn. Eftersom han är minderårig utövas den faktiska regeringsmakten av Highlord Bolvar Fordragon i egenskap av lordregent. Lady Katrana Prestor och adelsrådet står för omfattande lagstiftningsråd och tillsyn.",al={"vem är kung i stormwind","nuvarande härskare","vem styr stormwind","stormwinds kung"}},{q="Vad hände med kung Varian Wrynn?",a="Kung Varian lämnade Stormwind på en hemlig diplomatisk resa till Theramore för att förhandla om fredliga relationer med Horden. Han försvann under mystiska omständigheter på vägen. Hans öde hålls som en välbevarad statshemlighet för att hindra rikets befolkning och yttre rivaler från att störta allt i kaos.",al={"var är varian","varian försvunnen","vad hände med kungen","varians bakgrund"}},{q="Varför förstördes Stormwind förr?",a="Stormwind var den första mänskliga nation som orchernas hord stötte på när den invaderade genom The Dark Portal under det första kriget. Trots ett envist försvar lett av kung Llane och Sir Anduin Lothar intogs, plundrades och jämnades staden med marken. Den överlevande befolkningen tvingades evakuera norrut över havet till Lordaeron.",al={"stormwind under första kriget","stormwinds fall","när brann stormwind","stormwind förstört"}},{q="Varför saknar Westfall, Redridge och Duskwood kungliga soldater?",a="Den kungliga militären är hårt ansträngd och lamslagen av hovets maktspel. Lady Katrana Prestor och adelsrådet blockerar ofta begäran om att skicka garnisoner utanför Elwynn Forest. De hävdar att huvudstadens medel och försvarsstyrkor inte får slösas på att patrullera avlägsna länder. Därför tvingas miliser som Folkets milis och Nattväktarna kämpa ensamma.",al={"varför inga soldater","varför får de ingen militär hjälp","övergivna städer","oskyddade städer i utkanterna"}},{q="Vilket territorium gör kungariket Stormwind anspråk på?",a="Historiskt sett härskar Stormwind över Azeroths södra kontinent, där Elwynn Forest, Redridge Mountains, Westfall och Duskwood ingår. Riket har också tidigare haft utposter vid gränsen som sträckte sig söderut in i norra Stranglethorn Vale.",al={"stormwinds gränser","stormwinds landområden","vilka länder tillhör stormwind"}},{q="Varför vände sig stenhuggarna mot Stormwind?",a="Efter att ha byggt om Stormwind City till ett mästerverk av vit sten lade Stonemasons Guild fram sin räkning. Påverkade av adelsrådets politik vägrade adelsrådet att betala hela summan, och stenhuggarna vägrade att kompromissa. De upplopp som följde drev gillet ut ur staden, där det blev de laglösa Defias Brotherhood.",al={"varför är defias arga","stenhuggarnas upplopp","defias bakgrund","varför gjorde byggarna uppror"}}},fx={["4ff36454"]={q="Vad är kungariket Stormwind?",a="Kungariket Stormwind, även kallat kungariket Azeroth, är det sydligaste av människornas sju kungariken och Grand Alliances hjärta. Det befolkades av ättlingar till det forntida Arathor-imperiet och omfattar bördiga områden som sträcker sig över Elwynn Forest, Westfall, Redridge Mountains och Duskwood. Efter att Scourge nyligen krossade Lordaeron i norr står Stormwind nu som den starkaste kvarvarande bastionen för mänsklig makt och civilisation i världen.",al={"vad stormwind är","vem stormwind är","kungariket stormwind"}},["4fc8efc2"]={q="Vilka är kungariket Stormwind allierade med?",a="Stormwind är en grundpelare i Grand Alliance och har nära band till dvärgarna i Ironforge och gnomerna i Gnomeregan i Khaz Modan, liksom till nattalverna på andra sidan havet i Kalimdor. Dess folk har också starka andliga och historiska band till Church of the Holy Light. Stormwind var en gång isolerat från de mänskliga rikena i norr, men leder nu de enade fraktioner som kämpar för att försvara civilisationen i Azeroth.",al={"stormwinds allierade","vilka stormwind är allierade med","stormwinds allians"}},bf266b42={q="Vad är Stormwinds historia?",a="Stormwind grundades för ungefär tolvhundra år sedan av arathi-migranter som färdades söderut förbi Khaz Modan och växte till ett självständigt jordbrukskungarike. Orcish Horde plundrade det fullständigt under det första kriget. Under Lord Anduin Lothars ledning flydde de överlevande norrut till Lordaeron. Efter det andra kriget återvände de för att återuppbygga sin strålande huvudstad. Sedan Lordaeron nyligen föll för Scourge har Stormwind blivit mänsklighetens främsta fäste.",al={"stormwinds historia","var stormwind kommer ifrån"}}},fp="19,416,20.285.0,21.581.0,17.422.1,17.481.2,34.208.0,35.270.0,40.266.0,64.357.0,51.194.0,47.285.1"}
P.entries["topic:syndicate"] = {n="Syndicate",s="Syndicate är en utbredd kriminell människorganisation, grundad och ledd av adelsmän som förlorade sin ställning när kungariket Alterac föll. Från befästa fästen i Alterac Mountains, Hillsbrad Foothills och ruinerna av Stromgarde Keep för de ett kompromisslöst krig mot både Alliansen och Horden för att återupprätta sin förlorade aristokrati.",h="Syndicate är en utbredd kriminell människorganisation, grundad och ledd av adelsmän som förlorade sin...",kw={"aliden perenolde","alterac","bandanas","durnholde keep","falconcrest","ravenholdt","strahnbrad","stromgarde","syndicate","uplands"},ang={["class:Rogue"]="Ravenholdt-gillet betalar bra för tjuvar som vågar smyga bakom fiendens linjer och stjäla emblem direkt från Syndicates banditer. De utnyttjar Syndicates interna paranoia.",["faction:Alliance"]="Syndicates agenter mördade Southshores tidigare magistrat och driver ständigt den hårt ansatta Stromgarde Militia mot total utplåning i Arathi Highlands.",["faction:Horde"]="Hövding Thrall och Lady Sylvanas har båda aktiva belöningar ute för Syndicate. De skickar ut spejare för att slå ut deras läger och återta stulna reliker.",["race:Orc"]="Syndicate ser ditt folk som bestar som är ämnade för kedjor och internering. Därför är det en angelägen hederssak att befria tillfångatagna fränder i Strahnbrad och Durnholde."},sec={{t="Den fallna adeln",b="När kungariket Alterac föll i vanära efter kung Aiden Perenoldes förräderi under det andra kriget, fråntogs dess aristokrati land och titlar. De kvarvarande adelsmännen från Alterac vägrade acceptera sin landsförvisning och slöt sig samman under den avlidne kungens son, prins Aliden Perenolde. De tog på sig orange bandanas och standardiserade sina grader med hjälp av inhyrda busar, stråtrövare och hedge-wizards. Så bildade de Syndicate. Utåt beter de sig som vanliga banditer: de plundrar karavaner, överfaller resande och driver utpressningsligor. I själva verket finns deras kriminella verksamhet enbart till för att finansiera ett organiserat försök att återerövra sina förfäders områden och kuva de omkringliggande länderna."},{t="Nordens fästen",b="Syndicate har befästa fotfästen över hela norra Lordaeron. I de snöiga Alterac Mountains befäste de den förstörda staden Strahnbrad och slog läger runt om i The Uplands och Dandred's Fold. Söderut håller de de sönderfallande resterna av Durnholde Keep i Hillsbrad Foothills och använder platsen som språngbräda för att trakassera Southshore och plundra försörjningsleder. Längre österut, på andra sidan Thoradin's Wall, samlar Lord Falconcrest en ockupationsarmé från Syndicate i de historiska ruinerna av Stromgarde Keep i Arathi. Där strider de aktivt mot den hårt ansatta Stromgarde Militia om herraväldet över Arathi Highlands."},{t="Fiender på alla fronter",b="Till skillnad från vanliga laglösa har Syndicate storslagna ideologiska ambitioner som gör att nästan alla regionala fraktioner hatar dem. De ser Alliansen som dödsfiender som stulit deras rättmätiga arv och riktar ofta in sig på tjänstemän i Southshore, som Magistrate Henry Maleb. Deras inställning till Horden är öppet rasistisk: i enlighet med Aedelas Blackmooress filosofi ser de orcher som bestar lämpade för slavarbete och vill återupprätta interneringslägersystemet. Sylvanas Windrunners Forsaken avrättar tillfångatagna medlemmar av Syndicate på fläcken, medan tjuvgillet Ravenholdt för ett ständigt skuggkrig mot deras klumpiga och arroganta agenter."},{t="Skuggornas marionetter",b="Syndicates adliga ledare tror att de kämpar för människans herravälde och sin förstfödslorätt, men i själva verket styrs de inifrån av mörkare krafter. Kultister från Argus Wake har infiltrerat deras högsta led och manipulerar män som Lord Falconcrest att ta Stromgarde Keep. Argus Wake tjänar inte människors intressen. I slutändan rapporterar de till Shadow Council i Jaedenar i Felwood och använder Syndicates arméer och stulna områden som en dödlig förtrupp för att bana väg för Burning Legion."}},faq={{q="Vilka är Syndicate?",a="Syndicate är en stor kriminell organisation bestående av adelsmän som förlorat sin ställning, banditer och legosoldater från det fallna kungariket Alterac. De leds av landsförvisade adelsmän som prins Aliden Perenolde och Lord Falconcrest och använder väpnade rån, mord och militär ockupation i ett försök att återupprätta Alterac.",al={"vad är syndicate","syndicates bakgrund","vilka är de orangeklädda"}},{q="Varför hatar Syndicate Alliansen?",a="Alterac förrådde Lordaerons Allians under det andra kriget. Som straff upplöste Alliansen kungariket och fråntog dess adelsmän deras land. Syndicates ledare betraktar Alliansen som sina dödsfiender och saboterar aktivt alliansstäder, handelskaravaner och militära garnisoner som Stromgarde Keep.",al={"varför angriper syndicate alliansen","syndicate och alliansen","alterac mot alliansen"}},{q="Varför tillfångatar och förslavar Syndicate orcher?",a="Syndicate följer den tidigare Durnholde-befälhavaren Aedelas Blackmooress hårda filosofi och ser orcher som vilda bestar lämpade enbart för ofrivilligt tjänande. Prins Aliden Perenolde försökte återupprätta Alliansens interneringslägersystem och använda förslavade orcher som tillfångatagits i Hillsbrad Foothills och Alterac som tvångsarbetare.",al={"syndicates orkslavar","varför sitter orcher i burar i strahnbrad","syndicates slaveri"}},{q="Hur förhåller sig Syndicate till Ravenholdt?",a="Ravenholdt är ett ansett gille av yrkesmördare och tjuvar i Alterac Mountains. De ser Syndicate som amatörmässiga, odisciplinerade råskinn. För att underminera Syndicate anlitar Ravenholdt skurkar som stjäl deras emblem. Syndicates ledning gallrar hänsynslöst ut agenter som vanärats genom att förlora sina emblem.",al={"ravenholdt mot syndicate","varför hatar ravenholdt syndicate","syndicates emblem"}},{q="Vem drar egentligen i trådarna bakom Syndicate?",a="Officiellt lyder Syndicate under landsförvisade adelsmän från Alterac, som prins Aliden Perenolde och Lord Falconcrest. De tror att de kämpar för att återta sina förlorade titlar. Viskningar i Arathi Highlands antyder att mörkare krafter ligger bakom ockupationen av Stromgarde. Resande kan lösa mysteriet genom att undersöka Syndicates fästen där.",al={"vem leder syndicate","argus wake och syndicate","shadow council och syndicate"}},{q="Var finns Syndicates främsta fästen?",a="Syndicate är verksamma i stor skala i tre områden: Alterac Mountains, med Strahnbrad och Dandred's Fold; Hillsbrad Foothills, med Durnholde Keep; och Arathi Highlands, med Northfold Manor. Där ockuperar de också en stor del av Stromgarde Keep under Lord Falconcrest.",al={"var finns syndicates baser","syndicates platser","var hittar man syndicate"}}},fx={["1053e6ff"]={q="Varför är Syndicate fientligt mot resande?",a="Syndicate ser alla främlingar som hot mot deras kriminella planer och territoriella ambitioner. De avskyr Alliansen för att den avvecklade Alterac efter det andra kriget, betraktar Horden som rena vildar lämpade enbart för tvångsarbete och tolererar ingen inblandning i sitt banditliv, sina mord och sina räder.",al={"varför syndicate anfaller","syndicate är fientligt","varför syndicate anfaller spelare"}},["8dd05730"]={q="Vem leder Syndicate?",a="Organisationen grundades och leddes i Alterac Mountains av prins Aliden Perenolde, son till Alteracs förrädiske, numera avlidne kung. I Arathi Highlands leds verksamheten av Lord Falconcrest från ruinerna av Stromgarde Keep, med stöd av regionala uppsyningsmän som Baron Vardus och Master Ryson.",al={"syndicates ledare","vem som styr syndicate","syndicates boss"}},c949a5e9={q="Vilka är Syndicate allierade med?",a="Öppet förlitar de sig på legosoldater, banditer och korrumperad mänsklig adel, samtidigt som de bekämpar nästan alla etablerade fraktioner. I hemlighet manipuleras Syndicate dock av Argus Wake, en ondskefull sammanslutning av häxmästare som tjänar Shadow Council i Jaedenar. Den har lovat att återupprätta Alteracs styre i utbyte mot fästen i norra Lordaeron.",al={"syndicates allierade","vilka som samarbetar med syndicate","syndicates samarbetspartner"}},ff7f041a={q="Varifrån kom Syndicate?",a="Syndicate föddes ur ruinerna av kungariket Alterac. Efter att kung Aiden Perenolde förrådde Alliansen under det andra kriget fråntogs Alterac sin suveränitet och föll i ruiner. Avsatta adelsmän och missnöjda aristokrater slöt sig samman under prins Aliden Perenolde och började ägna sig åt smuggling, banditverksamhet och terrorism för att återta sina förlorade landområden.",al={"syndicates ursprung","syndicates historia","hur bildades syndicate"}}},fp="9,231,15.622.0,24.554.0,21.649.0,29.411.2,22.286.0,41.283.0,48.314.1,53.278.0,55.331.2,46.303.0"}
P.entries["topic:tauren"] = {n="Tauren",s="Tauren, eller shu'halo på sitt eget språk, är ett ädelt nomadfolk av människoformade nötkreatur som hör hemma i centrala Kalimdor. De är djupt hängivna Jordmodern, shamanismen och naturen, och drevs nästan till utrotning av hänsynslösa centaurstammar innan de slöt förbund med Thralls Nya Horde. I dag har de enats under höghövding Cairne Bloodhoof och grundat ett permanent hem på Mulgore slättmarker och Thunder Bluffs höga höjder.",h="Tauren, eller shu'halo på sitt eget språk, är ett ädelt nomadfolk av människoformade nötkreatur som hör hemma...",kw={"the barrens","cairne bloodhoof","centaur","jordmodern","hamuul runetotem","kodo","magatha grimtotem","mulgore","shu'halo","tauren","thunder bluff"},ang={["class:Druid"]="Genom ärkedruiden Hamuul Runetotem arbetar taurendruider sida vid sida med Night Elf-druiderna i Cenarion Circle. De lägger rivaliteten mellan fraktionerna åt sidan för att läka landet och skydda The Emerald Dream.",["class:Shaman"]="Taurenfolkets shamanistiska traditioner är bland de äldsta i Azeroth. Deras läror var avgörande för att hjälpa orcherna återupptäcka sina heliga band till elementen efter de gångna krigens demoniska besudling.",["faction:Horde"]="Tauren ger Horden en moralisk kompass och djupa andliga rötter. Deras uråldriga visdom och heder mildrar orchernas och trollens aggressiva instinkter.",["race:Tauren"]="Som shu'halo har ditt folks uråldriga nomadvandringar gett vika för ett blomstrande hemland i Mulgore, säkrat genom det obrytbara brödraskapet mellan Cairne och Thrall."},sec={{t="Nomader i The Barrens",b="I otaliga generationer levde tauren som säsongsnomader och strövade över The Barrens torra slätter, jagade de stora kodo och lyssnade efter Jordmoderns röst. Deras fredliga vandringar hemsöktes dock av århundraden av brutalt blodspillan. De våldsamma centaurstammarna, födda ur den tragiska föreningen mellan Zaetar och prinsessan Theradras, förde ett obevekligt utrotningskrig mot dem. Taurenstammarna saknade ett befäst hemland och ville inte föra ett ändlöst krig, så de drevs till randen av utplåning och deras överlevnad hängde på en skör tråd."},{t="Den nya horden och Thunder Bluff",b="Räddningen kom genom en oväntad allians över havet. Under det tredje kriget mötte hövding Cairne Bloodhoof krigshövding Thrall och hans nyanlända orcher. De två ledarna såg att de delade en hederskänsla och en längtan efter sitt shamanistiska arv, och slöt sig samman. Med hjälp av Horden krossade tauren de härjande centaurerna och tog de frodiga, skyddade gräsmarkerna i Mulgore i besittning. Cairne lät uppföra staden Thunder Bluff på dess vindpinade platåberg. Tacksamma för att ha räddats marscherade tauren tillsammans med Horden till Mount Hyjal för att hejda den brinnande legionen."},{t="Andliga väktare och inre spänningar",b="Inom Horden bidrar tauren med ett stadigt och fredligt samvete. Deras kunskaper om naturen och elementen hjälpte till att återuppliva orchernas shamanism, medan ärkedruiden Hamuul Runetotem bygger sällsynta diplomatiska och andliga band med Night Elf-druider för att undersöka den växande fördärvelsen i The Emerald Dream. Ändå är enigheten skör. De flesta stammar vördar Cairnes visdom, men den främlingsfientliga och hänsynslösa Grimtotem-klanen bor i Thunder Bluff och smider i hemlighet planer på att tillskansa sig makten och styra shu'halo mot överhöghet. Klanen leds av den listiga äldre kvinnan Magatha Grimtotem."}},faq={{q="Varför gick tauren med i Horden?",a="Tauren var nära att utplånas av de hänsynslösa centaurerna i The Barrens. Krigshövding Thrall och hans orcher anlände och stred sida vid sida med Cairne Bloodhoof. De drev tillbaka centaurerna och hjälpte tauren att säkra Mulgore. Bundna av djup hederskänsla och gemensamma andliga värderingar svor Cairne sitt folks trohet till den nya Horden i tacksamhet.",al={"varför gå med i horden","tauren och hordens allians","varför är tauren med i horden"}},{q="Vem leder tauren?",a="Tauren leds av höghövding Cairne Bloodhoof, den visa och vördnadsvärda ledaren för Bloodhoof-stammen. Han är respekterad för sin styrka och sitt sansade omdöme och enar de olika stammarna från sin plats högst upp i Thunder Bluff. Till hans hjälp står ärkedruiden Hamuul Runetotem och äldre kvinnan Magatha Grimtotem.",al={"taurenfolkets ledare","taurenhövding","vem styr thunder bluff"}},{q="Vad är Jordmodern?",a="Jordmodern är den centrala gudomen i taurenfolkets tro. Shu'halo tror att hon skapade världen, solen och månen. De vördar henne genom en livsstil som är djupt förankrad i naturens balans, årstidsvandringar, jakt och respekt för elementen.",al={"jordmodern","vem är jordmodern","taurenfolkets religion"}},{q="Varför hatar tauren centaurerna?",a="Centaurerna jagade tauren för nöjes skull och förde krig mot dem i århundraden i centrala Kalimdor. De såg taurenfolkets fredliga andlighet som en svaghet och jagade dem från plats till plats. Innan orcherna ingrep drev de nästan shu'halo till fullständig utrotning.",al={"taurenfolkets krig mot centaurerna","fejd med centaurerna"}},{q="Kan tauren vara druider?",a="Ja. Ärkedruiden Hamuul Runetotem leder taurendruiderna. De lär sig vildmarkens vägar tillsammans med Night Elf-folket, vilket gör taurendruiderna till en hörnsten i Cenarion Circle.",al={"taurendruidernas historia","hur blev tauren druider"}},{q="Är alla tauren lojala mot Cairne Bloodhoof?",a="De flesta stammar vördar Cairne, men Grimtotem-stammen är ett bittert undantag. De leds av Magatha Grimtotem och tror att tauren är överlägsna alla andra raser. De avskyr Cairnes allians med Horden och arbetar i tysthet för att underminera hans fredliga styre.",al={"grimtotem-klanens lojalitet","taurenfolkets inbördeskrig"}},{q="Vilka klasser kan tauren ha?",a="Tauren tränar som krigare, jägare, shamaner och druider.",al={"taurenklasser","vilka klasser kan tauren ha"}}},fp="6,342,21.443.0,31.534.0,41.562.1,34.311.0,21.251.0,25.240.0,35.246.0,21.166.0,41.250.0,28.53.0"}
P.entries["topic:terenas-menethil-ii"] = {n="Terenas Menethil II",s="Över hela Lordaeron bär Terenas Menethil II ett kungarikes börda genom krig och dess efterspel. I mer än fem årtionden regerade han som en vis och diplomatisk kung, grundade Alliansen av Lordaeron under det andra kriget och gav den unge prins Varian Wrynn skydd. Mordet på honom av hans korrumperade son, prins Arthas, inledde Lordaerons fall för gisslet.",h="Över hela Lordaeron bär Terenas Menethil II ett kungarikes börda genom krig och dess efterspel.",kw={"alliansen av lordaeron","arthas","capital city","frostmourne","lordaeron","menethil","andra kriget","terenas","tredje kriget","uther"},ang={["class:Paladin"]="Som paladin följer du en väg som Terenas hjälpte till att forma tillsammans med ärkebiskop Alonsus Faol och Uther the Lightbringer, när de grundade Silverhandens riddare. Terenas ledde sin egen son in i orden.",["faction:Alliance"]="Som medlem av Alliansen ärver du arvet efter koalitionen som Terenas grundade med Anduin Lothar för att besegra den gamla horden i det andra kriget.",["race:Human"]="Som människa minns du kung Terenas som en legendarisk patriark som enade de sju kungadömena mot till synes omöjliga odds. Hans plötsliga svek och död för sin egen sons hand är fortfarande en nationell tragedi.",["race:Undead"]="Som Forsaken kallade du en gång Capital City ditt hem under Terenas, din siste levande härskare. Hans fall dömde riket åt gisslet."},sec={{t="Alliansens grundare",b="När flyktingar från Stormwind nådde norr med Sir Anduin Lothar besvarade kung Terenas Menethil II deras vädjan. Han samlade monarkerna från de splittrade människorikena och sändebud från Ironforge och Quel'Thalas och förde dem samman i Alliansen av Lordaeron. Terenas gjorde inte anspråk på att leda dess arméer. Han utsåg Lothar till överbefälhavare och enade mänsklighetens riken för första gången på årtusenden. Tillsammans besegrade de den gamla horden."},{t="Segerns bördor",b="Efter det andra kriget insisterade Terenas på att överlevande orcher skulle hållas i interneringsläger i stället för att avrättas. Han trodde att freden kunde bestå när deras demoniska raseri hade lagt sig. Lägren lade en tung skattebörda på Lordaerons allierade. Gilneas stängde sig bakom The Greymane Wall, Stromgarde lämnade Alliansen efter politiska meningsskiljaktigheter och högalverna drog sig helt ur. Terenas fick bära kostnaden medan koalitionen föll sönder."},{t="Tronens fall",b="Terenas stod inför orchuppror ledda av Thrall, rykten om dödskulter i norr och en mystisk pest. En kringvandrande profet uppmanade kungen att överge Lordaeron och fly över havet till Kalimdor, men Terenas avfärdade honom som galen. Kort därefter återvände prins Arthas från sitt fälttåg i norr och hyllades som segrare. Under det kungliga firandet knäböjde Arthas inför sin far, drog runklingan Frostmourne och stötte den genom Terenas hjärta. Kungariket krossades."}},faq={{q="Vem var kung Terenas Menethil II?",a="Kung Terenas Menethil II regerade över Lordaeron i mer än femtio år och stod i centrum för politiken i norr. Han grundade Alliansen av Lordaeron för att bekämpa Horden i det andra kriget och styrde från Capital City fram till sin död.",al={"vem är terenas","terenas menethil","kung av lordaeron"}},{q="Hur dog Terenas?",a="Terenas dödades av sin son, prins Arthas Menethil, i tronrummet. Arthas hade korrumperats av runklingan Frostmourne under sin expedition till Northrend. Han återvände till Capital City hyllad som segrare och stötte klingan genom sin fars hjärta.",al={"hur dog terenas","arthas dödar sin far","terenas död"}},{q="Vilken relation hade Terenas till Stormwind?",a="Terenas hjälpte Stormwind att överleva. Efter att det sydliga kungariket föll i det första kriget gav han dess överlevande en fristad och uppfostrade prins Varian Wrynn tillsammans med sin egen son Arthas. Han behandlade Varian som en andra son tills Stormwind kunde återtas och byggas upp igen.",al={"terenas och stormwind","terenas och varian","hjälpte terenas stormwind"}},{q="Varför föll Alliansen av Lordaeron sönder under hans styre?",a="Efter det andra kriget valde Terenas att hålla tillfångatagna orcher i interneringsläger i stället för att avrätta dem. Den höga kostnaden väckte ilska bland medlemsrikena. Gilneas byggde The Greymane Wall och isolerade sig, Stromgarde lämnade efter politiska meningsskiljaktigheter och alverna i Quel'Thalas drog sig helt ur.",al={"varför föll alliansen sönder","varför lämnade kungarikena lordaeron","skatter för interneringsläger"}},{q="Kände Terenas till odödhetens pest?",a="Terenas kände till märkliga kulter och en sjukdom som spred sig i norr, men underskattade faran. Dalaran uppmanade honom att sätta de nordliga städerna i karantän, men han tvekade av rädsla för att hans folk skulle lida mer. Han skickade prins Arthas och Uther the Lightbringer för att undersöka saken, ovetande om fällan som väntade dem.",al={"kände terenas till pesten","terenas svar på pesten"}},{q="Varför lyssnade Terenas inte på den mystiske profeten?",a="En beslöjad profet kom till Terenas rådssal och uppmanade honom att evakuera Lordaerons folk västerut till Kalimdor. Terenas avfärdade honom som en från vettet lössläppt fanatiker och trodde att hans arméer, paladiner och starka kungarike skulle klara de prövningar som väntade.",al={"terenas och profeten","medivh och terenas","varför flydde inte terenas"}}},fx={be9b83e5={q="Vilka var kung Terenas närmaste bundsförvanter?",a="Under sin regeringstid räknade Terenas kung Thoras Trollbane av Stromgarde och Uther the Lightbringer bland sina närmaste personliga vänner, och betraktade Uther nästan som en bror. Han tog också emot prins Varian Wrynn och sir Anduin Lothar som flyktingar och fostrade Varian som en andra son vid prins Arthas sida. Även om riken som Gilneas och Quel'Thalas så småningom lämnade Alliansen på grund av skatter och gränser, behöll Terenas Stormwinds, Ironforges, Kul Tiras och Kirin Tor i Dalarans orubbliga lojalitet fram till sin död.",al={"terenas bundsförvanter","vem stödde terenas","kung terenas bundsförvanter"}},aa06bf27={q="Vad är historien om kung Terenas Menethil II?",a="Terenas föddes in i den kungliga Menethildynastin, som hade styrt Lordaeron i generationer, och översåg mer än fem årtionden av fred och välstånd. När Stormwind föll i det första kriget samlade han de mänskliga rikena, högalverna och dvärgarna för att bilda den ursprungliga Alliansen av Lordaeron, som framgångsrikt slog tillbaka Horden i det andra kriget. Terenas förespråkade att besegrade orcher skulle interneras i stället för avrättas, vilket tömde Alliansens kassakistor och drev flera kungadömen bort. Hans långa, ädla regeringstid fick ett abrupt slut när hans egen son, prins Arthas, återvände förvriden från Northrend och mördade honom i den kungliga tronsalen.",al={"terenas historia","terenas menethils regeringstid","berättelsen om kung terenas"}}},fp="19,341,25.472.0,22.428.0,22.475.2,33.224.0,20.256.0,47.256.0,61.298.0,45.304.0,52.248.0"}
P.entries["topic:third-war"] = {n="Tredje kriget",s="Tredje kriget var den apokalyptiska konflikt som krossade den gamla världsordningen för bara några år sedan. Burning Legion låg bakom kriget, som utlöstes genom Lich Kings Plague of Undeath. Under kriget föll Kingdom of Lordaeron och Quel'Thalas förstördes nästan helt, innan allt kulminerade i ett desperat, enat försvar vid Mount Hyjal.",h="Tredje kriget var den apokalyptiska konflikt som krossade den gamla världsordningen för bara några år sedan.",kw={"archimonde","arthas","hyjal","mannoroth","medivh","nordrassil","scourge","stratholme","terenas","tredje kriget"},ang={["class:Paladin"]="Knights of the Silver Hand slets isär under kriget när Arthas upplöste dem, mördade Uther the Lightbringer och förvandlade deras heliga salar till benhus.",["faction:Alliance"]="Lordaerons fall flyttade Alliance-ledningens centrum söderut till Stormwind och Ironforge, medan de överlevande blickar norrut med brinnande längtan efter att återta sitt hemland.",["faction:Horde"]="För Thralls Horde blev kriget en prövning som ledde till försoning: Grommash Hellscream dräpte Mannoroth och bröt den demoniska blodsförbannelsen för gott, så att orcherna kunde bygga en självständig nation i Kalimdor.",["race:NightElf"]="Försvaret av Nordrassil kostade kaldorei deras odödlighet och blottade deras uråldriga hemland för omvärlden för första gången på tiotusen år.",["race:Undead"]="Forsaken är levande minnesmärken över krigets fasor. De var invånare i Lordaeron, slaktade av pesten och tvingade att tjäna Scourge tills de bröt sig fria och tog Undercity i besittning."},sec={{t="Pesten och prinsen",b="Kriget började i det fördolda i norra Lordaeron, förklätt till en våldsam sjukdom som spreds med infekterad säd från Andorhal. Den smittade skörden dödade inte bara sina offer; den reste dem som glupska ghouls bundna till Lich Kings vilja. Prins Arthas Menethil försökte hejda smittan tillsammans med Kirin Tor-magikern Jaina Proudmoore. Förblindad av sorg, vrede och dreadlordernas manipulationer lät Arthas utrota den smittade befolkningen i Stratholme innan han förföljde sin fiende till Northrends frusna ödemarker. Där tog han det förbannade runsvärdet Frostmourne i sin hand och kastade bort sin själ. Han återvände söderut bara för att mörda sin far, kung Terenas, och överlämna Lordaeron åt Scourge."},{t="Legionens invasion",b="Stärkt av döden krossade Arthas högalvernas rike Quel'Thalas för att återuppväcka nekromantikern Kel'Thuzad vid Sunwell. Den odöda armén belägrade sedan Dalaran och lade beslag på de trollformelsböcker som krävdes för att kalla demonherren Archimonde till Azeroth. När Burning Legions befälhavare satte sin fot på de dödligas jord jämnades Dalaran med marken i en magisk uppvisning av förödelse. Scourge hade fyllt sin funktion som förtrupp, och Burning Legion riktade blicken mot den eviga kraften på andra sidan Great Sea."},{t="Färden västerut och Mount Hyjal",b="Vägledd av kryptiska varningar från den mystiske profeten, som senare visade sig vara den försonade väktaren Medivh, ledde krigschef Thrall New Horde över Great Sea, medan Lady Jaina Proudmoore evakuerade överlevande flyktingar från Alliance. I det forntida Kalimdor drabbade nykomlingarna samman med de tillbakadragna nattalverna, innan alla tre fraktionerna insåg det överhängande hotet. Under World Tree Nordrassil, på toppen av Mount Hyjal, stod dödliga tillsammans mot omöjliga odds. Archimonde förstördes av uråldriga wisps när han nådde trädet. Därmed krossades Legionens förtrupp och kriget tog slut."},{t="En sargad värld",b="Även om Archimonde föll är freden år tjugofem efter Dark Portal bräcklig och märkt av förlust. Alliance of Lordaeron är borta, och Stormwind och Ironforge får nu hålla samman den södra Alliance medan Lordaeron ruttnar som Plaguelands. I Kalimdor har Thralls Horde grundat Durotar, men spänningarna med de nyallierade nattalverna är fortfarande explosiva. Scourge består i de norra ruinerna, och de befriade odöda, Forsaken, håller nu Capital Citys katakomber och kämpar för sin överlevnad mot både sina forna herrar och hämndlystna korsfarare."}},faq={{q="När ägde Tredje kriget rum?",a="Tredje kriget började år tjugo efter Dark Portal, när Plague of Undeath bröt ut i Lordaeron, och slutade år tjugoett vid slaget om Mount Hyjal. Nu, år tjugofem efter Dark Portal, ligger förödelsen bara fyra år tillbaka i tiden. Ruinerna är fortfarande färska, och nästan alla vuxna som lever i dag stred i kriget eller förlorade familj i det.",al={"när var tredje kriget","hur länge sedan var kriget","tredje krigets datum"}},{q="Hur skilde sig Tredje kriget från det Första och Andra kriget?",a="Första och Andra kriget var främst konflikter mellan Old Horde och Alliance-rikena. Tredje kriget var en global demonisk invasion som krossade hela nationer. Dödligas fiender stred inte bara mot varandra, utan också mot det kosmiska hotet från Burning Legion och dess odöda Scourge på tre kontinenter. Det tvingade dem till en desperat vapenvila.",al={"skillnaden mellan tredje och andra kriget","varför tredje kriget var annorlunda","horde mot alliance i tredje kriget"}},{q="Vad hände med Kingdom of Lordaeron?",a="Lordaeron förstördes inifrån. The Cult of the Damned förgiftade den regionala spannmålsförsörjningen med Plague of Undeath, dödade befolkningen och reste dem som monster. Rikets egen kronprins, Arthas, dukade under för korruptionen, mördade sin far kung Terenas II och överlämnade det sönderslagna riket åt Scourge.",al={"lordaerons öde","varför lordaeron förstördes","vad hände med terenas"}},{q="Vem var profeten som varnade alla för att bege sig till Kalimdor?",a="Profeten var Medivh, den siste väktaren av Tirisfal. Medivh återvände för att sona sin tidigare roll i att öppna The Dark Portal. Förklädd till en kringvandrande gestalt höljd i korpfjädrar varnade han ledarna för att Lordaeron var dömt och uppmanade dem att enas på den bortglömda kontinenten Kalimdor.",al={"vem var profeten","profeten i korpmantel","medivh i tredje kriget"}},{q="Varför är nattalverna med i Alliance nu?",a="I tiotusen år levde nattalverna i strikt isolering. Tredje kriget förde Legion tillbaka till deras heliga skogar och tvingade dem att offra sin odödlighet för att dräpa Archimonde vid World Tree. Ställda inför en värld som förändrats i grunden, allt större resurskonflikter med Thralls Horde och kvarlevande korruption från Scourge övergav de sin ensamhet och slöt en allians med folken i Eastern Kingdoms.",al={"varför nattalverna gick med i alliance","nattalverna i tredje kriget","kaldorei går med i alliance"}},{q="Hur undkom Horde kriget i Lordaeron?",a="Krigschef Thrall litade på Medivhs profetiska drömmar. Han samlade de befriade klanerna från interneringslägren, anföll människornas hamnar för att lägga beslag på segelfartyg och flydde över Great Sea innan Scourge eller Legion hann sluka hela Lordaeron.",al={"hur thrall lämnade lordaeron","orcher seglar västerut","hordes flykt till kalimdor"}}},fx={b67a3dac={q="Vad var det tredje kriget?",a="Det tredje kriget var en katastrofal global konflikt där den demoniska Burning Legion inledde sin andra invasion av Azeroth, med hjälp av det odöda Scourge. Kriget började med de odödas pest i norra Lordaeron och prins Arthas Menethils förräderi, och spred sig snabbt över Eastern Kingdoms och vidare till Kalimdor. Till skillnad från tidigare konflikter mellan bara orcher och människor drog det in nästan alla större raser på Azeroth, innan det kulminerade i ett desperat, enat försvar på Mount Hyjal.",al={"vad är det tredje kriget","sammanfattning av tredje kriget","förklara tredje kriget"}},["4a458aae"]={q="Varför kallas det det tredje kriget?",a="Det kallas det tredje kriget eftersom det följde på det första och andra kriget mellan den ursprungliga orcherhorden och den stora Alliansen av Lordaeron. Eftersom invasionen orsakade en aldrig tidigare skådad global förödelse och förde med sig demonarméer är den också känd som det tredje stora kriget, kaoskriget och kaosets era.",al={"ursprunget till namnet tredje kriget","varför kallas det tredje kriget","namnet kaosets era"}}},fp="9,234,25.585.0,26.419.0,31.524.0,15.492.0,30.238.0,63.284.0,42.279.0,59.222.0,49.409.0,46.223.0"}
P.entries["topic:titan"] = {n="Titan",s="Titanerna är en uråldrig ras av väldiga, gudalika varelser som färdas genom kosmos, skapar ordning och formar världar. I forntiden kom de till Azeroth för att besegra de kaotiska Old Gods, bygga väldiga anläggningar på jordytan och främja liv innan de gav sig av till det Stora mörkret bortom.",h="Titanerna är en uråldrig ras av väldiga, gudalika varelser som färdas genom kosmos, skapar ordning och formar...",kw={"aman'thul","earthen","eonar","khaz'goroth","skapare","norgannon","ordning","pantheon","titan"},ang={["class:Mage"]="Arkan magi är titanernas grundläggande livskraft, och dess ordnade principer kan spåras direkt till de strukturella förtrollningar som Pantheon vävde in i världen.",["profession:Mining"]="Gruvarbetare gräver djupt i jordens ben och hittar ofta oförstörda metallådror smidda av titanerna och arkitektoniska grundvalar som är äldre än den nedtecknade historien.",["race:Dwarf"]="Titanerna vördas som de gudomliga Skaparna. Att upptäcka deras ursprung genom titaniska reliker är Explorers' League och King Magni Bronzebeards främsta uppdrag.",["race:Gnome"]="Gnomer delar ett mekaniskt arv som härstammar från titanernas skapelser, vilket ligger bakom deras naturliga fallenhet för urverkskonstruktion och utgrävning."},sec={{t="Kosmos arkitekter",b="Titanerna är kosmiska jättar smidda av urmateria och magi, och förkroppsligar ordningens och skapelsens krafter. Under sina färder genom det Stora mörkret bortom sökte de upp slumrande världar att odla. De reste kontinenter, stillade kaotiska elementarkrafter och formade liv. För att upprätthålla balansen skapade de mäktiga konstruktioner av sten, järn och hav som skulle vaka över deras verk."},{t="Azeroths ordnande",b="För länge sedan upptäckte titanernas Pantheon Azeroth, som hölls i de kaotiska elementarherrarnas och de fasansfulla Old Gods grepp. Titanerna förde krig mot dessa parasitiska fasor, förvisade elementarerna till fickdimensioner och förseglade de monstruösa Old Gods djupt under jordskorpan. När de säkrat världen formade de storslagna biomer, byggde valvkomplex som Uldaman och anförtrodde fem mäktiga drakar, Dragon Aspects, ansvaret för landet, magin, tiden och själva livet. Sedan färdades de åter bland stjärnorna."},{t="Den fallne förkämpen",b="Alla titanerna delade inte längre Pantheons vision om perfekt ordning. Sargeras, en gång titanernas främste krigare och försvarare, blev förtvivlad och skräckslagen av det djupa kosmiska mörker och den demoniska ondska han fått i uppdrag att bekämpa. Han förkastade sina fränders verk och vände sig till nihilism. Han grundade den demoniska Burning Legion för att släcka all skapelse i stället för att låta den fördärvas."}},faq={{q="Lever titanerna fortfarande, och finns de på Azeroth?",a="Titanerna själva lämnade Azeroth för evigheter sedan och for till det Stora mörkret bortom efter att ha besegrat Old Gods och ordnat världen. De lämnade kvar väldiga väktare, konstruktioner av sten och järn samt enorma, begravda valvkomplex som skulle vaka över deras skapelse.",al={"var finns titanerna","finns titanerna på azeroth","titanernas platser"}},{q="Varför bryr sig dvärgarna så mycket om titanerna?",a="Dvärgarna härstammar direkt från earthen, en ras av underjordiska stenvarelser som titanerna formade för att hugga ut världens grundvalar. Genom arkeologi och utgrävningar av ruiner som Bael Modan och Uldaman försöker dvärgarna upptäcka sitt eget bortglömda ursprung.",al={"dvärgarnas koppling till titanerna","varför gräver dvärgarna","dvärgarna och skaparna"}},{q="Vad är Pantheon?",a="Pantheon är titanernas styrande råd, lett av Highfather Aman'Thul. Övriga medlemmar är Khaz'goroth, världarnas formare, Eonar, livets beskyddare, Norgannon, de himmelska magiernas väktare, Golganneth, himlarnas herre, och Aggramar, förkämpen som ersatte Sargeras.",al={"titanernas pantheon","vem leder titanerna","titanernas ledare"}},{q="Skapade titanerna Dragon Aspects?",a="Ja. Innan Pantheon lämnade Azeroth kanaliserade de sina krafter genom väktarna för att välsigna fem protodrakar. Alexstrasza, Ysera, Malygos, Nozdormu och Neltharion fick enorma krafter för att värna om livet, naturen, magin, tiden och jorden.",al={"titanernas drakar","aspekternas ursprung","vem skapade aspekterna"}},{q="Är Sargeras en titan?",a="Sargeras var en gång Pantheons förkämpe och försvarade kosmos mot kaos och demoner. Mörkret han bevittnade drev honom till förtvivlan och vansinne. Han bröt med sina bröder för att bilda Burning Legion och hängav sig åt att bränna ner det ordnade universumet.",al={"vem är sargeras","är sargeras en gud","sargeras ursprung"}},{q="Föll en titan i Silithus?",a="Profetior nedtecknade av Qiraji-profeten Skeram hävdar att en titan stred mot en uråldrig ondska i Silithus södra öknar och föll. Men forskare och upptäcktsresande tvistar om huruvida varelsen verkligen var en titan eller bara en av deras titaniska konstruktioner.",al={"silithus titan","c'thuns profetia om en titan","dödade c'thun en titan"}}},fx={f6eb9ea0={q="Vad är titanerna?",a="Titanerna är kolossala, gudalika kosmiska väsen och ordningens och skapelsens främsta förkämpar. De vandrar genom det stora mörkret, ger formlösa världar struktur och främjar liv vart de än färdas.",al={"vilka är titanerna","vad är en titan","titanernas historia"}},["23c22d21"]={q="Varifrån kom titanerna?",a="Ingen dödlig vet var titanerna kom ifrån. De är uråldriga väsen från det stora mörkret som färdas genom kosmos för att bringa ordning till nyfödda världar, som när de kom till Azeroth, besegrade de gamla gudarna och formade landet.",al={"titanernas ursprung","varifrån kom titanerna","hur skapades titanerna"}},["91d84aea"]={q="Vem leder titanerna?",a="Titanerna leds av överfader Aman'Thul, den äldste bland dem och ledare för deras styrande råd, Pantheon. Med enorma tidsmässiga och kosmiska krafter vägleder Aman'Thul deras uppdrag genom det stora mörkret för att skapa ordning i världar.",al={"vem leder titanerna","titanernas ledare","ledaren för pantheon"}}},fp="5,244,24.304.0,23.408.0,19.320.0,42.206.0,49.232.0,21.277.0,41.237.0,20.239.0,29.238.0"}
P.entries["topic:trogg"] = {n="Trogg",s="Troggs är råbarkade underjordiska humanoider, ättlingar till de tidigaste misslyckade titanformade experimenten som förseglades djupt under jorden. Efter att nyligen ha klöst sig upp till ytan när dvärgarnas utgrävningar störde deras uråldriga valv, har dessa outtröttliga grävare tagit över dvärgarnas stenbrott och drivit bort gnomerna från deras älskade huvudstad Gnomeregan.",h="Troggs är råbarkade underjordiska humanoider, ättlingar till de tidigaste misslyckade titanformade...",kw={"caverndeep","jordvarelser","gnomeregan","grubbis","oggleflint","rockjaw","stonesplinter","trogg","uldaman"},ang={["faction:Alliance"]="Att rensa bort troggs från Dun Morogh, Loch Modan och Gnomeregan är fortfarande en viktig försvarsinsats för att skydda bergariket och dess flyktingar.",["profession:Mining"]="Troggbon finns ofta vid rika mineralådror och i djupa gruvor som Gol'Bolar, vilket tvingar gruvarbetare att försvara sina fyndigheter med hackor och hammare.",["race:Dwarf"]="Dessa vilda släktingar grävdes fram av dina egna hackor när du sökte efter titanernas arv. Deras intrång i Khaz Modan är därför en direkt följd av dvärgarnas arkeologi.",["race:Gnome"]="Troggs är en bitter plåga för ditt folk. De krossade ert underjordiska hem och skingrade de överlevande gnomerna till Tinker Town i Ironforge."},sec={{t="De bristfälliga föregångarna",b="Långt innan dödliga raser började skriva historia försökte de titanformade väktarna skapa tjänare av sten. Den första utformningen gick snett och gav upphov till stenhyade bestar med låg intelligens och tygellös vildhet. Bekymrade över sina misslyckade skapelser förfinade väktarna matrisen till jordvarelserna, som så småningom skulle bli dvärgarnas förfäder. De jättelika Ironaya ville inte utplåna de ofullkomliga troggsen och förseglade dem därför djupt under jorden i valvet Uldaman, med avsikten att hålla dem fångna i evig dvala."},{t="Väckta av hackor",b="I oräkneliga årtusenden låg troggsen i dvala, tills Explorers' League of Ironforge bröt igenom de uråldriga underjordiska komplexen i Khaz Modan. När de vaknade i en obekant tidsålder vällde svärmar av ursinniga troggs upp ur djupet och förföljde sina avlägsna dvärgsläktingar med nedärvd vrede. Ytan var ljus och ogästvänlig, så de högg ut vidsträckta tunnelsystem under Dun Morogh, Loch Modan och Badlands och överföll snart stenbrott, arkeologiska utgrävningsplatser och handelsstationer."},{t="Katastrofen i Gnomeregan",b="Troggsvärmarna följde vibrationer och ljud genom underjorden och grävde sig rakt upp i Gnomeregan. Gnomerna var desperat underlägsna i antal och råstyrka och utkämpade ett bittert krig i de underjordiska gångarna. I ett desperat försök, planerat av Mekgineer Thermaplugg, släppte High Tinker Gelbin Mekkatorque ut radioaktiv gas för att utrota inkräktarna. Den bestrålade gasen dödade tragiskt nog omkring åttio procent av gnomernas befolkning, men gjorde bara troggsen ännu ursinnigare. Den storslagna teknostaden blev ett bestrålat fäste för troggs."}},faq={{q="Vad är troggs egentligen?",a="Troggs är underjordiska humanoider som skapades som den första, bristfälliga generationen stentjänare av de titanformade väktarna. Bekymrade över deras råa brutalitet låste väktarna in dem i dvalavalv som Uldaman i stället för att förgöra dem. Dvärggrävare råkade gräva fram dem tusentals år senare.",al={"troggs ursprung","vad är en trogg","troggs historia"}},{q="Är troggs släkt med dvärgar?",a="Ja. Båda raserna formades av titanernas väktare. Troggs är väktarnas oförfinade första försök, medan jordvarelserna, dvärgarnas förfäder, var den fulländade andra versionen.",al={"är dvärgar och troggs släkt","sambandet mellan troggs och dvärgar"}},{q="Hur tog troggsen Gnomeregan?",a="Troggsen lockades av vibrationerna från tunga maskiner och grävde sig in i Gnomeregan underifrån. Trots gnomernas försvarsuppfinningar övermannade inkräktarna försvararna med sitt överlägsna antal. Ett misslyckat försök att driva ut dem med radioaktiv gas dödade i stället de flesta gnomerna och befäste troggs kontroll över staden.",al={"varför finns troggs i gnomeregan","troggs attack mot gnomeregan"}},{q="Kan troggs tala eller har de en avancerad kultur?",a="Troggs har mycket begränsad intelligens och kommunicerar främst med gutturala grymtningar och vrål. De värdesätter råstyrka högst av allt och väljer stamledare genom våld. Vissa kan utföra rudimentär schamanistisk magi, men deras hantverk är grovt och når sällan längre än till enkla klubbor, stenpilar och stulna reliker.",al={"kan troggs prata","troggskultur","troggs intelligens"}},{q="Varför samlar troggs på uråldriga reliker?",a="Explorers tror att deras tvångsmässiga samlande av uråldriga titanreliker är en instinktiv rest från deras titanformade ursprung. Troggs förstår dock sällan vad de bär på och använder ovärderliga artefakter som klubbor eller primitiva lyckoamuletter.",al={"varför samlar troggs på artefakter","troggskatter"}},{q="Finns det troggs utanför Khaz Modan?",a="Ja. Underjordiska troggstammar har byggt bon över hela Azeroth, bland annat Ragefire-troggsen djupt inne i Ragefire Chasm under Orgrimmar, Gravelflint-troggsen i Darkshore och grupper i Badlands och Alterac.",al={"troggs platser","troggs i durotar","troggs i kalimdor"}}},fx={["0f8118fe"]={q="Varför är troggar så fientliga mot andra raser?",a="Troggar drivs nästan helt av rå instinkt, list och ren aggressivitet. När de väcktes ur sin uråldriga slummer djupt under jorden var deras omedelbara impuls att låta sin vrede gå ut över dem som bodde ovan jord, särskilt deras dvärgsläktingar som bröt sig in i deras valv. De är enfaldiga och revirhävdande och ser andra levande varelser antingen som hot som måste krossas eller som måltider, och tar gärna till våld och till och med kannibalism utan provokation.",al={"varför attackerar troggar","är troggar aggressiva","varför hatar troggar dvärgar"}},["9c157b85"]={q="Vem leder troggarna?",a="Troggar har ingen enad härskare eller central civilisation. I stället organiserar de sig i spridda stammar och klaner, som Rockjaw-, Stonesplinter- och Stonevault-troggarna. Inom varje stam tillhör ledarskapet den starkaste, största och grymmaste besten som kan upprätthålla sin makt genom hot och blodsutgjutelse, som Grimlok i Uldaman.",al={"troggarnas ledare","troggarnas hövding","troggarnas kung"}},["21373546"]={q="Har troggar några bundsförvanter?",a="Troggar slåss nästan alltid ensamma. Deras vildhet, kannibalistiska tendenser och fientlighet mot andra raser gör diplomati omöjlig, och de avskyr främlingar. Ett sällsynt undantag finns bland Stonesplinter-klanen, som har knutit lösa band till kobolderna i Tunnel Rats, men verkliga allianser utanför den egna sorten är i stort sett obefintliga.",al={"troggarnas bundsförvanter","vilka samarbetar med troggar","troggfraktioner"}},["638bdf0a"]={q="Varifrån kom troggarna?",a="Troggar var den första generationen titanformade varelser som skapades av titanernas väktare. Konstruktionen visade sig vara bristfällig och överdrivet komplicerad, och skapade stenhudade, brutala varelser utan högre intellekt. Bestörta över resultatet förfinade väktarna sina följande försök till jordlingar och förseglade de defekta troggarna i stasisvalv som Uldaman. I årtusenden sov de under Azeroth, tills dvärgarbetare ovetande grävde upp deras gravar.",al={"troggarnas ursprung","troggarnas historia","hur skapades troggar"}}},fp="5,206,23.418.0,23.401.0,29.421.1,24.221.0,30.151.0,34.263.0,49.260.0,37.199.0,39.198.0"}
P.entries["topic:troll"] = {n="Troll",s="Troll är en av Azeroths äldsta folkslag och uppstod kring Evighetens källa långt före Sundringen. De är kända för sin otroliga fysiska läkningsförmåga, sin dyrkan av urandar som kallas loa och sin mästerliga voodoo. Deras splittrade imperier härskade en gång över stora delar av den forntida världen. I dag är uråldriga kungadömen som Gurubashi och Amani fortfarande djupt fientliga mot främlingar, medan Darkspear-stammen har funnit en varaktig fristad i Thralls Horde.",h="Troll är en av Azeroths äldsta folkslag och uppstod kring Evighetens källa långt före Sundringen.",kw={"amani","aqir","darkspear","gurubashi","loa","läkning","troll","voodoo","zandalari"},ang={["class:Priest"]="Trollens prästerskap är oupplösligt knutet till loa och skuggjakten. De kommunicerar direkt med djurandar och uråldriga mörka krafter i stället för det heliga ljuset.",["faction:Horde"]="Darkspear-trollens list, rörlighet och andliga styrka förser hövdingens fana med oumbärliga spejare, skuggjägare och shamaner.",["race:NightElf"]="Alvernas historia och forntida myter spårar bittra rivaliteter tillbaka till trollkungadömen. De betraktar trollens religiösa voodoo och offerriter med stor misstänksamhet.",["race:Troll"]="Ditt arv sträcker sig längre tillbaka än nästan varje civilisation på Azeroth. Medan dina kusiner i Zul'Gurub och Zul'Aman klamrar sig fast vid bitter, isolationistisk stolthet, bygger Darkspear ett bestående arv genom Hordens styrka."},sec={{t="Vildmarkens barn",b="Långt före den stora Sundringen splittrade det forntida Kalimdor, närde Evighetens källas urkrafter trollens uppkomst. De tidiga trollen var vilda, mycket rörliga jägare och samlare. Deras unika fysiologi gav dem häpnadsväckande läkekraft, så att de snabbt återhämtade sig från svåra sår och med tiden till och med kunde växa ut avhuggna lemmar på nytt. De slog sig ned kring Zandalars heliga berg och riktade sin vördnad mot urandar som de kallade loa. Under andlig vägledning av skuggjägare och häxdoktorer växte dessa ritualer samman till voodoo."},{t="Kriget mot aqir",b="I forntiden förde trollen ett långt krig mot de insektslika aqir, vars svärmar hotade att ta över kontinenten. Amani- och Gurubashi-imperierna ledde kampen och drev till sist aqir till landets avlägsna hörn: norrut, till det som blev Azjol-Nerub, och söderut, till öknarna där Ahn'Qiraj skulle resa sig."},{t="Ett splittrat arv",b="När insektssvärmarna hade besegrats och hållits i schack upplöstes trollens gemensamma sak. Varje stor fraktion drog sig tillbaka till sitt eget självständiga imperium och utvecklade egna kulturer, fysiska särdrag och stamstrukturer anpassade till skogar, djungler och frusna ödemarker. Efter årtusenden av åtskillnad, rivalitet och territoriella krig mot yngre folkslag förföll trollens välde långsamt till ruin och isolering. De flesta kvarvarande trollkungadömen betraktar alla andra folkslag med häftig, orubblig fientlighet och klamrar sig bittert fast vid ruinerna av sin forna storhet. Bara Darkspear-stammens landsförvisade djungeltroll har valt en ny väg och anslutit sig till Horden tillsammans med orcher och taurer."}},faq={{q="Kan troll verkligen växa ut förlorade lemmar?",a="Ja. Trollens enastående fysiologi gör att de återhämtar sig från fysiska skador snabbare än de flesta andra dödliga folkslag. Med tiden kan ett troll till och med växa ut förlorade fingrar och hela lemmar på nytt, vilket gör dem ovanligt motståndskraftiga i strid.",al={"trollens läkning","trollens återväxt av lemmar","hur läker troll"}},{q="Vad är loa?",a="Loa är de uråldriga gudar som trollen dyrkar i nästan alla stammar. Många är mäktiga djurandar som trollen hedrar med offergåvor, meditation och rituell magi. Präster och skuggjägare åkallar loa för att få välsignelser, vägledning och förödande kraft i strid.",al={"vilka är loa","trollgudar","vad dyrkar troll"}},{q="Varför är de flesta troll fientliga mot spelare?",a="De flesta trollstammar, som Amani-skogstrollen och Gurubashi-djungeltrollen, har uråldriga, isolerade kulturer som hyser djupt hat mot främlingar. Århundraden av konflikter med folkslag som trängt in på deras marker har gjort dem ytterst beskyddande av sina förfäders territorier. De angriper inkräktare så fort de får syn på dem.",al={"varför är troll onda","fientliga troll","onda troll"}},{q="Hur anslöt sig Darkspear till Horden?",a="Darkspears djungeltroll drevs bort från sina förfäders marker och blev instängda på en ö under belägring av murlocer och sjöhäxor. Hövding Thrall och hans orchflotta ingrep och räddade Darkspear från utplåning. Av tacksamhet och gemensam nödvändighet svor deras hövding stammen trogen den nybildade Horden.",al={"varför är troll med i horden","darkspears ursprung i horden","thrall och troll"}},{q="Vad är voodoo?",a="Voodoo är en uråldrig lära om andlig och mörk magi som utövas av trollens häxdoktorer, skuggjägare och präster. Den väver samman kontakt med förfäderna, dyrkan av loa, förbannelser, hexor och kraftfulla örtblandningar för att skada fiender och stärka bundsförvanter.",al={"trollvoodoo","hur fungerar voodoo","häxdoktorsmagi"}},{q="Vilka klasser kan troll vara?",a="Troll tränar som krigare, jägare, lönnmördare, präster, shamaner, magiker och häxmästare.",al={"trollklasser","vilka klasser kan troll vara","kan troll vara häxmästare"}}},fp="5,266,21.429.0,20.319.0,18.600.0,40.133.0,13.263.0,39.277.0,37.303.0,15.245.0,28.80.0"}
P.entries["topic:twilight-s-hammer"] = {n="Twilight's Hammer",s="The Twilight's Hammer är en nihilistisk, apokalyptisk kult som är hängiven åt att väcka Old Gods och bringa Azeroth till sin undergång. Den var ursprungligen en orkklan under ogremagikern Cho'gall, men har utvecklats till en sluten, mångrasig orden som utför mörka ritualer över Kalimdor och Eastern Kingdoms.",h="The Twilight's Hammer är en nihilistisk, apokalyptisk kult som är hängiven åt att väcka Old Gods och bringa...",kw={"aku'mai","blackfathom deeps","cho'gall","kelris","the master's glaive","old gods","silithus","twilight's hammer","void"},ang={["class:Priest"]="Twilight's Hammer använder samma Void- och skuggmagi som skuggpräster åkallar. De tjänar som en mörk varning om vad som händer när gemenskapen med viskningarna överväldigar dödligas förstånd.",["class:Warlock"]="Twilight's Hammer hade ursprungligen band till Gul'dans Shadow Council, men övergav den demoniska behärskningen av felmagi till förmån för Old Gods ursprungliga vansinne. Därför är de oberäkneliga rivaler snarare än allierade.",["faction:Horde"]="Kulten är en skamlig kvarleva från Old Hordes mörkaste dagar. Thralls nya Horde har helt förkastat deras vansinne och avrättar aktivt alla fanatiker som försöker locka unga orker tillbaka till nihilismen.",["race:NightElf"]="När utomstående kultister vanhelgar heliga platser som Blackfathom Deeps och The Master's Glaive angriper de Kalimdors heliga nordliga marker både andligt och fysiskt."},sec={{t="Ursprung i skuggorna",b="The Twilight's Hammer började på Draenor som en orkklan i Old Horde, ledd av den tvåhövdade ogremagikern Cho'gall, en av Gul'dans främsta löjtnanter i Shadow Council. Under Cho'gall anammade klanen en dyster, apokalyptisk lära och kom att se Horde som enbart ett verktyg för förstörelse, ämnat att bringa alltings undergång."},{t="Ankomsten till Azeroth",b="När Twilight's Hammer korsade The Dark Portal under det första kriget fördjupades deras apokalyptiska fanatism ytterligare. I Azeroths jord kände kultisterna de äkta viskningarna från Old Gods, uråldriga fasor kedjade under marken. Blackhand tolererade deras oberäkneliga, ritualistiska beteende enbart eftersom Cho'gall höll deras blodtörst i schack. Han skickade dem tillsammans med Kilrogg Deadeyes Bleeding Hollow-klan i de första anfallen mot Stormwind Keep. Senare verkade klanen djupt inne i Grim Batol under det andra kriget och övervakade viktiga raffinaderier tills Gul'dans förräderi splittrade Horde. Trots att Orgrim Doomhammer beordrade att den förrädiska klanen skulle slaktas nära Tomb of Sargeras överlevde en kärna av fanatiker."},{t="En spridande cancersvulst",b="När kulten nådde Kalimdors bortglömda stränder förvandlades den från en splittrad orkklan till en hemlig, mångrasig konspiration. Twilight's Hammer lockar desillusionerade medlemmar från både Alliance och Horde och rekryterar varje själ som är tillräckligt bruten för att välkomna intet. I norra Kalimdor har kultister under Twilight Lord Kelris befäst sig i Blackfathom Deeps översvämmade salar, där de offrar offer till Aku'mai, en monstruös tjänare åt en Old God. Längre norrut i Darkshore stör deras utgrävare de väldiga, förstenade kvarlevorna vid The Master's Glaive. I Silithus södra öknar vakar läger av kåpklädda fanatiker över abyssala vindstenar och lyssnar efter uråldriga fasor som rör sig under sanden."}},faq={{q="Vad försöker Twilight's Hammer uppnå?",a="De vill utplåna allt liv och all ordning på Azeroth. Kulten söker varken erövring eller rikedom, utan ser intet som en helig välsignelse och arbetar aktivt för att befria de uråldriga Old Gods som är kedjade under världen.",al={"vad vill kultisterna","twilight's hammers mål","twilight hammers syfte"}},{q="Är de en orkklan eller en kult?",a="De började som en orkklan på Draenor under Cho'galls ledning. Efter flykten från det andra kriget övergav de klangränserna och blev en hemlig, mångrasig kult som värvar människor, nattalver, dvärgar och alla som är villiga att dyrka Void.",al={"är de orker","är twilight's hammer en klan","twilight hammers raser"}},{q="Vem leder Twilight's Hammer?",a="Kulten grundades och leddes av Cho'gall, en listig, tvåhövdad ogremagiker och tidigare lärjunge till Gul'dan. Lokala grenar lyder under regionala befälhavare, som Twilight Lord Kelris i Blackfathom Deeps.",al={"vem är twilight hammers ledare","twilight hammers ledare","cho'gall"}},{q="Varför är de i Blackfathom Deeps?",a="Under Twilight Lord Kelris ledning ockuperade kultisterna det sjunkna nattalvstemplet längs The Zoram Strand för att dyrka Aku'mai och offra offer åt henne. Hon är en uråldrig hydra med tre huvuden och tjänar en Old God.",al={"blackfathom-kultister","kelris bfd","vad gör de i ashenvale"}},{q="Vad gör de vid The Master's Glaive i Darkshore?",a="The Master's Glaive är en väldig glaive som sitter fast i skallen på en kolossal varelse. Ancient of Lore Onu säger att en mycket gammal jordens herre föll där. Kultister samlas där för att umgås med dess kvarvarande mörka energier och söka förebud om sina herrars uppvaknande.",al={"kultister vid master's glaive","twilight's hammer i darkshore"}},{q="Varför försökte Orgrim Doomhammer utplåna dem?",a="När det andra kriget rasade som värst övergav Cho'gall och Gul'dan Hordes marsch mot Lordaeron för att söka gudomlighet vid Tomb of Sargeras. Warchief Doomhammer rasade över förräderiet som kostade Horde segern och skickade lojala trupper för att slakta de avhoppade klanerna.",al={"doomhammer och twilight's hammer","förräderiet under andra kriget"}}},fx={["4ab30bd1"]={q="Varför är Twilight's Hammer fientliga mot utomstående?",a="Twilight's Hammer tjänar de gamla gudarna och eftersträvar Azeroths fullständiga förintelse. De ser alla utomstående civilisationer, både Alliansen, Horden och neutrala grupper, som hinder för sin apokalyptiska storplan. Alla som inte har svurit trohet till deras nihilistiska sak är fiender som ska elimineras eller offras i deras mörka ritualer.",al={"varför är twilight's hammer fientliga","twilight hammer attackerar vid syn","varför attackerar kultister mig"}},["301a24e8"]={q="Vem arbetar Twilight's Hammer åt?",a="Deras verkliga herrar är de gamla gudarna, uråldriga väsen av tomrum och skugga som fängslats djupt under Azeroth. Kulten försöker krossa deras fängelser och väcka väsen som C'Thun i Silithus. De vördar också dessa mörka herrars tjänare, som hydran Aku'mai i Blackfathom Deeps.",al={"vilka tjänar twilight hammer","twilight hammers herrar","vilka är twilight hammer allierade med"}},["23bd082e"]={q="Var uppstod Twilight's Hammer-klanen?",a="De började på Draenor som en orchklan i den gamla Horden, ledd av den tvåhövdade ogremagikern Cho'gall, en av Gul'dans främsta löjtnanter. Under hans ledning anammade klanen en apokalyptisk troslära och följde med resten av Horden genom The Dark Portal till Azeroth.",al={"twilight hammers ursprung","varifrån kom twilight hammer","twilight's hammers historia"}},["74c580c8"]={q="Varför heter de Twilight's Hammer?",a="Namnet går tillbaka till klanens tid i den gamla Horden under Cho'gall. Ursprunget finns inte dokumenterat, men det passar en troslära som vill leda världen mot dess undergång.",al={"varför kallas de twilight's hammer","vad betyder twilight hammer","ursprunget till namnet twilight hammer"}}},fp="17,170,17.346.0,18.644.0,18.668.0,48.189.0,31.238.0,32.204.0,34.210.0,56.253.0,47.249.0"}
P.entries["topic:varian-wrynn"] = {n="Varian Wrynn",s="Kung Varian Wrynn är den rättmätige härskaren över Kingdom of Stormwind, men är för närvarande försvunnen efter att ha försvunnit på väg till ett diplomatiskt toppmöte i Theramore. I hans frånvaro bär hans tioårige son Anduin kronan, med vägledning av Highlord Bolvar Fordragon och Lady Katrana Prestor.",h="Kung Varian Wrynn är den rättmätige härskaren över Kingdom of Stormwind, men är för närvarande försvunnen...",kw={"anduin","kung","försvunnen","stenhuggare","stormwind","theramore","varian","wrynn"},ang={["class:Warrior"]="Kung Varian, som tränats av veteraner bland riddarna och härdats av det första krigets fasor, beundras i hela Alliance som en formidabel krigare och en stridslysten ledare.",["faction:Alliance"]="Varians frånvaro lämnar Alliance utan sin starkaste sydliga monark och skapar ett politiskt maktvakuum som ger dissidenter mod och hotar gränssäkerheten från Westfall till Redridge.",["race:Human"]="För människorna i Stormwind är Varian kung Llanes älskade son, som återvände från exilen för att återuppbygga deras hem. Hans plötsliga försvinnande kastar en skugga av skräck över hela riket."},sec={{t="En barndom i aska",b="Varian var bara en pojke när det första kriget krossade hans liv. Han såg sin far, kung Llane Wrynn, dödas av lönnmördaren Garona Halforcen när Old Horde stormade huvudstaden. Den föräldralöse prinsen räddades av Anduin Lothar och flydde norrut med kungarikets överlevande till Southshore. I Capital City tog kung Terenas Menethil II emot Varian som en andra son. Den unge prinsen växte upp i exil tillsammans med prins Arthas Menethil och bar minnet av ett nedbränt hem med sig, tills Alliance of Lordaeron besegrade horden och återtog Stormwind."},{t="En besvärlig återuppbyggnad",b="Varian kröntes vid arton års ålder och tog sig an den enorma uppgiften att återuppbygga sitt förstörda kungarike. För att återställa huvudstaden anlitade han Stonemasons Guild under Edwin VanCleefs ledning. Men när det storslagna arbetet var färdigt vägrade det korrumperade House of Nobles att betala de utlovade lönerna, och stenhuggarna vägrade ge sig. Varian hamnade handfallen mellan den förhärdade adeln och de rasande hantverkarna. Tvisten utmynnade i våldsamma upplopp på Stormwinds gator."},{t="Den försvunne kungen",b="För att dämpa de pyrande spänningarna på andra sidan havet gav sig Varian nyligen av från Stormwind på en privat resa till Theramore Isle för fredssamtal arrangerade av Lady Jaina Proudmoore. Han nådde aldrig fram till toppmötet. Kungen försvann spårlöst under överfarten, vilket lämnade Stormwind sårbart, medan rykten om en konspiration spreds vid hovet och regentskapet hamnade i händerna på Highlord Bolvar."}},faq={{q="Var befinner sig kung Varian just nu?",a="Officiellt vet ingen i Stormwind. Varian försvann när han seglade över Great Sea till Theramore för hemliga diplomatiska samtal.",al={"var är varian","vart tog kungen vägen","lever varian","varians plats"}},{q="Vem styr Stormwind i hans ställe just nu?",a="Hans unge son, Anduin Wrynn, innehar tronen som barnkung. Eftersom Anduin bara är tio år gammal ligger den verkliga administrativa och militära makten hos Highlord Bolvar Fordragon, som fungerar som regent och påverkas starkt av den kungliga rådgivaren Lady Katrana Prestor.",al={"vem styr stormwind","vem är kung nu","stormwinds ledare"}},{q="Vad försvårade Varians återuppbyggnad av Stormwind?",a="När Stonemasons Guild hade byggt upp Stormwind igen vägrade House of Nobles att betala deras utlovade löner. Tvisten utmynnade i våldsamma upplopp på stadens gator, och de förvisade stenhuggarna blev senare Defias Brotherhood.",al={"varian och stenhuggarna","varians upplopp bland stenhuggarna","varian och adeln"}},{q="Varför reste Varian till Theramore?",a="Varian var på väg till Theramore Isle på inbjudan av Lady Jaina Proudmoore för att delta i ett diplomatiskt toppmöte på hög nivå, med målet att minska fientligheterna mellan Alliance och Thralls Horde.",al={"varför lämnade varian","toppmötet i theramore","varians fredssamtal"}},{q="Hur undkom Varian det första kriget?",a="Efter att kung Llane mördats och horden bränt Stormwind evakuerade överbefälhavaren Anduin Lothar prins Varian och de kvarvarande civila överlevande sjövägen. De seglade norrut till Lordaeron, där kung Terenas Menethil II tog den unge prinsen till sitt hov.",al={"varian i första kriget","unge varian","stormwinds fall och varian"}},{q="Vilken relation hade Varian till Arthas Menethil?",a="De växte upp som nära följeslagare och rivaler i Lordaeron medan Varian levde i exil. De båda prinsarna fäktades ofta tillsammans. Men Arthas väg mot vansinne, mordet på hans far Terenas och hans svek mot Lordaeron förvandlade den gamla vänskapen till bittert hat.",al={"kände varian arthas","varian och arthas","var arthas och varian vänner"}}},fx={["4f50c804"]={q="Vem är Varian Wrynn?",a="Kung Varian Wrynn är den rättmätige härskaren över kungariket Stormwind och arvtagare till huset Wrynn. Som pojke bevittnade han sitt kungarikes fall och mordet på sin far, kung Llane, under det första kriget. Han förvisades till Lordaeron och återvände flera år senare, efter att Alliansen återtagit hans hemland, och besteg tronen vid arton års ålder för att återuppbygga Stormwind. Nyligen försvann dock kungen under mystiska omständigheter på en diplomatisk resa, vilket lämnade kungariket i kaos.",al={"vem är varian","kung varian","stormwinds kung","vem är kung wrynn"}},["4a21f8ea"]={q="Vilka är Varian Wrynns bundsförvanter?",a="Varian står i hjärtat av den stora Alliansen. Bland hans närmaste rådgivare och beskyddare finns Highlord Bolvar Fordragon, som styr som regent under Varians frånvaro, och den kungliga rådgivaren Lady Katrana Prestor. Hans starkaste historiska band går till kungarikena i Alliansen av Lordaeron, som kung Terenas Menethil II knöt genom att fostra den unge Varian efter Stormwinds fall. Som kung av Stormwind för han befäl över dess arméer och riddare.",al={"varians bundsförvanter","vilka arbetar med varian","varian wrynns fraktion"}}},fp="12,201,16.519.0,22.441.0,17.358.1,31.131.0,47.224.0,47.235.1,34.189.0,36.264.0,52.289.0"}
P.entries["topic:venture-company"] = {n="Venture Company",s="Venture Company är ett ökänt hänsynslöst goblinkartell med fokus på aggressiv resursutvinning, tunga industrimaskiner och skogsavverkning. Kartellen är inte knuten till de stora goblinhamnarna som Booty Bay eller Ratchet, utan dagbrottsbryter och kalhugger områden i Kalimdor och Eastern Kingdoms utan hänsyn till lokalbefolkningen eller naturen.",h="Venture Company är ett ökänt hänsynslöst goblinkartell med fokus på aggressiv resursutvinning, tunga...",kw={"fizsprocket","gerenzo","puzik gallywix","razdunk","samophlange","skördare","the sludge fen","super reaper","venture company","windshear crag"},ang={["class:Druid"]="Deras omfattande kalhuggning i Stonetalon Mountains och industriella förorening av naturliga källor i Mulgore och The Barrens innebär en uppenbar och ohämmad skändning av landet.",["class:Rogue"]="Både Shattered Hand och SI:7 håller noga uppsikt över kartellens gifthandel, infiltrerar deras torn och saboterar deras högt uppsatta förmän för att komma åt deras dödliga kemiska blandningar.",["profession:Engineering"]="Kartellen tillverkar några av Azeroths bästa och mest avancerade skördare och mekaniska regulatorer, vilket gör deras ritningar till eftertraktade mål för företagsspioner.",["race:Tauren"]="Venture Company invaderade Mulgore heliga kullar utan tillstånd, förgiftade förfädernas vattenkällor och kalhögg skogen i trots mot Jordmodern."},sec={{t="Industriell plundring",b="Mogul Razdunk leder verksamheten på avstånd, och Venture Company följer en enkel företagsfilosofi: om något kan huggas ner, borras igenom eller sprängas ut ur ett berg ska det utnyttjas. Kartellen använder några av Azeroths mest avancerade tunga maskiner, däribland enorma skördare för timmer, borriggar och industriella raffinaderier. Till skillnad från traditionella handelshus som fokuserar på frakt eller detaljhandel specialiserar sig Venture Company på att med våld ta råvaror och struntar i fördrag, gränser och lokal självbestämmanderätt."},{t="Inkräktar i Kalimdor",b="Kartellens snabba expansion i Kalimdor har gjort den allmänt hatad. I Mulgore drev Supervisor Fizsprocket in borr- och gruvriggar i de östra klipporna trots att taurerna formellt nekat dem mineralrättigheter, och förorenade rena vattenkällor över slätterna. Längre norrut förvandlade företaget The Sludge Fen i The Barrens till ett kemiskt avlopp för att driva oljepumpar, samtidigt som de gjorde anspråk på Hordens tidigare Boulder Lode Mine och utförde vansinniga experiment med samophlanges och giftiga brygder. I Windshear Crag i Stonetalon Mountains har avverkning under den galne spetälskgnomen Gerenzo Wrenchwhistle ödelagt hela dungar med kolossala Super Reaper 6000-maskiner."},{t="Företagsrivalitet och ljusskygga kontrakt",b="Venture Company är avskytt även av andra gobliner. Baron Revilgaz i Booty Bay lägger ofta ut uppdrag om angrepp mot deras basläger och oljerigg vid Lake Nazferiti, både för att hindra deras territoriella intrång och stjäla deras toppmoderna bränsleregulatorer till skördarna. Tinkers' Union i Ratchet ägnar sig öppet åt företagsspionage för att stjäla ingenjörsritningar. Än värre är att SI:7 och Shattered Hand har upptäckt att företaget handlar med farliga alkemiska ämnen: de säljer Zanzils dödliga sinnesförändrande gifter till Defias-nekrmanser i Westfall och använder giftiga ångor för att föda upp muterade drönararbetare."}},faq={{q="Vem leder Venture Company?",a="Kartellens president är Mogul Razdunk, som på avstånd styr organisationens övergripande företagsverksamhet. De dagliga arbetena på platser runt om i Azeroth sköts av regionala uppsyningsmän, förmän och anlitade arbetsledare, som Supervisor Fizsprocket i Mulgore, Supervisor Lugwizzle vid The Sludge Fen och Gerenzo Wrenchwhistle i Stonetalon Mountains.",al={"venture company ledare","venture company chef","vem styr venture company","mogul razdunk"}},{q="Varför hatar Horden Venture Company?",a="Kartellen driver olagliga och aggressiva resursutvinningsplatser på Hordens förfäders marker. I Mulgore invaderade de de östra bergen utan tillstånd och förorenade taure­nernas heliga vattenkällor. I The Barrens tog de över Hordens Boulder Lode Mine och förvandlade The Sludge Fen till en giftig oljepöl.",al={"taurer venture company","varför horden hatar venture company","venture company mulgore"}},{q="Är de knutna till Steamwheedle Cartel eller Booty Bay?",a="Nej. Venture Company är en separat, rovlysten organisation. De är bittra företagsfiender till Steamwheedle Cartel. Baron Revilgaz i Booty Bay anlitar ofta legosoldater för att störa deras skogsavverkning i Stranglethorn Vale, och Sputtervalve i Ratchet skickar regelbundet agenter för att sabotera deras skördare och stjäla deras ritningar.",al={"är de steamwheedle","venture company booty bay","venture company ratchet"}},{q="Varför leder en spetälsk gnom verksamheten i Windshear Crag?",a="Venture Company anställde Gerenzo Wrenchwhistle för hans hänsynslösa mekaniska genialitet och lät honom konstruera den enorma timmerskördaren Super Reaper 6000. Anställningen väckte ramaskri bland kartellens gobliningenjörer, som Ziz Fizziks, och retade till och med upp handelsfurstarna i Undermine, som ogillade att Razdunk umgicks med den utstötta gnomen.",al={"gerenzo wrenchwhistle","gnom i stonetalon","varför spetälsk gnom venture company"}},{q="Vad gör Venture Company i Westfall?",a="Venture Company hade ett olagligt handelsavtal med Defias Brotherhood. De skaffade Zanzilli-gifter och sålde blandningen till Defias-agenten Klaven Mortwake i Westfall, som använde de giftiga brygderna för att skapa tanklösa Defias-drönare liknande arbetarna i Venture Companys verksamheter.",al={"venture company westfall","klaven mortwake venture company","venture company defias"}},{q="Vad produceras vid The Sludge Fen?",a="Kartellen byggde en industriell borrigg direkt ovanpå det som en gång var en klar naturlig källa och pumpar upp och raffinerar olja samtidigt som den dumpar giftigt slam över norra The Barrens. Förutom olja utför forskare där tester på avancerade mekaniska samophlanges och framställer giftiga blandningar.",al={"olja sludge fen","venture companys oljerigg i barrens","samophlange sludge fen"}}},fx={f7d6a0aa={q="Vad är Venture Company?",a="Venture Company är en hänsynslös, goblinledd kartell som ägnar sig åt att plundra Azeroths naturresurser för maximal vinst. De specialiserar sig på tunga maskiner, gruvdrift och kalhuggning, och deras filosofi är enkel: kan något grävas upp, huggas ner eller sprängas ut ur ett berg, så gör de det. De verkar helt utanför lokala lagar och traditionell etik och använder skördare, borrmaskiner och beväpnade vakter för att utvinna rikedomar ur vildmarkens gränstrakter.",al={"vilka är venture co","vad är venture company","venture co:s historia"}},["36300444"]={q="Varför är Venture Company fientliga mot resande?",a="Venture Company bedriver olaglig och aggressiv resursutvinning på omstridda och självständiga länders mark, från Mulgore heliga kullar till Stonetalon skogar. Eftersom de regelbundet inkräktar, stjäl markanspråk och slår ut konkurrenter är deras anläggningar kraftigt befästa. Deras förmän ser varje utomstående som en industrispion, en rivaliserande markanspråkare eller en hämndlysten lokalbo som vill sabotera deras maskiner, och beordrar sina vakter att skjuta först.",al={"varför attackerar venture co","venture co attackerar","varför är venture company fientliga"}},["48d27ccb"]={q="Vilka är Venture Company allierade med?",a="Venture Company arbetar främst för egen vinning, men sluter ofta tvivelaktiga avtal med utomstående fraktioner när det finns guld att tjäna. De har etablerat hemlig handel med Defias Brotherhood och säljer dem alkemiska blandningar och giftiga brygder framställda av Zanzil. Bortsett från sådana legoknektsaffärer har de få vänner. De trampar regelbundet neutrala karteller som Steamwheedle Cartel på tårna och väcker handelsfurstarnas vrede i Undermine.",al={"venture companys allierade","vilka samarbetar venture company med","venture companys partnerskap"}}},fp="15,297,18.336.0,23.645.1,39.564.2,30.289.0,44.300.0,62.294.0,58.278.0,46.260.1,41.255.0"}
P.entries["topic:war-of-the-ancients"] = {n="De äldstes krig",s="För tiotusen år sedan slet drottning Azsharas och hennes Highbornes vårdslösa trolldom upp en portal genom Well of Eternity och släppte lös den demoniska Burning Legion över Azeroth. Under ledning av den unge druiden Malfurion Stormrage, hans bror Illidan och prästinnan Tyrande Whisperwind drev en desperat allians av nattalver, drakar och uråldriga skogssemigudar tillbaka inkräktarna. Förstörelsen av Well of Eternity utlöste Great Sundering, som våldsamt splittrade den uråldriga kontinenten Kalimdor och för alltid förändrade världens utseende.",h="För tiotusen år sedan slet drottning Azsharas och hennes Highbornes vårdslösa trolldom upp en portal genom...",kw={"azshara","burning legion","cenarius","highborne","malfurion","sargeras","great sundering","tyrande","de äldstes krig","well of eternity"},ang={["class:Druid"]="Konflikten markerar födelsen av dödlig druidism, då Malfurion Stormrage lärde sig vildmarkens vägar av Cenarius och visade att naturens kraft kunde besegra kosmisk undergång.",["class:Mage"]="Highbornes vårdslösa arrogans under kriget är Azeroths främsta historiska varning för de katastrofala farorna med okontrollerad användning av arkanisk magi.",["class:Priest"]="Tyrande Whisperwinds mästerskap över Elunes nåd under kriget lyfte Månens prästerskap till en central roll i nattalvernas militära och civila ledning.",["race:NightElf"]="Kriget formade varje aspekt av det moderna Kaldorei-samhället och förklarar deras djupa misstro mot arkanisk magi, vördnad för Cenarius och det bestående ledarskapet hos Malfurion och Tyrande.",["race:Tauren"]="Tauren som vördar Cenarius och vildmarkens halvgudar minns att samma skogsandar kämpade mot Legion tillsammans med nattalverna för tiotusen år sedan."},sec={{t="Highbornes dårskap",b="När det uråldriga Kaldorei-imperiet stod på sin höjdpunkt hämtade drottning Azshara och hennes elitkast av trollkarlar, Highborne, obevekligt kraft ur Well of Eternitys väldiga arkaniska djup. Deras vårdslösa manipulation sände enorma vågor genom Great Dark Beyond och lockade till sig Sargeras, Burning Legions herre. Azshara och hennes rådgivare Xavius tjusades av löften om oöverträffad makt och fulländning och öppnade en transdimensionell rift i Well. Legioner av felhundar, felvakter, doomvakter och monstruösa befälhavare strömmade in i huvudstaden Zin-Azshari, slaktade alla som inte var Highborne och inledde sitt korståg för att utrota allt liv i världen."},{t="Kaldorei-motståndet",b="Förfärade över slakten samlades nattalver utanför Highborne-kasten för att göra motstånd. Motståndet leddes av enastående hjältar: den första dödliga druiden Malfurion Stormrage, Elunes hängivna prästinna Tyrande Whisperwind och Malfurions begåvade bror Illidan. Tillsammans samlade de vanliga nattalver till en desperat frontlinje mot Legionens anstormning."},{t="Segerns pris",b="Kriget växte till proportioner som hotade att krossa världen när halvguden Cenarius samlade de uråldriga vildgudarna och drakflygarna till striden. Fast beslutna att hindra Sargeras från att själv beträda Azeroth gjorde Malfurion och motståndsrörelsen ett desperat försök att störta portalen ovanför Well of Eternity. Deras vågade plan lyckades kasta den demoniska hären tillbaka in i Twisting Nether, men påfrestningen blev för stor. Well imploderade våldsamt och utlöste Great Sundering, som splittrade Kalimdor i separata kontinenter och översvämmade världens mitt. Great Sea uppstod och Kaldorei-kulturen förändrades för alltid."}},faq={{q="Vad orsakade De äldstes krig?",a="Drottning Azshara och hennes Highborne-trollkarlar experimenterade obevekligt med de arkaniska energierna i Well of Eternity. Deras besvärjelser sände vågor genom kosmos som lockade till sig den mörke titanen Sargeras. Han övertalade Highborne att öppna en port i Well så att Burning Legion kunde ta sig in i Azeroth.",al={"varför började kriget","vem orsakade de äldstes krig","portalen i well of eternity"}},{q="Vad var Great Sundering?",a="Great Sundering var katastrofen som avslutade kriget. För att hindra Sargeras från att ta sig in i världen störtade motståndsrörelsen portalen inne i Well of Eternity. Motreaktionen fick Well att implodera våldsamt och slet sönder superkontinenten Kalimdor till separata landmassor. Great Sea bildades.",al={"vad är great sundering","hur splittrades kalimdor","explosionen i well of eternity"}},{q="Vem ledde de dödliga styrkorna mot Legion?",a="Den unge druiden Malfurion Stormrage, hans bror Illidan och prästinnan Tyrande Whisperwind samlade nattalverna som kämpade mot Azshara och Legion. Halvguden Cenarius förde samtidigt vildmarkens uråldriga andar till deras sida.",al={"vem ledde motståndet","kaldorei-motståndets ledare"}},{q="Kämpade andra raser tillsammans med nattalverna?",a="Ja. De mäktiga drakflygarna anslöt sig till kampen, och skogssemiguden Cenarius ledde sina vilda fränder i strid mot den demoniska invasionen tillsammans med nattalverna.",al={"tauren i de äldstes krig","vem hjälpte nattalverna"}},{q="Vad hände med drottning Azshara under kriget?",a="Azshara stannade i sitt palats i Zin-Azshari ända till slutet, besatt av att föra Sargeras till Azeroth. När Well of Eternity imploderade och haven svalde huvudstaden sjönk drottningen och hennes överlevande Highborne-lojalister ner i de virvlande djupen.",al={"var finns azshara","dog drottning azshara"}},{q="Varför misstror nattalver arkanisk magi i dag?",a="Kaldorei såg med egna ögon hur Highbornes omåttliga törst efter arkanisk magi tillkallade Burning Legion och ödelade det uråldriga Kalimdor. Efteråt förbjöd nattalverna strikt arkanisk trolldom och vände sig i stället till druidism och tron på Elune för att skydda sina marker.",al={"varför hatar nattalver magiker","kaldoreis magiförbud"}}},fx={c481acb5={q="Vad var War of the Ancients?",a="War of the Ancients var Azeroths första stora krig mot den demoniska Burning Legion och utkämpades för ungefär tiotusen år sedan. Förblindade av löften om gudomlig makt kastade drottning Azshara och hennes Highborne besvärjelser genom Well of Eternity för att föra in Sargeras och hans demoniska legioner i världen. Nattalvernas motstånd, tillsammans med de tidiga dödliga raserna, drakflyglarna och vildgudarna, kämpade desperat för att hejda invasionen. Kriget kulminerade i att Well of Eternity förstördes och världen slets itu i Great Sundering.",al={"vad är war of the ancients","war of the ancients förklarat","första invasionen från legion"}},["9e83d11f"]={q="Varför kallas det War of the Ancients?",a="Kriget fick sitt namn både av den uråldriga tidsålder då det utkämpades, tiotusen år före vår tid, och av de Ancients avgörande roll. Halvgudar och vildgudar som Cenarius tågade tillsammans med de uråldriga drakflyglarna och dödliga försvarare för att rädda Azeroth från demonisk förintelse.",al={"varför kallas det war of the ancients","betydelsen av namnet war of the ancients","namnet war of the ancients"}}},fp="19,302,21.530.0,23.352.0,20.554.0,36.259.0,29.276.0,45.211.0,48.149.0,46.257.0,52.239.0"}
P.entries["topic:warlock"] = {n="Warlock",s="Warlocks är magiker som sluter avtal med mörka krafter och behärskar demoner, försvagande förbannelser samt förödande eld- och skuggmagi. Nästan alla civiliserade samhällen på Azeroth fruktar och misstror dem djupt, men några använder dessa förbjudna konster för att försvara sina fraktioner och vänder Burning Legions vapen mot dess egna tjänare.",h="Warlocks är magiker som sluter avtal med mörka krafter och behärskar demoner, försvagande förbannelser samt...",kw={"affliction","demonology","destruction","fel","felhunter","gul'dan","imp","shadow council","succubus","twisting nether","voidwalker","warlock"},ang={["class:Mage"]="Mages ser på warlocks med starkt förakt och rädsla. De betraktar dem som odisciplinerade trollkarlar vars vårdslösa affärer med Nether utsätter allt dödligt liv för fara.",["class:Paladin"]="De som vördar Holy Light betraktar demonisk åkallan som avskyvärd kätteri och håller utövande warlocks under uppsikt med öppet fientliga blickar.",["class:Shaman"]="Shamaner avskyr warlockmagi mer än allt annat och minns hur Gul'dans felmagi skar av deras förfäders band till andarna och dödade Draenors land.",["race:Orc"]="För orker bär demonologi på den bittra skammen efter Old Hordes blodsförbannelse, även om några bevarar konsterna för att överleva i en fientlig värld.",["race:Troll"]="Darkspear-warlocks börjar tillsammans med orkiska lärlingar i Valley of Trials och granskas lika misstänksamt som alla andra som brukar felmagi under Thralls Horde."},sec={{t="Förbjudna konster",b="Där vanliga magiker ser fördärv och undergång ser warlocks möjligheter. De segrar genom beräknad grymhet och slår till på avstånd, höljda i skugga och eld. Genom att suga åt sig sina fienders livskraft och själar får warlocks kraft till sina mest katastrofala ritualer. De låter svavelregn falla från himlen och krossar sinnen med plågsamma förbannelser. Eftersom de bara bär enkla tygkläder och har liten fysisk motståndskraft förlitar de sig på åkallade fasor som avleder faran, och offrar villigt demoniska tjänare för att själva överleva."},{t="Demonisk träldom",b="En warlocks makt över Twisting Nether börjar med små förhandlingar och växer till järnhård dominans. Nybörjare lär sig befalla små imps att kasta eld, men när utövarens mörka kunskap fördjupas binder de långt farligare väsen: voidwalkers som slits ur skuggdjupen för att ta emot fysiska slag, förföriska succubi som kan förleda fiendens sinnen och glupska felhunters som slukar magisk energi. Varje åkallan kräver farlig rituell koncentration, för Netherns invånare prövar ständigt sina mästare för att hitta minsta tecken på svaghet."},{t="Ett arv av förödelse",b="Orkernas demonologis rötter går tillbaka till Draenor, där demonherren Kil'jaeden förförde Gul'dan med löftet om oöverträffad makt. Gul'dan grundade det hemlighetsfulla Shadow Council och omvandlade många shamaner till mästare i felmagi. Den utbredda användningen av demonisk magi förvandlade Draenors bördiga slätter till en karg, röd ödemark och förebådade Old Hordes invasion genom Dark Portal. I människornas länder förbjöd Kirin Tor demonologi och jagade olovliga åkallan, men ambitiösa magiker föll regelbundet för lockelsen i obändigt trolldomskunnande."},{t="Tolererade utstötta",b="I modern tid balanserar warlocks på en knivsegg mellan nytta och avrättning. I Stormwind samlas utövare i hemlighet i dystra källarkrogar, långt från Cathedral of Lights vaksamma blick. I Orgrimmar håller de till i de skuggiga ravinerna i Cleft of Shadow och övervakas av Thralls shamanistiska styre. Deras metoder väcker avsky, men varken Alliance eller Horde kan helt bortse från den förödande fördel warlockmagi ger på ett fientligt slagfält."}},faq={{q="Vad skiljer en warlock från en mage?",a="Mages utnyttjar den ordnade strukturen hos arkan magi för att manipulera eld, frost och energi. Warlocks struntar i säkra gränser och kastar sig rakt in i kaotisk felmagi, skuggmagi och demonisk åkallan. Många warlocks började sin bana som mages, men tröttnade på akademiska begränsningar och sökte förbjudna genvägar till överväldigande makt.",al={"warlock jämfört med mage","skillnad mellan warlock och mage","mage eller warlock"}},{q="Är alla warlocks onda?",a="Alla warlocks är inte onda av naturen, men deras magi är farlig och fördärvande. Många sjunker ner i vansinne eller ansluter sig till demoniska kulter, men warlocks som spelarkaraktärer svär ofta trohet till sin fraktion och vänder mörk trolldom, stulna själar och bundna demoner mot yttre hot som Scourge eller Burning Legion.",al={"är warlocks onda","kan warlocks vara goda","varför tillåter alliance warlocks"}},{q="Hur åkallar och kontrollerar warlocks demoner?",a="Warlocks använder ritualcirklar, mörka besvärjelser och själskraft för att dra varelser ur Twisting Nether. När demonen väl har åkallats måste den kuvas och bindas till magikerns vilja genom ren mental dominans. Om en warlocks koncentration brister slaktar demonen gärna sin mästare.",al={"hur fungerar warlocks husdjur","lore om demonisk åkallan","binda demoner"}},{q="Varifrån kommer orkiska warlocks?",a="Orkiska warlocks uppstod på Draenor när Kil'jaeden manipulerade Gul'dan att överge shamanismen för demonisk trolldom. Gul'dan bildade Shadow Council och tränade andra orker. De spred felmägi över sitt hemland tills Draenors jord vissnade och dog.",al={"hur blev orker warlocks","gul'dan och warlocks","orkisk felmagis ursprung"}},{q="Varför tolererar Alliance och Horde warlocks i sina städer?",a="Ingen av fraktionerna litar egentligen på dem. I Stormwind och Ironforge utövar warlocks sin magi i hemliga källare och bortglömda tunnlar för att undvika folkets vrede. I Orgrimmar hålls de avskilda i Cleft of Shadow. Ledarna tolererar dem enbart för att deras skräckinjagande förbannelser och åkallan bevisligen är effektiva vapen i krig.",al={"varför tillåts warlocks","är warlocks lagliga","warlocks laglighet"}},{q="Vad används soul shards till?",a="Warlocks dränerar besegrade fienders levande essens för att skapa kristalliserade soul shards. Dessa själfragment fungerar som kraftfulla batterier och ger råenergin som behövs för att kringgå magins naturlagar, åkalla monstruösa demoner och kasta sina mest förödande besvärjelser.",al={"varför tar warlocks själar","lore om soul shards","skörda själar"}},{q="Vilka raser kan vara warlocks?",a="Bland Alliance tränar människor och gnomer till warlocks, och bland Horde gör orker, troll och Forsaken det. Dvärgar, nattalver, tauren och Skyborne gör det inte. Överallt tolereras warlocks, men ingen litar på dem.",al={"vem kan bli warlock","warlockraser","kan troll vara warlocks","troll-warlock"}}},fp="7,204,14.431.0,17.443.0,16.483.0,17.429.0,43.258.0,22.278.0,42.241.0,33.238.0,64.282.0,30.219.0,28.223.0"}
P.entries["topic:warrior"] = {n="Warrior",s="Krigare är Azeroths främsta frontkämpar och behärskar tung plåtrustning, sköldar och nästan alla sorters stridsvapen. De driver sina förödande slag med ren stridsvrede och stormar in i stridens hetaste skede för att försvara svagare allierade eller slå sig genom fiendens led. De finns bland alla raser och civilisationer, som allt från ståndaktiga stadsvakter och kungliga mästare till kringvandrande legosoldater.",h="Krigare är Azeroths främsta frontkämpar och behärskar tung plåtrustning, sköldar och nästan alla sorters...",kw={"vapenmästare","bärsärk","furie","närstrid","plåt","skydd","vrede","sköld","förtrupp","krigare"},ang={["class:Warrior"]="Varje strid prövar din uthållighet och ditt mod; genom att förvandla smärtan från inkommande slag till ren vrede styr du frontlinjen.",["faction:Alliance"]="Alliansens fotsoldater och riddare utgör den försvarande förtruppen som skyddar mänskliga kungariken, dvärgarnas bergafästen och alvernas skogar.",["faction:Horde"]="För Horden är stridskonst en livsstil, och gryntstormtrupper och taurenkrigare leder varje framryckning för att ta nytt land.",["profession:Blacksmithing"]="Krigare förlitar sig helt på smeder som hamrar fram den tunga plåtrustningen, de stadiga bucklarna och de vässade klingor som behövs för att överleva dödlig strid."},sec={{t="Mästare på stål och sköld",b="Krigare förlitar sig varken på gudomliga böner eller magiska besvärjelser. Deras kraft kommer helt från fysisk uthållighet, disciplin på slagfältet och ingående vapenkunskap. Klädda i den tyngsta plåtrustningen styr de frontlinjen. Vissa strider bakom väldiga sköldar, står emot hårda angrepp och avleder faran från magiker och bågskyttar. Andra går till anfall med tvåhandsspjut, yxor och bredsvärd, eller ger sig in i närstrid med ett vapen i vardera handen för att hugga genom hela formationer."},{t="Stridsvredens kraft",b="I stridens hetta väcker smärta och blod krigarens inre eld. Den kallas helt enkelt vrede och växer när krigare utdelar och tar emot stryk. I stället för att ge vika för utmattning eller blödande sår riktar erfarna kämpar sin stridsvrede mot benkrossande slag, svepande virvlar av stål och dånande stridsrop som stärker närstående kamrater och krossar fiendens stridsmoral."},{t="En allmän tradition",b="Till skillnad från klasser som är knutna till särskilda trosläror eller elementära beskyddare finns krigartraditionen bland alla Azeroths raser. Stormwind förlitar sig på sina disciplinerade riddare och fotsoldater, Ironforge samlar sitt härdade bergsvakt och Horden sluter upp bakom orciska svärdsmästare, taurenkrigare och Forsakens dödsvakter. Oavsett om de drivs av ära, försvar av sitt land eller kall hård valuta utgör de som tar till vapen ryggraden i varje stående armé."}},faq={{q="Vad ger en krigare kraft om den inte använder magi?",a="Krigare förlitar sig på stridskunskap, taktisk träning och vrede. Vreden växer direkt ur stridens sammanstötningar, både när de träffar fiender och när de tar emot slag. Detta rus av stridsadrenalin driver deras mest förödande manövrer, som svepande vapenslag, bedövande sköldstötar och skrämmande rop.",al={"hur strider krigare","krigarens resurs","vad är vrede"}},{q="Vilka raser kan bli krigare?",a="Alla spelbara raser i Azeroth kan bli krigare. Alla dödliga kulturer behöver tungt rustade frontsoldater, från de allvarsamma dvärgbeskyddarna i Khaz Modan till de vilda orciska stormtrupperna i Durotar.",al={"vem kan bli krigare","krigarras","kan alla raser bli krigare"}},{q="Vilken roll har krigare i en stridsgrupp?",a="Krigare leder vanligtvis från fronten. Ståndaktiga skyddskrigare använder sköldar och plåtrustning för att ta emot stryk och hålla farliga fienders uppmärksamhet på sig. Vapenmästare och furiekrigare går i stället till anfall med förkrossande tvåhandsvapen eller klingor i båda händerna och övermannar fiender med brutal fysisk skada.",al={"krigarens roll","är krigare stridsvagnar","vapenmästare, furie eller skydd"}},{q="Vilka vapen kan krigare använda?",a="Krigare behärskar nästan alla vapen som används i dödlig strid. De kan använda svärd, klubbor, yxor, spjut, dolkar och stavar, med en eller två händer, samt tunga sköldar och avståndsvapen som bågar, gevär och armborst.",al={"krigarvapen","kan krigare använda bågar","vad kan krigare bära"}},{q="Vilka är några berömda krigare i Azeroths historia?",a="Bland berömda krigare finns Lord Anduin Lothar, Stormwinds mästare och högste befälhavare för Alliansen av Lordaeron; Grommash Hellscream, hövding för Warsong-klanen; och Cairne Bloodhoof, högöverhuvud för de förenade taurenstammarna.",al={"berömda krigare","legendariska krigare","vilka är krigarnas hjältar"}},{q="Var får nya krigare sin formella träning?",a="Krigare tränar där soldater samlas. Mänskliga rekryter övar i Northshire Abbey, dvärgar och gnomer lär sig vid Anvilmar i Coldridge Valley, nattalver tränar i Shadowglen, orcer och troll övar i Valley of Trials, Forsaken-krigare anmäler sig vid kasernen i Deathknell och Skyborne börjar på Zephras Isle.",al={"krigartränare","var lär sig krigare","krigartränarnas platser"}}},fx={["2a49f247"]={q="Vad är en krigare?",a="Krigare är Azeroths främsta frontkämpar och förlitar sig på ren fysisk styrka, vapenkunskap och tung rustning i stället för mystiska konster. De kommer från alla kulturer och bakgrunder och tjänstgör som ståndaktiga stadsvakter, fruktade berserker, legosoldater och erfarna befälhavare. Utrustade med sköldar och ett stort urval vapen rusar krigare rakt in i striden för att dra på sig fiendens vrede och skydda sina skörare följeslagare från skada.",al={"vad är en krigare i historien","krigarens identitet i historien","vilka är krigare"}},["2e549509"]={q="Vad innebär det att följa krigarens väg?",a="Att välja ett liv som krigare innebär att ägna dig åt ständig träning, disciplin och kompromisslös stridskonst. Du går ut på slagfältet utan besvärjelser som skydd och sätter all din tillit till tung plåtrustning, ditt valda stål och dina instinkter. Oavsett om du söker ära, rikedom som legosoldat eller vill försvara ditt folk mot hot vid horisonten är du muren som möter faran direkt och omvandlar rå stridsvrede till avgörande hugg.",al={"att bli krigare","vad innebär det att vara krigare","krigarens liv"}}},fp="7,292,27.348.0,24.257.0,21.356.0,47.185.0,31.179.0,46.263.0,40.208.0,50.237.0,52.320.0"}
P.entries["topic:warsong-clan"] = {n="Warsong-klanen",s="Warsong-klanen är en av orchernas mest våldsamma och legendariska stridsstyrkor och leddes tidigare av den vördnadsvärde hövdingen Grommash Hellscream. Efter att ha överlevt exil, interneringsläger och demonisk förvridning verkar klanen nu främst i Ashenvale som Warsong Outriders. De säkrar timmer åt den unga Horden med hård hand och drabbar ständigt samman med nattalverna.",h="Warsong-klanen är en av orchernas mest våldsamma och legendariska stridsstyrkor och leddes tidigare av den...",kw={"ashenvale","cenarius","grommash","hellscream","mannoroth","outriders","splintertree","warsong"},ang={["faction:Alliance"]="Warsong förkroppsligar orchernas obevekliga aggression och visar många i Alliansen att fred mellan de två fraktionerna förblir omöjlig så länge deras yxor svingas i Ashenvale.",["faction:Horde"]="Utan timret som Warsong Outriders hugger i Ashenvale skulle den Nya Horden sakna råmaterial för att befästa sina bosättningar och utöka sina områden i Kalimdor.",["race:NightElf"]="Nattalverna hyser ett intensivt hat mot Warsong, inte bara för att de skövlar heliga skogar i Ashenvale, utan också för att de urskillningslöst slaktade halvguden Cenarius.",["race:Orc"]="Warsong står för både orcherfolkets största skam och främsta försoning: klanen var först med att dricka Mannoroths blod, men dess hövding dog också för att bryta demonens grepp om alla orcher."},sec={{t="Ett trotsigt arv",b="Långt innan de tog sig till Azeroth byggde Warsong upp sitt rykte på Draenors öppna slätter med rörlig krigföring till varg. Efter Hordens nederlag undvek Warsong tillfångatagande medan andra orcher tynade bort i Alliansens interneringsläger. De strövade genom vildmarken och höll fast vid sin krigaranda tills Thrall förenade sig med Hellscream för att skapa den Nya Horden."},{t="Blod och försoning",b="När de anlände till Kalimdor under det tredje kriget beordrade Thrall Hellscream och hans klan till Ashenvale för att hugga timmer och bygga en utpost. Inkräktarna väckte nattalvernas och skogshalvguden Cenarius vrede. Warsong drevs till bristningsgränsen och föll åter för demonfursten Mannoroths demonblod för att segra. I sin vansinniga felkorruption dödade de Cenarius. Thrall och hans allierade lyckades befria Hellscream från förbannelsen. Det ledde fram till en ödesdiger slutstrid där Grom gav sitt liv för att förgöra Mannoroth. Hans heroiska offer bröt demonblodets förbannelse för alltid och befäste Warsong-klanens plats i Hordens historia."},{t="Kriget om Ashenvale",b="I dag fortsätter klanen Grommashs uppdrag under Warsong Outriders baner. Från fästen som Splintertree Post och aktiva timmerläger hugger de timmer som är avgörande för att bygga den unga Hordens nation i Durotars torra ödemarker. Deras närvaro har utlöst ett bittert territoriellt krig med nattalvernas Silverwing Sentinels. Med sitt förfäders arv som drivkraft visar Warsong inga tecken på att ge upp Warsong Gulch. De tränger allt djupare in i den uråldriga skogen trots ständiga bakhåll."}},faq={{q="Vem leder Warsong-klanen just nu?",a="Efter Grommash Hellscreams död i slutet av det tredje kriget införlivades större delen av Warsong-klanen i Thralls Nya Hord. Deras aktiva styrkor, särskilt Warsong Outriders i Ashenvale, lyder under lokala befälhavare och överhuvudet, krigshövding Thrall.",al={"warsong-ledare","vem är warsongs hövding","warsongs nuvarande hövding"}},{q="Varför hugger Warsong timmer i Ashenvale?",a="Den Nya Horden håller till på Durotars och The Barrens torra slätter, där det finns ont om timmer. Warsong skickades till Ashenvales rika skogar för att samla virke. Det behövs för att bygga städer som Orgrimmar, underhålla militära befästningar och försörja den växande Horden.",al={"varför hugga timmer i ashenvale","warsongs timmer","orcher hugger träd i ashenvale"}},{q="Hur dödade Warsong Cenarius?",a="Under det tredje kriget ledde halvguden Cenarius nattalvernas hårda försvar av Ashenvale och drev Warsong till desperation. Klanen drack ur en pöl som förorenats av demonfursten Mannoroths blod. De förvandlades till demonvansinniga kaosorcher, vars förstärkta raseri var nog för att övermanna och döda Cenarius.",al={"cenarius död","vem dödade cenarius","warsong mot cenarius"}},{q="Hur undkom Warsong interneringslägren efter det andra kriget?",a="Till skillnad från många orc-klaner som tillfångatogs när det andra kriget tog slut undvek Grommash Hellscream och Warsong att bli tillfångatagna av Alliansen. De gömde sig i Lordaerons avlägsna vildmark. De bedrev gerillakrig och höll fast vid sin krigaranda tills Thrall fann dem.",al={"warsongs interneringsläger","groms flykt","warsongs flykt"}},{q="Vad är Warsong Gulch?",a="Warsong Gulch är en kanjondal i södra Ashenvale där Warsong Outriders drabbar samman direkt med nattalvernas Silverwing Sentinels. Outriders kämpar för att säkra sin timmerverksamhet, medan Sentinels försöker driva bort orcherna från sin heliga skog för gott.",al={"warsong gulchs historia","vad är warsong gulch","warsong-slagfält"}},{q="Vem var Grommash Hellscream?",a="Grommash ”Grom” Hellscream var Warsong-klanens legendariske hövding och mentor åt Thrall. Han var den första orchen som drack demonblod på Draenor, men han sonade till slut sina handlingar och befriade alla orcher från demonernas herravälde genom att döda demonfursten Mannoroth. Han offrade sitt liv för det.",al={"vem är grom","grom hellscream","grommash"}}},fx={ab40120e={q="Vad är Warsong-klanen?",a="Warsong-klanen är en stridslysten orcisk klan, känd för sin aggressivitet och sina rörliga vargryttare. Klanen leddes länge av den legendariske hövdingen Grom Hellscream och tjänar nu som en viktig del av Thralls Horde. Den leder avverkning och militära fälttåg i Ashenvales täta skogar.",al={"vilka är warsong-klanen","vilka är warsong","information om warsong-klanen"}},b8b233bd={q="Var kom Warsong-klanen ifrån?",a="Warsong-klanen kom ursprungligen från Draenors slätter, där den blev känd för sina stridslystna, rörliga vargryttare. Klanen tog sig till Azeroth med Horde under Grom Hellscreams ledning. Efter att ha undkommit människornas interneringsläger efter Second War följde den senare Thrall över Great Sea till Kalimdor.",al={"warsong-klanens historia","warsongs ursprung","var kommer warsong ifrån"}},f1dd8797={q="Vilka är Warsong-klanen allierad med?",a="Warsong-klanen har svurit full trohet till Thralls New Horde. De strider sida vid sida med sina orciska fränder, Darkspear-trollen, tauren från Mulgore och de nyligen upptagna Forsaken. De skördar livsviktigt timmer till Hordes växande bosättningar i Durotar och The Barrens.",al={"warsongs allierade","vem strider warsong för","warsongs fraktion"}},["5b3f6a6c"]={q="Varför är Warsong-klanen fientlig mot alliansens resenärer?",a="Som en central militärstyrka i Horde betraktar Warsong-klanen alliansens medlemmar som dödsfiender. Deras djupt rotade hat drivs på ytterligare i Ashenvale, där nattalvernas Silverwing Sentinels och deras allierade hårt bekämpar klanens aggressiva kalhuggning av de heliga, uråldriga skogarna.",al={"varför anfaller warsong","varför är warsong fientliga","är warsong fiender"}}},fp="12,283,20.345.0,20.563.0,21.372.0,37.222.0,41.244.0,34.299.0,69.208.0,22.259.0,28.261.0"}
P.entries["topic:westfall-brigade"] = {n="People's Militia",s="I Westfall håller People's Militia stånd mot Defias Brotherhood. Gryan Stoutmantle grundade frivilligstyrkan vid Sentinel Hill efter att Stormwind dragit tillbaka sina trupper. Tillsammans med lokala bönder och tillresta äventyrare försvarar de området mot banditer.",h="I Westfall håller People's Militia stånd mot Defias Brotherhood.",kw={"defias brotherhood","edwin vancleef","gryan stoutmantle","moonbrook","people's militia","sentinel hill","sentinel tower","westfalls brigad"},ang={["class:Warrior"]="Som krigare ser du Gryan Stoutmantle och hans beskyddare leda från fronten. De får klara sig med slitna klingor och provisoriska rustningar mot övermäktiga odds.",["faction:Alliance"]="Som hjälte i Alliansen ser du hur krisen i Westfall blottlägger farliga sprickor i kungariket och visar hur bräcklig freden är i dess kärnland.",["race:Human"]="Som människa ser du hur Stormwinds folk på landsbygden försvarar sina egna hem när det kungliga hovet blundar."},sec={{t="En övergiven trakt",b="Westfall försörjde en gång kungariket Stormwind, men kungariket drog tillbaka sina trupper och lämnade folket försvarslöst. Defias Brotherhood spred sig över slätterna, lade beslag på familjegårdar och järngruvor och pressade lokala bönder på pengar. När inga kungliga förstärkningar syntes till samlade veteranen Gryan Stoutmantle medborgare och pensionerade soldater för att bilda People's Militia."},{t="Försvaret av Sentinel Hill",b="Sentinel Tower, högst upp på Sentinel Hill, är Militians bas. Därifrån patrullerar frivilliga områdets huvudvägar med få militära redskap och knappa förnödenheter. Gryan Stoutmantle leder dem mot de växande skarorna av Defias stråtrövare, tjuvar och plundrare. När Redridge ber om hjälp måste Militian säga nej. Om de skickar ens en handfull män kan Westfall gå förlorat."},{t="Sammansvärjningen avslöjas",b="People's Militia får genom spaning och hjälp utifrån veta hur stort hotet från Defias är. Brotherhood är mer än ett gäng lantliga tjuvar: de lyder under Edwin VanCleef, den tidigare skråmästaren för stenhuggarna som återuppbyggde Stormwind. Från Deadmines under Moonbrook planerar Defias att störta kungariket. Den hårt trängda Militian är det enda som står mellan huvudstaden och ett öppet uppror."}},faq={{q="Varför strider People's Militia ensam utan Stormwinds armé?",a="Stormwind drog tillbaka sina trupper från Westfall och lämnade folket försvarslöst. Ingen på landsbygden har fått veta varför. Gryan Stoutmantle samlade People's Militia för att försvara det som återstod av landet.",al={"varför ingen stormwind-vakt","var finns stormwinds armé","varför övergavs westfall"}},{q="Vem leder People's Militia?",a="Gryan Stoutmantle, en erfaren mänsklig veteran, grundade och leder People's Militia.",al={"vem leder westfalls brigad","militians ledare","gryan stoutmantles roll"}},{q="Var ligger deras högkvarter?",a="People's Militia har sin bas vid Sentinel Hill, kring det höga stenvakttornet mitt i Westfall.",al={"militians bas","var ligger sentinel hill","westfalls militiabas"}},{q="Kan Militian hjälpa andra utsatta områden som Redridge?",a="Nej. När Magistrate Solomon från Lakeshire bad om militära reserver var Gryan Stoutmantle tvungen att säga nej, eftersom Militian knappt höll stånd mot Defias.",al={"varför hjälper de inte lakeshire","solomons begäran till stoutmantle"}},{q="Vem är Militians främsta fiende?",a="People's Militia strider mot Defias Brotherhood, ett kriminellt syndikat av före detta stenhuggare, skurkar och stråtrövare under ledning av Edwin VanCleef.",al={"vilka strider de mot","militians fiende","defias fiende"}}},fx={e3ac0fe0={q="Var kom Westfall Brigade ifrån?",a="Det finns ingen Westfall Brigade i Westfall. Försvararna av Sentinel Hill är People's Militia. Gryan Stoutmantle samlade lokala bönder, veteraner och vanliga invånare där efter att Defias Brotherhood tagit över Westfall och Stormwind inte ingrep. De skulle kunna gripa till vapen och försvara sina egna hem och åkrar.",al={"westfall brigades historia","westfall brigades ursprung","people's militia ursprung"}}},fp="16,259,18.383.0,21.378.0,25.408.1,68.209.0,31.84.0,36.106.0,58.163.0,41.136.1"}
P.entries["topic:wildhammer-clan"] = {n="Wildhammer-klanen",s="Wildhammer-klanen är en härdad, naturbunden gren av dvärgfolket, berömd för att tämja vilda gripar och svinga stormladdade hammare. För flera århundraden sedan drevs de bort från sin förfäders fäste Grim Batol och byggde ett självständigt hem bland The Hinterlands skogsklädda bergstoppar. De är tillbakadragna av naturen, men förblir trogna vänner till Alliansen och försvarar himlen närhelst de kallas.",h="Wildhammer-klanen är en härdad, naturbunden gren av dvärgfolket, berömd för att tämja vilda gripar och svinga...",kw={"aerie peak","falstad","grim batol","grip","the hinterlands","khardros","kurdran","stormhammare","wildhammer"},ang={["class:Hunter"]="Bandet mellan Wildhammer-bergsmännen och deras vilda gripar står för den högsta formen av bestbehärskning, byggd på ett livslångt partnerskap snarare än enkel kontroll.",["class:Shaman"]="Wildhammer-traditionen leder rå stormenergi genom mystiska hammare och upprätthåller ett band till elementär blixt och natur som är långt äldre än Ironforges moderna kyrkotraditioner.",["faction:Alliance"]="Alliansen har Wildhammer-dvärgarna att tacka för mycket av sitt övertag i luften. Deras blixtladdade gripryttare vände krigslyckan mot Hordens röda drakar under Andra kriget.",["race:Dwarf"]="För en dvärg från Ironforge är Wildhammer-dvärgarna släkt, bundna av gamla eder. De föredrar blåsiga klippor och öppen himmel framför djupa gruvor, men deras mod med stormhammaren inger den djupaste respekt."},sec={{t="Förvisade från Grim Batol",b="Före De tre hamrarnas krig levde Wildhammer-dvärgarna vid Ironforges fot. När högkonung Modimus Anvilmar dog splittrade ett inbördeskrig dvärgarnas kungarike, och de segrande Bronzebeards tog Ironforge för sig själva. Thane Khardros ledde sin klan norrut för att grunda ett magnifikt fäste inne i Grim Batol. Men freden blev kortvarig: de besegrade Dark Irons belägrade snart fästet. Khardros dräpte själv Dark Iron-trollkvinnan Modgud, men hennes döende förbannelse fördärvade berget så grundligt att salarna blev obeboeliga. Wildhammer-klanen avböjde en inbjudan att återvända under Bronzebeards styre och valde att klara sig själva. De tågade norrut, in bland The Hinterlands skogar och klippiga bergspass."},{t="Stormens ryttare",b="I de frodiga högländerna i sitt nya rike byggde Wildhammer-klanen Aerie Peak. Till skillnad från sina kusiner under jord omfamnade dessa dvärgar den öppna himlen och den levande klippan och utvecklade ett djupt, andligt band till de inhemska griparna. Genom att smida förtrollade stormhamrar i avskilda fågelhus blev Wildhammer-dvärgarna Azeroths främsta luftburna kavalleri. Under Andra kriget, när krigsöverste Orgrim Doomhammer förde sina styrkor mot Quel'Thalas och anföll Aerie Peak, kom högste befälhavare Anduin Lothar och Alliansen till deras undsättning. I tacksamhet svor högthane Kurdran Wildhammer att ställa sina gripryttare till koalitionens förfogande. De utkämpade luftstrider mot Hordens förslavade röda drakar över Lordaerons och Stora havets himlar."},{t="Trogna till slutet",b="När Dark Portal öppnades på nytt ledde Kurdran Wildhammer sina ryttare till Draenor med Alliansexpeditionen. Han offrade möjligheten att återvända för att försegla revan, en gärning som förevigats av en kolossal staty i Stormwinds Valley of Heroes. I Aerie Peak tog högthane Falstad över ledningen för klanen. Även när människornas kungadömen grälade och splittrades under senare år förblev Wildhammer-dvärgarna trogna bundsförvanter till kung Terenas Menethil II. När Scourge svepte fram över Lordaeron under Tredje kriget steg Wildhammer-ryttarna åter till väders. De kämpade desperat för att skydda allierade länder och oskyldiga flyktingar från de levande döda."}},faq={{q="Var finns Wildhammer-klanen just nu?",a="Deras främsta fäste är Aerie Peak, i The Hinterlands bergiga skog, norr om Wetlands och Thandol Span.",al={"wildhammers hem","var bor wildhammer-dvärgarna","wildhammer-klanens plats"}},{q="Varför bor inte Wildhammer-dvärgarna i Ironforge?",a="Efter högkonung Modimus Anvilmars död förlorade Wildhammer-klanen inbördeskriget om kontrollen över Ironforge till Bronzebeards. Thane Khardros ledde sin klan norrut för att bygga ett nytt liv i Grim Batol, i stället för att böja sig för Bronzebeards styre.",al={"varför lämnade wildhammer ironforge","wildhammer under de tre hamrarnas krig"}},{q="Vad hände med deras fäste i Grim Batol?",a="Under De tre hamrarnas krig belägrade Dark Iron-trollkvinnan Modgud Grim Batol. Thane Khardros dräpte henne, men hennes mörka trolldom infekterade salarna med en fasansfull fördärvelse. Berget blev helt obeboeligt, och klanen tvingades till The Hinterlands.",al={"varför är grim batol övergivet","förbannelsen över grim batol","modgud och grim batol"}},{q="Vem leder Wildhammer-klanen i dag?",a="Högthane Falstad Wildhammer leder klanen från Aerie Peak. Han tog över efter sin föregångare Kurdran Wildhammer, som anslöt sig till Alliansexpeditionen genom Dark Portal.",al={"wildhammer-klanens ledare","wildhammer-högthane","vem styr aerie peak"}},{q="Hur anslöt sig Wildhammer-dvärgarna till Alliansen?",a="Under Andra kriget anföll Orgrim Doomhammer The Hinterlands på sin väg mot Quel'Thalas. Högste befälhavare Anduin Lothar ledde Alliansen i försvaret av Aerie Peak och drev bort Horden och skogstrollen. Wildhammer-dvärgarna imponerades av deras mod och anslöt sig till Lordaerons allians.",al={"varför tillhör wildhammer alliansen","wildhammer och alliansens historia"}},{q="Är Wildhammer-dvärgarna nära allierade med Ironforge?",a="Ja. De två klanerna slogs under De tre hamrarnas krig, men förenades för att besegra Dark Irons. För att hedra sin vänskap byggde de Valley of Kings i Loch Modan, och sedan dess har de hållit fast vid sin allians.",al={"förhållandet mellan bronzebeard och wildhammer","kommer ironforge och wildhammer överens"}}},fx={eadee6c6={q="Vad är Wildhammer-klanen?",a="Wildhammer-klanen är ett av Azeroths tre stora dvärgfolk och är känd för sin nära samhörighet med naturen, sin självständighet och sin djärva skicklighet i luften. Till skillnad från sina Bronzebeard-släktingar, som föredrar underjordiska salar, bor Wildhammers öppet bland höga bergstoppar och lummiga skogar. De är berömda världen över som oöverträffade gripryttare och flyger upp i skyn med mystiska stormhamrar laddade med blixtar för att försvara sina hemtrakter och hjälpa sina mångåriga allierade.",al={"vilka är wildhammers","översikt över wildhammer-klanen","wildhammer-dvärgar"}},f21b0698={q="Var kom Wildhammer-klanen ifrån?",a="För länge sedan bodde Wildhammers i klipporna och bergssluttningarna kring Ironforge under högkonungen Modimus Anvilmar. Efter hans död bröt inbördeskriget War of the Three Hammers ut. Thane Khardros och hans klan förvisades från Ironforge av de segrande Bronzebeards och begav sig norrut för att bygga den storslagna fästningen Grim Batol. Efter att ha överlevt en fasansfull belägring av Dark Irons, som lämnade Grim Batol förbannat och obeboeligt, flyttade Wildhammers ännu längre norrut till Lordaeron. Till slut slog de sig ned i de skogsklädda bergen i The Hinterlands.",al={"wildhammers historia","wildhammer-klanens ursprung"}}},fp="15,269,21.580.0,19.651.0,16.568.0,45.106.0,44.196.0,46.222.0,36.158.0,42.292.0,57.214.0"}
P.entries["topic:worgen"] = {n="Worgen",s="Worgen är våldsamma, varglika humanoider som är förbannade med okontrollerbart ursinne och rör sig upprätt men jagar med bestisk snabbhet. De troddes en gång vara rena mardrömmar från andra plan, men dessa vilda flockjägare terroriserar nu Silverpine Forest, Ashenvale och Duskwood.",h="Worgen är våldsamma, varglika humanoider som är förbannade med okontrollerbart ursinne och rör sig upprätt...",kw={"arugal","pyrewood","scythe of elune","shadowfang keep","silverpine","ur","velinde starsong","worgen"},ang={["class:Druid"]="Worgen är en varnande berättelse om vild kraft som kallats fram utan visheten att kontrollera den, och deras spridning genom Kalimdors skogar oroar Cenarion Circle.",["class:Mage"]="Kirin Tor i Dalaran debatterade länge forskningen i Urs mystiska skrifter. Arugals katastrofala frammaning bekräftade Urs varningar om att dessa mardrömsvarelser aldrig borde kallas fram.",["race:NightElf"]="Worgen är fortfarande ett oroande mysterium för kaldorei, vars väktare nu finner bestarna strövande omkring i Ashenvale och Felwood.",["race:Undead"]="I Silverpine Forest strider Forsaken mot förvildade worgenflockar och Arugals förvridna kultister om herraväldet över området söder om Ruins of Lordaeron."},sec={{t="Viskningar och folksagor",b="Långt innan de nyligen dök upp i Lordaeron och Kalimdor talades det i viskningar om vargmän i folksagor och varnande sägner. Deras verkliga ursprung är fortfarande ett mysterium: lärda som studerat bestarna tror att de drogs till Azeroth från en annan värld, och både ärkemagikern Arugal och nattalvernas Scythe of Elune har visat sig kunna kalla fram dem."},{t="Arugal's Folly",b="Under det tredje kriget, när Svärmhorderna vällde över Lordaeron och stupade Kirin Tor-magiker reste sig som odöda, sökte ärkemagikern Arugal ett vapen för att förstärka Dalarans sinande styrkor. Med hjälp av den förbjudna forskningen från Dalaran-magikern Ur trängde Arugal igenom slöjan och kallade bestarna till Silverpine Forest. De frammanade worgen ödelade de odöda inkräktarna med vild hänsynslöshet, men ärkemagikern kunde inte tygla deras raseri. Bestarna vände sig mot magikerna själva och spred sin förbannelse med huggtand och klo. Driven till vansinne av skuld och fascination tog Arugal monstren till sig som sina barn och lade beslag på Baron Silverlaines förfäders säte, numera omdöpt till Shadowfang Keep, och förbannade närboende bybor till monstruös nattlig träldom."},{t="Lien väcks",b="På andra sidan havet i Kalimdor släppte en annan åkallan lös worgen på nytt. Nattalvsväktaren Velinde Starsong grävde fram Scythe of Elune i ett desperat försök att rena Felwood från Burning Legions kvarvarande demoniska rester. Genom den uråldriga reliken kallade hon fram vargmän för att slita sönder de demoniska satyrerna. Men medan striderna rasade insåg Velinde att lien hade undflytt hennes kontroll: bestarna började visa sig utan hennes medgivande och smög sig in i Ashenvales mörka skogar och längre bort. Worgen strövar nu omkring i vilda, förvildade flockar och sprider skräck där skuggan från deras månupplysta jakter faller."}},faq={{q="Vad är worgen?",a="Worgen är våldsamma, upprättgående varglika humanoider med skrämmande styrka, rovdjurssinnen och mörk skuggmagi. De håller främst till i avskilda skogsområden och ruiner, där de jagar i flockar under okontrollerbart bestiskt ursinne.",al={"vad är en worgen","worgen-lore","vargmän"}},{q="Var kom worgen ursprungligen ifrån?",a="Ingen vet säkert. Bestarna verkar komma från en helt annan värld: ärkemagikern Arugal kallade dem till Silverpine från bortom slöjan, och nattalvernas Scythe of Elune har kallat fram dem i Kalimdor.",al={"worgens ursprung","vem skapade worgen","hur skapades worgen"}},{q="Hur hamnade worgen i Silverpine Forest?",a="Under det tredje kriget kallade ärkemagikern Arugal fram dem med hjälp av den avlidne Dalaran-magikern Urs esoteriska forskning. Arugal hoppades att de skulle förstärka Kirin Tor mot Svärmen, men de lössläppta bestarna vände sig mot alla.",al={"worgen i silverpine","varför finns worgen i silverpine","vem kallade fram worgen"}},{q="Hur blir man en worgen?",a="Tillståndet sprids som en smittsam övernaturlig åkomma. Ett bett eller rivsår från en aktiv worgen smittar humanoider, som till slut dukar under för vilda drifter och förvandlas till vargbest, om de inte hålls tillbaka med järnhård disciplin eller särskild trolldom.",al={"worgenförbannelse","kan man förvandlas till en worgen","worgenbett"}},{q="Vad är Scythe of Elune?",a="Scythe of Elune är en mäktig nattalvsrelik. Den har ett djupt, nyckfullt herravälde över worgen och kan kalla fram och hetsa upp dem.",al={"scythe of elune","scythe of elune-lore"}},{q="Vem är ärkemagikern Arugal?",a="Arugal var en ärkemagiker i Kirin Tor i Dalaran. Efter att ha kallat fram worgen för att strida mot Svärmen dukade han under för vansinne och kom att härska över de hemsökta ruinerna i Shadowfang Keep tillsammans med sina monstruösa ”barn”.",al={"arugal","vem är arugal"}},{q="Varför finns worgen i Ashenvale och Kalimdor?",a="Worgenflockar stryker nu omkring i Ashenvale och Felwood, och Darnassus väktare söker fortfarande svar på hur de kom till Kalimdor. Deras undersökning följer spåren efter den försvunna väktaren Velinde Starsong och en uråldrig relik, Scythe of Elune.",al={"worgen i ashenvale","worgen i kalimdor","terrowulf"}}},fx={d99a4888={q="Varför är worgen fientliga mot resenärer?",a="De flesta worgen du möter har slukats av vild, ursprunglig vrede. Förbannelsen berövar dem förnuft och självbehärskning och driver de drabbade in i ett raseri där de ser främlingar som byten eller hot som måste slitas i stycken. Även de som följer den vansinnige ärkemagikern Arugal ser dödliga som fiender att slakta eller förbanna så att de ansluter sig till deras flockar.",al={"varför anfaller worgen","är worgen fientliga","varför är worgen aggressiva"}},["92f4d7ca"]={q="Vem leder worgen?",a="Worgen lyder inte under en enda härskare, utan samlas i flockar under mäktiga gestalter. I Silverpine Forest tjänar många ärkemagikern Arugal i Shadowfang Keep. Det var han som kallade dem till världen. Självständiga flockar strövar fritt genom Lordaeron, Duskwood och Kalimdor och följer endast sin alfaledare eller sina urinstinkter.",al={"worgenledare","vem styr worgen","worgenhärskare"}},["52984533"]={q="Vilka är worgen allierade med?",a="Worgen har inga breda allianser. I Silverpine lyder vissa flockar den renegate ärkemagikern Arugal, som håller till i Shadowfang Keep. I övrigt härjar dessa vildsinta bestar i vildmarken och angriper Scourge, alliansen och Forsaken utan åtskillnad. De tjänar bara sin ursprungliga hunger och ledarna för sina egna flockar.",al={"worgens allierade","vem tjänar worgen","worgenfraktioner"}},b6544cd9={q="Var kom worgen ifrån?",a="Deras verkliga ursprung är okänt. Bestarna verkar komma från ett annat rike. Under Third War kallade ärkemagikern Arugal dem till Silverpine från någonstans bortom vår värld. Ingen vet hur flockarna började ströva i Kalimdors skogar. Nattalverna försöker fortfarande ta reda på det.",al={"worgens historia","worgens bakgrund","hur skapades worgen"}}},fp="6,201,22.315.0,14.663.0,17.501.1,16.228.0,42.211.0,43.199.0,33.230.0,28.128.0,23.204.0,41.221.0"}
P.entries["topic:world-of-warcraft-forever"] = {n="World of Warcraft: Forever",s="World of Warcraft: Forever utspelar sig året efter det tredje kriget: Thralls hord har slagit sig ner i Durotar, Stormwind styrs av en regent för sin unge kung och de Fördömda håller Undercity. Världen rymmer Skyborne på Zephras Isle, de omstridda Riverglades och Shen'dralas, heliga Mount Hyjal och staden Dalaran, som reser sig ur ruinerna i Alterac Mountains.",h="World of Warcraft: Forever utspelar sig året efter det tredje kriget: Thralls hord har slagit sig ner i...",kw={"klasskombinationer","dalaran","darkspear islands","mount hyjal","riverglades","shen'dralas","skyborne","world of warcraft forever","wow forever","zephras isle"},ang={["race:Dwarf"]="Dvärgarna i Ironforge följer schamanens väg såväl som Ljusets, och åkallar sten och storm.",["race:Skyborne"]="Ditt folk har bara börjat återvända till Azeroth, och både alliansen och horden har tagit in Skyborne i sina led.",["race:Undead"]="Vissa av de Fördömda svingar fortfarande det heliga Ljuset som paladiner, trots att det bränner dem; Tyr's Watch håller Bandarion Keep i västra Tirisfal."},sec={{t="Världen efter det tredje kriget",b="Den brinnande legionen har drivits tillbaka vid Mount Hyjal, men världen den lämnade efter sig är sargad. Thralls hord av orcher, troll och tauren har slagit sig ner i Durotar och Mulgore, och de Fördömda under Sylvanas Windrunner har anslutit sig från Lordaerons ruiner. I Stormwind styr Highlord Bolvar Fordragon som regent åt den unge kungen Anduin Wrynn medan kung Varian är försvunnen. Dvärgarna i Ironforge, de landsförvisade gnomerna och nattalverna på Teldrassil står med alliansen, och Scourge håller fortfarande Plaguelands."},{t="Skyborne",b="Skyborne, eller shen'dorei, härstammar från nattalver som gjorde uppror mot prins Tortheldrin av Eldre'Thalas och flydde när vindandar förde deras ö, Zephras Isle, till Skywall, luftens elementarplan. Årtusenden där förvandlade dem till högalver, och allt fler föds med blå hud. Andarna försvann för århundraden sedan, Zephras Isle faller långsamt sönder och Skyborne blickar åter mot Azeroth: deras luftskepp når Alterac Mountains nära Dalaran och Skywatcher Plateau i Mulgore. Skyborne strider för både alliansen och horden."},{t="Länder att utforska",b="Zephras Isle svävar i Skywall och är Skybornes hemland. Riverglades, öster om Burning Steppes, är en gammal gränsbygd tillhörande Stormwind som gick förlorad i det första kriget, där lojala styrkor i Farholde Keep håller stånd mot vildmarken, hordens utposter och Twilight's Hammer i Sunnyglade. Shen'dralas är ett kargt gränsland mellan Desolace, Feralas och Mulgore, omstritt av kentaurer, quilboar och utstötta. Mount Hyjal, nattalvernas heliga berg, bär fortfarande spåren efter Archimondes nederlag. I Alterac Mountains har Kirin Tor sänkt Dalarans sköld och återuppbygger staden, och utanför Kalimdors kust strider horden och alliansen om Darkspear Islands."},{t="Grottor och räder",b="Faror väntar under städerna och i världens avlägsna hörn: Hall of Thanes djupt under Ironforge, de hemsökta Ruins of Lordaeron ovanför Undercity, en utgrävningsplats i Wetlands, själva City of Dalaran, Drowned City i Stranglethorn Vale, Krol'dok Stronghold i Riverglades, Alcaz Prison i Dustwallow Marsh, Blackmaw Hold i Azshara och Shaper's Terrace i Un'Goro Crater. På Mount Hyjal sätts de mäktigaste krigshärarna på prov i Barrow Deeps och Hyjal Summit."},{t="Vem går vilken väg",b="Krigare finns bland alla raser. Paladiner är människor, dvärgar eller Fördömda. Schamaner är orcher, tauren, troll, dvärgar eller Skyborne från horden. Präster är människor, dvärgar, gnomer, nattalver, troll eller Fördömda. Magiker är människor, gnomer, orcher, troll, Fördömda eller Skyborne från alliansen. Häxmästare är människor, gnomer, orcher, troll eller Fördömda. Jägare är människor, dvärgar, nattalver, orcher, tauren, troll eller Skyborne. Skurkar finns bland alla raser utom tauren, och druider är nattalver, tauren eller Skyborne."}},faq={{q="När utspelar sig World of Warcraft: Forever?",a="Året efter det tredje kriget, när de Fördömda har tagit Undercity. Thrall leder horden från Orgrimmar, Highlord Bolvar Fordragon är regent i Stormwind åt den unge kungen Anduin, och Scourge håller fortfarande Plaguelands.",al={"när utspelar sig wow forever","wow forever tidslinje","vilket år utspelar sig wow forever","när utspelar sig forever"}},{q="Vilka länder kan jag utforska i WoW Forever?",a="Bland länderna finns Zephras Isle, Skybornes svävande hem i Skywall; Riverglades, en gammal gränsbygd tillhörande Stormwind; Shen'dralas, ett gränsland mellan Desolace, Feralas och Mulgore; Mount Hyjal, nattalvernas heliga berg; och Dalaran, som åter reser sig i Alterac Mountains. Horden och alliansen strider också om Darkspear Islands.",al={"vad är nytt i wow forever","vad är nytt i forever","nya zoner i wow forever","wow forever zoner","vad finns i wow forever"}},{q="Vilka är Skyborne?",a="Högalver som härstammar från nattalver som flydde från Eldre'Thalas för länge sedan och levde på Zephras Isle i Skywall, luftens elementarplan. När deras ö faller sönder blickar de åter mot Azeroth, och de strider för både alliansen och horden.",al={"skyborne","shen'dorei","ny ras i wow forever"}},{q="Var ligger Dalaran?",a="Vid stranden av Lordamere Lake i Alterac Mountains. Archimonde krossade staden i det tredje kriget; sedan dess har Kirin Tor sänkt skölden de reste över ruinerna, och staden återuppbyggs.",al={"dalaran wow forever","är dalaran återuppbyggt","dalaran alterac"}},{q="Vilka grottor och räder finns det?",a="Bland dem finns Hall of Thanes under Ironforge, Ruins of Lordaeron ovanför Undercity, en utgrävningsplats i Wetlands, City of Dalaran, Drowned City i Stranglethorn Vale, Krol'dok Stronghold i Riverglades, Alcaz Prison i Dustwallow Marsh, Blackmaw Hold i Azshara och Shaper's Terrace i Un'Goro Crater. Räderna är Barrow Deeps och Hyjal Summit på Mount Hyjal samt Onyxia's Lair i Dustwallow Marsh.",al={"wow forever grottor","wow forever räder","nya grottor i wow forever","nya räder"}},{q="Vilka klasser kan varje ras ha?",a="Människor: krigare, paladin, jägare, skurk, präst, magiker eller häxmästare. Dvärgar: krigare, paladin, jägare, skurk, präst eller schaman. Nattalver: krigare, jägare, skurk, präst eller druid. Gnomer: krigare, skurk, präst, magiker eller häxmästare. Orcher: krigare, jägare, skurk, schaman, magiker eller häxmästare. Fördömda: krigare, paladin, skurk, präst, magiker eller häxmästare. Tauren: krigare, jägare, schaman eller druid. Troll: krigare, jägare, skurk, präst, schaman, magiker eller häxmästare. Skyborne: krigare, jägare, skurk eller druid, samt magiker i alliansen och schaman i horden.",al={"kombinationer av ras och klass","vilken klass kan jag välja","kan odöda vara paladiner","odöd paladin","dvärgschaman","gnompräst","människojägare","orcmagiker","trollhäxmästare","skyborne-klasser"}}},fp="26,376,29.535.0,12.561.0,16.657.0,18.526.0,20.468.0,39.270.0,40.336.0,21.257.0,17.215.0,34.463.0,31.671.0"}
P.entries["zone:alterac"] = {n="Alterac Mountains",s="Alterac Mountains är ett kallt, förfallet högland mitt i Lordaeron, en gång hem åt det förrädiska människoriket Alterac och Dalarans lärda magokrati. I dag härjar Crushridge-ogrerna, Syndicates aristokratiska banditer och kvarlevande magiska krafter bland de snötäckta topparna. Resande kommer från närliggande bosättningar vid bergsfoten och den återuppbyggda staden Dalaran.",h="Alterac Mountains är ett kallt, förfallet högland mitt i Lordaeron, en gång hem åt det förrädiska...",kw={"alterac","crushridge","dalaran","perenolde","ravenholdt","strahnbrad","syndicate","högland"},ang={["class:Mage"]="Dalarans gator, som byggs upp igen, surrar av kvarvarande magiska strömmar och jäktade magiker från Kirin Tor. Staden är en allvarsam pilgrimsfärd till den ödelagda kärnan av människornas trolldomskonst.",["class:Rogue"]="Ravenholdt Manors dolda dal ligger inbäddad bland Alteracs östra klippor och erbjuder elitkontrakt, låsdyrkningsövningar och hemliga gilleshemligheter under Lord Jorach Ravenholdts uppsikt.",["faction:Alliance"]="Alliansens resande möter Crushridge-ogrerna och Syndicates laglösa, som ockuperar det forna riket.",["faction:Horde"]="Frostwolf Clan har gjort de avskilda bergen till sitt hem, medan Forsakens agenter från Tarren Mill möter ogres och Syndicates laglösa.",["profession:Herbalism"]="Alteracs frusna toppar är välkända bland örtletare som den enda naturliga växtplatsen för Wintersbite, en viktig ingrediens i kraftfulla brygder mot kyla."},sec={{t="Det fallna riket",b="Under det andra kriget var Alterac ett av människornas sju kungariken, men kung Aiden Perenolde förrådde Alliance of Lordaeron och ställde sig på Old Hordes sida i hopp om att rädda sitt rike. Förräderiet avslöjades och slogs ned, och nationen splittrades i omstridda gränsområden. Efter rikets upplösning och det tredje krigets fasor förvandlades Alteracs storslagna stenhuvudstad till ruiner. I dag ockuperas Ruins of Alterac av de brutala Crushridge-ogrerna, ledda av Mug'thol, medan de överlevande människoadelsmännen organiserade sig i Syndicate, ett hänsynslöst brottssyndikat som med våld försöker återta sina förlorade gods."},{t="Staden återuppbyggs",b="Vid bergens västra kant, längs Lordamere Lakes stränder, ligger det som återstår av Kirin Tors stora stadsstat Dalaran. Efter att demonherren Archimonde ödelade staden under det tredje kriget reste Dalarans överlevande magiker en väldig, ogenomskinlig violett kupol av skyddande magi över ruinerna. Den har sedan dess tagits bort, och de bygger upp staden under öppen himmel. Kirin Tor fortsätter att återuppbygga sitt heliga säte, och Archmage Ansirem Runeweaver finns i Violet Citadel."},{t="Konflikternas gränsland",b="Äventyrare tar sig ofta upp bland topparna med Southshore eller Tarren Mill som utgångspunkt. Bortom de kringvandrande yetierna, bergslejonen och Syndicates fotsoldater rasar regionens största konflikt under snögränsen. Djupt inne i bergspassen ligger Alterac Valley, där dvärgarnas Stormpike Guard har drabbat samman med orkernas tillbakadragna Frostwolf Clan om urgamla territoriella rättigheter och gruvrättigheter."}},faq={{q="Vad hände med kungariket Alterac?",a="Under det andra kriget förrådde kung Aiden Perenolde alliansen för att hjälpa Horden. Lordaeron och Stromgarde slog ned förräderiet och ockuperade landet. När Scourge drog fram genom Lordaeron under det tredje kriget föll det som återstod av Alterac i anarki, och den förstörda huvudstaden lämnades åt Crushridge-ogrerna.",al={"varför är alterac förstört","vad hände med perenolde","alteracs kungarikes historia"}},{q="Vilka är Syndicate?",a="Syndicate är en laglös organisation som bildats av Alteracs egendomslösa adel. De leds av tidigare Alteraciska kungligheter som Lord Aliden Perenolde och använder lönnmördare, stråtrövare och vanärade lorder för att terrorisera de omgivande områdena och driva bort rivaler. De kämpar desperat för att återta sina förfäders domäner.",al={"vilka är syndicate","varför finns det människobanditer i alterac","syndicates historia"}},{q="Vad hände med Dalarans lysande kupol?",a="Efter att Archimonde ödelade Dalaran under det tredje kriget reste de överlevande i Kirin Tor en skyddande magisk sköld över ruinerna. Skölden har sedan dess tagits bort, och staden återuppbyggs under öppen himmel. Archmage Ansirem Runeweaver står nu i Violet Citadel.",al={"lila kupol alterac","vad är den violetta bubblan","dalarans sköld"}},{q="Var hittar jag flygvägar eller trygga värdshus i Alterac?",a="Southshore och Tarren Mill i Hillsbrad Foothills är vanliga utgångspunkter för expeditioner in bland de snöiga topparna. Dalaran vid den västra kanten är öppet för alliansens resande medan Kirin Tor bygger upp staden, men där finns ingen flygmästare. Horden är hatad av Kirin Tor och angrips så snart dess medlemmar visar sig i staden.",al={"flygväg i alterac","värdshus i alterac","uppdragsnav i alterac"}},{q="Vad är Alterac Valley?",a="Alterac Valley är en avskild, snötäckt dal som omstrids av dvärgarnas Stormpike Guard och orkernas Frostwolf Clan. Stormpikes anlände på en arkeologisk expedition, vilket utlöste ett fullskaligt territoriellt krig med Frostwolves, som levt fredligt i dalen sedan de förvisades under det första kriget.",al={"ingång till alterac valley","frostwolf mot stormpike","var ligger alterac valley"}},{q="Vad är Ravenholdt Manor?",a="Dold i en undanskymd bergsskreva öster om huvudvägen ligger Ravenholdt Manor, League of Assassins hemlighetsfulla gillehus. Under Lord Jorach Ravenholdts ledning fungerar det som träningsplats och fristad för skickliga skurkar från hela Azeroth.",al={"var ligger ravenholdt","mördarherrgård i alterac","tjuvgille i alterac"}}},fp="17,268,18.592.0,19.393.0,21.359.0,40.283.0,22.287.0,40.271.0,54.308.0,23.313.0,25.231.0"}
P.entries["zone:alteracvalley"] = {n="Alterac Valley",s="Djupt inne i Alterac Mountains ligger Alterac Valley, Frostwolves klan, Thralls egen klan, och nu ett fruset slagfält. Dvärgar från Stormpike-expeditionen har grävt sig in i dalen på jakt efter rikedomar och band till sina förfäders historia. Frostwolves vägrar tåla intrånget och har samlat en armé för att driva bort dem. Båda sidor kämpar genom fiendens torn och gravplatser för att nå fiendens general: Vanndar Stormpike i Dun Baldar eller Drek'Thar i Frostwolf Keep.",h="Djupt inne i Alterac Mountains ligger Alterac Valley, Frostwolves klan, Thralls egen klan, och nu ett fruset...",kw={"alterac valley","slagfält","frostwolf clan","stormpike guard","drek'thar","vanndar stormpike","dun baldar","frostwolf keep","durotan","thrall"},ang={["faction:Alliance"]="Alliance-soldater marscherar med Stormpike Guard för att hålla dalens gruvor och hemligheter borta från Frostwolf-horden.",["faction:Horde"]="Det här är krigshövdingens eget hemland. Varje Horde-krigare i dalen försvarar snön där Thrall fann sitt folk.",["race:Dwarf"]="Stormpike-dvärgarna ser dalens reliker som en länk till sina förfäder, och ingen orchklan ska driva bort dem från deras utgrävningar.",["race:Orc"]="Frostwolves är Durotans klan och Thralls eget blod. För en orch är det att försvara deras dal som att försvara den nya Hordes hjärta."},sec={{t="Frostwolves hem",b="När Gul'dan förvisade Durotans Frostwolf-klan för att de trotsade honom fann orcherna en fristad i den kalla dalen och gjorde den till sitt hem. Långt senare fann unge Thrall sin fars folk här och lärde sig schamanernas vägar av den äldre Drek'Thar. Thrall leder nu Horde i Kalimdor, men många Frostwolves stannade kvar i dalen under Drek'Thars ledning och vaktar den lika hårdnackat som vilket hemland som helst."},{t="Stormpike-expeditionen",b="Stormpike Guard är en expedition av dvärgar från Ironforge, ledd av Vanndar Stormpike från den nordliga fästningen Dun Baldar. De kom till dalen för dess gruvor och reliker som de tror knyter dem till deras förfäder, och har grävt ner sig där med bunkrar, torn och okuvlig stolthet. För Frostwolves är de inkräktare; för dvärgarna tillhör dalens hemligheter dem med upptäckarens rätt."},{t="Krig i snön",b="Kampen om Alterac Valley är det största av dessa krig: en armé mot en annan. Krigare stormar torn och bunkrar, intar gravplatser och lägger beslag på dalens gruvor för sin sida. Striden slutar när den ena sidan bryter igenom till fiendens general och besegrar honom: Vanndar Stormpike i Dun Baldar för Horde, eller Drek'Thar i Frostwolf Keep för Alliance."}},faq={{q="Vad är Alterac Valley?",a="Alterac Valley är en slagmark gömd i Alterac Mountains och hem åt Frostwolf-orcherna. Frostwolf-klanen och dvärgarna i Stormpike Guard utkämpar ett fullskaligt krig där, och båda försöker nå och besegra den andra sidans general.",al={"vad är alterac valley","slagfältet alterac valley","av"}},{q="Varför strider Frostwolves i Alterac Valley?",a="Dalen är Frostwolves hem, där Durotans klan slog sig ner i exil och där Thrall fann sitt folk. De tänker inte tåla att Stormpike-dvärgarna gräver sig in där, och Horde strider vid deras sida för att driva bort expeditionen.",al={"frostwolf clan","hordes insatser i alterac valley","varför strider horde i alterac valley"}},{q="Varför är Stormpike-dvärgarna i Alterac Valley?",a="Stormpike-expeditionen kom från Ironforge för att utvinna dalens rikedomar och leta efter reliker från deras förfäders tid. De leds av Vanndar Stormpike från Dun Baldar och vägrar ge upp sina anspråk, och Alliance strider vid deras sida.",al={"stormpike guard","alliances insatser i alterac valley","stormpike-expeditionen"}},{q="Vem är Drek'Thar?",a="Drek'Thar är Frostwolf-klanens äldre schaman och mentorn som lärde unge Thrall schamanernas vägar. Han för befäl över Frostwolves från Frostwolf Keep, och Alliance måste besegra honom för att vinna striden.",al={"drek'thar","frostwolf-general","frostwolf-äldre schaman"}},{q="Vem är Vanndar Stormpike?",a="Vanndar Stormpike är dvärgarnas befälhavare i Stormpike Guard. Han leder expeditionen från fästningen Dun Baldar, och Horde måste besegra honom för att vinna striden.",al={"vanndar stormpike","stormpike-general","dun baldar"}},{q="Hur vinner man striden i Alterac Valley?",a="Varje armé kämpar genom fiendens torn, bunkrar och gravplatser mot fiendens fäste. Striden slutar när den ena sidan besegrar fiendens general: Vanndar Stormpike i Dun Baldar eller Drek'Thar i Frostwolf Keep.",al={"mål i alterac valley","hur man vinner alterac valley","generaler i alterac valley"}}},fp="14,352,23.380.0,24.395.0,15.327.0,23.208.0,47.222.0,48.239.0,17.204.0,25.156.0,40.214.0"}
P.entries["zone:arathi"] = {n="Arathi Highlands",s="Arathi Highlands är en karg högplatå i sydöstra Lordaeron, känd som det forntida Arathorimperiets födelseplats. I dag ligger kungariket Stromgarde i ruiner, och det klippiga landet slits sönder av krig på flera fronter mellan Stromgardes kvarvarande styrkor, Horden, Syndikatets kriminella adelsmän och invaderande ogres.",h="Arathi Highlands är en karg högplatå i sydöstra Lordaeron, känd som det forntida Arathorimperiets...",kw={"arathi","arathi highlands","arathor","boulderfist","galen trollbane","hammerfall","refuge pointe","stromgarde","syndikatet","thandol span","thoradin's wall"},ang={["class:Warrior"]="Stromgarde gav upphov till Azeroths mest hyllade tradition av frontkrigare, och dess karga slagfält har blivit en vördad prövning i vapenkonst.",["faction:Horde"]="Hammerfall är helig mark för dagens Horde – ett monument över Orgrim Doomhammers offer, som befriade ett förslavat folk ur fångenskapen.",["profession:Mining"]="Arathis klippiga åsar är rika på järn och mithril, och Drywhisker Gorge är den enda kända fyndplatsen för Lesser Bloodstone Ore.",["race:Human"]="Alla människoriken spårar sina rötter till Arathorimperiet. Att se den mänskliga civilisationens vagga sönderslagen och översvämmad av ogres och tjuvar är en djup kulturell tragedi."},sec={{t="Mänsklighetens vagga",b="För årtusenden sedan enade kung Thoradin de splittrade människostammarna under Arathis fana och lät bygga den ståtliga huvudstaden Strom på dessa torra, lättförsvarade slätter. Det var här mänskligheten slöt sin legendariska pakt med högalverna under Trollkrigen och bemästrade de magiska konsterna för att driva tillbaka Amani. Med tiden flyttade adliga ätter norrut till Lordaeron och söderut mot Stormwind, men kejsarens garde stannade kvar och lade grunden till det krigiska riket Stromgarde. I århundraden stod Stromgarde som ett bålverk av orubbliga krigare, hängivna åt att hålla skogstrollen stången."},{t="Ett krossat kungarike",b="Stromgarde blev avgörande för att försvara Alliansen under det andra kriget under kung Thoras Trollbane, men det tredje kriget och dess följder krossade nationen. Kungariket skonades från plågans värsta härjningar från Scourge, men kung Thoras mystiska död kastade riket in i kaos. Boulderfist-ogres strömmade in från kullarna, medan Syndikatets förrädiska adelsmän från Alterac lade beslag på stora delar av Stromgarde Keep. I dag håller prins Galen Trollbane och hans lojala överlevare fast vid en liten del av staden och sitt fäste vid Refuge Pointe, där de utkämpar ett bittert gerillakrig mot hopplösa odds."},{t="Kriget om höglandet",b="Arathi är en hårt omstridd knutpunkt. I nordost gjorde Horden om ett övergivet interneringsläger för människor till Hammerfall, uppkallat efter den legendariske krigshövdingen Orgrim Doomhammer. Därifrån säkrar de sina nordliga besittningar och skyddar sina allierade i Hillsbrad. Samtidigt söker Witherbark-trollstammen hämnd på sina forntida mänskliga förtryckare, och Argus Wake drar i trådarna bakom Syndikatets ockupation. Mitt på högplatån ligger forntida bindningscirklar, där bundna elementaler håller en gåtfull, uråldrig kraft fången under stenen."}},faq={{q="Vad hände med Stromgarde Keep?",a="Efter kung Thoras Trollbanes död dukade Stromgarde under för inre stridigheter och överväldigande angrepp. Boulderfist-ogres tog stadens yttre distrikt, medan det opportunistiska Syndikatet lade beslag på helgedomen. Prins Galen Trollbane och hans krympande garnison håller sig kvar i ett enda befäst hörn och utkämpar desperata strider inne i sin egen huvudstad.",al={"varför ligger stromgarde i ruiner","vem kontrollerar stromgarde","stromgardes läge i dag"}},{q="Vad är Hammerfall?",a="Hammerfall är en befäst utpost för Horden, byggd bland resterna av ett interneringsläger för människor där orcher hölls fångna efter det andra kriget. Platsen fick sitt namn för att hedra den tidigare krigshövdingen Orgrim Doomhammer, som stupade när han ledde fälttåget för att befria fångarna i Lordaerons läger.",al={"hordens bas i arathi","hammerfalls historia","varför heter det hammerfall"}},{q="Var verkar Alliansen i Arathi?",a="Alliansens soldater och Stromgardes försvarare utgår från Refuge Pointe, en naturligt befäst kanjon mitt i höglandet. Därifrån gör de räder för att återta Stromgarde Keep och slå tillbaka de framryckande ogres och trollen.",al={"alliansens bas i arathi","refuge pointe","var finns människorna från stromgarde"}},{q="Vad är stencirklarna över slätterna?",a="Bindningscirklarna – den inre, den yttre, den östra och den västra – är forntida magiska sigill som upprätthålls och bevakas av vilda elementaler. De håller en okänd urvarelse fången djupt under höglandet.",al={"bindningscirklarna","elementaler i arathi","stencirklar"}},{q="Hur tar du dig till Arathi Highlands?",a="Resenärer från norr och väster passerar genom öppningen i Thoradin's Wall från Hillsbrad Foothills. Resenärer som kommer söderifrån, från Khaz Modan, korsar den väldiga dvärgbron Thandol Span, som sträcker sig över ravinen mellan höglandet och Wetlands.",al={"ta sig till arathi","hur tar man sig till arathi highlands","ingången till arathi"}},{q="Vad gör Syndikatet i Arathi?",a="Syndikatet består av adelsmän från Alterac som förvisats och nu försöker skapa nya domäner genom att plundra fallna riken. I Arathi har de tagit över stora delar av Stromgarde Keep och gårdar i utkanterna, som Northfold Manor.",al={"varför är syndikatet i arathi","syndikatet i stromgarde","vem leder syndikatet här"}}},fp="16,232,18.553.0,19.544.0,25.539.1,33.281.0,19.247.0,42.214.0,45.192.0,38.235.0,38.202.1"}
P.entries["zone:arathibasin"] = {n="Arathi Basin",s="Arathi Basin är en bördig dal i Arathi Highlands och en av huvudfronterna i kriget mellan människorna och de Förfallna. The League of Arathor strider för att återta Arathors förlorade marker åt sina uppbackare i Stormwind, medan The Defilers, elittrupper bland de Förfallna under dreadlorden Varimathras, försöker skära av den livsviktiga förbindelsen mellan människorna och deras dvärgiska allierade i söder. Båda sidor kämpar om dalens gård, stall, sågverk, smedja och guldgruva, vars resurser försörjer kriget.",h="Arathi Basin är en bördig dal i Arathi Highlands och en av huvudfronterna i kriget mellan människorna och de...",kw={"arathi basin","slagfält","the league of arathor","the defilers","varimathras","gård","stall","sågverk","smedja","guldgruva"},ang={["faction:Alliance"]="Varje fäste som The League håller är ett fält av Arathor som återtagits, och spannmål och järn på väg till Stormwinds soldater.",["faction:Horde"]="När Horden strider vid The Defilers sida blöder den människorna på resurserna de behöver och håller dem avskurna från dvärgarna i söder.",["race:Human"]="De här gårdarna försörjde Stromgarde i generationer. För en människa är dalen ingen trofé, utan ett hem att återta.",["race:Undead"]="De Förfallna minns de levande kungadömen som fördrev dem. Att ta dalen från Arathors arvingar är en kylig och passande hämnd."},sec={{t="Arathors skafferi",b="Långt före det tredje kriget försörjde dalens fält, kvarnar och gruvor riket Stromgarde, arvtagare till det forntida Arathor. När Lordaeron föll och Stromgarde rämnade lämnades dalen nästan helt oförsvarad, medan gårdarna och verkstäderna fortfarande stod kvar. Den som håller dem nu har spannmål, timmer, järn och guld, sådant som håller en armé ute i fält. Därför är den stillsamma dalen en av de mest omstridda platserna i höglandet."},{t="The League och The Defilers",b="The League of Arathor är ett kompani i Alliansen, bestående av överlevare från Stromgarde och deras vänner. Med stöd från Stormwind och bas i Refuge Pointe har de svurit att återta markerna som deras förfäder byggde upp. The Defilers är de Förfallnas svar: härdade trupper från Undercity under Varimathras vakande öga, som verkar tillsammans med Horden vid Hammerfall. Deras mål är att tömma dalen på dess rikedomar och skära av vägen som förbinder människorna i norr med dvärgarna i söder."},{t="Håll dalen",b="Fem fästen avgör striden: gården, stallet, sågverket, smedjan och guldgruvan. Varje sida skyndar sig att hissa sin fana över dem och försvara det de tar, eftersom varje fäste de håller ökar deras resurser. Plundrare smyger mellan dem för att ta en punkt medan fienden är upptagen på annat håll, och sidan som först samlar tillräckligt med resurser vinner dalen, åtminstone för en tid."}},faq={{q="Vad är Arathi Basin?",a="Arathi Basin är en slagmark i en bördig dal i Arathi Highlands. Alliansens The League of Arathor och de Förfallnas The Defilers kämpar där om kontrollen över gården, stallet, sågverket, smedjan och guldgruvan, vars resurser försörjer deras krig.",al={"vad är arathi basin","slagfältet arathi basin","ab"}},{q="Vilka är The League of Arathor?",a="The League of Arathor är ett kompani i Alliansen, bestående av överlevare från Stromgarde och deras allierade. De får stöd från Stormwind och har sin bas nära Refuge Pointe. De strider för att återta Arathors förlorade marker och dalens rikedomar.",al={"the league of arathor","alliansen i arathi basin","arathors liga"}},{q="Vilka är The Defilers?",a="The Defilers är elittrupper bland de Förfallna som tjänar under dreadlorden Varimathras, Lady Sylvanas löjtnant. Tillsammans med Horden vid Hammerfall försöker de lägga beslag på dalens resurser och skära av förbindelsen mellan människorna i norr och deras dvärgiska allierade.",al={"the defilers","de förfallna i arathi basin","the defilers varimathras"}},{q="Varför strider Alliansen och de Förfallna om Arathi Basin?",a="Dalens gårdar, kvarnar och gruvor kan försörja och beväpna en armé. För The League är återerövringen ett steg mot att återupprätta Arathor; för The Defilers svälter ett övertagande ut människorna och skär av dem från deras dvärgiska allierade i söder.",al={"vad står på spel i arathi basin","varför strida om arathi basin","kriget om arathi basin"}},{q="Hur vinner man striden i Arathi Basin?",a="Båda sidor kämpar för att inta och hålla dalens fem fästen: gården, stallet, sågverket, smedjan och guldgruvan. Varje fäste de håller ökar sidans resurser, och sidan som först samlar tillräckligt vinner.",al={"målen i arathi basin","resurser i arathi basin","hur vinner man arathi basin"}}},fp="12,307,21.422.0,27.477.0,17.392.0,21.209.0,30.203.0,21.252.0,61.253.0,38.195.0"}
P.entries["zone:ashenvale"] = {n="Ashenvale",s="Ashenvale är nattalvernas urgamla, regndränkta förfädersskog, helig och skyddad av Sentinels och halvguden Cenarius. Den gränsar till The Barrens i söder och Darkshore i norr, och har blivit en bitter krigszon när Horde avverkar timmer för att bygga sin unga nation. Uråldriga träd och fridfulla moonwells delar trädkronorna med demoniska fästen, fientliga bestmän och stridsplatser längs den omstridda gränsen.",h="Ashenvale är nattalvernas urgamla, regndränkta förfädersskog, helig och skyddad av Sentinels och halvguden...",kw={"ashenvale","astranaar","bough shadow","cenarius","grommash","mannoroth","silverwing","splintertree","warsong","zoram"},ang={["class:Druid"]="Naturens balans här är belägrad från flera håll. Mellan timmerverksamheten, de fördärvade furbolgernas hålor och den mardrömshemsökta portalen i Bough Shadow behöver Ashenvale desperat återställas av Cenarion Circle.",["profession:Herbalism"]="Ashenvale får näring från uråldriga magiska leyströmmar och ständigt regn och är en av Kalimdors rikaste platser för att samla Briarthorn, Stranglekelp, Kingsblood och sällsynt Gromsblood kring demoniska ärr.",["race:NightElf"]="Ashenvale är din andliga bakgård och Cenarius arv. Att försvara dess lundar mot Warsongs yxor och rensa moonwells från satyrernas fördärv är en fråga om kaldoreis uråldriga heder.",["race:Orc"]="Det här timret blir till själva murarna och belägringstornen i Orgrimmar. Det är också helig mark där Grommash Hellscream spillde blod för att befria orcerna från demoniskt slaveri."},sec={{t="Den viskande trädkronan",b="Ashenvale breder ut sig nedanför Mount Hyjal och har i årtusenden stått under kaldoreis och Cenarius barns vård. Väldiga träd flätas samman till en tät trädkrona som förvandlar det dagliga regnet till ett milt dis och höljder skogsmarken i evig skymning. Uråldriga ruiner från alvernas civilisation sticker upp genom mossan, vaktade av vandrande ancients och dryader. I tusentals år byggde nattalverna inga riktiga städer här, utan föredrog att jaga varsamt och bevara det vilda området i orörd balans."},{t="Kriget om skogen",b="Freden krossades under det tredje kriget, när Grommash Hellscream och Warsong-klanen trängde in i skogen efter timmer och dödade Cenarius efter att ha fallit för demonisk blodtörst. Nu, år 25 efter Dark Portal, har striden blivit ett fullskaligt territoriellt krig. Från Splintertree Post och södra The Mor'shan Rampart driver Warsong Outriders yxor och skogsmaskiner in i de östra skogarna för att förse Orgrimmar. Silverwing Sentinels, med bas i fristadsstaden Astranaar, har svurit att fördriva varenda orcisk skogshuggare från den heliga lunden."},{t="Dröjande skuggor",b="Timmerkriget är långt ifrån Ashenvales enda fara. Burning Legion lämnade ärrade fördärv vid Felfire Hill och Demon Fall Canyon, där Mannoroth mötte sitt slut. Grymma satyrer utgår från ruiner som Satyrnaar och Xavian och fördärvar vattendrag och djurliv. Furbolgstammar, som en gång var alvernas vänner, har till stor del fallit offer för mörk galenskap. Samtidigt smyger mystiska worgen kring den norra helgedomen nära Felwood, och förbannade drakvarelser stryker omkring i Bough Shadow och vaktar en portal till det oroliga Emerald Dream."}},faq={{q="Varför strider Horde och Alliance i Ashenvale?",a="Orcerna i Durotar har nästan inget timmer i sitt torra hemland och behöver desperat Ashenvales virke för att bygga Orgrimmar och försörja sin unga nation. För nattalverna är Ashenvale ett heligt förfädersland som skyddas av naturgudar. Silverwing Sentinels ser Warsong-klanens kalhuggning som en oacceptabel skändning, vilket utlöser ständiga skärmytslingar och den hårda striden i Warsong Gulch.",al={"varför fäller horde träd","orsak till kriget i ashenvale","warsong mot silverwing"}},{q="Vad hände med Cenarius i den här skogen?",a="Under det tredje kriget ledde Grommash Hellscream Warsong-klanen in i Ashenvale för att samla timmer. Cenarius anföll orcerna för att försvara den heliga lunden. I desperation att besegra halvguden drack Grommash och hans klan ur en källa som förorenats av gropfursten Mannoroth. De fick demonisk vrede och dödade Cenarius. Även om Grom senare bröt förbannelsen genom att döda Mannoroth i Demon Fall Canyon, har alverna inte glömt mordet på sin skyddsgud.",al={"hur cenarius dog","grom dödade cenarius","cenarius öde"}},{q="Vad är Blackfathom Deeps?",a="Blackfathom Deeps är ett sjunket tempelkomplex under The Zoram Strand längs Ashenvales nordvästra kust. Det var tidigare ett uråldrigt kaldorei-tempel tillägnat Elune, men sjönk i havet under den stora delningen. Nu har det tagits över av vilda naga, Twilight's Hammer-kultister och vattenlevande bestar som vördar den uråldriga hydran Aku'mai.",al={"var ligger bfd","bfd-lore","blackfathom deeps historia"}},{q="Vad är det stora trädet i Bough Shadow?",a="I Bough Shadow står ett av fyra stora träd som Cenarion Circle planterade för tusentals år sedan för att förankra passager in i Emerald Dream. Det fungerar som en aktiv portal mellan Azeroth och drömmen. Gröna drakspawn vaktar området, men en ondskefull smitta i drömmen driver ibland monstruösa Nightmare Dragons genom portalen.",al={"trädet i bough shadow","portalen i bough shadow","gröna drakar i ashenvale"}},{q="Varför är furbolgerna i Ashenvale fientliga?",a="Nattalverna hade fredliga allianser med furbolgerna i århundraden, men den demoniska smitta som Burning Legion lämnade efter sin invasion krossade deras sinnen. Kvarvarande felmagi från platser som Felwood, Satyrnaar och Demon Fall Canyon drev stammar som Thistlefur till våldsamt vansinne och gjorde dem fientliga mot både främlingar och sina egna.",al={"galna furbolger i ashenvale","thistlefur fördärvade","varför anfaller furbolger"}},{q="Vem ligger begravd i Demon Fall Canyon?",a="Demon Fall Canyon är slagfältet där Grommash Hellscream och Thrall ställdes mot gropfursten Mannoroth. Grom fällde demonherren med ett dödande slag och befriade orcerna från den demoniska blodsförbannelsen, men miste själv livet. Ett monument över Grom Hellscream står där nu, och många orcer vallfärdar dit för att hedra krigaren som befriade sitt folk.",al={"mannoroth canyon","grommash grav ashenvale","monument i demon fall"}},{q="Hur tar jag mig genom Ashenvale?",a="Resande från Alliance kommer oftast in genom bergspasset i norr från Auberdine i Darkshore och följer landsvägen österut mot Astranaar. Äventyrare från Horde marscherar norrut från The Barrens genom den befästa The Mor'shan Rampart mot Splintertree Post, eller västerut till Zoram'gar Outpost vid The Zoram Strand. Båda fraktionerna har flygmästare vid sina större fästen.",al={"hur man tar sig till ashenvale","resa i ashenvale","flygrutter i ashenvale"}}},fx={["97bd7929"]={q="Vad är Ashenvale?",a="Ashenvale är en vidsträckt, uråldrig regnskog söder om Darkshore och Felwood och norr om The Barrens och Stonetalon Mountains. Skogen är nattalvernas förfädershem och har värnats och bevarats av dem i tusentals år. Trädkronorna är så väldiga och täta att ett stilla regn faller nästan oavbrutet, men knappt når skogsmarken. I dag är Ashenvale en omstridd vildmark där forntida andar och Kaldorei Sentinels strider mot timmerexpeditioner som tränger fram, kvarvarande demoner från invasionen och vildsinta bestar.",al={"vad är ashenvale","om ashenvale","berätta om ashenvale","ashenvale-zonen"}},d00ef10f={q="Vad hände med Ashenvale under Third War?",a="Under Third War drabbades Ashenvale av katastrofala omvälvningar. Warsong-klanen under Grommash Hellscream invaderade först för att skörda timmer och provocerade omedvetet halvguden Cenarius. Grom lurades av demonisk påverkan, drack demonblod och dödade Cenarius. Kort därefter invaderade Archimonde och Burning Legion i full styrka, lät infernaler regna över skogen och ryckte fram mot Mount Hyjal. Legionens skräckfurstar släppte lös vidriga farsoter som förvandlade delar av vildmarken till den fördärvade ödemarken Felwood. Demoniska ärr från invasionen finns kvar i skogen än i dag.",al={"ashenvales historia","vad hände i ashenvale","ashenvale under third war"}},["3f2d3290"]={q="Vilka bor i Ashenvale?",a="I årtusenden bevarades skogen som vildmark. Där levde främst skogens djur, dryader, lundens väktare och kännande urgamla varelser, medan kringströvande nattalvernas Sentinels höll uppsikt i stället för att det fanns städer. I dag har nattalverna befästa utposter som Astranaar och Maestra's Post. I öster och längs västkusten har Horde anlagt enklaver som Splintertree Post och Zoram'gar Outpost. I den vilda skogens inre finns furbolgstammar, fientliga satyrer, harpyor och kvarvarande demoniska avkommor.",al={"vilka bor i ashenvale","ashenvales invånare","vilka bor här"}},["24f461e0"]={q="Varför huggs skogen ner?",a="Orcerna i Horde, ledda av Warsong-klanen, behöver timmer till sina bosättningar och för att expandera på Durotars och The Barrens torra slätter. För nattalverna är Ashenvales uråldriga träd och levande urgamla varelser heliga. De ser trädfällning som en oförlåtlig skändning. Varje avverkningsläger och varje såg blir en öppen provokation som tänder ändlösa blodsutgjutelser.",al={"varför fäller de träd","varför avverkar de skog","varför behöver warsong timmer","avskogning i ashenvale"}},d5bfe513={q="Är Ashenvale farligt?",a="Extremt farligt. Vägarna är igenvuxna och höljda i skuggor, och jättelika björnar, rovdjurskatter och vilddjur stryker omkring. Utöver bestarna hemsöker våldsamma satyrer forntida ruiner, korrumperade furbolger angriper alla som kommer nära och områden med brinnande felkorruption hyser demoner. Resenärer måste också hantera det öppna fraktionskriget: Silverwing Sentinels och Warsong Outriders jagar aktivt fiendens spejare genom trädkronorna.",al={"är ashenvale farligt","hur farligt är ashenvale","faror i ashenvale"}},["534156e4"]={q="Vem styr Ashenvale?",a="Ingen enskild makt har odelat herravälde över Ashenvale. Översteprästinnan Tyrande Whisperwind och nattalvernas Sentinels gör anspråk på att förvalta sina förfäders land, leder utposter som Astranaar och vaktar dungarna med vandrande uråldringar. Horden bestrider dock östra Ashenvale hårdnackat genom Warsong-klanen och Splintertree Post, vilket gör skogens hjärta till en bittert omstridd gränstrakt.",al={"vem styr ashenvale","vem bestämmer här","ashenvales ledarskap"}},["0575374f"]={q="Vilka är Sentinels?",a="Sentinels är nattalvernas elitstyrka i stående tjänst, bestående av hängivna kvinnliga krigare, jägare och bågskyttar. De grundades efter De uråldriga kriget och inledde den långa vakten under översteprästinnan Tyrande Whisperwind medan de manliga druiderna sov i The Emerald Dream. De patrullerar skogarna på dödliga panterbestar och med oöverträffad smygförmåga, och fäller alla inkräktare som skändar naturen.",al={"vilka är sentinels","nattalvernas sentinels"}},["42b1a6f5"]={q="Vad är Astranaar?",a="Astranaar är den främsta nattalvbyn i centrala Ashenvale och Alliansens huvudbas i regionen. Den är byggd på en ö mitt i en sjö och nås endast via broar som sträcker sig över skogsvägen. Staden fungerar som handelsplats, fristad och försvarsbastion mot Hordens skoningslösa angrepp och närliggande korrumperade furbolger.",al={"vad är astranaar","staden astranaar","berätta om astranaar"}},["56b6ce63"]={q="Vad är Splintertree Post?",a="Splintertree Post är Hordens befästa fäste i östra Ashenvale. Det grundades efter det tredje kriget och fungerar som den främsta militära utposten som skyddar Warsong-klanens omfattande skogsavverkning vid Warsong Lumber Camp och bevakar vägen söderut mot The Mor'shan Rampart och The Barrens.",al={"vad är splintertree post","splintertree post","horden i splintertree"}},["64786646"]={q="Vilka är satyrerna och var kommer de ifrån?",a="Satyrer är avskyvärda, behornade demoniska humanoider som förvandlats från forntida högborna nattalver. De svor trohet till den brinnande legionen under De uråldriga kriget, med Lord Xavius som den förste. De är svurna fiender till alla kaldorei och lurar i forntida alvruiner som Xavian, Night Run och Satyrnaar. De brukar vidrig skuggmagi och försöker sprida fördärv genom de orörda dungarna.",al={"vad är satyrer","satyrernas ursprung","var kommer satyrerna ifrån"}},e95425a8={q="Vad är The Zoram Strand?",a="The Zoram Strand är en karg kustremsa som utgör Ashenvales nordvästra gräns längs The Veiled Sea. Den var en gång del av alvernas kust före Sunderingen, men är nu full av fientliga naga och murlocker. Där finns också den förstörda ingången till Blackfathom Deeps och Hordens isolerade kustfäste Zoram'gar Outpost.",al={"vad är the zoram strand","the zoram strand","zoram-stranden"}},["273c413f"]={q="Hur hamnade jag i Ashenvale?",a="Din väg hit beror på vem du är lojal mot. Om du strider för Alliansen följde du troligen Sentinel-vägen söderut från Auberdine i Darkshore och kom in under de skuggiga grenarna på väg mot Maestra's Post och Astranaar. Om du rider med Horden marscherade du norrut längs den dammiga Gold Road från The Crossroads i The Barrens och tog dig genom The Mor'shan Ramparts befästa barrikader, rakt in i den täta skogen.",al={"hur kom jag hit","hur tar jag mig till ashenvale","att ta sig till ashenvale"}},["023178b1"]={q="Vad förväntas jag göra i Ashenvale?",a="Du befinner dig i en omstridd vildmark mellan forntida väktare och djärva inkräktare. Alliansens hjältar samlas i Astranaar för att försvara nattalvernas förfäders hemland, slå tillbaka Hordens skogsavverkning, rena korrumperade furbolger och angripa kvarvarande demonsekter. Hordens äventyrare rycker ut från Splintertree Post och Zoram'gar Outpost för att säkra det timmer Durotar så desperat behöver, utöka sitt territorium och överleva skogsandarnas och Sentinels vrede.",al={"varför är jag här","vad gör jag i ashenvale","vad är mitt mål här"}}},fp="9,328,21.445.0,17.489.0,17.472.0,53.389.0,41.434.0,26.315.0,39.340.0,42.344.0,35.325.0,34.374.0"}
P.entries["zone:azshara"] = {n="Azshara",s="Azshara är en karg, vindpinad kuststräcka i nordöstra Kalimdor, täckt av sprakande höstlöv som aldrig faller. Den var en gång en del av den storslagna huvudstaden för nattalverna, innan den Stora Sundringen slet sönder staden och slukade den i havet. Här finns fortfarande en farlig vildmark full av uråldriga ruiner, hotfulla naga och ensliga magiutövare. Både Horde och Alliance håller osäkra utposter längs gränserna och aktar sig för de rastlösa spöken och fasor från havet som lurar därinne.",h="Azshara är en karg, vindpinad kuststräcka i nordöstra Kalimdor, täckt av sprakande höstlöv som aldrig faller.",kw={"azshara","azuregos","bay of storms","coral sea","eldarath","highborne","spitelash","talrendis point","valormok","xylem"},ang={["class:Mage"]="De splittrade stenarna i Eldarath sprakar fortfarande av bortglömd magi från Highborne, och högt ovanför klipporna prövar den tillbakadragne Archmage Xylem dem som söker mästerskap i magisk teleportering och besvärjelser.",["profession:Herbalism"]="Azsharas eviga höstklimat ger näring åt sällsynta och kraftfulla örter, däribland Dreamfoil, Golden Sansam, Mountain Silversage och Purple Lotus bland ruinerna.",["profession:Mining"]="Azsharas branta kustklippor och taggiga bergsryggar är rika på värdefulla mineralådror med stora fyndigheter av Mithril, Truesilver och Thorium.",["race:NightElf"]="Varje dränkt pelare och varje jämrande Highborne-skugga i Azshara är ett dystert, hemsökande vittnesmål om drottning Azsharas vårdslösa arrogans och den forntida kaldoreiska civilisationens katastrofala undergång."},sec={{t="Ett dränkt imperium",b="För tiotusen år sedan var kusten kaldoreiernas civilisations hjärta och omgav den kungliga huvudstaden Zin-Azshari. När drottning Azshara och hennes Highborne-hov lockade Burning Legion till Azeroth kulminerade det följande War of the Ancients i den katastrofala kollapsen av Well of Eternity. Havet dånade inåt och slukade större delen av den magnifika staden, och lämnade efter sig splittrade klippor, förrädiska korallrev och vattenfyllda spiror. De överlevande döpte om det förstörda landskapet efter sin fallna härskarinna och gjorde det till ett förbannat monument över högmod och katastrofalt förräderi."},{t="Höstens prakt och dolda faror",b="Azshara är berömt för sitt fantastiska täcke av karmosinröda, orange och gyllene löv, som ger intrycket av en evig höst utan årstidernas växlingar. Under detta fridfulla lövverk finns dock en ogästvänlig vildmark. Korrumperade satyrer utför mörka ritualer i skogsgläntor, kvardröjande Highborne-uppenbarelser hemsöker dränkta grunder, och Spitelash-naga patrullerar Coral Seas grunda rev. Våldsamma bestar, jättelika hydror och bergsjättar strövar fritt över högländerna och de elfenbensvita stränderna."},{t="De landsförvisades och utstöttas rike",b="På grund av sin isolering och hårda terräng lockar Azshara till sig enstöringar som ägnar sig åt bortglömda konster eller vakar över farliga krafter. Den gåtfulle Archmage Xylem bor i ett avskilt torn högt uppe på klipporna, där han prövar både lovande magiker och listiga skurkar. Längre längs kusten spanar demonjägaren Loramus Thalipedes ut över vågorna från en karg ö, medan den väldige havsjätten Lord Arkkoroc kräver blodsoffer i sitt tempel med utsikt över de upprörda vattnen."}},faq={{q="Varför är alla träden röda och orange här?",a="Azshara är täckt av en evig höst. Det livfulla orange, gyllene och röda lövverket fäller aldrig sina blad, vilket ger kustens skogar en slående vacker men vemodig stämning som har bestått i tusentals år.",al={"varför har azshara evig höst","varför är träden röda","azsharas höstlöv"}},{q="Hur blev Azshara en ruin?",a="Den här kuststräckan utgjorde en gång utkanten av kaldoreiernas huvudstad, Zin-Azshari. Under War of the Ancients imploderade Well of Eternity under den Stora Sundringen, som slet itu kontinenten och fick stora delar av staden att störta i havet.",al={"vad hände med azshara","varför är azshara sönderslitet","azsharas historia"}},{q="Vem styr över Azshara i dag?",a="Ingen enskild fraktion härskar över området. Alliance håller en liten vaktstyrka vid Talrendis Point nära Ashenvale, medan Horde utgår från lägret Valormok. Den omgivande marken domineras av farliga Spitelash-naga, våldsamma satyrer och otämjda monster.",al={"vem kontrollerar azshara","vem styr azshara","är azshara alliance eller horde"}},{q="Vem är Archmage Xylem?",a="Archmage Xylem är en excentrisk mänsklig magiker som bor i ett avlägset torn på en klippa med utsikt över Azshara. Han står utanför regionens politik och hjälper besökande magiker och skurkar att låsa upp sin unika stridsförmåga och magiska potential genom prövande utmaningar.",al={"xylem i azshara","magikertorn i azshara","magiker i azshara"}},{q="Vad gör den blå draken i ruinerna?",a="Den mäktiga blå draken Azuregos och hans avkomma vakar över de uråldriga ruinerna i Eldarath. Han skyddar med våldsam beslutsamhet de kraftfulla magiska artefakter från Highborne som fortfarande ligger begravda i rasmassorna, så att de inte plundras av dödliga.",al={"azuregos i azshara","blå drake i azshara","drake i eldarath"}},{q="Varför anser nattalverna att landet är förbannat?",a="Kaldoreierna anser att Azshara är förbannat eftersom det bär namnet och det arkitektoniska arvet efter deras förrädiska drottning Azshara, vars pakt med Burning Legion krossade deras imperium och förde förödelse över världen.",al={"är azshara förbannat","varför hatar nattalver azshara","nattalvernas förbannelse över azshara"}}},fp="7,220,16.460.0,33.382.0,30.428.0,42.182.0,30.229.0,24.237.0,22.233.0,43.180.0,49.189.0"}
P.entries["zone:badlands"] = {n="Badlands",s="Badlands är en torr, solstekt vidsträckt ödemark med sprucken mark, dammstormar och klippiga raviner mellan Loch Modan och Searing Gorge. Trots att området ligger djupt inne i dvärgarnas Khaz Modan är det en orolig gränstrakt som domineras av Dark Iron-dvärgar, troggs, Dustbelcher-ogrer och häckande svarta drakfolk. Här finns också titanruinerna Uldaman och Hordens fäste Kargath, vilket gör området till en strategiskt viktig knutpunkt.",h="Badlands är en torr, solstekt vidsträckt ödemark med sprucken mark, dammstormar och klippiga raviner mellan...",kw={"angor fortress","badlands","dustbelcher","jordsmidda","goretooth","kargath","lethlor","troggs","uldaman"},ang={["faction:Horde"]="Kargath är din enda militära fristad djupt inne i Khaz Modan och fungerar som frontlinje mot Dark Horde, som ockuperar Blackrock Mountain.",["profession:Mining"]="Det torra landskapet är rikt på järn, guld, äkta silver och mithril. Sällsynta Indurium-fyndigheter finns i Uldaman och den omgivande terrängen.",["race:Dwarf"]="I Uldaman finns svaren på ditt eget ursprung. Upptäckten av titanernas jordsmidda tjänare förändrade dvärgarnas syn på historien."},sec={{t="En karg gränstrakt",b="Badlands ligger inklämt söder om Loch Modans grönskande kullar och övergår snabbt i ett svettigt bäcken av karga slätter och oländig terräng. För att överleva här måste du stå ut med skoningslösa prärievargar, pumor, gamar och våldsamma sandstormar som skymmer horisonten. Över platåerna ligger Dustbelcher-ogrerna utspridda i primitiva läger, medan den hotfulla Dark Iron-klanen befäster Angor Fortress och angriper alla som inkräktar på deras territorium."},{t="Uldamans hemligheter",b="I de norra klipporna ligger Uldaman, ett forntida underjordiskt komplex uthugget av titanernas jordsmidda tjänare. Ironforge-prospektörer har nyligen upptäckt platsen, och utgrävningarna har blottlagt monumentala hemligheter om dvärgarnas forntida ursprung. Men grävandet i de underjordiska valven väckte horder av våldsamma Stonevault-troggs och animerade jordsmidda väktare. De slaktade arkeologiska arbetslag och förvandlade utgrävningsplatserna utanför till blodiga skärmytslingsfält."},{t="Kargaths och Lethlors skuggor",b="Badlands är ett av Hordens mest utsatta fästen i södra Eastern Kingdoms. Fästningen Kargath ligger i nordväst och ger Warchief Thralls styrkor en operationsbas för att hålla uppsikt över den förrädiska Dark Horde i närbelägna Blackrock Mountain. Långt österut ligger Lethlor Ravine, en förrädisk klyfta där svarta drakungar och farliga svarta drakfolk vaktar sina häckningsplatser i bergen skugga."}},faq={{q="Varför är Horden stationerad i Badlands?",a="Utposten Kargath grundades av Kargath Expeditionary Force på order av Warchief Thrall. Under Warlord Goretooths befäl ger lägret Horden en viktig bas för anfall mot Rend Blackhand och hans förrädiska Blackrock-klan, som håller till i Blackrock Mountain.",al={"varför kargath","horden i badlands","vad är kargath"}},{q="Hur tar du dig till Badlands?",a="Alliansens resenärer kan gå rakt söderut från Loch Modan genom passet Maker's Terrace. Hordens resenärer har en längre vandring framför sig: genom de södra kullarna i Loch Modan eller genom Searing Gorge via det västra bergspasset, innan de kan låsa upp Kargaths flygmästare.",al={"ta sig till badlands","hur når man badlands","ingången till badlands"}},{q="Vad är Uldaman?",a="Uldaman är ett enormt underjordiskt valv byggt av de forntida titanerna och deras jordsmidda tjänare. Dvärgprospektörer har nyligen grävt fram platsen i jakten på dvärgarnas ursprung, men utgrävningen väckte begravda jordsmidda konstruktioner och primitiva Stonevault-troggs. Ruinen har förvandlats till ett dödligt slagfält.",al={"vad är uldaman","uldaman grottans historia","vem byggde uldaman"}},{q="Vad gör de svarta drakarna i Lethlor Ravine?",a="Lethlor Ravine är en östlig ravin där den svarta drakflykten fortplantar sig och häckar. Drakar och drakungar vaktar kullen, som utgör ett farligt hot nära bergen. De jagar vandrare och håller obehöriga borta från de östra områdena.",al={"drakar i badlands","drakar i lethlor ravine","svarta drakflykten i badlands"}},{q="Vem kontrollerar Angor Fortress?",a="Angor Fortress innehas av den fientliga Dark Iron-klanen. Fästningen ligger söder om Uldaman och fungerar som en regional bas där Dark Iron utför spaningsuppdrag, utmanar titanernas utgrävningar och strider mot närliggande ogreklaner och upptäcktsresande från ytan.",al={"angor fortress","fästning i badlands","dark iron i badlands"}},{q="Finns det några vänliga bosättningar för alliansspelare här?",a="Nej. Badlands har inga befästa bosättningar eller flygmästare för Alliansen. Prospektörer från Ironforge och enstaka eremiter håller till i utspridda, bräckliga läger nära utgrävningsplatserna, men alliansäventyrare måste förlita sig på baser i Loch Modan eller Searing Gorge för att få ordentliga förnödenheter.",al={"alliansstad i badlands","alliansens flygrutt i badlands","vänliga allierade i badlands"}}},fp="8,296,16.335.0,22.421.0,34.395.0,43.231.0,31.249.0,16.286.0,51.191.0,28.193.0,61.250.0"}
P.entries["zone:barrens"] = {n="The Barrens",s="Över The Barrens håller Hordens utposter vägarna medan rivaliserande styrkor tränger på från alla håll. Kalimdors centrala slätt var en gång skog före den stora klyvningen, men är nu torr mark med rött damm, busksnår och kringströvande vilda djur. The Crossroads är navet för Hordens trafik, men quilboar, centaurer och en krypande korruption hotar dess grepp.",h="Över The Barrens håller Hordens utposter vägarna medan rivaliserande styrkor tränger på från alla håll.",kw={"the barrens","the crossroads","gold road","kolkar","naralex","quilboar","ratchet","taurajo","wailing caverns"},ang={["class:Druid"]="Det förändrade vattnet från Wailing Caverns vittnar om en tragedi: Naralex försök att återställa The Barrens gick om intet på grund av en mardröm.",["class:Shaman"]="Dessa torra slätter sätter ditt band till elementen på prov, från de uttorkade jordarnas andar till det förtrollade vatten som bubblar upp i avlägsna oaser.",["faction:Horde"]="The Barrens är ditt rikes försörjningsväg. Genom att hålla The Crossroads och bevaka karavanerna längs Gold Road hjälper du Orgrimmar och Thunder Bluff att hålla stånd.",["race:Tauren"]="Dina nomadiska förfäder strövade över dessa savanner i generationer innan orcherna nådde Kalimdor. De jagade heligt villebråd och kämpade för att överleva mot de hänsynslösa Kolkar-centaurerna."},sec={{t="Den nya Hordens hjärta",b="I generationer har nomadiska tauren jagat kodo och zhevra över slätterna och utkämpat ett återkommande försvarskrig mot Kolkar-centaurerna. Under det tredje kriget ledde Thrall orcherna till Kalimdor och hjälpte Cairne Bloodhoof att driva tillbaka centaurerna och ta sig över savannen till Mulgore. The Barrens förbinder nu Durotar, Mulgore och Ashenvale. The Crossroads och Camp Taurajo bevakar handeln längs Gold Road, medan orciska gårdar trotsar det hårda klimatet när de bygger ett varaktigt hem."},{t="Ett belägrat land",b="Hordens kontroll över savannen är fortfarande omstridd. Razormane-quilboar, med sina piggsvinsliknande taggar, plundrar gårdar och försörjningsleder från törneomgärdade fästen. Razorfen Krauls hålor tornar upp sig i söder. På östkusten håller styrkor från Theramore Northwatch Hold, medan dvärgiska guldgrävare gräver sig in i titanernas anläggning Bael Modan. Ratchets gobliner håller en osäker neutralitet i handeln och välkomnar resenärer med mynt att spendera."},{t="Den gröna korruptionen",b="Flera oaser bryter upp de norra slätterna, och deras vatten flödar med onaturlig kraft. Källan finns i Wailing Caverns, där nattalvdruiden Naralex försökte nå The Emerald Dream och återställa The Barrens till dess forna skogsskick. En mardröm förvrängde hans vision. Nu rinner förorenat vatten genom The Forgotten Pools och The Stagnant Oasis, där märkliga avvikande växter, onaturliga bestar och de avfälliga Druids of the Fang uppstår."}},faq={{q="Varför finns det lummiga oaser mitt i en öken?",a="The Forgotten Pools och Lushwater Oasis får sitt vatten från underjordiska källor som flödar ut ur Wailing Caverns. Nattalvdruiden Naralex försökte leda källornas vatten genom The Emerald Dream och göra den torra marken grön, men försöket gick snett och fyllde norra The Barrens med stark, oberäknelig naturmagi.",al={"oaser i the barrens","varför finns det vatten i the barrens","vattnet i wailing caverns"}},{q="Vem kontrollerar The Crossroads?",a="Horden bemannar The Crossroads, främst med orciska och taurenska krigare i tjänst hos krigshövding Thrall. Platsen där de viktigaste handelsvägarna möts gör den till Hordens främsta militära knutpunkt och genomfartsnav i centrala Kalimdor, som förbinder Durotar, Mulgore och Ashenvale.",al={"vem styr the crossroads","horden i the crossroads","vakterna i the crossroads"}},{q="Varför attackerar quilboarerna alla?",a="Quilboar gör anspråk på The Barrens som sitt urgamla födslorättsområde. De tror att dess väldiga törnesnår växte ur blodet från deras halvgud Agamaggan under de forntida krigens tid. De ser den anländande Horden och de ursprungliga tauren som inkräktare som tar deras heliga samlingsmarker och jaktområden.",al={"quilboarernas historia","varför är quilboarerna aggressiva","razormanes motiv"}},{q="Varför finns det allianssoldater i The Barrens?",a="Alliansen håller sig till savannens utkanter. Mänskliga trupper från Theramore bemannar Northwatch Hold för att hålla uppsikt över Hordens rörelser, medan dvärgar vid Bael Modan och Bael'dun Keep gräver efter urgamla titanartefakter begravda i de södra kullarna.",al={"alliansen i northwatch hold","dvärgarna i bael modan","alliansen i the barrens"}},{q="Tillhör Ratchet Horden?",a="Nej. Ratchet är en självständig goblinhamn som styrs av Gazlowe. Den välkomnar resenärer från Horden och Alliansen, smugglare och äventyrare för sjöfartshandel, så länge de respekterar goblinernas affärer och håller vapnen i slida inne i staden.",al={"tillhör ratchet horden","ratchets fraktion","gazlowe och ratchet"}},{q="Vad händer med silithiderna i söder?",a="Silithider, insektsliknande varelser, har kommit fram ur jordhålor i södra The Barrens, särskilt kring Field of Giants. Deras plötsliga ankomst och snabbt växande kolonier hotar resenärer och närliggande utposter, och Horden undersöker deras ursprung.",al={"insekter i the barrens","insekter vid field of giants","silithider i södra the barrens"}}},fx={["08031609"]={q="Vad är The Barrens?",a="The Barrens är en vidsträckt, solstekt savann som dominerar centrala Kalimdor. Området omges av låga berg och utgör Hordens territoriella hjärtland, som förbinder Durotar, Mulgore, Ashenvale och områden längre söderut. Här finns mest torra slätter och gräsmarker, men också enstaka oaser som får vatten från underjordiska källor och vidsträckta handelsvägar mellan avlägsna bosättningar.",al={"vad är the barrens","området the barrens","berätta om the barrens"}},d0091816={q="Varför är The Barrens så torrt och öde?",a="För länge sedan var detta område en frodig, grönskande skog som sköttes av nattalverna. För tiotusen år sedan slet den stora Sunderingens katastrofala förödelse och krigen kring den brinnande legionen sönder skogarna. Katastrofer och bränder härjade landskapet, utarmade den bördiga jorden och lämnade efter sig de torra, solbrända slätter vi ser i dag.",al={"varför är området så kargt","varför är det torrt och öde","the barrens ursprung"}},d67a8142={q="Vilka bor i The Barrens?",a="I generationer var nomadiska taurenstammar de främsta invånarna och strövade omkring tillsammans med kodo och zhevra. I dag har Horden större bosättningar som The Crossroads och Camp Taurajo, liksom utspridda orciska jordbrukarfamiljer. På de vilda slätterna bor också fientliga quilboarstammar, Kolkar-centaurklaner, harpior, neutrala gobliner i Ratchet och dvärgiska arkeologiska expeditioner.",al={"vilka bor här","invånarna i the barrens","vilka bor i the barrens"}},["8675aa57"]={q="Är The Barrens farligt?",a="Extremt farligt. Förutom ursinniga inhemska rovdjur som raptorer och åsködlor utsätts resenärer för ständiga räder från Razormane- och Bristleback-quilboarer, som försvarar sina taggiga bon. Härjande Kolkar-centaurer och våldsamma harpior överfaller resenärer längs höjderna, medan Alliansens styrkor och beväpnade dvärgiska utgrävningar utmanar Hordens kontroll över södern.",al={"är the barrens farligt","hot i the barrens","faror i the barrens"}},ba0a3e81={q="Varför skickade Horden mig till The Crossroads?",a="The Crossroads är uppmarschområdet för alla Hordens operationer i centrala Kalimdor. Äventyrare som kommer från Durotar eller Mulgore skickas hit för att stödja försörjningslinjerna, försvara utsatta utposter mot aggressiva lokala stammar och etablera en fast militär närvaro i den vidsträckta vildmarken.",al={"varför skicka mig till the crossroads","varför är jag vid the crossroads","the crossroads syfte"}},["2ec69a3c"]={q="Vad är The Crossroads till för?",a="Platsen fungerar som The Barrens livliga nav för handel och logistik. Den ligger precis där den nord-sydliga Gold Road korsar öst-västvägen mellan Ratchet och Stonetalon Mountains. Här finns viktiga handelsstånd, flygrutter för wyverner och försvarskaserner som förbinder nästan alla Hordens utposter på kontinenten.",al={"vad är the crossroads","vad är the crossroads till för","syftet med the crossroads"}},["23c4dfc8"]={q="Vem byggde The Crossroads?",a="Horden grundade utposten efter det tredje kriget. När Thrall ledde orcherna och Darkspear Trolls i bygget av Durotar och säkrandet av centrala Kalimdor, uppförde de bosättningen där forntida handelsvägar möts. Den skulle säkra deras försörjningslinjer och skydda dem mot kringströvande centaurer och quilboarer.",al={"vem byggde the crossroads","the crossroads ursprung","hur byggdes the crossroads"}},e472d007={q="Vilka är centaurerna och varför hatar de oss?",a="Centaurerna är aggressiva, fyrbenta rövare som har drabbat samman med taurenfolket på dessa slätter i generationer. Stammar som de lokala Kolkar ser andra folkslag som inkräktare eller byten att jaga för nöjes skull. Deras urgamla blodfejder med taurenfolket leder till ständigt blodspillan när deras plundringståg stöter på Horden.",al={"varför hatar centaurerna oss","vilka är centaurerna","centaurernas hot"}},e2564dbf={q="Vad gör harpyorna här ute?",a="Våldsamma fågelhumanoider bygger bon längs The Barrens norra höjder och raviner. De slår till utan förvarning, livnär sig på as och överfaller karavaner som färdas längs vägarna. Under ledare som Serena Bloodfeather utgör deras organiserade räder ett ständigt hot mot Hordens försörjningslinjer genom de norra passen.",al={"harpior i the barrens","varför är harpiorna här"}},["909ebb4b"]={q="Vilka är dvärgarna vid Bael Modan och vad gräver de efter?",a="De är en expedition från Ironforge under General Twinbraid och håller till i det befästa Bael'dun Keep. De gräver fram ett begravt forskningskomplex från titanernas tid djupt under marken i jakt på forntida reliker och historisk kunskap. Deras omfattande användning av sprängpulver och maskiner drev bort de inhemska Stonespire-tauren.",al={"dvärgarna vid bael modan","vad gräver dvärgarna efter","utgrävningsplatsen bael modan"}},["52bcea79"]={q="Varför är Gann Stonespire så arg på dvärgarna?",a="Bael Modan byggdes rakt ovanpå förfädersmark som Stonespire-tauren höll helig. När dvärgarna kom drev de bort eller massakrerade stammen och slet sönder byn med tunga grävmaskiner. Efter att alla diplomatiska försök misslyckats helt beslöt sig Gann för att utkräva blodig hämnd på utgrävningsplatsen.",al={"gann stonespire arg","varför hatar gann dvärgarna","gann stonespire hämnd"}},["918bbb4f"]={q="Vad är Ratchet och varför är gobliner neutrala?",a="Ratchet är en livlig hamnstad vid The Merchant Coast, grundad av Gazlowe efter hans ingenjörsarbete i Orgrimmar. Steamwheedle Cartel driver hamnen strikt för handel och sjöfart med platser som Booty Bay. De håller sig neutrala för att tjäna på handel med alla och välkomnar både Horde- och Alliance-resenärer så länge guldet flödar.",al={"vad är ratchet","varför är goblinerna i ratchet neutrala","ratchets gobliner"}},["50dbd02f"]={q="Vart leder vägarna vidare efter The Barrens?",a="The Barrens fungerar som vägskälet för hela Kalimdor. Leder i norr klättrar genom The Mor'shan Rampart in i Ashenvales täta, omstridda skogar. Bergspass i väster slingrar sig mot Stonetalon Mountains, medan Southern Gold Road leder förbi Camp Taurajo mot Dustwallow Marshs träskmarker och Thousand Needles höga klippor.",al={"vart efter the barrens","nästa zon efter the barrens","vad kommer efter the barrens"}},["06412399"]={q="Vad finns söderut förbi Camp Taurajo?",a="Om du färdas söderut längs Gold Road passerar du Bael Modans väldiga dvärgiska befästningar och kommer in i de omstridda gränslanden. Längre söderut ligger de taggiga fästningarna Razorfen Kraul och Razorfen Downs, följda av The Great Lift, som leder ner i Thousand Needles kanjoner.",al={"söder om camp taurajo","vad ligger söder om taurajo","förbi camp taurajo"}},["9b9beaa0"]={q="Hur hamnade jag i The Barrens?",a="Du följde de naturliga vägarna som leder bort från ditt folks hemländer. Orcs och Darkspear trolls färdades västerut från Durotar och passerade Far Watch Post på andra sidan Southfury River. Tauren tog sig österut genom bergspasset från Mulgore och kom först fram till Camp Taurajo. Resenärer från mer avlägsna trakter, däribland Forsaken och enstaka Alliance-inkräktare, anländer ofta till havs via goblinhamnen Ratchet. Hur du än kom hit breder den vidsträckta savannen ut sig framför dig, mitt i centrala Kalimdor.",al={"hur hamnade jag här","hur kom jag till the barrens","varför är jag i the barrens"}},f4aa7870={q="Vad förväntas jag göra i The Barrens?",a="Som medlem av Horde är du här för att säkra och tämja denna vidsträckta gränsmark. Orcs och tauren har grundat bosättningar som The Crossroads och Camp Taurajo, men de är ständigt belägrade. Du ska driva tillbaka aggressiva Razormane- och Bristleback quilboar, bekämpa centaur-rövare och undersöka det märkliga, förvridna liv som spirar runt öknens oaser. Du måste också hålla utkik efter Alliance-utposter som rycker fram vid Northwatch Hold och Bael Modan, så att hjärtlandet förblir tryggt.",al={"vad ska jag göra här","vad är mitt mål i the barrens","vad gör jag här"}}},fp="11,327,22.499.0,18.441.0,22.440.1,51.304.1,28.279.0,40.290.0,41.217.0,29.221.0,48.281.0"}
P.entries["zone:blackfathom"] = {n="Blackfathom Deeps",s="Blackfathom Deeps är ett översvämmat tempelkomplex under jord längs The Zoram Strand i nordvästra Ashenvale. Den sjunkna helgedomen, som en gång var vigd åt nattalvernas mångudinna Elune, har tagits över av kulten Twilight's Hammer, förrädiska naga och satyrer. De samlas i dess mörka vatten för att vörda Aku'mai, en uråldrig hydra och tjänare till en Old God.",h="Blackfathom Deeps är ett översvämmat tempelkomplex under jord längs The Zoram Strand i nordvästra Ashenvale.",kw={"aku'mai","bfd","blackfathom","djupen","gelihast","ghamoo-ra","kelris","sarevess","zoram"},ang={["class:Shaman"]="Schamaner som hörsammar Je'neu och Earthen Ring måste dyka ner i det mörka vattnet för att hejda elementens fördärv och driva bort Old Gods kaotiska smitta.",["faction:Alliance"]="Alliansens hjältar tar sig in för att rädda spejaren Scout Thaelrid, återfinna förlorad högbornekunskap och hjälpa nattalverna att rena sitt heliga hemland från kultisternas terror.",["faction:Horde"]="Från Zoram'gar Outpost försöker Horden säkra Ashenvales norra kust mot naga som tränger sig på och hindra de mörka ritualerna i djupet från att hota deras utposter.",["race:NightElf"]="För nattalverna är djupen en smärtsam vanhelgning av deras arv. En uråldrig helgedom åt Elune och dess heliga månkällare har besudlats av voidkultister och monstruösa varelser."},sec={{t="Elunes sjunkna helgedom",b="Långt innan den stora Sunderingen krossade det forntida Kalimdor var komplexet ett storslaget tempel tillägnat Elune. Högborne-murare reste broar täckta av ädelstenar medan drottning Azshara styrde vattnen omkring dem och skilde saltvatten från bergsbäckar runt en helig månkällare. När Sunderingen slet sönder världen för tiotusen år sedan sjönk templet ner i Veiled Seas kustdjup. I årtusenden låg det ostört under vågorna, tills otäcka viskningar började sippra upp ur mörkret under jord."},{t="En håla full av uråldriga fasor",b="Lockade av vansinniga drömmar och mörka järtecken samlades kulten Twilight's Hammer vid de sjunkna ruinerna. Där slöt de en ohelig vapenvila med kustens naga, ledda av Lady Sarevess, och kringströvande satyrer. Tillsammans vanhelgade de månkällaren och förslavade traktens liv. De drev den jättelika havssköldpaddan Ghamoo-ra till vansinne genom åratal av plåga, lät den brutale murlocken Gelihast resa ett blodaltare och fyllde de väldiga grottdjupen med nya offer. Under Twilight Lord Kelris ledning gjorde kultisterna ruinerna till en samlingsplats inför Old Gods förestående återkomst."},{t="Odjuret i djupet",b="Längst inne i det sjunkna templet ligger Aku'mai, en uråldrig hydra med tre huvuden och tjänare till en Old God. Den steg upp ur vattnet när den gudens fördärv smittade templets månkällare. Twilight Lord Kelris och hans kultister offrar oskyldiga åt odjuret för att få makt. Om du fäller Kelris och tänder ritualens ljus i hans helgedom öppnas vägen till odjurets lya, där hjältar kan dräpa Aku'mai innan dess ondska sprider sig över Kalimdor."}},faq={{q="Vad var Blackfathom Deeps innan platsen föll i mörker?",a="Ursprungligen var det ett magnifikt nattalvstempel tillägnat mångudinnan Elune. Där fanns kristallklara bassänger, broar med ädelstenar och en välsignad månkällare. Drottning Azshara vakade över allt innan den stora Sunderingen bröt sönder templet och sänkte det under havet.",al={"bfd historia","vem byggde bfd","ursprungligt tempel"}},{q="Varför är kultisterna från Twilight's Hammer här?",a="Lockade av mardrömssyner och viskande röster från djupet under Azeroth kom kultisterna för att dyrka Old Gods. Under Twilight Lord Kelris tog de över de sjunkna ruinerna för att fostra Aku'mai. De offrar levande i hopp om att påskynda sina kaotiska mästares återkomst.",al={"kultister i bfd","varför är twilight's hammer här","vad vill kultisterna"}},{q="Vem är Twilight Lord Kelris?",a="Twilight Lord Kelris leder Twilight's Hammer-cellen i Blackfathom Deeps. Han vill få Old Gods att återvända och styr kultens offer till Aku'mai. Han övervakar också templets vanhelgande.",al={"vem är kelris","kelris historia","ledare för bfd"}},{q="Vad gör naga och satyrer i ruinerna?",a="Både naga och satyrer lockades till det dränkta templet av kvarvarande uråldrig magi. Naga, ledda av Lady Sarevess, slöt ett avtal med Twilight's Hammer: kultisterna ger henne fångar och mörk kunskap, och i gengäld skyddar hennes sjöhäxor dem med magi mot fasorna som lurar i djupet.",al={"varför är naga här","varför satyrer i bfd","lady sarevess"}},{q="Varför bryr sig Earthen Ring och Argent Dawn om den här platsen?",a="Argent Dawn skickade spejaren Scout Thaelrid för att undersöka misstänkta allianser mellan naga och kultister. Han fann bevis på deras mordiska ritualer. Samtidigt skyndade Earthen Ring till Ashenvale, eftersom åkallan av Old Gods hotar elementens balans och hela världens trygghet.",al={"earthen ring ashenvale","argent dawn bfd","scout thaelrid"}},{q="Vad händer när Aku'mai besegras?",a="När Aku'mai dräps förlorar Old Gods sitt omedelbara fysiska fäste i Ashenvale. Kulten kan inte längre hoppas använda den uråldriga hydran för att återupprätta Old Gods välde. Det är ett hårt slag mot Twilight's Hammer och renar en del av den mörka smitta som fördärvar den förstörda månkällaren.",al={"vad händer när aku'mai dödas","aku'mais slut","efter att slutbossen dödats"}}},fx={["45e74127"]={q="Vad är Blackfathom Deeps?",a="Blackfathom Deeps är ett vidsträckt, delvis översvämmat komplex av underjordiska grottor under The Zoram Strand i nordvästra Ashenvale. Det var en gång en uråldrig fristad för nattalver, men dess översvämmade gångar och marmorsalar har tagits över av ondskefulla krafter. I dag är det ett förvridet fäste under jord, där mörka kultister, ormformade naga och förvridna vattenvarelser samlas kring en helgedom tillägnad de kaotiska Old Gods.",al={"vad är bfd","vad är blackfathom","om blackfathom deeps"}},["0e7de610"]={q="Varför ligger Blackfathom Deeps under vatten?",a="För tiotusen år sedan slet den katastrofala Great Sundering sönder det forntida Kalimdor och krossade den omgivande kusten. Tempelkomplexet sjönk under Veiled Seas vatten när landet gav vika. Under årtusendena slukade havet de flesta av dess nedre salar och gårdar, och förvandlade de majestätiska promenaderna till ett översvämmat nätverk av underjordiska grottor och tidvattensgrottor.",al={"varför är det översvämmat","varför ligger bfd under vatten","hur sjönk det"}},["55d79134"]={q="Vem är Aku'Mai?",a="Aku'mai är en monstruös, uråldrig hydra med tre huvuden och en tjänare till en Old God. När den Old Gods fördärv trängde upp ur marken och besmittade templets heliga Moon Well steg Aku'mai upp ur vattnet och lurar nu i ruinernas djupaste grotta. Twilight's Hammer dyrkar besten och offrar oskyldiga till den för att få makt.",al={"vem är akumai","vad är akumai","hydra-boss i bfd"}},["10cbfa4e"]={q="Lever Aku'Mai fortfarande där nere?",a="Ja. Aku'mai lever i sitt underjordiska näste i ruinernas hjärta. Kultisterna i Twilight's Hammer vaktar den monstruösa hydran och offrar tillfångatagna oskyldiga till den i utbyte mot mörk makt.",al={"lever akumai","sover akumai","är akumai fortfarande där nere"}},cc477b61={q="Vem dyrkar Aku'Mai?",a="Aku'mai dyrkas av den fanatiska kulten Twilight's Hammer, som leds i ruinerna av Twilight Lord Kelris. De vördar hydran som en tjänare till sina mörka herrar och tror att den kan stärkas för att återupprätta tiden då Old Gods härskade över världen.",al={"vem dyrkar akumai","akumais dyrkare","kultister som dyrkar akumai"}},e60c1e85={q="Varför verkar alla så oroliga för den här platsen?",a="Närhelst Old Gods åkallas hotar en allvarlig fara hela Azeroth. Yttre fraktioner som Argent Dawn och The Earthen Ring förstår att samlingen av kultister, naga och satyrer under en mörk fana förebådar katastrofalt kaos. Kultens ritualer, offer och dyrkan av Aku'mai fördärvar vattnen omkring dem och hotar att sprida vansinne över Ashenvale.",al={"varför oroa sig för bfd","varför är blackfathom farligt","hotet från blackfathom"}},b8724226={q="Varför finns det både naga och murlocs i samma ruiner?",a="Båda drogs till de mörka energier som vaknade i ruinerna. Naga steg upp ur havet för att utforska det uråldriga tempelkomplexets krossade kraft och slöt en ondskefull pakt med kulten. Samtidigt hörsammade murlockrigaren Gelihast de Old Gods kallelse, kämpade sig in och vann kultens respekt genom rå brutalitet.",al={"varför naga och murlocs","murlocs i bfd","naga i bfd"}},cd1d34a5={q="Varför just jag? Varför skicka in en främling i stället för en armé?",a="Att marschera in med en armé i de sjunkna, översvämmade grottorna vore en logistisk mardröm, och fraktioner som Argent Dawn arbetar i det tysta genom spejare för att inte varna kulten. Deras hemliga spejare, Thaelrid, överfölls och sårades dödligt i salarna. Tiden håller på att rinna ut, så de förlitar sig på kapabla och diskreta hjältar som du för att fälla Kelris innan kultens planer bär frukt.",al={"varför skicka äventyrare","varför inte skicka en armé","varför jag i bfd"}},f5e67a9b={q="Vad händer sedan om jag dödar Kelris?",a="Kelris död röjer inte genast grottorna. När du besegrar honom lämnar han efter sig fyra ceremoniella altarljus i sin helgedom. Om du tänder ljusen bryts sigillen som håller helgedomens mörka skydd på plats. Då anfaller vågor av kultens försvarare och den väldiga stendörren öppnas, med en passage rakt in i Aku'mais inre näste.",al={"efter att kelris dödats","vad händer om jag dödar kelris","vad händer när kelris dör"}},f0f9473c={q="Hur hamnade jag i Blackfathom Deeps?",a="Du följde rykten om uråldrigt mörker till den dimhöljda The Zoram Strand i nordvästra Ashenvale. Bland ruinerna längs stranden leder en trappförsedd brunn ner i jorden, och du måste dyka genom översvämmade tunnlar för att nå dessa dränkta salar. Oavsett om nattalverna i Darnassus skickade dig för att leta efter försvunna spejare, om shamanska The Earthen Ring vägledde dig för att undersöka växande elementärt fördärv eller om du följde viskningar om kultister som samlats under vågorna, ledde din väg rakt in i den nedsänkta helgedomen.",al={"hur hamnade jag här","hur tar jag mig in här","hur hittade jag den här platsen"}},["39220d00"]={q="Vad förväntas jag göra i Blackfathom Deeps?",a="Du är här för att rensa det uråldriga templet från ondskan som frodas där inne. Kulten Twilight's Hammer, vägledd av Twilight Lord Kelris, har slutit sig samman med lokala naga och satyrer för att dyrka och föda den urtida besten Aku'mai. För att stoppa deras dystra ritualer måste du slå ut kultens ledare, sätta stopp för naga-trolldomen som förgiftar vattnet och ta dig till den lägsta helgedomen för att dräpa den monstruösa hydran innan Old Gods tjänare släpper lös kaos över Azeroth.",al={"vad gör jag här","varför är jag här","vad är mitt mål här","vad är mitt uppdrag här"}}},fp="17,259,23.451.0,24.522.0,21.435.1,56.272.0,44.252.0,28.187.0,47.268.0,62.267.0,38.268.1"}
P.entries["zone:blastedlands"] = {n="Blasted Lands",s="Blasted Lands är en ödslig vidsträckt trakt av röd lera och karg klippa vid den sydöstra spetsen av Eastern Kingdoms, förödd av Dark Portals kaotiska energier. Området var en gång en del av det grönskande Black Morass, men den splittrade jorden hyser nu rester av Burning Legions demoner, brutala Dreadmaul-ogrer och tåliga ökendjur. Nethergarde Keep vakar över den öde ödemarken och skyddar Azeroth mot fasor som kan strömma ut ur den slumrande porten.",h="Blasted Lands är en ödslig vidsträckt trakt av röd lera och karg klippa vid den sydöstra spetsen av Eastern...",kw={"black morass","blasted lands","the dark portal","drazial","dreadmaul","gromsblood","kum'isha","lord kazzak","lynnore","nethergarde keep","razelikh","the tainted scar"},ang={["class:Mage"]="Magikerna i Nethergarde Keep står för den stränga, defensiva tillämpningen av arkana krafter och håller vakt mot felkorruption och dimensionssprickor som lämnats efter Medivhs fall.",["class:Warlock"]="The Tainted Scar myllrar av högt uppsatta demoner och Daio the Decrepit håller till bland klipporna. Det öde landet erbjuder erfarna trollkarlar enastående möjligheter att binda farliga felvarelser.",["faction:Alliance"]="Nethergarde Keep är din enda befästa tillflykt i regionen och skyddar rikets södra delar mot fasor som kan hota Duskwood och Stormwind.",["faction:Horde"]="Horde har ingen fästning här, men ruinerna av Dark Portal står som ett dystert minnesmärke över den gamla Hordes överfart och förödelsen som demonisk korruption orsakat.",["profession:Herbalism"]="Den torra röda leran är en av de ytterst sällsynta naturliga miljöer där Gromsblood växer."},sec={{t="Ett sargat ödeland",b="Före det första kriget var regionen en fortsättning på de täta sankmarkerna som kallades Black Morass. Den frodiga våtmarken utplånades helt när trollkarlen Gul'dan och den besatte Medivh slet upp Dark Portal för att släppa lös orchernas Horde. Kaotiska felenergier läckte genom dimensionssprickan, sög bort all fukt och brände jorden till sprucken röd lera. När Dark Portal senare förstördes i slutet av det andra kriget skållade katastrofala chockvågor terrängen ännu mer och förvandlade den inhemska stenen till dess overkliga karmosinröda färg."},{t="Nethergardes ensamma vakt",b="Nethergarde Keep ligger på de norra klipporna och vakar över den enda vägen in i dalen. Fästningen byggdes på uppdrag av ärkemagikern Khadgar och Kirin Tor efter det andra kriget. Den bemannas av stränga magiker och ståndaktiga soldater som svurit att hindra nya demoniska eller orchiska angrepp. Det är en ogästvänlig postering med sträng disciplin; garnisonens regelbrytare straffas med förvisning till The Stockade i Stormwind. Försvararna utsätts för ständiga angrepp från Dreadmaul-ogrerna, som stannade kvar efter Draenors fall och nu plundrar vägarna och angriper fästningens portar under ondskefull ledning."},{t="Legionens kvarleva",b="I sydväst ligger The Tainted Scar, en kraterfylld kanjon som myllrar av kontinentens farligaste demoner. Befälhavaren Lord Kazzak blev kvar efter nederlaget vid Mount Hyjal och samlar kringströvande demoner, doomguards och felhundar under sitt baner. Högt ovanför de röda ödemarkerna styr hans dreadlordlöjtnant Razelikh the Defiler de dödligas tjänstgöring bland kultisterna Shadowsworn vid Altar of Storms och befaller de lokala Dreadmaul-ogrerna."},{t="Blodets kraft",b="Trots ödemarkens karghet trotsar lärda och vandrare dess fasor för att göra unika upptäckter. Strax innanför det norra passet utför Bloodmage Drazial och Bloodmage Lynnore excentriska alkemiska experiment. De utvinner organ ur traktens skorpioner, basilisker och vildsvin för att brygga ovanligt kraftfulla kroppsförstärkande elixir. Längre in i ödemarken söker en ensam draenei-eremit vid namn Kum'isha utspridda draenethystfragment. Han belönar resenärer som återfinner dessa främmande lämningar från Draenors splittrade förflutna."}},faq={{q="Varför är marken röd och karg?",a="Blasted Lands var en gång en del av det sumpiga Black Morass. När Dark Portal öppnades tömde rå demonisk magi regionen på liv och fukt. När Dark Portal senare förstördes förvandlade den brännande hettan och de kaotiska energierna från förstörelsen leran till hård karmosinröd jord.",al={"varför är blasted lands rött","varför är det dött","vad hände med träsket"}},{q="Vad är Dark Portal?",a="Dark Portal är en väldig dimensionsport byggd för att förbinda Azeroth med Draenor, orchernas splittrade hemvärld som nu kallas Outland. Portalen förstördes för att kapa förbindelsen mellan världarna, men dess väldiga stenram står fortfarande kvar och bevakas ständigt av Nethergarde Keep.",al={"vart leder dark portal","är portalen öppen","vad är porten"}},{q="Vem styr Nethergarde Keep?",a="Nethergarde Keep är en alliansfästning som övervakas av magiker från Kirin Tor och soldater trogna Stormwind. Den byggdes efter det andra kriget under ärkemagikern Khadgars ledning. Garnisonen håller sträng och dyster vakt över Dark Portal och slår tillbaka attacker från närliggande ogre och demoner.",al={"vem styr nethergarde","är nethergarde alliansens","nethergardes magiker"}},{q="Vad är The Tainted Scar?",a="The Tainted Scar är en demonfylld kanjon i södra Blasted Lands. Den fungerar som tillflykt för Burning Legions kvarvarande styrkor i Eastern Kingdoms, ledda av den mäktige doomguarden Lord Kazzak och befolkade av doomguards, felguards och felhundar.",al={"eliter i tainted scar","vilka finns i tainted scar","demonernas dal i blasted lands"}},{q="Vilka är blodalverna som slagit läger nära ingången?",a="Bloodmage Drazial och Bloodmage Lynnore är forskare som undersöker hur den förvridna faunan har anpassat sig till det hårda felpåverkade landskapet. I utbyte mot inälvor, hjärnor och lungor från traktens basilisker, gamar, skorpioner och vildsvin brygger de kraftfulla elixir som stärker dödligas egenskaper.",al={"blodalvernas förstärkningsdrycker","drazial och lynnore","vildsvinslungor uppdrag"}},{q="Vem är Kum'isha the Collector?",a="Kum'isha är en gåtfull draenei-mystiker som bor i ödemarkens mitt. Han samlar på draenethystfragment och sfärer, kristallina lämningar från Draenor, och byter till sig förseglade paket med sällsynt utrustning och varor av alla som kommer med dem.",al={"draenei i blasted lands","kumisha","draenethyst-uppdrag"}},{q="Hur tar du dig till Blasted Lands till fots?",a="Färdas genom Deadwind Pass österut till Swamp of Sorrows. Följ huvudvägen söderut genom Swamp of Sorrows, förbi Horde-bosättningen Stonard, tills du når det smala bergspasset som leder rakt in i Blasted Lands röda lera.",al={"ta sig till blasted lands","hur kommer man dit","ingången till blasted lands"}},{q="Varför bor det ogre i öknen?",a="Dreadmaul-ogrerna tog sig genom Dark Portal under det andra kriget. I stället för att dra sig tillbaka genom portalen befäste de sig i Dreadmaul Hold och föll under dreadlorden Razelikhs och kulten Shadowsworns herravälde.",al={"dreadmaul-ogrerna i berättelsen","varför är ogre här","dreadmaul hold"}}},fp="13,202,19.450.0,26.499.0,20.387.0,22.443.0,33.247.0,24.237.0,30.250.0,25.239.0,50.267.0,30.205.0,43.184.0,41.237.0"}
P.entries["zone:burningsteppes"] = {n="Burning Steppes",s="Burning Steppes är ett förkolnat, vulkaniskt ödemarkområde vid foten av Blackrock Mountain i söder. Det skapades när Ragnaros kallades till Azeroth för århundraden sedan och rymmer den främsta landvägen mellan Stormwind och Khaz Modan. I dag kryllar det av Blackrock-orcher, Firegut-ogrer, Dark Iron-dvärgar och yngel från den svarta drakflykten.",h="Burning Steppes är ett förkolnat, vulkaniskt ödemarkområde vid foten av Blackrock Mountain i söder.",kw={"anduin lothar","blackrock-klanen","blackrock mountain","blackrock spire","burning steppes","doomhammer","flame crest","morgan's vigil","ragnaros","thaurissan"},ang={["faction:Alliance"]="Burning Steppes är en dyster och farlig gränstrakt där överbefälhavaren Anduin Lothar föll. Marshal Maxwell vid Morgan's Vigil söker ständigt modiga hjältar som kan hejda hoten på väg mot Redridge.",["faction:Horde"]="Thralls nya hord vakar oroligt över Flame Crest och är fast besluten att tygla den farliga, obotfärdiga Blackrock-klanen, vars krigshets fläckar orchernas heder.",["profession:Mining"]="Det vulkaniska landskapet är rikt på sällsynta mineraler. Det är en av få utomhusregioner på Azeroth där du kan utvinna värdefulla Dark Iron-fyndigheter och rika thoriumådror.",["race:Dwarf"]="Varje sten i stäpperna vittnar om Dark Iron-klanens dårskap under kriget mellan de tre hamrarna, som kulminerade i att deras huvudstad krossades och Ragnaros kallades till Azeroth."},sec={{t="Ett katastrofalt ursprung",b="För länge sedan var dessa bergssluttningar bara den norra delen av Redridge Mountains. Under kriget mellan de tre hamrarna grundade den landsförvisade Dark Iron-klanen sitt rike här och byggde huvudstaden Thaurissan. När nederlaget mot Bronzebeard- och Wildhammer-klanerna verkade oundvikligt försökte den desperata trollkarlen Thaurissan frammana elementarkrafter. I stället krossade han marken och kallade Ragnaros eldherren till Azeroth. Den våldsamma explosionen krossade bergen runtomkring, öppnade floder av lava och skapade den väldiga vulkanen Blackrock Mountain. Stäpperna blev för alltid förkolnade och karga."},{t="Ekon från det andra kriget",b="Under det andra kriget gjorde den gamla horden Blackrock Spire till sitt främsta maktsäte. Mot konfliktens slut trängde Lordaerons stora allians djupt in i Burning Steppes för att belägra berget. Vid foten av Blackrock Mountain drabbade krigshövdingen Orgrim Doomhammer samman med lord Anduin Lothar och fällde människornas mästare. Lothars död bröt inte alliansens beslutsamhet. I stället eggades de allierade arméerna till att driva bort orcherna, vilket beseglade det andra krigets utgång och lämnade efter sig en bestående dal av aska och rostigt stål."},{t="En håla för monster och drakar",b="Thrall grundade en ny hord i avlägsna Kalimdor, men Blackrock-klanen som blev kvar i stäpperna håller fast vid den gamla hordens blodtörstiga grymhet. Från Blackrock Stronghold samarbetar de öppet med den svarta drakflykten och de lokala Firegut-ogrerna i stället för att hålla någon vapenvila. Dark Iron-dvärgar och elementartjänare lurar bland de brinnande ruinerna. Samtidigt jagar svarta drakar och drakfolket oförsiktiga resenärer som försöker ta vägen mellan Stormwind och de norra rikena."}},faq={{q="Varför är marken förkolnad och täckt av lava?",a="För århundraden sedan försökte Dark Iron-trollkarlen Thaurissan frammana en elementartjänare som skulle rädda hans klan från nederlag i kriget mellan de tre hamrarna. Hans besvärjelse bröt av misstag igenom till elementarplanet och kallade Ragnaros eldherren. Den slet upp marken, skapade den väldiga vulkanen Blackrock och förvandlade norra Redridge Mountains till ett förkolnat ödemarksområde.",al={"varför brinner det","vad hände med burning steppes","varför är blackrock mountain en vulkan"}},{q="Tillhör orcherna här Thralls hord?",a="Nej. Orcherna i Burning Steppes är rester av Blackrock-klanen som vägrar ansluta sig till Thralls nya hord. De respekterar inte vapenvilan med alliansen och håller fast vid de vilda, krigshetsande traditionerna från det första och andra kriget. De tjänar Blackrock Spire och den svarta drakflykten.",al={"är det här thralls orcher","tillhör blackrock-orcherna horden","varför är orcherna fientliga här"}},{q="Var dog Anduin Lothar?",a="Anduin Lothar dödades av krigshövdingen Orgrim Doomhammer vid foten av Blackrock Mountain i Burning Steppes, mot slutet av det andra kriget. Lothars död fick hans andreman Turalyon och alliansens styrkor att gå till våldsam motattack och krossa hordens linjer.",al={"var dödades lothar","var lothar dog","duellen mellan orgrim doomhammer och lothar"}},{q="Var kan alliansen hitta skydd i stäpperna?",a="Alliansens soldater och resenärer håller till vid Morgan's Vigil, en upphöjd utpost i områdets sydöstra bergssluttningar. Marshal Maxwell leder stationen, bevakar det norra passet och håller uppsikt över fiendens truppförflyttningar kring berget.",al={"alliansens bas i burning steppes","var finns alliansens flygrutt","var ligger morgan's vigil"}},{q="Var samlar horden sina styrkor här?",a="Hordens äventyrare beger sig till Flame Crest, ett upphöjt läger längs den nordöstra bergskammen. Härifrån bevakar sändebud den rivaliserande Blackrock-klanen och håller flygförbindelser till Badlands, Swamp of Sorrows, Searing Gorge och Riverglades.",al={"hordens bas i burning steppes","flame crest","var ligger hordens stad"}},{q="Vad är Ruins of Thaurissan?",a="Ruins of Thaurissan är resterna av den storslagna stad som Dark Iron-klanen byggde efter sin landsförvisning från Ironforge. När Thane Thaurissan kallade Ragnaros förstörde den råa elementarkraften hans huvudstad och förslavade de överlevande till eldherrens vilja.",al={"thaurissans ruiner","vad är den förstörda dvärgastaden","ruiner mitt på kartan"}}},fp="15,216,20.517.0,24.428.0,29.389.0,46.338.0,42.250.0,28.268.0,51.237.0,43.237.0,33.248.0"}
P.entries["zone:darkshore"] = {n="Darkshore",s="Darkshore är en kall, dimhöljd kustremsa längs nordvästra Kalimdor, beströdd med forntida Kaldorei-ruiner och oroligt djurliv. Med Alliancens hamnstad Auberdine som ankare fungerar området som den främsta vägen in på kontinenten för resenärer från Teldrassil och Eastern Kingdoms. Bortom den patrullerade vägen hotar demoniska kulter, framryckande naga och en krypande korruption från högländerna regionens sköra balans.",h="Darkshore är en kall, dimhöljd kustremsa längs nordvästra Kalimdor, beströdd med forntida Kaldorei-ruiner och...",kw={"ameth'aran","auberdine","bashal'aran","blackwood den","cliffspring falls","darkshore","the master's glaive","onu","tower of althalaxx"},ang={["class:Druid"]="Darkshore är frontlinjen för Cenarion Circle-adepter som svarar på kallelser från Moonglade för att undersöka förgiftade vattendrag och brygga renande medel åt sjuka skogsdjur.",["faction:Alliance"]="Auberdine är Alliancens främsta handelsknutpunkt i norra Kalimdor och upprätthåller den direkta sjöförbindelsen mellan Stormwind och Ironforge och nattalvernas huvudstad Darnassus.",["faction:Horde"]="Darkshore är en avlägsen, hårt bevakad bastion för Alliansen, belägen rakt norr om hordens läger i Ashenvale. Den farliga kustlinjen patrulleras av fientliga Sentinel-vakter och farliga kulter.",["race:NightElf"]="För unga nattalver som lämnar Teldrassil är Darkshore deras första steg ut på Kalimdors fastland, där de möter sin forntida civilisations smärtsamma ruiner och vildmarkens spridande korruption."},sec={{t="Ett land av dimma och minnen",b="Darkshore sträcker sig under de västra skuggorna från Mount Hyjal och Felwood, och präglas av tallskogar, havsdimma och klippiga stränder som piskas av kalla vågor. För årtusenden sedan låg de blomstrande Kaldorei-tvillingstäderna Ameth'Aran och Bashal'Aran längs den här kusten. De krossades under den stora delningen, och deras pelarskelett och marmorvalv ligger nu halvt dränkta i bränningarna eller övervuxna av rötter, hemsökta av oroliga Highborne-andar och översvämmade av asätande murlocs och invaderande naga."},{t="Auberdines fristad",b="Efter det tredje kriget och planteringen av Teldrassil grundade nattalverna Auberdine som en livlig hamnstad mitt i vildmarken. Auberdine har träbryggor där fartyg regelbundet lägger till från Rut'theran Village, Stormwind Harbor och, via Southshore, Menethil Harbor i det avlägsna Wetlands. Staden är livlinan som förbinder nattalvernas område med resten av Alliansen. Sentinel-vakter patrullerar flitigt handelsvägen söderut mot Ashenvale, men den lilla garnisonen har svårt att hålla ordning i den djupa vildmarken bortom vägen."},{t="Förgiftade vatten och viskande djup",b="Trots skyddet från bergen i öster plågas Darkshore av en långsam, ondskefull förruttnelse. Förorenat avrinningvatten från Felwood sipprar ner och förgiftar källor som Cliffspring Falls, förorenar grundvattnet och driver traktens björnar, hjortar och furbolgs från Blackwood Den till våldsamt vansinne. Än värre är att onda organisationer har etablerat fästen i skuggorna: Dark Strand och Twilight's Hammer-kultisterna utför avskyvärda ritualer vid Tower of Althalaxx och samlas kring det skräckinjagande, forntida monumentet som kallas The Master's Glaive."}},faq={{q="Hur tar jag mig till Darkshore?",a="Alliansspelare kan ta en båt till Auberdine från Rut'theran Village vid foten av Teldrassil, direkt från Stormwind Harbor eller från Menethil Harbor i Wetlands via Southshore. Horderesenärer som färdas norrut måste gå genom Ashenvale och följa huvudvägen nordost från Zoram'gar Outpost över gränsen.",al={"ta sig till darkshore","hur man tar sig till auberdine","båt till darkshore"}},{q="Vad är det för fel på djurlivet och furbolgs?",a="Floder som rinner från Felwoods förgiftade höjder, till exempel Cliffspring River, för med sig demonisk förorening rakt ner i Darkshores grundvatten. När de inhemska furbolgstammarna dricker ur de vidriga vattendragen blir de vilda, och traktens hjortar och rovdjur drabbas av sjukdom och aggression.",al={"varför är djuren sjuka","furbolgkorruption","förorening i darkshore"}},{q="Vad hände med Ameth'Aran och Bashal'Aran?",a="De var blomstrande Kaldorei-tvillingstäder som förstördes för tiotusen år sedan under den stora delningen. Deras härskare, Athrikus Narassin, hävdade att han skulle rädda sitt folk från katastrofen, men band i stället deras själar i ädelstenar för att bevara dem som eviga kraftkällor åt sig själv. Ruinerna lämnades fulla av gråtande spöken.",al={"ameth'aran historia","bashal'aran berättelse","ruiner i darkshore"}},{q="Vad är The Master's Glaive?",a="I södra Darkshore står The Master's Glaive, en enorm förstenad skalle genomborrad av ett jättelikt stenande vapen. Det är en forntida relik med koppling till de ursprungliga Old Gods och deras tjänare, och lockar nu till sig farliga kultister från Twilight's Hammer.",al={"vad är the master's glaive","jätteskalle i darkshore","monster vid master's glaive"}},{q="Vem är det jättelika trädet i Grove of the Ancients?",a="Det är Onu, en vis och vördnadsvärd Ancient of Lore. Han vilar i sin fridfulla lund söder om Auberdine och begrundar Twilight's Hammer-kultens oroande intrång. Han hjälper också resenärer att undersöka störningar i skogen.",al={"ancient of lore i darkshore","vem är onu","trädperson i darkshore"}},{q="Vem bor i Tower of Althalaxx?",a="Tornet hålls av Dark Strand, en grym kult som utövar mörk trolldom och åkallar demoniska väsen. Deras sammansvurna överfaller aktivt oförsiktiga resenärer i de norra delarna av kustskogen.",al={"tower of althalaxx","kultister i darkshores torn","althalaxx-kult"}}},fx={f41ff152={q="Vem styr Auberdine?",a="Auberdines civila angelägenheter leds av äldsten Thundris Windweaver, med stöd av Auberdine Village Council. Stadens militärvakt sköts av Sentinels, med officerare som Sentinel Glynda Nal'Shea, som samordnar lokala patruller och försvaret.",al={"ledare i auberdine","vem bestämmer i auberdine","auberdine village council"}},["5f65caea"]={q="Varför byggdes staden vid kusten?",a="När nattalverna återvände efter det tredje kriget valde de den här platsen för att återuppliva sjöfarten och försörjningslederna. Hamnen erbjuder en livsviktig färjeförbindelse till Rut'theran Village på Teldrassil och tar emot långväga handelsfartyg från Menethil Harbor i Eastern Kingdoms.",al={"varför bygga auberdine vid stranden","auberdines hamn syfte","varför auberdine vid kusten"}},["451a86e7"]={q="Vem bestämmer här?",a="Nattalverna gör anspråk på Darkshore som en del av sitt växande kungarike. Äldsten Thundris Windweaver sköter civila angelägenheter från Auberdine, medan nattalvernas Sentinels upprätthåller militär kontroll längs kustvägen och regionens gränser.",al={"vem styr darkshore","vem kontrollerar darkshore","darkshores ledning"}},f5d3cc9f={q="Vilka är Sentinels?",a="Sentinels är Kaldoreis traditionella stående armé, som främst består av elitkrigare bland nattalverna. De patrullerar vägarna, vaktar bosättningar som Auberdine och försvarar alvernas områden mot monster och inkräktare som tränger sig på.",al={"sentinels armé","nattalvernas sentinels","vad är sentinels"}},["435217d7"]={q="Lyder de under Darnassus?",a="Ja. Darkshores försvarare är trogna Kaldoreis ledning i Darnassus, högt uppe i Teldrassil, även om huvudstadens höga ämbetsmän ibland betraktar Auberdine, den karga gränsstaden, som en avlägsen utpost för utstötta och missanpassade.",al={"lyder sentinels under darnassus","darnassus auktoritet över darkshore","lyder auberdine under darnassus"}},["709b4618"]={q="Varför ligger det så många skeppsvrak på stranden?",a="Darkshore är ökänt för sitt hårda väder, kraftiga regn, täta havsdimma och klippiga grund. Olycksbådande vindar rör upp plötsliga vågor som driver fartygen mot klipporna, så att de grunda vattnen fylls av vrak efter fartyg som inte klarade passagen till Auberdine.",al={"skeppsvrak i darkshore","varför förliser skepp här","sjunkna båtar i darkshore"}},["9d4c460f"]={q="Varför hemsöker Highborne dessa ruiner?",a="För tiotusen år sedan var Highborne drottning Azsharas magiska adel, som härskade över tvillingstäder som Ameth'Aran och Bashal'Aran. När den stora Sundringen krossade deras imperium fängslade deras härskare deras själar i bindande ädelstenar, så att deras plågade andar hemsöker stenpelarna i evighet.",al={"varför finns highborne-spöken här","ameth'arans spöken","vilka var highborne"}},c8232ccb={q="Vad fördärvade Blackwood-stammen?",a="Blackwood-furbolgarna var en gång nattalvernas vänliga grannar, men har drivits in i ett omättligt vansinne av mörk fördärvelse. Floder som rinner ned från Felwoods förgiftade höjder för med sig giftigt vatten genom Darkshore, vilket förvrider både djurens och furbolgarnas sinnen.",al={"blackwood-furbolgarna galna","varför är furbolgarna arga i darkshore","furbolgarnas fördärvelses källa"}},a33e07d8={q="Vilka är Twilight's Hammer och varför har de slagit läger här?",a="Twilight's Hammer är en nihilistisk apokalyptisk kult som ägnar sig åt de mörka väsen som kallas Old Gods. De har samlats vid The Master's Glaive i södra Darkshore, där de utför ritualer och gräver ut forntida underjordiska lämningar begravda under marken.",al={"twilight hammer i darkshore","kultister i darkshore","varför är twilight-kultister här"}},b665bd5a={q="Varför är Darkshore farligt?",a="Utanför Auberdines närmaste gränser är kusten full av faror. Vilda bestar och rasande furbolgar stryker omkring bland träden, naga och murlocs hemsöker stränderna, och skuggiga kulter som Dark Strand och Twilight's Hammer överfaller resenärer från gömda utposter.",al={"är darkshore säkert","faror i darkshore","darkshores faror"}},["9cbaedb5"]={q="Varför kallas det Darkshore?",a="Kusten fick sitt namn av de täta, skuggiga skogarna och den dystra, ovanliga dimma som täcker hela strandlinjen, skymmer dagsljuset och lägger stränderna i ett ständigt mörker.",al={"varför heter det darkshore","darkshores namns ursprung","varför kallas det darkshore"}},c5ede25e={q="Hur hamnade jag i Darkshore?",a="Du kom troligen hit genom Auberdine, den livliga kusthamnen och handelsplatsen som förbinder norra Kalimdor med den större världen. Om du reste från Teldrassils grenar tog en färja dig över det dimhöljda vattnet från Rut'theran Village till fastlandets kajer. Resenärer från Eastern Kingdoms tar ofta den långa färden med de stora segelfartygen från Menethil Harbor. Härdade vandrare som i stället tar landvägen från Ashenvales djupa skogar följer den patrullerade Sentinel-vägen norrut till den klippiga, dimhöljda kusten.",al={"hur kom jag hit","hur kom jag till darkshore","hur anlände jag hit"}},c840edc2={q="Vad förväntas jag göra i Darkshore?",a="Nattalverna i Auberdine behöver desperat hjälp med att hejda en växande plåga längs kusten. En vidrig fördärvelse som sipprar ned från Felwoods höjder har förgiftat floderna och grundvattnet och drivit det lokala djurlivet och de fridfulla Blackwood-furbolgarna in i våldsamt vansinne. Bortom skogarna vaknar forntida Highborne-ruiner som Ameth'Aran med rastlösa spöken, naga och murlocs tränger sig på de klippiga stränderna, och ondskefulla Twilight's Hammer-kultister samlas kring det forntida monumentet The Master's Glaive. Auberdine Village Council och Sentinels förlitar sig på resenärer som du för att återställa balansen.",al={"varför är jag här","vad ska jag göra i darkshore","vad är mitt syfte här"}},["7cfc9767"]={q="Vad är Darkshore?",a="Darkshore är en lång, dimmig kustremsa med klippor längs nordvästra Kalimdor. Den ligger skyddad mellan bergen i öster och Veiled Sea i väster och rymmer skuggiga skogar, regnpiskade stränder och sönderfallande alvruiner. Den är nattalvernas främsta förbindelse mellan öhemmet Teldrassil och fastlandet.",al={"berätta om darkshore","vad är darkshore för slags zon","översikt över darkshore"}},["0d623756"]={q="Varför ser platsen så förstörd och dyster ut?",a="En stor del av Darkshore krossades för tiotusen år sedan under Great Sundering, som reducerade storslagna Kaldorei-städer till ruiner. I dag ger den ständiga havsdimman, de stormiga vindarna och den magiska förorening som sipprar ner från besmittade bergsfloder kusten dess ihållande, sorgsna stämning.",al={"varför är darkshore dystert","varför är darkshore förstört","darkshore ödelagt"}},d345bcc9={q="Vilka bor här nu?",a="Nattalverna håller bosättningen Auberdine vid liv tillsammans med besökande Alliance-handlare, däribland dvärgar och människor. Utanför staden befolkas vildmarken av fientliga naga, troggs, fördärvade furbolgs och rester av de mörka kulter som gömmer sig bland de uråldriga stenarna.",al={"vilka bor i darkshore","befolkningen i darkshore","vem bor i darkshore"}},["137b9ce8"]={q="Vad är Auberdine?",a="Auberdine är en stillsam kustbosättning och den främsta Alliance-hamnen i norra Kalimdor. Låga alvsalar av trä, jordstigar och en framträdande hamnfyr präglar platsen, som förbinder Darnassus på andra sidan vattnet med fastlandet och Eastern Kingdoms.",al={"staden auberdine","berätta om auberdine","vad är staden i darkshore"}}},fp="9,278,25.396.0,22.414.0,37.419.0,26.297.0,51.247.0,44.314.1,28.235.0,51.239.0,36.182.0"}
P.entries["zone:darkspearislands"] = {n="Darkspear Islands",s="Utanför Kalimdors kust ligger Darkspear-trollens ceremoniella öar, nu ett slagfält där Horde och Alliance kämpar om varje läger, ruin och torn. För Horde, och framför allt för Vol'jins troll, är öarna helig mark som aldrig får falla i utomståendes händer. För Alliance är de ett brohuvud utanför Kalimdors kust och en chans att slå mot ett av Hordes stoltaste folk. Segern går till den sida som intar och håller öarnas befästa platser, tar Darkspear Islands-flaggan och först samlar ihop 2000 resurser.",h="Utanför Kalimdors kust ligger Darkspear-trollens ceremoniella öar, nu ett slagfält där Horde och Alliance...",kw={"darkspear islands","darkspear","slagfält","ceremoniella öar","darkspear islands-flaggan","shipwreck cove","abandoned tower","resurser","vol'jin","loa"},ang={["faction:Alliance"]="För Alliance-soldater är varje befäst plats som intas på Darkspear Islands ett brohuvud utanför Kalimdors kust och ett slag mot ett av Hordes stoltaste folk.",["faction:Horde"]="Varje Horde-krigare på dessa stränder försvarar ett löfte: Darkspear stod vid Thralls sida när Horde knappt hade något kvar, och deras heliga öar faller inte så länge Horde kan hålla i ett svärd.",["race:Troll"]="Det här är ditt folks ceremoniella marker. Varje Alliance-fana som hissas här är en förolämpning mot loa och Sen'jins minne, och varje fana som rivs ner är en bön som besvarats."},sec={{t="Darkspears heliga öar",b="Darkspear är ett öfolk. De drevs bort från Stranglethorn Vale av sina större och grymmare rivaler och byggde upp sina liv bland öarna i de södra haven. Dessa öar utanför Kalimdors kust bevarar de för sina riter och för loa som de vördar. Det var på öar som dessa som Thralls stormskadade flotta fann Sen'jins folk ansatta av Kul Tiran-sjömän, murlocs och en sjöhäxa. Där svor trollen för första gången trohet till Horde. För en Darkspear är en fiendefana över de ceremoniella markerna lika mycket en skändning som ett nederlag."},{t="Två sidor, två skäl",b="För Horde är det en hedersskuld att hålla öarna. Darkspear stod vid Thralls sida när Horde knappt hade något kvar, och orcer, tauren och Forsaken kämpar sida vid sida med dem så att trollens heliga mark förblir deras. För Alliance är öarna ett brohuvud utanför Kalimdors kust och ett sätt att slå mot Horde där dess stolthet sitter som djupast. Ingen av sidorna talar om fred här. Varje landstigning besvaras, och varje läger som faller kämpas det om på nytt."},{t="Så utkämpas striden",b="Ingen armé kan hålla öarna enbart med numerärt övertag. Striderna sträcker sig från lägret och de gamla ruinerna till Abandoned Tower och Shipwreck Cove. Den sida som intar och håller öarnas befästa platser bygger upp sitt resursförråd. En enda fana, Darkspear Islands-flaggan, kan vända striden för den som tar den. Den sida som först samlar ihop 2000 resurser vinner dagen och driver fienderna tillbaka till deras skepp, fram till nästa landstigning."}},faq={{q="Vad är slagfältet Darkspear Islands?",a="Det är ett slagfält utanför Kalimdors kust, på Darkspear-trollens ceremoniella öar. Hordes och Alliances styrkor kämpar där för att inta och hålla öarnas befästa platser, ta Darkspear Islands-flaggan och först samla ihop 2000 resurser.",al={"vad är darkspear islands","darkspear islands slagfält","pvp på darkspear islands"}},{q="Varför kämpar Horde om Darkspear Islands?",a="Öarna är heliga för Darkspear-trollen, Vol'jins folk, som anslöt sig till Horde när Thrall räddade dem från Kul Tiran-sjömän, murlocs och en sjöhäxa. Att förlora sina ceremoniella marker till Alliance vore en skändning, så hela Horde kämpar för att hålla dem.",al={"varför försvarar horde darkspear islands","hordes intressen på darkspear islands","varför kämpar trollen där"}},{q="Varför kämpar Alliance vid Darkspear Islands?",a="För Alliance är öarna ett brohuvud utanför Kalimdors kust och en chans att slå mot Horde genom ett av dess stoltaste folk. Varje befäst plats som intas där är mark som Horde måste blöda för att återta.",al={"varför anfaller alliance darkspear islands","alliances intressen på darkspear islands","alliances skäl för darkspear"}},{q="Hur vinner man striden om Darkspear Islands?",a="Båda sidor intar och håller öarnas befästa platser, som fyller på deras resurser, och försöker ta Darkspear Islands-flaggan. Den sida som först samlar ihop 2000 resurser vinner striden.",al={"mål på darkspear islands","hur man vinner på darkspear islands","darkspear islands-flaggan"}},{q="Var utkämpas striderna på öarna?",a="Striderna sträcker sig över öarna, från lägret och de gamla ruinerna till Abandoned Tower och Shipwreck Cove. Kampen om varje plats tar sällan slut efter en enda anstormning.",al={"platser på darkspear islands","shipwreck cove","abandoned tower"}},{q="Vilka är Darkspear-trollen?",a="Darkspear är en stam av djungeltroll som leds av Vol'jin. De drevs bort från Stranglethorn Vale och levde bland öarna i de södra haven tills Thralls flotta fann dem. Sedan dess har de tjänat Horde troget, från Sen'jin Village i Durotar till varje front i dess krig.",al={"darkspear-stammen","vilka är darkspear","vol'jins troll"}}},fp="17,348,29.519.0,22.417.0,23.392.0,43.238.0,51.274.0,53.195.0,48.184.0,46.174.0,29.291.0"}
P.entries["zone:darnassus"] = {n="Darnassus",s="Darnassus är nattalvernas fridfulla huvudstad under bar himmel, byggd bland grenarna på det nyplanterade världsträdet Teldrassil. Den styrs av översteprästinnan Tyrande Whisperwind tillsammans med druiderna i Cenarion Enclave och är en stillsam fristad för ett uråldrigt folk som vänjer sig vid dödligheten. Staden breder ut sig över stora terrasser runt en kristallklar sjö och är nattalvernas samhälles hjärta och deras bro till Alliansen.",h="Darnassus är nattalvernas fridfulla huvudstad under bar himmel, byggd bland grenarna på det nyplanterade...",kw={"cenarion enclave","darnassus","fandral","nattalvernas huvudstad","rut'theran","staghelm","teldrassil","temple of the moon","tyrande","whisperwind"},ang={["class:Druid"]="Cenarion Enclave är centrum för druidutbildningen på Teldrassil och övervakas av den krävande och kompromisslösa ärkedruiden Fandral Staghelm.",["class:Priest"]="Det storslagna Temple of the Moon är Elunes systrars heliga centrum och leds av översteprästinnan Tyrande Whisperwind själv.",["faction:Alliance"]="Darnassus fungerar som Alliansens västligaste fäste och erbjuder ett viktigt skydd för flottan och strategiska positioner på kontinenten Kalimdor.",["race:NightElf"]="Darnassus är hjärtat i din självständiga civilisation och din fristad när du tar dig an den dödliga tillvarons aldrig tidigare skådade prövningar."},sec={{t="En krona högt bland grenarna",b="Till skillnad från Stormwinds täta stenbyggnader och Ironforges uthuggna stentunnlar är Darnassus vidsträckt, stilla och öppen mot vildmarken. Huvudstaden ligger uppe i Teldrassils trädkrona, utanför norra Kalimdors kust, och dess graciösa träbyggnader och vindlande stigar omger en stilla sjö. Eleganta broar förbinder terrasser för handelsfolk, hantverkare, väktare och druider och skapar en stämning där samhällsstyre förenas med djup vördnad för naturen."},{t="En fristad för ett dödligt folk",b="Darnassus är anmärkningsvärt ungt för en civilisation som är tusentals år gammal. Efter det tredje kriget och Nordrassils offer vid Mount Hyjal ställdes kaldorei plötsligt inför åldrandets och sjukdomens faror. Ärkedruiden Fandral Staghelm och hans anhängare sökte återvinna sin förlorade livskraft och planterade Teldrassil medan ärkedruiden Malfurion Stormrage var försvunnen i The Emerald Dream. Darnassus grundades bland dess väldiga grenar som en fristad och ett minnesmärke över deras överlevnad, men skuggor av obehag viskar redan bland rötterna."},{t="En delad härd",b="Darnassus verkar fridfullt, men vilar på en skör politisk balans. Från Temple of the Moon höga pelargångar vägleder översteprästinnan Tyrande Whisperwind folkets andliga liv och militära försvar genom de vaksamma väktarna. På andra sidan vattenvägarna i Cenarion Enclave leder ärkedruiden Fandral Staghelm druiderna medan Malfurion är fortsatt frånvarande. Båda ledarna visar upp en enad front inför sina nyfunna allierade i Alliansen, men spänningen mellan prästinnorna och druidkretsen dröjer sig kvar i staden."}},faq={{q="Hur tar du dig från fastlandet till Darnassus?",a="Eftersom Teldrassil är en ö utanför Kalimdors nordvästra kust måste resenärer ta sig med båt eller flyg till Rut'theran Village vid trädets fot. Från byns bryggor tar en lysande magisk portal resenärer direkt upp till stadens grenar.",al={"hur man tar sig till darnassus","resa till darnassus","ingången till darnassus"}},{q="Vem styr Darnassus?",a="Översteprästinnan Tyrande Whisperwind styr Darnassus och kaldorei från det storslagna Temple of the Moon. Ärkedruiden Fandral Staghelm leder druiderna i Cenarion Circle från Cenarion Enclave och fungerar som deras de facto ledare medan Malfurion Stormrage är försvunnen i The Emerald Dream.",al={"ledare i darnassus","vem styr","darnassus härskare"}},{q="Varför grundades staden så nyligen?",a="Darnassus grundades kort efter det tredje kriget. När nattalverna offrade sin odödlighet för att besegra Archimonde vid Mount Hyjal drev Fandral Staghelm på för att låta det nya världsträdet Teldrassil växa och återvinna deras forna tillstånd. Darnassus höggs ut bland grenarna som deras nya fristad.",al={"varför är darnassus nytt","när byggdes darnassus","darnassus historia"}},{q="Var är ärkedruiden Malfurion Stormrage?",a="Malfurion Stormrage är försvunnen; hans ande är fångad i The Emerald Dream. I hans frånvaro styr ärkedruiden Fandral Staghelm druiderna på Teldrassil, medan Tyrande Whisperwind ständigt söker ett sätt att väcka och återfinna sin älskade livskamrat.",al={"var är malfurion","är malfurion i darnassus","malfurions plats"}},{q="Var finns yrkesinstruktörerna och butikerna?",a="Staden är indelad i särskilda terrasser. På Craftsmen's Terrace finns insamlings- och skrädderiyrken samt ett värdshus, medan Tradesmen's Terrace rymmer handelsstånd och auktionshuset. Smeder och stridsinstruktörer finns på Warrior's Terrace, och stadens bank ligger på Temple Gardens centrala ö.",al={"yrken i darnassus","auktionshuset i darnassus","banken i darnassus"}},{q="Varför gick nattalverna med i Alliansen?",a="Efter förödelsen under det tredje kriget utsattes nattalverna för allt större press från Horden, särskilt genom orchernas skogshuggarexpeditioner in i Ashenvale. Darnassus insåg behovet av allierade mot dessa intrång och andra växande hot i Kalimdor, öppnade diplomatiska förbindelser och gick med i Storalliansen.",al={"varför är nattalverna med i alliansen","nattalvernas band till alliansen","alliansen och darnassus"}}},fx={c2a87a41={q="Vad är Darnassus?",a="Darnassus är nattalvernas huvudstad, belägen högt uppe bland grenarna på det väldiga världsträdet Teldrassil. Staden grundades nyligen efter det tredje kriget och tjänar som en fridfull tillflyktsort. Öppna terrasser, broar och stillsamma lundar omger en stor central sjö och speglar nattalvernas djupa vördnad för naturen och Elune.",al={"vad är det här för stad","berätta om darnassus","darnassus historia"}},a1b472ac={q="Vilka byggde Darnassus?",a="Staden grundades av nattalverna efter det tredje kriget under ledning av ärkedruiden Fandral Staghelm och druiderna som planterade Teldrassil. Den byggdes av nätta trälodger, formad sten och levande grenar för att hedra kaldoreiernas överlevnad efter deras offer vid Mount Hyjal.",al={"vem skapade darnassus","vem grundade darnassus"}},["9187c5ce"]={q="Varför ligger Darnassus uppe i ett träd?",a="När Nordrassil förstördes vid Mount Hyjal och nattalverna förlorade sin odödlighet planterade Fandral Staghelm och hans druider Teldrassil utanför norra Kalimdor i hopp om att återställa deras eviga liv. Darnassus byggdes direkt i dess vidsträckta, höga trädkrona som en avskild fristad långt från fastlandets faror.",al={"varför ligger det i ett träd","varför teldrassil"}},["03a6f12c"]={q="Var finns Tyrande Whisperwind?",a="Översteprästinnan Tyrande Whisperwind bor i Temple of the Moon på södra sidan av Darnassus. Från denna månbelysta helgedom leder hon The Sisterhood of Elune och styr kaldoreiernas samhälle.",al={"var är tyrande","hitta tyrande"}},bbc7c157={q="Vem är Fandral Staghelm?",a="Fandral Staghelm är den tillförordnade ärkedruiden som leder Cenarion Circle i Darnassus medan Malfurion Stormrage är försvunnen. Han drev på planteringen av Teldrassil och har aggressiva, expansionistiska åsikter om kaldoreierna, vilket ofta leder till konflikter med översteprästinnan Tyrande Whisperwind.",al={"ärkedruiden fandral staghelm","vem är fandral"}},["2b5108ff"]={q="Vad är Temple of the Moon?",a="Temple of the Moon är Darnassus storslagna centrum för andlig tillbedjan och den officiella platsen för kaldoreiernas styre. Det är hem åt The Sisterhood of Elune och översteprästinnan Tyrande Whisperwind och byggdes av sten som fördes med magi från fastlandet efter det tredje kriget.",al={"temple of elune i darnassus","vad är måntemplet"}},["4096dbf8"]={q="Vem är Elune?",a="Elune är nattalvernas vördnadsfulla mångudinna, förknippad med fred, läkande och natthimlen. Kaldoreierna kretsar sina andliga liv kring dyrkan av henne, vägledda av hennes översteprästinna och The Sisterhood of Elune.",al={"gudinnan elune","vad är elune"}},e87e3fa7={q="Varför finns det en fontän inne i Temple of the Moon?",a="Mitt i templet ligger en helig månskälla under Haidenes staty. Dess välsignade vatten anses vara Elunes egen beröring och används av The Sisterhood of Elune för bad, återhämtning och heliga riter.",al={"temple of the moon månskälla","elunes fontän darnassus"}},["0e74b3a4"]={q="Vad är Cenarion Enclave?",a="Cenarion Enclave är en frodig lund i nordvästra Darnassus där stadens druider möts och tränar. Den kantas av uråldriga träd med mystiska runor och rymmer Archdruid Fandral Staghelms helgedom av levande trä. Den fungerar också som samlingsplats för Cenarion Circle.",al={"cenarion enclave darnassus","var finns druider i darnassus"}},e546b5d1={q="Varför är Fandral Staghelm archdruid och inte Malfurion?",a="Archdruid Malfurion Stormrage försvann under mystiska omständigheter in i The Emerald Dream efter det tredje kriget. I hans frånvaro tog Fandral Staghelm befälet över druiderna och ledde planteringen av Teldrassil.",al={"varför leder fandral","varför är inte malfurion archdruid"}},c7c576ca={q="Är Darnassus farligt?",a="Darnassus är lugnt och skyddas noga av nattalvernas Sentinels, höga Ancient Protectors och Ancients of War. Staden är fortfarande en fridfull tillflyktsort för Alliansen, även om oro och korruption sjuder i Teldrassils omgivande vildmark.",al={"är darnassus säkert","hot i darnassus"}},["6a190c74"]={q="Hur hamnade jag i Darnassus?",a="Om du är en nattalv började din resa troligen i Shadowglen. Därifrån tog du dig ner genom Dolanaar och följde sedan skogsvägen västerut över Teldrassils grenar till huvudstadens portar. Resenärer från andra länder kommer i stället med skepp från fastlandet till Rut'theran Village, långt där nere vid världsträdets fot. Sedan går de genom den glödande, förtrollade portalen som för dem rakt upp till staden.",al={"hur kom jag hit","hur kom jag till darnassus","hur tog jag mig till darnassus"}},["2586ce4f"]={q="Vad ska jag göra i Darnassus?",a="Darnassus är kaldoreiernas politiska och andliga hjärta. Äventyrare söker vägledning hos ledarna, High Priestess Tyrande Whisperwind i Temple of the Moon eller Archdruid Fandral Staghelm i Cenarion Enclave. De besöker också vapenmästare, klassmentorer och hantverkare på stadens terrasser. Oavsett om du skickas ut i vildmarken för att rena Teldrassil från dess plåga eller förbereder en resa bortom stränderna till det oroliga fastlandet, får du de förnödenheter, den undervisning och de order du behöver här.",al={"vad gör jag här","varför är jag i darnassus","vad ska jag göra i darnassus"}}},fp="9,270,28.281.0,25.386.0,16.380.0,49.204.0,20.227.0,37.344.0,39.235.0,52.319.0,42.260.0"}
P.entries["zone:deadmines"] = {n="The Deadmines",s="Djupt under Moonbrooks dammiga bondby ligger The Deadmines, ett enormt underjordiskt komplex som en gång stod för en tredjedel av Stormwinds guldreserver. Gruvorna övergavs under det första kriget och har länge ansetts hemsökta. Nu har Defias Brotherhood i hemlighet tagit över de labyrintiska gångarna som sin främsta operationsbas. Här arbetar Edwin VanCleef och hans inkallade gobliningenjörer i det fördolda med att bygga en hämndmaskin riktad mot kungariket.",h="Djupt under Moonbrooks dammiga bondby ligger The Deadmines, ett enormt underjordiskt komplex som en gång stod...",kw={"cookie","the deadmines","defias","edwin vancleef","ironclad cove","pansrat slagskepp","moonbrook","mr. smite","vancleef","westfall"},ang={["class:Paladin"]="Dessa vanhelgade schakt prövar mod och tro, och ekar av Sir Anduin Lothars historiska prövningar och de förlorade gruvarbetarna vars rastlösa döda fortfarande vandrar i de yttre gångarna.",["faction:Alliance"]="The Deadmines utgör det allvarligaste inre hotet mot kungariket Stormwind. Att fälla VanCleef är den avgörande segern som återger Westfalls belägrade bönder hoppet.",["profession:Engineering"]="Goblin Foundry och Sneeds mekaniska verkstad ger en inblick i avancerade ångdrivna rivare, fjärrstyrda golems och specialiserad beväpning.",["profession:Mining"]="De klippiga gångarna stod en gång för en tredjedel av huvudstadens rikedomar och är fortfarande rika på koppar, tenn och silver."},sec={{t="Ett arv av guld och ruiner",b="Före det första kriget hyllades The Deadmines som det främsta guldbrytningscentret i människornas riken och finansierade Stormwinds välstånd. När orkernas hord svepte genom kungariket och jämnade huvudstaden med marken övergavs gruvorna hastigt åt mörkret. Under de oroliga åren vandrade legendariska gestalter i djupen: Sir Anduin Lothar hölls fången av underjordiska ogres i tjugo månader medan han återfick den heliga Tome of Divinity, och Warchief Blackhands upproriska dotter Griselda flydde genom de nedre gångarna tillsammans med ogret Turok, innan båda gick sina öden till mötes. Djupen ansågs förbannade och bebodda endast av hasande odöda och lurande underjordiska skadedjur, och låg orörda i årtionden."},{t="Brödraskapets högkvarter",b="När Stonemasons' Guild kastades ut ur Stormwind utan ersättning för återuppbyggnaden av staden organiserade Edwin VanCleef de utstötta hantverkarna på nytt som Defias Brotherhood. För att hitta ett säkert högkvarter utom räckhåll för Gryan Stoutmantles People's Militia upprättade tjuvarna sin centrala fästning i de övergivna gångarna. De drev bort det lagliga Miners' League, lämnade Foreman Thistlenettles dödsdömda arbetare att gå under och återuppstå som odöda gastar, och gjorde om schakten till ett industriellt krigsläger. De nedre gruvorna vaktas av klumpiga ogres, härdade banditer och mekaniska konstruktioner, och ekar åter av hackor, eldar och olaglig industri."},{t="Ironclad Coves hemlighet",b="Bortom den heta Goblin Foundry och Mast Room, där timmer ligger strött, finns Ironclad Cove, en vidsträckt underjordisk grotta uthålad under The Dagger Hills. I den gömda hamnen har VanCleef anlitat goblinskeppsbyggare och uppfinnare för att konstruera ett kolossalt pansrat dreadnoughtskepp. Skeppet, som står under befäl av Captain Greenskin och förste styrman Mr. Smite, är byggt för att segla genom en undervattensport ut mot havet. Där tänker Defias Brotherhood angripa sjöhandeln som håller Stormwind rikt."}},faq={{q="Var ligger ingången till The Deadmines?",a="Ingången är gömd i en förfallen lada i den ruinerade staden Moonbrook, i sydvästra Westfall. Vindlande gångar leder genom ett yttre område med Defias-grävare och odöda gruvarbetare fram till den låsta instansens ingång.",al={"ingången till deadmines","hur man tar sig till deadmines","var ligger deadmines"}},{q="Varför kallar alla The Deadmines för ”VC”?",a="Äventyrare kallar ofta grottan ”VC” efter dess ledare, Edwin VanCleef. Förkortningen används för att inte förväxla The Deadmines med Dire Maul, ett uråldrigt alviskt komplex i Feralas med samma initialer, ”DM”.",al={"varför vc","vad betyder vc","varför kallas det vc"}},{q="Vem är Edwin VanCleef?",a="Edwin VanCleef var den briljante mästaren för Stonemasons' Guild, som ledde den storslagna återuppbyggnaden av Stormwind City efter det första kriget. När House of Nobles vägrade betala sina skulder bildade VanCleef Defias Brotherhood för att kräva ersättning genom uppror och öppet röveri.",al={"vancleefs bakgrund","vem är den sista bossen","defias ledare"}},{q="Vad byggs i Ironclad Cove?",a="Defias har anlitat gobliningenjörer för att bygga ett massivt pansrat slagskepp. Det är utrustat med tung beväpning och robust timmer och ska segla ut genom vikens undervattensport för att plundra handeln som försörjer huvudstaden.",al={"vad bygger de","deadmines skepp","pansrat slagskepp"}},{q="Vad hände med arbetarna från Miners' League utanför instansen?",a="Foreman Thistlenettle och hans arbetslag skickades dit för att lagligen återöppna gruvorna åt kungariket. När Defias stormade gruvorna ledde en förödande rasolycka till att gruvarbetarna blev instängda i mörkret. Där svalt de ihjäl och återuppstod till slut som viljelösa, rastlösa odöda.",al={"thistlenettles öde","varför finns det odöda gruvarbetare","samla minnen i berättelsen"}},{q="Vad innebär det för Defias skepp att besegra murlocken Cookie?",a="Cookie är den besynnerliga skeppskocken ombord på VanCleefs dreadnought. Att besegra VanCleef kapar upprorets huvud, medan Cookies död röjer skeppets kök på den återstående besättningen. Då utplånas Defias närvaro i Ironclad Cove innan äventyrarna flyr genom kustgången.",al={"cookie murlocken","varför är cookie en boss","cookie deadmines"}},{q="Vart leder utgångstunneln när man lämnar grottan?",a="Den naturliga tunneln bakom dreadnoughtskeppet leder äventyrarna till en utgång vid kustklipporna i The Dagger Hills, med utsikt mot havet och Westfall Lighthouse.",al={"deadmines utgång","vart leder utgången"}}},fx={d03732b9={q="Vad är The Deadmines?",a="The Deadmines är ett vidsträckt nätverk av labyrintiska tunnlar djupt under Westfall och nordvästra Stranglethorn Vale. Före det första kriget var gruvorna den rikaste guldkällan i människornas länder och sades ha rymt en tredjedel av hela Stormwinds skattreserver. De övergavs när Horden invaderade och plundrade kungariket. Gruvgångarna stod tomma i åratal, tills laglösa tog över dem.",al={"vad är the deadmines","the deadmines historia","berätta om the deadmines"}},["990a0946"]={q="Varför kallas de The Deadmines?",a="Efter att det första kriget ödelagt Stormwind förföll de övergivna guldgruvorna i mörker och ansågs allmänt vara hemsökta. I djupet strök dödliga fasor omkring, och det utmattade, övergivna stenriket låg tyst. Därför började resenärer helt enkelt kalla de övergivna gruvorna The Deadmines.",al={"varför heter det deadmines","varför kallas det deadmines","ursprunget till namnet deadmines"}},["001f20c6"]={q="Vem grävde de här tunnlarna?",a="I generationer bröt mänskliga arbetare och skråmedlemmar fram rikedomar av guld ur kullarna för att finansiera Stormwinds tidiga expansion. På senare tid försökte Miners' League öppna gruvorna igen under Foreman Thistlenettles ledning. Då tog Defias Brotherhood och deras inkallade grävare över det underjordiska nätverket och byggde omfattande befästningar där.",al={"vem byggde the deadmines","vem grävde the deadmines","gruvarbetare som byggde the deadmines"}},b6ffba12={q="Vilka är Defias Brotherhood?",a="Defias Brotherhood är en hänsynslös sammanslutning av avfällingar, banditer och laglösa. Den består av före detta stenhuggare, tjuvar, stråtrövare och mördare. De är svurna fiender till kungariket, har tagit kontroll över Westfall och verkar i det fördolda. De smider planer på blodig hämnd och vill störta Stormwinds härskande adel.",al={"vilka är defias","defias brotherhood","vad är defias"}},d563a934={q="Varför bär de röda bandanas?",a="Defias bär röda sidensjalar som en trotsig symbol för blodet som Stormwinds förtryckta arbetarklass har spillt. De visar sin trohet till Edwin VanCleefs uppror och påminner varje medlem om den blodsskuld som de anser att hovet har till dem.",al={"varför röda bandanas","defias röda masker","betydelsen av röd bandana"}},["29fe0b04"]={q="Vem grundade Defias Brotherhood?",a="Edwin VanCleef, den tidigare mästaren i Stonemasons Guild, grundade brödraskapet. Efter att i åratal ha återuppbyggt Stormwinds krossade murar använde han sina omfattande kunskaper i smygteknik, bedrägeri och ingenjörskonst till öppet uppror när rikets aristokrati vägrade betala hans arbetare.",al={"vem grundade defias","vem startade brödraskapet","defias grundare"}},["90ba82c0"]={q="Varför gömmer sig Defias i en gammal gruva?",a="The Deadmines är en enorm, försvarbar fästning gömd under Moonbrooks stilla ruiner. Westfall har till stor del övergivits av kungens armé, och gruvornas bortglömda underjordiska kammare leder direkt till en dold havsvik. VanCleef fann där en perfekt avskild bas för att samla en armé och tunga vapen ostört.",al={"varför gömställe i the deadmines","varför är defias i gruvan","varför gömma sig i the deadmines"}},["019c688c"]={q="Finns det verkligen ett skepp i gruvan?",a="Ja. Längst in i labyrinten ligger Ironclad Cove, en väldig underjordisk bassäng. Där ligger för ankar ett enormt, järnklätt krigsskepp, utrustat med tunga kanoner och riggat av gobliningenjörer. När det är färdigt ska det segla genom en dold sjöport ut i havet.",al={"finns det ett skepp i the deadmines","the deadmines krigsskepp","defias krigsskepp"}},["763d2dd2"]={q="Vem bestämmer här nere?",a="Edwin VanCleef leder hela verksamheten från sin hytt ombord på krigsskeppet, djupt inne i Ironclad Cove. Från sin underjordiska utsiktspost styr han gruvdriften, ingenjörsarbetet och räderna som håller Westfall i sitt grepp.",al={"vem leder the deadmines","vem styr the deadmines","chef i the deadmines"}},["985d6768"]={q="Har VanCleef några löjtnanter?",a="Han leder en brokig skara betrodda hantlangare i gruvgångarna. Den råbarkade ogren Rhahk'Zor vaktar de övre portarna. Sneed leder timmerverkstäderna inifrån en järnkrossare, goblinen Gilnid sköter smältverken i gjuteriet, och Captain Greenskin och den hänsynslöse taurenstyrmannen Mr. Smite ansvarar för krigsskeppet.",al={"vancleefs officerare","befälhavare i the deadmines","defias löjtnanter"}},["27e06e7a"]={q="Vem arbetar gobliner åt?",a="Goblinerna arbetar direkt för Edwin VanCleef som inhyrda specialister och legosoldater till hantverkare. De sköter gjuteriet, timmerverkstäderna och skeppsvarven. I utbyte mot mynt, inflytande och resurser bidrar de med den tekniska skicklighet och de industrimaskiner som behövs för att bygga VanCleefs krigsmaskiner.",al={"vem anlitade goblinerna","är gobliner defias","goblinernas allians med defias"}},fb90d257={q="Varför skickade de mig för att döda deras ledare?",a="Gryan Stoutmantle och den hårt prövade People's Militia har inte den militära styrkan som krävs för att ta sig in i The Deadmines. Stormwind vänder bort blicken och avfärdar hotet, så milisen måste helt förlita sig på modiga, självständiga äventyrare som du. Ni ska slå er djupt in i berget och hugga av ormens huvud.",al={"varför skickas jag för att döda vancleef","gryan stoutmantles begäran","varför döda defias ledare"}},e11d0994={q="Har någon annan försökt döda VanCleef?",a="Ingen har lyckats. Stormwind har inte skickat någon armé mot honom, och People's Militia vid Sentinel Hill är för svag för att storma gruvorna. Därför vänder sig Gryan Stoutmantle till äventyrare.",al={"vem försökte döda vancleef","tidigare angrepp mot the deadmines","har någon angripit the deadmines"}},["22846885"]={q="Varför kan inte Stormwinds armé göra det?",a="Stormwinds stående styrkor är utspridda över Elwynn och avlägsna gränser, försvagade av skulder och byråkratisk likgiltighet. Adelsrådet vägrar finansiera en expedition till Westfall. Därför står provinsens gårdar utan försvar, och People's Militia måste hantera krisen på egen hand.",al={"varför finns ingen stormwind-armé","varför rensar inte stormwind the deadmines","stormwinds vakter i westfall"}},["93f204fb"]={q="Hur tog Defias över gruvorna?",a="Efter att ha flytt från Stormwind ledde VanCleef sina följeslagare till Westfalls laglösa fält. De överföll de lokala gruvorna, rasade samman viktiga tunnlar för att fånga kungliga arbetare och befäste det vidsträckta underjordiska nätverket till en ointaglig bas.",al={"hur defias tog över the deadmines","hur the deadmines föll","defias tog över gruvan"}},["9fd39a6b"]={q="Gick gruvarbetarna med i Defias?",a="Medan Miners' League-arbetarna överfölls och omkom, gick många missnöjda arbetare, ficktjuvar och desperata lösdrivare frivilligt med i Brotherhoods sak. I dag sliter vanliga arbetare och malmbrytare oavbrutet i schakten under Defias-förmäns och arbetsledares vakande piskor.",al={"gick gruvarbetarna med i defias","är gruvarbetarna defias","gruvarbetare som arbetar för defias"}},a6aef884={q="Varför finns det gobliner här nere som hjälper Defias?",a="Att bygga en bepansrad juggernaut och avancerade skördevakter kräver metallurgisk och mekanisk expertis som vanliga banditer saknar. VanCleef anlitade gobliningenjörer, hantverkare och timmerskärare, som gärna anlade gjuterier och verkstäder i grottorna i utbyte mot rikedomar och vinst.",al={"varför gobliner i the deadmines","gobliner i the deadmines","varför är gobliner här"}},b9fb938c={q="Vad får gobliner ut av att hjälpa Defias?",a="För gobliner är det bara affärer. De får en stor andel av guldet som plundras från Westfalls gruvor, fri tillgång till malm och timmer av hög kvalitet samt full frihet att testa riskfyllda ingenjörsprototyper utanför handelsfurstarnas jurisdiktion.",al={"vad får gobliner ut av det","goblinernas vinst i the deadmines","varför arbetar gobliner för defias"}},["4854becf"]={q="Vem är Sneed?",a="Sneed är en slug goblinförman som övervakar Defias timmerverksamhet i Mast Room. Han styr avverkningen inifrån en tung, rakbladsvass timmerstrimlare och förvandlar jätteträd till master och balkar åt dreadnaughten.",al={"vem är sneed","sneed i the deadmines","sneed-bossen"}},ba2c808f={q="Vad är det här Stonemasons Guild som alla pratar om?",a="Stonemasons Guild var ett ansett skrå av arkitekter, murare och hantverkare, lett av Edwin VanCleef, som återuppbyggde Stormwind City från ruinerna efter plundringen under det första kriget. De återställde de vita murarna och tornen, men när rikets politik svek dem blev de grunden för upproret.",al={"stonemasons guild","vad var stonemasons guild","vilka var stenhuggarna"}},["30bf5c0b"]={q="Vägrade Stormwind verkligen att betala Stonemasons?",a="Ja. Stormwinds House of Nobles drog på sig katastrofala skulder genom att utöka de militära fälttågen och vägrade betala hela ersättningen som utlovats för återuppbyggnaden av staden. Adeln, som i hemlighet manipulerades av Lady Katrana Prestor, erbjöd bara en mager ersättning och upplöste plötsligt skrået när VanCleef krävde gottgörelse.",al={"betalade stormwind inte stenhuggarna","varför fick stenhuggarna inte betalt","house of nobles betalning till stenhuggarna"}},["6779ccff"]={q="Var det upplopp i Stormwind?",a="När skrået upplöstes utan att få betalt ledde VanCleef ilskna upplopp genom Stormwinds gator. Kronan slog hårt tillbaka och drev de upproriska hantverkarna i landsflykt.",al={"stormwind-upploppet och stenhuggarna","vad hände under stenhuggarupproret"}},["8f04eff1"]={q="Är Defias bara banditer eller något värre?",a="De är mycket mer än vanliga tjuvar. Defias Brotherhood är ett organiserat, djupt rotat revolutionärt syndikat som använder avancerad goblinteknik, spionage och tränad magi. De drivs av ett personligt och ideologiskt hat mot Stormwinds härskarklass.",al={"är defias banditer","hur farliga är defias","hur stort är hotet från defias"}},["2dd70853"]={q="Har Defias någon egentlig plan?",a="Deras mål är inget mindre än att få Stormwind på knä. Genom att tömma Westfall på resurser och svälta huvudstaden samtidigt som de i hemlighet bygger ett tungt järnkrigsskepp under marken tänker de segla rakt till Stormwind Keep och bombardera riket tills det kapitulerar villkorslöst.",al={"defias stora plan","vad är defias mål","vad vill defias"}},["9ff64ec1"]={q="Kan Defias hota själva Stormwind?",a="Utan tvekan. Med kung Varian försvunnen, hovet lamslaget av interna intriger och den kungliga armén pressad till bristningsgränsen kan en överraskande flottattack från en fullt beväpnad järn- och ståljuggernaut krossa Stormwinds hamnförsvar och göra staden försvarslös inifrån.",al={"kan defias förstöra stormwind","kan defias ta över stormwind","hotet från defias mot stormwind"}},["9d82770e"]={q="Vad händer när VanCleef är död?",a="När du överlämnar VanCleefs avhuggna huvud till Gryan Stoutmantle vid Sentinel Hill bekräftas hjärnans död, vilket blir ett förödande slag mot Brotherhoods storslagna kampanj. Dokument som hittas på hans kropp, som ett oskickat brev, pekar dessutom mot djupare konspirationer och korruption i Stormwinds innersta kretsar.",al={"efter vancleefs död","vancleef död, vad händer nu","följderna av vancleefs död"}},f607b8be={q="Tar det slut på Defias om man dödar VanCleef?",a="Det krossar deras omedelbara planer, men utplånar inte upproret. Tusentals ficktjuvar, stråtrövare och sympatisörer håller fortfarande stånd i Westfall, Redridge och Stockades och hyser ett bittert hat mot kronan som överlever deras grundare och ledare.",al={"tar defias slut med vancleef","är defias besegrade","stoppar vancleefs död defias"}},c2558e80={q="Blir Westfall äntligen tryggt när VanCleef faller?",a="Inte genast. Förrymda mekaniska skördevakter stryker fortfarande omkring på de fördärvade fälten, gnollflockar strövar i kullarna och utspridda Defias-celler fortsätter att plundra gårdar. Det blir en lång och mödosam kamp för People's Militia innan freden verkligen återvänder till slätterna.",al={"är westfall tryggt nu","kommer westfall att återhämta sig","westfall efter the deadmines"}},d15c407d={q="Varför är det sådan oreda i Westfall?",a="Westfall var en gång rikets bördiga kornbod, men år av försummelse, torka och Defias terror förvandlade det till ruiner. Laglösa drev bort nybyggarna, tog över gruvorna och lämnade de en gång frodiga betesmarkerna obrukade och fulla av glupska asätare och förrymda skördegolemer.",al={"varför är westfall förstört","vad hände med westfall","läget i westfall"}},["8c3ab485"]={q="Vart tog alla Westfalls bönder vägen?",a="De flesta drevs bort med våld när Defias tog över landsbygden och flydde till Sentinel Hills portar eller tiggde på Stormwinds gator. Bara en handfull envisa nybyggare är kvar på sina familjegårdar, där de desperat kämpar mot banditer och gnoller för att få ihop en skörd.",al={"var är bönderna","vad hände med westfalls bönder","fördrivna westfall-bönder"}},["619c91ff"]={q="Varför skickar inte kungen hjälp till Westfall?",a="Kung Varian Wrynn har mystiskt försvunnit och lämnat sin unge son Anduin och Highlord Bolvar Fordragon att styra riket. Det kungliga hovet, manipulerat av trätlystna adelsmän, hävdar att riket saknar pengar och soldater att avvara för Westfalls försvar och lämnar provinsen åt sitt öde.",al={"varför hjälper inte kungen westfall","varför hjälper inte kungen","kung varian hjälper westfall"}},["21f940b9"]={q="Hur hamnade jag i The Deadmines?",a="Din jakt på Defias Brotherhood ledde dig över Westfalls fördärvade slätter till Moonbrook, en övergiven stad som översvämmats av stråtrövare. En förrädare från Defias hjälpte dig att hitta deras hemliga högkvarter, gömt i den förfallna gruvöppningen i utkanten av staden. Du kämpade dig ner genom de gamla gruvgångarna och förbi odöda utgrävningar, och trängde in i djupet där Brotherhood har befäst sitt näste.",al={"hur kom jag hit","hur hamnade jag här","hur tar jag mig in här"}},a22369d2={q="Vad ska jag göra i The Deadmines?",a="Gryan Stoutmantle och People's Militia skickade dig för att hugga av ormens huvud. Du ska kämpa dig igenom Brotherhoods gruvarbetare, goblinuppfinnare och piratlegoknektar för att nå Ironclad Cove. Där måste du borda deras krigsskepp, möta Edwin VanCleef själv och ta hans huvud för att en gång för alla bryta Defias grepp om Westfall.",al={"vad gör jag här","vad är mitt mål här","varför är jag här"}}},fp="13,318,25.642.0,26.653.0,27.461.1,47.206.0,42.189.0,22.291.0,37.246.0,65.243.0,63.283.0,57.175.0"}
P.entries["zone:deadwind"] = {n="Deadwind Pass",s="Deadwind Pass är en fördärvad, klippig ravin mitt i Azeroth som förbinder Duskwood med Swamp of Sorrows. I dess mitt reser sig Karazahns elfenbensvita spira, tidigare hemvist för Guardian Medivh, vars död släppte lös fördärvande magiskt avfall över landet. Det är en livlös passage där ogres, spöken och demoniska vindar stryker omkring, utan skydd eller civiliserad tillflykt.",h="Deadwind Pass är en fördärvad, klippig ravin mitt i Azeroth som förbinder Duskwood med Swamp of Sorrows.",kw={"dark riders","deadman's crossing","deadwind-ogres","deadwind pass","karazhan","medivh","morgan's plot","den siste väktaren","vice"},ang={["class:Mage"]="Ley-linjerna under Deadwind Pass löper samman direkt in i Karazhan. Magiker betraktar denna knutpunkt med stor bävan och vet hur Medivh förvrängde dess arkaniska ledning för att bryta igenom dimensionella barriärer.",["class:Warlock"]="Spår av rå demonisk energi täcker fortfarande klipporna och stenkällarna. Medivhs besatthet och passets nekromantiska historia har lämnat en outplånlig fläck av fel-magi som fortfarande kan kännas.",["faction:Alliance"]="Stormwind betraktar denna döda passage som ett dystert ärr vid sina gränser. Fasorna som flydde från Karazhan gjorde slut på Duskwoods forna prakt och hotar fortfarande Darkshire, strax längs den västra vägen.",["faction:Horde"]="För resenärer som färdas västerut från Stonard är denna ravin en fientlig flaskhals, full av hämndlystna människors andar och väldiga ogres som angriper alla som går in i klyftan."},sec={{t="En ravin av ben och tjutande vind",b="Deadwind Pass betraktades en gång som en utlöpare av Redridge Mountains, men har förvandlats till ett urholkat ärr av blekt sten och förstenat trä. En stinkande, obeveklig vind skär genom ravinerna och gav klyftan dess namn. Himlen ovanför är ständigt gravgrå och hotar med oberäkneliga åskväder som gör det farligt att färdas med metallvapen. Totemiska avbilder hänger från livlösa grenar längs huvudvägen och varnar vägfarare att fortsätta framåt. Här finns ingen bördig jord, inga brytvärda malmådror och inga byar eller flygmästare som kan hjälpa till."},{t="Karazhans arv",b="Passets historia kretsar kring den väldiga borgen Karazhan. Tornet byggdes ovanpå en kraftfull knutpunkt av underjordiska ley-linjer och tjänade som Guardian Medivhs tillflykt. Det var i denna spira som Medivh planerade att öppna Dark Portal och ödelägga Stormwind. När hans vansinne och besatthet avslöjades under First War stormade en expedition ledd av Lord Anduin Lothar och unge Khadgar tornet och avrättade honom. Medivhs våldsamma död släppte lös en stötvåg av fel-fördärv som ödelade både passet och den närliggande skogen Duskwood. Karazhan blev kvar som en hotfull rest som läcker instabil magisk energi."},{t="Deadwinds ogres och ruinerade gårdar",b="Söder om huvudvägen förgrenar sig passet in i Deadwind-ogreklanens område kring The Vice. Dessa bestar, klädda i stinkande trasor och beväpnade med taggigt järn, överfaller skoningslöst alla som närmar sig den södra vägen. De sägs tjäna en dold herre i närheten. Längre söderut ligger Morgan's Plot och de skelettlika resterna av en by som en gång försörjde tornet. I dag kryllar byns ruiner ovan jord och dess labyrintiska källare av jämrande vålnader och rastlösa andar, kvarlevor efter dem vars liv släcktes av Karazahns tygellösa trolldom."},{t="Lien och de mörka ryttarna",b="De beslöjade Dark Riders rider ut ur Deadwind Pass. På senare tid har de spridit skräck i Duskwood och slaktat oskyldiga nybyggare i en skoningslös jakt på den gåtfulla Scythe of Elune, innan de dragit sig tillbaka in i passets skuggor."}},faq={{q="Varför är den här platsen så död och ruinerad?",a="Deadwind Pass ödelades av den arkaniska föroreningen och mörka trolldom som kretsade kring Karazhan. När Guardian Medivh dödades i sitt torn under First War störtade en explosion av fel-magi ner genom ravinen, förstenade träden, berövade jorden allt liv och fördärvade himlen för alltid.",al={"varför är deadwind pass dött","vad hände med deadwind pass","varför är träden döda här"}},{q="Finns det några vänliga byar, värdshus eller flygmästare här?",a="Nej. Deadwind Pass har inga vänligt sinnade bosättningar, värdshus eller flygmästare för någon av fraktionerna. Alliance-resenärer måste förlita sig på Darkshire i Duskwood västerut, medan Horde-medlemmar måste utgå från Stonard i Swamp of Sorrows österut.",al={"flygrutt i deadwind pass","finns det en by i deadwind pass","värdshus i deadwind pass"}},{q="Vilken roll spelar Karazhan i Deadwind Pass?",a="Karazhan var Guardian Medivhs torn, där han arbetade för att öppna Dark Portal. Det står kvar som ett hotfullt landmärke bland Deadwind Passs vissna träd, instabila magi och rastlösa döda.",al={"karazhan i deadwind pass","medivhs torn","karazhans historia"}},{q="Vilka är Dark Riders och varifrån kommer de?",a="Dark Riders är beslöjade gestalter som rider ut ur Deadwind Pass. De jagar mäktiga reliker, däribland Scythe of Elune, och har spridit skräck i närliggande Duskwood.",al={"dark riders i deadwind","scythe of elune och ryttarna"}},{q="Kan jag samla örter eller bryta malm i Deadwind Pass?",a="I den nuvarande eran finns det inga användbara fyndplatser för örter eller malm i Deadwind Pass. Kadaverfåglar och fientliga ogres håller till i det karga landskapet.",al={"örter i deadwind pass","gruvdrift i deadwind","resurser i deadwind pass"}},{q="Vilka bor i Deadwind Pass i dag?",a="Passet är främst bebott av den aggressiva Deadwind-ogreklanen i The Vice, samt av kringströvande kadaverfåglar och rastlösa spöken. Några kringvandrande mänskliga asätare överlever på egen hand utan stöd från Alliance.",al={"invånare i deadwind pass","vem bor i deadwind","fiender i deadwind pass"}}},fp="13,250,34.500.0,22.508.0,31.455.0,30.182.1,37.230.0,59.217.0,42.181.0,53.166.1,48.112.0,33.162.0"}
P.entries["zone:desolace"] = {n="Desolace",s="Desolace är en karg, vindpinad öken på Kalimdors västkust, präglad av sprucken grå jord, ständigt stormiga skyar och benen från fallna bestar. Det är centaurernas förfäders vagga och en omstridd ödemark, märkt av uråldriga Highborne-ruiner, demoniska kulter som breder ut sig och bittra stamkrig. Både Horde och Alliance håller osäkra fästen här bland dammet. Båda försöker vinna inflytande och hejda korruptionen som sprider sig.",h="Desolace är en karg, vindpinad öken på Kalimdors västkust, präglad av sprucken grå jord, ständigt stormiga...",kw={"burning blade","centaur","desolace","gelkis","magram","maraudon","nijel's point","shadowprey village","theradras","zaetar"},ang={["class:Druid"]="Druiderna i Cenarion Circle ser Desolace som ett fasansfullt sår i naturens ordning. Här mötte Zaetar sitt tragiska slut och elementärt förfall kväver jorden.",["class:Warlock"]="De torra slätterna och demoniska platser som Mannoroc Coven lockar till sig mörka utövare som söker felhästarnas hemligheter. Det är ståtliga vildhästar som genom förbjudna ritualer från Shadow Council förvandlats till eldspyende fasor.",["faction:Alliance"]="Från Nijel's Point bevakar Alliance både de förrädiska centaurstammarna och den misstänkta spridningen av Hordes bosättningar, som Shadowprey Village. De håller också utkik efter demoniska kulter.",["faction:Horde"]="Horde försöker säkra kusten vid Shadowprey Village och skydda kodohjordarna vid Ghost Walker Post. Samtidigt kämpar de utan uppehåll för att krossa Burning Blade och bevisa att dagens Horde är fri från demoniskt inflytande.",["race:Tauren"]="För tauren är Desolace helig och tragisk mark. Det är centaurernas vagga, och deras härjningar drev ditt folk till utrotningens rand."},sec={{t="Ett förbannat och krossat land",b="Desolace var inte alltid en karg vidsträckt ödemark av aska och gulnade vattenpölar. Enligt legenden vissnade landet när jordelementaren prinsessan Theradras tömde den omgivande livskraften för att återskapa sin kropp. Zaetar, Cenarius son, kom till henne, men i stället för att kuva henne tog han prinsessan till sin maka. Ur deras onaturliga förening föddes de första centaurerna. Den nyfödda rasen skämdes och greps av blodtörstig vrede, mördade sin far och tog över slätterna. De lämnade efter sig den sargade ödemark som nu är känd som Desolace."},{t="Stridande hovar",b="Inlandet i Desolace genljuder av tusentals hovar när fyra splittrade centaurstammar för evigt strider mot alla främlingar och mot varandra. Kolkar strövar på de östra klipporna, Magram håller till i grova jurtor kring bräckta slukhål, Gelkis bor bakom repbroar i djupa raviner i söder och de fanatiska Maraudine försvarar vägen till själva Maraudon. Resenärer som tar sig genom ödemarken dras ofta in i den uråldriga blodsfejden. De tvingas slakta en stam för att få fri lejd och inleda osäkra förhandlingar med en annan."},{t="Kulter och skuggiga kuster",b="Bortom de stridande centaurerna frodas mörkare faror längs gränserna. Kulten Burning Blade verkar obehindrat från Thunder Axe Fortress och Shadowbreak Ravine. Där åkallar de demoner och satyrer som hotar att dränka regionen i fel fire. Längs den stormiga kusten smyger naga upp på stränderna vid Ethel Rethor, medan Darkspear Trolls fiskar med spjut från Shadowprey Villages pålplattformar. Högt uppe bland de norra klipporna håller Alliance uppsikt från Nijel's Point. De misstänker att Horde vill utöka sitt inflytande och aktar sig för den demoniska besmittelse som sprider sig från Mannoroc Coven."}},faq={{q="Varför är Desolace en så död ödemark?",a="Enligt legenden var landet en gång bördigt. Jordelementaren prinsessan Theradras förbrukade regionens livskraft för att återuppbygga sin kropp. Kort därefter ödelade centaurernas födelse och våldsamma expansion den växtlighet som överlevt. Kvar blev bara grått damm och aska.",al={"varför är desolace dött","desolaces historia och ursprung"}},{q="Varifrån kom centaurerna?",a="Centaurerna är avkomma till Zaetar, halvguden Cenarius son, och elementaren prinsessan Theradras. De första khanerna avskydde sin förvridna gestalt och greps av vrede. De dödade sin far direkt efter födseln och förökade sig över slätterna i ett utbrott av brutalitet.",al={"centaurernas ursprung","vem skapade centaurerna","zaetar och theradras"}},{q="Kan jag sluta förbund med centaurstammarna här?",a="Ja. Äventyrare kan vinna anseende hos antingen stammen Gelkis eller stammen Magram genom att döda medlemmar ur rivalstammen. Om du vinner tillräckligt mycket anseende får du tillträde till deras by, stamuppdrag och fred inom deras område. Den andra stammen blir då permanent fientlig mot dig.",al={"anseende hos centaurer","gelkis eller magram","hur blir man vän med centaurer"}},{q="Vad är Maraudon?",a="Maraudon är centaurernas heliga förfädersgrav, dold djupt inne i Desolaces slingrande västra klippor. Där finns både Zaetars grav och prinsessan Theradras underjordiska lya. Hon fortsätter att sprida mörk elementarkorruption genom dess vidsträckta grottgångar.",al={"var ligger maraudon","maraudon-instansen","vad finns under desolace"}},{q="Vem är vandraren som strövar omkring i Desolace med en björn?",a="Det är Rexxar, Hordens mästare, som har sällskap av sin trogna björn Misha. Den halvtreslige vandraren patrullerar de dammiga vägarna i Desolace och Stonetalon Mountains. Han håller vildmarken under uppsikt och hjälper dem som utför viktiga uppdrag för Horde.",al={"rexxar i desolace","bestmästare i desolace","vem är orchen med en björn"}},{q="Varför bekämpar Alliance och Horde Burning Blade här?",a="Kulten Burning Blade har tagit över fästen som Thunder Axe Fortress för att åkalla demoner och binda felhästar. Demonerna och satyrerna som kulten kallar fram hotar att sprida demonisk smitta i hela regionen. Det är en fara som både Horde och Alliance måste bemöta.",al={"burning blade i desolace","kultister i thunder axe fortress","varför finns demoner här"}}},fp="8,209,24.445.0,14.468.0,25.490.0,38.221.0,32.220.0,40.243.0,17.238.0,49.233.0,63.210.0"}
P.entries["zone:dunmorogh"] = {n="Dun Morogh",s="Dun Morogh är ett snötäckt högland i hjärtat av Khaz Modan. Det är både dvärgarna i Ironforges uråldriga utgångspunkt och hemland och tillflyktsort för de fördrivna gnomerna från Gnomeregan. Trots väldiga bergstoppar och befästa pass hotas det snöiga riket allt mer inifrån av troggar, Frostmane-troll och bestrålade spetälska gnomer.",h="Dun Morogh är ett snötäckt högland i hjärtat av Khaz Modan.",kw={"anvilmar","brewnall village","coldridge valley","deeprun tram","dun morogh","frostmane","gnomeregan","gol'bolar","ironforge","kharanos","magni bronzebeard","troggar"},ang={["profession:Cooking"]="Lokala jägare och värdshusvärdar i Kharanos och Brewnall Village tar gärna vara på vildsvinskött, björnrevben och dvärgarnas starköl för att hålla den bitande bergskylan stången.",["profession:Mining"]="Bergsklipporna i Dun Morogh är rika på kopparådror nära ytan, särskilt kring stenbrottet vid Gol'Bolar och längs de snötäckta klippväggarna.",["race:Dwarf"]="Det här är ditt förfäders hemland. Från härdarna i Anvilmar till den flammande kärnan i Great Forge i Ironforge är det din plikt mot King Magni att försvara topparna mot troll och troggar.",["race:Gnome"]="Ditt förlorade hem, Gnomeregan, ligger bestrålat i den västra dalen. Dun Morogh är din bas i landsflykten, där du står vid dina dvärgkusiners sida och kämpar mot troggar och förrymda spetälska gnomer."},sec={{t="Ett fäste i bergen",b="Dun Morogh omfattar Eastern Kingdoms högsta toppar, ett alpint område omgivet av taggiga berg som skärmar av det från Searing Gorge i söder och Wetlands i norr. De snötäckta bergen ger upphov till floderna som rinner genom Khaz Modan och rymmer nästan outtömliga koppar- och järnådror. Tillträdet är starkt begränsat till bergstunnlar som North Gate Pass och South Gate Pass, som övervakas noga av dvärgarnas bergsvakter. Mitt i området ligger Ironforge, ett urgammalt underjordiskt underverk och huvudstad i King Magni Bronzebeards rike, direkt förbundet med Stormwind genom det makalösa Deeprun Tram."},{t="En delad tillflykt",b="För århundraden sedan drev dvärgarna de inhemska Frostmane-is-trollen upp i klipporna och banade plats åt sig själva tillsammans med sina briljanta gnomallierade. De två folken blomstrade i närliggande bergshallar fram till den senaste katastrofen i Gnomeregan under det tredje kriget. En fruktansvärd trogginvasion och ett katastrofalt radioaktivt gasutsläpp ödelade det teknologiska underverket, förvandlade dess försvarare till vettlösa spetälska gnomer och drev High Tinker Gelbin Mekkatorque och hans överlevande folk i landsflykt. Nu bor gnomerna som gäster i Ironforge, medan spetälska gnomer och överlevande troggar väller ut i Chill Breeze Valley."},{t="Oro i snödrivorna",b="Livet i snödrivorna är långt ifrån lugnt. Frostmane-stammen har blivit djärvare och upprättat tungt beväpnade läger från Shimmer Ridge ner till Coldridge Valley. Samtidigt har primitiva troggar klöst sig ut ur uråldriga underjordiska sprickor och in i Gol'Bolar Quarry, vilket hotar områdets gruvdrift. Mellan strövande yetier, vildsvin, infiltrerande agenter från Dark Iron-dvärgarna och giftigt nedfall från ruinerna av Gnomeregan har dvärgarnas bergsvakter fullt upp med att upprätthålla ordningen från Kharanos till gränsportarna."}},faq={{q="Vilka raser börjar i Dun Morogh?",a="Både dvärgar och gnomer börjar sina äventyr här i Coldridge Valley, en skyddad dal i sydvästra Dun Morogh, innan de ger sig av genom Coldridge Pass till Kharanos och resten av området.",al={"startande ras i dun morogh","vem börjar här","startområde för dvärgar","startområde för gnomer"}},{q="Vad hände med Gnomeregan?",a="Under det tredje kriget svärmade troggar, en underjordisk ras, in i Gnomeregan. I ett försök att rensa ut inkräktarna släppte High Tinker Gelbin Mekkatorque ut radioaktiv gas i de nedre nivåerna. Planen misslyckades katastrofalt. Tusentals dog och många gnomer bestrålades och förvandlades till vansinniga spetälska gnomer, vilket tvingade de friska överlevarna att fly till Ironforge.",al={"varför är gnomeregan förstört","vad hände med gnomerna","varför finns spetälska gnomer här"}},{q="Hur lämnar du Dun Morogh till fots?",a="Dun Morogh omges av höga bergsryggar. Om du vill ta dig österut till Loch Modan till fots följer du vägarna till North Gate Pass eller South Gate Pass i de nordöstra bergen. Du kan också resa direkt till Stormwind City med Deeprun Tram inne i Ironforge.",al={"utgång från dun morogh","dun morogh till loch modan","lämna dun morogh"}},{q="Var finns flygmästaren i Dun Morogh?",a="Den enda fungerande flygmästaren för Alliansen i området finns inne i Great Forge i Ironforge. Därifrån kan resenärer ta sig till platser runt om i Khaz Modan, Stormwind och Alliansens norra utposter.",al={"flygmästare i dun morogh","flygrutt i dun morogh","vart kan man flyga från dun morogh"}},{q="Vilka är Frostmane-trollen?",a="Frostmane är en stam av istroll som härskade över Dun Morogh långt innan dvärgarna trädde fram ur Uldaman. De besegrades och drevs upp i klipporna för generationer sedan, men är fortfarande bittra fiender till Ironforge och plundrar regelbundet dvärgarnas gårdar och vägar från tillhåll som Frostmane Hold.",al={"varför finns det troll i dun morogh","troll i dun morogh","frostmane-stammen"}},{q="Vad är Kharanos?",a="Kharanos är den främsta dvärgbosättningen i centrala Dun Morogh. Här finns Thunderbrew Distillery, tränare och förnödenheter. Orten fungerar som bas för unga äventyrare och bergsvakter som tar itu med lokala problem med troll och vilda djur.",al={"stad i dun morogh","kharanos knutpunkt","vad är huvudorten"}}},fx={ee70a2d7={q="Vad är Dun Morogh?",a="Dun Morogh är ett högt beläget, snötäckt bergslandskap i västra Khaz Modan. Höga bergstoppar omger det på alla sidor och gör det till Ironforge-dvärgarnas förfäders hemtrakter och gnomernas tillflyktsort. Området är känt för sin stränga kyla, täta tallskogar, frusna sjöar och stora mineralrikedomar. Längs de norra bergskammarna ligger den magnifika bergsborgen Ironforge, och i de västra kullarna finns den belägrade teknostaden Gnomeregan.",al={"vad är det här för plats","var är vi","dun morogh-zonen"}},["8c7c9511"]={q="Vad har hänt i Dun Moroghs historia?",a="Dun Morogh behärskades ursprungligen av Frostmanes istroll. Dvärgar och gnomer slog sig senare ner på de snöklädda topparna och knöt ett varaktigt vänskapsband. De byggde Ironforge och Gnomeregan och trängde tillbaka Frostmane till avlägsna bergsklyftor. Under det andra kriget försvarade dvärgar och gnomer framgångsrikt sina bergsfästen mot orchernas Horde. I dag har de fridfulla trakterna drabbats av oro efter Gnomeregans fall och de allt fler trogginvasionerna.",al={"dun moroghs historia","vad hände här"}},["4399d516"]={q="Vem bor i Dun Morogh och vem styr där?",a="Dun Morogh styrs främst av King Magni Bronzebeard från hans tron i bergsfästet Ironforge. Dvärgarna av Bronzebeard-klanen bemannar garnisoner, utposter och vakttorn längs bergspassen. Dun Morogh är också hem för gnomerna, vars ledare High Tinker Gelbin Mekkatorque och överlevande folk nu har sökt skydd hos sina dvärgallierade efter Gnomeregans tragiska fall. Bortom bosättningarna utmanar Frostmane-troll och primitiva troggar dvärgarnas makt i vildmarkens bergsklyftor och stenbrott.",al={"vem styr dun morogh","vem kontrollerar dun morogh","vem bor här"}},["1f8f2322"]={q="Är Dun Morogh farligt?",a="Dvärgarnas bergsvakter skyddar landsvägarna och städerna, men vildmarken innebär allvarliga faror. Grizzlybjörnar, bergsvildsvin, utsvultna vargar och ursinniga wendigor strövar omkring i snödrivorna. Fientliga Frostmane-istroll gör räder från bergsryggar som Shimmer Ridge och Frostmane Hold. Under tiden har troggar från underjorden tagit över Gol'Bolar Quarry och Coldridge Pass, och radioaktiva spetälska gnomer stryker omkring i de förorenade utkanterna av Gnomeregan.",al={"är dun morogh säkert","hot i dun morogh","faror i dun morogh"}},["6bfc0e90"]={q="Varför vill alla att jag ska döda troggar i Gol'Bolar Quarry?",a="Gol'Bolar Quarry i sydöstra Dun Morogh är en viktig dvärgisk utgrävningsplats och gruvbosättning. Gruvarbetarna grävde efter sten och värdefull malm, men bröt igenom till underjordiska tunnlar och grävde fram horder av vilda troggar. Varelserna vällde ut i det öppna dagbrottet och gruvan, drev tillbaka arbetarna och tvingade verksamheten att stänga. Bergsvakterna och arbetsledarna behöver dugliga rekryter som kan utrota de invaderande troggarna så att kungariket kan återta stenbrottet.",al={"troggar i gol'bolar","varför döda troggar i stenbrottet","problem i gol'bolar quarry"}},bf67ca5d={q="Vart ska jag ta vägen efter Dun Morogh?",a="När du har slutfört dina uppgifter i Dun Morogh och fått tillräckligt med erfarenhet leder resan naturligt österut till Loch Modan. Du kan gå genom tunnlarna i antingen North Gate Pass eller South Gate Pass, eller ta en gryfon från den stora flygmästarens näste i Ironforge direkt till byn Thelsamar vid sjön.",al={"vart går jag efter dun morogh","nästa område efter dun morogh","efter dun morogh"}},["44145090"]={q="Hur hamnade jag i Dun Morogh?",a="Om du är en dvärg eller gnom som just har gett dig ut på äventyr började du på Coldridge Valleys skyddade träningsmarker innan du tog dig genom passet till själva Dun Morogh. Dvärgarna kommer från dessa karga toppar, medan gnomflyktingar flydde hit efter Gnomeregans fall för att söka skydd hos sina dvärgallierade. Resenärer från andra kungariken anländer vanligtvis genom Ironforges storslagna portar via Deeprun Tram från Stormwind, eller genom att färdas västerut genom bergspassen från Loch Modan.",al={"hur hamnade jag här","hur kom jag till dun morogh","varför kom jag hit"}},["8cf74af4"]={q="Vad ska jag göra i Dun Morogh?",a="Ironforges snöklädda rike behöver varje stridsduglig försvarare. Fientliga Frostmane-troll hotar dvärgarnas bosättningar från de höga bergsryggarna, vilda troggar har tagit över Gol'Bolar Quarry och muterade spetälska gnomer stryker omkring i Gnomeregans förorenade ruiner i väster. Bosättningar som Kharanos och Brewnall Village behöver desperat rekryter som kan driva tillbaka vilddjuren och röja stigarna. Hjälp till att säkra trakten, slipa dina färdigheter och visa att du är värdig att svara på Alliansens större kallelse.",al={"vad ska jag göra här","vad är mitt mål i dun morogh","vad gör jag här"}}},fp="10,226,21.341.0,16.532.0,21.397.0,31.294.0,28.274.0,36.235.0,41.202.0,29.271.0,17.212.0"}
P.entries["zone:durotar"] = {n="Durotar",s="Durotar är det torra hemlandet med röd klippa, grundat av hövding Thrall efter det tredje kriget och uppkallat efter hans far Durotan. Landet avgränsas av Southfury River och det stora havet och utgör Nya hordens kärnland och prövningsplats för unga orcher och Darkspear Trolls. I de karga ravinerna finns befästa bosättningar som Razor Hill, krigarstaden Orgrimmar och fientliga skansar med allt från quilboarstammar till strandsatta allianssoldater.",h="Durotar är det torra hemlandet med röd klippa, grundat av hövding Thrall efter det tredje kriget och...",kw={"durotan","durotar","echo isles","orgrimmar","razor hill","sen'jin village","skull rock","southfury river","thrall","tiragarde keep","valley of trials","zalazane"},ang={["class:Shaman"]="Det torra landskapet är genomsyrat av elementandar rå kraft. Unga schamaner besöker heliga platser som Spirit Rock och Shrine of the Dormant Flame för att stämma sig med jord och eld.",["class:Warlock"]="Thrall håller mörk magi under sträng uppsikt och tvingar Shadow Councils kulter att gömma sig på platser som Skull Rock och under staden i Ragefire Chasms vindlande grottor.",["faction:Alliance"]="Durotar är hjärtat i hordens militära styrka. Alla alliansresenärer som påträffas i de solstekta ravinerna jagas genast av aggressiva patruller och traktens vilddjur.",["race:Orc"]="Durotar är ditt folks nya utlovade land, vunnet med svett och blod efter år av demonisk dvala och fångenskap. Att visa sitt värde i Valley of Trials är det första övergångsprovet för varje ny hjälte i horden.",["race:Troll"]="Efter att ha undkommit sjöhäxan i det stora havet fann Darkspear en fristad hos Thrall i Durotar, men förrädaren Zalazane tog över Echo Isles inifrån. Att återta öarna och försvara Sen'jin Village är personligt."},sec={{t="Ett hårt nytt hem",b="När Thrall ledde sitt folk över det stora havet till Kalimdor sökte han medvetet en otämjd gränsmark där orcherna kunde skapa en hederlig tillvaro genom arbete och uthållighet i stället för erövring. Durotars spruckna röda jord, uttorkade raviner och höga klippspiror påminner orcherna starkt om Draenor före dess undergång. Klimatet är obarmhärtigt, med lite odlingsbar mark och knappt om vatten, men horden tog till vara på landskapets naturliga försvar och strama storslagenhet. I väster gränsar Durotar, på andra sidan Southfury River, till det öppna Barrens och i norr till Azsharas ödelagda vildmark. Durotar står som ett levande bevis på att orcherna har format sitt eget öde."},{t="Fiender vid gränsen",b="Durotar står fast under hordens styre, men kampen om att säkra landet pågår ännu. Razormane-quilboar, som drevs bort när landet grundades, plundrar ständigt bosättningar och gårdar från klipporna i väster. Längre söderut håller rester av storamiral Daelin Proudmoores flotta från Kul Tiras fortfarande den förfallna garnisonen i Tiragarde Keep under löjtnant Benedict och vägrar kapitulera. Än värre är att demoniska rester av Burning Blade-kulten gömmer sig i dolda raviner och djupa havsgrottor och försöker i hemlighet korrumpera unga orcher på nytt med löften om felmakt."},{t="Darkspears prövningar",b="Längs sydkusten ligger Sen'jin Village, basen för de landsförvisade Darkspear-trollen. Under ledning av Master Gadrin tvingades Darkspear bort från sitt hem på de närbelägna Echo Isles, efter att häxdoktorn Zalazane förlorat förståndet och använt mörk voodoo för att förslava sina fränder. Darkspear kan inte återta öarna på egen hand. De förlitar sig på nyutbildade krigare bland orcher och troll, som träder fram från Valley of Trials för att bryta Zalazanes grepp och säkra kusten."}},faq={{q="Varför slog Thrall ner hordens bopålar i en så karg öken?",a="Thrall valde medvetet detta obarmhärtiga område. Den röda jorden och de karga platåbergen påminde orcherna om deras förfäders värld Draenor, medan de hårda förhållandena blev en botgöring och en härd för disciplin. Thrall trodde att hans folk behövde förtjäna sin överlevnad genom hederliga umbäranden i stället för att erövra bördiga marker. På så sätt skulle de inte falla tillbaka i blodtörstig självbelåtenhet.",al={"varför bosätta sig här","varför durotar","varför är durotar kargt"}},{q="Vem fick Durotar sitt namn efter?",a="Landet namngavs till ära för Durotan, Thralls avlidne far och den tidigare hövdingen för Frostwolf-klanen. Durotan hade motsatt sig orkklanernas demoniska fördärv och mördades på trollkarlen Gul'dans order.",al={"vem är durotar uppkallat efter","durotan","durotars namns ursprung"}},{q="Varför finns det mänskliga soldater i Tiragarde Keep?",a="Soldaterna i Tiragarde Keep är överlevande marinsoldater från Kul Tiras under löjtnant Benedict, rester av storamiral Daelin Proudmoores invasionsflotta. Även efter att Proudmoore dödades vägrade trupperna att kapitulera eller dra sig tillbaka och håller fast vid en fientlig utpost på Durotars sydkust.",al={"varför finns människor i durotar","människor i tiragarde keep","proudmoores trupper i durotar"}},{q="Vad handlar konflikten på Echo Isles om?",a="Darkspear-trollen grundade ursprungligen sitt hem på Kalimdor på Echo Isles. Men en mäktig häxdoktor vid namn Zalazane dukade under för galenskapen och vände sin mörka magi mot sina fränder och förslavade deras sinnen. De överlevande flydde till fastlandet och grundade Sen'jin Village, varifrån de ger sig ut på räder för att bryta hans grepp.",al={"vad hände på echo isles","varför sen'jin village","zalazanes bakgrund"}},{q="Vad gör Burning Blade i Durotar?",a="Burning Blade är en undergrävande demonkult som är lojal mot Shadow Council och Burning Legion. Agenter gömmer sig på avskilda platser som Skull Rock och i Burning Blade Coven, där de försöker underminera Thralls ledarskap och locka lättledda orcher tillbaka till demoniskt slaveri.",al={"burning blade i durotar","kultister vid skull rock","demoner i durotar"}},{q="Hur förbinds Durotar med andra områden?",a="En bro över Southfury River leder västerut till Barrens. Utanför Orgrimmar erbjuder ett zeppelintorn flygresor över hela kontinenten direkt till Tirisfal Glades och Grom'gol Base Camp i Stranglethorn Vale.",al={"hur lämnar man durotar","resor i durotar","utgångar från durotar"}}},fx={["6c467bea"]={q="Varför bor troll i Durotar?",a="Darkspear-stammen har Thrall att tacka för sin överlevnad. Han räddade dem när deras ursprungliga öhem började sjunka under vattenlevande fienders angrepp. De svor trohet till Horden och följde med orcherna till Kalimdor. Där fick de de närliggande Echo Isles att bo på, samtidigt som de behöll nära kulturella och militära band till Orgrimmar.",al={"varför är troll här","darkspear i durotar"}},["84e0b3bb"]={q="Vart går färden efter Razor Hill?",a="När du har bevisat din styrka kring Razor Hill får du order om att antingen bege dig norrut, genom Orgrimmars ståtliga portar för att träffa högre militärledare, eller västerut över Southfury River till The Barrens vidsträckta slätter. Där väntar större strider mot quilboar, kentaurer och alliansens inkräktare.",al={"efter razor hill","vart efter razor hill","nästa område efter razor hill"}},["25a880c0"]={q="Hur hamnade jag i Durotar?",a="Är du en orch är detta karga, röda land ditt folks nya självständiga hem, som hövding Thrall gjorde anspråk på efter uttåget från Eastern Kingdoms. Du växte upp här och skickades till den avskilda Valley of Trials för att pröva din styrka under ökensolen innan du förtjänade din plats i Horden. Är du ett Darkspear-troll flydde ditt folk över Stora havet tillsammans med Thrall och slog sig ned vid kusten efter att ha drivits bort från närbelägna Echo Isles av den förrädiske häxdoktorn Zalazane.",al={"hur kom jag hit","varför är jag i durotar"}},d894869f={q="Vad förväntas jag göra i Durotar?",a="Du är här för att bevisa ditt värde för Horden och trygga överlevnaden för en ung nation. Durotar är fortfarande en hård gränsbygd som hotas från alla håll. Razormane-quilboar plundrar bosättningar, mänskliga kvarlevor från Kul Tiras klamrar sig envist fast vid Tiragarde Keep och den lömska kulten Burning Blade smider planer i skuggiga raviner. Genom att hjälpa utposter som Razor Hill och Sen'jin Village tämjer du klipporna, skyddar utsatta bosättningar och förtjänar din plats bland hjältarna som vandrar på gatorna i närbelägna Orgrimmar.",al={"vad ska jag göra i durotar","vad är mitt syfte här","vad gör jag här"}},["04dde4a2"]={q="Vad är Durotar?",a="Durotar är ett klippigt, solstekt land på Kalimdors östra kust och den stolta hembygden för Horde. Warchief Thrall grundade landet efter det tredje kriget. Dess röda jord, taggiga raviner och hårda klimat är avsiktligt utformade för att påminna om Draenor, orchernas förfädersvärld. Durotar gränsar till Southfury River i väster och Stora havet i söder och öster. Här ligger huvudstaden Orgrimmar, och landet ger skydd åt både orcher och Darkspear-troll.",al={"om durotar","information om durotar","var ligger durotar"}},cb6442fd={q="Vad hände i Durotar?",a="Durotar var ursprungligen ett löst hållet strövområde för quilboarstammar, men blev målet för Thralls folkutvandring över Stora havet. När allierade styrkor hade drivit tillbaka de inhemska bestiastammarna och besegrat Burning Legion vid Mount Hyjal, grundade Thrall formellt Durotar som en självständig orchisk nation. Kort efter landets grundande invaderade Grand Admiral Daelin Proudmoores flotta den östra kusten. Horde slog dock tillbaka armadan och drev de kvarvarande människorna till Tiragarde Keep.",al={"durotars historia","durotars förflutna"}},b3a1e6d0={q="Vilka bor i Durotar?",a="Durotar styrs som ett stamhövdingadöme av Warchief Thrall från Orgrimmar. Orcher utgör den stora majoriteten av befolkningen, tillsammans med landsförvisade Darkspear-troll som samlats kring Sen'jin Village. Taurenallierade och besökande ambassadörer från Forsaken färdas ofta genom trakten, medan fientliga grupper av quilboar, kentaurer, harpyor och marinsoldater från Kul Tiras utmanar gränserna i de yttre bergsklyftorna.",al={"vem styr durotar","durotars befolkning","durotars invånare"}},b78335a1={q="Är Durotar farligt?",a="Ja. Bortom de befästa vägarna och portarna till bosättningar som Razor Hill och Orgrimmar är Durotar till stor del otämjt. Giftiga skorpioner, rovgiriga raptorer och krokolisker stryker omkring i vildmarken. Än värre är att fiender ständigt trakasserar resande från Horde: Razormane-quilboar anfaller från de norra ravinerna, Kolkar-kentaurer gör räder mot vattenhålen, människornas marinsoldater håller Scuttle Coast och Burning Blades hemliga trollkarlar lurar i närheten.",al={"är durotar säkert","hot i durotar","faror i durotar"}},["923cfd3c"]={q="Vad är Razor Hill och varför ligger det här?",a="Razor Hill är den viktigaste befästa vägkorsningen i centrala Durotar. Den ligger mitt i korsningen mellan Sen'jin Village i söder, The Barrens på andra sidan Southfury River i väster och Orgrimmar i norr. Därifrån samordnas Hordes försörjning och försvar. Bosättningen domineras av militärbarackerna och vakttornet. Härifrån samordnas gränspatruller, och platsen fungerar som den främsta utposten som skyddar resande från kustens marinsoldater och rövare.",al={"razor hill","om razor hill","varför razor hill"}},["1bf45605"]={q="Vem byggde Razor Hill?",a="Razor Hill byggdes av Thralls Horde kort efter ankomsten till Kalimdor. Till en början var det bara en kal kulle vid gränsen, berömd som platsen där Rexxar avvärjde ett bakhåll från Kul Tiras-styrkor som siktade på Thrall. Platsen befästes med en rejäl barack och jordhålor för att stärka Hordes försvar mellan havet, ravinerna och den nordliga huvudstaden.",al={"vem byggde razor hill","razor hills ursprung"}},["6b0364de"]={q="Är Razor Hill en del av Orgrimmar?",a="Det är inte en del av själva staden, men står direkt under Orgrimmars förvaltning och militära befäl. Razor Hill fungerar som en yttre garnisonsstad och samlingsplats i centrala Durotar. Där kontrolleras anländande resenärer, rekryter tränas och de södra infartsvägarna till huvudstadens höga norra portar säkras.",al={"ligger razor hill i orgrimmar","razor hill och orgrimmar"}},["406d1dd3"]={q="Bodde det någon i Durotar innan Horde kom?",a="Quilboarfolket gjorde anspråk på landet långt innan Horde anlände. Taggiga stammar, i synnerhet Razormane, höll till i bergsklyftorna och längs flodbankarna i det som räknades till det större Barrens. Avgörande fälttåg under Thralls ledning drev dem till avlägsna raviner och västerut över Southfury River, men de kämpar fortfarande ursinnigt för att återta sina förfäders land.",al={"vilka bodde här först","durotars ursprungsbefolkning"}},f5af283b={q="Vem har befälet kring Razor Hill?",a="Lokalt försvar och militära insatser i Razor Hill sköts av erfarna veteraner som Gar'Thok, medan orchiska ämbetsmän som Orgnil Soulscar leder kontraspionage och interna utredningar. Tillsammans sköter de stadens försvar, organiserar jaktexpeditioner och ger lovande rekryter i uppdrag att försvara centrala Durotar.",al={"ledare i razor hill","vem leder razor hill"}},["87682b7e"]={q="Vilka är sjömännen från Kul Tiras och varför är de på vår kust?",a="De är resterna av den stora armada som leddes av den avlidne Grand Admiral Daelin Proudmoore från Kul Tiras. Proudmoore vägrade att acceptera fred med orcherna och anlade Tiragarde Keep längs den östra kusten som ett fäste för kriget. Även efter att admiralen dödats i Theramore befäste sig hans överlevande officerare i ruinerna och fortsatte sin obevekliga kampanj mot Horde.",al={"sjömän från kul tiras","varför finns människor i durotar","sjömän i tiragarde keep"}},["52bc9e7d"]={q="Vem är Lieutenant Benedict?",a="Lieutenant Benedict är den överlevande officeren från Kul Tiras som för befäl över den fientliga garnisonen i Tiragarde Keep. Efter Admiral Proudmoores död samlade Benedict de kvarvarande soldaterna och marinsoldaterna under de stående orderna. Han upprätthåller ett befäst människofäste i Durotar som regelbundet trakasserar orchiska bosättningar och karavaner.",al={"lieutenant benedict","benedict i tiragarde","vem är benedict"}},["9c6f22ef"]={q="Vad är Sen'jin Village?",a="Sen'jin Village är en fiskeby vid Durotars södra kust och Darkspear-trollens tillfälliga hem. Hövding Vol'jin grundade byn, där alkemister, jägare och shamaner arbetar för att säkra fastlandskusten och skydda den mot vattenmonster och förrädiska fränder på andra sidan vattnet.",al={"sen'jin village","vad är sen'jin","sen'jin"}},["115273b6"]={q="Vem var Sen'jin?",a="Sen'jin var en vördad skuggjägare och hövding för Darkspear-stammen på deras förfädersöar i Stora havet. Under det tredje kriget förutsåg han Thralls ankomst och att hans folk skulle befrias, men gav sitt liv för att försvara stammen mot ursinniga murlocer och havshäxor innan de hann fly.",al={"vem är sen'jin","sen'jins bakgrund"}}},fp="7,395,16.374.0,23.415.0,27.369.0,56.632.0,28.226.0,51.345.0,39.378.0,43.280.1,39.261.0"}
P.entries["zone:duskwood"] = {n="Duskwood",s="Duskwood var en gång en solbelyst skog, men är nu en förbannad skog som ligger fångad i ett onaturligt, evigt dunkel. Stormwinds myndigheter har övergivit området, och de belägrade människorna klamrar sig fast vid livet i Darkshire under den lokala Night Watch-milisens vakande beskydd. I de mörka dungarna och hemsökta gravhögarna strövar människoätande gastar, jättelika giftspindlar, plundrande ogres och vilda, mystiska worgen.",h="Duskwood var en gång en solbelyst skog, men är nu en förbannad skog som ligger fångad i ett onaturligt, evigt...",kw={"althea ebonlocke","brightwood","darkshire","duskwood","ello ebonlocke","jitters","morbent fel","night watch","raven hill","scythe of elune","sven yorgen","twilight grove","worgen"},ang={["class:Druid"]="I Twilight Grove står ett uråldrigt Great Tree med starka band till The Emerald Dream, vilket gör Duskwood till en viktig plats för druider som undersöker världens slumrande magi.",["class:Paladin"]="De vanhelgade gravhögarna i Raven Hill och Morbent Fels kusliga nekromanti gör Duskwood till en plats där heliga korsfarare som brukar Ljuset måste prövas utan dröjsmål.",["faction:Alliance"]="Duskwood tillhör formellt Alliansen, men får inget officiellt militärt stöd från Stormwind. Området förlitar sig helt på hjältemodiga äventyrare och Night Watch för att hålla förintelsen stången.",["profession:Herbalism"]="De hemsökta gravhögarna och den förbannade jorden ger sällsynta växter som Grave Moss och Kingsblood, vilket lockar samlare som vågar trotsa rastlösa odöda på kyrkogårdarna."},sec={{t="Från solljus till skugga",b="Innan mörkret föll var provinsen en bördig jordbruksbygd i kungariket Stormwind, med välmående bosättningar som Grand Hamlet och Raven Hill. Områdets tragedi började när Guardian Medivh föll vid Karazhan under det första kriget och släppte lös vågor av förvriden felmagi som förvandlade den fridfulla skogen till en knotig, skuggig sumpmark. Spindlar muterade till fruktansvärda rovdjur, medan flyende vargar strömmade norrut till Elwynn Forest. Med tiden döptes Grand Hamlet om till Darkshire, och dess skräckslagna invånare lämnades till stor del att klara sig själva när rikets kungliga garnison drog sig tillbaka för att försvara huvudstaden."},{t="Liemannen och vargmännen",b="Landets nutida mardröm fördjupades när en nattalvprästinna vid namn Velinde Starsong anlände med en övernaturlig artefakt kallad Scythe of Elune. När hon försvann i den nedlagda gruvan Roland's Doom grävdes reliken så småningom upp av en gruvarbetare vid namn Jitters. Hans vårdslösa hantering av vapnet släppte lös glupska, tvåbenta varbestar kallade worgen i skogen. Dessa rovdjur från en annan dimension, insvepta i ständig dimma och blodtörst, härjade i de västra dungarna och förvärrade lidandet i ett område som redan dignade under odöda förbannelser."},{t="Ett utsatt gränsland",b="I dag överlever Darkshire endast tack vare Commander Althea Ebonlockes och hennes frivilliga milis, Night Watch, vaksamhet, medan Lord Ello Ebonlocke försöker styra den sönderfallande bosättningen. Utanför stadens lyktsatta gräns väntar ren livsfara: den väldiga Raven Hill Cemetery sjuder av rastlösa döda som väckts av nekromantikern Morbent Fel, Vul'Gol-ogres har vandrat från Deadwind Pass för att ta södern i besittning, och kusliga Dark Riders stryker omkring vid vägskälen i sin outtröttliga jakt på den försvunna lien."},{t="Twilight Grove",b="Nära mitten av Duskwood ligger en djup, uråldrig krater som trotsar den omgivande förvridningen: Twilight Grove. Här står ett uråldrigt Great Tree med en slumrande portal till The Emerald Dream. Badad i ett mjukt, eteriskt skymningsljus förblir gläntan en övernaturlig fristad i ett annars döende land, bevakad av slumrande druidiska krafter."}},faq={{q="Varför kallas det Duskwood?",a="Landet var en gång en livfull, solbelyst provins i Stormwind. När Guardian Medivh dödades i närbelägna Karazhan under det första kriget sköljde instabila felenergier över skogen, kvävde solljuset, förvrängde växtligheten och gav upphov till namnet Duskwood.",al={"varför är duskwood mörkt","brightwoods historia","vad hände med brightwood"}},{q="Varifrån kom worgen?",a="Nattalven Velinde Starsong förde den mystiska Scythe of Elune till området och dog nära Roland's Doom. Flera år senare störde en skräckslagen arbetare vid namn Jitters lien i gruvan och öppnade ovetande revor som kallade de vilda vargmännen till skogen.",al={"varför finns det worgen","worgens ursprung i duskwood","scythe of elune och worgen"}},{q="Varför finns det så många odöda i Raven Hill?",a="Raven Hill Cemetery var viloplats för oräkneliga själar som gått under av svält, bestar och krig. Den avskyvärde nekromantikern Morbent Fel slog sig ner på Forlorn Rowe och använde mörk magi för att väcka gravarna till gastar, skelett och styggelser.",al={"odöda i raven hill","varför finns det spöken i duskwood","morbent fels odöda"}},{q="Varför har Stormwind inte skickat soldater för att hjälpa Darkshire?",a="Eftersom kung Varian Wrynn är försvunnen och resurserna är hårt ansträngda har Stormwinds regentskap kallat tillbaka militären för att skydda Elwynn och tronen. Darkshire lämnas helt åt sig självt och försvaras enbart av frivilligmilisen Night Watch.",al={"varför finns ingen stormwind-vakt","stormwind övergav darkshire","var är armén"}},{q="Vilka är Dark Riders som stryker omkring i skogen?",a="Dark Riders är mystiska, huvbärande ryttare från Deadwind Pass nära Karazhan. De lockades av att Scythe of Elune släpptes lös och drog in i Duskwood, där de skoningslöst slaktade Sven Yorgens familj under jakten på artefakten.",al={"dark riders i deadwind","ryttarna vid yorgens gård","vilka är dark riders"}},{q="Vad är det väldiga trädet i kraterns mitt?",a="Kratern är Twilight Grove, där ett uråldrigt Great Tree står. Trädet rymmer en portal till The Emerald Dream och upprätthåller ett lugnt, mystiskt skymningsljus som skiljer sig från skogens förbannade mörker.",al={"trädet i twilight grove","grön portal i duskwood","kraterns träd"}}},fx={["31aef3fe"]={q="Vad är Duskwood? Varför är det alltid mörkt här?",a="Duskwood är ett dystert, tätt skogsklätt område söder om Elwynn Forest. Det var en gång en grönskande provins i kungariket Stormwind. Landet föll i ett onaturligt, evigt skymningsljus när Medivh dödades i Karazhan. Då frigjordes vågor av mörk magisk energi som vissnade växtligheten, framkallade tät svart dimma och lockade otaliga vidunder att ströva under trädens kronor.",al={"varför är duskwood mörkt","vad hände med duskwood","duskwoods historia"}},a3ed01d1={q="Har Duskwood alltid sett ut så här?",a="Nej. Före det första kriget var det ett solbelyst område med blomstrande bosättningar som Grand Hamlet och Raven Hill. Räder från den gamla Horden och den magiska katastrof som följde på Medivhs fall förvandlade den soliga skogen till det skuggiga mardrömsrike du ser i dag.",al={"var duskwood alltid mörkt","brightwoods historia","duskwoods förflutna"}},["9267ad89"]={q="Är mörkret i Duskwood magiskt eller naturligt?",a="Det är helt och hållet magiskt. Den ständigt mulna himlen och den kvävande dimman beror på mörka förbannelser som släpptes lös när Medivh dog i närbelägna Deadwind Pass, i kombination med uråldriga föremål som Scythe of Elune, vilka rubbar skogens naturliga ordning.",al={"är dimman i duskwood magisk","magisk förbannelse i duskwood","varför är solen borta i duskwood"}},aa573e0c={q="Vem styr över Darkshire?",a="Darkshire styrs av borgmästaren Lord Ello Ebonlocke tillsammans med Darkshires råd. Staden förlitar sig i hög grad på sina egna invånare för att upprätthålla ordningen och skipa rättvisa i stadshuset.",al={"darkshires ledare","vem styr darkshire","darkshires råd"}},["63356d06"]={q="Vem är Lord Ello Ebonlocke?",a="Lord Ello Ebonlocke är överhuvud för den framstående adelsfamiljen Ebonlocke, vars rötter i Grand Hamlet sträcker sig längre tillbaka än det första kriget. Som borgmästare kämpar han envist för att hålla Darkshire igång trots att Stormwinds kungliga hov har skurit av staden från militär hjälp.",al={"vem är ello ebonlocke","lord ebonlocke","borgmästare i darkshire"}},a73a6b59={q="Är Darkshire fortfarande lojalt mot Stormwind?",a="Ja, Darkshire är formellt fortfarande lojalt mot Alliansen och kung Anduin, men folket hyser en djup bitterhet. De känner sig helt övergivna av huvudstadens adel och tvingas försvara sig själva mot monster vid varje gräns.",al={"tillhör darkshire alliansen","är darkshire lojalt mot stormwind","lyder darkshire under stormwind"}},ec7f551f={q="Vad är Night Watch och varför behöver de min hjälp?",a="Night Watch är en lokal frivilligmilis som bildats och tränats av Darkshires invånare för att patrullera huvudvägarna och försvara byn. När Stormwinds armé har dragits tillbaka är de alldeles för få för att bekämpa gastar, skelett, worgen och vilddjur, så de måste anlita kringvandrande äventyrare för att minska hoten.",al={"vad är night watch","night watch-milisen","varför hjälpa night watch"}},be442b70={q="Vem är Commander Althea Ebonlocke?",a="Commander Althea Ebonlocke är Lord Ellos dotter och Night Watchs beslutsamma ledare. Hon samordnar försvaret av Darkshire och värvar själv hjältar för att slå tillbaka mot de odöda och andra vidunder som kryper fram ur skogen.",al={"commander althea","vem är althea ebonlocke","night watchs befälhavare"}},c10a928d={q="Varifrån kommer alla dessa skelett och gastar?",a="De döda rör sig främst vid Raven Hill Cemetery och Tranquil Gardens Cemetery. Nekromantikern Morbent Fel, som håller till i sitt hem högst upp på Forlorn Rowe, utövar aktivt mörk magi för att väcka lik till liv och förvandla traktens gravplatser till vandrande legioner.",al={"varför finns odöda i duskwood","varifrån kommer skeletten i duskwood","var kommer gastar ifrån"}},f53dcf97={q="Vad hände vid Raven Hill? Varför är det övergivet?",a="Raven Hill var en gång en stor stad, systerstad till Grand Hamlet. När mörka förbannelser och vidunderliga varelser översvämmade den omgivande landsbygden flydde de levande eller blev slaktade. I dag har den vidsträckta kyrkogården slukat området, och bara några få skräckslagna utstötta som Jitters vågar närma sig ruinerna.",al={"raven hills historia","varför är raven hill övergivet","vad hände med raven hill"}},["64d771df"]={q="Varför är alla i Darkshire så dystra och rädda?",a="Byborna lever i ständig skräck. De är belägrade från alla håll av onaturliga rovdjur, worgen och rastlösa döda, utan officiella förstärkningar från Stormwind. Varje färd bortom stadens fackelupplysta centrum riskerar att sluta i ett bakhåll från fasor som smyger i mörkret.",al={"darkshires invånare är rädda","varför är darkshire rädda","darkshires paranoia"}},["2e45eefe"]={q="Är Duskwood farligt?",a="Ytterst farligt. Vilda worgen, jättelika giftspindlar, kringströvande gastar, aggressiva ogres och Defias-banditer lurar längs vägarna. Om du ens avviker lite från stigen in i skogen kan du hamna öga mot öga med dödliga odöda krigare eller fasor som inte syns.",al={"är duskwood farligt","hur farligt är duskwood","hotnivå i duskwood"}},["4f653c45"]={q="Hur hamnade jag i Duskwood?",a="Du kom troligen söderifrån, från Elwynns soliga fruktodlingar och över Nazferiti River, eller följde vägen sydost från Westfalls torra slätter. Resenärer kommer också ofta via den södra bron från Redridge efter att ha hjälpt folket i Lakeshire. Så snart du passerade under det täta lövverket försvann dagsljuset bakom ett ogenomträngligt mörker. Kungariket Stormwind gör fortfarande anspråk på provinsen på papperet, men dess soldater har sedan länge övergett gränslandet. Den som korsar dess gränser får därför vandra ensam längs dessa skuggiga vägar.",al={"hur kom jag till duskwood","hur kom jag hit","varifrån kom jag till duskwood"}},["39e18767"]={q="Vad förväntas jag göra i Duskwood?",a="Darkshire utkämpar en desperat kamp för sin överlevnad, och eftersom Stormwind vägrar skicka förstärkningar vädjar invånarna till varje duglig resenär om hjälp. Den lokala milisen, Night Watch, behöver ditt svärd för att driva tillbaka gastar, skelett och mardrömslika worgen som närmar sig staden och vägarna. Fråga Commander Althea Ebonlocke och borgmästare Ello Ebonlocke i Darkshire, eller res västerut för att undersöka fasorna kring gravplatsen vid Raven Hill. Oavsett om du rensar bort spindlar som breder ut sig eller undersöker den mörka historia som hemsöker övergivna gårdar kommer landet att pröva din tapperhet till det yttersta.",al={"vad gör jag i duskwood","varför är jag här i duskwood","vad är mitt mål här"}}},fp="8,307,23.516.0,27.456.1,24.445.0,18.302.0,26.262.0,31.267.1,43.223.0,53.223.0,43.221.1,46.207.0"}
P.entries["zone:dustwallow"] = {n="Dustwallow Marsh",s="Dustwallow Marsh är ett vidsträckt, kvävande hett träskland mitt i Kalimdor, inklämt mellan The Barrens torra slätter och det Stora havet. Ständiga underjordiska källor håller det förrädiska kärrlandet vattenfyllt. Där finns farliga rovdjur, hemliga strider mellan fraktioner och den svarta drakflockens hotande närvaro. I öster ligger Theramore, en öfästning tillhörande Alliansen, och i nordväst bor de hordallierade Stonemaul-ogrerna i Brackenwall Village.",h="Dustwallow Marsh är ett vidsträckt, kvävande hett träskland mitt i Kalimdor, inklämt mellan The Barrens torra...",kw={"alcaz","brackenwall","dustwallow","jaina","träsk","onyxia","quagmire","stonemaul","tabetha","theramore","wyrmbog"},ang={["class:Mage"]="Magiker korsar kärrlandet till Tabetha's Farm i The Quagmire för att söka upp eremitens särskilda kunskap om arkana ledare och uråldriga kraftkällor.",["faction:Alliance"]="I Dustwallow Marsh ligger Theramore Isle, hjärtat för Alliansens närvaro på Kalimdor. Äventyrare som anländer via Menethil Harbor vaktar vägarna och nystar upp ett nät av desertörer och försvunna sändebud.",["faction:Horde"]="Hordens sändebud kommer för att stödja de hårt ansatta Stonemaul-ogrerna i Brackenwall Village, slå tillbaka drakarnas attacker från Wyrmbog och hålla ett vaksamt öga på människornas rörelser längs kusten."},sec={{t="Ett dränkt landskap",b="Före den stora omvälvningen var Dustwallow en hög, gräsbevuxen slätt full av hjorddjur. Katastrofen slet sönder dalen, fick grundvattnet att stiga och dränkte marken i ändlösa stillastående pölar, mossiga grund och kvävande lera. Underjordiska källor håller träsket ständigt fuktigt och översvämmat, täckt av tät dimma och fullt av krokolisker, rovfåglar och spindlar. Vassa grund och kringdrivande träsk gör färden farlig för alla äventyrare som lämnar de sönderfallande vägarna."},{t="Gamla fejder och sköra vapenvilor",b="Dustwallow var till största delen vildmark fram till tiden efter det tredje kriget, då Lady Jaina Proudmoore ledde mänskliga flyktingar över havet för att bygga citadellet Theramore Isle på den östra kusten. Kort därefter förde Kul Tiran-styrkor under storamiral Daelin Proudmoore krig mot Thralls unga Horde. Det ledde till blodiga strider i våtmarkerna och amiralens nederlag. I dag råder officiell vapenvila mellan Theramore och Orgrimmar, men spänningarna pyr under ytan. Theramore plågas av avhopp och sabotage, medan spioner utkämpar tysta, dödliga konflikter i kärrlandet."},{t="Wyrmbogs skugga",b="I söder övergår träsket i ett kargt, klippigt kärrland som kallas Dragonmurk och Wyrmbog. Området befolkades först av Stonemaul-ogrerna under halvorghjälten Rexxar. Det blev en gravplats när den svarta drakflocken våldsamt drev klanen från Stonemaul Village. De fördrivna ogres flydde norrut till Brackenwall Village under Overlord Mok'Morokk och svor att hämnas. Bland de karga klipporna lurar Onyxia, Deathwings dotter, som styr sin avkomma och smider onda planer långt bortom träsket."}},faq={{q="Var finns Alliansens främsta bosättning här?",a="Alliansens närvaro är koncentrerad till Theramore Isle, en befäst stadsstat på en klippig ö utanför den östra kusten. Staden grundades av Lady Jaina Proudmoore efter det tredje kriget. En smal väg förbinder den med Kalimdor, och viktiga sjöleder går till Menethil Harbor i Eastern Kingdoms.",al={"alliansens bas i dustwallow","var ligger theramore","människornas stad i dustwallow"}},{q="Var kan Hordens äventyrare söka skydd i träsket?",a="Resenärer från Horde slår läger i Brackenwall Village, i träskets nordvästra del. Bosättningen grundades av Stonemaul-klanen av ogres, som anslöt sig till Horde under Rexxar och öppnade portarna för orcher och taurenallierade.",al={"hordens bas i dustwallow","var ligger brackenwall","ogerby"}},{q="Varför finns det så många svarta drakar i det södra träsket?",a="Den södra delen, som kallas Wyrmbog och Dragonmurk, är Onyxias revir och häckningsplats. Hon är Deathwings dotter. Hennes svarta drakspawn drev våldsamt bort Stonemaul-ogrerna och gjorde klipphyllorna och de djupa grottorna till bon för drakungar och draklingar.",al={"drakar i wyrmbog","varför svarta drakar här","the dragonmurk"}},{q="Vad hände med Stonemaul-ogrerna ursprungliga hem?",a="Stonemaul-ogrerna bodde ursprungligen i fred i Stonemaul Village i det södra träsket. Men den svarta drakflocken inledde ett förödande anfall, dödade många och tvingade de överlevande att fly nordväst till Brackenwall Village.",al={"stonemaul ruins","vad hände med stonemaul village","gammal ogrestad"}},{q="Vem bor i den ensliga stugan ute i The Quagmire?",a="Stugan tillhör Tabetha, en excentrisk och mäktig eremitmagiker som lever stilla i träskets djup. Magiker söker ofta upp henne för undervisning eller hjälp med att rena instabila magiska reliker.",al={"tabetha's farm","tabetha i dustwallow","vem är häxan i träsket"}},{q="Vad är Alcaz Island och vem kontrollerar ön?",a="Alcaz Island är en hårt bevakad ö utanför träskets nordöstra kust. Den hålls av Strashaz-nagorna och patrulleras av farliga elitförsvarare, medan hydror lurar i vattnen runtomkring.",al={"alcaz island","ö utanför dustwallows kust","vad finns på alcaz"}}},fp="16,349,19.464.0,29.524.0,25.469.2,42.276.0,53.203.0,58.250.2,52.204.0,52.188.0,41.171.2"}
P.entries["zone:easternplaguelands"] = {n="Eastern Plaguelands",s="Eastern Plaguelands utgör det ödelagda hjärtat av det fallna kungariket Lordaeron, kvävt av Scourges pest, giftiga dimmor och förvridna svampar. I norr tornar Stratholme upp sig som regionens maktcentrum för de odöda, medan den fanatiska Scarlet Crusade befäster sina ställningar i öster. Mitt i mardrömmen står Light's Hope Chapel som en orubblig, neutral fristad för alla som är modiga nog att slå tillbaka.",h="Eastern Plaguelands utgör det ödelagda hjärtat av det fallna kungariket Lordaeron, kvävt av Scourges pest...",kw={"argent dawn","darrowshire","eastern plaguelands","kelthuzad","lights hope chapel","nathanos","plaguewood","rivendare","scarlet crusade","scourge","stratholme","tyrs hand"},ang={["class:Paladin"]="Lordaerons fallna rike rymmer en djup tragedi för Silver Hand, från platsen där Arthas mörka förvandling ägde rum i Stratholme till den tappra sista striden vid Light's Hope Chapel.",["faction:Alliance"]="För Alliansen är en färd in i Plaguelands en högtidlig pilgrimsresa för att återta och hedra de ödelagda lämningarna efter deras forna allierade i norr.",["profession:Herbalism"]="Denna pesthärjade region är en av de ytterst få platser där du kan samla sällsynta, kraftfulla örter som Arthas' Tears, Plaguebloom och Black Lotus.",["profession:Mining"]="Ådror av Truesilver, Mithril och Rich Thorium löper genom de korrumperade sluttningarna och farliga dalarna, där Scourge härjar.",["race:Undead"]="Eastern Plaguelands är både platsen där Scourge-hotet föddes och en viktig front där Forsaken slår tillbaka mot sina forna herrar och Scarlet Crusades fanatiker."},sec={{t="Ett land i ruiner",b="Regionen kallades en gång Eastweald och var norra Lordaerons bördiga jordbrukscentrum, med den stora metropolen Stratholme och välmående städer som Darrowshire och Corin's Crossing. Under det tredje kriget lät prins Arthas rensa Stratholme efter att ha upptäckt att stadens spannmålsförråd smittats med De odödas pest. Efter kungarikets fall löpte Scourges mörka magi fritt. Jorden blev brun och rutten, vanliga växter förvandlades till väldiga svampar och en kuslig orange dimma lade sig över dalarna."},{t="Krig på tre fronter",b="Stratholme är Scourges södra maktsäte i Lordaeron, där Baron Rivendare befaller under lichens Kel'Thuzads ledning. I sydöst trotsar den fanatiska Scarlet Crusade de odöda. De har befäst staden Tyr's Hand och angriper Stratholmes röda bastioner. Deras dogmatiska hat riktar sig inte bara mot de döda, utan också mot levande resenärer som korsar deras gränser. I norr utkämpar skogstrollen Mossflayer från Zul'Mashar sina egna isolerade och desperata strider, fångade i korselden från den större konflikten."},{t="De levandes bastioner",b="För att överleva i Eastern Plaguelands måste du se upp var du sätter fötterna. Den neutrala Argent Dawn verkar från Light's Hope Chapel längst i öster och erbjuder en trygg tillflykt, viktiga förnödenheter och flygrutter åt både Alliansens och Hordens förkämpar. Bortom kapellet står de förfallna vakttornen vid Crown Guard, Eastwall, Northpass och Plaguewood som tysta påminnelser om Lordaerons förlorade försvar."}},faq={{q="Vad fick himlen och träden att se så sjuka ut?",a="Landskapet lider av de koncentrerade effekterna av The Cult of the Damned och deras De odödas pest. Den vidriga nekromantiska magin lämnades obehindrad efter det tredje kriget och förpestade jorden, muterade det lokala djurlivet, fyllde luften med en onaturlig orange smog och förvandlade naturliga skogar till groteska svamplundar som Plaguewood.",al={"varför är himlen orange","varför finns det jättesvampar","korruption i eastern plaguelands"}},{q="Var hittar jag en trygg tillflykt eller flygrutt här?",a="Light's Hope Chapel, vid områdets östra gräns, är den främsta fristaden. Argent Dawn sköter kapellet, som erbjuder flygrutter till Undercity, Ironforge, Chillwind Camp och The Hinterlands och välkomnar resenärer från både Alliansen och Horden.",al={"säker zon i epl","var finns flygrutten i epl","vänlig stad i eastern plaguelands"}},{q="Vem kontrollerar staden Stratholme?",a="Stratholme är splittrat av pågående krig. Större delen av de brinnande ruinerna styrs av Scourge under Baron Rivendare, som tjänar Kel'Thuzad. Scarlet Crusade har dock en offensiv garnison i den västra stadsdelen och för en skoningslös och blodig belägring mot de odöda styrkorna.",al={"vem leder stratholme","stratholmes bossars historia","vad finns i stratholme"}},{q="Varför är Scarlet Crusade fientlig mot äventyrare utifrån?",a="Efter Lordaerons fall och Silver Hands splittring dukade Scarlet Crusade under för gränslös fanatism och paranoia. De är övertygade om att alla utomstående bär på pestens smitta eller umgås med de odöda. Därför anfaller de alla som inte tillhör orden och närmar sig deras fästen, som Tyr's Hand.",al={"varför anfaller scarlet crusade mig","tyrs hand fientlig","scarlet crusade röd"}},{q="Vad hände med staden Darrowshire?",a="Under det tredje kriget anföll Scourge-styrkor under ledning av dödsriddaren Marduk the Black och gastarna Horgus the Ravager staden. Paladinen Davil Crokford och kapten Joseph Redpath kämpade tappert, men Redpaths själ fördärvades av nekromanti. Han förvandlades till ett redskap för slakt av sitt eget folk. Nu ligger staden i hemsökta ruiner.",al={"darrowshires historia","darrowshires fall","vem förstörde darrowshire"}}},fp="19,201,14.487.0,21.470.0,22.315.0,46.266.0,50.219.0,36.218.0,58.241.0,41.318.0"}
P.entries["zone:elwynn"] = {n="Elwynn Forest",s="I Elwynn Forest hämtar Stormwind timmer, guld, fisk och grödor från landet. Northshire Abbey skickar mänskliga rekryter ut i skogarna, där skadedjur, undanträngt djurliv och rövare hotar freden.",h="I Elwynn Forest hämtar Stormwind timmer, guld, fisk och grödor från landet.",kw={"defias","eastvale","elwynn","elwynn forest","fargodeep","goldshire","hogger","jasperlode","nazferiti","northshire","northshire abbey","vancleef"},ang={["class:Rogue"]="Som skurk finner du Elwynn genomsyrat av Defias Brotherhoods skugga, med stölder, smuggelgods och underjordiska rebellsignaler.",["faction:Alliance"]="Som medlem av Alliansen hjälper du till att skydda Alliansens främsta mänskliga kungarike. Stormwind City är beroende av Elwynns timmer-, malm- och spannmålsleder.",["profession:Mining"]="Som gruvarbetare hittar du kopparådror i Echo Ridge, Fargodeep och Jasperlode. Kobolder härjar i gruvorna, men de är fortfarande en viktig första prövning.",["race:Human"]="Som människa börjar du i kungarikets förfäders hemtrakter. Du tränar vid Northshire Abbey innan du ger dig av för att försvara ditt hemland mot banditer, bestar och politiskt förfall."},sec={{t="Rikets kornbod",b="Elwynn Forest sträcker sig söderut från Stormwinds portar till floden Nazferiti. Regnet ger näring åt de bördiga fälten, medan täta lövskogar förser huvudstaden med virke. Goldshire och Eastvale Logging Camp skickar spannmål, boskap, timmer och rå koppar till Stormwind. I Elwynn föds också tåliga Evendale-hästar upp, uppskattade av resande och riddare i hela kungariket."},{t="En bräcklig fred",b="Problem tränger sig på från alla håll. Stormwind Army är hårt ansatt av uppgifter långt borta, så lokala marskalkar och ställföreträdare måste förlita sig på oprövade rekryter. Kobolder har tagit över Fargodeep Mine och Jasperlode Mine. Riverpaw-gnoller stryker längs de sydvästra gränserna, medan murlocker håller till vid Stone Cairn Lake och Crystal Lake. Vargar som flyr från fördärvet på andra sidan floden i Duskwood har tagit sig in i Elwynn."},{t="Hotet från röda bandanor",b="Defias Brotherhood har spridit sig genom Elwynn som ett organiserat rövarband. Medlemmarna kom från Edwin VanCleefs Stonemasons Guild efter bittra tvister om löner med House of Nobles. De har tagit över Northshire Vineyards, Brackwell Pumpkin Patch, Jerod’s Landing och Mirror Lake Orchard. Rykten säger att deras agenter leder närliggande gnoller och kobolder för att skapa oro i riket. Väktarna Rolf och Malakai gav sig av för att undersöka murlocker nära Stone Cairn Lake. Båda dödades och lämnades på sjöns stränder."}},faq={{q="Varför patrullerar Stormwind Guard knappt skogen?",a="Stormwinds väpnade styrkor är hårt ansatta. Kungariket skickade stora styrkor söderut till Stranglethorn Vale, vilket byggde upp skulder och tömde de lokala leden. Westbrook Garrison och Goldshire förlitar sig nu på små besättningar och frivilliga rekryter för att möta banditer, gnoller och murlocker.",al={"var finns väktarna","varför finns ingen stormwind army","varför är elwynn oförsvarat"}},{q="Varför finns det kobolder i alla gruvorna?",a="Det finns få väktare, och kobolder har svärmat in i Fargodeep Mine, Jasperlode Mine och Echo Ridge Mine för att komma åt guld och mineraler. De drev bort de mänskliga guldletarna och gruvarbetarna och försvarade sedan sina fyndigheter med ljus, enkla hackor och verktyg de plockat upp.",al={"varför finns kobolder i gruvorna","kobolder i elwynn","fargodeep hemsökt av kobolder"}},{q="Vilka är banditerna med röda masker?",a="Banditerna med röda masker tillhör Defias Brotherhood, laglösa som har tagit över gårdar och gruvor i Elwynn och Westfall. People's Militia vid Sentinel Hill i Westfall försöker fortfarande ta reda på vem som leder dem och varför.",al={"röda masker","banditer med röda bandanor","vilka är defias i elwynn"}},{q="Vart leder vägen söderut?",a="Vägen söderut korsar floden Nazferiti och fortsätter in i Duskwood. Området var en gång fridfullt, men har fallit i ett onaturligt mörker och hemsöks av odöda, monstruösa spindlar och glupska bestar.",al={"vad finns på andra sidan floden","vart leder bron till duskwood","bron över nazferiti"}},{q="Vad ligger bakom fejden mellan familjerna Maclure och Stonefield?",a="Stonefields och Maclures är grannfamiljer som driver gårdar i södra Elwynn, och de har varit bittra fiender länge. Deras yngre släktingar, Maybell Maclure och Tommy Joe Stonefield, har i hemlighet blivit förälskade, vilket gör rivaliteten ännu mer laddad.",al={"maclure mot stonefield","rivalitet mellan gårdar i elwynn","fejden mellan stonefield och maclure"}},{q="Vad är Tower of Azora?",a="Tower of Azora är ett mystiskt torn vid vägen mellan Goldshire och Eastvale Logging Camp. Där bor tillbakadragna magiker, bland dem Theocritus, som studerar regionens ley-linjer och bedriver magisk forskning utanför den direkta tillsynen från Stormwinds Wizard’s Sanctum.",al={"tornet vid vägen till eastvale","magikertorn i elwynn","vem bor i tower of azora"}}},fx={["23586590"]={q="Vad är Elwynn Forest?",a="Elwynn Forest är kungariket Stormwinds grönskande hjärtland. Dessa uråldriga skogar med ståtliga lövträd, böljande kullar och strömmande floder ligger nedanför Burning Steppes fotkullar och förser kungariket med timmer, fisk, grödor och malm. Under dess mäktiga trädkronor ligger små gårdar, slingrande landsvägar och städer som Goldshire, medan huvudstaden Stormwind vakar över riket från den nordvästra höjdryggen.",al={"vad är elwynn","var är jag","elwynn forests historia"}},["4e6f8475"]={q="Vad har hänt i Elwynn Forest förr i tiden?",a="Elwynn grundades för århundraden sedan av mänskliga migranter av Arathi-blodslinjen och växte till ett blomstrande rike. Under det första kriget svepte dock orchernas Hord genom skogen, brände dess skogsgläntor och omringade Stormwind City innan de jämnade Goldshire och huvudstaden med marken. Efter det andra kriget hjälpte överbefälhavare Turalyon till att övervaka folkets återvändande, och skogen byggdes upp på nytt. Bara utspridda, ruttnande katapulter minner om invasionen.",al={"elwynn forests historia","elwynn forests förflutna","elwynn forest under det första kriget"}},["2f8050d9"]={q="Är Elwynn Forest farligt?",a="Även om Elwynn verkar idylliskt döljer den fridfulla ytan en växande oro. Kobolder har tagit över rikets viktiga guldgruvor, medan fientliga Riverpaw-gnoller plundrar från den västra gränsen. Våldsamma murlocker har slagit läger runt Crystal Lake och Stone Cairn Lake och överfaller både vakter och resenärer. Än värre är att den rödmaskerade Defias Brotherhood verkar i skuggorna och ockuperar fruktodlingar och gårdar, medan Stormwinds styrkor kämpar för att behålla kontrollen.",al={"är elwynn säkert","hot i elwynn forest","hot i elwynn"}},["41d1722e"]={q="Är det här en del av Stormwind?",a="Ja, Elwynn Forest är kärnområdet i kungariket Stormwind. Skogen gränsar direkt till huvudstadens portar och förser marknaderna med virke från Eastvale, grödor från lantgårdarna och malm från traktens gruvor. Stormwind Guard upprätthåller utposter i skogarna, bland annat vid Westbrook Garrison och Northshire Valley, men rikets resurser är för närvarande hårt ansträngda.",al={"är elwynn en del av stormwind","stormwinds kungarike och territorium","elwynns tillhörighet"}},["36c6d40e"]={q="Varför är det så fridfullt här jämfört med alla andra platser?",a="Elwynn ligger i rikets skyddade mitt, precis innanför Stormwind Citys värnande murar. Till skillnad från Duskwood i söder, som föll offer för en smygande magisk förbannelse, och Westfall i väster, som lämnades åt torka och banditvälde, återuppbyggdes Elwynn i stor utsträckning efter andra kriget. Närheten till tronen skyddar området från de värsta fasor som lurar i grannländerna.",al={"varför är elwynn fridfullt","elwynn jämfört med duskwood","varför är elwynn inte förstört"}},["7bf05012"]={q="Vad är Goldshire?",a="Goldshire är Elwynn Forests centrala by och vägkorsning, strax söder om Northshire och sydost om Stormwind City. Byn grundades för århundraden sedan och är ett viktigt nav som knyter samman handelsvägarna till Westfall, Redridge Mountains och Duskwood. Här finns flitiga hantverkare, lokala tränare och det berömda värdshuset Lion's Pride Inn, som välkomnar resenärer genom rikets hjärta.",al={"goldshire","berätta om goldshire","goldshires historia"}},["2eb13bb0"]={q="Vem är Marshal Dughan och varför skickar alla mig till honom?",a="Marshal Dughan är Goldshires lokala befälhavare och främste upprätthållare av lagen i byn och den omgivande skogen. Han är stationerad i byn och ansvarar för den lokala säkerheten, samordnar patruller i trakten och försöker skydda resenärer och försörjningsleder. Eftersom Stormwinds militär är överbelastad på andra håll förlitar sig Dughan i hög grad på dugliga äventyrare för att undersöka hot och återställa ordningen i Elwynn.",al={"marshal dughan","vem är dughan","dughan i goldshire"}},["68a6801b"]={q="Rapporterar Marshal Dughan till Stormwind?",a="Ja, Marshal Dughan är officer i Stormwind Guard och rapporterar direkt till rikets högsta befäl i Stormwind City. Han upprätthåller kronans lagar och försöker hävda kunglig auktoritet i hela den centrala skogen, men måste ständigt be huvudstaden om trupper och förnödenheter som sällan kommer fram.",al={"dughan och stormwind","vem rapporterar dughan till","är dughan med i stormwind guard"}},["6c2b38d9"]={q="Varför började jag vid Northshire Abbey?",a="Northshire Valley är en skyddad, befäst tillflyktsort som skapats för att träna och värva lovande nya rekryter till kungariket Stormwind. Dalen skyddas av stenmurar och naturliga klippor och rymmer Northshire Abbey, där unga krigare, präster, paladiner och andra aspiranter finslipar sina färdigheter och hjälper lokala befälhavare innan de ger sig ut i den större världen.",al={"varför northshire","börja i northshire","starta i northshire"}},f22f39d1={q="Vad är Northshire Abbey?",a="Northshire Abbey är det historiska sätet för Holy Order of Northshire Clerics, en orden inom Holy Light som hjälpte Stormwind under rikets mörkaste tider. Klostret består av Main Hall, Hall of Arms och Library Wing. Där gav man en gång Guardian Medivh skydd under hans koma och bevarade heliga skrifter som Tome of Divinity. Klostret återuppbyggdes efter andra kriget och tränar nu rekryter och förkämpar för Light.",al={"northshire abbeys historia","vad är northshire","klostret i northshire"}},c283ebda={q="Vem är Marshal McBride?",a="Marshal McBride upprätthåller lagen och leder försvaret i Northshire Valley. Från sin bas vid Northshire Abbey övervakar han det lokala försvaret, håller uppsikt över hoten från det angripna Echo Ridge Mine och framryckande Defias-banditer och värvar dugliga nya invånare till rikets försvar.",al={"marshal mcbride","mcbride i northshire","vem är mcbride"}},["16daccd8"]={q="Vad är Fargodeep Mine?",a="Fargodeep Mine är en övergiven guld- och koppargruva söder om Goldshire. Gruvan var en gång en viktig inkomstkälla och metallkälla för Stormwinds skattkammare, men kastades in i kaos när ett koboldklan invaderade gångarna. Nu är den övertagen och utgör en fara nära de lokala gårdarna. Därför skickar Marshal Dughan äventyrare ner i djupet för att undersöka och rensa ut inkräktarna.",al={"fargodeep mine","fargodeep","fargodeeps historia"}},e239f261={q="Vilka är Riverpaw-gnollerna och varför anfaller de oss?",a="Riverpaw-flocken är en vild klan hyenliknande gnoller som slagit sig ner längs Elwynns västra gräns nära Westbrook Garrison. De är aggressiva och rovgiriga och har länge motsatt sig människornas expansion samt plundrat gårdar och överrumplat oförsiktiga resenärer. De har slagit läger längs Forest's Edge och Stone Cairn Lake och tränger aggressivt in på människornas marker.",al={"riverpaw-gnoller","varför anfaller riverpaw","riverpaw-flocken"}},da4445a3={q="Arbetar Riverpaw-gnollerna åt någon?",a="Gnoller drivs oftast av ren vildsinthet och girighet, men rykten i skogen antyder att de kan samarbeta med Defias Brotherhood. Märkliga band och belöningar, däribland affärer med skumma uppköpare nära Ridgepoint Tower, tyder på att banditerna kan beväpna eller samordna gnollerna för att destabilisera Elwynns västra gränstrakter.",al={"vem leder riverpaw","samarbetar gnollerna med defias","kopplingen mellan riverpaw och defias"}},["29c0080a"]={q="Varför oroar sig alla för murlockerna vid floden?",a="Murlocker har trängt in i Elwynns vattendrag i stor styrka och invaderat Crystal Lake och Stone Cairn Lake. De här primitiva groddjuren är ytterst revirhävdande och överfaller lokala fiskare, resenärer och patruller. Guard Thomas befarar att de kommer att ta över de lokala vägarna och föra striderna ända in i Goldshire om deras bosättningar längs stränderna får växa ostört.",al={"murlocernas hot mot elwynn","varför oroa sig för murlocker","murlocproblemet"}},f8d7f725={q="Vad hände med Rolf och Malakai?",a="Vakter Rolf och Malakai var vakter från Stormwind som skickades för att undersöka den ökande murlocaktiviteten nära de östra vattendragen och Stone Cairn Lake. De har inte rapporterat tillbaka, och Guard Thomas ber resenärer att undersöka saken.",al={"rolf och malakai","försvunna vakter i elwynn","vad hände med vakterna hartford och stone"}},["0c4f3fe8"]={q="Vad händer vid Eastvale Logging Camp?",a="Eastvale Logging Camp är hjärtat i Elwynns livliga timmerindustri och ligger bland de östra skogarna vid gränsen till Redridge Mountains. Skogshuggarna fäller skogens väldiga lövträd för att ge Stormwinds rike virke till byggnader, vagnar och befästningar, men fientliga vargar och björnar hotar ofta arbetslagen.",al={"eastvale logging camp","virke från eastvale","vad är eastvale"}},["9effb187"]={q="Vart leder vägen efter Elwynn?",a="När du har hjälpt Marshal Dughan delar sig vägarna från Goldshire mot kargare gränstrakter. Den västra bron över floden Nazferiti leder till Westfalls damm och blåst, där Defias har makten. I öster ligger Redridge Mountains högt beläget vid gränsen, medan de södra broarna leder in i Duskwoods förbannade, hemsökta dunkel.",al={"vart efter elwynn","nästa område efter elwynn","efter elwynn forest"}},cd54a445={q="Hur är Westfall?",a="Westfall är ett torrt, vindpinat jordbruksområde sydväst om Elwynn. Området var en gång rikets kornbod, men dess böljande betesmarker ligger nu torra och obrukade. Där härjar förrymda mekaniska skördevakter, glupska asfåglar och banditer. Defias Brotherhood kontrollerar nästan hela området, och bara en desperat lokal milis vid Sentinel Hill gör motstånd.",al={"vad är westfall","om westfall","översikt över westfall"}},["4080ef4d"]={q="Hur hamnade jag i Elwynn Forest?",a="Om du är människa är Elwynn Forest ditt folks kärnland. Du tog troligen dina första steg i den skyddade dalen vid Northshire Abbey och hörsammade rikets kallelse att träna dina förmågor och hjälpa de lokala myndigheterna. När du hade löst de första problemen i dalen skickade Marshal McBride dig söderut längs vägen till Goldshire. Resenärer av andra raser tar sig vanligtvis hit från Deeprun Tram via Stormwind City och går genom huvudstadens pampiga portar rakt ut i skogen.",al={"hur kom jag hit","varför är jag i elwynn forest","hur kom jag till elwynn","hur hamnade jag här"}},f92572cc={q="Vad förväntas jag göra i Elwynn Forest?",a="Stormwinds armé är utspridd över hela riket, så det lokala försvaret av Elwynn har fallit på lokala biträden och dugliga rekryter som du. Marshal Dughan i Goldshire behöver hjälp med att rensa ut kobolderna i guldgruvorna, slå tillbaka Riverpaw-gnollerna vid den västra gränsen och bekämpa de våldsamma murlockerna runt sjöarna. Samtidigt har rödmaskerade Defias-banditer tagit över lokala gårdar och fruktodlingar, och markägare som Maclures och Stonefields behöver hjälp att lösa sina dispyter. När du har hjälpt till att återställa ordningen här leder vägen västerut till Westfall eller österut mot Redridge Mountains.",al={"vad ska jag göra i elwynn","vad gör jag här","vad är mitt uppdrag i elwynn forest","varför är jag här"}}},fp="13,250,28.459.0,18.438.0,22.513.1,54.269.0,43.248.0,38.217.0,31.190.0,54.246.0,27.282.0"}
P.entries["zone:felwood"] = {n="Felwood",s="Felwood är en förpestad skog mellan Ashenvale och Mount Hyjal, djupt förgiftad av demonisk magi under det tredje kriget. En gång var den ett frodigt paradis med ängar och lundar som vårdades av nattalverna, men nu kryllar den av demoniska satyrer, glupska bestar och förvridna uråldringar. Druider från Cenarion Circle arbetar desperat tillsammans med Alliansens och Hordens utposter för att rena landet och driva ut Shadow Council ur dess djup.",h="Felwood är en förpestad skog mellan Ashenvale och Mount Hyjal, djupt förgiftad av demonisk magi under det...",kw={"banehollow","bloodvenom","deadwood","emerald sanctuary","felwood","jaedenar","sångblomma","talonbranch","tichondrius","timbermaw"},ang={["class:Druid"]="Felwood är en djup tragedi för Cenarion Circle, vars druider viger sina liv åt att rena förpestade växter och lugna vansinniga naturandar.",["class:Warlock"]="Jaedenars mörka tunnlar och de kvarvarande demoniska styrkorna gör Felwood till ett centrum för jakten på Shadow Councils rivaliserande kultister.",["profession:Herbalism"]="Den felgenomsyrade jorden ger sällsynta och oberäkneliga växter, och är en av få platser i Azeroth där man kan samla Gromsblood och Arthas' Tears.",["race:NightElf"]="Vanhelgandet av dessa uråldriga skogar är en källa till enorm sorg och skam för kaldorei, som misslyckades med att skydda dem från legionens inflytande."},sec={{t="Ett vanhelgat paradis",b="Före det tredje kriget var dalen en fridfull tillflyktsort med sjungande fåglar, klara bäckar och stilla lundar som vaktades av uråldriga beskyddare. Det tog slut när fruktansfursten Tichondrius och den brinnande legionen använde Gul'dans skalle för att förgifta norra Kalimdor inför anfallet mot Mount Hyjal. Skallens fasansfulla trolldom förvandlade skogsmarken till ett förkolnat träsk. Illidan Stormrage dräpte till slut Tichondrius och slukade artefaktens essens, men marken förblev genomsyrad av felkorruption. Mäktiga trädandar och uråldringar ruttnade inifrån, floder förvandlades till kokande galla och skogens bestar drevs till kannibalisk vansinnighet."},{t="Kampen för rening",b="Att läka Felwood har visat sig vara plågsamt långsamt. Vid Emerald Sanctuary längs den södra gränsen utkämpar Cenarion Circle en uppförsbacke mot den förpestade korruptionen. Druider utrustar vandrare med Cenarion-fyrar och renande salvor och arbetar för att läka förgiftade växter som sångblommor och nattdrakslökar. Båda fraktionerna håller fästen i de förgiftade vildmarkerna: nattalverna vid Talonbranch Glade i norr och Horden vid Bloodvenom Post. Dessa utposter är sköra skyddsvallar mitt i en dödlig vildmark där naturen har vänt sig mot allt dödligt kött."},{t="Skuggan i Jaedenar",b="Den kvarvarande felkontamineringen underhålls aktivt av mörka kultister. I Jaedenars och Shadow Holds underjordiska labyrint utför resterna av Shadow Council vidriga ritualer under Lord Banehollows ledning. Dessa häxmästare, som samarbetar med svekfulla satyrer som vanhelgar uråldriga månbrunnar, skördar skogens lidande och tillkallar demoniska förstärkningar. Allt varaktigt hopp om att återupprätta Felwood kräver att detta lömska råd rycks upp med rötterna."}},faq={{q="Varför är Felwood förgiftat?",a="Under det tredje kriget använde fruktansfursten Tichondrius den demoniska artefakten Gul'dans skalle för att korrumpera skogen. Syftet var att försvaga nattalvernas försvar under den brinnande legionens marsch mot Mount Hyjal och förpesta djurlivet, vattnet och uråldringarna.",al={"hur blev felwood korrumperat","vad hände med felwood","varför är träden döda"}},{q="Kan de korrumperade växterna i skogen renas?",a="Ja. Druider från Cenarion Circle ger äventyrare salvor bryggda av insamlade felrester och mineralavlagringar. När salvorna stryks på växter som sångblommor, piskslåknölar och nattdrakar renas de från sin korruption och ger kraftfullt läkande frukt och välsignelser.",al={"hur renar man växter","cenarion-växtsalva","korrumperad sångblomma"}},{q="Vem kontrollerar Jaedenar?",a="Jaedenar kontrolleras av Shadow Council, en hemlig sekt av dödliga häxmästare och demonanhängare. Djupt inne i Shadow Holds underjordiska grottor vakar fruktansfursten Lord Banehollow över deras mörka ritualer och styr satyrerna som bor i området.",al={"vad är jaedenar","vem finns i shadow hold","jaedenars boss"}},{q="Är furbolgarna i Felwood fientliga?",a="De flesta är fientliga. Stammar som Deadwood har helt fallit för demonisk korruption och felvansinne. Timbermaw-stammen som håller det norra tunnelsystemet är däremot okorrumperad, men misstror främlingar djupt tills de visat sig vänligt sinnade.",al={"felwoods furbolgar","timbermaw-furbolgar","deadwood village"}},{q="Hur tar man sig genom Felwood till Moonglade eller Winterspring?",a="Vägen leder norrut, rakt in i Timbermaw Hold, ett befäst grottkomplex. De okorrumperade Timbermaw-furbolgarna kontrollerar tunnlarna som förbinder Felwood med Moonglade och Winterspring. Resenärer måste antingen vinna deras förtroende eller kämpa sig igenom.",al={"timbermaw-tunnel","vägen till winterspring","passagen till moonglade"}},{q="Varför anfaller de korrumperade uråldringarna nattalver?",a="De en gång ädla uråldringarna och trädandarna förvrängdes och förgiftades av demonisk magi. Bundna i evig vånda hyser deras krossade sinnen en djup bitterhet mot nattalverna, som de anser ha övergett dem åt den brinnande legionen.",al={"vansinniga trädandar","korrumperade uråldringar","varför är uråldringarna fientliga"}}},fp="7,298,19.587.0,21.430.0,22.403.1,25.236.0,51.234.0,22.236.0,36.219.0,60.221.0,49.200.0"}
P.entries["zone:feralas"] = {n="Feralas",s="Feralas är en vidsträckt, dimhöljd regnskog mellan Desolace, Thousand Needles och Veiled Sea. Skyddad av höga bergsväggar bevarar den ett forntida ekosystem med igenvuxna Kaldorei-ruiner och urtidsbestar. I dag är vildmarken omstritt territorium mellan forntida Highborne-rester, invaderande Gordunni-ogrer och rivaliserande utposter som Alliance och Horde har upprättat.",h="Feralas är en vidsträckt, dimhöljd regnskog mellan Desolace, Thousand Needles och Veiled Sea.",kw={"camp mojache","dire maul","dream bough","eldre'thalas","feathermoon","feralas","gordunni","shandris","thalanaar"},ang={["class:Druid"]="Dream Bough och dess förbindelse med Emerald Dream gör Feralas till helig mark, som kräver vaksamhet mot inkräktande fördärv och skändare.",["faction:Alliance"]="Operationerna utgår från Feathermoon Stronghold under Shandris Feathermoon. Agenter får i uppdrag att hålla kustens naga i schack och försvara alvarvet.",["faction:Horde"]="Camp Mojache är ett livsviktigt gränsfäste som behöver pålitliga krigare för att slå tillbaka aggressiva intrång från Gordunni, avfälliga Grimtotem och Woodpaw-gnoller.",["profession:Herbalism"]="I trädkronornas fuktiga skugga växer värdefulla växter från tempererade och tropiska trakter, däribland Sungrass, Purple Lotus och Khadgar's Whisker.",["race:NightElf"]="Feralas har stor kulturell betydelse som en vagga för den forntida Kaldorei-civilisationen, men synen av heliga ruiner som Eldre'Thalas skändade av ogres väcker djup sorg och vrede."},sec={{t="En skog opåverkad av ödemarken",b="Medan grannområdena Desolace och Thousand Needles har torkat ut till karga ödemarker och uttorkade raviner, är Feralas fortfarande intensivt grönskande. Bergskedjor sluter sig kring trädkronorna och upprätthåller ett varmt mikroklimat med djupa dimmor, uråldriga träd och höga vattenfall. Före den stora klyvningen såg stora delar av Kalimdor ut så här. Under årtusenden har den djupa djungeln slukat monumenten efter Kaldorei-civilisationen som en gång härskade här och gömt bortglömda tempel och paviljonger under kvävande mossa och täta ormbunkar."},{t="Eldre'Thalas ruiner",b="Mitt i Feralas reser sig den förstörda metropolen Eldre'Thalas, numera kallad Dire Maul. Den byggdes under Kaldorei-imperiets storhetstid, men dess vidsträckta stengårdar har förfallit och skändats av den vilda ogreklanen Gordunni. Ogrerna har spridit sig över dalen, plundrat heliga platser, vanhelgat orörda dungar och drivit den inhemska faunan till territoriellt raseri. Djupt inne i Dire Mauls förseglade kamrar viskas det fortfarande om Highborne-rester och fångade krafter från tiotusen år tillbaka."},{t="Kampen om fästen",b="Både Alliance och Horde har skickat stora expeditioner in i djungeln, men det är fortfarande farligt att ta sig fram där. Från Feathermoon Stronghold på Sardor Isle leder general Shandris Feathermoon Sentinels i strider mot både ogreexpansionen och de framryckande naga. I öster ligger Camp Mojache, en central Horde-garnison som kämpar mot aggressiva Woodpaw-gnoller, fientliga Grimtotem-tauren och de obevekliga ogreklanerna. Ingen av fraktionerna har verklig kontroll över det otämjbara inlandet."}},faq={{q="Vad är Dire Maul?",a="Dire Maul är det nuvarande namnet på Eldre'Thalas, en storslagen alvstad som överlevde den stora klyvningen. Under årtusenden förföll staden och övertogs av den brutala Gordunni-klanen. Anläggningen är nu uppdelad i omstridda flyglar där ogres, förrädiska andar och forntida Highborne-hemligheter finns.",al={"eldre'thalas","ogrestad","centrum för forntida ruiner"}},{q="Hur tar sig Alliance-resenärer säkert till Feathermoon Stronghold?",a="Alliance-utforskare som kommer från Desolace kan ta sig söderut genom The Twin Colossals, men bestarna där är farliga. Resenärer kan också smyga sig ut i havet vid Sar'theris Strand i Desolace och simma söderut längs Forgotten Coast direkt till Sardor Isle. Då slipper de helt den farliga landsvägen och Camp Mojache.",al={"ta sig till feathermoon","alliance-ingång till feralas","hur tar sig alliance till feralas"}},{q="Varför strider Horde så aggressivt mot Gordunni-ogrerna?",a="Gordunni-ogrerna expanderar våldsamt ut från Dire Maul, plundrar försörjningskaravaner och angriper resenärer i djungeln. Deras förödande krigsstyrkor hotar Camp Mojache direkt, vilket får Horde-ledare som Belgrom Rockmaul att kräva snabba och hårda angrepp mot klanens utposter.",al={"varför döda gordunni","hordes ogrekrig","camp mojache ogres"}},{q="Vad är Dream Bough?",a="Dream Bough är ett av Azeroths fyra stora träd och rymmer en mystisk naturportal som förbinder den fysiska verkligheten med Emerald Dream. Liksom sina motsvarigheter i Ashenvale, Duskwood och The Hinterlands bevakas det av den gröna drakflocken och forntida väktare.",al={"grön drakportal","stort träd i feralas","emerald dream-träd"}},{q="Varför finns Grimtotem-tauren i Feralas?",a="En utbrytargrupp av Grimtotem-tauren har en anläggning i vildmarken och verkar utanför Thunder Bluffs auktoritet. De är fientliga mot både Alliance och Horde. De har fångat lokala faeriedrakar och är ett aktivt mål för Hordes spejare.",al={"grimtotem i feralas","grimtotem compound","fientliga tauren"}},{q="Finns det Silithider i Feralas?",a="Ja. Söder om huvudvägen ligger The Writhing Deep, en myllrande underjordisk kupa full av silithidinsekter. Att de dyker upp i den frodiga regnskogen är ett oroande tecken på att kupans kollektiva medvetande breder ut sig långt bortom södra Kalimdors ökenområden.",al={"the writhing deep","insekter i feralas","silithidkupa"}}},fp="7,281,32.415.0,25.429.0,26.398.0,18.249.0,62.265.0,61.250.0,24.261.0,44.222.0,30.218.0"}
P.entries["zone:gnomeregan"] = {n="Gnomeregan",s="Gnomeregan, uthugget i Dun Moroghs snöiga bergssluttningar, var en gång gnomernas underjordiska huvudstad och största tekniska underverk. I dag ligger staden i ruiner och är avspärrad, förgiftad av radioaktivt nedfall efter ett desperat försvar mot en invasion av troggar underifrån. De överlevande gnomerna bor nu som flyktingar i närbelägna Ironforge, medan de bestrålade salarna fortfarande svärmar av muterade troggar, vansinniga spetälska gnomer och förrymda mekaniska väktare.",h="Gnomeregan, uthugget i Dun Moroghs snöiga bergssluttningar, var en gång gnomernas underjordiska huvudstad och...",kw={"dun morogh","gnomeregan","grubbis","spetälsk gnom","mekkatorque","strålning","thermaplugg","tinkers' court","trogg","viscous fallout"},ang={["faction:Alliance"]="Gnomerna stod sida vid sida med alliansen under det andra kriget. Att befria deras förlorade huvudstad från Thermaplugg är avgörande för att återställa deras styrka inom fraktionen.",["profession:Engineering"]="Den förstörda staden är fortfarande en oöverträffad gravplats för avancerade mästerverk, ritningar och experimentella konstruktioner. Där finns ovärderliga ritningar mitt i det dödliga mekaniska kaoset.",["race:Dwarf"]="Dina släktband till gnomerna går tillbaka till tiden då dina förfäder hjälpte till att lägga Gnomeregans grund. Dina utgrävningar i Uldaman släppte oavsiktligt lös trogghorderna som orsakade stadens undergång.",["race:Gnome"]="Gnomeregan är hjärtat i ditt folks största tragedi och bestående skam. Att ge sig in där är en plågsam pilgrimsfärd för att hämnas åttio procent av ditt fallna folk och störta förrädaren Thermaplugg."},sec={{t="Ett underverk av järn och ånga",b="Långt före sitt tragiska fall vittnade Gnomeregan om höjderna av gnomernas snille, ambition och uppfinningsrikedom. Det vidsträckta mekaniska komplexet byggdes med hjälp av dvärgarna i närbelägna Ironforge och drevs av jättelika malande motorer, surrande kugghjul och ett invecklat ventilationsnät som krävde att femton tekniker arbetade dygnet runt bara för att hålla luften frisk. Staden var ett blomstrande centrum för uppfinningar, hantverkstävlingar och politik kring Tinkers' Court. Den tjänade som stolt huvudstad, varifrån gnomerna bidrog med ovärderliga belägringsmotorer, flygmaskiner och vapen till Lordaerons allians under det andra kriget."},{t="Trogginvasionen och förgiftningen",b="Ungefär när Scourge drog fram genom Lordaeron under det tredje kriget vaknade en mardröm under Dun Morogh. Dvärgarnas ovetande utgrävningar vid Uldaman, en uråldrig titanskattkammare, väckte horder av primitiva troggar som grävde sig in i Gnomeregans nedre grundvalar. Överuppfinnare Gelbin Mekkatorque och hans styrkor utkämpade ett desperat krig mot inkräktarna. När försvaret bröt samman följde Mekkatorque rådet från sin främste rådgivare, Mekgineer Thermaplugg, och godkände att stadens tankar med radioaktivt avfall tömdes i de nedre nivåerna för att utrota troggarna. I stället spred sig den giftiga gasen och orsakade en okontrollerbar katastrof som utplånade nästan åttio procent av gnomernas befolkning på några dagar."},{t="Den galne Mekgineers förräderi",b="Katastrofen kan ha varit allt annat än en olyckshändelse. Mekgineer Thermaplugg hade länge i hemlighet åtrått Mekkatorques ämbete som överuppfinnare, och det ryktas att han kände till trogginvasionen innan den började och hjälpte till att sätta katastrofen i rullning. Ryktena har aldrig bekräftats, men Mekkatorque tror att de kan stämma. Vad Thermaplugg än hade för avsikt spårade katastrofen ur. Strålningen dödade inte troggarna, utan drev dem in i ett våldsamt raseri, medan Thermaplugg själv blev fångad i de förorenade nedre våningarna. Förvriden av strålsjuka till en vansinnig spetälsk gnom utropade Thermaplugg sig själv till Gnomeregans teknodiktator. Från sin tron i Tinkers' Court styr han över viljelösa överlevande spetälska gnomer och oberäkneliga maskiner."},{t="En bräcklig seger",b="Överuppfinnare Mekkatorque leder nu återerövringen av Gnomeregan från Tinkertown i Ironforge och skickar ut äventyrare från alliansen i de giftiga djupen för att störta Thermapluggs styre. När Mekgineer dödas i hjärtat av Tinkers' Court bryts hans kontroll över stadens förrymda försvar och skaror av spetälska gnomer. Det ger en efterlängtad hämnd för hans monumentala förräderi. Men en fullständig återerövring är fortfarande utom räckhåll. De djupare tunnlarna är ännu fyllda av bestrålat slam, muterade bestar och troggar. Mekkatorque måste därför sätta ihop gyroborrare och utarbeta större militära planer för att en dag återta sitt folks uråldriga hem."}},faq={{q="Varför är Gnomeregan bestrålat?",a="När troggar invaderade underifrån försökte överuppfinnare Gelbin Mekkatorque utrota dem genom att öppna tryckventilerna till stadens tankar med radioaktivt avfall, på råd av Mekgineer Thermaplugg. Planen var att översvämma enbart de nedre områdena, men den dödliga giftiga strålningen sipprade genom hela staden, dödade åttio procent av gnomernas befolkning och muterade de överlevande.",al={"vad hände med gnomeregan","varför är gnomeregan grönt","strålning i gnomeregan"}},{q="Var kom alla troggar ifrån?",a="Troggarna var uråldriga varelser som väcktes ur en djup underjordisk dvala av dvärgarnas arkeologiska utgrävningar vid titankomplexet Uldaman. De drogs till vibrationerna och hettan från Gnomeregans tunga maskiner och grävde omfattande tunnelsystem rakt in i stadens nedre nivåer och ingenjörskvarter.",al={"varför finns det troggar i gnomeregan","troggarnas ursprung","trogginvasion"}},{q="Varför bad inte gnomerna alliansen om hjälp mot troggarna?",a="Trogginvasionen slog till under det tredje kriget, medan kungariket Lordaeron föll för Scourge. Gnomerna mötte den ensamma med sin egen teknik och sina egna soldater. Det finns inga uppgifter om varför överuppfinnare Mekkatorque aldrig bad om hjälp utifrån. I stället tog han till den desperata åtgärden att tömma stadens tankar med radioaktivt avfall.",al={"varför hjälpte inte alliansen gnomeregan","övergav alliansen gnomerna"}},{q="Vad är spetälska gnomer?",a="Spetälska gnomer är gnomer som överlevde den radioaktiva utsläppningen i Gnomeregan men drabbades av svår fysisk och mental förvridning efter långvarig exponering. Deras hud har blivit sjukligt blekgrön, deras kroppar är täckta av blåsor och sjukdomar, och deras sinnen har brutits ned till vansinnigt, mordiskt raseri under Mekgineer Thermapluggs herravälde.",al={"varför är gnomerna gröna och galna","bestrålade gnomer","spetälska gnomers historia"}},{q="Vem är Mekgineer Thermaplugg?",a="Mekgineer Thermaplugg var överuppfinnare Mekkatorques betrodda främste rådgivare och åtrådde i hemlighet ämbetet som överuppfinnare. Det var på hans uppmaning som staden fylldes med strålning, och Mekkatorque kallar honom numera hela det gnomiska folkets förrädare. Han bestrålades tillsammans med staden och härskar nu som en sinnesförvirrad spetälsk despot från Tinkers' Court.",al={"thermaplugg","vem är slutbossen","mekgineer thermaplugg"}},{q="Vad förändras när Mekgineer Thermaplugg besegras?",a="När Thermaplugg besegras kapas ledningen över de spetälska gnomerna och stadens förrymda försvar. Det säkrar viktiga tekniska data och stärker gnomernas moral rejält. Men staden blir inte renad på en gång. Dödlig strålning och täta trogginvasioner fortsätter att fylla de nedre gångarna, så Mekkatorque måste förbereda djupare utgrävningar innan staden kan återerövras helt.",al={"återtar vi gnomeregan","vad händer när thermaplugg dör","är gnomeregan räddat"}},{q="Varför finns Dark Iron-dvärgar i Gnomeregan?",a="Den fientliga klanen Dark Iron skickade sändebud till Gnomeregan, däribland Dark Iron Ambassador. Dark Irons är alltid ivriga att sabotera för både Ironforge och alliansen. De söker en möjlighet att sluta en allians med Thermaplugg och hoppas kunna utnyttja gnomernas teknik och beväpnade maskiner i sina egna krigsinsatser.",al={"dark iron ambassador","varför finns dark irons i gnomeregan","dvärgar i gnomeregan"}},{q="Var bor de överlevande gnomerna nu?",a="Efter den radioaktiva katastrofen flydde de överlevande, obestrålade gnomerna genom bergen till Ironforge. Deras dvärgkusiner gav dem skydd i Tinkertown, ett ingenjörskvarter inne i bergsfästningen. Där styr Gelbin Mekkatorque sitt folk i exil medan han planerar deras återkomst till hemmet.",al={"var bor gnomerna","gnomernas hemstad","flyktingar i ironforge"}}},fx={["072b7788"]={q="Vad är Gnomeregan?",a="Gnomeregan är gnomernas urgamla underjordiska huvudstad, uthuggen djupt i de snötäckta kullarna i västra Dun Morogh. Staden byggdes med hjälp av dvärgarna från Ironforge för århundraden sedan och var ett storslaget ingenjörsverk fyllt av maskiner och nyskapande teknik. Men nu ligger dess glänsande metallhallar förgiftade och översvämmade av muterade trogger och förvridna spetälskegnomer efter en katastrofal olycka.",al={"vad är gnomeregan","gnomeregans historia","om gnomeregan"}},["18622943"]={q="Var Gnomeregan gnomernas huvudstad?",a="Ja. Gnomeregan var i generationer hjärtat i gnomernas samhälle och styre. Staden var centrum för gnomernas uppfinningsrikedom och rymde deras akademier, verkstäder och Tinkers' Court, där deras valda High Tinker regerade. Alla större uppfinningar och vetenskapliga projekt bland gnomerna hade sitt ursprung i dessa underjordiska salar.",al={"var detta gnomernas huvudstad","är gnomeregan huvudstaden","gnomernas huvudstad"}},c31b3f81={q="Bor gnomerna fortfarande i Gnomeregan?",a="Gnomeregan är inte längre hemvist för gnomernas folk. Åttio procent av befolkningen dog när giftig strålning fyllde staden, och många av dem som blev kvar förvandlades till vansinniga lepragnomer. De flesta osmittade överlevande flydde till Tinkertown i Ironforge, men några ingenjörer och återerövringsarbetare finns kvar i ruinerna.",al={"bor gnomer här","är gnomerna fortfarande i gnomeregan","vem bor i gnomeregan nu"}},["46a0252f"]={q="Vem utlöste strålningen i Gnomeregan?",a="High Tinker Gelbin Mekkatorque beordrade att stadens radioaktiva tankar skulle nödtömmas, på inrådan av sin främste rådgivare, Mekgineer Thermaplugg. Planen skulle bara fylla de nedre våningarna för att utrota trogginvasionen, men strålningen dödade nästan åttio procent av gnomerna. Thermaplugg, som i hemlighet eftertraktade ämbetet som High Tinker, stämplas nu som förrädare; rykten om att han kände till trogginvasionen i förväg har aldrig bekräftats.",al={"vem bestrålade gnomeregan","vem släppte ut gasen","vem utlöste strålningen"}},bfca8253={q="Kunde gnomerna ha räddat Gnomeregan?",a="Ingen kan säga säkert. Trogginvasionen kom medan det tredje kriget rasade, och gnomerna bekämpade den på egen hand tills den desperata tömningen av stadens radioaktiva tankar beseglade Gnomeregans öde.",al={"kunde de ha räddat staden","kunde gnomeregan ha räddats","var gnomeregans fall oundvikligt"}},["6e97b706"]={q="Grävde gnomerna upp troggerna?",a="Nej. Troggs väcktes djupt under marken när dvärgiska upptäcktsresande grävde fram titanvalvet i Uldaman. När troggerna stördes ur sin slummer tunnlade de genom bergen mot Ironforge, men lockades bort av Gnomeregans högljudda vibrationer och malande maskiner.",al={"grävde gnomerna upp troggs","hur väcktes troggerna","orsakade gnomerna troggerna"}},["1dd76133"]={q="Vem styr gnomerna nu?",a="High Tinker Gelbin Mekkatorque är fortfarande gnomernas valda ledare. Trots tragedin i Gnomeregan håller hans folk honom högt, och erkänner hans geni och hängivenhet. Han leder nu de fördrivna gnomerna från Tinker Town i Ironforge, helt inriktad på att återta deras hemland.",al={"vem leder gnomerna","gnomernas ledare","gnomernas high tinker"}},["21748788"]={q="Finns det fortfarande en gnomkung?",a="Gnomerna har ingen traditionell monarki; de är en meritokrati som leds av en vald High Tinker. Mekkatorque skämtar ibland om att kalla sig ”gnomernas kung”, men den ende som gör anspråk på kunglig titel i Gnomeregan är den galne förrädaren Mekgineer Thermaplugg, som krönte sig själv till tekniköverherre.",al={"finns det en gnomkung","har gnomerna en kung","gnomisk kunglighet"}},["955293ce"]={q="Varför vill Alliansen att jag ska bege mig till Gnomeregan?",a="High Tinker Mekkatorque och Alliansen behöver modiga äventyrare som kan slå till mot den förstörda stadens hjärta. De behöver din hjälp med att minska antalet troggs, återvinna förlorade tekniska ritningar och data, slå ut Thermapluggs automatiserade försvar och till sist avrätta förrädaren Thermaplugg själv.",al={"varför skicka mig till gnomeregan","varför har alliansen ett uppdrag i gnomeregan","varför bege sig till gnomeregan"}},["1f8ae1d4"]={q="Vad hoppas gnomerna vinna på att återta Gnomeregan?",a="Förutom att skipa rättvisa mot Thermaplugg behöver gnomerna desperat återfå viktiga ritningar, kraftkällor och maskiner som lämnats kvar. På sikt skulle ett återtagande av staden låta gnomerna avsluta sin exil i Ironforge, återuppbygga sin avancerade civilisation och återta sin ställning som en industriell stormakt för Alliansen.",al={"vad vill gnomerna ha från gnomeregan","gnomernas mål i gnomeregan","varför återta gnomeregan"}},cb78eee3={q="Kan lepragnomer botas?",a="Gnomiska forskare som Ozzie Togglevolt och Razzle Sprysprocket studerar aktivt de giftiga resterna i hopp om att uppfinna ett botemedel genom rekomposition. Än så länge är dock åkomman obotlig, och de flesta lepragnomer fortsätter att förfalla mentalt och fysiskt i de giftiga ångorna.",al={"kan lepragnomer botas","finns det ett botemedel mot lepragnomer","bota lepragnomer"}},["84ebb566"]={q="Var lepragnomer vanliga gnomer förut?",a="Ja. De var vanliga medborgare, uppfinnare och arbetare som blev instängda i de underjordiska tunnlarna under nödtömningen. Den giftiga radioaktiva gasen förvrängde deras kroppar, färgade huden sjukligt grön och härjade deras förstånd, så att de blev rabiata och endast lojala mot Thermaplugg.",al={"var lepragnomer vanliga gnomer","hur blev de lepragnomer","leprag nomernas ursprung"}},c40f7a95={q="Vet lepragnomer vad de gör?",a="Nej. Strålningen drev dem till fullständigt vansinne. I sitt delirium inbillar sig lepragnomer ofta att alla utomstående som kommer in i staden, även andra av Alliansens folk, är trogginvaserare. Med tiden bryter långvarig exponering ner deras sinnen ännu mer, tills de blir dreglande eländiga varelser.",al={"har lepragnomer något förstånd","är lepragnomer vansinniga","kan lepragnomer tänka"}},["0653d7e6"]={q="Vad är det för gnomiska maskiner som slåss mot mig?",a="De mekaniska konstruktionerna, hålkortsvakterna och folkmassbankarna du möter var ursprungligen automater för stadens försvar och nytta, byggda för att skydda staden och upprätthålla ordningen. Mekgineer Thermaplugg tog över deras huvudstyrsystem och programmerade om dem till att angripa alla inkräktare som kommer in i hans domän.",al={"gnomiska maskiner som anfaller","varför är robotarna fientliga i gnomeregan","vem styr maskinerna i gnomeregan"}},["322b05cb"]={q="Varför behöver gnomerna äventyrare utifrån i stället för sin egen armé?",a="Nästan åttio procent av gnomernas befolkning utplånades i katastrofen, vilket slog deras militär i spillror. De få överlevande gnomiska soldaterna är hårt ansträngda med att upprätthålla säkerheten och bygga krigsmaskiner åt Alliansen i Ironforge, så Mekkatorque måste anlita härdade legosoldater och hjältar för att rensa de giftiga ruinerna.",al={"varför behöver de äventyrare utifrån","varför använda inte gnomernas armé","varför ber de mig om hjälp i gnomeregan"}},["300e368c"]={q="Hur hamnade jag i Gnomeregan?",a="Du tog dig till Gnomeregan genom Dun Moroghs snötäckta utlöpare, västerut förbi Brewnall Village till stadens väldiga mekaniska portar och sedan ner med servicehissarna. Horde-äventyrare kan också använda en direkt teleportfyr som installerats i Booty Bay av gobliningenjörer, vilka har ett aktivt och lönsamt intresse av all teknik som kan bärgas ur ruinerna.",al={"hur hamnade jag här","hur tar man sig in i gnomeregan","gnomeregans ingång"}},["8cb52331"]={q="Vad förväntas jag göra i Gnomeregan?",a="Du är här för att slå till mot den galne förrädaren Mekgineer Thermaplugg, som tog kontroll över staden efter att ha lurat High Tinker Gelbin Mekkatorque att dränka dess nedre våningar i giftig strålning. För de fördrivna gnomernas räkning i Ironforge, eller för att bärga teknik och hemligheter, måste du kämpa dig genom horder av bestrålade troggs, havererade försvarsautomater och galna lepragnomer för att nå Tinkers' Court och göra slut på Thermapluggs välde.",al={"varför är jag här","vad är mitt uppdrag här","vad ska jag göra i gnomeregan"}}},fp="10,331,26.559.0,36.587.0,27.653.1,17.596.1,29.340.0,35.286.0,67.301.0,22.308.0,29.337.0,53.258.1,48.273.0,42.304.0"}
P.entries["zone:hallofthanes"] = {n="The Hall of Thanes",s="Djupt under den livliga staden Ironforge ligger The Hall of Thanes, ett uråldrigt underjordiskt komplex fyllt av dvärgisk historia. Denna avskilda grotta är avsedd för alliansens äventyrare på låg nivå och rymmer reliker från bergarikets förflutna, nu i fara. För att komma in måste du hitta bortglömda leder genom själva berget.",h="Djupt under den livliga staden Ironforge ligger The Hall of Thanes, ett uråldrigt underjordiskt komplex fyllt...",kw={"tillträde","grotta","durgen dirgehammer","faldrim anvilmar","the hall of thanes","ironforge","magmatus","plunder","underground map"},ang={["faction:Alliance"]="Ironforges stabilitet stärker alliansen direkt, så att rena dessa djupa grottor är avgörande för att säkra High Seat.",["race:Dwarf"]="För dvärgar är ett besök i The Hall of Thanes en resa ner till Dun Moroghs förfädersgrund, där vanhelgare drivs ut ur heliga salar som bär legendariska klannamn.",["race:Gnome"]="Som nära allierade som lever i Ironforge har gnomer ett starkt intresse av att oskadliggöra mekaniska konstrukter som Plunder, vilka hotar deras gemensamma tillflyktsort."},sec={{t="Hemligheter under berget",b="Medan hammarslagen ekar i Great Forge och Ironforge sjuder av liv, sträcker sig bortglömda salar långt djupare ner under stenen. The Hall of Thanes är en av dessa vördnadsvärda underjordiska platser. Den har länge varit knuten till dvärgiska släktlinjer och reliker från stenhantverkets tid, men nu måste djärva mästare från alliansen våga sig in i dess skuggiga valv för att säkra djupen."},{t="Hitta vägen",b="Det är ingen enkel sak att ta sig till The Hall of Thanes. Korridorerna som leder till de uråldriga valven har stängts eller gömts för vanliga resenärer i Ironforge. Äventyrare måste tyda bortglömda kartor, med början i att hitta en Underground Map, innan de kan navigera de djupare tunnlarna och ta sig in i grottan."},{t="Hotet från Dirgehammer",b="I komplexets hjärta väntar en mäktig samling hot, från förtrollade väktare som Plunder och den eldiga besten Magmatus till upproriska gestalter av uråldrig dvärgisk härkomst, som Faldrim Anvilmar. I den innersta helgedomen härskar Durgen Dirgehammer. När han besegras stillas äntligen oron som pyr under stadens golv, och de heliga dvärgsalarna skyddas från omstörtning."}},faq={{q="Var ligger The Hall of Thanes?",a="The Hall of Thanes ligger under dvärgarnas huvudstad Ironforge. Den ligger gömd i bergets djupare, avspärrade underjordiska områden, bortom stadens huvudstråk.",al={"the hall of thanes plats","var ligger the hall of thanes","ironforge grottans plats"}},{q="Hur tar jag mig in i The Hall of Thanes?",a="Uppdragskedjan börjar hos Earthseer Farsen, som håller vakt vid Gol'Bolar Quarry i Dun Morogh, och fortsätter via ”Underground Map” till ”Old Ironforge Incursion”, som leder dig in i The Hall of Thanes.",al={"hur man tar sig in i the hall of thanes","tillträde till the hall of thanes","uppdraget underground map"}},{q="Vilka bossar finns i The Hall of Thanes?",a="Expeditionen ställs inför fyra stora hot: Faldrim Anvilmar, den vulkaniska besten Magmatus, en förtrollad golem vid namn Plunder och den slutliga motståndaren Durgen Dirgehammer.",al={"bosslista","vilka är bossarna","bossar i the hall of thanes"}},{q="Vilket nivåspann rekommenderas för den här grottan?",a="Grottan är anpassad för äventyrare från alliansen på nivå 13 till 18 och erbjuder en tidig utmaning under jord i Ironforges djupa tunnelsystem.",al={"vilken nivå är the hall of thanes","nivåspann för the hall of thanes"}},{q="Kan spelare från horden gå in i The Hall of Thanes?",a="Nej. The Hall of Thanes är en grotta enbart för alliansen, direkt under alliansens huvudstad Ironforge.",al={"kan horden gå in i the hall of thanes","är the hall of thanes bara för alliansen"}},{q="Vad uppnår man genom att besegra Durgen Dirgehammer?",a="När du besegrar Durgen Dirgehammer bryter du de upproriska dvärgstyrkornas grepp och stoppar deras frammanade konstrukter djupt under Ironforge. När han fälls återställs tryggheten i de uråldriga förfädersvalven under Great Forge.",al={"varför döda dirgehammer","berättelsen om slutbossen","durgen dirgehammer bakgrund"}}},fx={["89d0670c"]={q="Vad är The Hall of Thanes?",a="The Hall of Thanes är en instanserad grotta djupt under dvärgarnas huvudstad Ironforge. Ironforge brukar sjuda av liv som Bronzebeard-klanens ståtliga hem, men detta underjordiska område rymmer växande interna hot och fientliga möten. Alliansens erfarna försvarare måste därför bege sig ner under berget och återställa ordningen.",al={"lore om the hall of thanes","vad är det här för grotta","grottan the hall of thanes"}},["20f1c0f0"]={q="Hur hamnade jag i The Hall of Thanes?",a="Du följde spåren efter en uråldrig underjordisk karta som hittades djupt inne på dvärgarnas område. När du hade nystat upp dess hemligheter och fått tillträde från Ironforge ledde sökandet dig till dessa bortglömda stensalar, uthuggna direkt under berget.",al={"hur hamnade jag här","hur kom jag hit","hur hittade jag the hall of thanes"}},b863ae36={q="Vad förväntas jag göra i The Hall of Thanes?",a="Du ska ta dig djupt in i dessa förfäders valv, övervinna de fientliga styrkor som håller dem och slå ner hoten som lurar i mörkret. Expeditionen kulminerar i en konfrontation med farliga avfällingar och väktare, däribland Faldrim Anvilmar, Plunder, Magmatus och Durgen Dirgehammer.",al={"vad gör jag här","varför är jag här","vad är mitt mål här"}}},fp="14,155,28.269.0,19.248.0,25.304.1,36.128.0,43.167.0,42.113.0,49.121.0,43.85.0,47.176.1"}
P.entries["zone:hillsbrad"] = {n="Hillsbrad Foothills",s="Hillsbrad Foothills är en grön och bördig trakt, den fallna kungadömet Lordaerons sista pastorala utpost. Området har till stor del undkommit Scourges pest, men slits sönder av öppet krig mellan människorna i Southshore och de Förfallna, som håller Tarren Mill. Här drabbar Alliansens och Hordens arméer samman i en våldsam korsväg utan nåd.",h="Hillsbrad Foothills är en grön och bördig trakt, den fallna kungadömet Lordaerons sista pastorala utpost.",kw={"azurelode","dun garok","durnholde","hillsbrad","hillsbrad fields","purgation isle","southshore","syndicate","tarren mill"},ang={["class:Rogue"]="Högt uppe i bergen ovanför kullarna ligger Ravenholdt Manor, den hemlighetsfulla samlingsplatsen och träningsplatsen för Azeroths mest elitpräglade tjuv- och lönnmördargille.",["race:Dwarf"]="Soldaterna i Dun Garok visar Ironforges beslutsamma militära åtagande att försvara sina mänskliga allierade och hålla tillbaka hotet från de odöda norr om våtmarkerna.",["race:Human"]="Southshore är en av ditt folks sista tillflyktsorter i Lordaeron. Att vandra över betesmarkerna påminner smärtsamt om det stora kungadöme som gick förlorat genom förräderi och odödlighet.",["race:Orc"]="Den här jorden bär en väldig tyngd för ditt folk: de raserade murarna i Durnholde Keep är platsen där krigshövding Thrall bröt sina bojor och väckte Hordens anda till liv igen.",["race:Undead"]="Tarren Mill befäster den södra gränsen av de Förfallnas rike, där Apothecary Lydon arbetar outtröttligt med att utveckla The New Plague för att trygga ditt folks framtid."},sec={{t="En trädgård bland ruiner",b="Medan norra Lordaeron ruttnar under Scourges pest förblir Hillsbrad påfallande grönt. De böljande betesmarkerna, tallskogarna och gårdarna i drift ger resenärer en sällsynt glimt av hur kungadömet såg ut före det tredje kriget. Men det fridfulla intrycket bedrar. Beväpnade patruller, laglösa legosoldater och asätande bestar sveper ständigt över fälten och landsvägarna. Det som borde vara Lordaerons kornbod har i stället blivit dess mest omstridda gränsland."},{t="Kriget mellan Southshore och Tarren Mill",b="Hillsbrads politiska hjärta präglas av två befästa fästen. I söder, längs kusten, ligger Southshore, en fristad för Alliansen där mänskliga flyktingar och soldater bor och svär sin trohet till Alliansen. I norr ligger Tarren Mill, en gång en stillsam mänsklig jordbruksby som ödelades av Scourge och senare befästes som de Förfallnas sydligaste garnison. Den öppna marken mellan bosättningarna är känd i hela Azeroth som en skoningslös dödszon, där Alliansens och Hordens mästare ständigt strider om kontrollen över trakten."},{t="Gamla sår och dolda hot",b="Hillsbrads våldsamma historia går djupt. Under det andra kriget bevittnade dess kust och kullar de första stora drabbningarna mellan Stora Alliansen och den gamla Horden. Senare fungerade fästningen Durnholde Keep som interneringsläger, där Thrall växte upp innan han ledde orchernas uppror. I dag ligger Durnholde i ruiner och har tagits över av Syndicate, landsförvisade mänskliga adelsmän som blivit hänsynslösa banditer. Kustens murlocker, fientliga gnoller och de skuggade döda på Purgation Isle ser till att ingen del av kullarna är helt trygg."}},faq={{q="Varför är Hillsbrad inte pestdrabbat som resten av Lordaeron?",a="Scourge marscherade främst genom de centrala korridorerna mot huvudstaden och de norra kungadömena, så Hillsbrad kringgicks i stort sett av pestkittlarna som ödelade norr. Därför är jorden fortfarande bördig och växtligheten frodig, vilket gör området till den mest orörda resten av gamla Lordaeron.",al={"varför är hillsbrad grönt","drabbades hillsbrad av pesten","varför finns ingen pest i hillsbrad"}},{q="Vem kontrollerar Hillsbrad just nu?",a="Ingen av fraktionerna har full kontroll. Alliansen håller Southshore och de närliggande gårdarna, som Hillsbrad Fields, medan de Förfallna håller Tarren Mill i norr. Dvärgstyrkor håller fästningen Dun Garok i öster, och det kriminella Syndicate har ockuperat ruinerna av Durnholde Keep.",al={"vem äger hillsbrad","fraktionskontroll i hillsbrad","är hillsbrad alliansen eller horden"}},{q="Vad är Durnholde Keep?",a="Durnholde var en gång högkvarter för Alliansens interneringslägersystem efter det andra kriget och styrdes av Aedelas Blackmoore, som uppfostrade Thrall där som slav och gladiator. Thrall flydde, samlade orcherna och ödelade fästningen. Efter Lordaerons fall tog Syndicate över ruinerna.",al={"durnholde bakgrund","vad hände vid durnholde","vem styr durnholde"}},{q="Varför strider de Förfallna och människorna så hårt här?",a="Tarren Mill utgör den södra gränsen för Sylvanas Windrunners domän, medan Southshore är Alliansens främsta uppmarschområde och hamn in i Lordaeron. De Förfallna ser Southshore som ett existentiellt hot mot sin södra flank, medan människorna betraktar de odöda som fruktansvärda inkräktare som måste drivas bort från deras hemland.",al={"varför kriget om southshore","bakgrund om southshore mot tarren mill","orsaken till konflikten i hillsbrad"}},{q="Vad är Purgation Isle?",a="Purgation Isle är en isolerad, karg ö utanför Hillsbrads sydkust. Till skillnad från kullarna på fastlandet kryllar ön av mäktiga odöda gastar, skelett och hämndlystna andar, vilket gör den till en extremt farlig tillflykt till havs för mörk magi och rastlösa döda.",al={"bakgrund om purgation isle","ö utanför southshore","varför finns odöda på purgation isle"}},{q="Vilka är banditerna som ockuperar lägren och tornen?",a="De tillhör Syndicate, ett organiserat nätverk av före detta adelsmän och fotsoldater från det fallna mänskliga kungadömet Alterac. De fördrevs efter att deras kungadöme förrådde sina allierade under det andra kriget och verkar nu som hänsynslösa banditer som försöker återta sina landområden genom utpressning, stöld och blodspillan.",al={"banditer i hillsbrad","vilka är syndicate","syndicate i hillsbrad"}}},fx={["5a0996a2"]={q="Vad är Hillsbrad Foothills?",a="Hillsbrad Foothills är ett böljande, tempererat kustområde längs södra kanten av det fallna Lordaeron. Det gränsar till Silverpine Forest i väster, de snötäckta Alterac Mountains i norr och Thoradin's Wall, som leder till Arathi Highlands i öster. Till skillnad från de pesthärjade områdena i norr är Hillsbrad fortfarande lummigt och lantligt, med gröna ängar, bördiga gårdar och kustklippor. Under den idylliska ytan är området en våldsam gränsbygd som de överlevande människorna i Alliansen och de framryckande Forsaken strider om.",al={"vad är hillsbrad","översikt över hillsbrad foothills","berätta om hillsbrad"}},["88d7d468"]={q="Vad hände i Hillsbrad Foothills?",a="Hillsbrad har länge varit en av de blodigaste slagfälten i Lordaeron. Under det andra kriget utkämpades här de allra första striderna mellan Alliansen och den gamla Horden, däribland häftiga skärmytslingar med skogstroll och räder längs kusten som lämnade städer som Hillsbrad och Southshore i ruiner för en tid. Senare låg orkernas interneringsläger här, med Durnholde Keep som centrum, tills Thralls uppror jämnade fästningen med marken. När det tredje kriget bröt ut stal Thrall skepp från Southshore för att nå Kalimdor, och senare svepte gisslet fram över norr. Till slut fick det de Fördömda att ta Tarren Mill.",al={"hillsbrads historia","slagets om hillsbrad historia","hillsbrads förflutna"}},["10678baf"]={q="Är Hillsbrad Foothills farligt?",a="Extremt farligt. Förutom rovdjur som bergslejon, snappsköldpaddor och kringströvande spindlar är Hillsbrad en aktiv krigszon. Southshores mänskliga vakter och Tarren Mills odöda Deathstalkers jagar fiendens resenärer längs vägarna. Dessutom håller stråtrövare från Syndicate till i utspridda torn och Durnholdes ruiner. Fientliga naga från Daggerspine och murloc från Torn Fin hemsöker kusten, Mudsnout-kobolder strövar i skogarna och dvärgskyttar har tagit Dun Garok i besittning med stora styrkor.",al={"hur farligt är hillsbrad","är hillsbrad säkert","faror i hillsbrad"}},dea356d1={q="Vad är Tarren Mill och varför är Horden här?",a="Tarren Mill är en förfallen bosättning i de norra kullarna och de Fördömdas sydligaste fäste i Lordaeron. Det var en gång en fridfull mänsklig bondby, men föll under gisslets invasion och ockuperades senare av Sylvanas Windrunners styrkor. Härifrån utövar Horden sin makt söderut, ger husrum åt apotekare som arbetar med smittsamma blandningar och stationerar trupper för upprepade angrepp mot Southshore och de närliggande mänskliga jordbruken.",al={"vad är tarren mill","varför är horden i tarren mill","hordens bas i tarren mill"}},b39e7470={q="Var Tarren Mill tidigare en mänsklig stad?",a="Ja. Före det tredje kriget var Tarren Mill en blomstrande stad i kungariket Lordaeron. Under det andra kriget skickade kung Terenas trupper hit för att befria tillfångatagna högälvsbågskyttar som Horden höll i närheten. Det bidrog till att befästa Quel'Thalas allians med mänskligheten. Även efter kungarikets fall höll en grupp människor fast vid staden en kort tid, innan gisslet och senare de Fördömdas ockupation tog den.",al={"bodde människor i tarren mill","var tarren mill mänskligt","tarren mills förflutna"}},c8808bc1={q="Vem styr i Tarren Mill?",a="High Executor Darthalia för befäl över de Fördömdas militära garnison i Tarren Mill. Hon leder krigsinsatserna i hela kullarna och beordrar riktade angrepp mot mänskliga bönder, staden Southshore och rivaliserande grupper i regionen. Tillsammans med henne övervakar forskare från Royal Apothecary Society, som Apothecary Lydon, verksamheten och de kemiska experimenten på orten.",al={"vem styr tarren mill","ledaren i tarren mill","befälhavaren i tarren mill"}},["9809687d"]={q="Vad handlar slaget om Hillsbrad egentligen om?",a="Det pågående slaget är en territoriell kamp på liv och död om södra Lordaeron. Människorna i Southshore och Hillsbrad Fields kämpar för att försvara de sista resterna av sitt ofördärvade hemland och behålla ett viktigt fäste vid kusten. De Fördömda vill i stället utvidga sitt unga kungarikes gränser från Undercity, systematiskt slå ut människornas försörjningslinjer för jordbruksvaror och driva bort Alliansen så att den inte kan inleda en motoffensiv.",al={"varför strider de i hillsbrad","syftet med slaget om hillsbrad","orsaken till kriget i hillsbrad"}},["3a05e673"]={q="Vad är Southshore?",a="Southshore är en livlig allianshamn vid sydkusten. Den var ursprungligen en enkel fiskeby och blev landstigningsplats för flyktingar från Stormwind under det första kriget. Under det andra kriget växte den till en starkt befäst militärhamn. I dag är den, under ledning av Magistrate Henry Maleb och Marshal Redpath, det främsta fästet för mänskliga överlevare, sjöfarare och äventyrare från Alliansen i norra Lordaeron.",al={"vad är southshore","översikt över southshore","alliansen i southshore"}},["54a7e72a"]={q="Var Durnholde Keep platsen där orker hölls fångna?",a="Ja. Efter Alliansens seger i det andra kriget fungerade Durnholde Keep som högkvarter för hela nätverket av interneringsläger i söder, under befäl av generallöjtnant Aedelas Blackmoore. Alliansens vakter fängslade och kuvade tillfångatagna orker här. Blackmoore uppfostrade bland annat den föräldralösa spädbarnet Thrall innanför arenans murar. Thrall lyckades till slut fly, samla sina bröder och slå fästningen i spillror med hjälp av jordandarna.",al={"var durnholde ett interneringsläger","orker fängslade i durnholde","durnholde internering"}},ee5f5dea={q="Vem håller Durnholde nu?",a="Durnholdes sönderslagna stengårdar och nedbrända byggnader har nu tagits över av Syndicate. Dessa landsflyktiga adelsmän, vanärade följeslagare och banditer från det fallna kungariket Alterac har befäst ruinerna. De använder dem som bas för räder mot försörjningslinjer, karavaner och resenärer i östra Hillsbrad.",al={"vilka finns i durnholde keep","banditer i durnholde","vem kontrollerar durnholde"}},["7f2bc51a"]={q="Vad är Dun Garok och varför är dvärgar här?",a="Dun Garok är en robust dvärgfästning bland de klippiga sydöstra branterna i Hillsbrad. Där är Stormpike-klanen och Ironforge Mountaineers förlagda under Captain Ironhills befäl. Trupperna kom för att förstärka Alliansens ställningar, säkra närliggande gruvor som Azurelode Mine och hindra de Fördömdas styrkor från att ta sig österut genom bergen mot Thoradin's Wall.",al={"vad är dun garok","varför finns det dvärgar i hillsbrad","dun garoks dvärgar"}},b8990472={q="Vad är det för murloc och något som liknar naga vid kusten?",a="Kustlinjen är översvämmad av murloc från stammen Torn Fin och de ormliknande naga som kallas Daggerspine. Torn Fin smyger omkring på grunt vatten, angriper fiskare och konkurrerar med gruvarbetare längs kusten. Samtidigt har Daggerspines naga krupit i land och etablerat kustnästen. De går brutalt till angrepp mot alla som färdas nära vågorna eller letar efter saker längs stranden.",al={"murloc vid hillsbrads kust","naga i hillsbrad","monster vid hillsbrads kust"}},["235a8e20"]={q="Hur hamnade jag i Hillsbrad Foothills?",a="Vilken väg du tog beror på din lojalitet. Om du marscherar med Horden reste du troligen söderut från The Sepulcher i Silverpine Forest, längs den långa, slingrande vägen österut vid Lordaerons södra gräns, tills du nådde Tarren Mill. Om du strider för Alliansen reste du långt från Ironforges dvärgsalar. Du marscherade norrut genom Loch Modan och Wetlands blöta träsk, tog dig genom Arathi Highlands och passerade den forntida öppningen i Thoradin's Wall för att nå hamnen i Southshore. Modiga sjöfarare och simmare tar ibland i stället sjövägen direkt norrut från Menethil Harbor.",al={"hur kom jag till hillsbrad","hur hamnade jag här","varför är jag i hillsbrad foothills","hur tar jag mig till hillsbrad"}},f17f6b77={q="Vad förväntas jag göra i Hillsbrad Foothills?",a="Du står vid en av Azeroths mest instabila frontlinjer. För Alliansen kretsar din plikt kring Southshore och Hillsbrad Fields: försvara mänskliga bönder mot de odödas angrepp, jaga Syndicates avfälliga banditer och hålla tillbaka de vilda varelserna som hemsöker stränderna. För Horden kräver High Executor Darthalia och Royal Apothecary Society i Tarren Mill att du systematiskt bryter ned människornas motstånd, samlar ingredienser till en ny farsot och driver tillbaka Stormpike-dvärgarna och Alliansens soldater. På fälten mellan de två städerna kräver överlevnad ständig vaksamhet mot fiendens hjältar.",al={"vad gör jag här","vad ska jag göra i hillsbrad","vad är mitt syfte i hillsbrad","varför är jag här"}}},fp="19,211,25.349.0,37.387.0,28.450.0,56.278.0,33.271.0,23.306.0,54.295.0,23.214.0,51.260.0"}
P.entries["zone:hinterlands"] = {n="The Hinterlands",s="The Hinterlands är en karg, tätt skogbevuxen vildmark i östra Lordaeron, inklämd mellan Plaguelands och havet. Regionen präglas av forntida ruiner efter Amani-trollens tempel, Wildhammer-klanens högt svävande örnbon vid Aerie Peak och ett väldig träd som förankrar en mystisk reva till Emerald Dream.",h="The Hinterlands är en karg, tätt skogbevuxen vildmark i östra Lordaeron, inklämd mellan Plaguelands och havet.",kw={"aerie peak","gryphon","hinterlands","jintha'alor","quel'danil","revantusk","seradane","vilebranch","wildhammer","witherbark"},ang={["class:Druid"]="Det uråldriga trädet i Seradane har en stark koppling till Emerald Dream, men mardrömmens krypande förruttnelse kräver ständig vaksamhet.",["faction:Alliance"]="Wildhammer-dvärgarna värnar om sin starka självständighet, men hjälp till deras utposter och högalverna i Quel'Danil skapar viktig välvilja inför de gemensamma trollhoten.",["faction:Horde"]="Revantusk Village ger Horde ett viktigt brohuvud i östra delen av norra Lordaeron, men överlevnad kräver att den våldsamma Vilebranch-stammen drivs tillbaka.",["race:Dwarf"]="För Wildhammer-släktingar och besökande Bronzebeard-dvärgar står Aerie Peak för ett dvärgliv utan stentak: en plats med vidsträckta himlar, shamanistisk kraft och legendariska gryphoner.",["race:Troll"]="I Hinterlands lever Amani-stammens forna storhet kvar. Där drabbar blodslinjer samman vid uråldriga tempeltrappor, och Revantusk visar att skogstrollen har en varaktig plats i New Horde."},sec={{t="Ett land med motstridiga anspråk",b="Långt innan människor eller dvärgar vandrade genom norra Lordaeron härskade skogstrollen i Amani Empire över Hinterlands. Efter nederlaget i de uråldriga Troll Wars splittrades imperiet i skilda stammar. Århundraden senare drev det tragiska War of the Three Hammers Wildhammer-dvärgarna bort från Grim Batol. Dvärgarna vandrade norrut och slog sig ner ovan jord vid Aerie Peak. Wildhammer tämjde de inhemska gryphonerna och tog till sig shamanistiska traditioner, och byggde en väldig fästning bland molnen. Trollstammarna såg dessa dvärgar ovan jord som oönskade inkräktare på sina förfäders marker, vilket utlöste en ändlös fejd med skärmytslingar och räder."},{t="Skogens stammar",b="Tre skilda skogstrollsfalanger håller till i det täta lövverket och de sönderfallande stentemplen. Den brutala och fanatiska Vilebranch-stammen är den starkaste och håller vidsträckta fästen i tempelstaden Jintha'Alor med sina terrasser och vid det höga Altar of Zul. I söder håller den svagare Witherbark-stammen fast vid Shadra'Alor och Hiri'Watha. Den nomadiska Revantusk-stammen hade länge föraktats av sina släktingar och saknade ett riktigt hem. Efter Third War valde den en radikal väg: den slöt ett fördrag med Thralls New Horde. Med stöd från orcher och Forsaken grundade Revantusk Revantusk Village på de östra havsklipporna och byggde ett trotsigt fäste vid kusten."},{t="Den slumrande revan",b="I Hinterlands norra delar står Seradane, ett väldig träd som skyddar en portal till Emerald Dream. Djupt bland dess grenar finns en stor, mystisk portal som öppnar sig mot Emerald Dream. Naturväsen och medlemmar av den gröna drakflykten vakar över den. Men en krypande skugga kallad Emerald Nightmare har börjat välla fram över portalens tröskel och förvrida drakar och drakvarelser, som en gång var välvilliga, till rasande väktare av lunden."}},faq={{q="Hur tar jag mig till Hinterlands?",a="Resenärer från både Alliance och Horde kommer från Hillsbrad Foothills och beger sig nordost genom ett bergspass bortom Durnholde Keep. Därifrån följer resenärer från Alliance vägen till Aerie Peak, medan äventyrare från Horde korsar vildmarken österut och ner till Revantusk Village vid östkusten.",al={"ingång till hinterlands","så tar du dig till hinterlands","resa till hinterlands"}},{q="Vem styr över Aerie Peak?",a="Falstad Wildhammer, herre över Aerie Peak, leder Wildhammer-klanen här. Thane Kurdran Wildhammer ledde klanen under Second War.",al={"wildhammer-ledare","vem leder wildhammer","härskare över aerie peak"}},{q="Varför är Revantusk-trollen allierade med Horde?",a="Till skillnad från de fientliga Vilebranch- och Witherbark-stammarna, som avvisade Horde-sändebud, sökte den nomadiska Revantusk-stammen skydd och ett slut på sitt kringflackande liv. New Horde gav viktiga resurser och soldater för att bygga Revantusk Village vid kusten och vann därmed stammens starka lojalitet mot de lokala rivalerna.",al={"revantusk och horde","varför trollen i hinterlands är med i horde","revantusk village historia"}},{q="Vad är Jintha'Alor?",a="Jintha'Alor är en väldig, urgammal trollfästning i flera nivåer, uthuggen i de södra klipporna. Den är Vilebranch-stammens främsta fäste och är full av vidriga offeraltaren, elitkrigare och häxdoktorer som utför blodriter till sina mörka loa.",al={"jintha'alors historia","trollstad i hinterlands","vilebranch-stad"}},{q="Vad är det väldiga trädet vid Seradane?",a="Seradane är ett av Azeroths väldiga träd och skyddar en portal till Emerald Dream. Gröna drakar och vilddjur vakar över lunden.",al={"seradane-portal","stort träd i hinterlands","gröna drakar i hinterlands"}},{q="Vad är Quel'Danil Lodge?",a="Quel'Danil Lodge är ett skogsrefugium som sköts av högalver från Highvale. Dessa skogvaktare och lärda undkom Scourges direkta angrepp på Quel'Thalas. De samarbetar med grannarna Wildhammer-dvärgarna och delar viktig underrättelse om de fientliga skogstrollen.",al={"högalvernas tillflyktsort i hinterlands","queldanil","alver i hinterlands"}}},fp="15,193,25.569.0,20.545.0,19.283.1,32.283.0,21.133.0,51.270.0,20.236.0,35.127.0,25.237.0"}
P.entries["zone:hyjal"] = {n="Mount Hyjal",s="Mount Hyjal är nattalvernas heliga berg i norra Kalimdor, krönt av världsträdet Nordrassil och den andra Evighetens källa. I Tredje krigets sista slag höll nattalver, människor och orcher dess sluttningar mot den brinnande legionen, tills Archimonde föll vid världsträdets rötter. Berget bär fortfarande ärren, och det sargade trädet står ännu över källan.",h="Mount Hyjal är nattalvernas heliga berg i norra Kalimdor, krönt av världsträdet Nordrassil och den andra...",kw={"archimonde","gravdjupen","slaget om mount hyjal","klorernas druider","hyjal","hyjal summit","mount hyjal","nordrassil","evighetens källa","världsträdet"},ang={["class:Druid"]="Druider håller Hyjal heligt: deras orden sov i evigheter i gravhölorna under berget, och dess världsträd band dem en gång till The Emerald Dream.",["faction:Alliance"]="Jaina Proudmoores överlevande från Lordaeron höll den första försvarslinjen på Hyjals sluttningar och vann den tid nattalverna behövde.",["faction:Horde"]="Thralls Horde stred på dessa sluttningar tillsammans med människor och nattalver för att hejda den brinnande legionen.",["race:NightElf"]="Hyjal är ditt folks heligaste mark: här gav kaldorei upp sin odödlighet så att världsträdet kunde förgöra Archimonde."},sec={{t="Det heliga berget",b="För tiotusen år sedan, efter den stora klyvningen, hällde Illidan Stormrage stulna vatten från den första Evighetens källa i en sjö på Mount Hyjal och skapade en andra källa. För att vakta den reste drak aspekterna världsträdet Nordrassil över dess vatten, och deras välsignelser gav nattalverna odödlighet och ett djupt band till The Emerald Dream. I årtusenden vakade kaldorei över berget medan deras druider sov i gravhölorna under det."},{t="Slaget om Mount Hyjal",b="Under Tredje kriget tågade demonherren Archimonde uppför berget med Scourge och den brinnande legionen för att tömma källan och förstöra världsträdet. Jaina Proudmoores människostyrkor och Thralls Horde lade gamla fiendskaper åt sidan för att stå vid Tyrande Whisperwind och Malfurion Stormrages sida och hålla sluttningarna länge nog för att Malfurion skulle hinna förbereda en fälla. När Archimonde nådde Nordrassil blåste Malfurion i Cenarius horn: tusentals irrbloss svärmade över demonen, och trädets lagrade kraft slet honom i stycken. Segern kostade nattalverna deras odödlighet och lämnade Nordrassil förkolnat."},{t="Gravdjupen och toppen",b="Under berget ligger Gravdjupen, ett uråldrigt grottsystem där Klorernas druider sov i björngestalt i tusentals år, tills Malfurion väckte dem med Cenarius horn för att strida mot legionen. I dag hör Gravdjupen och Hyjal Summit, högt uppe på berget, till de farligaste platserna i Kalimdor och passar bara stora krigshärar av härdade hjältar."}},faq={{q="Var ligger Mount Hyjal?",a="Mount Hyjal reser sig i norra Kalimdor, omgivet av Ashenvale, Felwood och Winterspring. På toppen står världsträdet Nordrassil och den andra Evighetens källa.",al={"var ligger hyjal","hyjals läge","hur tar man sig till mount hyjal"}},{q="Vad hände under slaget om Mount Hyjal?",a="I slutet av Tredje kriget ledde Archimonde den brinnande legionen och Scourge uppför berget för att förstöra världsträdet. Människor, orcher och nattalver höll stånd tillsammans på sluttningarna tills Malfurion Stormrage blåste i Cenarius horn vid Nordrassil; tusentals irrbloss och trädets egen kraft förgjorde demonherren.",al={"slaget om hyjal","hur dog archimonde","vem dödade archimonde"}},{q="Varför förlorade nattalverna sin odödlighet här?",a="Nordrassils välsignelser höll nattalverna unga för alltid. När trädets kraft släpptes lös för att förgöra Archimonde brändes välsignelserna bort, och kaldorei blev dödliga.",al={"nattalvernas odödlighet","varför är nattalver dödliga"}},{q="Vad är Gravdjupen?",a="Ett uråldrigt grottsystem under Mount Hyjal där Klorernas druider sov i The Emerald Dream i tusentals år, tills Malfurion Stormrage väckte dem för att strida mot den brinnande legionen. Djupen hör nu till Kalimdors farligaste platser.",al={"gravdjupen","klorernas druider","hyjals gravhölor"}},{q="Vad är Hyjal Summit?",a="Mount Hyjals höga delar, bland de farligaste platserna i Kalimdor. Bara de starkaste krigshärarna vågar sig dit.",al={"hyjal summit","toppen av mount hyjal"}}},fp="11,334,19.465.0,25.540.0,31.343.0,21.164.0,43.319.0,52.157.0,26.264.0,21.130.0"}
P.entries["zone:ironforge"] = {n="Ironforge",s="Ironforge, uthugget i hjärtat av Ironforge Mountain i snöiga Dun Morogh, är Bronzebeard-dvärgarnas uråldriga huvudstad och en ointaglig bastion för Alliansen. Kring den glödande hettan från Great Forge breder denna vidsträckta underjordiska stad ut sig som ett livligt centrum för handel, industri och uråldrig dvärgisk kunskap. Under King Magni Bronzebeards ståndaktiga styre ger den nu också skydd åt de fördrivna gnomerna från närbelägna Gnomeregan.",h="Ironforge, uthugget i hjärtat av Ironforge Mountain i snöiga Dun Morogh, är Bronzebeard-dvärgarnas uråldriga...",kw={"bronzebeard","deeprun tram","dun morogh","great forge","high seat","ironforge","khaz modan","magni bronzebeard","tinker town"},ang={["faction:Alliance"]="Ironforge, som är direkt förbundet med Stormwind via Deeprun Tram, står som Alliansens nordliga ankare och en av dess mest pålitliga militära fästningar.",["profession:Blacksmithing"]="Great Forge vördas i hela Azeroth som det främsta centrumet för metallarbete. Där finns Great Anvil, där mästersmeder och King Magni själv formar metall till legender.",["race:Dwarf"]="Ironforge är dina fränders uråldriga hem och står som ett stolt vittnesmål om din motståndskraft, din mästerliga stenkonst och din heliga härstamning från titanerna.",["race:Gnome"]="Sedan katastrofen som ödelade Gnomeregan har Tinker Town varit ditt tillfälliga hem och högkvarter medan High Tinker Mekkatorque smider planer för att befria din stad."},sec={{t="En stad av sten och eld",b="Ironforge grundades för tvåtusenfemhundra år sedan, när den första generationen dvärgar vaknade i Uldaman och vandrade västerut till Dun Moroghs karga bergstoppar. De grävde sig in i det högsta berget och byggde en väldig helgedom åt sin titanfader Khaz'goroth, intill den kolossala Great Forge. Sedan dess har staden vuxit i koncentriska ringar kring denna eldiga härd. Till skillnad från huvudstäder ovan jord ligger Ironforge helt omsluten av stentak och värms av dånande eldstäder och underjordiska floder av smält magma. Dess befästa portar och väldiga grottor har visat sig nästan ointagliga under århundraden av krig."},{t="Kriget om de tre hamrarna",b="I generationer levde tre dvärgaklaner sida vid sida i Ironforge: Bronzebeards, Wildhammers och Dark Irons. När High King Modimus Anvilmar dog år 230 före Dark Portal utbröt ett bittert inbördeskrig om herraväldet över berget. Bronzebeard-klanen segrade och förvisade sina rivaler. Senare ledde Sorcerer-Thane Thaurissan en hämndlysten belägring av Dark Irons, som trängde ända in i hjärtat av Ironforge innan Bronzebeard-styrkorna slog tillbaka dem. Thaurissan råkade frammana Ragnaros the Firelord i söder, vilket krossade Redridge Mountains och blev hans egen härs undergång. Bronzebeards har haft oinskränkt kontroll över Ironforge sedan dess."},{t="Trohet till Alliansen",b="Under det andra kriget intog orc-klanen Bleeding Hollow stora delar av Khaz Modan, men Ironforge höll stånd bakom sina stängda portar tills Alliansen av Lordaeron hävde belägringen. Av denna hedersskuld svor King Magni Bronzebeard Ironforges eviga trohet till Alliansen och stod fast även när kungadömen som Gilneas och Quel'Thalas övergav den. Under det tredje kriget sörjde Magni sin bror Muradins förlust i Northrend. I dag förblir Ironforge en av Alliansens mest okuvliga bastioner."},{t="En fristad för landsflyktiga",b="Efter Gnomeregans tragiska fall till trogg-invaderare och radioaktiv strålning öppnade King Magni Ironforges portar för tusentals gnomiska flyktingar. Under High Tinker Gelbin Mekkatorque grundade de landsflyktiga Tinker Town och skapade en livlig teknologisk fristad inne i stenstaden. Tillsammans med den underjordiska Deeprun Tram, som förbinder Ironforge direkt med Stormwind City, har dvärgarnas fäste förvandlats till ett livligt vägskäl för dvärgisk stålhantverksskicklighet och gnomisk uppfinningsrikedom."}},faq={{q="Vem styr Ironforge?",a="King Magni Bronzebeard styr Ironforge och kungariket Khaz Modan från High Seat. Han är en skicklig krigare och mästersmed, har lett sitt folk genom det andra och tredje kriget och förblir en djupt lojal stöttepelare för Alliansen.",al={"ironforge kung","ironforges härskare","vem är dvärgakungen"}},{q="Varför finns det så många gnomer i Ironforge?",a="När den närbelägna gnomiska huvudstaden Gnomeregan föll efter en plötslig trogg-invasion och en katastrofal strålningsolycka flydde de överlevande gnomerna till Dun Morogh. King Magni välkomnade dem till Ironforge och gav dem en hel stadsdel, som nu kallas Tinker Town.",al={"gnomer i ironforge","varför är gnomerna här","gnomer i tinker town"}},{q="Vad är Great Forge?",a="Great Forge är stadens eldiga industriella hjärta, som får sin kraft från underjordiska vattenfall av smält magma. Den omger Great Anvil, där dvärgiska vapensmeder smider legendariska vapen och rustningar.",al={"great forge","ironforges städ","ironforges centrum"}},{q="Hur tar man sig mellan Ironforge och Stormwind?",a="Ironforge är direkt förbundet med Stormwind City genom Deeprun Tram, en enastående underjordisk järnväg byggd med gnomisk ingenjörskonst som går rakt genom berggrunden i Eastern Kingdoms.",al={"ironforge till stormwind","deeprun tram","tåg till stormwind"}},{q="Har Ironforge någonsin fallit för en fiendehär?",a="Ironforge har aldrig fallit för en utomstående inkräktare. Kilrogg Deadeyes Bleeding Hollow-klan belägrade staden i flera månader under det andra kriget, och Dark Irons kämpade sig in i staden under kriget om de tre hamrarna, men portarna och försvararna höll stånd.",al={"har ironforge blivit erövrat","föll ironforge","belägringen av ironforge"}},{q="Vart tog de andra dvärgaklanerna vägen?",a="Efter kriget om de tre hamrarna flyttade den besegrade Wildhammer-klanen norrut till Wetlands och The Hinterlands, medan den fientliga Dark Iron-klanen slog sig ner i Redridge- och Blackrock-regionerna under Firelords herravälde.",al={"var finns wildhammers","var finns dark irons","de tre hammarnas klaner"}}},fx={["0779b12a"]={q="Vad är Ironforge?",a="Ironforge är dvärgarnas urgamla huvudstad och en av Azeroths äldsta bosättningar. Staden är uthuggen djupt under berget Ironforge Mountain i det snöiga Dun Morogh och är hjärtat i dvärgarnas kungarike Khaz Modan och en hörnsten i Alliansen. Den är en befäst underjordisk metropol med koncentriska ringar av väldiga grottkammare, dånande smedjor och livliga stensalar fulla av hantverkare, upptäcktsresande och soldater.",al={"översikt över ironforge","vad är ironforge för slags plats","om ironforge"}},["9f789b9e"]={q="Vem byggde Ironforge inne i berget?",a="För tusentals år sedan kom dvärgarnas tidiga förfäder från titanruinerna i Uldaman och reste västerut till Dun Morogh. När de upptäckte traktens högsta berg högg de ut sitt hem djupt i berggrunden. De byggde ett altare åt titanen Khaz'goroth och tände Great Forge, som den underjordiska staden sedan växte kring.",al={"vem byggde ironforge","hur skapades ironforge","vem högg ut ironforge"}},["1ca57bea"]={q="Varför rinner det lava genom mitten av Ironforge?",a="Staden höggs medvetet ut kring naturliga, underjordiska strömmar och vattenfall av smält sten. Dvärgarnas metallhantverkare utnyttjade denna outsinliga geotermiska hetta för att driva Great Forge. Den gav kraft åt gjuterier, smältverk och smedjor där Ironforges rustnings- och vapensmeder kunde tillverka vapen och rustningar i världsklass utan att elden någonsin slocknade.",al={"varför finns det lava i ironforge","lava i great forge","varför finns det magma i ironforge"}},af5eaa17={q="Vad hände i Ironforge genom historien?",a="Långt efter att staden grundats bröt ett inbördeskrig ut när högkung Modimus Anvilmar dog. Bronzebeard-klanen drev bort de rivaliserande klanerna Wildhammer och Dark Iron och försvarade senare staden mot en brutal invasion från Dark Iron. Århundraden senare, under det andra kriget, belägrade orkernas Horde Ironforge. Bergfästningen höll stånd tills Alliansen kom och bröt belägringen. Än i dag står den orubbad.",al={"ironforges historia","vad hände i ironforges historia"}},["879099cb"]={q="Vilka bor i Ironforge?",a="Ironforge är främst hem åt Bronzebeard-dvärgarna, som styr Khaz Modan. Men Gnomeregans katastrofala fall drev ett stort antal gnomiska flyktingar till staden. De grundade ett eget distrikt i Tinker Town under High Tinker Gelbin Mekkatorque. Mänskliga ambassadörer, kringresande köpmän och äventyrare från Alliansen av alla slag vandrar regelbundet genom stadens stengator.",al={"vilka bor i ironforge","ironforges befolkning","folk i ironforge"}},["30458af2"]={q="Är Ironforge farligt?",a="Bakom stadens väldiga, stängda portar anses Ironforge vara en av världens säkraste och tryggaste fästningar. Vakter patrullerar varje ring och bergsmurarna har stått emot alla belägrande arméer. Men oförsiktiga besökare kan falla i de glödheta groparna med smält slagg kring Great Forge, och skumma konspiratörer sägs hålla till i avskilda hörn.",al={"är ironforge säkert","hot i ironforge","är det säkert här"}},["44f103f9"]={q="Varför heter staden Ironforge?",a="Staden fick sitt namn efter Great Forge, den väldiga kärnan för dvärgarnas industri och hantverk, som bosättarna byggde när de först högg sig in i bergstoppen. Både den omgivande grottstaden och själva berget fick namn efter det ståtliga, eviga gjuteriet.",al={"ironforges namns ursprung","varför heter det ironforge","varifrån fick ironforge sitt namn"}},["8722c25e"]={q="Vem styr Ironforge?",a="King Magni Bronzebeard, thane av Ironforge och hövding för Bronzebeard-klanen, styr kungariket från High Seat. Som veteranbefälhavare från det andra och tredje kriget leder Magni dvärgarnas nation och samordnar nära med Alliansens ledare för att säkra Khaz Modan och de omgivande områdena.",al={"ledare för ironforge","vem leder ironforge","vem styr"}},f1f3f31b={q="Är King Magni en bra kung?",a="Magni vördas allmänt av sitt folk som en ståndaktig, modig och duglig monark som skyddade sitt kungarike genom Hordens belägring och Scourges anstormning. Även om han personligen brottas med sorgen över sin försvunne bror Muradin och spänningarna med sin dotter Moira, är han en hängiven härskare som brinner för sitt folk och sina allierade.",al={"är magni bronzebeard en bra kung","hur ser man på king magni","är magni omtyckt"}},["48b1fbac"]={q="Lyder King Magni under Stormwind?",a="Nej. Ironforge är ett helt självständigt kungarike. King Magni betraktar Stormwind som en jämbördig och uppskattad partner inom Alliansen, förenad genom urgammad heder och ömsesidiga försvarspakter. Dvärgarna hjälpte till att återuppbygga Stormwind efter det andra kriget, och Deeprun Tram förbinder deras huvudstäder, men Magni lyder endast under sin tron i bergen.",al={"lyder magni under stormwind","står ironforge under stormwind","ironforge och stormwind"}},df9a6ce3={q="Varför finns det ett gnomdistrikt i Ironforge?",a="När den underjordiska gnomhuvudstaden Gnomeregan föll för en plötslig trogginvasion och giftig strålning ledde High Tinker Gelbin Mekkatorque de överlevande till Ironforge. King Magni erbjöd sina långvariga grannar ovillkorlig tillflykt och avsatte ett distrikt som blev Tinker Town, där deras hov i exil kunde finna skydd.",al={"varför bor gnomer i ironforge","varför finns tinker town här","gnomernas historia i ironforge"}},f6bc736b={q="Vad hände med Gnomeregan?",a="Gräsliga underjordiska varelser kallade troggs vällde fram ur djupa sprickor och in i Gnomeregan. I desperation försökte gnomerna rensa ut inkräktarna genom att släppa ut radioaktivt avfall i de lägre nivåerna. Strålningen utplånade inte troggs, utan bestrålade i stället staden, gjorde många invånare sjuka och tvingade de överlevande att fly.",al={"vad hände med gnomeregan","gnomeregans fall","varför föll gnomeregan"}},cda22453={q="Planerar gnomerna att återta Gnomeregan?",a="Ja. Tinker Town fungerar som uppmarschområde för High Tinker Mekkatorque och hans ingenjörer medan de smider planer, uppfinner och bygger maskiner för att återta sitt bestrålade hem. Gnomkommandosoldater och frivilliga från Alliansen går regelbundet till angrepp i stadens korridorer för att rensa bort troggs och undanröja förrädiska hot.",al={"kommer gnomerna att återta gnomeregan","återtar gnomerna gnomeregan","planer på att återta gnomeregan"}},c12e1e98={q="Hur hamnade jag i Ironforge?",a="Om du är dvärg eller gnom har du troligen marscherat uppför de väldiga stenvallarna från Dun Morogh efter att ha visat vad du går för i Coldridge Valley och Kharanos. Du skickades dit för att träffa stadens ledare. Om du kommer längre bortifrån anlände du troligen med Deeprun Tram direkt från Stormwinds hjärta, eller flög direkt in till Great Forge på ryggen av en gryphon för att handla, studera eller hörsamma King Magnis vapenrop.",al={"hur kom jag hit","hur kom jag till ironforge","hur tog jag mig till ironforge"}},fb631935={q="Vad förväntas jag göra i Ironforge?",a="Ironforge är Alliansens pulserande hjärta för handel, utbildning och militär planering i Khaz Modan. Här kan du bemästra ditt yrke vid Great Forges dånande eldar, få avancerad klassutbildning eller rådfråga Explorers' League i Hall of Explorers. High Tinker Mekkatorque samordnar gnomernas motstånd från Tinker Town, medan King Magni Bronzebeard övervakar rikets försvar mot växande hot i Eastern Kingdoms.",al={"vad ska jag göra i ironforge","varför är jag här","vad är mitt mål här"}}},fp="9,312,24.539.0,28.652.0,21.321.0,18.389.0,20.300.0,42.268.0,24.194.0,50.210.0,43.250.0,35.236.0"}
P.entries["zone:lochmodan"] = {n="Loch Modan",s="Loch Modan är en tempererad bergsdal öster om Dun Morogh, känd för sin väldiga alpina sjö som hålls på plats av den monumentala Stonewrought Dam. Området kretsar kring dvärgstaden Thelsamar och kämpar mot allt fler troggar, kobolder i gruvorna och aggressiva ogres i de nordöstra högländerna.",h="Loch Modan är en tempererad bergsdal öster om Dun Morogh, känd för sin väldiga alpina sjö som hålls på plats...",kw={"the farstrider lodge","ironband","mo'grosh stronghold","stonesplinter","stonewrought dam","the loch","thelsamar","troggar","valley of kings"},ang={["class:Hunter"]="The Farstrider Lodge längs de sydöstra bergsryggarna är en välkänd samlingsplats för spårare som jagar dalens björnar, crocolisks och bergsgamar.",["faction:Alliance"]="Loch Modan bevakar gränsen mellan Dun Morogh och de nordliga vägarna mot Wetlands och är ett viktigt bålverk för Ironforges territoriella försvar.",["profession:Mining"]="Loch Modans kullar, stenbrott och trogginfekterade grottor är rika på lättåtkomliga ådror av koppar, tenn och silver.",["race:Dwarf"]="Loch Modan visar både dvärgarnas oöverträffade ingenjörskonst i sten och den farliga forntida historia som ditt folk gång på gång gräver fram under berget."},sec={{t="Höglandets juvel",b="Loch Modan ligger i östra Khaz Modan och utgör en behaglig kontrast till Dun Moroghs frusna snöfält. Karga bergstoppar omsluter en tempererad dal med tallar och björkar, där själva sjön ligger inbäddad. Den väldiga sötvattensjön hålls på plats av Stonewrought Dam, ett arkitektoniskt mästerverk som sträcker sig längs den norra bergskanten. Den fridfulla bosättningen Thelsamar är områdets hjärta och hyser kringresande bergsbestigare, jägare och gruvarbetare som arbetar i de givande koppar- och tennådrorna utspridda bland kullarna."},{t="Uppgrävda fasor och invasioner",b="Loch Modans fridfulla landskap döljer återkommande våld. Trasiga katapulter och ballistor på sjöbottnen vittnar om Andra kriget, då orchernas Horde ockuperade dalen innan dvärgarna drev bort dem. På senare tid råkade dvärgarnas arkeologiska utgrävningar gräva fram svärmar av vilda troggar under jord. Under vilda hövdingars ledning har troggstammarna intagit de södra ravinerna i Stonesplinter Valley och Valley of Kings, hotat handelsvägarna och tvingat Ironforge Mountaineers att kämpa förtvivlat för att försvara dem."},{t="Intriger i skuggorna",b="Troggar och de väldiga ogres från Mo'grosh Stronghold är inte de enda farorna som tränger sig på i dalen. När man undersöker de lokala sabotageaktionerna närmare upptäcker man att de förrädiska Dark Iron-dvärgarna är verksamma i Loch Modan. Dark Iron-infiltratörer har tagit sig in från de brinnande passen i söder och ger sig på dvärgarnas förråd av sprängkrut. De har dessutom lömska planer mot själva Stonewrought Dam."}},faq={{q="Vad hindrar sjön från att översvämma Wetlands?",a="Stonewrought Dam, ett väldiga underverk av dvärgisk stenbyggnadskonst och ingenjörskonst, håller tillbaka hela sjön. Dvärgarnas ingenjörer underhåller den noggrant, eftersom ett dammbrott skulle spola bort de lägre sumpmarkerna i Wetlands norrut.",al={"vad är dammen","stonewrought dams syfte","varför har loch modan en damm"}},{q="Varifrån kom alla troggarna?",a="Dvärgarnas upptäcktsfärder och gruvarbetare råkade bryta igenom underjordiska kammare djupt inne i bergen och släppte lös horder av vilda troggar. De svärmade snabbt upp till ytan och anlade läger i dalarna.",al={"varför finns det troggar här","trogginvasionen i loch modan","troggarnas ursprung"}},{q="Vilken är områdets främsta bosättning för Alliance?",a="Thelsamar ligger inbäddad på de västra klipporna och är den främsta staden för Alliance och ett nav för resor. Där finns Stoutlager Inn, handelsfolk och gryphon masters som förbinder staden med Ironforge och andra platser.",al={"staden i loch modan","nav i loch modan","thelsamar"}},{q="Vem styr Mo'grosh Stronghold?",a="Fästet i de nordöstra bergen hålls av brutala ogres som tog sig ner i dalen och byggde en befäst utpost som terroriserar närliggande jägare och resenärer.",al={"ogreläger i loch modan","ogres i nordöstra loch modan","mo'grosh"}},{q="Vad hände med Ironband's Excavation Site?",a="Prospector Ironbands arkeologiska utgrävning översvämmades av troggar som strömmade ut ur de underjordiska kamrarna. Utgrävningslaget tvingades avbryta arbetet och kämpa för att säkra sina återstående förråd.",al={"ironbands utgrävning","varför övergavs ironbands utgrävning","prospector ironbands problem"}},{q="Kan du resa från Loch Modan till Badlands eller Searing Gorge?",a="Ja. Stigar går söderut genom bergen till Badlands torra ödemark, medan Stonewrought Pass genom Valley of Kings leder sydväst till Searing Gorges vulkaniska klippor.",al={"loch modan till badlands","loch modans södra utgång","vägen till badlands"}}},fx={["2ab9b343"]={q="Vad är Loch Modan?",a="Loch Modan är en tempererad dal i östra Khaz Modan, öster om Dun Morogh och söder om Wetlands. Den omges av karga berg och ljusa tallskogar, och dess främsta kännetecken är den väldiga sötvattensjön som hålls tillbaka av den ståtliga Stonewrought Dam. Området är en viktig del av dvärgarnas kungarike Ironforge.",al={"området loch modan","om loch modan","vad är det här för plats"}},["4c6debd3"]={q="Vad hände i Loch Modan?",a="Under det andra kriget svepte Horden in i Loch Modan och befäste positioner runtom i dalen mot Alliansen. Ironforges försvarare utkämpade ett blodigt fälttåg för att befria sitt land. Dvärgarna återtog regionen, men trasiga katapulter och ballistor som ligger kvar på sjöbottnen och öarna vittnar om kriget.",al={"loch modans historia","tidigare strider i loch modan","loch modan under det andra kriget"}},["11acca40"]={q="Är Loch Modan farligt?",a="Bakom den fridfulla alpina fasaden döljer sig flera kriser i Loch Modan. Aggressiva troggs som grävts fram vid nya utgrävningar härjar i kullarna och gruvorna, Mo'grosh-ogrer håller till i nordost, kobolder plågar vägarna och infiltratörer från Dark Iron-klanen saboterar aktivt dvärgarnas ställningar kring Stonewrought Dam.",al={"faror i loch modan","är loch modan tryggt","hot i loch modan"}},["85c52931"]={q="Vilka bor här?",a="Dvärgar och gnomer från Ironforge bor i dalen, främst kring bosättningen Thelsamar, och jägare och spårare håller till vid Farstrider Lodge. Men aggressiva troggs, kobolder, sabotörer från Dark Iron och Mo'grosh-ogrer utmanar dvärgarnas kontroll över stora delar av vildmarken.",al={"vilka bor i loch modan","invånare i loch modan","vem bor här"}},["0925f1bd"]={q="Tillhör det här området dvärgarnas kungarike?",a="Ja. Loch Modan är en viktig östlig provins i kungariket Ironforge. Den styrs under King Magni Bronzebeards myndighet och försvaras av Ironforge Mountaineers.",al={"tillhör loch modan ironforge","styr ironforge över loch modan","dvärgarnas kungarike i loch modan"}},["90a2b33d"]={q="Har sjön alltid varit så här stor?",a="Nej. Sjön var en gång mycket mindre. När mästerarkitekten Franclorn Forgewright ritade och byggde Stonewrought Dam dämdes avrinningen från Khaz Modans berg upp av den väldiga konstruktionen. Sjön blev då mer än dubbelt så stor som den ursprungligen var.",al={"hur stor var loch modan","sjöns ursprungliga storlek","gjorde dammen sjön större"}},ef90b12a={q="Vem styr här omkring?",a="Regionen lyder direkt under King Magni Bronzebeard i Ironforge. Den civila förvaltningen i Thelsamar sköts lokalt av Magistrate Bluntnose, militärgarnisonerna följer befäl som Captain Rugelfuss och försvaret av den livsviktiga Stonewrought Dam ligger under Chief Engineer Hinderweir VII.",al={"vem styr loch modan","loch modans ledarskap","vem styr det här landet"}},["0cf9ab54"]={q="Vad är Thelsamar?",a="Thelsamar är den främsta dvärgbosättningen i Loch Modan och ligger längs de västra klipporna. Där finns Stoutlager Inn, hantverkare, gryphonförare och den lokala förvaltningen. Orten fungerar som utgångspunkt mellan Ironforge, Wetlands och de östra gränstrakterna.",al={"byn thelsamar","orten thelsamar","om thelsamar"}},["9c1680d8"]={q="Vad är troggs och var kommer de ifrån?",a="Troggs är vilda, underjordiska humanoider som dvärgarnas arkeologiska utgrävningar och gruvdrift oavsiktligt släppte lösa under Khaz Modans bergstoppar. När de väcktes svärmade de upp i dalarna, byggde primitiva läger och angrep resande.",al={"var kom troggs ifrån","vad är en trogg","troggs ursprung"}},["15b5e85c"]={q="Vad gör Dark Iron-dvärgarna vid dammen?",a="Sabotörer från Dark Iron har tagit sig fram till Stonewrought Dam med sprängämnen och försöker underminera Ironforges kronjuvel. Deras planer hotar att spränga dammen och ödelägga regionen, så Chief Engineer Hinderweir VII måste be om hjälp med att rensa ut dem.",al={"dark iron vid dammen","varför är dark iron vid stonewrought dam","hot från dark iron i loch modan"}},["0550e806"]={q="Vad gräver Ironbands utgrävning efter?",a="Prospector Ironbands grupp skickades för att gräva fram forntida titanföremål och avslöja dvärgarnas bortglömda arv. Tyvärr grävde de sig in i grottor fulla av troggs. Gruvarbetarna blev övermannade och drevs bort, och Ironband började i stället rikta blicken mot de forntida ruinerna i Uldaman.",al={"målet med ironbands utgrävningsplats","vad gräver de efter vid ironband","ironbands utgrävning"}},c3dabc80={q="Vad är Dun Algaz och varför är det farligt?",a="Dun Algaz är det befästa bergspasset som förbinder Loch Modan med Wetlands i norr. Fientliga styrkor, däribland orcher från Dragonmaw och lokala banditer, belägrar och strider ständigt om passet. Utan dvärgpatruller är det farligt att ta sig igenom.",al={"dun algaz-passet","varför är dun algaz farligt","passagen till wetlands"}},["2a064472"]={q="Vad finns på andra sidan Dun Algaz?",a="Genom Dun Algaz vindlande tunnlar ligger Wetlands, ett vidsträckt, dimmigt träsk som sträcker sig mot Menethil Harbor och de nordliga länderna.",al={"vart leder dun algaz","vad ligger norr om dun algaz","bortom dun algaz"}},["52ebefe5"]={q="Hur hamnade jag i Loch Modan?",a="Om du är dvärg eller gnom gick din väg troligen österut från Dun Moroghs snöiga klippor, genom de bevakade tunnlarna vid North Gate eller South Gate Pass. Resenärer från mer avlägsna trakter, däribland människor och nattalver som kommer från Stormwind via Deeprun Tram till Ironforge, färdas samma bergsväg ner i den tempererade dalen eller flyger direkt till Thelsamar.",al={"hur hamnade jag här","hur kom jag till loch modan","ta sig till loch modan"}},["13e88a97"]={q="Vad förväntas jag göra i Loch Modan?",a="Loch Modans försvarare är hårt pressade och behöver din hjälp omedelbart. Fientliga trogger som dvärgarnas gruvdrift grävt fram hotar bosättningarna, medan vilda Mo'grosh-ogrer dominerar nordost. I Thelsamar och Valley of Kings hoppas Captain Rugelfuss och de lokala bergssoldaterna att rekryter ska slå tillbaka troggernas intrång, hjälpa Prospector Ironbands hårt ansatta utgrävning och skydda den livsviktiga Stonewrought Dam från hotande sabotage.",al={"varför är jag här","vad ska jag göra i loch modan","vad är mitt uppdrag här"}}},fp="10,205,16.273.0,31.409.0,20.301.1,52.164.0,35.171.0,52.170.0,30.171.0,44.163.0,64.175.0"}
P.entries["zone:moonglade"] = {n="Moonglade",s="Moonglade är en urgammal, avskild skogsdal högt uppe i norra Kalimdor, vördad som druidismens heliga hjärta och hem åt Cenarion Circle. Skyddad under evig skymning och orörd av dödlig korruption är den en neutral fristad där Night Elf- och taurenutövare studerar naturen sida vid sida. För andra än druider krävs det att man trotsar den farliga bergstunneln genom Timbermaw Hold för att nå denna höglandsfristad.",h="Moonglade är en urgammal, avskild skogsdal högt uppe i norra Kalimdor, vördad som druidismens heliga hjärta...",kw={"cenarion circle","dendrite starblaze","emerald dream","lake elune'ara","moonglade","nighthaven","remulos","stormrage barrow dens"},ang={["class:Druid"]="Moonglade är ditt heliga hem och din fristad. Tack vare din medfödda andliga förbindelse kan du teleportera hit från var som helst i Azeroth för att rådfråga mästare som Dendrite Starblaze, samtala med mäktiga andar och bemästra former som vattenformen.",["race:NightElf"]="I tiotusen år var Moonglade ditt folks andliga hjärta och viloplatsen för era sovande ärkedruider, skyddad under Elunes bestående välsignelse.",["race:Tauren"]="Ditt inträde i Cenarion Circle innebär att ett uråldrigt band till Cenarius återupplivas. Hamuul Runetotem drev på förändringen, som respekteras i hela Moonglade trots nattalvernas gamla slutenhet."},sec={{t="Helig skymning",b="Moonglade omges av branta berg norr om Felwood och Winterspring och ligger i en evig, fridfull natt under Elunes månes milda sken. I dess mitt ligger Lake Elune'ara, en djup och stilla sjö som varit helig sedan kaldoreicivilisationens gryning. Gläntan förblev oskadd av Burning Legion under både forntida invasioner och det nyliga tredje kriget, skyddad av den vaksamma halvguden Cenarius och hans avkomma. I dag, under Keeper Remulos ledning, tjänar dalen som en fridfull tillflyktsort där naturens balans bevaras, fri från fraktionskonflikter."},{t="Cirkelns säte",b="Moonglade är högkvarter för Cenarion Circle, som grundades för årtusenden sedan av Malfurion Stormrage. I byn Nighthaven vid sjön vägleder uråldriga traditioner druidernas utbildning. Efter det tredje kriget tog Circle det historiska steget att välkomna tauren till sina led, ledda av ärkedruiden Hamuul Runetotems lära. I Moonglade läggs politiska lojaliteter till Alliance eller Horde åt sidan. Beväpnade väktare upprätthåller strikt neutralitet och ser till att våld mellan medlemmarna snabbt bestraffas."},{t="Barrow Dens och drömmen",b="Söder om Lake Elune'ara ligger de uråldriga Stormrage Barrow Dens. I tusentals år låg alvdruider sovande i dessa underjordiska hålor och färdades genom andevärlden The Emerald Dream medan deras dödliga kroppar vilade under ständig bevakning. Det var här Tyrande Whisperwind blåste i Cenarius horn för att väcka Malfurion under det tredje kriget. Än i dag är hålorna nära knutna till drömmen, men märkliga och oroande krusningar har börjat uppstå från de djupa tunnlarna medan mörka viskningar oroar smaragdriket."}},faq={{q="Hur tar sig resenärer som inte är druider till Moonglade?",a="Om de inte förs dit med rituell magi under säsongsevenemang måste resenärer till fots passera genom Timbermaw Hold, ett tunnelkomplex som förbinder övre Felwood, Winterspring och Moonglade. Timbermaws furbolger vaktar passagen hårdnackat och kräver att främlingar bevisar sina goda avsikter innan de släpper igenom dem säkert.",al={"hur tar man sig till moonglade","ta sig till moonglade","ingången till moonglade"}},{q="Varför kan Horde och Alliance gå sida vid sida i fred här?",a="Moonglade styrs av Cenarion Circle, en orden som helt ägnar sig åt naturen snarare än politik. Moonglade Wardens, som är utposterade runt Nighthaven, upprätthåller strikt neutralitet och angriper omedelbart alla som angriper någon som står väl till hos Circle.",al={"varför är moonglade neutralt","pvp i moonglade","kan horde och alliance slåss här"}},{q="Vad har Nighthaven för syfte?",a="Nighthaven är den främsta bosättningen i Moonglade och fungerar som bostad och verksamhetscentrum för Cenarion Circle. Där finns tränare, vårdare och helgedomar där både kaldorei- och taurendruider samråder om Azeroths vildmarkers hälsa.",al={"nighthavens syfte","vad är nighthaven","stad i moonglade"}},{q="Vem styr Moonglade när Malfurion Stormrage är borta?",a="Keeper Remulos, en mäktig son till halvguden Cenarius, vakar över Moonglade från Shrine of Remulos. Tillsammans med framstående medlemmar av Circle, som Dendrite Starblaze, sköter han de heliga markerna och leder arbetet med att läka världen.",al={"ledare för moonglade","vem leder cenarion circle","vem är remulos"}},{q="Vad vilar under Stormrage Barrow Dens?",a="Barrow Dens är djupa underjordiska kammare där druider traditionellt gick in i långvarig gemenskap med The Emerald Dream. I kammarnas djupare delar finns fortfarande kraftfulla förbindelser till drömmen, men de senaste störningarna tyder på att oroande mardrömmar börjar vakna där inne.",al={"barrow dens bakgrund","stormrage barrow dens syfte","var druider sover"}},{q="Varför har druider särskilda flygrutter från Nighthaven?",a="Hippogryfmästaren Silva Fil'naveth och vindryttarvaktaren Bunthen Plainswind erbjuder särskilda resor direkt till Rut'theran Village och Thunder Bluff enbart för druider, så att orden enkelt kan resa mellan sin heliga lund och sina folks hemländer.",al={"flygmästare i nighthaven","druidernas flygmästare i moonglade","gratis flygresor i moonglade"}}},fp="9,207,15.457.0,18.412.0,29.447.1,43.274.0,57.197.0,34.215.0,53.223.0,45.241.0,58.258.0"}
P.entries["zone:mulgore"] = {n="Mulgore",s="Mulgore är taurenfolkets urgamla hemland, en frodig, skyddad dal med smaragdgröna gräsmarker, höga platåer och böljande slätter nedanför Stonetalon Mountains. Höga, naturliga bergsväggar omger landet, som säkrades efter att Cairne Bloodhoof slöt förbund med Thralls Horde för att driva bort de härjande centaurerna. I dag är det de förenade taurenstammarnas andliga och territoriella kärnland, som styrs från den mäktiga mesastaden Thunder Bluff.",h="Mulgore är taurenfolkets urgamla hemland, en frodig, skyddad dal med smaragdgröna gräsmarker, höga platåer...",kw={"bael'dun","baine bloodhoof","bloodhoof village","cairne bloodhoof","camp narache","jordmodern","kodo","mulgore","red cloud mesa","red rocks","thunder bluff","venture company"},ang={["class:Druid"]="De böljande slätterna och orörda dungarna är en av Kalimdors renaste naturtillflykter, där taurendruider studerar balansen och naturens gåvor.",["class:Hunter"]="Traditionen med den stora jakten lever vidare över dessa slätter, där pumor, vargar och vilda kodo sätter varje spårares skicklighet och tålamod på prov.",["faction:Horde"]="Mulgore är hjärtat för Hordens andlighet och jordbruk i centrala Kalimdor, och knyts till Thralls folk genom en bloded om ömsesidigt försvar.",["race:Tauren"]="Den här dalen är ditt urgamla hemland, återvunnet genom uppoffring och enighet. Att bevara dess källor och rena dess heliga marker är grundläggande plikter mot Jordmodern."},sec={{t="Ett återvunnet land",b="I generationer levde tauren som nomader, ständigt jagade och fördrivna från de centrala slätterna av aggressiva centauriska krigarskaror. Deras lycka vände när överhövding Cairne Bloodhoof mötte Thrall och hans fördrivna orcher. Taurenfolket såg att de delade ideal om ära, schamanism och styrka och slöt en allians med den unga Horden. Med hjälp av orcherna bröt Cairne centaurernas grepp om regionen och ledde sitt folk till Mulgore. Här byggde de för första gången på århundraden permanenta bosättningar och krönte de högsta nordliga mesorna med sin huvudstad, Thunder Bluff."},{t="Jordmodern sätter dem på prov",b="För att bli vuxen i Mulgore måste man svara på den stora jaktens kallelse och ära Jordmodern. Unga tauren börjar sin träning på Red Cloud Mesas södra platå, i Camp Narache under Chief Hawkwinds ledning. När de tar sig ner till The Golden Plains och Bloodhoof Village genomgår de Jordmoderns riter. De lär sig att tala med förfädernas andar, samla in inhemska örter och visa respekt för hjordarna av kodo och tallstrider som upprätthåller deras civilisation."},{t="Hotande skuggor",b="Trots sitt fridfulla yttre möter Mulgore växande hot från alla håll. Fördrivna quilboar har slagit sig ner i Brambleblade Ravine och vanhelgat de heliga gravplatserna vid Red Rocks. I bergen jagar Windfury-harpior vilt, medan Palemane-gnoller anfaller från dolda grottor. Än mer oroande är exploateringen utifrån: handelsgobliner från Venture Company har börjat vanhelga de heliga vattenkällorna och bryta sten i de östra kullarna, medan dvärgäventyrare från Bael Modan har upprättat Bael'dun Digsite för att gräva fram uråldriga titanartefakter, trots taurenfolkets protester."}},faq={{q="Varför slog sig tauren ner permanent i Mulgore?",a="Taurenfolket var historiskt nomader som färdades genom Kalimdor medan de förföljdes av härjande centaurer. Efter att ha slutit sig samman med Thralls Horde fick Cairne Bloodhoof den militära styrka som krävdes för att driva bort centaurerna och återta taurenfolkets urgamla dal Mulgore. De byggde permanenta bosättningar, däribland Bloodhoof Village och Thunder Bluff, för att skapa ett enat hemland där alla taurenstammar kunde leva i fred och blomstra.",al={"varför bor tauren här","taurenfolkets hemlands historia","varför bosätta sig i thunder bluff"}},{q="Hur lämnar du Mulgore till fots?",a="Mulgore omges helt av oframkomliga bergsväggar, förutom ett enda pass i sydöst. Följ den stora grusvägen österut förbi Bloodhoof Village och Morin Cloudstalkers utpost. Vägen går genom en bergskorridor och leder rakt ut på The Barrens torra slätter.",al={"utgång från mulgore","hur tar man sig från mulgore till the barrens","vägen ut ur mulgore"}},{q="Vilka är Venture Company och varför är de här?",a="Venture Company är en hänsynslös, goblinstyrd handelskartell som vill åt Kalimdors naturtillgångar. I Mulgore bedriver de gruvdrift i de östra bergen och har ockuperat de viktiga vattenkällorna, som Thunderhorn, Wildmane och Winterhoof. De vanhelgar landet och hotar den regionala vattenförsörjningen.",al={"venture company i mulgore","varför finns det gobliner här","venture companys gruva"}},{q="Varför gräver dvärgar på taurenfolkets mark?",a="Dvärgar från expeditionen till Bael Modan har upprättat Bael'dun Digsite i Mulgores västra förberg. De gräver fram reliker efter sina titanskapare på uppdrag av Explorers' League och gräver utan lov på taurenfolkets mark. De ignorerar taurenfolkets protester mot att verksamheten sårar Jordmodern.",al={"bael'dun digsite","varför är dvärgar i mulgore","bael dun"}},{q="Vad är Jordmoderns riter?",a="Jordmoderns riter är en helig serie prövningar som alla unga tauren genomgår när de blir vuxna. Prövningarna testar jakt, spårning, andlig syn och kunskap om naturens balans. De visar att den unga novisen är hängiven landet och folkets uråldriga traditioner.",al={"jordmoderns riter","taurenfolkets vuxenrit","jordmoderns rit"}},{q="Vem styr Mulgore?",a="Överhövding Cairne Bloodhoof styr alla taurenfolkets länder från huvudstaden Thunder Bluff, högt uppe på de nordliga mesorna. Hans son, Baine Bloodhoof, styr Bloodhoof Village och sköter vardagsfrågorna på de lägre slätterna, med stöd av Cairnes visdom.",al={"mulgores ledare","vem är hövding i mulgore","cairne bloodhoof ledare"}}},fx={["145a41be"]={q="Vad är Mulgore?",a="Mulgore är taurenfolkets frodiga, skyddade förfädershem, inbäddat innanför en ring av skyddande berg i centrala Kalimdor. De böljande, gyllene grässlätterna och de höga, vindpinade platåbergen erbjuder utmärkta jaktmarker och en fridfull tillflyktsort. Till fots når du området endast genom ett enda bergspass i öster, som leder till The Barrens.",al={"vad är det här för område","berätta om mulgore","översikt över mulgore"}},bf98c20a={q="Är Mulgore farligt?",a="Mulgore är mycket fridfullare än The Barrens, men problemen hopar sig. Aggressiva Bristleback quilboar tränger in på heliga marker, Palemane-gnoller lurar i grottor i söder och Windfury-harpior håller till längs bergsryggarna. Dessutom exploaterar Venture Company orörda vattenkällor och bergssluttningar, medan dvärgiska utgrävare skändar förfädernas marker i väster.",al={"är mulgore säkert","hot i mulgore","faror här"}},["148e56bf"]={q="Vilka är tauren, och hur hamnade de i Mulgore?",a="Tauren, eller shu'halo, är ett uråldrigt nomadfolk som vördar Jordmodern. I generationer vandrade de i The Barrens, ständigt jagade och drivna mot utrotning av härjande centaurstammar. Efter att ha knutit ett hedersband till Thrall och de nyligen anlända orcherna under det tredje kriget ledde högöverhövding Cairne Bloodhoof sitt enade folk tillbaka till Mulgore, deras förfäders dal, för att skapa ett varaktigt hem.",al={"varifrån kommer tauren","taurens historia i mulgore","hur kom tauren hit"}},dd86ecd9={q="Vem är Cairne Bloodhoof?",a="Cairne Bloodhoof är den vördnadsvärde högöverhövdingen för de enade taurenstammarna, ledare för Bloodhoof och härskare över Thunder Bluff. Cairne är en oöverträffad krigare och vis äldre. Han slöt förbund mellan sitt folk och Thralls Horde och ledde dem genom farliga krig mot centaurerna för att grunda en varaktig fristad på platåbergen.",al={"cairne bloodhoofs historia","vem är högöverhövdingen","taurenledare"}},["96a44cf3"]={q="Är Baine hans son?",a="Ja, Baine Bloodhoof är Cairnes son. Baine är känd för sitt mod i strid och sin diplomatiska återhållsamhet. Han styr Bloodhoof Village i centrala Mulgore som bosättningens hövding, medan hans far förbereder honom på att en dag ta över som högöverhövding.",al={"är baine cairnes son","baine bloodhoofs släktskap","baine bloodhoof"}},["24d564cd"]={q="Vad är Bloodhoof Village?",a="Bloodhoof Village är en stor bosättning vid Stonebull Lakes klara vatten i centrala Mulgore. Byn är uppkallad efter Cairnes stam och styrs av hans son Baine. Den är det främsta navet för handel, hantverk och samling, där unga jägare och tappra samlas efter att ha färdats ner från Red Cloud Mesa.",al={"bloodhoof villages historia","vad är bloodhoof","by i mulgore"}},dbff83eb={q="Vad är Thunder Bluff?",a="Thunder Bluff är taurenfolkets storslagna huvudstad, byggd högt uppe på en rad vindpinade, lättförsvarade platåberg som reser sig över norra Mulgore. Cairne Bloodhoof grundade staden efter det tredje kriget. Dess upphöjda platåer och repbroar ger tauren från alla stammar skydd och utgör ett tryggt fäste mot centaurernas angrepp.",al={"thunder bluffs historia","taurenfolkets huvudstad","stad på platåbergen"}},["69b40be7"]={q="Vad gör Palemane-gnollerna i Mulgore?",a="Palemane-stammen av gnoller har grävt bon kring Palemane Rock och slagit upp utspridda läger längs Mulgores södra berg. Taurenfilosofin värdesätter att dela Jordmoderns gåvor, men dessa aggressiva gnoller trakasserar resenärer, plundrar närliggande jaktmarker och angriper alla tappra som kommer nära deras revir.",al={"palemane-gnoller i mulgore","varför är gnollerna här","palemane rock"}},["7f5f34f0"]={q="Hur hamnade jag i Mulgore?",a="Om du är tauren växte du upp här bland de nomadiska stammar som nyligen enats under högöverhövding Cairne Bloodhoof. Efter det tredje kriget slog sig ditt folk ner på dessa frodiga förfädersslätter för att komma undan centaurerna och bygga ett permanent hem. Din träning började på den södra platån vid Red Cloud Mesa. Resenärer av andra raser kommer genom det enda befästa bergspasset från östra The Barrens eller får lift med en wyvern direkt till Thunder Bluffs vidsträckta platåstad.",al={"hur hamnade jag här","varför är jag i mulgore","hur kom jag till mulgore"}},a8ac99e7={q="Vad förväntas jag göra i Mulgore?",a="Unga tauren måste genomgå Jordmoderns riter för att bevisa sitt värde, hedra förfädernas traditioner och lära sig landets seder. Utöver riterna hotas Mulgores fred av faror som tränger sig på: aggressiva Bristleback quilboar svärmar i de östra ravinerna, Palemane-gnoller lurar i kullarna och det goblindrivna Venture Company förorenar heliga vattenkällor och gräver efter malm i bergen. Oavsett om du svarar på Chief Hawkwinds uppmaning eller hjälper Baine Bloodhoof i Bloodhoof Village är din plikt att skydda stammarna och försvara det nya hemlandet.",al={"vad gör jag här","vad ska jag göra här","vad är mitt mål i mulgore"}}},fp="7,276,16.464.0,29.422.0,19.560.0,49.395.0,33.247.0,50.273.0,44.275.0,38.319.0,18.219.0"}
P.entries["zone:orgrimmar"] = {n="Orgrimmar",s="Orgrimmar reser sig bland norra Durotars röda raviner som orchernas befästa huvudstad och Nya hordens hjärta. Troll, tauren och Förfallnas allierade finner också skydd innanför dess murar.",h="Orgrimmar reser sig bland norra Durotars röda raviner som orchernas befästa huvudstad och Nya hordens hjärta.",kw={"cleft of shadow","drag","durotar","grommash hold","orgrim doomhammer","orgrimmar","ragefire chasm","thrall","valley of spirits","valley of strength","valley of wisdom","krigshövding"},ang={["class:Shaman"]="Som schaman följer du Thralls återupprättande av schamanismen i hordens ledarskaps hjärta. I den fridfulla Valley of Wisdom studerar utövare elementen och samtalar med förfädernas andar.",["class:Warlock"]="Som trollkarl finner du en osäker tillflykt i The Cleft of Shadow. Thrall håller uppsikt medan du slipar dina mörka konster, avskild från öppet dömande.",["faction:Horde"]="Som hordens mästare finner du vapensmeder, klassmentorer och handelsplatser i dess militära och kulturella centrum. Krigshövding Thrall tar också emot besökare här.",["race:Orc"]="Som orch kan du se Orgrimmar som en dyrköpt frihet från demonisk dvala och fångenskap, och som ditt folks stolta förfädersfäste på Durotars mark.",["race:Troll"]="Som Darkspear-troll har du funnit en varaktig fristad tillsammans med orcherna efter att ha förlorat Darkspear Isles. Valley of Spirits är ditt trygga andliga hem."},sec={{t="Ett hem uthugget ur sten",b="Orgrimmar växte fram ur orchernas sökande efter ett hemland efter det tredje kriget. Krigshövding Thrall ledde dem till Kalimdors torra kuster, på jakt efter frihet från demonisk fördärv och mänskligt slaveri. Han döpte det hårda landet efter sin far och staden efter sin fallne mentor, Orgrim Doomhammer. Att bygga fästet krävde blod och svett. Med hjälp av tauren, Darkspear-troll, gobliningenjörer och mästaren Rexxar drev Horden tillbaka kentaurer, harpior och våldsamma åsködlor som hotade ravinerna."},{t="Hordes dalar",b="Karga berg skyddar Orgrimmar från främmande inkräktare och Durotars våldsamma rakbladsvindar. Stadens naturliga håligheter ger varje dal sin egen plats i hordens liv. Valley of Strength rymmer den civila portbyggnaden, med en väg vidare in i handelsbasaren The Drag. Taurendruider och schamaner samlas vid bassängerna i visdomens dal. Darkspear-skuggjägare och häxdoktorer bor bland de pålade paviljongerna i andarnas dal."},{t="Skuggor i den röda klippan",b="Nedanför Valley of Honor och höjderna vid Grommash Hold sjuder ett annat liv under Orgrimmar. Trollkarlar och skurkar övar i grottan som kallas skuggornas klyfta, där Thrall håller noggrann uppsikt och motvilligt tillåter deras konster. Ännu längre ner slingrar sig Ragefire Chasm genom vulkaniska tunnlar under ravinens botten. Mörka sekterister och underjordiska bestar frodas där och hotar fästningen inifrån dess egna grundvalar."}},faq={{q="Vem styr Orgrimmar?",a="Krigshövding Thrall styr Orgrimmar från Grommash Hold. Han leder Nya horden med ära, överlevnad och schamanistiskt arv i åtanke, tillsammans med Darkspear-hövdingen Vol'jin och den veteranbefälhavare Varok Saurfang.",al={"ledare i orgrimmar","vem styr orgrimmar","nuvarande krigshövding"}},{q="Varför heter staden Orgrimmar?",a="Thrall döpte Orgrimmar efter Orgrim Doomhammer, den legendariske tidigare krigshövdingen. Orgrim bröt skuggorådets grepp om Gamla horden och överlämnade sin rustning och Doomhammer till Thrall innan han dog i strid.",al={"orgrimmars namnets ursprung","efter vem är orgrimmar uppkallat"}},{q="Vilka bor i Orgrimmar förutom orker?",a="Orgrimmar är hem åt Darkspear-trollstammen, vars medlemmar bor i Valley of Spirits, och välkomnar besökande taurenambassadörer i Valley of Wisdom. En grupp sändebud från Förfallna finns också i staden efter deras nyliga inträde i Horden.",al={"raser i orgrimmar","vem bor här","troll i orgrimmar"}},{q="Vad är Cleft of Shadow?",a="The Cleft of Shadow är en dunkel, grottlik spricka under ravinklipporna, intill The Drag. Stadens skurk- och trollkarlsgillen har sitt hem där och håller olaglig handel och farliga demoniska besvärjelser avskilda från bostadsområdena.",al={"cleft of shadow","underjordiska orgrimmar","häxmästarnas område i orgrimmar"}},{q="Vilka hot finns inne i staden?",a="Ragefire Chasm ligger rakt under The Cleft of Shadow. Dess vulkaniska sprickor vimlar av trogger, brännande elementarer och förrädiska trollkarlar som försöker underminera Thralls styre från djupen.",al={"faror i orgrimmar","hotet i ragefire chasm","kultister i orgrimmar"}},{q="Hur reser du till andra kontinenter från Orgrimmar?",a="Zeppelinare byggda av gobliner lägger till på torn utanför Orgrimmars huvudport. De flyger regelbundet över Stora havet till Tirisfal Glades nära Undercity och söderut till Grom'gol Base Camp i Stranglethorn Vale.",al={"zeppelinare i orgrimmar","ta sig till tirisfal från orgrimmar","resa från orgrimmar"}}},fx={["34960c6e"]={q="Vad är Orgrimmar?",a="Orgrimmar är orchernas krigiska huvudstad och den nya Hordens främsta säte. Staden är uthuggen ur de höga röda klippkanjonerna i norra Durotar och utgör ett befäst skydd som krigshövding Thrall lät bygga efter det tredje kriget. Den är hjärtat för handel, militär styrka och kultur bland orcherna, Darkspear-trollen, tauren och deras Forsaken-allierade.",al={"vad är det här för stad","översikt över orgrimmar","om orgrimmar"}},["2f0bb5cb"]={q="Vem byggde Orgrimmar?",a="Krigshövding Thrall och hans orcher grundade fästningen kort efter slaget vid Mount Hyjal och färdigställde den på anmärkningsvärt kort tid. De fick hjälp av de listiga Darkspear-trollen, de ädla tauren från Mulgore, goblinarbetare och ingenjörer samt den kringvandrande halvorchjätten och bestmästaren Rexxar.",al={"vem skapade orgrimmar","hur byggdes orgrimmar","orgrimmars byggande"}},["8dcd1cbd"]={q="Varför ligger Orgrimmar här ute i öknen?",a="Thrall ledde medvetet sitt folk till Durotars hårda, solstekta marker för att bygga ett hem genom arbete och uthållighet. Den röda jorden och de karga klipporna påminde orcherna om deras förfädershem Draenor, samtidigt som dalarna och kanjonerna erbjöd naturligt försvar för deras dyrköpta självständighet.",al={"varför bygga i durotar","varför ligger staden i en öken","varför slå sig ner här"}},["2df9c1bd"]={q="Var är Thrall?",a="Thrall håller hov i Grommash Hold, högt uppe i Valley of Wisdom. Utanför hans kalla stenfästning står en uråldrig trädstam med Mannoroths krossade skalle och rustning på en påle. Det är ett slående monument över Grom Hellscreams offer och Hordens befrielse från demonisk fördärvelse.",al={"var hittar jag thrall","var befinner sig thrall","var är krigshövdingen"}},["6bde2c20"]={q="Vem är Nazgrel?",a="Nazgrel är en veteran bland orchkrigare och en betrodd löjtnant som tjänstgör direkt under Thrall i Grommash Hold. Han är hängivet lojal mot krigshövdingen och hjälper Hordens högsta befäl att övervaka stadens försvar och stridsberedskap.",al={"vem är krigaren vid thrall","nazgrels roll","thralls rådgivare nazgrel"}},["19245cb0"]={q="Är Orgrimmar farligt?",a="Stadens höga portar och erfarna fotsoldater håller inkräktare borta, men faror lurar fortfarande innanför murarna. Skumma kultister och avfälliga kulter gömmer sig i de skuggiga klyftorna under klipporna, våldsamma rakvindar sveper genom dalarna och skadar vårdslösa byggen, och den underjordiska grottan Ragefire Chasm sjuder av trogger och mörk elementär fördärvelse rakt under gatorna.",al={"är det säkert här","faror i orgrimmar","risker i orgrimmar"}},f5c45f78={q="Vad hände vid Orgrimmar?",a="Efter det tredje kriget ledde Thrall orcherna till Kalimdor för att undkomma den demoniska smitta som hade slagit sönder deras folk. Med hjälp av tauren, trollen och Rexxar högg de ut denna fästning ur Durotars kanjoner, samtidigt som de kämpade mot traktens quilboar, centaurer och harpior. En karg gränstrakt blev den nya Hordens bestående borg.",al={"orgrimmars historia","orgrimmars förflutna","hur grundades orgrimmar"}},f55ec44b={q="Hur hamnade jag i Orgrimmar?",a="Om du är en orc eller en Darkspear-troll svarade du på dina äldstes kallelse. Efter att ha visat vad du går för i Durotars prövningar skickade dina tränare dig norrut längs de röda lervägarna, så att du kunde passera genom huvudstadens stora, befästa portar. Om du kom långväga ifrån, som en tauren från Mulgore-slätterna eller en Forsaken-resenär som korsat Stora havet med zeppelin från Tirisfal Glades, har du kommit till hjärtat av den Nya horden. Du har hörsammat krigschef Thralls kallelse att ena dess skingrade folk under en fana.",al={"hur hamnade jag här","hur kom jag hit","varför kom jag till orgrimmar"}},["07461c2e"]={q="Vad ska jag göra i Orgrimmar?",a="Du är här för att vässa ditt hantverk, rapportera till dina ledare och hjälpa den växande Horden. Sök upp klassmästare och yrkestränare i stadens dalar, handla på auktionshusen eller inställ dig inför krigschef Thrall i Grommash Hold. Det unga riket hemsöks av hot, från centaurernas stridsgrupper och quilboar-plundrare som tränger över gränserna till avskyvärda kultister som gömmer sig i Ragefire Chasms underjordiska djup. Visa ditt värde genom att försvara dina allierade.",al={"vad ska jag göra här","varför är jag här","vad är mitt syfte i orgrimmar"}}},fp="9,189,26.559.0,20.491.0,23.432.1,20.206.0,32.211.0,36.267.0,28.236.0,35.193.0,53.213.0"}
P.entries["zone:ragefire"] = {n="Ragefire Chasm",s="Under Orgrimmar skyddar Ragefire Chasms vulkaniska tunnlar troggs och en demonisk kult. Searing Blade smider planer mot den unga Horden i grottor under The Cleft, och hotar huvudstaden ovanför.",h="Under Orgrimmar skyddar Ragefire Chasms vulkaniska tunnlar troggs och en demonisk kult.",kw={"bazzalan","ravin","cleft of shadow","jergosh","neeru fireblade","orgrimmar","ragefire","rfc","searing blade","taragaman"},ang={["class:Warlock"]="Som häxmästare kan du själv se Searing Blades mörka magi i ritualerna och de demoniska skriftrullar som Jergosh the Invoker och Bazzalan använder.",["faction:Horde"]="För Horden är renandet av klyftan under Orgrimmar ett prov där unga hjältar får visa sin styrka och skydda huvudstaden.",["race:Tauren"]="Som tauren gör Maur Grimtotems död för Ragefire-troggsens händer jakten på bestarna till en fråga om heder och hämnd för Thunder Bluff."},sec={{t="Faran under jord",b="Ragefire-troggs väller upp ur djupet under Orgrimmar och in i en labyrint av vulkaniska gångar och lavagropar. Medan orciska byggare reser sitt nya hem ovanför blir troggsen allt aggressivare. Magatha Grimtotem skickar Maur Grimtotem för att inleda samtal på Thunder Bluffs vägnar, men troggsen slaktar sändebudet. De ger sig bara för våld."},{t="Searing Blade",b="En demonisk kult som kallas Searing Blade är farligare än troggsen. Fanatikerna är lojala mot Shadow Council och smider planer på den unga Hordens undergång i grottor intill magmaströmmar. Häxmästaren Jergosh the Invoker, den listige satyren Bazzalan och den grymme felvakten Taragaman the Hungerer leder dem. Taragaman vakar över ett altare i lavasjön."},{t="Krigshövdingens spel",b="Neeru Fireblade verkar vara en häxmästarlärare vid chasmens ingång i The Cleft of Shadow. I hemlighet leder han den lokala Burning Blade. Neeru skickar Hordeäventyrare ner i djupet som lojalitetsprov, i hopp om att rensa ut svaga kultister och döda Thralls anhängare. Thrall känner till Neerus svek. Hordens hövding använder dessa expeditioner för att undanröja farliga kultledare som Jergosh och Bazzalan, samtidigt som han låter Neeru stanna kvar för att bevaka Shadow Councils större planer."}},faq={{q="Var finns ingången till Ragefire Chasm?",a="Ingången ligger inne i Orgrimmar, i det underjordiska distriktet som kallas The Cleft of Shadow. Den ligger nära Neeru Fireblades tält, där häxmästaren håller till.",al={"rfc:s plats","var ligger rfc","ragefire-ingång"}},{q="Varför finns det troggar under Orgrimmar?",a="Ragefire-troggs grävde sig upp från underjordiska hålor under Durotar. Diplomatin lyckades inte hejda deras plötsliga närvaro under huvudstaden, vilket ses som ett allvarligt hot.",al={"ragefire-troggarnas ursprung","varför finns troggar här","orgrimmars troggar"}},{q="Vem leder kultisterna inne i ravinen?",a="Searing Blade leds av Jergosh the Invoker, en häxmästare, och Bazzalan, en satyr. Taragaman the Hungerer, en tillkallad felvakt, bistår dem.",al={"rfc-bossar","searing blades ledare","vem styr ragefire"}},{q="Vad innebär det för berättelsen att döda Bazzalan och Jergosh?",a="När Bazzalan och Jergosh dödas bryts Searing Blades aktiva ledarskap under Orgrimmar. Deras död visar Hordens motståndskraft och låter Thrall omintetgöra en demonbesvarande cell under sin tron.",al={"bazzalans bakgrund och betydelse","varför döda bazzalan","vad händer med de dolda fienderna"}},{q="Kan Alliance-äventyrare gå in i Ragefire Chasm?",a="Alla äventyrare kan fysiskt ta sig in genom portalen, men en Alliance-äventyrare måste undvika Horde-vakter på hög nivå och fientliga försvarare genom hela Orgrimmar för att nå The Cleft of Shadow.",al={"kan alliance göra rfc","alliance i ragefire"}},{q="Varför avrättar Thrall inte bara Neeru Fireblade?",a="Thrall tolererar dem som utövar mörk magi i The Cleft of Shadow och håller dem nära under uppsikt i stället för att driva dem utom synhåll.",al={"thrall och neeru fireblade","varför låta neeru leva"}}},fx={f4fa764c={q="Vad är Ragefire Chasm?",a="Ragefire Chasm är ett underjordiskt nätverk av heta vulkangrottor som löper rakt under orckapitalen Orgrimmar. Precis under de livliga gatorna ovanför döljer dess smälta djup våldsamma troggar och en hemlig sammanslutning av Searing Blade-kultister som smider planer mot Horden.",al={"vad är ragefire chasm","om ragefire chasm","ragefire chasms bakgrund"}},["947efccf"]={q="Varför finns det en grotta under Orgrimmar?",a="Grottorna bildades naturligt som ett vulkaniskt nätverk i den klippiga marken under Durotar. När orcerna valde denna försvarsvänliga kanjon för att bygga Orgrimmar låg den heta klyftan redan under marken, urholkad av urgamla underjordiska magmaströmmar.",al={"varför finns det en grotta under orgrimmar","hur bildades ragefire chasm","grottor under orgrimmar"}},["9252a3ac"]={q="Grävde orcerna ut den?",a="Nej. Orcerna grävde inte ut Ragefire Chasm. Det var redan en naturlig labyrint av smält sten och lavaöppningar långt innan Thrall ledde sitt folk till Durotar och lät resa Orgrimmars murar ovanför.",al={"grävde orcerna ut rfc","grävde horden ut ragefire chasm"}},b0dedca2={q="Varför skickade Thrall ner mig hit?",a="Thrall fick höra viskningar om kultistverksamhet som frodades rakt under hans stad. I stället för att inleda en öppen militär räd som skulle varna förrädarna skickade han lovande äventyrare ner i djupet för att undersöka hotet och undanröja Searing Blades skuggledare.",al={"varför skickade thrall mig till rfc","varför gav thrall mig ett uppdrag i ragefire","varför är jag i ragefire chasm"}},["0d5305cc"]={q="Vem är Thrall?",a="Thrall är Hordens krigschef och grundare av nationen Durotar. Han föddes som Go'el, son till hövding Durotan i Frostwolf-klanen. Han undkom mänskligt slaveri och gladiatorgroparna för att ena de splittrade orc-klanerna, återuppliva deras bortglömda shamantraditioner och skapa en ny, hedervärd Hord.",al={"vem är krigschef thrall","thralls bakgrund","vem är thrall"}},["09eb01d5"]={q="Hur blev han krigschef?",a="Thrall kämpade sida vid sida med Orgrim Doomhammer för att befria fängslade orcer från Alliansens interneringsläger efter det andra kriget. När Doomhammer föll i strid testamenterade han sin legendariska svarta rustning och stridshammare till Thrall och utsåg honom till ny krigschef, så att han kunde leda deras folk till Kalimdor.",al={"hur blev thrall krigschef","thralls väg till ledarskapet","hur fick thrall doomhammer"}},c23e3fbc={q="Är Thrall en shaman?",a="Ja. Med vägledning från andarna och den urgamle eremiten Drek'Thar i Frostwolf-klanen blev Thrall den första nya orciska shamanen på en generation. Han förkastade den fördärvande demoniska felmagin som en gång hade förslavat hans folk och valde i stället harmoni med elementen.",al={"är thrall shaman","thralls klass","kan thrall använda magi"}},["833fd6a3"]={q="Vilka är de dolda fiender som Thrall talar om?",a="De dolda fienderna är demoniska kultister och sympatisörer som lever i hemlighet i Durotar och smider planer på att störta Thralls unga samhälle. De verkar från skuggor och dolda tunnlar, tjänar mörka krafter ur orcernas förflutna och undergräver aktivt Hordens fred inifrån.",al={"thralls dolda fiender","vilka är de dolda fienderna","vad är de dolda fienderna"}},["606e7173"]={q="Varför finns det demoner under Orgrimmar?",a="Searing Blades kultister förde demoner som Taragaman the Hungerer ner i djupet för att förankra sina mörka ritualer. De lurar under The Cleft of Shadow och använder demonisk kraft för att locka oförsiktiga invånare och pröva dem som vill tjäna den brinnande legionen.",al={"demoner i ragefire chasm","varför finns det demoner under orgrimmar","taragaman i rfc"}},["0ca922e2"]={q="Vad är Shadow Council?",a="Shadow Council var en hemlighetsfull sammanslutning av trollkarlar som Gul'dan ursprungligen bildade på Draenor för att manipulera orc-klanerna och binda dem till den brinnande legionen. Rester av sekter som Burning Blade fortsätter att arbeta för sina demoniska herrars mål, trots att rådet krossades under det första och andra kriget.",al={"shadow councils bakgrund","vad är shadow council","shadow councils historia"}},be4be4e7={q="Vad är Ragefire-troggarna?",a="Ragefire-troggarna är en våldsam, underjordisk klan av primitiva troggar som hemsöker de övre delarna av klyftan. De är barbariska och aggressiva och strömmar in i grottorna genom underjordiska sprickor för att genast angripa alla som kommer in på deras revir.",al={"ragefire-troggar","vad är troggarna i rfc","rfc-troggar"}},["608f7b0a"]={q="Varför jag? Jag är väl inte direkt någon hjälte än?",a="Thrall kan inte sätta in sina elitvakter ur Kor'kron utan att oroa konspiratörerna och driva dem längre ner under jorden. Genom att anlita ivriga nya äventyrare kan han slå till i tysthet och förneka inblandning, slå ut kultens närmaste löjtnanter och samtidigt hålla sina egna motutredningar diskreta.",al={"varför skickades jag till rfc","varför skicka en äventyrare till ragefire","varför jag i ragefire"}},cbc9ae06={q="Vad händer efter att jag dödat trollkarlen och satyren?",a="När Jergosh the Invoker och Bazzalan har fallit har deras planer i klyftan slagits i spillror. Du rapporterar din seger till Thrall, som bekräftar att det finns ett större nät av förräderi som sträcker sig bortom grottorna och upp till ytan.",al={"efter att ha dödat bazzalan och jergosh","nästa steg efter att ha dödat jergosh","vad ska jag göra efter rfc"}},e02585d8={q="Leder det här tillbaka till Thrall?",a="Ja. Thrall förväntar sig att du rapporterar direkt till hans tronrum i Visdomens dal. När du dödar kultens fältmästare bevisar du din lojalitet och ger krigschefen en bild av hur omfattande omstörtningen är, mitt under hans fötter.",al={"leder rfc tillbaka till thrall","återvänd till thrall efter rfc","rapportera till thrall"}},["02870934"]={q="Hur hamnade jag i Ragefire Chasm?",a="Du tog dig ner genom de skuggiga tunnlarna under Orgrimmar till The Cleft of Shadow, där stadens utstötta och mörkare utövare samlas. Bredvid trollkarlen Neeru Fireblades tält ligger klyftans djupaste tröskel: en rykande valvbåge som leder rakt ner i Durotars vulkaniska underjord. Vare sig krigschef Thrall skickade dig hit för att jaga dolda förrädare, tauren-sändebud från Thunder Bluff sände dig eller mörka viskningar ledde dig ner för att pröva din styrka, gick du genom porten till de underjordiska magmatunnlarna.",al={"hur hamnade jag här","hur kom jag till ragefire chasm","varför är jag i de här grottorna"}},["9382a7ef"]={q="Vad ska jag göra i Ragefire Chasm?",a="Du är här för att rensa bort en ruttenhet som hotar Hordens hjärta. I dessa vulkangrottor har vilda troggar klöst sig upp ur djupet, förkastat freden med våld och slaktat sändebud. Än värre smider Searing Blade, en hemlig utbrytargrupp ur det demoniska Shadow Council, planer på att förgöra Orgrimmar i mörkret. Din uppgift är att kämpa dig genom troggarna, möta den väldige felvakten Taragaman the Hungerer och undanröja kultens dödliga befälhavare, Jergosh the Invoker och satyren Bazzalan. Då krossar du deras underjordiska nätverk innan det svämmar över och hotar staden ovanför.",al={"vad gör jag här","vad är mitt mål i ragefire","varför skickades jag ner hit"}}},fp="14,165,18.299.0,17.349.0,19.465.1,40.152.0,31.176.0,40.138.0,64.199.1,46.186.0,50.149.1"}
P.entries["zone:razorfenkraul"] = {n="Razorfen Kraul",s="Långt söderut i The Barrens ligger Razorfen Kraul, quilboarens urgamla kärnland i Kalimdor. Dessa vilda stammar vördar den täta labyrinten av jättelika törnbuskar som den heliga viloplatsen för sin stamfader, halvguden Agamaggan, som föll i strid. I dag har Kraul blivit allt fientligare under quilboarmatriarken Charlga Razorflanks tyranni, och hennes mörka förehavanden hotar hela regionen.",h="Långt söderut i The Barrens ligger Razorfen Kraul, quilboarens urgamla kärnland i Kalimdor.",kw={"agamaggan","the barrens","charlga","halmgar","kraul","quilboar","ramtusk","razorfen","razorflank","scourge"},ang={["class:Shaman"]="Quilboarernas geomanti förvrider jorden och elementen kring Agamaggans blod och visar tydligt hur primitiva schamankrafter används med vilda avsikter.",["faction:Horde"]="Det är nödvändigt att hejda Kraulbornas aggression för att skydda försörjningsvagnar och nya bosättningar över de vidsträckta södra delarna av The Barrens.",["race:Tauren"]="Quilboarerna har länge kämpat om gränserna mot Mulgore, och deras vanhelgande av jorden genom mörka allianser gör renandet av Kraul till en viktig fråga om stamförsvar.",["race:Undead"]="Apotekare från Undercity intresserar sig särskilt för de märkliga reagenserna, fladdermusguanon och ryktena om Scourge-intrång som förekommer bland törnbuskarna."},sec={{t="Vildsvinsgudens blod",b="För tiotusen år sedan, under det apokalyptiska War of the Ancients, kastade sig den väldige vildguden Agamaggan in i striden mot Burning Legion. Det stora vildsvinet stupade till slut i strid, men hans offer räddade liv på Azeroth. Legender berättar att där hans blod trängde ner i jorden sköt väldiga, törnbeklädda rankor upp och bildade täta, försvarbara labyrinter över de södra slätterna. Quilboarfolket, som vördar Agamaggan som sin gudomliga förfader, gjorde anspråk på dessa väldiga snår som sina heliga marker och grundade Razorfen i det största av dem."},{t="Häxans ambition",b="Razorfen Kraul styrs med hård hand av den åldriga häxan Charlga Razorflank. Under hennes despotiska ledning har de schamanistiska quilboarerna övergett sina traditionella gränsstrider för att föra ett aggressivt, samordnat krig mot rivaliserande stammar, regionala handelsvägar och unga Horde-bosättningar. Än värre är att oroande viskningar och spejarrapporter berättar om odöda vid törnbuskarna. Man fruktar att Charlga har börjat förhandla med utsända från den fruktade Scourge och söker utnyttja förbjuden nekromanti för att stärka sin stams vildhet."}},faq={{q="Vad är Razorfen Kraul?",a="Razorfen Kraul är ett urgammalt underjordiskt nätverk av väldiga, taggiga rankor i södra The Barrens. Det är quilboarfolkets andliga kärnland och fäste. De betraktar den trassliga labyrinten som sitt förfädershem.",al={"vad är rfk","förklara razorfen kraul","översikt över razorfen"}},{q="Hur skapades de jättelika törnbuskarna?",a="De väldiga törnbuskarna sköt upp ur jorden för tiotusen år sedan under War of the Ancients, direkt ur blodet från halvguden Agamaggan, som stupat i strid.",al={"varför finns det jättelika törnbuskar","varifrån kommer törnbuskarna","agamaggan törnbuskar"}},{q="Vem styr Razorfen Kraul?",a="Kraul styrs av Charlga Razorflank, en skoningslös quilboarhäxa och schaman som leder Razorfen-stammen och organiserar attacker mot närliggande byar och resande.",al={"vem är bossen i rfk","charlga razorflank","häxan i kraul"}},{q="Varför oroar sig Horde för Razorfen Kraul?",a="Förutom quilboarernas ständiga räder mot nya bosättningar i The Barrens har Horde-spejare sett odöda smyga omkring i snåren. Det väcker skrämmande farhågor om att Charlga samarbetar med Scourge.",al={"varför bryr sig horde","hordes intresse för rfk","hot i the barrens"}},{q="Varför intresserar sig Alliance-styrkor för Kraul?",a="Charlgas stam expanderar aggressivt och hotar utposter nära Feralas och Thousand Needles. Därför försöker Alliance-befälhavare och spejare vid Thalanaar få häxan undanröjd för att säkra gränsen.",al={"alliance-uppdrag i rfk","varför tar sig alliance hit","thalanaar-uppdrag"}},{q="Vad innebär det för berättelsen att besegra Earthcaller Halmgar?",a="Att besegra Earthcaller Halmgar, en ovanlig och inflytelserik geomant djupt inne i snåren, blir ett slag mot quilboarernas prästerskap, som formar jorden. När Kraul berövas så mäktiga elementbesvärjare försvagas Charlga Razorflanks försvarsverk och quilboarernas förmåga att styra Agamaggans heliga törnbuskar hämmas.",al={"vad händer när earthcaller halmgar dör","earthcaller halmgars historia","halmgar besegrad"}}},fx={["59c8bcc4"]={q="Vem byggde alla törnen i Razorfen Kraul?",a="Ingen byggde dem för hand. För tiotusen år sedan, under de uråldriga krigens tid, föll den kolossale galtsemiguden Agamaggan i strid mot den brinnande legionen. Där hans gudomliga blod dränkte jorden bröt väldiga, ogenomträngliga törnbuskar fram ur marken och bildade det labyrintiska snår du ser i dag.",al={"vem skapade törnena","vem byggde törnena","törnenas ursprung i razorfen kraul"}},["4843f165"]={q="Vad är quilboar?",a="Quilboar är primitiva, aggressiva, galtlika humanoider som hör hemma på Kalimdor. De har muskulösa, kutryggiga kroppar som är täckta av vassa, skyddande taggar. De tros vara halvguden Agamaggans dödliga avkomma, vördar hans viloplatser och försvarar sina taggiga revir våldsamt mot alla utomstående.",al={"vad är quilboar","vilka är quilboar","quilboars bakgrund"}},ea4583b3={q="Varför lever quilboar i en enorm törnelabyrint?",a="Törnelabyrinten växte upp direkt ur blodet från deras fallna gud Agamaggan. För quilboar är Razorfen helig mark och hans verkliga viloplats. Snåren inger dem både helig vördnad och naturliga, nästan ointagliga fästningar mot fienderna i trakten.",al={"varför bo bland törnen","varför bor quilboar här","quilboars törnelabyrint"}},b1fd1d2b={q="Är Charlga Razorflank ledare för alla quilboar?",a="Inte för alla quilboar, men hon härskar över den mäktiga Razorfen-stammen, som har slagit sig ner i Kraul. Den listiga häxan och geomantikern drev bort de lokala tauren från södra Barrens och har stor makt, även om rivaliserande quilboar-stammar utspridda över Kalimdor styr sig själva.",al={"charlga razorflank ledare","vem leder alla quilboar","styr charlga över alla"}},["8ed48c28"]={q="Vem är Agathelos the Raging?",a="Agathelos är ett enormt, vildsint vildsvin som bor i Razorfen Kraul. Quilboar vördar vildsvin som levande symboler för sin gud Agamaggan och ser särskilt stora och uthålliga djur som Agathelos som direkta välsignelser och heliga uttryck för den Store Galten urkraft.",al={"vem är agathelos","agathelos the raging historia","agathelos jättelikt vildsvin"}},["4f663063"]={q="Ränner Horde också runt i Razorfen Kraul?",a="Ja. Charlga Razorflanks rövare genomför ständigt brutala angrepp mot Horde-bosättningar i hela Barrens och drev bort tauren från deras förfäders marker i söder. Både orcherna och tauren skickar aktivt krigare för att bryta häxans makt och få slut på hotet från quilboar.",al={"är horde här","hordes närvaro i razorfen","horde i razorfen kraul"}},["5328604f"]={q="Vem är Agamaggan?",a="Agamaggan den Store Galten var en forntida väktare och en av de första och mäktigaste vilda gudarna som vandrade på Azeroth. Quilboar vördar honom som sin skapare och dyrkar hans minne. De hämtar andlig och geomantisk kraft ur hans blod och de väldiga törnesnår som föddes ur hans offer.",al={"vem är agamaggan","agamaggan den store galten","agamaggan historia"}},bc4e6730={q="Dog Agamaggan under War of the Ancients?",a="Ja. För tiotusen år sedan hörsammade Agamaggan Cenarius uppmaning att försvara Azeroth mot Burning Legion. Han härjade över kontinenten och krossade tusentals demoner innan han till slut föll i strid mot överväldigande demoniska legioner. Han offrade sitt liv så att Malfurion Stormrage kunde nå Well of Eternity.",al={"hur dog agamaggan","agamaggan under war of the ancients","dog agamaggan"}},e47b7687={q="Dyrkar quilboar fortfarande Agamaggan?",a="Ja, med fanatisk hängivenhet. Quilboar-schamaner och geomantiker ber Agamaggan om styrka i strid, vördar jättelika vildsvin som hans välsignelser och samlar på Blood Shards av hans förstenade blod. De tror att hans fysiska kvarlevor skyddar dem och deras heliga hem.",al={"dyrkar quilboar fortfarande agamaggan","quilboars religion","dyrkan av agamaggan"}},["7583b13a"]={q="Vad är Death's Head-gänget?",a="Death's Head är en militant quilboar-fraktion som leds i strid av Overlord Ramtusk och verkar sida vid sida med Razorfen-stammen. Ramtusk använder sina disciplinerade, stridsvana trupper för att hålla ett järngrepp om törnelabyrinten och föra grymma krig mot grannarna.",al={"death's head-stammen","vilka är death's head","death's head-quilboar"}},["4bc36485"]={q="Kommer quilboar här att anfalla bosättningarna i Barrens?",a="Det gör de redan. Under häxan Charlga Razorflanks ledning sveper aggressiva rövarband ständigt ut ur snåren och in i de omgivande områdena. De har trakasserat resenärer nära The Great Lift, angripit rivaliserande stammar och drivit Horde-bosättningar och karavaner till randen av öppet krig.",al={"kommer quilboar anfalla barrens","quilboar anfaller barrens","quilboar-räder i barrens"}},ed4c33ec={q="Vad är skillnaden mellan Kraul och Downs?",a="Båda är enorma törnenätverk som uppstod när Agamaggan föll, men de har olika uppgifter. Razorfen Kraul är förfädernas hjärta, där Charlga Razorflank samlar levande quilboar-rövare. Razorfen Downs, längre åt sydost nära halvgudens väldiga käftben, har hamnat under Scourges mörkare inflytande.",al={"skillnaden mellan kraul och downs","razorfen kraul eller downs","kraul eller downs"}},["974f5634"]={q="Är Scourge inblandad i Razorfen?",a="Ja. Oroväckande rapporter och beslagtagna meddelanden visar att Charlga Razorflank har börjat förhandla med Scourges agenter. Spanare har sett odöda rycka fram nära Razorfen, vilket väcker allvarlig oro för att Lich Kings undersåtar försöker få fotfäste på Kalimdor genom dessa ovetande stammar.",al={"scourge i razorfen","finns det odöda i razorfen","scourges närvaro i kraul"}},a384c7af={q="Vem är Amnennar?",a="Amnennar the Coldbringer är en mäktig agent för Scourge som har etablerat sig i närliggande Razorfen Downs. I det fördolda manipulerar han quilboar-ledarna och befaller Death's Head-styrkorna att förvandla de södra snåren till ett fäste för odöda.",al={"vem är amnennar","amnennar the coldbringer","amnennars historia"}},af015f4e={q="Hur hamnade jag i Razorfen Kraul?",a="Du reste till Barrens sydligaste utmarker, nära de höga klipporna med utsikt över Thousand Needles. Genom det omstridda busklandet fann du det väldiga snår av blodnärda törnen som växte fram ur den forntida galtguden Agamaggans lik. Den västra ingången till Kraul är uthuggen direkt i dessa enorma, förstenade törnrankor. Quilboar-försvarare vaktar vägen mot alla som vågar tränga in på deras heliga område.",al={"hur kom jag hit","hur når man razorfen kraul","var ligger razorfen kraul"}},["141f6ea5"]={q="Vad ska jag göra i Razorfen Kraul?",a="Du är här för att bryta Razorfen-stammens fientliga makt och hejda dess aggressiva expansion över Barrens. Under häxan Charlga Razorflanks ledning har dessa fanatiska quilboar trappat upp sina våldsamma angrepp mot närliggande bosättningar och karavaner. Ditt mål är att kämpa dig genom de slingrande törnpassagerna, slå ut Death's Head-ledningen och fälla Charlga innan hennes mörka geomantik och misstänkta kontakter med ondskefulla odöda styrkor utlöser ett fullskaligt krig.",al={"vad är mitt uppdrag här","varför är jag i razorfen kraul","vad gör jag här"}}},fp="14,218,21.427.0,20.423.1,23.142.0,34.156.0,25.170.0,48.182.0,48.157.0,59.248.0"}
P.entries["zone:redridge"] = {n="Redridge Mountains",s="Öster om Elwynn Forest breder Redridge Mountains ut sig med strömmande floder, skogsklädda sluttningar och Lake Everstills stilla vatten. Trots de natursköna höjderna hemsöks trakten av fientliga Shadowhide-kobolder och Blackrock-orcher från Dark Horde, som tränger allt närmare. Med kungarikets trupper upptagna av inre stridigheter i Stormwind måste Lakeshire, staden vid sjön, förlita sig på kringvandrande legosoldater för att hålla stånd.",h="Öster om Elwynn Forest breder Redridge Mountains ut sig med strömmande floder, skogsklädda sluttningar och...",kw={"blackrock-orcher","lake everstill","lakeshire","magistrate solomon","marshal marris","redridge","redridge mountains","render's valley","shadowhide","stonewatch","stonewatch keep","verner osgood"},ang={["faction:Alliance"]="Lakeshire är en viktig utpost vid frontlinjen där unga soldater från Alliansen finslipar sina färdigheter mot organiserade styrkor av orcher och kobolder.",["faction:Horde"]="Blackrock-orcherna som slagit sig ner i Redridge tillhör den fientliga Dark Horde och är därmed lika mycket fiender till Thralls Horde som till människorna i Lakeshire.",["profession:Herbalism"]="De tempererade bergssluttningarna ger goda växtförhållanden för Briarthorn, Bruiseweed, Mageroyal och Swiftthistle.",["profession:Mining"]="De klippiga branterna och dalarna runt Lake Everstill bjuder på gott om koppar- och tennfyndigheter samt sällsynta silverådror, särskilt nära Rethban Caverns."},sec={{t="En belägrad bastion",b="Redridge-bergen var en gång ett av kungarikets fredligaste hörn och försåg Stormwind med timmer, sötvattensfisk och grödor. I dag har det lugna livet vittrat bort. Staden Lakeshire vid sjön är ständigt befäst mot fientliga intrång. I öster har Stonewatch Keep, en gång en stolt bastion för kungariket, fallit i händerna på förrädiska Blackrock-orcher, som skär av vägar och hotar att helt ta över de östra dalarna."},{t="Det delade bergslandet",b="Geografiskt utgör dessa berg en del av bergsryggen som löper längs Azeroths subkontinent. För århundraden sedan sträckte sig bergskedjan mycket längre norrut, tills Dark Iron-klanen av misstag åkallade eldherren Ragnaros. Marken slets sönder och den glödande kratern Blackrock Mountain bildades. Katastrofen skilde de norra topparna från bergen och förvandlade dem till de askfyllda Burning Steppes. Kvar blev bara de södra dalarna i Redridge, lummiga, gröna och sårbara för angrepp från sluttningarna ovanför."},{t="Övergivna av kronan",b="Magistrate Solomon och Marshal Marris vädjar om förstärkningar, men regentrådet i Stormwind har i praktiken lämnat Lakeshire åt sitt öde. Desperata vädjanden till Sentinel Hill och Darkshire leder ingenstans, eftersom båda systerbosättningarna är lamslagna av sina egna kriser. När inga förstärkningar syns till måste de lokala magistraterna anlita varje duglig svärdskämpe som vågar sig längs Lakeridge Highway, rensa koboldlägren och driva tillbaka hotet över Lake Everstill."},{t="Dolda lojaliteter",b="Den förrädiske häxmästaren Morganth slöt först förbund med Blackrock-orcherna för att ta Stonewatch Keep. Sedan förrådde han dem och band Shadowhide-kobolderna till sin tjänst från Tower of Ilgalar. Rapporter som återfanns under utredningen av Blackrock avslöjar också en allians mellan orcherna och den svarta drakflykten."}},faq={{q="Varför skickar inte Stormwind soldater för att hjälpa Lakeshire?",a="Lakeshires kvarvarande kungliga soldater är kraftigt underlägsna efter förlusten av Stonewatch Keep. Magistrate Solomon har bett om trupper, vapen, mat och förnödenheter, men Stormwinds styrkor är hårt ansatta och grannbosättningarna har egna problem. Därför förlitar sig garnisonen på äventyrare som hjälper till att försvara trakten.",al={"varför finns inga vakter från stormwind","varför är redridge övergivet","var är stormwinds armé"}},{q="Vem kontrollerar Stonewatch Keep?",a="Stonewatch Keep har intagits av Blackrock-orcher som tillhör Dark Horde. Från detta befästa fäste i bergen hotar de de östra dalarna och resande längs Lakeridge Highway. Deras förhållanden till andra lokala hot undersöks under utredningen.",al={"vilka finns i stonewatch","stonewatchs fiender","vad hände med stonewatch"}},{q="Vilka faror döljer sig i Lake Everstill?",a="Lake Everstill verkar fridfull från strandkanten, men vattnet är fullt av fientliga murlocstammar som plundrar bryggorna och ruinerna i närheten. Den som simmar måste också se upp för rovlystna threshadoner under ytan, vilket har gett upphov till envisa rykten om vattenmonster som stryker omkring i djupet.",al={"monster i lake everstill","faror i redridge-sjön","murlocer i everstill"}},{q="Finns det några utposter för Horde i Redridge?",a="Nej. I Redridge Mountains finns inga bosättningar, försäljare eller flygpunkter för Horde. Resande från Horde som passerar genom området är vanligen på väg mellan Burning Steppes i norr och Swamp of Sorrows i sydöst, genom allianskontrollerade vägar och fientlig vildmark.",al={"horde-städer i redridge","är redridge horde eller alliansen","hordes flygpunkt i redridge"}},{q="Vad är Three Corners?",a="Three Corners är en viktig vägkorsning i Redridges sydvästra hörn. Den knyter samman Lakeridge Highway med den östra gränsen till Elwynn Forest och vägen mot Duskwood. Därför är den en oumbärlig knutpunkt som ofta utsätts för angrepp från kringvandrande kobolder och vilda bestar.",al={"three corners","three corners vägkorsning","redridge vägkorsning"}},{q="Varför är den norra vägen till Burning Steppes så farlig?",a="Stigen norrut förbi Render's Camp klättrar rakt upp i Burning Steppes, en karg vulkanisk ödemark som domineras av mäktiga Blackrock-orcher, eldelementaler och drakfolk. Den plötsliga faran gör det norra bergspasset till en av de dödligaste stigningarna i södra Azeroth.",al={"redridges norra väg","gränsen mellan burning steppes och redridge","redridges norra bergspass"}}},fx={["85c0e73f"]={q="Vad är Redridge Mountains?",a="Redridge Mountains är ett högt beläget, naturskönt område öster om Elwynn Forest och söder om Burning Steppes. Med sina strida floder, höga almar och glittrande Lake Everstill ansågs det länge vara ett av de fredligare områdena i södra Azeroth. I dag har dess fridfulla skönhet slagits i spillror av invaderande Blackrock-orcher, våldsamma gnoll och fientliga sjömurlocker.",al={"vad är redridge","redridge mountains-område","berätta om redridge"}},["5d244582"]={q="Tillhör Redridge Stormwinds kungarike?",a="Ja, Redridge ligger under kungariket Stormwinds beskydd och styre, men sedan Andra kriget har de lokala ledarna i stort sett skött vardagsärendena själva. Magistrate Solomon i Lakeshire vädjar fortfarande formellt till Stormwinds tron om försvar och förlitar sig på handel med Alliansen och ömsesidig lojalitet, även när kungliga trupper inte syns till.",al={"tillhör redridge stormwind","tillhör redridge alliansen","tillhör lakeshire stormwind"}},["8563150d"]={q="Varför finns det en sjö mitt i Redridge?",a="Lake Everstill samlar naturligt upp vattnet från de omgivande bergskedjorna. Sjöns klara, stilla vatten gav en gång Lakeshire rikligt med fisk och rent vatten, men på senare tid har den invaderats av våldsamma murlockstammar och patrulleras av lurande tröskardjur under ytan.",al={"varför finns lake everstill","redridge-sjöns ursprung","vad är sjön i redridge"}},["8de34bfa"]={q="Vad hände i Redridge Mountains?",a="Redridge var en gång en fridfull vagga för mänskliga gårdar, fram till Första kriget. Då besegrade Warchief Blackhand och Shadow Councils häxmästare riddarna under Sir Anduin Lothar och drev människorna i landsflykt. Alliansen återtog och återuppbyggde området efter Andra kriget. På senare tid har det åter belägrats sedan Blackrock-orcher trängde ner från bergen och intog Stonewatch Keep.",al={"redridges historia","vad hände i redridge","redridge under första kriget"}},bf444872={q="Är Redridge Mountains farligt?",a="Trots sitt idylliska utseende är Redridge oerhört farligt. Blackrock-orcher kontrollerar de östra ravinerna och fästet, Shadowhide-gnoll plundrar skogarna och murlocker svärmar längs sjöstränderna. Till och med den norra vägen gränsar till Burning Steppes brännande toppar, där fasor långt bortom vad en vanlig patrull kan hantera lurar strax bortom bergspassen.",al={"är redridge säkert","hur farligt är redridge"}},["1cc45818"]={q="Varför är alla i Lakeshire så oroliga?",a="Lakeshire är under pågående belägring. Blackrock-orcherna har intagit Stonewatch Keep på andra sidan sjön, Shadowhide-gnoll pressar staden från kullarna och murlocker angriper vattenvägarna. Bron är förstörd och inga förstärkningar kommer från Stormwind. Stadsborna fruktar att ett fullskaligt angrepp kan utplåna dem när som helst.",al={"varför är lakeshire rädd","hot mot lakeshire","varför är man orolig i lakeshire"}},["851f5e81"]={q="Är Lakeshire på väg att falla?",a="Utan hjälp utifrån ser Lakeshires läge mörkt ut. Den lokala stadsvakten är vida underlägsen orkrövare, gnollflockar och sjöodjur. Deras fäste i Stonewatch blev lätt översvämmat, och Lakeshires försvarare har drivits tillbaka till sjöns västra strand. De håller nätt och jämnt en försvarslinje längs den trasiga bron.",al={"kommer lakeshire att falla","är lakeshire dödsdömt","kan lakeshire överleva"}},["7ced12b0"]={q="Har Stormwind skickat hjälp till Lakeshire?",a="Lakeshire har vädjat om hjälp till Stormwind, Westfall och Darkshire, men grannbosättningarna är upptagna med sina egna kriser. General Marcus Jonathan har också ombetts skicka förstärkningar. De kungliga soldater som fortfarande försvarar Lakeshire saknar både trupper och förnödenheter efter Stonewatch Keeps fall.",al={"hjälpte stormwind lakeshire","stormwinds hjälp till lakeshire","har stormwind skickat trupper till redridge"}},["3a3ab87f"]={q="Vem bestämmer här omkring?",a="Lakeshire styrs av Magistrate Solomon, som sköter civila frågor och stadens angelägenheter från Lakeshire Town Hall. Militär- och försvarsinsatser leds av Marshal Marris, som styr den lokala vakten och samordnar försvaret nära bron.",al={"vem leder redridge","vem styr lakeshire","ledare i redridge"}},["1dd15680"]={q="Vem är Magistrate Solomon?",a="Magistrate Solomon är Lakeshires valde ledare och överdomare i Court of Lakeshire. Han är gammal och utmattad och bär ansvaret för att hålla staden försörjd, organiserad och politiskt knuten till kungariket, samtidigt som han desperat vädjar till utländska och regionala ledare om militär hjälp.",al={"magistrate solomon","vem är solomon","solomon i redridge"}},["0e63cf14"]={q="Lyder Marshal Marris under Magistrate Solomon?",a="Ja. Solomon företräder kungarikets civila myndighet och domstol i Lakeshire, medan Marshal Marris för befälet över Stormwind Guards förband där. De samarbetar nära. Solomon sköter diplomatin och stadens överlevnad, medan Marris hanterar taktiska skärmytslingar och truppförflyttningar.",al={"rapporterar marris till solomon","marshal marris och solomons rang","vem har högst rang i lakeshire"}},["7b7fd7c0"]={q="Vilka är Blackrock-orcherna, och varför är de i Redridge?",a="Blackrock-klanen är en hänsynslös rest av den gamla Horden, med bas i Blackrock Mountain i norr. Till skillnad från Thralls Horde i Kalimdor avvisar dessa utbrytare all fred med Alliansen. De har tågat ner från Burning Steppes till Redridge för att erövra området och använder Stonewatch Keep som bas för att krossa Lakeshire.",al={"blackrock-orcher i redridge","varför är orcher i redridge","vilka är blackrock-klanen i redridge"}},["114fb915"]={q="Varifrån kom Blackrock-orcherna?",a="De marscherade söderut genom de karga norra bergspassen, direkt från Burning Steppes och Blackrock Spire, deras forntida fästning från det andra kriget. De upprättade framskjutna utposter som Render's Camp innan de övermannade Stonewatch Keep.",al={"varifrån kom redridges orcher","blackrock-orchernas ursprung","varifrån kommer orcherna"}},["9f02e3ae"]={q="Är Blackrock-orcherna samma orcher som i krigen?",a="Ja. De är hårdföra veteraner och direkta ättlingar till Blackrock-klanen från det första och andra kriget, som vägrade kapitulera eller följa Thralls nya schamanistiska väg. De håller fast vid sina ursprungliga blodtörstiga seder och sin mörka magi, och deras ursprungliga mål är fortfarande att utplåna människorikena.",al={"är blackrock-orcherna från det första kriget","blackrock-orcher från det andra kriget","är det här samma orcher från de gamla krigen"}},["09fb7c4a"]={q="Vilka är Redridges gnoller? Varför anfaller de?",a="De lokala Shadowhide-gnollerna är vilda, hyenaliknande humanoider som lever i Redridges kullar och dalar. De är naturligt revirhävdande rovdjur, men deras samordnade våldsamhet drivs nu av mörka krafter. De har enat de utspridda flockarna till en organiserad armé som vill slakta mänskliga bosättningar.",al={"gnoller i redridge","varför anfaller gnollerna redridge","shadowhide-gnoller"}},ba7471d2={q="Samarbetar gnollerna med orcherna?",a="Shadowhide-gnollerna tjänar den förrymde häxmästaren Morganth i Tower of Ilgalar. Deras relation till Blackrock-orcherna kan undersökas med hjälp av rapporter som hittas i området.",al={"allierade gnoller och orcher","arbetar gnollerna för blackrock","samarbetar orcher och gnoller"}},["74e139ea"]={q="Vem är Yowler?",a="Yowler är ledare för Redridges gnoller. Han håller till i kullarna ovanför Lakeshire och hetsar flocken mot staden. Verner Osgood ber äventyrare att besegra honom och ta med hans tass tillbaka.",al={"vem är yowler","yowler, gnollernas ledare","yowler i redridge"}},b25dfaa0={q="Varför är Everstill Bridge trasig, och varför spelar det roll?",a="Everstill Bridge är svårt skadad. Den är mycket viktig eftersom den sträcker sig över Lake Everstills smala näs och är Lakeshires främsta transportförbindelse till den östra stranden och Stonewatch. Förstörelsen hämmar stadens handel och försvar och försvårar en motattack mot fiendens läger.",al={"trasiga everstill bridge","varför är bron i lakeshire trasig","trasig bro i redridge"}},b35f81a4={q="Varför har inte Stormwind reparerat Everstill Bridge?",a="Stormwind har inte skickat några pengar, förnödenheter eller murare för att hjälpa till. Ansvaret har helt fallit på lokala arbetare under ledning av Foreman Oslow. Deras reparationsarbete avbryts och saboteras ständigt av murlocräder och förlorade förnödenheter.",al={"varför har bron inte reparerats","stormwind reparerar bron i lakeshire","vem reparerar bron"}},["834d2ea2"]={q="Varför finns det svarta drakungar i Redridge?",a="Svarta drakungar har strömmat ner genom passen från Burning Steppes och angripit Lakeridge Highway och de södra ravinerna. De stryker omkring på de klippiga åsarna, spanar in området och jagar förbipasserande. De är en olycksbådande varning om att Deathwings yngel är aktivt i närheten.",al={"drakungar i redridge","svarta drakar i redridge","varför finns drakungar i redridge"}},ce7dd1a7={q="Samarbetar drakarna med orcherna?",a="Lakeshire oroas av att Blackrock blir allt mäktigare och att svarta drakungar har siktats. Magistrate Solomon ber resande att framföra hans oro till Highlord Bolvar Fordragon. Ytterligare undersökningar avslöjar hotets natur.",al={"är svarta drakar allierade med blackrock","allians mellan orcher och drakar","samarbetar blackrock-orcher med drakar"}},["7d7bd3f8"]={q="Varför är det en äventyrare som slåss här i stället för vakterna?",a="Lakeshires vakter är helt upptagna med att försvara stadens försvarslinje, så ingen kan skickas ut på anfall. Förstärkningarna som begärts har ännu inte kommit. Magistrate Solomon och Marshal Marris har inget val än att anlita resande äventyrare för att driva tillbaka orcherna, minska gnollernas antal och säkra landsvägen.",al={"varför gör jag det här i redridge","varför äventyrare i redridge","var är vakterna i redridge"}},["839c7682"]={q="Var är Stormwinds armé?",a="Stormwinds styrkor är hårt ansträngda. Kungliga soldater finns fortfarande kvar i Lakeshire efter nederlaget vid Stonewatch Keep, men stadens upprepade begäran om nya trupper och förnödenheter har inte gett försvararna de förstärkningar de behöver.",al={"var är stormwinds soldater","varför finns ingen stormwind-armé","var är stormwinds armé"}},de572e98={q="Hur hamnade jag i Redridge Mountains?",a="Du följde förmodligen vägarna österut från Elwynn Forest genom vägskälet Three Corners, eller tog dig över floden från Duskwoods mörka skogar i sydväst. Som en ung förkämpe som hjälper människornas länder leder dina resor naturligt hit när problemen kring Stormwind kräver mer erfarna händer. Lakeshires nödrop når grannområdena och lockar resande äventyrare upp längs Lakeridge Highway till dessa härjade höjder.",al={"hur hamnade jag här","hur kom jag till redridge","varför kom jag till redridge"}},d1ce2561={q="Vad förväntas jag göra i Redridge Mountains?",a="Lakeshire är i desperat nöd och har i praktiken övergivits av kronan. Du är här för att besvara Magistrate Solomons och Marshal Marris vädjanden om hjälp med försvaret. Staden pressas hårt av våldsamma Shadowhide-gnoller längs vägarna och skoningslösa Blackrock-orcher som har intagit Stonewatch Keep. Den kungliga garnisonen är underlägsen i antal och Everstill Bridge är sönderslagen. Du måste slå tillbaka gnollerna, driva bort orchernas förtrupp och hindra denna fridfulla tillflyktsort vid sjön från att falla samman helt.",al={"vad gör jag här","varför är jag här","vad är mitt mål i redridge","vad är mitt uppdrag här"}}},fp="18,271,21.379.0,17.453.0,22.430.0,22.309.1,52.324.0,29.235.0,37.186.0,41.258.0,26.229.0,60.279.0"}
P.entries["zone:riverglades"] = {n="Riverglades",s="Riverglades är en omstridd floddal öster om Burning Steppes och Badlands, som historiskt har gjort anspråk pås av Stormwinds kungarike. Regionen översvämmades av den gamla horden under det första kriget och övergavs till stor del av kronan, men är fortfarande ett slagfält där lokala mänskliga lojalister drabbar samman med Hordens moderna utposter och det lokala djurlivet. Den gränsar till Redridge Mountains i sydväst och Swamp of Sorrows i söder, och vetter mot Tanaris på andra sidan havet.",h="Riverglades är en omstridd floddal öster om Burning Steppes och Badlands, som historiskt har gjort anspråk...",kw={"blackrock pass","brotherhood of the horse","demar brant","farholde keep","krol'dok stronghold","powderfuse port","redridge pass","riverglades","rog'mar","sunnyglade"},ang={["faction:Alliance"]="Alliansens soldater ser gamla sår rivas upp i Riverglades, där resterna av Brotherhood of the Horse fortsätter ett obemärkt korståg för att återta mark som Stormwind övergav under det första kriget.",["faction:Horde"]="För Horden innebär utposter som Rog'mar en säker kustnära bas och ett fortsatt tryck mot de gamla mänskliga fästena som finns kvar öster om Redridge.",["race:Human"]="Mänskliga resenärer möter ett tragiskt kapitel i sitt eget arv i Sunnyglade, en påminnelse om det första krigets höga pris vid kungarikets östra gräns."},sec={{t="Ett glömt gränsland",b="Riverglades var historiskt en del av Stormwinds kungarike, men föll i ruiner under det första kriget när den gamla horden svepte genom regionen. Dess centrala bosättning, Sunnyglade, plundrades av orcherna, som skonade dess magitorn enbart för att studera mänsklig magi innan de förslavade de överlevande stadsborna. Stormwinds soldater försökte befria fångarna och återuppbygga området, men kungariket beslutade till slut att hela dalen var förlorad och styrde om resurserna till försvaret av kärnlandet. Under många år förblev regionen i stort sett avskuren från formellt stöd från kronan."},{t="Kampen om Farholde",b="Trots att Stormwinds högsta ledning övergav dem gav de mänskliga försvararna aldrig helt upp sitt hemland. Under ledning av riddarkommendör Demar Brant från det legendariska Brotherhood of the Horse håller de återstående lojalistiska styrkorna Farholde Keep som ett bålverk mot vildmarken och fientliga inkräktare. Samtidigt upprätthåller den moderna horden en stark närvaro i närheten, med utposter som Rog'mar och Bolder'ok, vilket ser till att den uråldriga konflikten om gläntorna fortsätter att pyra."},{t="Geografi och färdvägar",b="Riverglades sträcker sig längs kusten vid Forbidding Sea och omges av bergig terräng och slingrande vattenvägar. Resenärer till fots kan ta sig västerut genom Blackrock Pass till Burning Steppes, slingra sig sydväst genom Redridge Pass mot Redridge Mountains, färdas söderut in i Swamp of Sorrows eller vandra nordväst förbi Twilight's Shroud till Badlands. Vid kusten erbjuder Powderfuse Port sjövägen över havet direkt till Steamwheedle Port i Tanaris."}},faq={{q="Vad är Riverglades?",a="Riverglades är en omstridd region öster om Badlands och Burning Steppes, vid Forbidding Sea. Området var en gång ett blomstrande territorium i Stormwind, men är nu en aktiv gränsbygd som bestrids av Alliansen vid Farholde Keep och Horden vid Rog'mar.",al={"översikt över riverglades","vad är det här för område","om riverglades"}},{q="Vad hände med Sunnyglade?",a="Sunnyglade plundrades och förstördes av den gamla horden under det första kriget. Orcherna tillfångatog de överlevande byborna och gjorde dem till slavar, men lät ett lokalt magitorn stå kvar för att tyda mänsklig magi. Stormwinds soldater befriade fångarna och försökte återuppbygga området, men kungariket övergav det till slut för att fokusera på sina västra gränser.",al={"sunnyglades historia","sunnyglades fall","vad hände med staden"}},{q="Vem kontrollerar Farholde Keep?",a="Farholde Keep hålls av Alliansens lojalister, ledda av riddarkommendör Demar Brant från Brotherhood of the Horse. Hans styrkor har kämpat i åratal för att återta Riverglades efter att Stormwind först förklarade territoriet förlorat.",al={"vem leder farholde","alliansen i riverglades","brotherhood of the horse"}},{q="Hur tar du dig från Riverglades till Tanaris?",a="En båt går regelbundet mellan Powderfuse Port på Riverglades östra kust och Steamwheedle Port i Tanaris och erbjuder en direkt sjöförbindelse över havet.",al={"båt till tanaris","båten från powderfuse port","hur tar man sig till tanaris"}},{q="Vilka pass leder till andra områden?",a="Du kan resa sydväst genom Redridge Pass till Redridge Mountains eller fortsätta söderut direkt mot Swamp of Sorrows. I väster leder Blackrock Pass förbi Bristle Hills till Burning Steppes, medan stigarna norr om Twilight's Shroud går rakt in i Badlands.",al={"hur tar man sig till redridge","pass från riverglades","utfarter från riverglades"}},{q="Vad är Krol'dok Stronghold?",a="Krol'dok Stronghold är ett befäst grottkomplex i Riverglades och utgör ett viktigt maktcentrum för fientliga styrkor i det omstridda territoriet.",al={"kroldok stronghold","riverglades grotta","vilken grotta finns här"}}},fp="11,291,22.431.0,25.415.0,20.414.0,24.187.0,28.295.0,27.212.0,46.146.0,34.266.0,28.127.0"}
P.entries["zone:ruinsoflordaeron"] = {n="Ruins of Lordaeron",s="Ruins of Lordaeron ligger direkt ovanför det underjordiska Undercity och är de ihåliga resterna av människornas en gång mäktiga nordliga kungarike. Scourge och prins Arthas lade det i ruiner under det tredje kriget, och nu kryllar gatorna och de spruckna torgen på ytan av kringvandrande vidunder, hämndlystna vålnader och ondskefulla experimenterare. Både Alliance och Horde skickar expeditioner till den här fördärvade borgen för att återta reliker från det förflutna eller rensa bort fasorna ovanför Forsakens huvudstad.",h="Ruins of Lordaeron ligger direkt ovanför det underjordiska Undercity och är de ihåliga resterna av...",kw={"bjork","lordaeron captain","the new plague","rath'mael","ruins of lordaeron","the abandoned","the baron","tirisfal glades","undercity","viktor the vile","witherfang"},ang={["class:Paladin"]="Lordaeron var Knights of the Silver Hands vagga. Att vandra genom dess vanhelgade salar för att rensa bort fasor och ge rastlösa kaptener ro är en högtidlig plikt för Ljuset.",["faction:Alliance"]="En färd in i Lordaeron låter Alliance slå till vid tröskeln till Forsakens huvudstad och skipa rättvisa och ge ro åt andarna efter deras mördade nordliga bröder.",["race:Human"]="Mänskliga äventyrare betraktar den förstörda huvudstaden som helig mark, stulen genom förräderi, och söker återta förlorade familjeklenoder och hedra sina fallna anhöriga.",["race:Undead"]="För Forsaken är ruinerna ovanför deras forna hem och eviga gravplats. Att rensa dem säkrar deras ytterdörr och förser apotekarna med ingredienser för att utveckla The New Plague."},sec={{t="En fallen stads gård",b="Capital City var en gång Eastern Kingdoms kronjuvel, kung Terenas Menethil II:s säte och den mänskliga civilisationens bultande hjärta. När prins Arthas återvände från Northrend dödade han sin far i tronsalen och släppte lös de odöda bland invånarna. I dag bor Forsaken i katakomberna under ytan, i Undercity, medan ruinerna ovanför förblir en övergiven skymningszon. Trasiga valv och ogräsbevuxna kullerstensgator ger skydd åt vilda bestar som Witherfang och förvirrade lämningar från det förflutna."},{t="Plåga och pest",b="Farorna i de ödelagda markerna begränsar sig inte till rastlösa döda. Apotekare och skumma gestalter som Viktor the Vile testar nya farsoter bland skuggorna, medan förvridna experiment som The Abandoned strövar fritt. Vreda andar som Rath'mael och förbannade tjänare som The Baron hemsöker de rasade korridorerna, fångade i ändlös plåga och redo att slå till mot levande eller odöda inkräktare som kommer i deras väg."},{t="Kungliga gardets vålnader",b="Bland de mest gripande farorna i de övre ruinerna finns de spektrala resterna av stadens försvarare, och till sist visar sig en vålnad från Lordaeron Captain. Dessa uppenbarelser klamrar sig fortfarande fast vid sina krossade eder och ser alla som närmar sig tronen som inkräktare. När Captain och soldaterna får ro får den obrutna vakten, som pågått sedan huvudstaden föll, ett bitterljuvt slut."}},faq={{q="Var ligger fängelsehålan Ruins of Lordaeron?",a="Fängelsehålan ligger på ytan av Capital City i Tirisfal Glades, precis ovanför ingångsnätverket som leder ner till Forsakens huvudstad Undercity.",al={"ruins of lordaeron plats","var ligger lordaeron-fängelsehålan","ingång till undercity-fängelsehålan"}},{q="Varför är både Horde och Alliance intresserade av den här platsen?",a="För Alliance är en färd in i Lordaeron en helig pilgrimsfärd för att återfinna förlorade familjeklenoder, samla kungliga vapensköldar och ge fallna förfäder slutlig ro. För Horde, särskilt Forsaken, är det viktigt att rensa de övre ruinerna för att säkra Undercitys utkanter och få forskningsprover till Royal Apothecary Societys nya farsot.",al={"varför besöka ruins of lordaeron","alliance-uppdrag i lordaeron","horde-uppdrag i lordaeron"}},{q="Vem är Viktor the Vile?",a="Viktor the Vile är en av de illvilliga gestalter som utnyttjar laglösheten i ruinerna. Han utför avskyvärda experiment och bidrar till den variga korruption som håller den övre huvudstaden full av förvridna styggelser.",al={"viktor the vile bakgrund","vem är viktor the vile"}},{q="Vad är ”The Abandoned” som man stöter på i ruinerna?",a="The Abandoned är ett groteskt odött vidunder som lämnats kvar i ruinerna. Liksom många lappverksskräckelser som skapades under och efter Scourges erövring irrar det planlöst genom de förfallna salarna och angriper allt det möter.",al={"the abandoned-boss","vem är the abandoned"}},{q="Vad betyder det för berättelsen att besegra Lordaeron Captain?",a="När den spektrala Lordaeron Captain besegras befrias en högt uppsatt kunglig försvarare från en evig, vansinnig plikt. Captain har varit bunden av sin heder sedan Scourges första massaker och har i åratal vaktat ett förstört kungarike mot alla som närmar sig. När Captain får ro bryts en plågsam cykel av spöklikt slaveri, och hens blodbestänkta insignia kan återtas.",al={"besegra lordaeron captain","lordaeron captain betydelse","vad händer när captain dör"}},{q="Är Ruins of Lordaeron åtskilt från Undercity?",a="Ja. Forsaken har sitt hem i Undercitys grottor nedanför, medan ruinerna ovanför är en aktiv stridszon som översvämmas av rastlösa vålnader, vilda rovdjur och experimentella hot som Forsaken ännu inte har utrotat helt.",al={"finns undercity i den här fängelsehålan","ruins jämfört med undercity"}}},fx={["1b77984b"]={q="Vad är den här platsen, Ruins of Lordaeron?",a="Du står bland de krossade resterna av Capital City, en gång den mänskliga civilisationens juvel och hjärtat i kungariket Lordaeron. Under det tredje kriget förrådde prins Arthas sitt kungarike, mördade sin far kung Terenas i tronsalen ovanför och släppte lös det odöda Gisslet på stadens gator. I dag står dess trasiga valv och svedda torn ovanför det underjordiska Undercity, som ett bittert minnesmärke över kungariket som föll.",al={"vad är ruins of lordaeron","ruins of lordaeron-lore","vad var den här platsen"}},eb89374f={q="Vilka bodde här innan staden förstördes?",a="Den här staden var hem åt mänsklighetens mäktigaste nordliga kungarike, styrt av Menethil-dynastin. Adelsmän, präster av det Heliga ljuset, soldater och hundratusentals vanligt folk vandrade en gång på de stenlagda gatorna. Tragiskt nog lämnade många av de forna invånarna aldrig platsen på riktigt. De föll offer för pesten, och deras återupplivade lik utgör både den viljelösa Scourge som hemsöker Plaguelands och de befriade Forsaken som nu bor i grottorna därunder.",al={"vilka bodde här före ruinerna","lordaerons ursprungliga invånare","vilka var här först"}},["6e6195fd"]={q="Varför är allt trasigt och nedbränt?",a="När prins Arthas återvände med Frostmourne dödade han kung Terenas och överlämnade staden till Scourge. Odöda fasor härjade längs avenyerna, brände byggnader och slaktade alla som försökte göra motstånd. Senare, under inbördeskriget bland de odöda, kämpade Sylvanas Windrunner och hennes Forsaken mot dreadlords och kvarvarande Scourge-legioner på just de här gårdarna och rev ner det som återstod av stadens storslagna arkitektur.",al={"varför är lordaeron förstört","hur brändes lordaeron ner","varför ligger det i ruiner"}},dd470a5c={q="Vem förstörde Lordaeron?",a="Kungariket krossades inifrån av sin egen kronprins, Arthas Menethil, under Lich Kings fördärvande viskningar. Arthas skickades för att stoppa The Cult of the Damned och deras pest av odödlighet. Han blev hänsynslös, tog upp det förbannade runsvärdet Frostmourne i den frusna norden och gav upp sin själ. När han återvände hem som dödsriddare slog han ner sin far och överlämnade staden till Scourges klor.",al={"vem förstörde lordaeron","vem krossade lordaeron","lordaerons förgörare"}},f5a9164f={q="Var är Arthas nu?",a="Arthas lämnade den förstörda kontinenten Lordaeron för flera år sedan och seglade tillbaka över Great Sea till Northrend när demonjägaren Illidan Stormrage hotade Lich King. Han kämpade sig uppför den iskalla spiran Frozen Throne och har försvunnit ur sikte i de frusna ödemarkerna. Kvar lämnade han ett kungarike som splittrats i rivaliserande grupper av odöda och överlevande.",al={"vart tog arthas vägen","var är prins arthas","arthas plats"}},["2fe0baef"]={q="Lyckades någon fly från staden?",a="Några få lyckades fly från massakern. Innan allt slutligen föll lyssnade trollkvinnan Jaina Proudmoore till en mystisk profets varningar och ledde tusentals mänskliga flyktingar över havet till Kalimdor, där de grundade hamnstaden Theramore. Andra flydde söderut mot kungariket Stormwind eller tog till vapen i det heligas namn och bildade det fanatiska Scarlet Crusade och det vaksamma Argent Dawn.",al={"överlevde lordaerons invånare","överlevde någon lordaerons fall","lordaerons överlevande"}},["9cf7434f"]={q="Varför finns det en stad med odöda under ruinerna?",a="När Lich Kings makt avtog bröt Sylvanas Windrunner hans mentala kontroll över en mängd odöda. De kallade sig Forsaken och störtade de demoniska dreadlords som höll Capital City. Ruinerna ovan jord var alltför utsatta för fientliga blickar och Scarlet Crusades ständiga angrepp, så Sylvanas valde att förvandla de väldiga underjordiska kryptorna och kloakerna till ett tungt befäst fäste.",al={"varför finns undercity","varför ligger undercity under lordaeron","odöda stad under ruinerna"}},["55ddf3da"]={q="Vem byggde Undercity?",a="Grunden anlades under Capital City som kungliga fängelsehålor, kloaker och djupa kryptor byggda av människorna i Lordaeron. Under Third War började Arthas och Scourge bygga ut de underjordiska gångarna till ett invecklat nätverk som skulle bli ett centrum för Scourges makt. Efter att ha tagit kontrollen från dreadlorden Varimathras färdigställde Sylvanas och Forsaken Undercity som sitt permanenta huvudstadssäte.",al={"vem byggde undercity","undercitys byggande","vem grävde ut undercity"}},c0ee4f6f={q="Har Undercity alltid legat där nere?",a="Inte i sin moderna, vidsträckta form. På kung Terenas tid bestod underjorden bara av slottsfängelsehålor, akvedukter, kloakkanaler och familjegravar. Först efter kungarikets fall gröpte Scourge-abominationer och Forsaken-arbetare ut de enorma ringarna och kvarteren du ser i dag och förvandlade servicetunnlarna till ett vidsträckt underjordiskt fäste för de döda.",al={"har undercity alltid funnits där","fanns undercity förr","gamla undercity"}},dc41e367={q="Vem bestämmer här?",a="Lady Sylvanas Windrunner, Banshee Queen, styr över ruinerna och Undercity därunder. En gång var hon Silvermoons ranger-general. Arthas dödade henne och återuppväckte henne som en hämndlysten banshee, och till slut återtog hon sin fysiska kropp. Med ren viljestyrka och list befriade hon sina odöda fränder och grundade Forsaken. Från sin tron i Royal Quarter leder hon dem med hänsynslös beslutsamhet.",al={"vem styr över lordaerons ruiner","undercitys ledare","vem kontrollerar den här platsen"}},["3d3094f9"]={q="Är Sylvanas en drottning eller något annat?",a="Hennes folk vördar henne som Banshee Queen och Forsakens Lady, men hon tillhör inte Lordaerons ärftliga kungahus. Titeln speglar hennes tragiska död för prins Arthas hand. Han slet hennes själ ur kroppen och tvingade henne att tjäna som en jämrande banshee. Även om titeln anspelar på monarki bygger hennes auktoritet på befrielse, överlevnad och total militär kontroll.",al={"är sylvanas en drottning","titeln banshee queen","vad är sylvanas titel"}},ac534dbb={q="Lyder Sylvanas under Thrall?",a="Officiellt erkänner Sylvanas Warchief Thrall som Hordens högsta befälhavare, och hon gick med på deras allians av bekvämlighet. I praktiken har Banshee Queen full självständighet över Forsaken och deras nordliga områden. Thralls ord respekteras och Forsaken-sändebud rör sig i Orgrimmar, men Lady Sylvanas sätter först och främst sin egen överlevnad och sitt folks ambitioner.",al={"sylvanas och thralls relation","lyder sylvanas thrall","står sylvanas under thrall"}},["6b51523d"]={q="Vad hände i tronrummet där uppe för trappan?",a="Tronrummet var platsen för det katastrofala förräderi som gjorde slut på kungariket. Prins Arthas, som just hade återvänt från Northrend, marscherade förbi välkomnande invånare och ringande klockor in i den här salen. När hans far, kung Terenas, reste sig från tronen för att hälsa honom drog Arthas Frostmourne, förklarade att han efterträdde sin far och stötte det förbannade runsvärdet genom den gamle kungens hjärta.",al={"vad hände i tronrummet","lordaerons tronrumshistoria","tronrummets historia"}},["6e83c082"]={q="Är det där Terenas dödades?",a="Ja. Står du precis framför den trasiga podiet står du på just de stenplattor där kung Terenas Menethil II drog sitt sista andetag. En svag, mörk fläck syns fortfarande på stengolvet. Den sägs vara den gamle kungens blod, som trängde in i murverket när hans son slog ner honom. Än i dag ekar spöklika viskningar och klockor svagt i salen.",al={"var dödades terenas","är det terenas blod","platsen där kung terenas dog"}},ea8d978d={q="Vad hände med Terenas krona?",a="Terenas gyllene krona föll till golvet när Arthas mördade honom i tronrummet. Kronans fall markerade slutet på hans regeringstid och katastrofen som drabbade Lordaeron.",al={"varför ligger kronan på golvet","kung terenas krona i ruinerna","terenas krona och blod"}},bb044bc8={q="Tillhör Forsaken verkligen Horden?",a="Ja, även om det till stor del är en pakt för ömsesidig överlevnad. Omgivna av Scarlet Crusade, fientliga människor och de kvarvarande styrkorna från Scourge skickade Forsaken sändebud över havet för att söka allierade. Horden behövde ett fotfäste i Eastern Kingdoms för att kunna stå emot alliansen, så den gick med på att släppa in dem. Därmed fick Forsaken välbehövligt militärt stöd och internationell status.",al={"forsaken och hordens allians","är odöda med i horden","varför tillhör forsaken horden"}},["50000697"]={q="Varför släppte Thrall in odöda i Horden?",a="Thrall övertygades främst genom ärkedruiden Hamuul Runetotems och taurenfolkets förmedling. De trodde att Forsaken var tragiska offer som en dag kanske kunde finna försoning eller botas från sin åkomma. Thrall insåg också att Horden behövde ett etablerat fäste i Eastern Kingdoms för att hindra alliansen från att dominera den norra kontinenten utan motstånd.",al={"varför tillät thrall odöda","varför thrall valde forsaken","varför tog horden in forsaken"}},["9af0f393"]={q="Litar orcherna och tauren på dem?",a="Inte helt. Tauren ser på dem med djup medkänsla och hoppas kunna hela dem, men många orcher hyser starka betänkligheter kring mörk magi, nekromanti och Undercitys olycksbådande natur. Thrall håller noga uppsikt över Sylvanas handlingar, och de stationerade sändebuden är på sin vakt inför vad som pågår i Royal Apothecary Societys laboratorier.",al={"litar orcherna på forsaken","litar tauren på forsaken","litar horden på odöda"}},["849f698a"]={q="Är det säkert för mig att stå här?",a="Det beror helt på var din lojalitet ligger. Kämpar du för Horden känner Forsaken och deras abominationer igen dig som en allierad, även om skuggorna ovanför döljer kringströvande varelser och kvarvarande andar. Marscherar du under alliansens baner befinner du dig djupt på fiendens territorium. Forsaken-vakter och dread guards slår ner dig så fort de får syn på dig.",al={"är ruinerna av lordaeron säkra","är jag säker här","faran med att stå i lordaeron"}},aac358a1={q="Kommer vakterna att anfalla mig?",a="Forsaken Deathguards och kungliga abominationer som är utposterade runt ruinerna ignorerar eller skyddar resenärer från Horden, men är brutalt fientliga mot alliansens kämpar. Dessutom lurar fientliga avfällingar och monster i avskilda gångar och fängelsehålor i ruinerna ovanför. De anfaller alla som kommer i deras väg, oavsett grupptillhörighet.",al={"anfaller undercitys vakter","är ruinernas vakter fientliga","kommer vakterna att anfalla mig"}},e9ec8c01={q="Finns det fortfarande Scourge i närheten?",a="Ja. Sylvanas rensade ut större delen av Scourge från Capital City, men Scourge har fortfarande ett starkt fäste precis utanför gränsen i Western Plaguelands. Även i de mörkaste vrårna och bortglömda undernivåerna i de här ruinerna dröjer viljelösa odöda och rester av Scourge kvar, redo att slita i sig levande kött från den som vågar sig för långt.",al={"scourge i lordaerons ruiner","finns scourge nära undercity","finns scourge i närheten"}},["0a975308"]={q="Vad är det för pest som alla pratar om?",a="De talar om Plague of Undeath, en fruktansvärd biomagisk smitta som utvecklades av Lich King och hans nekromantiker. Cult of the Damned spred den över Lordaeron via smittat spannmål. Den dödade alla som åt det inom några timmar och återupplivade genast deras lik som lydiga, ruttnande tjänare åt Scourge.",al={"vad är plague of undeath","vilken pest nämns","lordaerons pest"}},["290f94a8"]={q="Vem skapade den ursprungliga pesten?",a="Den ursprungliga pesten konstruerades av Burning Legions dreadlords och fulländades av Lich King, Ner'zhul, medan han hölls fången högst upp på Frozen Throne i Northrend. För att släppa lös den över Lordaeron tog han hjälp av Dalarans avfällige ärkemagiker Kel'Thuzad, som grundade Cult of the Damned och förgiftade spannmålsförråden.",al={"vem skapade plague of undeath","skaparen av den ursprungliga pesten","vem skapade pesten"}},["89f62638"]={q="Skapar Sylvanas en ny?",a="Ja. Lady Sylvanas har gett Royal Apothecary Society i uppdrag att brygga en \"New Plague\". Målet är att skapa ett biologiskt vapen som är kraftfullt nog att utplåna både Scourge och de levande, så att Forsaken kan överleva och hämnas på Arthas. Deras hemliga tester pågår just nu i Apothecarium nedanför.",al={"skapar sylvanas en pest","forsakens nya pest","ny pest i undercity"}},dcb566d2={q="Vem är Lich King och vad vill han?",a="Lich King är Scourges högste härskare, skapad av den torterade orkschamanen Ner'zhuls ande, innesluten i is högst upp på Frozen Throne. Hans mål var att försvaga Azeroth åt Burning Legion, men han närde också sina egna skrämmande ambitioner: att utrota allt dödligt liv och ersätta det med ett evigt, enat rike av odöda under hans fullständiga mentala kontroll.",al={"vem är lich king","vad vill lich king","lich kings motiv"}},["3a9893a7"]={q="Var är Lich King nu?",a="Han härskar från Frozen Throne, högst upp på Icecrown Glacier på den avlägsna, frusna kontinenten Northrend. Efter Illidans anfall, som spräckte hans isfängelse, kallade Lich King tillbaka Arthas till Northrend för att förena deras andar och bevara sin makt, långt från Lordaerons krossade rike.",al={"var är lich king","lich kings plats","var ligger frozen throne"}},["0138c577"]={q="Kontrollerar han fortfarande Forsaken?",a="Nej. När Illidans besvärjelseverk spräckte Frozen Throne började Lich Kings telepatiska grepp att brista. Sylvanas och många andra odöda återfick sin fria vilja och bröt sig loss från hans kollektiva medvetande. Han försöker återta kontrollen över dem, men Forsaken gör nu våldsamt motstånd mot hans viskningar och kämpar hårt för att bevara sin självständighet.",al={"kontrollerar lich king forsaken","kan lich king befalla forsaken","forsakens fria vilja"}},["6a523c60"]={q="Vilka är Scarlet Crusade och varför hatar de odöda?",a="Scarlet Crusade är en religiös orden av mänskliga fanatiker, bildad av de splittrade resterna av Silver Hand och Lordaerons riddare. De är traumatiserade av pesten som förstörde deras hemland och uppfyllda av paranoia. I deras ögon är alla odöda vidriga varelser utan undantag, och alla levande som umgås med dem anses vara besmittade och dömda till avrättning.",al={"vilka är scarlet crusade","varför hatar scarlet crusade odöda","scarlet crusades bakgrund"}},b59db3a3={q="Är de samma som Argent Dawn?",a="Nej, de är bittra rivaler med gemensamma rötter. Båda uppstod ur spillrorna av Knights of the Silver Hand, men när Scarlet Crusade föll för blind fanatism och främlingshat bröt sig mer moderata paladiner loss och bildade Argent Dawn. Dawn välkomnar alla raser och fokuserar på att försvara landet mot Scourge i stället för att rensa ut urskillningslöst.",al={"scarlet crusade mot argent dawn","är scarlet crusade och argent dawn samma","skillnaden mellan scarlet crusade och argent dawn"}},ca88b6f6={q="Angriper de också levande spelare?",a="Ja. Scarlet Crusade tror att alla som inte bär deras karmosinröda tabard i hemlighet hyser pesten eller samarbetar med de odöda. Vare sig du är en ork, en tauren, en Night Elf eller en mänsklig soldat från Stormwind kommer deras fanatiker att stämpla dig som smittobärare och anfalla dig så fort de får syn på dig.",al={"angriper scarlet crusade alliance","angriper scarlet crusade levande","scarlet crusade fientliga mot levande"}},["861c7602"]={q="Vad gör Royal Apothecary Society där nere?",a="Det här skändliga gillet av Forsaken-al kemister och före detta magiker verkar från Apothecarium i Undercity och arbetar outtröttligt på Lady Sylvanas uppdrag. Deras främsta uppgift är att utveckla en katastrofal \"New Plague\" som kan utrota både Scourge och de levande raserna. De utför hänsynslösa experiment för att säkra Forsakens överhöghet.",al={"vad gör royal apothecary society","royal apothecary societys syfte","apotekarna i undercity"}},["3c47ce18"]={q="Experimenterar de på folk?",a="Djupt inne i Apothecarium hålls tillfångatagna krigare från Scarlet Crusade, Scourge-ghouls och allehanda bestar inlåsta i järnburar. Apotekarna utsätter fångarna för smärtsamma kemiska blandningar och virulenta peststammar. De undersöker hur snabbt köttet ruttnar och hur smittan påverkar levande respektive nekrotisk fysiologi.",al={"experimenterar apotekarna på människor","royal apothecary societys experiment","torterar undercitys apotekare folk"}},f7d23701={q="Lever Arthas fortfarande, och skulle jag kunna slåss mot honom?",a="Arthas är inte död i dödlig mening, men helt förvriden till en dödsriddare och mästare över Scourge. Han befinner sig långt bortom havet i Northrend, utom räckhåll för alla i Lordaeron. Just nu kämpar du mot hoten som dröjer sig kvar här: Scourges lokala befälhavare, Scarlet Crusade och de vilda bestar som hemsöker ruinerna.",al={"kan jag slåss mot arthas","lever arthas","kommer vi att möta arthas"}},["9fc2648e"]={q="Är han Lich King nu?",a="Viskningar från norr hävdar att Arthas besteg Icecrown Spire för att befria Lich King från Illidans belägring. Han krossade isen, tog på sig Helm of Domination och förenade sin själ med Ner'zhuls. För världen i stort ligger Northrends exakta tillstånd höljt i isig mystik, men hans mörka närvaro vilar över alla odöda.",al={"är arthas lich king","blev arthas lich king","arthas identitet som lich king"}},["89a21402"]={q="Hur hamnade jag i Ruins of Lordaeron?",a="Du gick genom de sönderfallande yttre portarna till den fallna huvudstaden i Tirisfal Glades, strax ovanför hissarna som leder ner till Undercity. Kanske svarade du på en militär inkallelse, följde rykten om okontrollerade fasor som klamrar sig fast vid rikets lik eller smet genom fientligt territorium för att återta heliga reliker från det förflutna. Din färd förde dig till de avspärrade, omstridda gårdarna, där Scourges skuggor och det gamla mänskliga rikets vålnader fortfarande dröjer sig kvar.",al={"hur hamnade jag här","hur kom jag hit","varför är jag i ruins of lordaeron","hur anlände jag hit"}},bb4abd7f={q="Vad förväntas jag göra i Ruins of Lordaeron?",a="Du är här för att rensa bort fasorna som frodas i ytans ruiner ovanför Forsakens huvudstad. För Horde innebär det att jaga bort kringströvande Scourge-bestar, återta förlorade insignier och testa dödliga brygder åt Royal Apothecary Society. För Alliance handlar det om ett hemligt anfall för att rena förfädernas marker, hämta heliga arvegods som Crest of Lordaeron och skänka tröst åt vandrande, plågade vålnader som inte funnit frid.",al={"vad gör jag här","vad är mitt uppdrag här","vad ska jag göra i ruinerna","vad är mitt mål här"}}},fp="18,278,27.503.0,22.413.0,25.302.1,48.174.0,61.277.0,23.179.0,49.228.0,61.384.1,54.227.0"}
P.entries["zone:scarlet"] = {n="Scarlet Monastery",s="På en höjd i nordöstra Tirisfal Glades låg Scarlet Monastery, en gång en fridfull helgedom och ett lärosäte för Church of the Holy Light. Efter Lordaerons fall tog Scarlet Crusade över klostret och befäste det kraftigt som sin främsta utpost i väster. Nu är det en vidsträckt fästning med fyra flyglar, där fanatiska zeloter tränar, torterar fångar och utkämpar ett kompromisslöst krig mot alla utomstående.",h="På en höjd i nordöstra Tirisfal Glades låg Scarlet Monastery, en gång en fridfull helgedom och ett lärosäte...",kw={"armory","cathedral","doan","graveyard","herod","library","mograine","scarlet crusade","scarlet monastery","tirisfal glades","whitemane"},ang={["class:Mage"]="Library-flygeln rymmer sällsynta historiska och teologiska verk, bevakade av Arcanist Doan, korstågets främsta arkanist.",["class:Paladin"]="Klostret var en gång ett heligt säte för Lordaerons prästerskap. Dess förfall till röd fanatism påminner tragiskt om hur hängivenhet kan förvridas till galenskap.",["class:Priest"]="Klostret var ursprungligen ett säte för Church of the Holy Light. Dess storslagna kapell visar hur helig kraft fortfarande kan brukas av dödliga som förvridits av hat och hämndlystnad.",["race:Undead"]="Scarlet Monastery ligger vid gränsen till Tirisfal Glades och utgör ett existentiellt hot mot Forsaken. Därifrån skickar de spioner till Deathknell och torterar tillfångatagna odöda i sina fängelsehålor."},sec={{t="En fallen helgedom",b="Före det tredje kriget var klostret ett stolt säte för Lordaerons prästerskap och ett centrum för lärande och upplysning. Efter Scourges förödelse rensade överlevande korsfarare salarna från kvarvarande odöda och spindlar och förvandlade de fridfulla arkiven och gårdarna till en befäst garnison. Drivna av paranoia och sorg började Scarlet Crusade se alla utomstående, levande eller odöda, människor eller andra, som smittbärare av pesten som måste renas med eld."},{t="De fyra flyglarna",b="Bortom klostrets Grand Vestibule ligger fyra tydligt avgränsade delar. Graveyard är en ohelgad terrass under bar himmel, där fallna korsfarare återuppstår som odöda vidunder och torterare pressar fram bekännelser från fångar. Library bevarar dyrbara teologiska skrifter och historiska verk, bevakade av den avfällige magikern Arcanist Doan och hans hundar. Armory är en träningsplats där Scarlet-vapenmästare som Herod drillar fanatiska rekryter till järnhårda krigare. Längst in ligger Cathedral, fästningens storslagna hjärta, där korstågets ledare styr sin kampanj genom den härjade norden."},{t="High Inquisitors fall",b="Cathedrals innersta helgedom styrs av Scarlet Commander Mograine och klostrets verkliga härskare, High Inquisitor Whitemane. Att besegra Whitemane blir ett hårt slag mot korstågets operativa ledning i Tirisfal Glades. Hennes förmåga att kanalisera bländande Holy Light och återuppväcka fallna mästare fick garnisonen att verka oövervinnelig för dess anhängare. När hon dödas krossas den gudomliga auktoritetens sken som gödde klostrets fanatism. Korstågets ledare avslöjas som dödliga, och deras fälttåg mot Forsaken och grannländerna försvagas kraftigt."}},faq={{q="Varför är Scarlet Crusade fientligt mot levande äventyrare från Alliance?",a="Korståget har fallit offer för extrem galenskap och paranoia. I deras ögon är alla som inte bär deras röda tabard möjliga smittbärare av Scourges pest. De skiljer inte längre mellan vän och fiende, utan ser alla utomstående som besmittade varelser som måste renas innan de kan sprida smittan.",al={"varför anfaller scarlet crusade människor","scarlet crusade fientligt mot alliance","varför är de galna"}},{q="Vad händer när du besegrar High Inquisitor Whitemane?",a="Att besegra High Inquisitor Whitemane halshugger Scarlet Crusades västra militärledning. Som klostrets andliga ledare höll hennes mirakulösa krafter att återuppväcka de döda truppernas moral uppe och fick Commander Mograine att fortsätta kämpa vid hennes sida. Hennes död tar ifrån korståget dess mäktigaste prästinna i Tirisfal Glades och lämnar garnisonen i oordning, vilket kraftigt minskar hotet mot den omgivande trakten.",al={"vad innebär det att döda whitemane","whitemane besegrad lore","cathedral slut"}},{q="Vad är The Scarlet Key och var finns den?",a="The Scarlet Key förvaras djupt inne i klostrets Library-flygel, i Arcanist Doans kassaskrin bakom hans privata arbetsrum. Nyckeln behövs för att låsa upp de yttre portarna till både Armory- och Cathedral-flyglarna.",al={"var finns scarlet key","hur låser man upp armory och cathedral","klostrets nyckel"}},{q="Varför är Arcanist Doan i Scarlet Monastery?",a="Arcanist Doan är en mäktig mänsklig magiker som tjänar Scarlet Crusade. Han är övertygad om att arkan magi är ett vapen som behövs för att rena Lordaeron från Scourge. Han sköter klostrets omfattande Library-flygel och vaktar The Scarlet Key i sitt arbetsrum.",al={"vem är arcanist doan","doan lore","magikern i library"}},{q="Vem var Alexandros Mograine och hur hänger han ihop med platsen?",a="Alexandros Mograine, den berömde Ashbringer, var en legendarisk paladin från Silver Hand och en av grundarna av Scarlet Crusade, tillsammans med High General Abbendis och Grand Inquisitor Isillien. Hans son Renault styr nu Cathedral tillsammans med High Inquisitor Whitemane.",al={"mograine klostrets historia","ashbringer klostret","renault mograines far"}},{q="Vad skiljer Graveyard-flygeln så mycket från resten av klostret?",a="Medan resten av klostret utåt sett präglas av fläckfri hängivenhet är Graveyard platsen där korstågets fanatism ruttnar inifrån. Där finns deras brutala tortyrkammare, som sköts av Interrogator Vishas, och försummade kryptor och rastlösa döda som samlas in eller manipuleras av fallna magiker som Bloodmage Thalnos.",al={"varför är graveyard fullt av odöda","thalnos lore","interrogator vishas"}}},fx={["3ffc247b"]={q="Vad är Scarlet Monastery?",a="Scarlet Monastery ligger högt i nordöstra Tirisfal Glades och är ett befäst heligt område samt Scarlet Crusades främsta fäste i regionen. Det var en gång ett fridfullt katedralkomplex ägnat åt Holy Light och kyrkliga studier. Nu har fästet gjorts om till ett tungt beväpnat högkvarter, en träningsplats och ett ideologiskt bålverk för Crusades fanatiska kamp mot de odöda.",al={"vad är scarlet monastery","scarlet monasterys bakgrund","om scarlet monastery"}},fd7417a7={q="Har Scarlet Monastery alltid tillhört dem?",a="Nej. Före Lordaerons fall kallades det helt enkelt Old Monastery. Den adliga ätten Godwyn gav ursprungligen sitt stöd till klostret, som tjänade som ärkebiskopssäte och prästseminarium under ärkebiskop Alonsus Faol. Efter förödelsen under Third War återtog överlevande paladiner dess salar från kvarvarande Scourge-härdar och döpte om det till Scarlet Monastery.",al={"har scarlet monastery alltid tillhört crusade","scarlet monasterys historia","vem ägde scarlet monastery tidigare"}},e7b85043={q="Vem byggde Scarlet Monastery?",a="Old Monastery byggdes som en helgedom åt Church of the Holy Light med den adliga ätten Godwyns stöd. Arkivarier som Blake Godwyn skötte dess bibliotek och arkiv i generationer. Klostret var ett stolt centrum för Lordaerons prästerskap och paladinträning fram till rikets sammanbrott.",al={"vem byggde klostret","klostrets ursprung"}},["0c05301c"]={q="Vilka är Scarlet Crusade?",a="Scarlet Crusade är en fanatisk militärorden av mänskliga heliga krigare och präster, bildad av resterna av Knights of the Silver Hand. De är uppfyllda av sorg och hat efter Scourging of Lordaeron och har helt hängivit sig åt att utrota de odöda. De driver sin sak med extrem hänsynslöshet och paranoia.",al={"vilka är scarlet crusade","vad är scarlet crusade","scarlet crusades bakgrund"}},b0ef06b1={q="Är Scarlet Crusade människor?",a="Ja, deras led består enbart av människor från det fallna riket Lordaeron. De är våldsamt intoleranta mot alla icke-mänskliga raser, oavsett allians eller tidigare band, och anser att främlingar är ovärdiga eller medfödda bärare av pesten.",al={"består scarlet crusade bara av människor","crusades ras","är scarlet crusade människor"}},["1402011d"]={q="Varför anfaller jag en kyrka full av paladiner?",a="Trots att de bär heliga ordens insignier och brukar Ljuset har klostrets befälhavare blivit våldsamma extremister. Oavsett om du svarar på Raleigh the Devouts uppmaning att rena orden från dess korrumperade ledning eller slår till på Varimathras vägnar i Undercity för att oskadliggöra en aggressiv granne vid hans tröskel, är du där för att krossa deras militära makt.",al={"varför anfalla scarlet monastery","varför döda paladiner här","skäl att strida mot scarlet monastery"}},["18e8d4ac"]={q="Är Scarlet Crusade verkligen ond?",a="De började med ett ädelt mål: att rensa Lordaeron från det odöda Scourge. Men trauma och paranoia har förvrängt deras syfte fullständigt. Nu torterar de oskyldiga resenärer, stämplar alla främlingar som smittade och slaktar alla som inte bär deras tabard. I jakten på renhet har de förlorat all moralisk besinning.",al={"är scarlet crusade ond","är de skurkar","är korsfararna onda"}},fe2faadd={q="Stöder Alliance Scarlet Crusade?",a="Inte officiellt. Vissa i Stormwind kan känna sympati för Lordaerons överlevande heliga krigare, men Crusades urskillningslösa fientlighet har brutit de officiella banden. Äventyrare och personer inom Alliance, som Raleigh the Devout, ser deras nuvarande befälhavare som vettlösa fanatiker vars grymheter fläckar Ljuset ära.",al={"stöder alliance crusade","tillhör scarlet crusade alliance","alliance och scarlet crusades band"}},fbd0569e={q="Vem leder Scarlet Monastery?",a="Fästningens militära garnison lyder under Scarlet Commander Renault Mograine, som för befäl över en hängiven krigarskara. Men komplexets verkliga andliga och läromässiga ledare är High Inquisitor Whitemane, en mäktig prästinna som kan återuppliva de fallna så att de strider i hennes namn.",al={"vem leder scarlet monastery","vem styr klostret","scarlet monasterys ledare"}},ae07147f={q="Finns klostrets ledare i katedralen?",a="Ja. Både Scarlet Commander Mograine och High Inquisitor Whitemane bor i Crusader's Chapel, djupt inne i katedralflygeln, där de skyddas av en inre krets hängivna försvarare.",al={"var finns whitemane","är whitemane i katedralen","var finns katedralens boss"}},["11700a05"]={q="Varför hatar Scarlet Crusade Forsaken så mycket?",a="För Crusade är alla odöda avskyvärda varelser, födda ur pesten som utplånade deras familjer och hemland. De skiljer inte mellan Scourges viljelösa hantlangare och de fria Forsaken som bor i Capital City. Båda ses som ruttnande inkräktare som måste renas helt i helig eld.",al={"crusade mot forsaken","varför hatar crusade odöda","scarlet crusades fejd med forsaken"}},["38169c8a"]={q="Var Scarlet Crusaders och Forsaken samma folk en gång?",a="Ja. Före det tredje kriget var de flesta Crusaders och Forsaken invånare, soldater eller präster i kungariket Lordaeron. När pesten svepte fram blev de som dog och återuppstod odöda, medan de traumatiserade levande flydde eller slöt sig samman. Före detta grannar och släktingar blev bittra, svurna fiender.",al={"kände korsfararna och forsaken varandra","var de båda invånare i lordaeron","lordaerons kvarlevor"}},["80c0e472"]={q="Varifrån kom Scarlet Crusade?",a="Crusade växte fram ur de överlevande Knights of the Silver Hand och Lordaeronsoldater som leddes av Highlord Alexandros Mograine och General Abbendis. Förlusten av kungariket blev övermäktig för de överlevande ledarna, och de splittrades. De som förespråkade skoningslös, kompromisslös fanatism bildade Scarlet Crusade, medan de moderata bröt sig loss och grundade Argent Dawn.",al={"scarlet crusades ursprung","hur grundades scarlet crusade","vem grundade scarlet crusade"}},c4a70323={q="Vad var Silver Hand?",a="Knights of the Silver Hand var den legendariska heliga paladinorden, grundad under det andra kriget av Archbishop Alonsus Faol och Uther the Lightbringer. De tjänade som Alliance och Lordaerons främsta försvarare tills prins Arthas krossade deras led under Scourges invasion.",al={"vad var silver hand","knights of the silver hand","silver hands paladiner"}},d5472427={q="Varför dödar Scarlet Crusade även levande människor?",a="Djup paranoia har fått Crusade att tappa greppet om verkligheten. De tror att varje främling kan bära på den odöda pesten i hemlighet. Alla som inte bär deras uniform och underkastar sig deras strikta auktoritet stämplas som korrumperade och döms till tortyr eller döden.",al={"varför anfalla levande människor","crusade dödar människor","varför dödar de sina egna"}},b6568619={q="Är Scarlet Crusade ett hot mot Stormwind?",a="Inte direkt i form av territoriella erövringar, eftersom deras verksamhet är förankrad i Lordaerons nordliga ruiner. Men deras vansinne och vilja att mörda varje resenär gör dem till ett aktivt hot mot Alliance-medborgare, ambassadörer och äventyrare som rör sig nära deras områden.",al={"är scarlet crusade ett hot mot alliance","crusade mot stormwind","hotet från scarlet crusade"}},["6889160e"]={q="Varför vill alla att jag ska ta mig in i Scarlet Monastery?",a="Båda fraktionerna har mycket att förlora i Tirisfal Glades. Forsaken kan inte tolerera en tungt beväpnad fanatisk fästning precis utanför sin huvudstad, medan personer inom Alliance vill återta heliga texter, kuva farliga avfällingar och skipa rättvisa åt en vettlös ledning.",al={"varför skickas jag till scarlet monastery","vem vill döda klostrets invånare","varför uppdrag i scarlet monastery"}},["0c6b4a7d"]={q="Vad används Scarlet Monastery Library till?",a="Biblioteket, som omfattar Athenaeum och Gallery of Treasures, rymmer gamla skrifter från Lordaeron, historiska dokument och arkan kunskap. Det fungerar både som ett intellektuellt arkiv och en avskild forskningsfristad under Arcanist Doans ledning.",al={"biblioteksflygelns syfte","vad gör de i biblioteket","scarlet monastery athenaeum"}},["29dc31ee"]={q="Vad används Armory- och Cathedral-flyglarna till?",a="Armory är Crusades militära hjärta med träningsplatser, kaserner och vapengömmor under Herod the Scarlet Champions uppsikt. Cathedral är den främsta andliga helgedomen och ledningscentralen, där Mograine tränar elittrupper och Whitemane håller predikningar och samordnar Crusades närvaro i Tirisfal.",al={"vad används armory och cathedral till","syftet med armory i sm","syftet med cathedral i sm"}},f04a1b7f={q="Hur hamnade jag i Scarlet Monastery?",a="Du reste till de avlägsna nordöstra kullarna i Tirisfal Glades och tog dig genom de dimhöljda gläntorna till Scarlet Crusades befästa högsäte. Kanske smög du norrut från Undercity på Hordes order för att undanröja ett fanatiskt hot vid deras tröskel, eller tågade norrut från Hillsbrad Foothills efter att desillusionerade korsfarare bett dig rensa klostret från dess fanatiska ledning. Vägen ledde dig till slut till detta hårt bevakade komplex.",al={"hur hamnade jag här","hur kom jag till scarlet monastery","varför kom jag hit"}},be779d1d={q="Vad ska jag göra i Scarlet Monastery?",a="Du ska ta dig igenom Crusades fyra flyglar och bryta dess grepp om regionen. Beroende på vem som skickade dig kan du jaga den fallna ledningen, däribland Scarlet Commander Mograine och High Inquisitor Whitemane, hitta förlorade skrifter och kunskap i biblioteket, samla fanatikernas hjärtan åt Royal Apothecary Society eller återta heliga artefakter och döda korrumperade ledare som stämplar alla utanför sina led som odöda och smittade.",al={"vad gör jag här","varför är jag här","vad är mitt uppdrag här"}}},fp="17,291,18.495.0,14.492.0,31.517.1,66.284.0,55.301.1,46.170.0,46.213.0,57.280.1,74.218.0"}
P.entries["zone:searinggorge"] = {n="Searing Gorge",s="Searing Gorge är en förbränd, ödslig ravin i södra Khaz Modan, med Blackrock Mountain som gräns i söder. En gång var området en grönskande del av Redridge Mountains, men för över tvåhundra år sedan ödelades det när Ragnaros the Firelord kallades fram i en apokalyptisk ritual. I dag bearbetar Dark Iron-klanen ravinen intensivt, och deras omfattande slavgruvor i The Cauldron övervakas noga av utbrytargruppen Thorium Brotherhood.",h="Searing Gorge är en förbränd, ödslig ravin i södra Khaz Modan, med Blackrock Mountain som gräns i söder.",kw={"blackrock mountain","the cauldron","dark iron-klanen","ragnaros","searing gorge","the slag pit","stonewrought pass","thorium brotherhood","thorium point"},ang={["class:Rogue"]="Skurkar med stor erfarenhet av låsdyrkning är uppskattade resenärer här, eftersom de kan ta sig förbi den låsta porten vid Stonewrought Pass, som förbinder Loch Modan direkt med ravinen.",["faction:Alliance"]="Alliansen håller porten vid Stonewrought Pass låst för att isolera Dark Iron från fredliga dvärgbosättningar i Loch Modan, men modiga äventyrare får slå till i ravinen.",["faction:Horde"]="Horden har använt Kargath som bas och huggit ut en väg in i ravinen för att samla underrättelser om Blackrock Mountain och störa Dark Iron-verksamheten i Khaz Modan.",["profession:Mining"]="Det vulkaniska landskapet och de djupa gruvorna i The Slag Pit gör Searing Gorge till ett av de främsta jaktområdena för rika ådror av mithril, äkta silver och eftertraktad Dark Iron-malm.",["race:Dwarf"]="För dvärgarna i Ironforge är Searing Gorge en bitter påminnelse om War of the Three Hammers och Dark Iron-klanens katastrofala dårskap. Dess gruvor hotar nu de södra vägarna in i Khaz Modan."},sec={{t="Ett förbränt ödeland",b="Före War of the Three Hammers var området som nu är Searing Gorge en grön, kuperad bergstrakt som hängde samman med Redridge-kedjan. Det frodiga landskapet försvann för över tvåhundratrettio år sedan, när Sorcerer-Thane Thaurissan i desperation försökte vända ett nederlag och kallade fram Ragnaros ur djupen under världen. Eldhärskarens katastrofala ankomst slet upp jorden, reste Blackrock Mountain, förvandlade den stora Dark Iron-staden Thaurissan till rykande ruiner och brände den norra dalen till en sprucken vidsträckt ödemark av aska, svavel och vulkaniskt glas."},{t="The Cauldron och The Slag Pit",b="Efter att ha förlorat sin gamla huvudstad tog Dark Iron-dvärgarna den ödsliga ravinen för att få tag på råmaterial till sin krigsmaskin. Mitt i dalen ligger The Cauldron, ett kolossalt dagbrott som sträcker sig djupt ner i berget. I dess nedre avsatser ligger The Slag Pit, ett brutalt gruvkomplex under jord. Här driver Dark Iron-förmän och trögfotade krigsgolemer tillfångatagna fiender till utmattande slavarbete. De bryter järn, mithril och sällsynta fyndigheter av Dark Iron-malm ur den brännande klippan, ständigt hotade av lavaflöden och kringströvande bestar."},{t="Thorium Brotherhood och omstridda vägar",b="På de norra klipporna med utsikt över gruvan ligger Thorium Point, Thorium Brotherhoods befästa utpost. De har brutit med sina fränder i Blackrock Mountain och erbjuder resenärer neutral tillflykt om de hjälper till att sabotera Dark Iron-verksamheten eller förser dem med sällsynta smältkomponenter. Tillträdet till själva ravinen är hårt begränsat: Alliansen håller Stonewrought Pass spärrad bakom tunga järnportar mot Loch Modan, medan Hordens expeditioner från närbelägna Kargath har huggit ut en smal stig genom östra Badlands för att spana i området."}},faq={{q="Varför är Searing Gorge förbränd och täckt av aska?",a="För över tvåhundratrettio år sedan, under War of the Three Hammers, försökte Dark Iron-hövdingmagikern Thaurissan kalla fram en övernaturlig kraft för att undvika nederlag. I stället kallade han fram Ragnaros the Firelord. Det katastrofala utbrottet krossade den södra delen av Redridge-bergskedjan, skapade vulkanen Blackrock Mountain och förtärde de omgivande dalarna, som blev Searing Gorge och Burning Steppes.",al={"varför är det förbränt","searing gorge-lore","hur skapades searing gorge"}},{q="Vilka är dvärgarna som bor vid Thorium Point?",a="De tillhör Thorium Brotherhood, en självständig fraktion av Dark Iron-dvärgar som bröt banden med sina kejserliga fränder under Blackrock Mountain. Från sitt läger på Thorium Point arbetar de som mästersmeder och hantverkare. De delar med sig av kunskap och hantverkshemligheter till alla resenärer som hjälper dem mot Dark Iron-styrkorna där nere.",al={"dvärgarna vid thorium point","vilka är thorium brotherhood","thorium brotherhood-lore"}},{q="Vad pågår i The Cauldron?",a="The Cauldron är ett enormt dagbrott som kontrolleras av Dark Iron-klanen och rymmer The Slag Pit under jord. Dark Iron-förmän och krigsgolemer använder tillfångatagna fångar som slavar för att bryta dyrbar malm, däribland värdefulla fyndigheter av Dark Iron, till de stora smedjorna i Blackrock Mountain.",al={"vad är the cauldron","the slag pit-lore","vad bryter dark iron"}},{q="Hur tar du dig in i Searing Gorge från Loch Modan?",a="Passagen från Loch Modan genom Stonewrought Pass spärras av en tung, låst port som bevakas av bergskrigare från Ironforge. Du måste antingen skaffa Key to Searing Gorge genom ett officiellt uppdrag åt Curator Thorius, få en skicklig skurk att dyrka upp låset eller helt ta dig förbi porten genom att följa den öppna stigen söder om Kargath i Badlands.",al={"porten vid stonewrought pass","hur öppnar man porten till searing gorge","key to searing gorge"}},{q="Varför är Horden intresserad av Searing Gorge?",a="Från fästningen Kargath i närbelägna Badlands har Hordens befälhavare huggit ut ett bergspass in i ravinen för att spana på Dark Iron-truppernas rörelser och säkra taktiska vägar mot Blackrock Mountain, som har enorm strategisk betydelse.",al={"varför är horden här","förbindelsen mellan kargath och ravinen","hordens närvaro"}},{q="Finns det några grottor eller raidportaler i Searing Gorge?",a="Det finns inga instansportaler direkt i själva ravinen, men den södra ingången leder rakt in i Blackrock Mountain. Där finns Blackrock Depths, Blackrock Spire och de djupa passagerna som leder in i Molten Core.",al={"instanser i searing gorge","grottor i searing gorge","var ligger molten core"}}},fp="13,249,20.456.0,29.498.0,39.549.0,51.376.0,44.359.0,33.260.0,50.303.0,45.225.0,62.207.0"}
P.entries["zone:shadowfang"] = {n="Shadowfang Keep",s="Shadowfang Keep tronar på karga klippor ovanför Pyrewood Village och är den förrädiske Kirin Tor-magikern ärkemagikern Arugals dystra fäste. En gång var det Baron Silverlaines ärvda gods, men nu vimlar borgen av vilda worgen och plågade vålnader efter dess slaktade försvarare. För äventyrare på väg genom södra Silverpine är borgen den mörka mittpunkten för den bestialiska farsot som slukar trakten.",h="Shadowfang Keep tronar på karga klippor ovanför Pyrewood Village och är den förrädiske Kirin Tor-magikern...",kw={"arugal","fenrus","pyrewood","sfk","shadowfang","silverlaine","silverpine","springvale","worgen"},ang={["class:Mage"]="Tragedin i Shadowfang är en mörk varning om vad som händer när en Kirin Tor-magiker ägnar sig åt att kalla fram väsen från andra dimensioner utan att kunna kontrollera dem.",["class:Paladin"]="Commander Springvales rastlösa ande påminner sorgset om de fallna paladinförsvararna, vars heliga eder förvrängdes av döden.",["class:Warlock"]="De mörka energierna, voidwalkers och felbesvärjelserna i borgen lockar utövare som vill återfinna uråldriga reliker som Orb of Soran'ruk.",["faction:Horde"]="De övergivna ser Arugals framryckande flockar som ett omedelbart hot mot deras spirande territorium i Silverpine. Därför är borgen ett prioriterat mål för Deathstalker-agenter och Royal Apothecary Society."},sec={{t="Silverlaine-dynastins fall",b="Innan Shadowfang höljdes i mardrömmar var det känt som Silverlaine Keep, ett adligt säte som bevakades av den fromme Commander Springvale. När Scourge svepte genom Lordaeron under det tredje kriget föll Dalarans magiker i stora skaror. I ett desperat försök att hejda de döda trotsade ärkemagikern Arugal Kirin Tors ledning och började studera magikern Urs forskning. Han kallade fram worgen från en annan dimension för att vända krigslyckan. Bestarna slet de odöda i stycken, men undslapp snart all kontroll och bröt sig in i södra Silverpine innan de stormade borgen. Baron Silverlaine och hela hans hov massakrerades och dömdes att hemsöka stenhallarna tillsammans med de vilda monster som intagit deras hem."},{t="Arugals barn",b="Krossad av skuld och galenskap drog sig Arugal tillbaka bakom de blodbestänkta murarna. Han tog de glupska vargmännen till sina älskade ”barn” och döpte om borgen till Shadowfang Keep. Djupt inne i stenens gömslen frodas vargflockar och skugghundar under tränare som Wolf Master Nandos. De står under uppsikt av Arugals väldiga vargbest, Fenrus the Devourer. Förbannelsen stannade inte utanför murarna. Närliggande Pyrewood Village är fortfarande fångat i en fasansfull nattcykel. Invånarna går som människor om dagen och jagar som glupska worgen under månen, obönhörligt bundna till den galne ärkemagikern som sitter högt ovanför dem."},{t="De övergivnas angrepp",b="Lady Sylvanas Windrunner insåg vilket allvarligt hot Arugal utgjorde mot deras välde i Silverpine Forest och skickade Royal Apothecary Society och elitstyrkan Deathstalkers för att hitta källan till worgenförbannelsen. Infiltrationstrupper led svåra förluster i fängelsehålorna, men Horde-hjältar som hörsammade kallelsen från The Sepulcher nådde till slut det högsta tornet. När ärkemagikern fälls tar hans tid som flockens herre formellt slut. Bestarnas sinne förlorar sin ledare, och spridningen genom vildmarken hejdas. Hans huvud blir ett bevis på Lordaerons hämnd."}},faq={{q="Vad händer när ärkemagikern Arugal besegras?",a="När Arugal dödas kapas den centrala kraft som styr worgenflockarna i södra Silverpine. Horde-äventyrare överlämnar hans avhuggna huvud till Dalar Dawnweaver vid The Sepulcher på order av Lady Sylvanas Windrunner. Hans död bryter den direkta viljan som styr Shadowfang-flocken, men de vilda bestarna och de spöklika resterna i borgen och skogarna omkring utgör fortfarande en ständig fara för resande.",al={"följden av att döda arugal","arugal död lore","vad händer när arugal dör"}},{q="Varför kallade Arugal fram worgen?",a="Under det tredje kriget led Dalarans arméer förödande nederlag mot Scourge. Fallna magiker reste sig gång på gång som odöda soldater för Lich King. Arugal sökte ett vapen som kunde vända krigslyckan och använde magikern Urs arkanforskning för att kalla fram worgen från en annan dimension. Han trodde att deras vildsinthet kunde hejda Scourge.",al={"varför worgen kallades fram","arugals motiv","dalaran worgen-frammaning"}},{q="Vem var Baron Silverlaine?",a="Baron Silverlaine var den mänsklige adelsman som styrde borgen och övervakade den närliggande byn Pyrewood före det tredje kriget. När Arugals frammanade bestar undslapp kontrollen stormade de fästet och slaktade baronen, hans hushåll och hans vakter. Silverlaines hämndlystna vålnad hemsöker fortfarande de stora matsalarna, dömd att vandra bland monstren som dödade honom.",al={"baron silverlaine lore","shadowfangs ursprungliga härskare"}},{q="Varför är byborna i Pyrewood Village vänligt sinnade om dagen?",a="Arugal utsatte invånarna i närliggande Pyrewood Village för sin mörka magi. Om dagen behåller de sin mänskliga form, sitt förstånd och sitt fredliga sätt mot Alliance-resenärer. Vid solnedgången griper förbannelsen tag och förvandlar hela befolkningen till vilda worgen som lyder den galne ärkemagikern i borgen.",al={"människor i pyrewood","pyrewoods förbannelse","varför pyrewood förvandlas till worgen"}},{q="Vem är Commander Springvale?",a="Commander Springvale var en paladin och den militär som ansvarade för försvaret av Silverlaine Keep. När worgen intog fästet stred han till döden. Hans rastlösa ande patrullerar fortfarande de övre korridorerna och håller fast vid sin krigiska plikt även i odöden.",al={"springvale lore","spöklik paladinboss"}},{q="Vad är The Book of Ur?",a="The Book of Ur är en bok med forskning av Ur, en ärkemagiker från Dalaran som studerade väsen från andra dimensioner, däribland worgen. Arugal använde Urs skrifter för att utföra sin katastrofala frammaning. Royal Apothecary Society i Undercity söker boken för att förstå vargbestarnas natur och deras märkliga magi.",al={"the book of ur-uppdrag","ur lore"}}},fx={d6cbfc07={q="Vem skickade mig hit?",a="De övergivnas befälhavare vid The Sepulcher beordrade anfallet för att röja Arugal ur vägen och ta reda på vad som hänt deras försvunna spejare. Samtidigt skickade Royal Apothecary Society i Undercity ut agenter för att hämta Ur's magiska forskning från ärkemagikerns bibliotek.",al={"vem skickade mig till shadowfang","uppdragsgivare i shadowfang keep","vem vill döda arugal"}},a794fece={q="Tillhör det här landet de övergivna nu?",a="De övergivna gör anspråk på norra Silverpine Forest, men deras grepp om södern är hårt omstritt. Shadowfang Keep står fortfarande stadigt under Arugals välde, medan kvarvarande Scourge, vildsinta bestar och överlevande mänskliga bosättningar utmanar den mörka damens styre i hela regionen.",al={"är silverpine de övergivnas land","äger sylvanas det här","de övergivnas territorium shadowfang"}},b918d1de={q="Vem styr i Shadowfang Keep?",a="Slottet lyder helt under ärkemagikern Arugal. Han blev vansinnig under det tredje kriget och härskar från de övre tornen, omgiven av sina monstruösa worgen och sitt väldiga husdjur, vargen Fenrus. Med mörk trolldom styr han över borgen.",al={"vem styr shadowfang keep","vem bestämmer där inne","shadowfangs herre"}},ecad974c={q="Är Arugal bossen i borgen?",a="Ja. Arugal är herre över Shadowfang Keep. Han ligger bakom worgenhärjningarna i Silverpine Forest och sitter högst upp i borgens torn som dess obestridda härskare.",al={"är arugal bossen","slutboss i shadowfang","arugals herre"}},["3b086809"]={q="Styrde någon där före honom?",a="Baron Silverlaine styrde borgen när den var en alliansskans. Han och hans familj härskade över slottet tills Arugals worgen bröt igenom murarna och slaktade alla där inne under det tredje kriget.",al={"vem styrde före arugal","shadowfangs tidigare herre","borgens tidigare härskare"}},["7f02160f"]={q="Var kommer worgen ifrån?",a="De är glupska varelser från en annan dimension, slitna från ett annat plan. I sin desperation att stoppa Scourge under det tredje kriget vände sig Arugal till den förbjudna forskningen av magikern Ur från Dalaran och kallade dessa utomjordiska bestar till Azeroth.",al={"varifrån kom worgen","worgens ursprung","worgens källa"}},["4fa8e666"]={q="Kallade Arugal till worgen på egen hand?",a="Arugal utförde kallelsen trots uttryckliga råd från sina jämlikar i Dalarans Kirin Tor. Han förlitade sig i hög grad på skrifterna i The Book of Ur och tvingade varelserna över gränserna mellan planen.",al={"agerade arugal ensam","vem hjälpte till att kalla på worgen","arugals kallelse"}},a6a018be={q="Går det att kontrollera worgen?",a="Knappt, och bara med mörk magi. De kallades dit för att kämpa mot de odöda, men vände sig genast mot dem som kallat dit dem. Arugal lyckas styra några av dem bara för att hans brustna sinne ser dem som familj. Han använder förtrollningar för att hålla deras lydnad skör.",al={"går worgen att kontrollera","att kontrollera worgen","är worgen tama"}},["24ed31c3"]={q="Vad hände med Deathstalkers Adamant och Vincent?",a="Deathstalkers Adamant och Vincent smög sig in i Shadowfang Keep på order från The Sepulcher för att rekognosera Arugals styrkor. Borgens försvarare tillfångatog dem. Vincent fängslades och avrättades på borggården, medan Adamant sitter fången i fängelsehålorna och väntar på att bli räddad.",al={"adamant och vincent","vad hände med deathstalkers","de övergivnas spejare i shadowfang"}},cc7bdeae={q="Varför skickades Deathstalkers in i Shadowfang Keep?",a="De övergivnas befäl behövde exakta uppgifter om bestarnas angrepp som hotade deras södra front. Adamant och Vincent fick i uppdrag att infiltrera borgen, ta reda på hur många Arugal verkligen hade och bana väg för ett avgörande anfall.",al={"varför skicka deathstalkers","rekognosering av shadowfang","deathstalkers uppdrag"}},["4cfa60a4"]={q="Lever Deathstalkers fortfarande?",a="Vincent är död, dödad efter att han tillfångatogs. Adamant sitter däremot fortfarande fängslad djupt nere i borgens celler, men lever och kan hjälpa Horde-äventyrare som lyckas ta sig fram till honom.",al={"lever vincent och adamant","överlevde deathstalkers","deathstalkers öde"}},c6ee2849={q="Vad är Deathstalkers?",a="Deathstalkers är de övergivnas främsta hemliga lönnmördare och skurkar. De är specialister på smygande, spionage och plötslig död och verkar som Undercitys tysta dolkar längs Lordaerons gränser.",al={"vad är en deathstalker","vilka är deathstalkers","de övergivnas deathstalkers"}},["40c5e48b"]={q="Vem lyder Deathstalkers under?",a="De följer en strikt befälskedja som styrs av övergivna officerare och befälhavare utplacerade i territorierna. I slutänden tjänar de Undercitys styrande råd.",al={"deathstalkers ledning","vem befaller deathstalkers","vem leder deathstalkers"}},["63a10ab0"]={q="Arbetar Deathstalkers direkt för Sylvanas?",a="Ja. Varje Deathstalker har svurit trohet till banshedrottningen, lady Sylvanas Windrunner. De utgör hennes personliga underrättelsenätverk och jagar hot mot hennes viljestyrda odöda i hela Lordaeron.",al={"tjänar deathstalkers sylvanas","sylvanas deathstalkers","deathstalkers och banshedrottningen"}},f68cd02f={q="Varför skickar alla in mig i Shadowfang Keep?",a="De övergivnas första rekognosering gick helt om intet när deras elitstyrka av Deathstalkers tillfångatogs. Arugals näste är för farlig för vanlig infanteri. Där behövs beprövade äventyrare som kan kämpa sig igenom både bestar och hämndlystna andar.",al={"varför skicka mig till shadowfang","varför gör jag det här","varför hjälte i shadowfang"}},ebbfbfb0={q="Är jag den enda som kan göra det?",a="De övergivnas resurser i Silverpine Forest är hårt ansträngda i strider mot Rot Hide-gnoller, rester av Scourge och patruller från Dalaran. Deras egna förtrupper har slagits ut, så du och dina allierade är den enda styrka som kan ta sig in i borgen.",al={"är jag den enda","ingen annan kan röja shadowfang","enda alternativet"}},["0f7e4add"]={q="Försökte någon ta sig in i borgen före mig?",a="Ja. Förutom Deathstalkers misslyckade spaning gick Kirin Tor-utredare som magikern Ashcrombe in i borgen för att undersöka Arugal. De blev själva tillfångatagna eller fast i de förbannade salarna.",al={"försökte någon annan ta sig in i shadowfang","tidigare försök i shadowfang","vem försökte före mig"}},["13386e7c"]={q="Vad hände med Silverpine Forest?",a="Silverpine var en gång ett grönskande rike med höga tallar med silverfärgad bark, skyddat av Alliansen. När Scourge svepte genom Lordaeron under det tredje kriget förtvinade pesten skogarna, skördarna brändes och folket massakrerades eller drevs bakom The Greymane Wall.",al={"silverpines historia","vad hände med silverpine","varför ser silverpine ut så här"}},["7c8f83a0"]={q="Tillhörde Silverpine Lordaeron?",a="Ja. Silverpine utgjorde den karga västra kanten av kungariket Lordaeron och gränsade till Gilneas i söder. Dess gods och bosättningar tillhörde Alliansen innan pesten krossade kungariket.",al={"var det här lordaeron","silverpines historia i lordaeron","ägde lordaeron silverpine"}},["91da6ffd"]={q="Varför är Silverpine Forest så öde nu?",a="Scourges invasion, Gilneas beslut att stänga sin väldiga mur och Arugals härjande worgenförbannelse ledde till att den levande befolkningen massakrerades, förbannades eller flydde långt bort. De få som är kvar klamrar sig desperat fast vid omstridda byar som Pyrewood.",al={"varför är silverpine öde","öde silverpine","varför är silverpine ruiner"}},["4bfedcc6"]={q="Vad är Shadowfang Keep?",a="Shadowfang Keep är ett hemsökt slott på de höga klipporna i södra Silverpine Forest, med utsikt över Pyrewood Village. Det hette ursprungligen Silverlaine Keep och var en gång en fästning för Alliance som vaktade gränsen nära Gilneas. Nu står det korrumperat och höljt i mörka dimmor, som högsäte för Archmage Arugal och hans vilda worgenavkomma.",al={"vad är shadowfang keep","berätta om shadowfang","shadowfang keeps bakgrund"}},["1d3b32c5"]={q="Vem byggde Shadowfang Keep?",a="Fästningen var säte för Baron Silverlaine, en adelsman vars familj länge härskade över de omgivande markerna och Pyrewood Village före det tredje kriget. Under hans styre stod den som ett stolt mänskligt fäste, bevakat av Commander Springvale och rikets svurna soldater.",al={"vem byggde shadowfang keep","shadowfangs ursprung","vem skapade shadowfang"}},efb02893={q="Varför är Shadowfang Keep fullt av worgen?",a="När de tillkallade worgen slet sig fria från Kirin Tors kontroll härjade de genom skogen och belägrade slottet. De slaktade Baron Silverlaine och hans hushåll. Archmage Arugal blev vansinnig av skuld över vad han släppt lös, tog bestarna till sig som sina egna ”barn”, gjorde ruinen till sitt hem och döpte om den till Shadowfang Keep.",al={"varför finns det worgen här","varför finns worgen i shadowfang keep","varför finns worgen där inne"}},["7d419eb0"]={q="Varför är Horden intresserad av det här slottet?",a="Worgen som strövar ut från fästningen är en okontrollerad pest som hotar Forsakens grepp om Silverpine Forest. Från sitt högsäte i The Sepulcher insåg Forsakens ledare att markerna aldrig kan bli trygga så länge Arugal styr sina varglika fasor från slottets höjder.",al={"varför bryr sig horden om shadowfang","hordens intresse för shadowfang","varför ta sig till shadowfang keep"}},["2ee73ad9"]={q="Varför förde Arugal worgen till Silverpine från början?",a="När odöda Scourge marscherade söderut dog Dalarans magiker i mängder, bara för att återuppstå i Lich Kings tjänst. Arugal trodde att tillkallade allierade från en annan dimension kunde övermanna de odöda där vanliga dödliga arméer hade misslyckats.",al={"varför föra worgen till silverpine","varför arugal tillkallade worgen","varför tillkalla worgen här"}},["671a79f5"]={q="Vem försökte Arugal stoppa?",a="Han tillkallade dem specifikt för att utplåna Scourges odöda arméer, som växte sig större genom att slakta och återuppväcka varje soldat och magiker som föll i strid.",al={"vem slogs arugal mot","arugals fiende","mot vem tillkallade arugal worgen"}},eeb57b84={q="Fungerade Arugals plan mot Scourge?",a="Taktiskt sett, ja. Worgen slet obehindrat sönder de odöda. Men strategiskt blev det en katastrof. De vilda vargmännen kunde inte kontrolleras, vände sig mot både mänskliga soldater och magiker och spred en dödlig förbannelse över området.",al={"besegrade worgen scourge","fungerade tillkallandet","worgens framgång mot scourge"}},["2bfe7e75"]={q="Är worgen i borgen samma som de som övertog Pyrewood?",a="Ja. Arugals flockar, däribland Shadowfang- och Moonrage-flockarna, har samma förbannade ursprung. Bestarna som stryker genom borgens salar är Arugals egen avkomma och nära knutna till förbannelsen som drabbat byborna nedanför.",al={"kommer shadowfang-worgen från pyrewood","pyrewood-worgen och shadowfang","samma worgenflock"}},b78b86f3={q="Vad hände med invånarna i Pyrewood?",a="Byborna överlevde Tredje kriget, men föll sedan offer för Arugals mörka magi. På dagen ser de ut som vanliga människor, men vid solnedgången förvandlas de till vilda, blodtörstiga worgen som lyder den galne ärkemagikern.",al={"vad hände med folket i pyrewood","pyrewoods öde","pyrewoods invånare"}},["39fbc1b5"]={q="Är invånarna i Pyrewood också förbannade?",a="Ja. De är offer för worgenförbannelsen, som gör dem till varulvar. På dagen behåller de sina sinnen och handlar fredligt med alliansvandrare. På natten berövar förbannelsen dem deras mänsklighet och förvandlar dem till glupska bestar.",al={"är pyrewood förbannat","pyrewoods förbannelse","är byborna smittade"}},d6e89a88={q="Vilka är spökena i Shadowfang?",a="De är de rastlösa andarna efter Baron Silverlaine, Commander Springvale och borgens tidigare hushåll. De dödades i worgenflockens överraskningsangrepp, och deras själar är fortfarande bundna till de raserade murarna av plåga och sorg.",al={"spöken i shadowfang","vilka är andarna i sfk","vålnader i shadowfang"}},["0a399272"]={q="Är spökena borgens gamla tjänare?",a="Ja. Allt från spöklika kockar och skuggiga uppassare till före detta vakter, de vålnadslika försvararna som strövar genom salarna är de mördade tjänare som en gång hjälpte Baron Silverlaine i livet.",al={"är spökena tidigare tjänare","borgens tjänarspöken","silverlaines tjänare"}},["3f532512"]={q="Varför kan spökena inte få ro?",a="Den rena fasan över hur de slaktades, i kombination med den starka skuggmagi som genomsyrar borgen, hindrar dem från att gå vidare. I sin eviga vånda angriper de varje levande inkräktare som stör deras gravar med oheligt hat.",al={"varför är spöken rastlösa","varför hemsöker andar shadowfang","orostillstånd hos spöken i shadowfang"}},["59c03d52"]={q="Arbetar Arugal för Scourge?",a="Nej. Arugal avskyr Scourge. Han tillkallade worgen just för att förgöra dem. Han har blivit galen, men hans lojalitet tillhör hans ”barn”, inte Lich King.",al={"är arugal med i scourge","arugal arbetar för scourge","tjänar arugal scourge"}},["99eb22e3"]={q="Kontrollerar Lich King Arugal?",a="Nej. Arugals galenskap är helt självförvållad och har sin grund i skuld och planarmagi, inte i Frozen Thrones telepatiska grepp. Han verkar självständigt som härskare över sitt eget mörka rike.",al={"kontrollerar lich king arugal","lich king och arugal","kontrolleras arugals sinne"}},["501c4a9b"]={q="Tar förbannelsen slut när Arugal är död?",a="Nej. När Arugal dödas halshuggs Shadowfang Keeps ledarskap, men worgenförbannelsen har redan infekterat dödligas blod i hela skogen. Plågan består långt efter att ärkemagikern fallit.",al={"tar worgenförbannelsen slut","försvinner worgenförbannelsen","är pyrewood botat"}},["6cb01af1"]={q="Kommer Forsaken att ta över Shadowfang Keep?",a="För tillfället nöjer sig Forsaken med att undanröja hotet mot sin södra gräns och återta The Book of Ur. Ruinen förblir ett dystert, hemsökt skal med utsikt över skogen, snarare än en bemannad utpost.",al={"tar forsaken över shadowfang","erövrar forsaken shadowfang","vem styr sfk efteråt"}},["3f22b397"]={q="Hur hamnade jag i Shadowfang Keep?",a="Du följde skräckens spår genom Silverpine Forest till klipporna med utsikt över Pyrewood Village. Om du tjänar Horde blev du troligen skickad söderut från The Sepulcher eller Undercity för att undersöka worgenhotet som kväver området. Om du slåss för Alliance ledde rykten om den förbannade skogen, förlorade heliga reliker eller den fallna Kirin Tor dig djupt in på fientligt Forsaken-territorium. Du klättrade uppför de slingrande klippstigarna bortom Pyrewoods portar, kämpade dig förbi glupska vargbestar och tog dig genom borgens urgamla port till den galne ärkemagikerns näste.",al={"hur hamnade jag här","hur tar jag mig till shadowfang keep","hur hittade jag hit"}},["31a8c552"]={q="Vad förväntas jag göra i Shadowfang Keep?",a="Ditt yttersta mål är att kämpa dig genom de hemsökta salarna och fälla Archmage Arugal för att göra slut på hans förvridna välde över Silverpine. På vägen måste du fälla worgen som stryker genom borggårdarna och kuva de rastlösa andarna efter Baron Silverlaine och hans mördade hushåll. Om du verkar för Forsaken har du fått i uppdrag att återta The Book of Ur och ta reda på vad som hänt Deathstalkers som försvunnit där inne. Alliansens mästare, paladiner och häxmästare söker efter förlorade kraftfulla artefakter, heliga vapen och hämnd för den mörka magi som förgiftar landet.",al={"vad gör jag här","varför är jag här","vad är mitt mål i shadowfang keep"}}},fp="15,249,31.608.0,17.575.0,19.531.1,46.300.1,33.314.0,26.353.0,59.258.0,28.263.0,23.300.0"}
P.entries["zone:shendralas"] = {n="Shen'dralas",s="Shen'dralas är ett kargt och omstritt vildmarksområde mellan Feralas, Mulgore och sydöstra Desolace. Här möts uråldriga lämningar efter nattalver, oroliga gränser, framryckande kentaurer, fördrivna utstötta och stridslystna quilboar.",h="Shen'dralas är ett kargt och omstritt vildmarksområde mellan Feralas, Mulgore och sydöstra Desolace.",kw={"bristleback retreat","desolace","evenshade overlook","feralas","lake dumont","magram front","mulgore","outcast hideaway","shendralas","valley of bones"},ang={["faction:Alliance"]="En avlägsen, omstridd vildmark med alternativa vägar mellan Feralas och centrala Kalimdor. Här lurar faror som kräver ständig vaksamhet.",["faction:Horde"]="Området ligger strax utanför södra Mulgore. Att hålla Magram och quilboar i schack här är avgörande för att skydda Hordens gränstrakter.",["race:NightElf"]="Namnet för tankarna till Eldre'Thalas och det uråldriga högbornearvet. Det väcker uppmärksamhet hos väktare som oroar sig för vårdslös arkana i södra Kalimdor.",["race:Tauren"]="Området gränsar till Mulgore och Desolace. Quilboarernas och kentaurernas aggressivitet längs bergsryggarna hotar de närliggande, förfäders gamla jaktmarkerna direkt."},sec={{t="En orolig gränstrakt",b="Shen'dralas ligger undangömt i högländerna sydost om Desolace, med Mulgore och Feralas som grannar. Det är en karg gränstrakt långt från fraktionernas huvudstäder. I de klippiga passen och gömda enklaverna kämpar desperata grupper för sin överlevnad i Kalimdors vildmark. Från avskilda utsiktsplatser som Evenshade Overlook till laglösa tillhåll som Outcast Hideaway präglas området av dem som vill spana obemärkt eller förbli bortglömda."},{t="Kentaurer, quilboar och uråldriga ruiner",b="Landet bär tydliga spår av det högbornearv som gett det dess namn, men här råder ingen frid. Konflikten mellan kentaurerna sträcker sig över Magram Front och håller gamla blodskulder vid liv längs gränserna. Samtidigt håller framryckande quilboar befästa utposter som Bristleback Retreat, och gör varje skuggig ravin till omstridd mark för resande."},{t="De dödas dal",b="I nordväst leder Valley of Bones mot Desolace. Den dystra korridoren är den främsta landvägen in i Shen'dralas. Sol och vind har blekt passagen, en hård påminnelse om de våldsamma strider som ständigt sköljer genom klippterrängen."}},faq={{q="Var ligger Shen'dralas?",a="Shen'dralas ligger sydost om Desolace, inklämt mellan Feralas och Mulgore. Den som färdas till fots kommer vanligtvis från Desolace genom Valley of Bones.",al={"var ligger shendralas","shendralas läge","hur tar man sig till shendralas"}},{q="Kontrolleras Shen'dralas av Alliansen eller Horden?",a="Ingen av fraktionerna råder här. Shen'dralas är en omstridd gränstrakt med kringströvande kentaurer, fientliga quilboar, utstötta och isolerade läger.",al={"tillhör shendralas horden","tillhör shendralas alliansen","vem styr shendralas"}},{q="Vilka större bosättningar eller landmärken finns här?",a="Viktiga landmärken är Valley of Bones, Bristleback Retreat, Evenshade Overlook, Magram Front, Outcast Hideaway och Shen'dralas centrala vidder.",al={"delområden i shendralas","landmärken i shendralas","sevärdheter i shendralas"}},{q="Varför finns det kentaurer här?",a="Kentaurernas territoriella krig sträcker sig från Desolaces slätter rakt in i området längs Magram Front, där klanen strider mot lokala försvarare och rivaliserande fraktioner.",al={"kentaurer i shendralas","magram front","varför finns magram här"}},{q="Vad är Bristleback Retreat?",a="Bristleback Retreat är en befäst utpost som hålls av Bristlebacks quilboar. De har skaffat sig ett hårt fäste längs områdets utkanter.",al={"bristleback retreat","quilboar i shendralas"}},{q="Hur hänger området ihop med Lake Dumont?",a="Geografiskt ligger Shen'dralas vildmark tvärs över den bergiga terräng där den avskilda Lake Dumont är gömd, enligt gamla kartor från lantmätare.",al={"lake dumont","shendralas kartans historia"}}},fp="11,141,23.322.0,36.313.0,19.222.0,29.144.0,55.152.0,45.155.0,27.159.0,28.132.0,57.115.0"}
P.entries["zone:silithus"] = {n="Silithus",s="Silithus är en ödslig, vindpinad öken längst i sydvästra hörnet av Kalimdor. Under den torra sanden breder väldiga kolonier av insektslika silithider ut sig, tillsammans med de uråldriga ruinerna av Ahn'Qiraj, som förseglades för tusen år sedan bakom den mäktiga The Scarab Wall. I dag håller druiderna i Cenarion Circle en hårt pressad vakt mot framryckande svärmar och domedagskultister.",h="Silithus är en ödslig, vindpinad öken längst i sydvästra hörnet av Kalimdor.",kw={"ahn'qiraj","cenarion hold","hive'ashi","hive'regal","hive'zora","the scarab dais","the scarab wall","silithider","silithus","twilight's hammer"},ang={["class:Druid"]="Som centrum för Cenarion Circles verksamhet i södra Kalimdor kallar Silithus på druider som kan hejda landets fördärv och möta de onaturliga yngel som hotar naturens balans.",["profession:Herbalism"]="Trots den hårda ökenterrängen frodas sällsynta botaniska skatter här, däribland Mountain Silversage, Dreamfoil, Sungrass och den mycket eftertraktade Black Lotus.",["profession:Mining"]="Silithus torra klippor och insektsgångar rymmer några av världens rikaste thoriumfyndigheter, däribland sällsynta ådror täckta av slem och gömda inne i silithidernas kupor.",["race:NightElf"]="Silithus är den dystra gravplatsen där dina förfäder blödde under War of the Shifting Sands och offrade tusentals för att försegla Ahn'Qirajs portar."},sec={{t="Öknens gränsland",b="För att nå Silithus måste du ta dig genom urskogen i Un'Goro Crater och uppför ett brett, stenigt pass i kraterns nordvästra hörn. Övergången är skarp: den frodiga urtida växtligheten försvinner och ersätts av vidsträckta, skiftande sanddyner, taggiga klippor och onaturligt höga kupor. Vatten är i princip obefintligt, och vindarna för med sig surrandet från insektsvingar och sandens viskningar. Cenarion Circle har sitt högkvarter, Cenarion Hold, nära öknens mitt. Det är den enda civiliserade utposten och ett skydd för resenärer, forskare och krigare som trotsar den fientliga ödemarken."},{t="Ekon från den skiftande sanden",b="För tusen år sedan blev denna torra vidsträckta öken slagfältet i War of the Shifting Sands. En allierad armé av nattalver och mäktiga drakflygningar kämpade desperat för att driva tillbaka Qiraji, ett lömskt insektsrike som uppstått ur den uråldriga Aqiri-civilisationen. När en fullständig seger visade sig omöjlig förseglade försvararna svärmarna i deras fäste med The Scarab Wall och det förtrollade The Scarab Dais. Medan de väldiga portarna höll stånd gjorde underjordiska tunnlar det möjligt för de bestlika silithiderna att gräva sig ut och bilda vidsträckta kolonier som Hive'Ashi, Hive'Zora och Hive'Regal ute i sanden."},{t="En storm drar samman",b="Den apokalyptiska kulten Twilight's Hammer har befäst sig i flera utposter och åkallar elementära fasor samtidigt som den vördar den mörka makt som slumrar under Ahn'Qiraj. Cenarion Circles spanare håller uppsikt över silithidkoloniernas utbredning i öknen och det uråldriga hotet bakom The Scarab Wall."}},faq={{q="Hur tar jag mig till Silithus till fots?",a="Ta dig till det nordvästra hörnet av Un'Goro Crater. Nära den slingrande flodkröken, mellan två tydliga naturliga stenpelare, leder en sluttande grusväg uppför kraterns bergiga vägg och rakt in i Silithus öken.",al={"ingången till silithus","hur man tar sig till silithus","vägen till silithus"}},{q="Vad är The Scarab Wall?",a="The Scarab Wall är en väldig, förtrollad barriär i södra Silithus. Den restes för tusen år sedan av nattalverna och drakflygningarna under War of the Shifting Sands för att fängsla det ondskefulla Qiraji-riket i Ahn'Qiraj.",al={"ahn'qirajs port","the scarab wall","den stora muren i silithus"}},{q="Vem styr Cenarion Hold?",a="Cenarion Hold är en utpost som grundats och drivs av Cenarion Circle. Där håller druider och allierade väktare uppsikt över de framryckande silithidsvärmarna, undersöker uråldriga ruiner och välkomnar neutrala resenärer från både Alliance och Horde.",al={"vilka finns i cenarion hold","cenarion holds fraktion","vänliga i cenarion hold"}},{q="Vad är de jättelika insektskullarna runt om i området?",a="De är silithidernas stora underjordiska kupor: Hive'Ashi, Hive'Zora och Hive'Regal. Varje kupa är ett vidsträckt nätverk av tunnlar där olika kaster av insektsvarelser bor och tjänar viljorna som hålls instängda bakom Ahn'Qiraj.",al={"silithus kupor","insektskupor i silithus","hive ashi hive zora"}},{q="Vad gör Twilight's Hammer här?",a="Kulten Twilight's Hammer har flera befästa baser i Silithus, däribland Twilight Base Camp och Twilight Post. De utför vidriga ritualer för att åkalla elementarer och dyrkar de uråldriga, ondskefulla entiteter som begravts bakom The Scarab Wall.",al={"twilight-kultister i silithus","twilight outpost i silithus","varför är twilight's hammer i silithus"}}},fp="8,245,19.408.0,28.509.0,18.272.0,33.207.0,24.219.0,23.205.0,49.212.0,41.243.0"}
P.entries["zone:silverpine"] = {n="Silverpine Forest",s="Silverpine Forest är en kuslig, dimhöljd skog längs Lordaerons västkust, mellan Tirisfal Glades och den förseglade The Greymane Wall. Ärren efter Scourge-pesten dröjer sig kvar, och skogen är Forsakens omstridda sydgräns. Resenärer möter förvildade worgen i skuggorna, sjuka gnoller och fientliga mänskliga enklaver.",h="Silverpine Forest är en kuslig, dimhöljd skog längs Lordaerons västkust, mellan Tirisfal Glades och den...",kw={"ambermill","arugal","fenris isle","the greymane wall","pyrewood","rot hide","the sepulcher","shadowfang","silverpine","silverpine forest"},ang={["class:Mage"]="Närvaron av Ambermill och ärkevisaren Arugals fall i vargaktigt vansinne gör Silverpine till en dyster varning om Kirin Tors magi som gått katastrofalt snett.",["faction:Alliance"]="Utforskare från Alliance möter en djupt fientlig skog, med endast en bräcklig Dalaran-garnison i Ambermill och de tragiska, förbannade byborna i Pyrewood Village.",["race:Undead"]="Silverpine är frontlinjen för Forsakens expansion söder om Tirisfal Glades, där Royal Apothecary Society prövar nya blandningar och Deathguard bekämpar kvarvarande Scourge-agenter."},sec={{t="En hemsökt gränsbygd",b="Silverpine Forest var en gång en grönskande pärla i Lordaeron, där adliga resenärer färdades till Capital City. Men skogen har tynat under tredje krigets grepp. Spöklika dimmor slingrar sig mellan döende tallar med silverfärgad bark, och övergivna gårdar har lämnats åt vildmarken. I norr ligger Tirisfal Glades, medan den östra stranden gränsar till Lordamere Lake. I söder tornar den väldiga, stängda The Greymane Wall upp sig och isolerar kungariket Gilneas från kaoset omkring. Forsaken håller sin centrala utpost vid The Sepulcher och försöker säkra skogen från fiender på alla sidor."},{t="Rivaliserande enklaver och Scourge",b="Forsakens anspråk på Silverpine bestrids häftigt av både levande och odöda fraktioner. I öster, på Fenris Isle, leder Thule Ravenclaw en styrka av kvarvarande Scourge och befaller samtidigt de pestdrabbade Rot Hide-gnollerna som härjar på de norra gårdarna. I söder håller mänskliga magiker från Dalaran den befästa bosättningen Ambermill, där de bedriver mystisk forskning och motsätter sig Forsakens expansion. Royal Apothecary Society och High Executor Hadrec vid The Sepulcher för ett brutal och mångsidig kampanj för att undanröja hoten och pröva nya, virulenta farsoter."},{t="Worgen och Shadowfang",b="Silverpines mest ökända fara är worgenförbannelsen. Högt uppe i den sydvästra skogen ligger Shadowfang Keep, tidigare säte för Baron Silverlaine, men nu under den vansinnige Dalaran-ärkevisaren Arugals kontroll. För att slå tillbaka Scourge under tredje kriget kallade Arugal på vargvidunder från en annan dimension. Varelserna vände sig mot sina besvärjare och spred en varulvsförbannelse över de södra skogarna. I Pyrewood Village sköter mänskliga bybor, som ser helt vanliga ut, sina sysslor i dagsljus, men förvandlas till vildsinta worgen under natthimlen."}},faq={{q="Vad är The Greymane Wall vid den södra gränsen?",a="The Greymane Wall är en väldig stenbarriär som kung Genn Greymane lät bygga för att helt isolera sitt kungarike Gilneas från resten av Lordaeron. När Scourge härjade kontinenten under tredje kriget låste Gilneas sina portar och vägrade ta emot hjälp utifrån. Därmed lämnades länderna norr om muren, däribland södra Silverpine, att klara sig själva.",al={"varför finns det en jättelik mur","the greymane wall i historien","porten till gilneas"}},{q="Varför anfaller byborna i Pyrewood Village om natten?",a="Invånarna i Pyrewood Village är drabbade av ärkevisaren Arugals worgenförbannelse. På dagen behåller de sin mänskliga form och följer sina vanliga rutiner, och är vänligt sinnade mot Alliance. När månen går upp tar förbannelsen över och förvandlar hela befolkningen till vildsinta, blodtörstiga worgen som våldsamt angriper alla i närheten.",al={"mysteriet i pyrewood village","worgen i pyrewood","varför är människorna i pyrewood fientliga om natten"}},{q="Vem är Thule Ravenclaw?",a="Thule Ravenclaw är en mäktig nekromantiker som tjänar Scourge. Från Fenris Keep på Fenris Isle i Lordamere Lake befaller han legioner av odöda och utövar inflytande över de sjuka Rot Hide-gnollerna i östra Silverpine. Han utgör ett direkt hot mot Forsakens östra flank.",al={"vem leder fenris isle","thule ravenclaw i historien","scourge på fenris isle"}},{q="Varför ockuperar Dalaran Ambermill?",a="Ambermill hålls av trollkarlar från Dalaran, ledda av ärkevisaren Ataeric. Från byn bevakar dessa mänskliga magiker Forsakens rörelser, studerar de magiska sjukdomar som plågar skogen och försöker hejda worgenutbrottet från Shadowfang Keep i närheten.",al={"magikerna i ambermill","varför är alliance i ambermill","dalaran i silverpine"}},{q="Vad är The Sepulcher?",a="The Sepulcher är Forsakens främsta militära utpost och knutpunkt för resor i Silverpine Forest. Under ledning av High Executor Hadrec fungerar den som bas för Deathguard-patruller, Deathstalker-spejare och Royal Apothecary Society när de kämpar för att säkra skogen.",al={"horde-stad i silverpine","var finns flygrutten","the sepulcher i historien"}},{q="Kan spelare på Alliance-sidan utföra uppdrag i Silverpine Forest?",a="Silverpine Forest har inga uppdragsnav eller vänligt sinnade städer för Alliance; alla lokala uppdrag är exklusivt för Horde. Äventyrare från Alliance tar sig vanligtvis bara in i skogen på väg från Southshore, för att utforska Shadowfang Keep eller strida mot fientliga Forsaken-styrkor.",al={"är silverpine bara för horde","uppdrag för alliance i silverpine","kan alliance ta sig till silverpine"}}},fx={["21fc6836"]={q="Vad är Silverpine Forest?",a="Silverpine Forest är en vidsträckt, urgammal skog längs Lordaerons karga västkust, precis söder om Tirisfal Glades och med Lordamere Lake som östlig gräns. En gång var det en lummig och grönskande skog som skyddades av Alliance. Nu ligger den insvept i spöklika dimmor och bleka, sjuka tallar, och den kusliga tystnaden bryts bara av ylanden i fjärran. Forsaken härskar i norr från The Sepulcher, men deras anspråk utmanas ständigt av rester av Scourge, vilda Rot Hide-gnoller, Dalarans magiker och de förbannade worgen från Shadowfang Keep.",al={"vad är silverpine","berätta om silverpine","silverpine forests historia"}},["01503e92"]={q="Vad hände i Silverpine Forest?",a="Silverpine liknade en gång The Hinterlands orörda vildmark, men Tredje kriget ödelade skogen. När Lich Kings Scourge svepte söderut brände odöda arméer ner gårdar, slaktade landsbygdens befolkning och smittade marken med de odödas pest. King Genn Greymane stängde in Gilneas bakom sin väldiga mur och övergav de nordliga områdena, däribland Pyrewood och Ambermill. För att slå tillbaka mot Scourge släppte ärkemagikern Arugal lös vilda worgen, men förbannelsen spred sig okontrollerat. När Lordaeron krossades blev den härjade skogen ett omstritt slagfält.",al={"silverpines historia","vad hände här i silverpine","silverpines fall"}},b9edb2aa={q="Vilka bodde här innan Forsaken?",a="Före Tredje kriget bodde människor från Lordaeron och Gilneas i Silverpine. De var bönder, gruvarbetare och soldater. De sydliga bosättningarna, som Pyrewood Village och Ambermill, lämnades utanför när Gilneas stängde in sig bakom The Greymane Wall. På Fenris Isle fanns en livlig militärgarnison från Lordaeron i Fenris Keep. De flesta av de tidigare invånarna dog under Scourges invasion, flydde söderut till den stängda muren eller dukade under för de odödas plåga och worgenförbannelsen.",al={"vilka bodde i silverpine tidigare","silverpines tidigare invånare","silverpines forna invånare"}},["5b2addb4"]={q="Varför ser skogen så död ut?",a="Skogen bär djupa, kvardröjande ärr efter Tredje kriget. Silverpine är det sydligaste området där Scourges pest av odödlighet synligt fördärvade växtligheten. Den sög livskraften ur jorden och lämnade de urgamla tallarna med silverfärgad bark bleka och sjuka, medan fördärvade barr föll från dem. När Lordaeron förstördes och Gilneas stängde sina portar fanns inga vårdare kvar som kunde läka de härjade dungarna eller sköta de nedbrända åkrarna. Kalla dimmor och förruttnelse lade sig över skogen.",al={"varför dör silverpine","varför ser silverpine dött ut","fördärvade träd i silverpine"}},["67376895"]={q="Är Silverpine Forest farligt?",a="Extremt farligt. Vilda rovdjur som fördärvade björnar, jättespindlar och våldsamma worgar stryker under träden. Pestdrabbade Rot Hide-gnoller slaktar våldsamt resenärer längs vägarna, medan mänskliga magiker från Dalaran befäster Ambermill mot Horde-intrång. I söder terroriserar de vilda Moonrage-worgen dalarna under Archmage Arugals välde. Utanför The Sepulchers befästa fristad kräver överlevnad ständig vaksamhet.",al={"hur farligt är silverpine","hot i silverpine","är det säkert här"}},["6dcc337b"]={q="Varför skickade Horde mig till Silverpine Forest?",a="Du skickades söderut från Tirisfal Glades för att förstärka Forsakens gränstrakter. Undercity anser att Silverpine Forest är avgörande för att säkra den södra gränsen, men deras grepp om området är svagt och styrkorna är utspridda. High Executor Hadrec och Deathguard behöver dugliga mästare som kan driva tillbaka Scourges framryckande nekromantiker, utrota fientliga gnoller, hålla uppsikt över Dalarans hemliga manövrer och hejda de blodtörstiga worgen som hotar att ta över skogarna.",al={"varför är jag i silverpine forest","hordes ankomst till silverpine forest","varför skickades jag hit"}},ab9ff98b={q="Är det fortfarande Forsakens land?",a="Forsaken gör anspråk på Silverpine Forest som Undercitys suveräna territorium, men deras kontroll är hårt omstridd. De behärskar norra Silverpine Forest och den befästa tillflyktsorten The Sepulcher, men har inte oinskränkt makt över hela skogen. Fientliga Rot Hide-gnoller härskar över vattnen i öster, Dalarans magiker har ockuperat Ambermill och Arugals vilda worgen dominerar de sydvästra delarna.",al={"äger forsaken silverpine forest","vem kontrollerar silverpine forest","forsakens territorium i silverpine forest"}},["858ebaa5"]={q="Vem byggde The Sepulcher?",a="Före det tredje kriget var The Sepulcher bara en stor, stillsam mänsklig begravningsplats med en krypta vid vägen. Folket i Lordaeron byggde den för att begrava sina döda längs den västra landsvägen. Efter Lordaerons fall tog de överlevande Forsaken över gravplatsen och byggde om kryptan till en befäst militär utpost, karavanstation och logistiskt högkvarter för sina operationer i söder.",al={"vem byggde the sepulcher","the sepulchers ursprung","the sepulchers historia"}},f51f7d3d={q="Varför har Forsaken sin bas vid The Sepulcher?",a="The Sepulcher ligger skyddat bland de västra kullarna och ger Forsaken en naturlig utsiktspunkt över kusten och huvudvägen. Den ligger mellan Scourge i öster, Dalaran i sydöst och vilda worgen i söder. Därför är den den enda säkra utposten där Deathguard-patruller och Royal Apothecary-forskare kan samordna försvaret och skydda vägen till Tirisfal.",al={"varför finns forsaken vid the sepulcher","varför har forsaken en bas vid the sepulcher","the sepulchers betydelse"}},["0581536d"]={q="Vem är High Executor Hadrec?",a="High Executor Hadrec leder Forsakens militära operationer i Silverpine Forest och har sin post vid The Sepulcher. Han är sträng och pragmatisk och styr Deathguard och Deathstalker-spejare när de kuvar vildmarken, avslöjar dolda hot och organiserar anfall mot fientliga styrkor som Thule Ravenclaw och Rot Hide-gnollerna.",al={"hadrec","vem är hadrec","high executor hadrec i silverpine forest"}},ff53d58c={q="Vem rapporterar High Executor Hadrec till?",a="Hadrec rapporterar direkt till Lady Sylvanas Windrunner, Forsakens bansheedrottning, och hennes högsta befäl i Undercity. Som högt uppsatt officer i Deathguard har han i uppdrag att säkra gränserna till hennes nyfödda kungarike och undanröja varje makt som kan hota Forsakens suveränitet.",al={"vem är hadrecs chef","hadrecs överordnade","vem rapporterar hadrec till"}},["6c73f41e"]={q="Vilka är Rot Hide-gnollerna och varför är de här?",a="Rot Hides är en grym gnollklan som lever i Silverpine Forest. De håller främst till på Fenris Isle och stryker längs Lordamere Lakes stränder. Till skillnad från vanliga gnoller är de drabbade av de odödas pest och har fläckig grå päls och rinnande gula ögon. De för ett brutalt gerillakrig mot Forsaken, letar igenom slagfält efter byte och anfaller ursinnigt alla som närmar sig deras läger.",al={"rot hide-gnoller","varför finns gnoller i silverpine forest","rot hide-gnoll i silverpine forest"}},ad054bc9={q="Vem styr Rot Hide-gnollerna?",a="Rot Hide-gnollerna är underkuvade av Thule Ravenclaw, en förrädisk nekromantiker som samarbetar med Scourge. Från sitt fäste på Fenris Isle använder Thule mörk magi för att manipulera de pestdrabbade bestarna och skicka dem till uppgrävda slagfält för att samla färska lik åt sina växande legioner av odöda.",al={"vem befaller rot hides","rot hides ledare","vem leder rot hides"}},["97f89d60"]={q="Vad är The Dead Field?",a="The Dead Field är ett pesthärjat jordbruksområde mitt i Silverpine Forest, längs vägen mot Lordamere Lake. Det var en gång en fridfull bondgård, men blev en massgravsplats under det tredje kriget när Scourge drog fram över Lordaeron. I dag är det en öppen begravningsplats full av grunda gravar och uppgrävd jord.",al={"the dead field i silverpine forest","the dead field","vad är the dead field"}},d487a8f2={q="Varför gräver gnollerna i The Dead Field?",a="Rot Hide-gnollerna gräver upp The Dead Field för att få fram människolik som begravdes där under det tredje kriget. På order av Thule Ravenclaw gräver de upp kroppar och bevarade kvarlevor för att förse nekromantikern med råmaterial till Scourges konstruktioner och förstärka hans odöda armé på Fenris Isle.",al={"varför gräver rot hides","varför är gnollerna vid the dead field","gnoller gräver upp lik"}},["3bca491d"]={q="Vad finns på Fenris Isle?",a="Fenris Isle är en stor ö i Lordamere Lake, utanför Silverpine Forests östra kust. Ön domineras av Fenris Keep, en före detta militär fästning i Lordaeron som förfallit i mörker. I dag är ön ett starkt befäst fäste, fullt av Rot Hide-gnoller och Thule Ravenclaws odöda tjänare.",al={"fenris isle","vad finns på fenris isle","fenris keep"}},bd044bca={q="Varför vill Hadrec att Fenris Isle ska anfallas?",a="Hadrec förstår att Fenris Isle är hjärtat i Scourges hot i östra Silverpine Forest. Om Thule Ravenclaw får sitta kvar i Fenris Keep har Scourge ett ointagligt område att utgå från när de väcker odöda gnoller, plundrar förrådskaravaner och hotar den östra vägen till Tirisfal. Ett anfall mot ön är avgörande för att bryta Thules makt och säkra sjön.",al={"varför anfalla fenris isle","hadrecs motiv för fenris isle"}},["574e415e"]={q="Samarbetar magikerna från Dalaran i Ambermill med Alliance?",a="Ja. Dalaran ägnar sig till stor del åt att återuppbygga sin ödelagda stad, men Kirin Tor-styrkorna vid Ambermill står fortfarande öppet på Alliance sida och är fientligt inställda till Horde. Dalaran skickar ofta hjälp till de överlevande mänskliga enklaverna i Silverpine Forest. De motarbetar Forsakens expansion och samarbetar tätt med kvarvarande styrkor i söder.",al={"ambermill, dalaran och alliance","står dalaran på alliances sida här","kirin tor och alliance i silverpine forest"}},fd7851b2={q="Vem är Arugal och vad är ”Arugals dårskap”?",a="Ärkemagikern Arugal var en magiker från Dalaran som i desperation försökte försvara sig mot Scourge under det tredje kriget. Han tog till förbjuden magi och åkallade monstruösa vargbestarna som kallas worgen. Men de vilda bestarna vände sig mot både Kirin Tors magiker och oskyldiga invånare och spred en glupsk lykantropisk förbannelse över södra Silverpine Forest. Arugal blev vansinnig av skuld och fasa över vad han släppt lös och drog sig tillbaka till Shadowfang Keep, där han tog worgen till sina ”barn”.",al={"arugal","arugals dårskap","vem var arugal","ärkemagikern arugals bakgrund"}},f38b73fd={q="Var kom worgen ifrån?",a="Worgen är vargbestarna från en annan värld som ärkemagikern Arugal drog hit genom dimensionerna. Arugal sökte ett vapen som kunde stärka Dalaran mot Scourge under det tredje kriget och frammana dessa varelser i Silverpine Forest. Där vände de sig snabbt mot dem som åkallat dem och spred en förvandlande förbannelse.",al={"var kom worgen ifrån","worgen i silverpine forest","hur kom worgen hit"}},fc903f13={q="Lever Arugal fortfarande?",a="Ja, ärkemagikern Arugal lever i allra högsta grad. Högt uppe i tornen på Shadowfang Keep, med utsikt över Pyrewood Village, är han insvept i vansinne. Från sin fästning styr han sin flock av Shadowfang-worgen och vaktar sitt förvridna vargrevir mot alla som vågar ta sig in genom portarna.",al={"lever arugal","var är arugal nu","arugals status"}},["5dc043c6"]={q="Vad är Pyrewood Village?",a="Pyrewood Village är en mänsklig bosättning i sydvästra Silverpine Forest, precis nedanför de resliga klipporna vid Shadowfang Keep. Den hamnade utanför när Gilneas förseglade The Greymane Wall före det tredje kriget. De överlevande invånarna kämpar för att upprätthålla ett sken av ett normalt liv om dagarna, men när solen går ner uppslukas de av ett uråldrigt mörker.",al={"pyrewood villages bakgrund","vad är pyrewood","staden pyrewood"}},["20eec241"]={q="Vart leder vägen efter Silverpine Forest?",a="När du har stabiliserat Silverpine Forest genom att konfrontera Thule Ravenclaw och fördriva Arugal från Shadowfang Keep går resan oftast österut över bergen till Hillsbrad Foothills, där du kan hjälpa Forsaken i Tarren Mill. Många Horde-resenärer tar i stället ett zeppelinare till Kalimdor för att strida på The Barrens vidsträckta slätter.",al={"vart efter silverpine forest","nästa zon efter silverpine forest","nästa steg efter silverpine forest"}},da147569={q="Hur hamnade jag i Silverpine Forest?",a="Du följde troligen vägen söderut från Tirisfal Glades och passerade bergspasset sydväst om Undercitys ruiner. Forsaken-figurer säkrar först sitt nordliga hem i Tirisfal och fortsätter sedan naturligt söderut till Silverpine Forest för att utvidga sitt unga imperium. Horde-resenärer från andra kontinenter anländer i stället med zeppelinare utanför Undercity och går sedan längs kusten. Enstaka äventyrare från söder kan ta sig genom Hillsbrad Foothills till dessa pesthärjade skogar.",al={"hur hamnade jag här","hur tar jag mig till silverpine forest","vägen till silverpine forest"}},["97a9302a"]={q="Vad ska jag göra i Silverpine Forest?",a="Du är här för att hjälpa Forsaken säkra sin södra gräns mot växande hot. Rapportera till High Executor Hadrec och Deathstalkers vid The Sepulcher. Du måste hejda de sjuka Rot Hide-gnollerna som plundrar från The Dead Field och Fenris Isle, spåra upp Scourges nekromantiker som Thule Ravenclaw och hålla noggrann uppsikt över Dalarans magiker i Ambermill. Längre söderut ska du också undersöka de glupska vargbestarna som terroriserar Pyrewood Village och skuggan från Shadowfang Keep.",al={"vad är mitt uppdrag här","varför skickades jag till silverpine forest","vad gör vi i silverpine forest"}}},fp="17,230,18.551.0,30.531.1,25.482.1,49.319.0,57.270.1,23.261.1,35.243.0,22.247.0,48.232.0"}
P.entries["zone:stockade"] = {n="The Stockade",s="The Stockade är Stormwinds högsäkerhetsfängelse, beläget under stadens kanalområde nära Mage Quarter. Det byggdes för att hysa rikets farligaste stråtrövare, politiska upprorsmakare och tillfångatagna fiender till staten, men har nyligen förfallit i våldsamt kaos. Warden Thelwater har tvingats tillbaka till ingången och rekryterar desperat dugliga äventyrare för att slå ner upproret inifrån innan det sprider sig till huvudstaden.",h="The Stockade är Stormwinds högsäkerhetsfängelse, beläget under stadens kanalområde nära Mage Quarter.",kw={"bazil thredd","bruegal ironknuckle","kanaler","defias","dextren ward","hamhock","kam deepfury","upplopp","the stockade","stormwind","targorr","warden thelwater"},ang={["class:Mage"]="Fängelset ligger precis vid kanalen i Mage Quarter. Där finns fysiska slagskämpar som är sårbara för bromsande besvärjelser, medan ogremagikern Hamhock kan släppa lös Chain Lightning.",["class:Rogue"]="Fängelsets utformning bjuder på ett intrikat nät av låsta järnceller och kopplingar till Defias. Här får du unik övning i låsdyrkning och insikt i Bazil Thredds undre världssyndikat.",["faction:Alliance"]="Upproret hotar själva hjärtat av huvudstaden. Att slå ner det skyddar Stormwinds inre säkerhet och uppfyller hemliga belöningar från Redridge, Duskwood och Ironforge.",["race:Dwarf"]="Att Kam Deepfury sitter i Stormwinds celler är en skymf mot Dun Modr. Kingdom of Ironforge kräver hans huvud för att hämnas dvärgliv som gått förlorade i Wetlands."},sec={{t="Ett fängelse under belägring",b="Under Stormwinds stillsamma kanaler har The Stockade blivit en krigszon. När den reguljära armén marscherade ut för att strida på avlägsna fronter fick det underbemannade fängelset förlita sig på oerfarna ungdomar, däribland fjortonåriga rekryter, för att upprätthålla ordningen. Det höll inte. Fångarna inledde ett blodigt, samordnat uppror, rev sönder sina yllefiltar till gängsjalar och högg ner de återstående vakterna. Warden Thelwater lyckades nätt och jämnt hålla kontroll över ingången, medan cellerna, korridorerna och förvaringsblocken hamnade i de dömdas skoningslösa händer."},{t="Adelsmän och lönnmördare",b="Upploppet blottlade den fula baksidan av Stormwinds politiska maskineri. Avlägsna områden hade länge varit frustrerade över att House of Nobles stoppade avrättningar för att vinna politisk hävstång. Guard Berton från Redridge ville få den tillfångatagna orchen Targorr the Dread avrättad för sina grymheter, men fick se adelsmännen frysa domen. Councilman Millstipe från Darkshire såg gravplundraren Dextren Ward skonas från galgen trots att han skändat gravar åt nekromantikern Morbent Fel. Till och med dvärgarna i Dun Modr skickade bud och krävde att Dark Iron-sabotören Kam Deepfury skulle dö. När The Stockade föll i kaos anlitade lokala myndigheter i tysthet äventyrare för att verkställa avrättningarna som huvudstadens domstolar vägrade genomföra."},{t="Hjärnan bakom upproret",b="Bakom fängelsets samordnade sammanbrott står Bazil Thredd, en listig brottsling med direkta band till Defias Brotherhood, som organiserade upproret från sin cell. Bland upprorsmakarna finns också Bruegal Ironknuckle, en farlig dvärgslagskämpe. Han är en av flera hårdföra fångar som äventyrare kan stöta på när de hjälper Warden Thelwater att återta fängelset."}},faq={{q="Varför har The Stockade gjort öppet uppror?",a="Defias Brotherhood organiserade ett upplopp i hela fängelset medan anläggningen var kraftigt underbemannad. När Stormwind Army skickades till avlägsna frontlinjer fick tonåriga frivilliga vakta hårdföra mördare. Fångarna överrumplade personalen, lade beslag på vapen och tvingade bort Warden Thelwater från cellblocken.",al={"varför upplopp","vad hände i the stockade","orsaken till upploppet i the stockade"}},{q="Vem leder upproret där inne?",a="Hjärnan bakom revolten är Bazil Thredd, en inflytelserik brottsling från Defias som sitter fängslad i det östra cellblocket. Andra farliga fångar är Bruegal Ironknuckle, Hamhock och Kam Deepfury.",al={"boss i the stockade","vem leder upploppet","vem styr the stockade"}},{q="Varför lever fångar som Targorr och Dextren Ward fortfarande?",a="Båda dömdes till döden, men korrupta politiker i House of Nobles lade byråkratiska hinder i vägen för avrättningarna för att använda dem som politisk hävstång. Inblandningen upprörde allierade i Lakeshire och Darkshire, som skickade äventyrare för att undanröja fångarna under kaoset.",al={"varför avrättades inte targorr","dextren ward och domstolen","korruption i house of nobles"}},{q="Vad innebär det för fängelset att besegra Bruegal Ironknuckle?",a="Bruegal Ironknuckle är en farlig dvärgslagskämpe bland upprorsmakarna. När äventyrarna besegrar honom avlägsnar de ett hot mot fängelset medan de arbetar för att slå ner upproret.",al={"bruegal ironknuckles historia","döda bruegal","vem är bruegal"}},{q="Varför finns Dark Iron-dvärgar och orcher i ett människofängelse?",a="The Stockade fungerar som ett högsäkerhetsförvar för krigsfångar av stort värde. Targorr the Dread ledde Blackrock-orchernas attacker i Redridge, medan Kam Deepfury utförde sabotage för Dark Iron-klanen i Wetlands. Båda tillfångatogs och fördes till huvudstaden.",al={"varför är dark iron-dvärgar här","kam deepfurys historia","targorr i the stockade"}},{q="Kan Horde-spelare gå in i The Stockade?",a="Ja, men det är ytterst farligt. Fängelseingången ligger mitt i Stormwind City, nära kanalerna i Mage Quarter. Horde-infiltratörer måste smyga förbi stadsvakterna och huvudstadens försvarare för att nå portalen.",al={"kan horde göra the stockade","horde i stormwinds fängelse"}}},fx={["07af5e0b"]={q="Vad är The Stockade?",a="The Stockade är Stormwinds högsäkerhetsfängelse, byggt under huvudstadens kanaldistrikt. Där hålls småtjuvar, mördare, politiska upprorsmakare och rikets mest kända fiender i väntan på dom.",al={"vad är stormwind stockade","stockades fängelse","stormwinds fängelse"}},["2fc364a6"]={q="Är The Stockade bara till för Defias?",a="Nej. Även om Defias Brotherhood utgör upprorets kärna finns här småtjuvar, gravplundrare som Dextren Ward, tillfångatagna Blackrock-orcher som Targorr the Dread och till och med Dark Iron-sabotörer som Kam Deepfury.",al={"är stockade bara för defias","vem finns i stockade","är alla fångar defias"}},["0d433487"]={q="Varför sitter så många Defias fångna här?",a="Stormwinds myndigheter har gripit medlemmar av Brotherhood i Westfall, Elwynn Forest och själva staden. I stället för att avrätta dem direkt har kronan fört dem till The Stockade och samlat ett lättrört nätverk av upprorsmakare precis under stadens golvbrädor.",al={"varför så många defias här","varför defias i stockade","defias brotherhood-fångar"}},e96a18b2={q="Vem styr det här fängelset?",a="Warden Thelwater ansvarar för anläggningen. När upproret bröt ut blev hans vakter övermannade och bortdrivna från cellblocken. Thelwater lyckades nätt och jämnt hålla ingången och försöker nu desperat rekrytera dugliga äventyrare för att återta korridorerna.",al={"vem styr stockade","fängelsevakt i stockade","warden thelwater"}},["06cbacdc"]={q="Varför kan inte Warden Thelwaters vakter hantera upploppet?",a="Fängelsevakterna var redan hårt ansträngda och tog till och med hjälp av volontärer så unga som fjorton år för att bevaka farliga fångar. När Defias slöt sig samman och anföll blev personalen helt överrumplad, massakrerad eller tvungen att fly till entréhallen.",al={"varför kan inte vakterna stoppa upploppet","var är fängelsevakterna","vakterna i stockade"}},["7c158547"]={q="Varför skickar Stormwind in mig i stället för armén?",a="Stora delar av Stormwinds militär är utplacerade vid avlägsna fronter, och korrupt byråkrati i House of Nobles lamslår snabba kommunala insatser. Stadens tjänstemän är dessutom desperata att hålla upploppet hemligt för att undvika panik på gatorna.",al={"varför skicka äventyrare","varför inte armén till stockade","var är stormwinds armé"}},a2006c52={q="Vet vakterna utanför vad som pågår där inne?",a="Vakterna håller upprorsmakarna vid fängelseingången, och Warden Thelwater söker hjälp med att återställa ordningen där inne. Stadens tjänstemän håller störningen hemlig för att inte oroa vanligt folk.",al={"vet vakterna utanför","känner stormwind till upploppet","stockades hemlighet"}},b1798127={q="Vad är skillnaden mellan fångarna, brottslingarna och upprorsmakarna här inne?",a="Fångarna är allt från vanliga skurkar och ficktjuvar som plockats upp från gatorna till dömda förbrytare och hårdföra Defias-upprorsmakare. De vanliga brottslingarna tog chansen att göra uppror och plundra, medan upprorsmakarna aktivt lyder Bazil Thredds order om att ta över fängelset.",al={"dömda brottslingar upprorsmakare fångar","fiendetyper i stockade","vilka är fångarna"}},["378bbf14"]={q="Hur fick fångarna tag på vapen och organiserade sig?",a="Upproret planerades noggrant av Defias-ledaren Bazil Thredd. På hans order slet fångarna sina yllefiltar i röda gängsjalar, överföll de underbemannade vakterna, stal deras vapen och nycklar och befriade metodiskt cellerna i varje flygel.",al={"hur fick fångarna vapen","hur organiserade sig defias","vem beväpnade fångarna"}},["855deb71"]={q="Varför ligger ett fängelse mitt under staden?",a="Fängelseanläggningen ligger under Stormwinds kanaler. Dess ursprungliga placering förklaras inte.",al={"varför fängelse under stormwind","stockades plats och orsak","fängelse under kanalerna"}},caa2e4bf={q="Hur hamnade jag i The Stockade?",a="Du gick genom de tunga järndörrarna vid de norra kanalerna i Stormwind City. Ett massivt upplopp bröt ut under gatorna, och Warden Thelwaters återstående vakter tvingades tillbaka till ingången, så fångarna tog kontrollen. I desperation att hålla kaoset dolt för invånarna ovanför rekryterade fångvaktaren dugliga äventyrare för att marschera rakt ner i cellblocken och återta anläggningen med våld.",al={"hur hamnade jag här","varför kom jag hit","hur kom jag in i stockade"}},["45edc40e"]={q="Vad ska jag göra i The Stockade?",a="Ditt främsta uppdrag är att krossa upproret och göra slut på dess ledare, Defias-hjärnan Bazil Thredd. Men allierade runt om i riket har tagit tillfället i akt att driva in gamla skulder: Darkshire vill hämnas på gravplundraren Dextren Ward, Lakeshire vill se den hänsynslösa orchen Targorr the Dread död, och Ironforge kräver huvudet av sabotören Kam Deepfury.",al={"vad är mitt uppdrag här","vad gör jag här","varför är jag här"}}},fp="12,345,20.476.0,20.680.1,30.277.1,38.302.0,35.174.0,60.285.0,60.151.0,61.253.0,37.213.0"}
P.entries["zone:stonetalon"] = {n="Stonetalon Mountains",s="Stonetalon Mountains är en karg bergskedja med vindnötta, klippiga toppar, som gränsar till Ashenvale, The Barrens och Desolace. Nattalver och tauren vördar området som en helig fristad, och dess heliga höjder står i skarp kontrast till röken och maskinerna som kväver de lägre ravinerna. I dag slits bergen sönder av skogsskövling, våldsam elementförödelse och pyrande gränskonflikter.",h="Stonetalon Mountains är en karg bergskedja med vindnötta, klippiga toppar, som gränsar till Ashenvale, The...",kw={"the charred vale","gerenzo wrenchwhistle","malaka'jin","stonetalon","stonetalon peak","sun rock retreat","talondeep pass","windshear"},ang={["class:Druid"]="Skändningen av Windshear Crag och den förbrända förpestningen i The Charred Vale är en allvarlig kallelse till druider som vill lugna ursinniga naturandar och skydda heliga boplatser.",["class:Shaman"]="Bergsandeväsendena ropar under goblinernas borrmaskiner, och deras rop hörs ända till Orgrimmar. De kallar på schamaner som ska hejda de härjande stenelementalerna och återställa balansen på topparna.",["faction:Alliance"]="Från sina poster högt uppe på Stonetalon Peak och i dolda läger runt Windshear Crag försvarar Alliance de uråldriga kaldorei-gravhögarna mot goblinernas maskiner och rivaler som tränger in på deras territorium.",["faction:Horde"]="Horde-äventyrare förlitar sig på den avskilda tillflyktsorten Sun Rock Retreat och trollernas utpost Malaka'jin i söder för att hejda Venture Companys industriella föroreningar och driva bort förrädiska Grimtotem-banditer."},sec={{t="De olycksbådande vindarna och topparna",b="Stonetalon Mountains reser sig brant ur centrala Kalimdor och fångar upp fukten från de västra haven, vilket ger plötsliga skyfall och förrädiska, regnhala sandstensstigar. De lägre dalarnas främsta kännetecken är den oupphörliga, piskande stormvinden som kallas Ill Winds. Den kan blända resenärer med grus eller slunga de oförsiktiga rakt utför lodräta klippväggar. Högre upp täcker ständigt gröna skogar åsarna kring Stonetalon Peak, där nattalver sköter förfädernas gravhögar och gläntor och vakar över de heliga boplatserna för wyverner och hippogryfer som häckar längs Mirkfallon Lake."},{t="Industri och intrång",b="Bergskedjans fridfulla avskildhet har brutits brutalt av Venture Companys ankomst. Gobliner har anlagt vidsträckta skogshuggarläger och grävt djupa dagbrott i Windshear Crag. Med hjälp av den sinnessjuke spetälskgnomen Gerenzo Wrenchwhistle har de kalhuggit gammelskogen, förmörkat himlen med ugnsrök och hällt industriellt slam i bergsbäckarna. Deras girighet har mötts av snabba motåtgärder: lokala schamaner från Orgrimmar svarade på bergsandeväsendena plågade rop, medan små alliansläger i närheten kämpar mot fördärvarna för att skydda det som återstår av höglandet."},{t="Ärr från det förflutna",b="I söder ligger The Charred Vale, en gång en blomstrande vildmark, nu en askbeklädd ödemark där vilda eldelementaler, svarta drakspawn och harpyor härjar. Topparna var den historiska plats där Horde och Alliance slöt en bräcklig vapenvila under det tredje kriget, vägledda av den mystiska Oraklet, men relationerna är nu på väg att försämras. Avfälliga Grimtotem-tauren håller till i beslagtagna läger, och Darkspear Trolls i Malaka'jin drabbar samman med Alliance-styrkor som tränger fram från The Barrens och Ashenvale."}},faq={{q="Hur tar jag mig till Stonetalon Mountains?",a="De flesta resenärer tar sig in via Talondeep Pass, en bergsstig som leder in i bergskedjan från sydvästra Ashenvale. Det finns också höga stigar söderut mot Desolace och leder som går österut, ner i The Barrens norra vidder.",al={"ingång till stonetalon","hur tar man sig till stonetalon","väg till stonetalon"}},{q="Varför är The Charred Vale bränd och förstörd?",a="The Charred Vale var en gång en grönskande fristad, men en katastrofal förödelse slukade dalen i lågor. Den har förvandlats till en pyrande ruin där aggressiva eldelementaler, vilda drakar och dödliga harpyor härjar.",al={"elden i charred vale","vad hände med charred vale","varför brann charred vale"}},{q="Vad gör Venture Company i Windshear Crag?",a="Venture Company kalhugger skoningslöst skogen och borrar djupt in i bergssidan efter mineralrikedomar. Verksamheten har förorenat Cragpool Lake med motorfett, skövlat dalarna och gjort de lokala andarna och invånarna ursinniga.",al={"venture company i stonetalon","gobliner i windshear crag","varför hugger gobliner ner träd"}},{q="Var finns de viktigaste flygmästarna?",a="Alliance-hjältar använder flygmästaren vid den högt belägna helgedomen på Stonetalon Peak i norr, medan Horde-äventyrare har sin bas i bergsbyn Sun Rock Retreat i mitten av bergskedjan.",al={"flygrutt i stonetalon","var finns flygpunkten i stonetalon","stonetalon fp"}},{q="Vad hände vid Stonetalon Peak under det tredje kriget?",a="Vägledda av profeten Medivhs syner klättrade Thrall och Jaina Proudmoore genom grottorna i Stonetalon Peak i jakt på Oraklet. Där slöt de två fraktionsledarna den historiska tillfälliga allians som förenade dem mot Burning Legion vid Mount Hyjal.",al={"stonetalon peak historia","oraklet i stonetalon","tredje kriget i stonetalon"}},{q="Vilka är Grimtotem i Stonetalon?",a="Grimtotem är en hänsynslös, utbrytargrupp av tauren som är fientlig mot utomståendes inflytande. I Stonetalons har de ockuperat en bergspost nära gränsen till The Barrens, där de terroriserar resenärer och tar fångar.",al={"grimtotem post","grimtotem i stonetalon"}}},fx={["4946a833"]={q="Vad är Stonetalon Mountains?",a="Stonetalon Mountains är en karg, vindpinad bergskedja mitt i Kalimdor, väster om The Barrens, söder om Ashenvale och norr om Desolace. Området är känt för sina extrema vindar, djupa raviner och branta sandstenstoppar som skapades under den stora delningen. Det utgör ett historiskt gränsland där nattalver och tauren har levt sida vid sida i generationer. De höga, heliga topparna är fortfarande lummiga av ständigt gröna träd, medan de lägre dalarna är torra, steniga och svårt sargade av industrin.",al={"stonetalon mountains-zon","vad är stonetalon","om stonetalon mountains"}},["4e995438"]={q="Är Stonetalon Mountains farligt?",a="Ja, resenärer möter både naturens faror och våldsamma fiender. Våldsamma stormbyar och plötsligt regn kan göra de höga sandstensklipporna så hala att folk störtar mot sin död. Förutom vädret kryllar bergen av aggressiva Bloodfury-harpior, rovgiriga wyverner, spindlar, kobolder och ursinniga elementarer. Venture Companys hänsynslösa maskiner och beväpnade vakter gör dessutom omstridda dalar som Windshear Crag ytterst farliga.",al={"fara i stonetalon","är stonetalon säkert","faror i stonetalon"}},["9d849e11"]={q="Vilka bor i Stonetalon Mountains?",a="Området är hem åt utspridda fraktioner snarare än en enda styrande makt. Nattalverna håller till vid Stonetalon Peak och vaktar heliga platser uppe i bergen, medan Horde har bosättningar vid Sun Rock Retreat och trollbyn Malaka'jin. De inhemska Bloodfury-harpiorna häckar bland klipporna, fientliga Grimtotem-tauren håller till vid närliggande utposter och det goblinledda Venture Company ockuperar avskogade områden kring Windshear Crag.",al={"vilka bor i stonetalon","stonetalons fraktioner","invånare i stonetalon"}},a4f73e64={q="Varför avverkar Venture Company skog i Windshear Crag?",a="Venture Company är ett hänsynslöst handelskonglomerat som söker vinst genom att utarma naturresurser utan begränsningar. I Windshear Crag kalhugger de uråldriga skogar med tunga maskiner som Super Reaper 6000 och spränger marken efter värdefull malm. Deras hänsynslöshet fyller luften med sot och förgiftar vattnet med slam och olja, vilket väcker hårt motstånd från både lokala druider och Horde.",al={"venture companys skogsavverkning","varför fäller gobliner träd","venture companys timmer i stonetalon"}},["66935983"]={q="Vem leder Venture Company i Windshear Crag?",a="Den lokala avverkningen och gruvdriften i Windshear Crag leds av en spetälsk gnom vid namn Gerenzo Wrenchwhistle. Gerenzo övervakar kalhuggningen från en plattform högt ovanför Cragpool Lake och använder sin mekaniska expertis för att maximera förödelsen. Hans olagliga verksamhet har till och med väckt vrede hos rivaliserande goblinuppfinnare från Tinkers' Union, som vill röja honom ur vägen.",al={"vem styr windshear crag","gerenzo wrenchwhistle","venture companys ledare i stonetalon"}},ff0da62d={q="Vilka är Bloodfury-harpiorna?",a="Bloodfury-harpiorna är en våldsam stam av fågelkvinnor som hör hemma i Stonetalon Mountains. Historiskt sett var bergen deras förfäders hemtrakter innan de spred sig till The Barrens och vidare. De försvarar sitt territorium aggressivt mot främlingar, fångar lokala bestar och drabbar samman våldsamt med både tauren-pilgrimer och goblinmaskiner som tränger sig på i områden som The Charred Vale.",al={"bloodfury-harpior","stonetalons harpyor","vilka är harpiorna här"}},["66599fe7"]={q="Vad är Sun Rock Retreat?",a="Sun Rock Retreat är en fridfull Horde-bosättning i en avskild bergsdal söder om Mirkfallon Lake. Den är den främsta basen för tauren och orcher i området och hyser schamaner och druider som försöker återställa marken efter Venture Companys föroreningar och bekämpa hoten mot de heliga bergen.",al={"sun rock retreats historia","vad är sun rock retreat","sun rock och tauren"}},["5a5a6e9c"]={q="Varför bosatte sig tauren i Sun Rock Retreat?",a="I generationer har tauren vördat dalen för dess starka band till andevärlden. Enligt gamla legender kysste solguden An'she toppen där tillflyktsorten ligger. Tauren har länge vallfärdat hit för att tala med andar och tända stora rituella bål som lyser upp de skuggiga bergen.",al={"varför bosatte sig tauren i sun rock","sun rock retreats historia","an'she och sun rock"}},["51d42c77"]={q="Vad är Windshear Crag?",a="Windshear Crag var en gång en grönskande urskog, men har ödelagts av industriell exploatering. Venture Company kalhögg dalen och lämnade efter sig en karg vidsträckt mark av stubbar, jord och rykande maskiner. Med Venture Companys skogsskövling, förorenade avrinning i Cragpool Lake och kobolder som tagit över den lokala gruvan står platsen som ett förstört monument över tygellös girighet.",al={"om windshear crag","windshear crag-zon","windshear crags bakgrund"}},d850bc0a={q="Vad finns i Windshear Mine?",a="Windshear Mine, som ligger i de sydöstra klipporna i Windshear Crag, har tagits över av aggressiva Windshear-kobolder. Sedan de vanliga gruvarbetarna drivits bort eller övergett gruvan gräver kobolderna nu ursinnigt efter ådror av Smoky Iron Ingots och angriper våldsamt alla som försöker tränga in i deras underjordiska grävschakt.",al={"kobolder i windshear mine","vad finns i windshear mine","smoky iron i windshear mine"}},d3863c46={q="Vad är The Talon Den på Stonetalon Peak?",a="The Talon Den är en uråldrig nattalvisk gravhåla uthuggen i höjderna på Stonetalon Peak. Den sköts av Cenarion-druider som samråder med naturens andar och The Emerald Dream. Djupt där inne har druider traditionellt sovit i helig kontemplation, skyddade av dryader, väktare och bergets magiska försvar.",al={"talon den","the den på stonetalon peak","gravhåla i stonetalon"}},a547ffd6={q="Har Ashenvale en förbindelse till Stonetalon Mountains?",a="Ja. Den karga bergspassagen The Talondeep Path förbinder sydvästra Ashenvale direkt med nordöstra Stonetalon Mountains genom en grottliknande tunnel. Resenärer och äventyrare färdas ofta mellan Ashenvales orörda, omstridda skogar och Stonetalon-kedjans karga höjder när de spårar hot från Venture Company eller de pågående fraktionskonflikterna.",al={"hur förbinds ashenvale med stonetalon","the talondeep path i ashenvale","gränsen mellan ashenvale och stonetalon"}},a5c2784c={q="Hur hamnade jag i Stonetalon Mountains?",a="De flesta resenärer når de här taggiga höjderna via The Talondeep Path, en uråldrig bergstunnel uthuggen i sydvästra Ashenvale. Andra vandrare klättrar uppför de karga stigarna västerut från The Barrens och tar sig genom de vindpinade passen in bland klipporna. Oavsett om nattalviska befälhavare i Astranaar skickat dig söderut eller du sänts västerut över den svedda gränsen från The Crossroads, möts alla som gör den mödosamma färden till bergskedjan av de höga ravinerna och de ylande Ill Winds.",al={"hur hamnade jag här","hur tar jag mig till stonetalon","ankomst till stonetalon"}},["4abc7ef6"]={q="Vad förväntas jag göra i Stonetalon Mountains?",a="Du är här för att möta de växande hot som skövlar dessa heliga höjder. I Windshear Crag river Venture Companys hänsynslösa gobliner ner uråldriga skogar och förorenar floderna med sina maskiner, vilket väcker båda fraktionernas vrede. Samtidigt skapar Grimtotem-stammen oroligheter längs den östra gränsen, medan våldsamma harpyor och rasande eldelementaler härjar i den svedda sänkan Charred Vale. Du måste hjälpa dina allierade att driva bort förorenarna och monstren för att skydda landet.",al={"vad ska jag göra här","varför är jag här","vad är mitt uppdrag i stonetalon"}}},fp="20,167,27.462.0,22.461.0,17.474.0,41.202.0,42.194.0,52.224.0,42.161.0,54.229.0,36.181.0"}
P.entries["zone:stormwind"] = {n="Stormwind City",s="I Stormwind City vilar kronan på en ung prins medan kung Varian är försvunnen. Staden återuppbyggdes efter det första kriget och är nu Grand Alliances hjärta, även om skulder och politisk oro präglar dess distrikt i vit sten.",h="I Stormwind City vilar kronan på en ung prins medan kung Varian är försvunnen.",kw={"anduin","bolvar","katedral","deeprun","prestor","stenhuggare","stormwind","vancleef","wrynn"},ang={["class:Paladin"]="Som paladin hittar du Cathedral of Light, den främsta helgedomen för din tro i södern. Där utbildas Silver Hands riddare och rättvisan upprätthålls.",["class:Rogue"]="Som rogue hittar du SI:7:s högkvarter under Old Towns stenlagda gator. Därifrån sköts Alliansens främsta nätverk för underrättelser och spionage.",["faction:Alliance"]="Som medlem i Alliansen kan du räkna med Stormwinds sjömakt, andliga förankring och viktiga diplomatiska ledarskap. Det är Grand Alliances folkrikaste storstad.",["race:Dwarf"]="Som dvärg kan du ta Deeprun Tram till dina fränder i Dwarven District. De upprätthåller nära handels- och militärförbindelser med människornas rike.",["race:Human"]="Som människa är Stormwind ditt folks sista stora säte för självständig makt sedan Lordaeron, Alterac och Dalaran föll i norr."},sec={{t="Upp ur askan",b="Stormwind grundades för över tusen år sedan av ättlingar till Arathi. I generationer var det ett blomstrande och självförsörjande rike. Orcish Horde tog sig genom The Dark Portal och ödelade den södra kontinenten. Under det första kriget jämnade de huvudstaden med marken. De överlevande följde Sir Anduin Lothar norrut över Great Sea till Lordaeron. Efter att Horden besegrats i det andra kriget bekostade King Terenas Menethil II och Alliansen återuppbyggnaden av staden. Stonemasons Guild byggde upp New Stormwind av polerad vit sten, med kanaler genom stadsdelarna."},{t="Ett splittrat hov",b="Stormwinds storslagna yttre döljer ett skuldsatt rike och ett splittrat hov. House of Nobles och Stonemasons Guild tvistade om lönerna, och konflikten lämnade riket förlamat av skulder. Guildens arbetare gjorde uppror och drevs ut ur staden de hade byggt. King Varian Wrynn har försvunnit på väg till ett diplomatiskt toppmöte. För att hålla paniken stången gick kronan till hans tioårige son, Prince Anduin Wrynn. Highlord Bolvar Fordragon styr nu som regent och militär befälhavare, med den kungliga rådgivaren Lady Katrana Prestor vid sin sida."},{t="Grand Alliances hjärta",b="Sedan Scourge intog Lordaeron har Stormwind blivit mänsklighetens främsta tillflyktsort och Alliansens centrum. High Tinker Mekkatorques underjordiska Deeprun Tram förbinder staden direkt med Ironforge, dvärgarnas rike. På andra sidan Valley of Heroes hedrar väldiga statyer Sons of Lothar, som försvann bortom The Dark Portal. De troende söker sig till Cathedral of Light, medan Wizard’s Sanctum rymmer studier i arkana konster. Handel, kultur och försvar över de södra haven möts alla i Stormwind."},{t="Vart murarna tog vägen",b="Stenhuggarna samlades på nytt i Westfall under sin gilmästare Edwin VanCleef. Där blev de Defias Brotherhood, rödmaskerade banditer som nu stryper rikets jordbruk. De som byggde Stormwinds vita murar har svurit att få House of Nobles att betala för varje sten."},{t="En vän vid hovet",b="Defias Brotherhood fick hjälp innanför Stormwind Keeps murar. Lord Gregor Lescovar från House of Nobles samarbetade i hemlighet med brödraskapet och läckte rikets planer, samtidigt som han satt bland de adelsmän som hade lurat stenhuggarna."},{t="Skuggor i fästet",b="Lady Katrana Prestor har i hemlighet styrt House of Nobles beslut. Hon eldade på konflikten med stenhuggarna och ignorerade vädjanden om militär hjälp från bosättningar som Westfall och Redridge. Hon viskade också gift i Highlord Bolvars öra och höll Stormwinds legioner overksamma och splittrade, medan oron utanför stadsmurarna hotar tronen."}},faq={{q="Vem styr Stormwind just nu?",a="Den tioårige Prince Anduin Wrynn bär Stormwinds krona, medan Highlord Bolvar Fordragon regerar som regent och för befäl över stadens militär. Bolvar förlitar sig på den kungliga rådgivaren Lady Katrana Prestors råd medan King Varian Wrynn fortfarande är försvunnen.",al={"nuvarande kung","vem är kungen","vem leder stormwind","stormwinds kung"}},{q="Vad hände med King Varian Wrynn?",a="King Varian försvann under misstänkta omständigheter när han seglade till ett diplomatiskt toppmöte i Theramore. Hans försvinnande hölls hemligt för att bevara stabiliteten, men rykten spreds genom gatorna och landsbygden.",al={"var är varian","försvunnen kung","varian borta","varian wrynn försvunnen"}},{q="Varför återuppbyggdes staden, och av vem?",a="Orcish Horde brände ner den ursprungliga staden under det första kriget. Efter det andra kriget finansierade Alliance of Lordaeron återuppbyggnaden, och mästerhantverkaren Edwin VanCleef ledde Stonemasons Guild när de reste huvudstaden i vit sten.",al={"vem återuppbyggde stormwind","stonemasons guild","new stormwind","stadens återuppbyggnad"}},{q="Varför gjorde stenhuggarna uppror mot kronan?",a="House of Nobles drog på sig stora skulder när Stormwinds militär byggdes ut och vägrade sedan betala Stonemasons Guild de utlovade lönerna. När Edwin VanCleef krävde betalning upplöste adelsmännen gillet. Arbetarna gjorde uppror och drevs ut ur staden.",al={"defias ursprung","varför är defias arga","stenhuggarnas uppror"}},{q="Vilka föreställer de väldiga statyerna i Valley of Heroes?",a="Valley of Heroes hedrar Sons of Lothar: General Turalyon, Ranger Captain Alleria Windrunner, Archmage Khadgar, Kurdran Wildhammer och Danath Trollbane. Statyerna minner om hjältarna som gick genom The Dark Portal till draenor för att försegla rämnan och skydda Azeroth.",al={"statyerna vid ingången","statyerna i valley of heroes","sons of lothars statyer"}},{q="Hur förbinds Stormwind med Ironforge?",a="Deeprun Tram, en underjordisk järnväg, förbinder Stormwind med Ironforge. High Tinker Gelbin Mekkatorque byggde den på begäran av King Magni Bronzebeard, så att huvudstäderna snabbt kunde handla med varandra och ge varandra förstärkningar i krig.",al={"deeprun tram","tåg till ironforge","hur tar man sig till ironforge"}},{q="Varför skickar Stormwind inga trupper för att hjälpa Westfall och Redridge?",a="Det kungliga hovet, med Lady Katrana Prestor som vägledare, säger att Stormwind inte kan undvara trupper från stadens murar och närliggande gränser. Rikets finanser är ansträngda, och politiska stridigheter har förlamat House of Nobles. Därför måste regionens städer förlita sig på sina lokala miliser.",al={"stormwinds armé saknas","varför får westfall ingen hjälp","förstärkningar nekades"}}},fx={["9beefbfb"]={q="Vad är Stormwind City?",a="Stormwind City är huvudstaden i människornas kungarike Stormwind och mänsklighetens största kvarvarande fäste i Azeroth. Staden byggdes norr om Elwynn Forest längs kusten och är Grand Alliances pulserande hjärta, främsta hamn och kulturella centrum. Efter att ha återuppbyggts ur askan från det första kriget skyddar dess befästa stenmurar hantverkare, lärda, soldater och flyktingar, som ser staden som en symbol för människornas uthållighet.",al={"om stormwind city","stormwind som huvudstad","vad är stormwind"}},edb1c1aa={q="Vad hände med Stormwind City förr i tiden?",a="Kungariket grundades ursprungligen för över tusen år sedan av ättlingar till Arathor-blodslinjen och blomstrade i århundraden genom konflikter med gnoller och djungeltroll. Men under det första kriget belägrade den orciska Horden huvudstaden. Efter mordet på kung Llane Wrynn, som blev en tragedi, stormades staden, plundrades och brändes ner till grunden. Sir Anduin Lothar ledde de överlevande flyktingarna norrut över havet till Lordaeron. De återvände först efter det andra kriget för att återta sitt hemland och bygga upp det på nytt.",al={"stormwinds historia","stormwinds förstörelse","stormwind under det första kriget"}},d0a4b7c8={q="Är Stormwind City farligt?",a="Bakom sina kolossala portar och vaksamma stadsvakt är Stormwind en av världens mest välbefästa fristäder. Men osedda faror lurar därinne. Våldsamma upplopp har brutit ut i det närbelägna Stockade, kultister och tjuvar smyger längs de skuggade kanalerna och politiska oroligheter som Defias Brotherhood satt i gång håller adelsrådet på helspänn. Öppen krigföring bryter sällan igenom murarna, men korruption, förräderi och dolda konspirationer viskar genom både Keep och gränderna.",al={"är stormwind säkert","faror i stormwind","hot mot stormwind"}},["163d181d"]={q="Vilka är Defias Brotherhood?",a="Defias Brotherhood är ett hänsynslöst gille av laglösa, banditer, tjuvar och pirater som öppet hotar kungarikets stabilitet. De känns igen på sina röda bandanas, som de bär för att symbolisera blodet som spillts för deras sak. Även om de främst verkar i Westfall, Redridge och Deadmines når deras inflytande ända in i Stormwind, där deras spioner och sympatisörer undergräver kronans makt och sprider splittring bland arbetarklassen.",al={"defias brotherhood","vilka är defias","defias-gänget"}},b1d432aa={q="Vad är Cathedral of Light?",a="Cathedral of Light reser sig högt över Cathedral Square och är mänsklighetens och Grand Alliances främsta andliga centrum. Den återuppbyggdes efter det andra kriget under ärkebiskop Alonsus Faol och dåvarande biskop Benedictus. Här finns Church of the Holy Lights säte och Order of the Silver Hands högkvarter. Paladiner och präster reser från hela rikena för att träna, söka visdom och meditera i dess storslagna, fridfulla salar.",al={"cathedral of light","stormwinds katedral","ljuskyrkan i stormwind"}},["3414b788"]={q="Hur hamnade jag i Stormwind City?",a="Om du inledde din resa i Northshire och tog dig genom Elwynn Forest ledde huvudvägen dig rakt genom Valley of Heroes och in genom huvudstadens befästa portar. Om du kommer från Dun Morogh eller Ironforge gick du troligen ombord på Deeprun Tram, gnomernas ingenjörsunderverk som förbinder dvärgarnas fäste direkt med Dwarven District under bergen. Resenärer från andra delar av Azeroth når Stormwinds portar efter långa färder genom de södra rikena, på jakt efter mänsklighetens sista stora fäste.",al={"hur hamnade jag här","hur kom jag till stormwind","hur tog jag mig till stormwind"}},["68c43aeb"]={q="Vad förväntas jag göra i Stormwind City?",a="Stormwind är Alliances pulserande hjärta och en fristad där du kan vila, träna och skaffa förnödenheter. Bakom de glänsande vita murarna är kungariket dock djupt splittrat. Kung Varian Wrynn har försvunnit under mystiska omständigheter, och pojkkungen Anduin och Highlord Bolvar Fordragon kämpar med politisk handlingsförlamning i Keep. Samtidigt ropar gränstrakterna i Westfall och Redridge efter hjälp mot den utbredda banditverksamheten, medan Defias Brotherhood smider planer i skuggorna. Du är här för att vässa dina färdigheter, rapportera till dina fraktionsledare och låna ut ditt svärd till ett hårt ansatt rike.",al={"varför är jag här","vad gör jag här","vad är mitt syfte i stormwind"}}},fp="14,142,19.590.0,15.532.0,27.258.0,21.287.1,17.236.1,19.351.2,30.238.0,35.216.0,38.251.1,48.261.1,50.272.0,40.223.0,65.267.0"}
P.entries["zone:stranglethorn"] = {n="Stranglethorn Vale",s="Stranglethorn Vale är en otämjd, tät djungel som dominerar södra spetsen av Eastern Kingdoms, söder om Duskwood. Regnskogen var en gång säte för det mäktiga Gurubashiimperiet och är nu beströdd med sönderfallande trollruiner, vilda bestar och konkurrerande läger av gobliner, pirater och soldater. Lokala trollstammar, Venture Company och rivaliserande fraktioner som försöker få fotfäste i hettan strider hårt om kontrollen över regionen.",h="Stranglethorn Vale är en otämjd, tät djungel som dominerar södra spetsen av Eastern Kingdoms, söder om...",kw={"bloodsail","booty bay","grom'gol","gurubashi","kurzen","nesingwary","revilgaz","stranglethorn","venture co","zul'gurub"},ang={["class:Hunter"]="På den norra flodstranden bor den berömde storviltjägaren Hemet Nesingwary, som utmanar skarpskyttar att pröva sin skicklighet genom att spåra djungelns farligaste rovfåglar, pantrar och krokolisker.",["faction:Alliance"]="Stormwinds historiska försök att erövra och kuva djungeln tyngde kungariket med svåra skulder. I dag försvaras dess intressen endast av hårt ansatta myterister vid Rebel Camp.",["faction:Horde"]="Grom'gol Base Camp ger Horden ett ovärderligt strategiskt fäste på den södra kontinenten, med direkt försörjning via zeppelinare från Durotar och Undercity.",["profession:Herbalism"]="Det fuktiga lövverket ger näring åt värdefull flora, vilket gör flodstränderna och kusterna till idealiska växtplatser för Wild Steelbloom, Fadeleaf, Goldthorn och Purple Lotus.",["race:Troll"]="Stranglethorn är djungeltrollens förfädershem. Deras forntida Gurubashivälde föll i inbördeskrig efter dyrkan av Hakkar the Soulflayer, vilket drev stammar som Darkspear över haven."},sec={{t="Ett imperiums ruiner",b="I årtusenden styrdes dalen från Gurubashiimperiets huvudstad, Zul'Gurub. Väldet splittrades när radikala präster kallade fram Hakkar the Soulflayer och kastade regionen in i ett katastrofalt inbördeskrig. Zandalari ingrep och krossade blodgudens uppror, men imperiet föll sönder bortom all räddning. I dag översvämmas djungeln av stridande efterföljarfraktioner, främst Bloodscalp i nordväst och Skullsplitter i öster. Båda slaktar utomstående fanatiskt för att återta sitt förfädershem."},{t="Pirater och profitörer",b="Där forntida ruiner tystnar fyller kommersiell girighet tomrummet. Vid den södra spetsen ligger Booty Bay, en livlig fristad som Steamwheedle Cartel byggt upp och Blackwater Raiders styr under Baron Revilgaz. Hamnen är det främsta navet för handel och sjötransporter i söder, men belägras ständigt av rivalerna Bloodsail Buccaneers, som ligger ankrade längs kusten. Längre inåt land skövlar Venture Company djungelns timmer och bryter efter sällsynta sjungande kristaller i kullarna."},{t="En omstridd vildmark",b="Stranglethorn Vale är ett av världens mest instabila gränsland. Horden förfogar över Grom'gol Base Camp på västkusten, som förbinds med Durotar och Tirisfal Glades via goblinzeppelinare, medan allianslojala styrkor utgår från Rebel Camp för att spåra upp den förrymde Colonel Kurzen. Bland det täta lövverket leder den legendariske jägaren Hemet Nesingwary våghalsiga storviltsjakter och lockar vandrare till farliga möten med smygande pantrar, enorma apor och fiendesoldater."},{t="Galenskap i djungeln",b="Alla hot i norra Stranglethorn är inte vilda bestar. Colonel Kurzen, en gång en dekorerad befälhavare utsänd av Stormwind, blev galen i snåren och upprättade en tyrannisk legosoldatförläggning. I själva verket fångades Kurzens sinne av Mind's Eyes trolldom, en artefakt som användes av ogremagikern Mai'Zoth från närbelägna Mosh'Ogg Ogre Mound. Det drev expeditionen till fullständig galenskap och fick hans forna män att bilda utbrytargruppen Rebel Camp."}},faq={{q="Vem kontrollerar Stranglethorn Vale?",a="Ingen enskild makt styr dalen. Djungeln är uppdelad mellan rivaliserande djungeltrollstammar som Bloodscalp och Skullsplitter, avvikarläger som Kurzen's Compound, legosoldaterna i Venture Company och utspridda militära poster från Horden och Alliansen. Den största stadsliknande bosättningen är goblinhamnen Booty Bay, som är neutral och styrs av Baron Revilgaz och Blackwater Raiders.",al={"vem äger stranglethorn","vem styr stv","stranglethorns fraktioner"}},{q="Vad är Booty Bay?",a="Booty Bay är en vidsträckt hamnstad byggd på de södra klipporna vid The Cape of Stranglethorn. Ursprungligen var den en mänsklig bosättning kallad Blackwater Cove. Troll intog den, och så småningom säkrade Steamwheedle Cartel staden. I dag styr Baron Revilgaz och Fleet Master Seahorn den som en neutral handelshamn som förbinder resenärer med Ratchet på andra sidan Great Sea.",al={"vad är booty bay","booty bays hamn","vem styr booty bay"}},{q="Varför gjorde Colonel Kurzen uppror?",a="Colonel Kurzen ledde en expedition in i djungeln på uppdrag av Stormwind, men Mai'Zoth tog hans sinne i sitt våld. Ogremagikern använde en mäktig relik kallad Mind's Eye. Kurzen blev alltmer oberäknelig och tyrannisk, vilket tvingade lojala soldater som Lieutenant Doren att bryta sig loss och bilda Rebel Camp för att stoppa honom.",al={"varför är kurzen ond","vad hände med kurzen","kurzens bakgrund"}},{q="Vad är Zul'Gurub?",a="Zul'Gurub är Gurubashiimperiets forntida, tempelprydda huvudstad, belägen i nordöstra Stranglethorn. Staden var centrum för inbördeskriget som avslutade imperiet för femton århundraden sedan, efter att radikala präster kallat fram blodguden Hakkar the Soulflayer. Den har länge övergivits åt vinrankor och ruiner, men mörka ritualer hotar fortfarande dess salar.",al={"vad är zg","zul'gurubs historia","gurubashis huvudstad"}},{q="Vad var Stone of the Tides?",a="Stone of the Tides är en legendarisk relik från Gurubashis forntid, som en trollkrigare upptäckte vid kusten. Den gav sin bärare makt över vatten och förmågan att frammana elementarväsen, ungefär som en mäktig magiker, och bäraren fick därför titeln ”Tidebearer”. Men reliken bar på en förbannelse som långsamt fick bäraren att försvinna från den fysiska världen. Därför gick varje bärare ut i havet och försvann.",al={"stone of the tides","tidebearerlegenden","gurubashis vattensten"}},{q="Hur tar jag mig till Stranglethorn Vale?",a="Resenärer kan gå söderut över flodgränsen från Duskwood till norra Stranglethorn. Horden har direkta zeppelintorn som förbinder Grom'gol Base Camp med Durotar och Tirisfal Glades. Resenärer från Kalimdor kan också gå ombord på handelsfartyget som regelbundet seglar mellan Ratchet i The Barrens och Booty Bay.",al={"hur tar man sig till stv","ta sig till stranglethorn","resa till stv"}}},fp="18,166,18.455.0,22.346.0,22.414.0,25.340.1,32.270.0,18.322.0,32.268.1,18.294.0,32.328.0,38.256.0"}
P.entries["zone:swampofsorrows"] = {n="Swamp of Sorrows",s="Swamp of Sorrows är en mörk, bräckt våtmark mellan Deadwind Pass och det torra Blasted Lands. Området var en gång den norra delen av det uråldriga Black Morass. De salttäta träskmarkerna är hem åt farliga djur, gröna drakspawn och det förstörda Temple of Atal'Hakkar, som sjunkit under Pool of Tears. Horde håller den befästa garnisonen i Stonard, medan Alliance saknar en trygg plats i träsket och vildmarken därför till stor del förblir otämjd.",h="Swamp of Sorrows är en mörk, bräckt våtmark mellan Deadwind Pass och det torra Blasted Lands.",kw={"black morass","broken","the harborage","lost ones","pool of tears","sorrowmurk","stonard","sunken temple","swamp of sorrows","the temple of atal'hakkar"},ang={["faction:Alliance"]="Utan en utpost att samlas kring är en färd genom träsket en ensam och fientlig resa som kräver noggranna förberedelser från Darkshire eller Nethergarde Keep.",["faction:Horde"]="Stonard är din viktiga främre befästning på den södra kontinenten och har direkta wyvernrutter till Kargath, Flame Crest, Grom'gol Base Camp, Booty Bay och Rog'mar i Riverglades.",["profession:Blacksmithing"]="Härdade äventyrare kan samla järn, guld, mithril och äkta silver längs bergsklipporna som ramar in träskets norra och södra kanter.",["profession:Herbalism"]="Träsket är en av få platser på Azeroth där det finns gott om blindweed, och där växer även rikligt med liferoot, fadeleaf och stranglekelp.",["race:Troll"]="Atal'Hakkars sjunkna ruiner är en dyster påminnelse om den mörka blodmagi som splittrade Gurubashi-imperiet och väckte drakaspekternas vrede."},sec={{t="En dränkt historia",b="Långt före Orcish Horde anlände utgjorde dessa träsk den norra halvan av ett enormt våtmarksområde som kallades Black Morass. Efter Gurubashi-imperiets fall flydde de fanatiska Atal'ai-trollen in i träsket för att uppföra Temple of Atal'Hakkar och kalla på sin blodtörstiga loa, Hakkar the Soulflayer. Ysera anade katastrofen och släppte lös sina krafter, så att den förbannade pyramiden dränktes under Pool of Tears. Gröna drakflockens väktare, ledda av Eranikus, placerades där för att vaka över den dränkta byggnaden. När Dark Portals katastrof senare brände den södra delen av träsket till Blasted Lands fick det norra kärret sitt nuvarande sorgsna namn."},{t="Utposter och splittrade landsflyktingar",b="Stonard är träskets främsta civiliserade utpost. Den grundades under Första kriget tillsammans med de numera förstörda bosättningarna Rockard och Kyross. Under Thrall byggdes utposten upp igen för att fungera som Hordes sydligaste samlingsplats i Eastern Kingdoms. Bortom Stonards palissader strövar märkliga vandrare omkring i kärret. En grupp draenei som blivit strandsatta på Azeroth dukade under för hemlängtan och vansinne och förföll till vilda Lost Ones. Men en liten grupp klarsynta Broken i landsflykt finns kvar vid Harborage. De är på sin vakt, men villiga att handla fredligt med resande."},{t="Det sjunkande träsket",b="För att överleva i träsket måste du ständigt se upp för dess rovdjur. Djupa kärr döljer anfallande krokolisker, giftiga spindlar, jagande sumpjaguarer och kringvandrande träskbestar täckta av kärrdy. Kustgrottorna och Misty Reed Strand kryllar av ursinniga murlocer, medan den salta tidvattensströmmen ständigt tränger längre in och bevarar murkna stockar i tjocka saltskorpor. Längre österut ligger Sorrowmurk, där aggressiva elitära drakspawn våldsamt vaktar vägen till Sunken Temple och anfaller alla som kommer nära deras vaktpost."}},faq={{q="Hur tar jag mig till Swamp of Sorrows?",a="Den vanligaste vägen till fots går österut från Darkshire i Duskwood, genom Deadwind Passs farliga, hemsökta ravin och rakt ner i träsket. Resande från söder kan i stället följa huvudvägen norrut från Blasted Lands.",al={"hur man tar sig till swamp of sorrows","vägen genom swamp of sorrows","ta sig till stonard"}},{q="Varför ligger Temple of Atal'Hakkar under vatten?",a="För flera hundra år sedan försökte Atal'ai-prästerskapet kalla Hakkar the Soulflayer till Azeroth. Ysera, den gröna drakflockens aspekt, upptäckte deras demoniska blodsriter och dränkte hela templet i kärret för att avvärja katastrofen. Kvar blev gröna drakspawn som vaktar de översvämmade salarna.",al={"varför sunken temple sjönk","vem sänkte templet","sunken temples historia"}},{q="Vad är Stonard?",a="Stonard var en av de första bosättningarna som Orcish Horde byggde efter att ha gått genom Dark Portal under Första kriget. Staden härjades i striderna, men har nyligen återtagits och byggts upp igen på Thralls order för att säkra Hordes försörjning nära Blasted Lands.",al={"stonards historia","orcbas i träsket","vem byggde stonard"}},{q="Finns det några bosättningar för Alliance här?",a="Nej. Alliance har inga städer, vakter eller flygrutter i Swamp of Sorrows. Äventyrare från Alliance i området måste utgå från Darkshire i Duskwood i väster eller Nethergarde Keep i Blasted Lands i söder.",al={"alliance-bas i swamp of sorrows","alliance-flygrutt i träsket","var finns alliances läger"}},{q="Vilka är de märkliga, muterade humanoiderna i träsket?",a="De är draenei som blev strandsatta på Azeroth efter att Dark Portal kollapsade. Avskurna från sin värld föll de flesta i förtvivlan och blev fientliga Lost Ones. En liten grupp sinnesfriska Broken i landsflykt sökte skydd i nordväst vid Harborage och valde neutral överlevnad framför ursinnigt raseri.",al={"vilka är lost ones","vad är harborage","draenei i träsket"}},{q="Vad är Sorrowmurk?",a="Sorrowmurk är det täta träskområdet precis öster om Pool of Tears. Där patrullerar elitära gröna drakspawn och drakungar, som våldsamt driver bort dödliga för att skydda Sunken Temples hemligheter.",al={"drakområde i swamp of sorrows","drakarna i sorrowmurk","gröna drakspawn i träsket"}}},fp="16,249,17.556.0,26.487.0,16.475.0,36.188.0,44.259.0,16.248.0,40.179.0,51.307.0,19.185.0"}
P.entries["zone:tanaris"] = {n="Tanaris",s="Tanaris är en vidsträckt, tryckande het öken i södra Kalimdor, präglad av böljande sanddyner och brännande hetta. I dess hjärta ligger Gadgetzan, en neutral handelsutpost som drivs av Steamwheedle Cartels gobliner. Bortom de livliga bosättningarna döljer sanddynerna fientliga sandtroll, farliga silithidbon och bronssvärmens hemliga domän.",h="Tanaris är en vidsträckt, tryckande het öken i södra Kalimdor, präglad av böljande sanddyner och brännande...",kw={"caverns of time","öken","fribytare","gadgetzan","nozdormu","sandfury","silithider","steamwheedle","tanaris","uldum","zul'farrak"},ang={["faction:Alliance"]="Utan några större fästen för Alliansen mellan Dustwallow Marsh och Feralas fungerar Alliansens flygmästare i neutrala Gadgetzan som en viktig utgångspunkt för resor genom södra Kalimdor.",["faction:Horde"]="Gadgetzan ger Hordens spejare en bekväm handelsplats med rutter från Freewind Post och Camp Mojache direkt till de silithidhärjade ödemarkerna längst i söder.",["profession:Herbalism"]="Den torra hettan får den svårfångade Firebloom att växa bland de förflyttande sanddynerna, medan skuggiga ruiner och fuktiga oaser ger skydd åt värdefull Purple Lotus.",["profession:Mining"]="De torra klipporna och de steniga utsprången runt sanddynerna rymmer rika ådror av Mithril, Truesilver, Iron och Gold, samt spridda fyndigheter av Small Thorium längre in.",["race:Troll"]="Att se Sandfury i Zul'Farrak ger trollen en tydlig inblick i deras forntida kusiner, som utvecklade en brutal kultur efter att ha hårdnat i öknens avskildhet."},sec={{t="Ett hav av sanddyner",b="Tanaris är en karg vildmark, svedd av solen. I den muromgärdade staden Zul'Farrak vaktar de härdade Sandfury-trollen sitt avskilda område. I dag härskar hyenor, basilisker och skorpioner över öknens mark, medan underjordiska tunnlar slingrar sig under den glödheta jorden."},{t="Goblinernas företag",b="Eftersom Tanaris ligger så nära deras öhem Kezan som fastlandet tillåter, har Steamwheedle Cartel byggt upp en blomstrande verksamhet här. Från Gadgetzans muromgärdade oas till Steamwheedle Ports kustbryggor håller goblinerna sig strikt neutrala och välkomnar mynt från både Alliansen och Horden. Freden upprätthålls med råstyrka från tungt beväpnade slagskämpar, men skurkar som Southsea Freebooters trakasserar ständigt sjöfarten och utgrävningsplatserna längs kusten."},{t="Forntida mysterier och växande faror",b="Sanden döljer krafter som är mycket äldre än de dödligas riken. I öster ligger Caverns of Time, Nozdormus och hans bronssvärms uråldriga hemvist, där drakarna ibland kan ses rida på öknens varma luftströmmar. I söder markerar enorma steng portar titanernas anläggning Uldum. Men en mörkare fara rör sig i underjordiska bon som The Gaping Chasm och The Noxious Lair, där silithidsvärmar har börjat gräva sig ut över sanden."}},faq={{q="Hur tar jag mig till Tanaris?",a="Resenärer till fots färdas genom Thousand Needles till The Shimmering Flats. Ett bergspass som huggits ut genom klipporna vid saltslättens södra ände leder rakt ner i öknen, så att du genast får syn på Gadgetzans murar. Ett skepp går också från Powderfuse Port i Riverglades till Steamwheedle Port på östkusten.",al={"hur man tar sig till tanaris","resa till tanaris","ingången till tanaris"}},{q="Varför är Gadgetzan neutralt mot båda fraktionerna?",a="Gadgetzan styrs av Steamwheedle Cartel, vars enda lojalitet är till vinsten. För att maximera handeln och skydda handelsvägarna genom öknen upprätthåller goblinerna strikt neutralitet och låter slagskämpar slå ner alla som är dumma nog att starta fraktionsbråk innanför stadsmurarna.",al={"varför är gadgetzan neutralt","kan horden och alliansen åka till gadgetzan","goblinernas neutralitet i gadgetzan"}},{q="Vad är Zul'Farrak?",a="Zul'Farrak är Sandfury-trollens befästa ökenhuvudstad. Sandfury-stammen har länge varit isolerad i öknen och blivit fientlig mot alla utomstående. De skyddar sina heliga bassänger och mystiska helgedomar från äventyrare som tränger sig på.",al={"vad är zul'farrak","vilka bor i zul'farrak","sandtrollens stad"}},{q="Vad är det för insektsvarelser som häckar runt om i öknen?",a="Insektsvarelserna är silithider, monstruösa kolonibildande grävare som bygger enorma bon som The Gaping Chasm och The Noxious Lair. Deras växande närvaro i Tanaris har oroat observatörer som Senior Surveyor Fizzledowser och väckt minnen av det uråldriga fasansvälde som var Sandskiftets krig.",al={"vad är det för insekter i tanaris","insektsbon i tanaris","silithider i tanaris"}},{q="Vad finns bakom de enorma stendörrarna i söder?",a="De väldiga portarna i Valley of the Watchers markerar ingången till Uldum, en legendarisk forskningsanläggning och förvaringsplats som tillhörde de uråldriga titanerna. Ingången är fortfarande ordentligt förseglad och vaktas av kolossala stenväktare, medan nyfikna lärda och gobliner spanar på håll.",al={"jättedörrarna i södra tanaris","ruins of uldums portar","titanporten i tanaris"}},{q="Vilka bor inne i Caverns of Time?",a="Caverns of Time är bronssvärmens och dess aspekt Nozdormus uråldriga lya. Från dessa dolda, vindlande djup vakar de tidlösa drakarna över historiens gång och patrullerar ibland himlen högt ovanför de södra sanddynerna.",al={"caverns of times historia","vad finns i caverns of time","drakar i tanaris"}}},fp="7,203,14.233.0,17.333.0,35.335.0,27.288.0,42.224.0,19.175.0,56.255.0,52.219.0,38.232.0"}
P.entries["zone:teldrassil"] = {n="Teldrassil",s="Teldrassil, som betyder ”Jordens krona”, är ett väld ofantligt nytt världsträd utanför Kalimdors nordvästra kust. Druiderna lät det växa efter det tredje kriget. Dess väldiga grenar bär upp en skymningsdunkel vildmark och nattalvernas huvudstad Darnassus. Men under dess fridfulla, månlysta krona har en smygande fördärvelse börjat röra på sig.",h="Teldrassil, som betyder ”Jordens krona”, är ett väld ofantligt nytt världsträd utanför Kalimdors nordvästra...",kw={"de äldstes cirkel","crown of the earth","darnassus","dolanaar","fandral staghelm","rut'theran","shadowglen","teldrassil","världsträd"},ang={["class:Druid"]="Med Malfurion fångad i The Emerald Dream leder ärkedruiden Fandral Staghelm Cenarion Circle här, men många druider oroar sig för att Teldrassil restes i all hast.",["faction:Alliance"]="Teldrassil är Alliansens nordligaste fäste i Kalimdor och knyter samman sjökommunikation och handel mellan Darnassus och kungarikena på fastlandet.",["profession:Herbalism"]="Trädets grönskande krona kompenserar för den totala bristen på mineraler och malm genom att vara ett paradis för dem som samlar fredsblomma, silverblad och jordrot.",["race:NightElf"]="Det här väldiga trädet är ditt folks nya början efter Mount Hyjals förödelse, men utan aspekternas välsignelser är det brådskande att försvara det."},sec={{t="En krona över havet",b="Teldrassil är mer än ett träd. Det är ett upphöjt ekosystem som reser sig högt ur det beslöjade havets vatten. Dess väldiga grenar bär upp böljande kullar, floder som får sitt vatten från morgondagg, dimhöljda sjöar och täta, uråldriga skogsdungar. Vid dess västra kant ligger Darnassus, kaldoreiernas storslagna huvudstad. Vid foten av den monumentala stammen ligger Rut'theran Village, som är förbundet med kronan ovanför genom en magisk portal och fungerar som öns främsta hamn."},{t="Aspekternas vägran",b="Efter Nordrassils offer under det tredje kriget och Shan'do Malfurion Stormrages mystiska försvinnande in i The Emerald Dream övertygade ärkedruiden Fandral Staghelm de äldstes cirkel om att odla ett nytt träd. Staghelm hoppades återge kaldoreierna deras förlorade odödlighet. Nozdormu och drakpekterna ansåg dock försöket övermodigt och undanhöll sina välsignelser. Utan deras livsviktiga skydd har Teldrassils tillväxt drabbats av onaturliga brister."},{t="En smygande sjukdom",b="Trots sin yttre prakt bär det unga världsträdet på en mörk sjukdom. Djurlivet i området har blivit våldsamt: fredliga furbolgstammar har fallit i vansinne, förvridna grellar förökar sig i gravkamrarna och vidriga satyrer utför mörka riter i skuggor som Fel Rock. Längs Darkshores stränder går havsjättar, huggare och sköldpaddor i land för att fly det förgiftade vattnet kring trädet. Naturkunniga och väktare arbetar nu febrilt bland grenarna för att finna skuggan som långsamt stryper deras nya hem."}},faq={{q="Varför odlades Teldrassil?",a="När Nordrassil ödelades i slutet av det tredje kriget förlorade nattalverna sin odödlighet. Ärkedruiden Fandral Staghelm drev på de äldstes cirkel och Cenarion Circle-druiderna att plantera ett nytt världsträd i havet, i hopp om att återge sitt folk det de hade förlorat.",al={"varför skapades det","vem skapade teldrassil","teldrassils ursprung"}},{q="Varför återställde inte Teldrassil nattalvernas odödlighet?",a="Nordrassil gav ursprungligen odödlighet eftersom Nozdormu, den tidlöse, välsignade trädet. När Teldrassil restes ansåg Nozdormu att nattalvernas önskan var arrogant och vägrade välsigna det nya trädet.",al={"odödlighet","varför inte odödlig","nozdormus välsignelse"}},{q="Hur lämnar du Teldrassil?",a="Resenärer måste ta sig genom Darnassus till den rosa portalen i The Temple Gardens, som för dem ner till Rut'theran Village vid stammens fot. Från Rut'theran går ett skepp över havet till Auberdine på fastlandet i Darkshore. Hippogryffrutter finns också att tillgå.",al={"hur tar man sig ut","lämna trädet","båt från teldrassil"}},{q="Varför finns det inga gruvfyndigheter i Teldrassil?",a="Hela området ligger ovanpå ett kolossalt världsträds levande grenar och ved, inte på naturlig kontinental berggrund. Eftersom det saknas steniga underjordiska lager bildas inga metallådror eller malmfyndigheter här, men örter frodas i överflöd.",al={"var finns koppar","ingen malm","gruvdrift i teldrassil"}},{q="Vad får furbolgarna och bestarna att bli vansinniga?",a="En ondskefull närvaro har börjat sippra in i Teldrassils ovälsignade rötter. Sjukdom har fördärvat det lokala vattnet och växtligheten och drivit de fredliga trädenlingarna och Gnarlpine-furbolgstammen till ursinnigt våld, medan satyrer som finns kvar aktivt odlar smittan.",al={"fördärvade furbolgar","gnarpine vansinniga","vad är fördärvelsen"}},{q="Vad är Shadowglen?",a="Shadowglen är en skyddad, avskild dalgång bland Teldrassils östra grenar, kring det stora trädet Aldrassil. Den är en fridfull fristad där unga nattalver börjar sin träning innan de ger sig ut i den större världen.",al={"shadowglen","startområde","aldrassils område"}}},fx={["11a6d5e5"]={q="Vad är Teldrassil?",a="Teldrassil är ett väldig världsträd som växer på en ö utanför Kalimdors nordvästra kust. Dess enorma stam reser sig ur Veiled Sea och breder ut sig i grenar så vidsträckta att de bär upp ett helt skogsrike med sjöar, floder och huvudstaden Darnassus högst uppe i trädkronan.",al={"vad är det här för plats","om teldrassil","berätta om teldrassil"}},["313cd5a2"]={q="Vad hände vid Teldrassil?",a="Efter det tredje kriget och skadorna på Nordrassil på Mount Hyjal försvann druiden Malfurion Stormrage. I hans frånvaro övertygade ärkedruiden Fandral Staghelm de äldstes cirkel om att odla ett nytt världsträd som ersättning för det som gått förlorat. Trädet växte framgångsrikt, men sedan dess har en krypande korruption börjat besudla dess grenar.",al={"teldrassils historia","hur skapades teldrassil","händelser vid teldrassil"}},c5e34e84={q="Vilka bor på Teldrassil eller styr där?",a="Teldrassil är nattalvernas förfäders fristad och deras nuvarande hemland. Andligt och samhälleligt vägleder översteprästinnan Tyrande Whisperwind och ärkedruiden Fandral Staghelm sitt folk från huvudstaden Darnassus, med stöd från The Sisterhood of Elune, Cenarion-druider och vaktpostkrigare som skyddar skogsbosättningarna.",al={"vem leder teldrassil","teldrassils ledare","vilka bor här"}},b86e706e={q="Är Teldrassil farligt?",a="Teldrassil skyddas av vaktposter, men blir allt farligare. En mörk åkomma har gjort de inhemska bestarna och de lokala furbolgerna vansinniga, medan illasinnade satyrer, blodtörstiga harpyor och härjande timberlings hotar bosättningarna bortom de patrullerade vägarna.",al={"är det säkert här","hot i teldrassil","faror i teldrassil"}},["2863bed2"]={q="Varför heter det Teldrassil?",a="På darnassiska, nattalvernas språk, betyder Teldrassil ordagrant ”jordens krona”. Namnet hedrar dess roll som ett monumentalt världsträd, avsett att härbärgera och skydda deras civilisation.",al={"vad betyder teldrassil","betydelsen av namnet teldrassil"}},["514d23b0"]={q="Vem är Fandral Staghelm?",a="Fandral Staghelm är ärkedruiden som tog över ledarskapet för nattalvernas druider efter att Malfurion Stormrage försvunnit in i The Emerald Dream. Fandral är lidelsefull, envis och aggressiv. Han drev på för att Teldrassil skulle planteras och hamnar ofta i konflikt med översteprästinnan Tyrande Whisperwind om politiken.",al={"vem är ärkedruiden","fandral staghelms bakgrund","staghelm"}},["52c333ac"]={q="Vem är Tyrande Whisperwind?",a="Tyrande Whisperwind är översteprästinna åt gudinnan Elune och nattalvernas högsta ledare. Hon har lett sitt folk i tiotusen år genom den långa vaksamheten och det tredje kriget och styr nu från Temple of the Moon i Darnassus.",al={"vem är tyrande","översteprästinnan tyrande","vem leder nattalverna"}},["29b1e9e4"]={q="Hur hamnade jag i Teldrassil?",a="Om du är en Night Elf är detta väldiga världsträd ditt folks nya hemland. Efter att ha offrat Nordrassil och er urgamla odödlighet på Mount Hyjal för att besegra Burning Legion, flyttade kaldorei från Kalimdors nordvästra kust. Ärkedruiden Fandral Staghelm och de uråldrigas cirkel lät Teldrassil växa i Veiled Sea för att ge ditt folk en förnyad tillflyktsort, och din resa började bland dess grönskande grenar i Shadowglen. Om du kom hit från fjärran seglade du troligen från Darkshore till hamnen i Rut'theran Village vid trädets fot och gick sedan genom den lysande portalen som för resenärer direkt upp till kronan.",al={"hur kom jag till teldrassil","hur kom jag hit","varför börjar jag här"}},["8381279f"]={q="Vad ska jag göra i Teldrassil?",a="Du kallas att skydda det unga världsträdet och avslöja den mörka sjukdom som skakar dess grenar. Trots de frodiga skogarna sprider sig en ondskefull korruption: timmerlingar blir aggressiva, fredliga furbolger från Gnarpine-stammen håller på att bli galna och vidriga satyrer lurar i skuggiga snår som Fel Rock. Med Shadowglen som utgångspunkt och genom att hjälpa bosättningar som Dolanaar måste du hjälpa Sentinels och druider att återställa balansen. Du ska fylla på de heliga månpölarna, rensa ut korrumperade skadedjur och lära dig ditt folks historia innan du beger dig till huvudstaden Darnassus och vidare över havet till Kalimdors fastland.",al={"vad gör jag i teldrassil","varför är jag här","vad är mitt uppdrag här"}}},fp="10,168,21.379.0,26.466.0,17.410.1,25.260.0,52.182.0,28.253.0,44.210.0,52.248.0,19.205.0"}
P.entries["zone:thousandneedles"] = {n="Thousand Needles",s="Thousand Needles är en vidsträckt kanjon med lodräta sandstenspelare och solstekta saltslätter i södra Kalimdor. Taurenstammar håller sig till bosättningar på höga platåer för att undkomma aggressiva centaurflockar, medan gnomiska och goblinska uppfinnare kör raketbilar i hög fart över Shimmering Flats uttorkade havsbotten.",h="Thousand Needles är en vidsträckt kanjon med lodräta sandstenspelare och solstekta saltslätter i södra...",kw={"cliffwatcher longhorn","darkcloud pinnacle","fizzle brassbolts","freewind post","the great lift","grimtotem","kravel koalbeard","mirage raceway","pozzik","the shimmering flats","thousand needles"},ang={["faction:Horde"]="The Great Lift förbinder The Barrens med ditt fäste vid Freewind Post och utgör en strategisk sydgräns mot centaurklaner och upproriska tauren.",["profession:Engineering"]="Saltslätterna är en vallfärdsplats för uppfinnare som vill studera raketbränsle, fordonsdelar och framdrivning i hög fart vid Mirage Raceway.",["race:Gnome"]="Mirage Raceway i Shimmering Flats ger din fraktion den främsta möjligheten att visa upp den precision och elegans som kännetecknar gnomisk ingenjörskonst, till skillnad från goblinernas undermåliga byggen.",["race:Tauren"]="Freewind Post påminner om hur högt ditt folk var tvunget att klättra för att undkomma centaurernas massaker och fungerar som en samlingsplats inför striden mot de förrädiska Grimtotem vid Darkcloud Pinnacle."},sec={{t="En skog av sten",b="Innan den stora delningen slet sönder det forntida Kalimdor var området en grönskande flodkanjon, genomskuren av vattendrag som flöt från inlandet mot havet. Kataklysmen slet isär kontinenten, höjde flodbädden över grundvattennivån och ändrade flodens lopp tills bara torr sten och sandstensspiror återstod. I dag reser sig dussintals smala, cylindriska pelare från kanjonens botten som en förstenad skog. Tauren slog sig ner på topparna och spände upp riskabla repbroar mellan höjderna för att bygga byar utom räckhåll för de fientliga centaurplundrare som patrullerar den skuggiga kanjonbottnen nedanför."},{t="Faror på platåerna",b="Livet på toppen av de nållika spirorna är långt ifrån fridfullt. Vid Freewind Post kämpar tauren som är lojala mot Horde inte bara mot rovlystna vindormar och wyverner från Highperch, utan också mot förrädiska fränder: den militanta Grimtotem-klanen, som har befäst sig vid Darkcloud Pinnacle. Cliffwatcher Longhorn leder försvaret av platån och söker djärva kämpar som kan slå till mot Grimtotem-uppviglare och säkra de bräckliga broarna mellan höjderna. I norr transporterar The Great Lifts enorma mekaniska vinschar resenärer ner från södra The Barrens, men att korsa kanjonbottnen är fortfarande livsfarligt."},{t="Mirage Raceway",b="I sydöst öppnar sig kanjonväggarna mot Shimmering Flats, en enorm, uttorkad saltslätt under havsnivån. I denna hårda, bländande vita ödemark upprätthåller gnomer och gobliner en spänd neutralitet kring Mirage Raceway. Rivaliserande ingenjörer Pozzik och Fizzle Brassbolts tävlar med experimentella raketbilar över den hårda saltmarken för att avgöra vilken ras som har den mest avancerade tekniken. Depån lockar till sig skurkar, bedragare som Kravel Koalbeard och jägare som jagar de tåliga skorpioner, sköldpaddor och basilisks som strövar omkring i den brännande sänkan."}},faq={{q="Hur fick Thousand Needles sitt namn?",a="Zonen har fått sitt namn efter de många enorma, cylindriska sandstensspiror som skjuter upp från kanjonens botten. De geologiska tornen formades ursprungligen av strömmande floder före den stora delningen och liknar nu en skog av jättelika nålar.",al={"varför heter det thousand needles","nålpelarnas ursprung","spirornas historia"}},{q="Hur tar man sig ner i Thousand Needles från The Barrens?",a="Resenärer tar The Great Lift, en väldig hiss med två vagnar som sköts av Horde-vakter vid The Barrens södra gräns. Det är livsfarligt att kliva ut över kanten, så det är viktigt att vänta på plattformen. Resenärer från Alliance kan också vandra in västerifrån via Thalanaar i Feralas.",al={"hur tar man sig till thousand needles","ingången till the great lift","hissen till needles"}},{q="Varför bor tauren högst upp på platåerna?",a="Centaurernas krigsband drev en gång tauren, som levde som nomader, nästan till utrotning. Genom att bygga utposter som Freewind Post på otillgängliga stenpelare kunde de skydda sig mot markanfall. De förband platåerna med hängbroar av trä, så att de kunde färdas högt ovanför rovdjuren och plundrarna nedanför.",al={"varför står tauren på pelarna","freewind posts historia","taurens höga mark"}},{q="Vad är Mirage Raceway?",a="Mirage Raceway är en testbana för ingenjörer på Shimmering Flats saltslätt. Gnomiska och goblinska uppfinnare kör experimentella raketbilar över den platta saltmarken för att göra upp om vilken ras som bygger de bästa maskinerna.",al={"saltbanan","gnomernas och goblinernas tävling","raketbilsbana"}},{q="Vad gör Grimtotem i kanjonen?",a="Grimtotem-klanen håller till vid Darkcloud Pinnacle, en befäst samling spiror mitt emot Freewind Post. Till skillnad från de andra taurenstammarna, som svurit trohet till Horde, angriper Grimtotem-klanen aktivt andra tauren och smider planer för att ta makten över platåerna.",al={"grimtotem i thousand needles","tauren vid darkcloud pinnacle","onda tauren i needles"}},{q="Vad är Shimmering Flats?",a="Shimmering Flats är en vidsträckt, uttorkad sjöbotten öster om kanjonens platåer. Saltskorpan bildades när det forntida innanhavet avdunstade efter den stora delningen. Den stekande hettan, det bländande vita saltet och de farliga rovdjuren gör området till en ogästvänlig öken som främst används för fordonstester i hög fart.",al={"saltslätt","vita öknen i needles","östra öknen"}}},fx={d1fb42e2={q="Vad är Thousand Needles?",a="Thousand Needles är en vidsträckt, torr kanjon som skiljer centrala och södra Kalimdor åt. Kanjonens botten är täckt av höga sandstensspiror som sträcker sig mot himlen likt en förstenad skog, sammanbundna ovanför av smäckra rep- och träbroar. I öster övergår kanjonen i saltökenområdet The Shimmering Flats, bländande vitt och platt.",al={"vad är det här för plats","om thousand needles","berätta om thousand needles"}},["98fcff4e"]={q="Varför består området bara av kanjoner och pelare?",a="För länge sedan, före den stora omvälvningen, var området en grönskande flodkanjon som formats av strömmande vatten på väg österut från Feralas till ett innanhav. När världen splittrades lyfte katastrofen flodbädden och ändrade flodens lopp. Utan vatten torkade landet ut och lämnade kvar höga sandstenspelare och en uttorkad saltslätt.",al={"varför finns det spiror","hur bildades spirorna","varför sandstenspelare"}},["05d5c74f"]={q="Är Thousand Needles farligt?",a="Det är mycket farligt. Barbariska centaurer från Galak patrullerar kanjonens botten i plundringsgrupper, medan rovlystna gamar, skorpider och kringströvande harpyor hemsöker klipporna. Även repbroarna mellan de höga topparna är förrädiska, eftersom rovfåglar ofta dyker ner mot oförsiktiga resenärer eller skadar brospannet.",al={"hur farligt är thousand needles","faror här","är det säkert"}},["1b8e8bea"]={q="Varför skickade Horde mig till Thousand Needles?",a="Horde upprätthåller en viktig närvaro här för att hjälpa de lokala taurenstammarna, som utsätts för skoningslösa angrepp. Freewind Post är en avgörande utpost mellan The Barrens och de södra öknarna, och Horde behöver modiga kämpar som driver tillbaka plundrande centaurer och avvärjer interna hot.",al={"hordes uppdrag i thousand needles","varför är jag här som horde","vad vill horde här"}},a7c3b539={q="Är detta taurenland?",a="Ja. Thousand Needles karga kanjoner och höga platåberg har i oräkneliga generationer varit förfädernas territorium för flera taurenstammar, även om våldsamma centaurklaner drev dem till överlevnadens rand innan Horde kom.",al={"äger tauren thousand needles","taurenernas territorium","är detta shu'halo-land"}},fef8bf7c={q="Vad är Freewind Post?",a="Freewind Post är Hordes främsta utpost i Thousand Needles. Den ligger högt ovanför dalbotten på ett väldiga platåberg och har trädrivna hissar, ett flygtorn och ett nätverk av hängbroar till de intilliggande topparna.",al={"freewind post","vad är freewind","freewind-byn"}},["6ac472b0"]={q="Vilka är centaurerna från Galak, och varför angriper de oss?",a="Galak-stammen är de lokala centaurer som gör anspråk på kanjonens botten. Liksom alla centaurer är de våldsamt revirhävdande, nomadiska och brutala. De jagar alla resenärer som färdas genom ravinerna och försöker utrota taurenbosättningarna helt.",al={"centaurer från galak","varför anfaller centaurerna","galak-stammen"}},["9f0b1de8"]={q="Varför hatar de tauren?",a="Fiendskapen mellan tauren och centaurer är urgammal och obeveklig. I generationer jagade kringströvande centaurer tauren för nöjes skull över Kalimdors slätter och inledde brutala, oprovocerade krig som ständigt tvingade de fredliga stammarna på flykt.",al={"varför hatar centaurerna tauren","fejden mellan centaurer och tauren","centaurernas agg"}},["0eee4587"]={q="Varför tävlar gobliner och gnomer med raketbilar i öknen?",a="Den platta, öppna saltslätten i The Shimmering Flats är en perfekt testplats för motorer med hög hastighet. Gnomer och gobliner anlade Mirage Raceway för att en gång för alla avgöra den långvariga tvisten om vilket folk som har bäst ingenjörskonst.",al={"varför tävla med bilar","goblinernas och gnomernas tävling","rivaliteten om raketbilar"}},e421f132={q="Vad är grejen med Darkcloud Pinnacle och de hemliga breven?",a="Darkcloud Pinnacle är Grimtotem-stammens hårt bevakade fäste på platåbergen öster om The Great Lift. Hemlig korrespondens som hittats där avslöjar dold kontakt mellan Grimtotem-ledare som Arnak Grimtotem och en okänd mörk makt, vilket tyder på förrädiska ambitioner långt bortom enkla stamfejder.",al={"brev från darkcloud pinnacle","grimtotem-breven","mysteriet kring darkcloud pinnacle"}},["7b560411"]={q="Vad planerar Grimtotem?",a="Grimtotem förkastar helt Cairne Bloodhoofs ledarskap och de kulturella förändringar som följde med anslutningen till Horde. De vill avsätta Cairne, underminera Hordes auktoritet och till och med samarbeta med ondskefulla makter och frammana hämndlystna väsen för att befästa sin dominans.",al={"grimtotems planer","vad vill grimtotem","grimtotem-konspirationen"}},["853c4dd1"]={q="Vad är Highperch, och varför vill vi ha wyvernägg?",a="Highperch är vilda wyverners urgamla häckningsplats i Thousand Needles. Tauren från Freewind Post klättrar upp till de höga bona för att samla befruktade wyvernägg, så att de varsamt kan föda upp och träna wyvernerna till lojala flygande riddjur åt Horde.",al={"wyvernerna vid highperch","varför samla wyvernägg","ägg från highperch"}},dc3189d8={q="Hur hamnade jag i Thousand Needles?",a="De flesta resenärer kommer norrifrån och rider söderut genom The Barrens förbi Camp Taurajo, tills de når den branta klippkanten där den väldiga, taurenbyggda The Great Lift sänker dem rakt ner till kanjonens botten. Äventyrare som färdas österut genom Feralas täta skogar kan i stället ta sig till den västra ravinen till fots, medan djärva upptäcktsresande som trotsar farorna i Dustwallow Marsh eller seglar till Theramore smiter igenom de omstridda passen. En lång marsch norrut från Tanaris öknar leder dig också rakt till den vidsträckta saltslätten i The Shimmering Flats.",al={"hur kom jag hit","hur tar jag mig till thousand needles","att ta sig till thousand needles"}},["16801326"]={q="Vad ska jag göra i Thousand Needles?",a="Din närvaro här beror på dina lojaliteter och ambitioner. Hordes kämpar får i uppdrag att hjälpa Freewind Post: driva tillbaka Galak-centaurernas grupper som strövar på kanjonens botten, hålla uppsikt över harpyornas boplatser, samla wyvernägg från Highperch och bekämpa den förrädiska Grimtotem-stammen som håller till på Darkcloud Pinnacle. För kringvandrande utan allians och resenärer från Alliance är det storslagna området en farlig landväg mellan centrala och södra Kalimdor. Den leder mot The Shimmering Flats, där goblin- och gnomvåghalsar betalar bra för delar, bränsle och hjälp med sin eviga rivalitet om raketbilar.",al={"varför är jag här","vad är mitt syfte här","vad gör jag i thousand needles"}}},fp="16,179,17.529.0,18.553.0,18.535.0,38.222.0,59.251.0,43.279.0,27.248.0,45.235.0,30.284.0"}
P.entries["zone:thunderbluff"] = {n="Thunder Bluff",s="Thunder Bluff är taurenfolkets storslagna huvudstad, belägen på vindpinade mesas av röd sten ovanför Mulgore grässlätter. Staden grundades av överhövding Cairne Bloodhoof sedan han med hjälp av New Horde enat de nomadiska stammarna. Den är folkets kulturella, andliga och kommersiella hjärta. Staden binds samman av svajande repbroar och träplattformshissar och erbjuder skydd mot centaurernas anfall samt en fridfull fristad för resenärer i Kalimdor.",h="Thunder Bluff är taurenfolkets storslagna huvudstad, belägen på vindpinade mesas av röd sten ovanför Mulgore...",kw={"cairne bloodhoof","elder rise","hissar","hamuul runetotem","hunter rise","magatha grimtotem","mulgore","the pools of vision","spirit rise","thunder bluff"},ang={["class:Druid"]="Elder Rise är Hordens främsta fristad för naturmagi och leds av ärkedruiden Hamuul Runetotem, den första taurendruiden på tusentals år.",["class:Shaman"]="Spirit Rise och de underjordiska The Pools of Vision utgör en fridfull mötesplats där elementandar och taurenfolkets förfäders andar vördas och får komma till tals.",["faction:Horde"]="Thunder Bluff är långt fridfullare och mer andlig än Orgrimmars hårda befästningar och utgör New Hordes pastorala fäste för inflytandet i södra Kalimdor.",["race:Tauren"]="Thunder Bluff står för den hårt vunna enigheten och pånyttfödelsen hos ditt folk efter generationer av nomadvandringar och trakasserier från centaurerna under överhövding Cairne Bloodhoof."},sec={{t="En stadigvarande fristad",b="I otaliga generationer vandrade taurenfolket nomadiskt över Kalimdor och kämpade hårt för sin överlevnad mot glupska centaurstammar. Den desperata tiden tog slut under det tredje kriget, när Cairne Bloodhoof slöt sig samman med krigshövding Thrall. Tillsammans slog orcherna och taurenfolket tillbaka centaurernas anfall och säkrade Mulgore bördiga betesmarker. För att skydda framtiden ledde Cairne de allierade stammarna till dessa naturliga stenfästen och grundade Thunder Bluff, taurenfolkets första enade, permanenta hem på århundraden."},{t="En stad bland molnen",b="Thunder Bluff sträcker sig över flera höga mesas som binds samman av hängande repbroar och förenar naturlig arkitektur med taurenfolkets praktiska läggning. På de centrala klipporna finns livliga marknader, en bank, ett värdshus och ett högt vindryttarrede, medan tre särskilda mesas sträcker sig ut över avgrunden. Hunter Rise är till för stadens spejare och spårare. Elder Rise rymmer kunskapsbevarare och Cenarion Circle, som leds av ärkedruiden Hamuul Runetotem. Spirit Rise är helgad åt andlig gemenskap och härbärgerar schamaner, präster och de gåtfulla underjordiska grottorna som kallas The Pools of Vision."},{t="En bräcklig enighet",b="Cairne Bloodhoof åtnjuter stor respekt hos nästan alla stammar, men det är inte friktionsfritt att styra ett nyligen bofast och stolt folk. Grimtotem-stammen, ledd av den listiga och skarptungade äldre modern Magatha Grimtotem, håller sig märkbart för sig själv på Elder Rise. Magatha ifrågasätter öppet Cairnes försonliga metoder och lojalitet mot Hordens främmande folk. Freden består under hövdingens vaksamma blick, men ideologiska sprickor viskar bland rådets eldar ovanför slätterna."}},faq={{q="Vem styr Thunder Bluff?",a="Överhövding Cairne Bloodhoof styr Thunder Bluff och leder de enade taurenstammarna. Cairne vördas för sin visdom, sitt tålamod och sin väldiga styrka. Han grundade staden efter att ha slutit förbund med Thralls Horde och drivit bort centaurerna från Mulgore.",al={"ledare för thunder bluff","vem bestämmer","hövding i thunder bluff","cairne"}},{q="Hur tar du dig upp till Thunder Bluff?",a="Besökare som kommer till fots eller på kodo måste åka med de stora träplattformshissarna på den centrala mesans sydvästra och nordöstra sida. Staden har också ett vindryttarrede med flygrutter över Kalimdor.",al={"hiss i thunder bluff","hur tar man sig in","ingång till thunder bluff","ta sig upp"}},{q="Varför byggde taurenfolket på höga mesas i stället för nere på marken?",a="Århundraden av nomadliv präglades av aggressiva centaurklaner som ständigt anföll och drog sig undan. De branta klipporna i Mulgore ger ett naturligt försvar. De skyddar taurenfolkets bostäder, smedjor och vördnadsvärda äldste från bakhåll på marken och låter dem slå sig ner permanent i fred.",al={"varför mesas","varför bor de på klippor","thunder bluffs klippor","taurenfolkets höjder"}},{q="Vilka olika höjder finns i staden?",a="Staden breder ut sig över en central mesa, indelad i nedre, mellersta och övre nivåer, med tre yttre mesas runtomkring. Hunter Rise är till för krigare, jägare och spårarstugor. Elder Rise är hem för druider, visa män och Grimtotem-fraktionen. På Spirit Rise finns helgedomar åt Jordmodern, tränare för schamaner, präster och magiker samt de grottliknande The Pools of Vision.",al={"områden i thunder bluff","vilka höjder finns","stadsdelar i thunder bluff"}},{q="Vad är The Pools of Vision?",a="The Pools of Vision är heliga underjordiska grottor gömda under Spirit Rise. Taurenfolkets siare, andevandrare och utövare av magisk konst samlas i dessa stilla, dimhöljda vatten för att tala med elementen och tyda omen om folkets framtid.",al={"the pools of vision","grotta på spirit rise","grotta i thunder bluff"}},{q="Vem är Magatha Grimtotem?",a="Magatha Grimtotem är matriark och äldre moder för den mäktiga Grimtotem-klanen. Hon bor på Elder Rise och deltar utåt sett i Cairnes råd, men är starkt traditionalistisk, misstror utomstående och utmanar i det tysta Bloodhoof-stammens milda hållning gentemot Horde.",al={"magatha","äldre moder","vem leder grimtotem"}}},fx={["6fa5b073"]={q="Vad är Thunder Bluff?",a="Thunder Bluff är taurenfolkets huvudstad, högt belägen på de vindpinade platåbergen i norra Mulgore. Hövding Cairne Bloodhoof grundade staden efter att ha drivit tillbaka centaurerna tillsammans med Thralls Horde. Den är ett tryggt, permanent hem för ett folk som levde som kringvandrande nomader i generationer.",al={"vad är det här för stad","berätta om thunder bluff","staden thunder bluff"}},fc90632b={q="Är Cairne Bloodhoof en kung?",a="Nej. Cairne Bloodhoof bär titeln högste hövding över de enade taurenstammarna. Taurensamhället kröner inga monarker. Cairne styr genom den djupa respekt, visdom och styrka han visat under årtionden, inte genom någon ärftlig, kunglig gudomlig rätt.",al={"cairne bloodhoof kung","är cairne kung","taurenkung"}},["047fa056"]={q="Lyder Cairne Bloodhoof under Thrall?",a="Thrall är Hordes krigshövding, men hans band till Cairne bygger på ömsesidig heder och en allians, inte strikt underkastelse. Cairne svor att förena sitt folk med Horde av tacksamhet och gemensamma ideal, och är en av Thralls mest betrodda rådgivare och jämlikar.",al={"lyder cairne under thrall","är thrall cairnes chef","cairne och thrall"}},["85c1a10f"]={q="Varför gick tauren med i Horde?",a="Centaurplundrare hade drivit de nomadiska tauren till utrotningens rand över The Barrens. När krigshövding Thrall och orcherna landsteg i Kalimdor hjälpte de Cairnes folk att bryta centaurernas belägring och säkra Mulgore. Därmed knöts deras kulturer samman i ett obrytbart band.",al={"varför gå med i horde","tauren och horde-alliansen","hur gick tauren med"}},["3180b5ca"]={q="Vad är grejen med Grimtotem-stammen?",a="Grimtotem är en stridslysten och aggressiv klan som leds av den gamla matriarken Magatha. Till skillnad från de fredliga Bloodhoof hyser de en djup misstänksamhet mot främlingar och ifrågasätter öppet Cairnes fredliga ledarskap. De anser att tauren borde erövra Kalimdor och driva bort de andra raserna.",al={"grimtotem-stammen","vilka är grimtotem","grimtotem-tauren"}},ca8246e8={q="Är Grimtotem fiender till Cairne?",a="Officiellt är de fortfarande en del av taurenfolkets enade nation, och Magatha bor till och med på Elder Rise. Under ytan pyr dock en bitter politisk rivalitet. Magatha smider ständigt planer och anser att bara hon har den rätta visionen för att styra tauren.",al={"är grimtotem onda","grimtotem mot cairne","magatha mot cairne"}},["54829977"]={q="Är Thunder Bluff farligt?",a="I staden håller de modiga vakterna ordning och skyddar mot bestarna och quilboar som stryker omkring på slätterna nedanför. Den största omedelbara faran för besökare är det branta fallet. Ett enda obetänksamt steg ut över mesas kanter eller de träbyggda broarna blir ödesdigert.",al={"är thunder bluff tryggt","hot i thunder bluff","fara här"}},["7db56847"]={q="Hur hamnade jag i Thunder Bluff?",a="Om du är en ung tauren började din resa söderut på de skyddade gräsmarkerna vid Red Cloud Mesa. Du passerade genom Bloodhoof Village innan du kom hit. Vägen leder till foten av dessa höga mesas, där stora träbyggda repdrivna hissar lyfter resenärer hundratals fot upp i skyn. Besökare från fjärran länder på andra sidan Kalimdor anländer ofta med wyvern till Wind Rider Roost mitt på klipporna.",al={"hur hamnade jag här","hur kom jag till thunder bluff","hur tar jag mig till thunder bluff"}},["347b5cac"]={q="Vad förväntas jag göra i Thunder Bluff?",a="Thunder Bluff är det andliga och kulturella hjärtat för taurenstammarna. Här kan du få avancerad träning av äldre schamaner, druider, jägare och krigare som samlats på höjderna. Högöverhövding Cairne Bloodhoof och stammarnas äldste behöver också skickliga hjältar som kan skydda Mulgore mot kvarvarande hot, däribland strövande centaurplundrare, det framryckande Venture Company, harpyor och upproriska quilboar. Därefter skickar de dig österut för att möta Hordens större prövningar.",al={"vad ska jag göra i thunder bluff","varför är jag här","vad är mitt syfte här"}}},fp="13,326,17.466.0,20.453.0,12.391.1,24.277.0,35.194.0,61.212.0,41.395.0,29.239.0,25.233.0"}
P.entries["zone:tirisfal"] = {n="Tirisfal Glades",s="Tirisfal Glades är Lordaerons hemsökta nordliga område och utgör nu Lady Sylvanas Windrunners och de Förkastades kärnland. Under fördärvade himlar och ruttnande grenar ligger fallna herrgårdar, slumrande kryptor och den väldiga underjordiska huvudstaden Undercity. Omgivet av tanklösa plågoandar och fanatiska Scarlet-korsfarare är detta ett farligt rike där de viljestarka odöda kämpar för sin överlevnad.",h="Tirisfal Glades är Lordaerons hemsökta nordliga område och utgör nu Lady Sylvanas Windrunners och de...",kw={"agamand","balnir","brill","deathknell","förkastade","glades","lordaeron","scarlet crusade","sylvanas","tirisfal","undercity"},ang={["class:Priest"]="Heliga historiska platser som Faol's Rest, ärkebiskop Alonsus Faols grav och Silver Hands grundares sista viloplats, ligger här. De har förvridits av döden och är omstridda mellan fanatiker och skuggpräster.",["faction:Alliance"]="För Alliansens överlevande folk är Tirisfal ett tragiskt minnesmärke över Lordaerons fall, fyllt av vanhelgade gravar efter forna bröder och systrar i tron.",["faction:Horde"]="Tirisfal är Hordens livsviktiga fäste i norra Eastern Kingdoms. Därifrån hålls de diplomatiska banden med de Förkastade vid liv, samtidigt som mänskliga extremister och Scourge hålls stången.",["race:Undead"]="Det här är ditt förfäders hemland två gånger om: kungariket du byggde när du levde och den osäkra fristad du måste försvara som odöd under Lady Sylvanas."},sec={{t="Ett land i skymning",b="Tirisfal Glades var en gång mänsklighetens bördiga vagga, men har vissnat under Lich Kings pestförbannelse. Solen tränger sällan igenom det grumliga dunklet och lägger ett evigt, sjukligt blekt sken över döende skogar, försummade pumpaland och kalla kustkullar. De gamla gårdarna Agamand Mills och Balnir Farmstead står fortfarande kvar, men deras forna herrar har till största delen hamnat i massgravar eller återuppstått som rastlösa döda. Trots förödelsen genomsyras landsbygden av en mörk motståndskraft, med städer som Brill och den avskilda fristaden Deathknell som fästen, där nyväckta Förkastade lär sig uthärda sitt andra liv."},{t="Krig på två fronter",b="Lady Sylvanas gör anspråk på herraväldet över området från de underjordiska Ruins of Lordaeron, men de Förkastade är fortfarande trängda från alla håll. Kvarvarande trälar från Scourge härjar fortfarande i hålor, på fält och i förfallna kryptor, helt underställda Northrends frusna tron. I öster har den fanatiska Scarlet Crusade gjort norra Tirisfal till sitt främsta fäste och verkar från Scarlet Monastery. De är hängivna åt att utrota alla odöda varelser, vare sig de är levande eller döda, och deras utposter och patruller utkämpar ständigt gerillakrig mot Förkastades spejare och civila resenärer."},{t="Ekon från det forntida förflutna",b="Långt innan de mänskliga rikena krönte sina första monarker bar Glades på ett uråldrigt arv. Högborne alvflyktingar försökte under en kort tid slå sig ner i skogarna, men skuggkrafter djupt under jorden började driva dem till vansinne och fick dem att vandra norrut. Under senare århundraden valde den hemliga dödliga sammanslutningen Council of Tirisfal dessa skuggiga dungar för att ge ensamma väktare kraft och skydda Azeroth från demoniska intrång."}},faq={{q="Varför är himlen grön och marken ruttnar?",a="Under det tredje kriget spred prins Arthas och Scourge De odödas pest över kungariket Lordaeron. Den magiska farsoten förgiftade inte bara befolkningen utan även jorden, träden och vattnet, och lämnade Glades i ett evigt tillstånd av kusligt, sjukligt förfall.",al={"varför är tirisfal fördärvat","vad hände med tirisfal","varför håller tirisfal på att dö"}},{q="Vad är skillnaden mellan de Förkastade och Scourge här?",a="De Förkastade är odöda som bröt sig fria från Lich Kings telepatiska herravälde efter slaget vid Mount Hyjal och valde att följa Lady Sylvanas Windrunner av egen fri vilja. Scourge som strövar kring gårdarna och ruinerna förblir tanklösa slavar, bundna till Lich Kings befallningar.",al={"förkastade jämfört med scourge","varför anfaller zombier odöda","är alla odöda onda"}},{q="Vilka är de rödpansrade soldaterna som anfaller resenärer?",a="De tillhör Scarlet Crusade, en kompromisslös utbrytarorden bestående av forna paladiner från Silver Hand och överlevare. De är övertygade om att alla odöda är oförbätterliga styggelser som måste renas med svärd och eld, och avrättar med fanatiskt hat både tanklösa trälar och viljestarka Förkastade.",al={"scarlet crusade","röda människor","människor från klostret"}},{q="Varifrån kommer namnet Tirisfal?",a="Namnet är äldre än alla mänskliga riken, och dess verkliga ursprung har gått förlorat i historien. Det är mest känt genom Council of Tirisfal, den hemliga magiorden som gav väktarna kraft att skydda Azeroth från demoner.",al={"tirisfals betydelse","tirisfals ursprung"}},{q="Var börjar nyväckta Förkastade sin färd?",a="Nyväckta Förkastade kommer ut ur kryptorna i Shadow Grave i Deathknell, en avskild stad i sydvästra Tirisfal. Där bedömer administratörer och bödlar om de återuppståndna döda har det förstånd och den lojalitet som krävs för att tjäna den Mörka Damen.",al={"odödas startområde","var ligger deathknell","de förkastades startområde"}},{q="Hur lämnar resenärer Tirisfal för andra kontinenter?",a="Ett stort zeppelintorn som drivs av gobliner står på sluttningen söder om Brill, precis utanför Ruins of Lordaeron. Luftskeppen erbjuder direkt och regelbunden färd över haven till Orgrimmar i Kalimdor och Grom'gol Base Camp i Stranglethorn Vale.",al={"zeppeliner i tirisfal","hur tar man sig till orgrimmar","hur tar man sig till stranglethorn"}}},fx={["6c272224"]={q="Vad är Tirisfal Glades?",a="Tirisfal Glades är de Förfallnas kärnland vid Lordaerons norra kust. Området var en gång den fredliga, bördiga kärnan i ett stolt mänskligt kungarike, men härjades av Scourges odödlighetsplåga under det tredje kriget. I dag täcker fördärvade skogar och ett ständigt grönt dunkel kullarna, omgivna av ruinerna av Lordaerons huvudstad, fientliga fanatiker, vilda bestar och kvarvarande odöda.",al={"vad är tirisfal","berätta om tirisfal glades","lore om tirisfal"}},["342b65f9"]={q="Har det här alltid varit de odödas land?",a="Nej. I tusentals år var Tirisfal den mänskliga civilisationens vagga och det blomstrande hjärtat i kungariket Lordaeron. Fredliga gårdar, välmående kvarnar och små byar frodades under kung Terenas Menethil. Den tiden fick ett våldsamt slut under det tredje kriget, när prins Arthas och Cult of the Damned drog fram med pesten och förvandlade invånarna till odöda slavar. Sylvanas befriade dem sedan.",al={"var tirisfal alltid odött","vilka bodde här tidigare","tirisfal före pesten"}},["4790468d"]={q="Vilka bor i eller styr Tirisfal Glades?",a="De Förfallna gör anspråk på Tirisfal Glades under drottning Sylvanas Windrunners styre från Undercity. Men deras grepp om området utmanas ständigt. Fanatiska Scarlet Crusade håller befästningar och sitt stora kloster i nordöst, medan tanklösa Scourge stryker omkring på övergivna gårdar. Vid den östra gränsen, vid The Bulwark, samverkar de Förfallna med Argent Dawn för att hålla Plaguelands fasor i schack.",al={"vem styr tirisfal","vem kontrollerar tirisfal glades","fraktioner i tirisfal"}},["97ffdb73"]={q="Är Tirisfal Glades farligt?",a="Extremt farligt. Utanför de Förfallnas utposters murar möter du kvarvarande tanklösa Scourge, vilda gnoller, jättespindlar och aggressiva djur som smittats av pesten. Ännu värre är fanatikerna i Scarlet Crusade, som avrättar alla odöda de får syn på. Långt österut ligger Western Plaguelands, där monster som är långt dödligare än allt i Tirisfal sliter sönder den oförsiktige.",al={"hur farligt är tirisfal","hot i tirisfal","är det tryggt här"}},["30e6283a"]={q="Vem bestämmer i Brill?",a="Magistrate Sevren sköter Brills civila förvaltning och ansvarar för stadens återuppbyggnad och invånarnas dagliga överlevnad. Den militära ledningen och de taktiska operationerna, särskilt kampanjen mot den närliggande Scarlet Crusade, leds av Executor Zygand.",al={"ledare i brill","vem leder brill","ansvarig i brill"}},["3fc3649e"]={q="Vem rapporterar Magistrate Sevren till?",a="Sevren tjänar den Mörka Damen, drottning Sylvanas Windrunner. Som magistrat i Brill företräder han de Förfallnas kronas civila myndighet i regionen och samarbetar direkt med kungliga exekutorer och Royal Apothecary Society i Undercity.",al={"sevrens chef","vem rapporterar sevren till","ledningskedjan i brill"}},["381a9b46"]={q="Var finns bansheedrottningen?",a="Lady Sylvanas Windrunner bor i Royal Quarter i Undercity, djupt under ruinerna av Capital City, strax söder om Brill. Från sin tronhall leder hon de Förfallna i kriget mot Scourge och Scarlet Crusade.",al={"var är sylvanas","hitta sylvanas","bansheedrottningens plats"}},e7993821={q="Vad är Brill?",a="Brill är de Förfallnas främsta stad i centrala Tirisfal Glades, vid vägkorsningen norr om Capital City. Det var en gång en levande bosättning under Barov-ätten. Efter det tredje kriget byggdes den upp för att ge nyvaknade odöda en plats för vila, handel och organisering innan de ger sig ut i världen.",al={"om brill","vad är brill för slags stad","lore om brill"}},["529e09c8"]={q="Bodde det levande människor här tidigare?",a="Ja. Brill var en gång ett stillsamt mänskligt samhälle i kungariket Lordaeron. Orten blev centrum för tidiga pestexperiment som Kel'Thuzad låg bakom. De ledde till massdöd och väldiga gemensamma gravar, långt innan prins Arthas kom dit för att undersöka saken.",al={"bodde människor i brill","brills historia som levande stad","vilka bodde i brill"}},["7b7ff5e2"]={q="Vad är Gallows' End Tavern?",a="Gallows' End Tavern är Brills centrala samlingslokal och värdshus. Där erbjuds skydd, vidriga drycker och en stunds vila från de dystra gläntorna utanför. I de mörkare hörnen håller de Förfallna fångade fiender, som fanatiker från Scarlet Crusade, för skumma experiment med alkemistblandningar.",al={"gallows' end tavern","värdshus i brill","vad är gallows' end"}},["0d8014ee"]={q="Vad är grejen med Agamand Mills?",a="Agamand Mills var en gång den rikaste och mest produktiva jordbruksegendomen i Tirisfal Glades, känd för sitt mjöl och spannmål. När pesten slog till blev hela området överrunnet och en massaker följde. I dag står där en ruttnande ruin full av väderkvarnar och kvarvarande odöda från Scourge.",al={"lore om agamand mills","vad hände med agamand mills","agamand mills"}},["001d4abe"]={q="Vilka var Agamand-ätten?",a="Agamand-ätten var en adlig och välbärgad mänsklig familj som byggde ut de vidsträckta kvarnarna och ägde mark runt om i Tirisfal, bland annat i Brill. Under det tredje kriget kunde deras rikedom inte rädda dem. Familjen föll för Scourge, och dess återuppväckta patriarker hemsöker fortfarande egendomen.",al={"agamand-familjen","vilka bodde vid agamand mills","agamand-ätten"}},eeb96a2c={q="Varför är de fientliga mot oss när de också är odöda?",a="De odöda som hemsöker Agamand Mills återfick aldrig sin fria vilja. Till skillnad från de Förfallna, som slet sig loss från Lich Kings mentala grepp, förblir de här varelserna förslavade som tanklösa Scourge-trälar. De tvingas förgöra alla levande eller upproriska döda som inkräktar på deras område.",al={"varför anfaller agamand oss","varför är agamands odöda fientliga","varför slåss odöda mot varandra"}},a357af07={q="Vart leder vägen efter Tirisfal?",a="De flesta Förfallna reser söderut genom bergspasset till Silverpine Forest för att hjälpa till att säkra den södra gränsen och bekämpa agenter från Dalaran och gnoller från Rot Hide. Luftskeppen söder om Brill tar dig också till Orgrimmar eller Grom'gol Base Camp på andra sidan havet.",al={"vart efter tirisfal","nästa område efter tirisfal","efter tirisfal glades"}},["50336b90"]={q="Vad är Undercity?",a="Undercity är de Förfallnas vidsträckta underjordiska huvudstad, byggd i de gamla kloakerna, gravkamrarna och katakomberna under de förstörda Ruins of Lordaeron. Staden fungerar som drottning Sylvanas fäste och som ledningscentral för de Förfallnas verksamhet i hela Azeroth.",al={"vad är undercity","lore om undercity","om undercity"}},ddddba9f={q="Är Silverpine nästa gräns?",a="Ja. Om du följer vägen söderut från Tirisfal kommer du direkt till Silverpine Forest. Det är den naturliga fortsättningen på din tjänst hos Forsaken, där du möter det växande hotet längs Lordaerons södra gränser.",al={"silverpine härnäst","ska jag till silverpine härnäst","silverpines gräns"}},["789ead4d"]={q="Hur hamnade jag i Tirisfal Glades?",a="Om du nyligen återuppstått som Forsaken dog du när Scourge föll över Lordaeron och begravdes här. När Lich Kings grepp bröts återfick du din fria vilja och klöste dig upp ur graven i den avskilda dalen Deathknell. Om du tillhör någon av de andra Horde-nationerna kom du troligen hit via zeppelintornen mellan Brill och Undercity, som förbinder detta fördärvade rike direkt med Orgrimmar och Grom'gol Base Camp.",al={"hur hamnade jag här","hur kom jag till tirisfal glades","hur kom jag hit"}},["89135166"]={q="Vad förväntas jag göra i Tirisfal Glades?",a="Ditt mål är att hjälpa Forsaken att säkra sitt osäkra grepp om Lordaerons fördärvade hjärtland. Från kryptorna i Deathknell ska du ta dig mot staden Brill och rena övergivna gårdar från den själlösa Scourge, slå ut fanatiska Scarlet Crusade-anhängare som tränger in från norr och gallra bland de pestsmittade bestarna i de ruttnande skogarna. På så sätt visar du Lady Sylvanas vad du går för och förbereder dig på att tjäna hennes växande kungarike under ruinerna av Capital City.",al={"vad ska jag göra här","varför är jag i tirisfal","vad är mitt mål här"}}},fp="15,338,18.442.0,19.456.0,26.372.0,42.269.0,65.287.0,53.289.0,39.222.0,53.244.0,53.247.0"}
P.entries["zone:undercity"] = {n="Undercity",s="Djupt under de krossade ruinerna av Lordaerons huvudstad ligger Undercity, de Förkastades mörka fäste. Det höggs ursprungligen ut ur uråldriga kungliga kryptor och fängelsehålor av Scourge. Lady Sylvanas Windrunner intog det och gjorde det till en ointaglig underjordisk fristad. I dag är det maktens säte för de Förkastade och Hordens viktiga bastion i norra Eastern Kingdoms.",h="Djupt under de krossade ruinerna av Lordaerons huvudstad ligger Undercity, de Förkastades mörka fäste.",kw={"apothecarium","arthas","de förkastade","lordaeron","scourge","sylvanas","terenas","tirisfal","undercity","varimathras"},ang={["faction:Horde"]="Som Hordens främsta fäste i Eastern Kingdoms säkrar Undercity zeppelinförbindelser direkt till Durotar och Grom'gol Base Camp.",["race:Human"]="Under jorden i ditt fallna förfädersrike ligger en mörk förvrängning av Lordaerons kungliga kryptor, där dina forna fränder nu vandrar som lik.",["race:Orc"]="Djupt inne i dessa fängelsehålor satt den legendariska krigshövdingen Orgrim Doomhammer en gång fängslad av Lordaerons allians, innan han gjorde sin historiska flykt.",["race:Undead"]="Undercity är din suveräna fristad och ditt hemland, uthugget av dina egna händer efter att du bröt Lich Kings järngrepp om ditt sinne."},sec={{t="Från kungliga kryptor till Scourges fäste",b="Långt innan pesten svepte över Lordaeron kallades katakomberna, fängelsehålorna och kloakerna under palatset tillsammans för Undercity. Där fanns adelns gravar, rikets djupaste fängelser, där den tidigare krigshövdingen Orgrim Doomhammer en gång hölls fången innan han flydde, och rikets fattigaste invånare. När Arthas Menethil mördade kung Terenas och ödelade huvudstaden år 20 efter Dark Portal beordrade prinsen sina odöda tjänare att gräva ut och utvidga gångarna under jord till ett befäst säte för Scourges styre."},{t="De Förkastades uppgång",b="Scourge hann aldrig färdigställa sin mörka huvudstad. När Lich Kings krafter försvagades efter slaget vid Mount Hyjal bröt Lady Sylvanas Windrunner sig fri från det kollektiva medvetandet och tog tusentals odöda med sig. Hon lockade Arthas i ett bakhåll och drev honom tillbaka till Northrend. Efter ett skoningslöst inbördeskrig på tre fronter mot resterna av Scourge, dreadlords och mänskligt motstånd tog Sylvanas katakomberna som inte var färdigbyggda. Hon gav sitt folk namnet de Förkastade och ledde under flera år arbetet med att färdigställa den vidsträckta underjordiska staden."},{t="De fördömdas arkitektur",b="Undercity är byggt i koncentriska ringar som är indelade i olika kvarter. I dess hjärta ligger Trade Quarter, som är förbundet med palatsruinerna ovanför genom stora hissar. Runt det ligger War Quarter, Rogues' Quarter, Magic Quarter och det giftiga Apothecarium, där Royal Apothecary Society brygger våldsamma farsoter i kanaler fyllda av grönt slem. Ännu längre in ligger Royal Quarter, där Banshee Queen håller hov tillsammans med sin dreadlordbefälhavare Varimathras. Där vaktas de av legioner av resliga styggelser."}},faq={{q="Vad var Undercity innan de odöda tog över?",a="Under Lordaerons palats låg de uråldriga kryptorna för mänskliga kungligheter, tillsammans med stadens fängelsekomplex och vidsträckta kloaksystem. Där fanns krigsfångar, däribland Orgrim Doomhammer, och utblottade invånare som levde i skuggorna under jord. Efter att ha plundrat huvudstaden började prins Arthas göra katakomberna till en fästning för Scourge, innan Sylvanas intog dem.",al={"undercitys ursprung","vad var undercity från början","lordaerons kloakers historia"}},{q="Varför är staden byggd under jord i stället för ovan jord?",a="Lordaerons stad ovan jord ödelades fullständigt under det tredje kriget. Den var därför svår att försvara mot Scarlet Crusade, Scourges styrkor och överlevande från alliansen. Gångarna under jord erbjöd naturliga försvarsverk, trånga passager och skydd från insyn, vilket lät de Förkastade slutföra Scourges ursprungliga byggnadsarbete och frodas obemärkta.",al={"varför bo under jord","varför återuppbygger man inte lordaeron","varför ligger undercity under ruinerna"}},{q="Vem styr över Undercity?",a="Staden styrs av Lady Sylvanas Windrunner, Banshee Queen och de Förkastades drottning. Hon regerar från Royal Quarter, vaktad av de Förkastades kungliga väktare och sin underkuvade dreadlordlöjtnant Varimathras.",al={"vem leder undercity","undercitys härskare","vem styr undercity"}},{q="Vad föreställer kung Terenas minnesmärke i ruinerna ovanför?",a="Ovanför stadens främsta hissar står ett stenmonument över den mördade kung Terenas Menethil II. Hans kropp finns inte där, eftersom den kremerades och askan kastades bort under Kel'Thuzads återuppståndelse. Överlevande människor från alliansen högg modigt ut monumentet bland ruinerna, så att minnet av Lordaerons sista sanna kung skulle leva vidare.",al={"kung terenas grav","lordaerons tronrum grav","vem byggde graven ovanför undercity"}},{q="Vad är det för märkliga ljud i Lordaerons tronrum?",a="I det förstörda tronrummet ovanför Undercitys hissar dröjer det förflutnas spöklika ekon kvar. Besökare som står i mitten kan höra svaga ljud från vålnader: festklockorna och rosenbladen när Arthas återvände, profeten Medivhs varningsord och det sista samtalet mellan kung Terenas och hans fadersmördande son.",al={"spökljud i tronrummet","viskningar i tronrummet","röster i lordaerons tronrum"}},{q="Varför tillåter de Förkastade andra medlemmar av Horden här?",a="De Förkastade bildade en allians av nödvändighet med krigshövding Thralls Horde för att överleva, omringade som de är av fientliga fanatiker från Scarlet Crusade och legioner från Scourge. De levande raserna i Horden har svårt att uthärda de giftiga ångorna och de alkemiska floderna, men sändebud och resande släpps in för att främja diplomatiska och militära band.",al={"varför finns orcher i undercity","horden i undercity","varför tillhör undercity horden"}}},fx={a590d153={q="Vad är Undercity?",a="Undercity är Forsakens underjordiska huvudstad, byggd direkt under de krossade ruinerna av Capital City i Tirisfal Glades. Staden höggs ut ur gamla kungliga kryptor, kloaker och katakomber. Prince Arthas byggde ut den till ett fäste för Scourge innan Lady Sylvanas Windrunner och hennes avfälliga odöda tog över under inbördeskriget. I dag är den en befäst fristad för odöda med fri vilja, genomkorsad av giftigt slam och noggrant bevakad mot alla levande inkräktare.",al={"vad är undercity","berätta om undercity","undercitys historia"}},c51b16b2={q="Vad hände med Lordaerons gamle kung?",a="King Terenas Menethil II mördades i tronsalen direkt ovanför staden av sin egen son, Prince Arthas. Efter att ha återvänt från Northrend, förvriden av runklingan Frostmourne, slog Arthas ner sin far och släppte lös Scourge över kungariket. Dödsriddaren stal senare Terenas aska för att återuppväcka Kel'Thuzad. Kvar blev bara minnesstenen och det intorkade blodspår som du fortfarande kan se nära den förstörda tronen.",al={"king terenas öde","vad hände med king terenas","vem dödade king terenas"}},c11144c7={q="Vem var Arthas?",a="Arthas Menethil var kronprins av Lordaeron och en hyllad paladin i Silver Hand. I sin desperation att stoppa undeath-pesten som svepte över hans hemland blev hans korståg hänsynslöst och fanatiskt. I Northrend tog han den förbannade runklingan Frostmourne, som slukade hans själ och gjorde honom till Lich Kings fruktade förkämpe. Han återvände hem och slaktade sin far, jämnade Lordaeron med marken och reste till slut tillbaka norrut för att förena sig med Frozen Throne.",al={"vem är arthas","prince arthas historia","arthas menethil"}},["7f6bbd49"]={q="Vem är Sylvanas Windrunner?",a="Lady Sylvanas Windrunner var en gång Silvermoons tappra ranger-general och försvarade Quel'Thalas mot Scourge under det tredje kriget. När hon föll slet Arthas hennes själ ur kroppen och förvandlade henne till en banshee för att plåga henne. När Lich Kings grepp försvagades bröt hon sig fri, återtog sin fysiska form och samlade andra självständiga odöda till Forsaken. Nu härskar hon som deras Banshee Queen från Royal Quarter.",al={"vem är banshee queen","sylvanas historia","vem är sylvanas"}},["2a8de90f"]={q="Varför kallas Sylvanas Dark Lady?",a="Forsaken hedrar Sylvanas som Dark Lady eftersom hon befriade dem från Lich Kings själlösa träldom och gav dem skydd när resten av Azeroth ville utrota dem helt. Titeln används tillsammans med Banshee Queen och speglar både hennes skuggfyllda makt över döden och hennes odöda undersåtars glödande, orubbliga hängivenhet.",al={"varför dark lady","sylvanas titel dark lady","vad betyder dark lady"}},["84f18f47"]={q="Varför tillhör Forsaken Horde?",a="Omgivna av fientliga Scarlet Crusade-anhängare, obevekliga Scourge-styrkor och hämndlystna rester av Alliance kunde Forsaken inte överleva ensamma i Lordaeron. Lady Sylvanas sträckte sig över havet till Warchief Thrall och slöt en pragmatisk allians av ömsesidig nytta. Horde fick ett viktigt militärt fäste i Eastern Kingdoms, medan Forsaken säkrade nödvändiga förstärkningar och politisk legitimitet i sin kamp för överlevnad.",al={"varför forsaken är med i horde","odöda går med i horde","forsaken, horde och alliance"}},["71200045"]={q="Vad är Scourge, och finns de fortfarande i närheten?",a="Scourge är den väldiga, glupska armé av själlösa odöda som skapades av Burning Legion och styrs av Lich King från Northrend. Forsaken ryckte Undercity och Tirisfal ur deras grepp, men Scourge är fortfarande ett omedelbart, dödligt hot. Deras legioner kväver fortfarande de närliggande Plaguelands under Kel'Thuzads befäl och hemsöker övergivna gårdar och kryptor i hela Tirisfal Glades.",al={"finns scourge i närheten","vad är scourge","scourge i lordaeron"}},["501548ab"]={q="Var är Lich King nu?",a="Lich King håller till på Frozen Throne i Northrends avlägsna, iskalla ödemarker. Efter inbördeskriget i Plaguelands flydde Prince Arthas från Lordaeron för att skydda sin försvagade mästare. Han besteg glaciären och förenade deras väsen till en enda skräckinjagande varelse. Från det arktiska fästet vakar hans iskalla blick fortfarande över Azeroth.",al={"var är lich king","lich kings plats","var är arthas nu"}},["4cc7f971"]={q="Vilka är Scarlet Crusade?",a="Scarlet Crusade är en fanatisk orden av mänskliga fanatiker, född ur ruinerna av Lordaerons försvar. Förblindade av sitt rättfärdiga hat mot odöda skiljer de inte mellan själlösa Scourge och Forsaken med fri vilja. De ser alla som smittats av undeath, och alla levande främlingar som tolererar dem, som avskyvärda missfoster som bara förtjänar bålet. Deras främsta fäste i Tirisfal är Scarlet Monastery.",al={"vilka är scarlet crusade","scarlet crusade-anhängare","scarlet crusades historia"}},["271820ed"]={q="Är Undercity farligt?",a="Det är oerhört farligt, särskilt för levande. Kanaler med rått alkemiskt avfall och giftigt slam löper genom stadens gator. De fyller de väldiga salarna med giftiga ångor som gör det farligt att andas för besökare av kött och blod. Under de stenlagda kvarteren ligger kloaker fulla av ohyra, och ännu djupare pågår hemliga experiment där mörk alkemi och hänsynslösa mord planeras dagligen.",al={"är undercity säkert","faror i undercity","undercitys faror"}},["2539a3c3"]={q="Hur hamnade jag i Undercity?",a="Som Forsaken ledde din väg naturligt hit efter att du vaknat till liv i Deathknell och visat din lojalitet genom Tirisfal Glades. Du följde vägarna förbi Brill och tog dig ner under de krossade ruinerna av Capital City. Om du kommer från Kalimdor eller avlägsna länder anlände du troligen med en Horde-zeppelin som lade till vid tornen utanför huvudstaden, eller så vandrade du genom det fördärvade landskapet. Undercity är Hordes främsta fäste i norra Lordaeron och erbjuder skydd och mening under det gamla palatsets katakomber.",al={"hur hamnade jag här","hur kom jag till undercity","hur tar man sig till undercity"}},b63c4cf2={q="Vad förväntas jag göra i Undercity?",a="Du är här för att hjälpa Forsaken och samla Hordes styrkor mot farorna runt Lordaeron. I stadens koncentriska kvarter kan du rådfråga klassinstruktörer, skaffa förnödenheter och vända dig till Royal Apothecary Societys mörka forskare. Utöver att sköta ditt yrke ska du ta på dig uppdrag från Lady Sylvanas Windrunner och hennes löjtnanter. Forsaken utkämpar krig på flera fronter: de rensar bort resterna av den själlösa Scourge, driver tillbaka den fanatiska Scarlet Crusade och säkrar trygg mark där de odöda med fri vilja kan överleva.",al={"vad gör jag här","vad ska jag göra i undercity","varför är jag här"}}},fp="9,318,36.556.0,20.416.0,26.421.0,54.450.0,60.340.0,24.362.0,51.333.0,57.328.0,51.322.0"}
P.entries["zone:ungoro"] = {n="Un'Goro Crater",s="Un'Goro Crater är en nedsänkt urskogsdjungel mellan Tanaris och Silithus torra ödemarker. Denna frodiga caldera domineras av kringströvande dinosaurier, levande elementaler och en central vulkan. Här finns uråldriga Titanreliker och kraftkristaller vars ursprung förblir ett stort mysterium.",h="Un'Goro Crater är en nedsänkt urskogsdjungel mellan Tanaris och Silithus torra ödemarker.",kw={"devilsaur","fire plume ridge","gudarnas land","lakkari","marshal's refuge","kraftkristaller","torwa pathfinder","ungoro","ungoro crater"},ang={["class:Druid"]="Druider från Cenarion Circle studerar Un'Goros isolerade ekosystem och skördar dess rika jord för att odla Morrowgrain. De försöker förstå den rena, otämjda livskraft som håller calderan vid liv.",["faction:Alliance"]="Alliansens naturkännare samlas kring Williden Marshal och J.D. Collie vid Marshal's Refuge. De tävlar om att tyda Titanpylonerna samtidigt som de skyddar forskare från Darnassus som samlar jordprover.",["faction:Horde"]="Hordens äventyrare anländer ofta via Tanaris för att pröva sin skicklighet mot legendariska devilsaurs och hjälpa Thunder Bluffs örtmästare att odla Morrowgrain från Un'Goros uråldriga jord.",["profession:Herbalism"]="Bäckenets rikliga fuktighet ger näring åt sällsynt växtlighet. Det är en av få platser i Kalimdor där Blindweed, Dreamfoil och Golden Sansam växer tillsammans med Firebloom på vulkanens sluttningar.",["profession:Mining"]="De branta kraterväggarna och klipporna vid Fire Plume Ridge är rika på Mithril Deposits och Rich Thorium Veins, vilket gör området till ett förstklassigt mål för den som söker malm av högsta kvalitet."},sec={{t="Gudarnas land",b="Un'Goro Crater ligger inklämd mellan vidsträckta öknar och trotsar södra Kalimdors geografi. Uråldriga Night Elf-arkiv om War of the Shifting Sands berättar att de insektsliknande Qiraji hejdades vid kraterns kanter och inte kunde tränga in i det som på deras språk kallades ”Gudarnas land”. Lärda tror att calderan tjänade som testområde eller forntida boplats för Titans när de formade Kalimdor. Stenpyloner reser sig längs bergsryggarna och surrar av energi, medan blå, röda, gröna och gula kristallformationer skjuter upp ur den uråldriga jorden."},{t="Ett vilt ekosystem",b="Un'Goro saknar städer, samhällen och ursprungliga humanoida folk. Här frodas livet i ett otämjt, uråldrigt tillstånd. Väldiga devilsaurs smyger över Terror Runs slätter, rovgiriga bloodpetals piskar till i The Marshlands och slemvarelser krälar över tjärgroparna i Lakkari. I kraterns mitt tornar Fire Plume Ridge upp sig, en aktiv vulkantopp full av fientliga eldelementaler som leds av varelsen Blazerunner. För upptäcktsresande och skinnare erbjuder bäckenet enastående naturtillgångar, däribland eftertraktade devilsaurhudar, om man överlever näringskedjan."},{t="Marshal's Refuge",b="Den civiliserade närvaron i kratern är nästan helt begränsad till Marshal's Refuge, ett upphöjt läger inbäddat i de norra klipporna. Under Williden Marshals ledning försökte en expedition med forskare, naturkännare och lyckosökare katalogisera bäckenets skatter, men de blev hårt ansatta av de monstruösa vilddjuren och drevs upp på högre mark. I dag fungerar lägret som en hårt prövad bas för oförvägna resenärer som studerar kraterns mystiska kraftkristaller, kartlägger vulkanisk aktivitet och håller vaksam uppsikt över silithidsvärmar som tränger igenom de södra bergsryggarna."}},faq={{q="Hur tar du dig in i Un'Goro Crater?",a="Resenärer kan ta sig in via naturliga sluttningar längs kraterväggarna. En finns i Tanaris sydvästra hörn nära Thistleshrub Valley, och en annan leder in från nordöstra Silithus. Vårdslösa äventyrare hoppar ibland nerför klipporna, men fallet är dödligt utan magisk hjälp. Marshal's Refuge i norr har flygförbindelser till Gadgetzan och Cenarion Hold.",al={"hur man tar sig in i ungoro","ingång till ungoro","hur man når ungoro crater"}},{q="Vad används de färgade kraftkristallerna till?",a="Röda, blå, gröna och gula Power Crystals ligger utspridda över djungelns mark. Med vägledning från gnomforskaren J.D. Collie vid Marshal's Refuge kan upptäcktsresande tyda instruktionerna för att använda kristallerna vid de norra, östra och västra pylonerna. När man kombinerar särskilda färger vid rätt pyloner utnyttjas vilande Titanenergier för att skapa skyddande eller läkande amuletter.",al={"ungoro-kristaller","röda blå gröna gula kristaller i ungoro","kraftpyloner"}},{q="Varför är Un'Goro frodigt trots att det omges av öknar?",a="Lärda tror att Un'Goros onaturliga växtkraft är konstgjord och härrör från Titans, som formade världen. Titaniska ledningar, varm geotermisk aktivitet från Fire Plume Ridge och uråldrig leyenergi ger näring åt ett isolerat ekosystem med extremt snabb tillväxt, som står emot det torra klimatet i grannområdena Tanaris och Silithus.",al={"varför ungoro är en djungel","ungoro och öknen","hur det växer växter i ungoro"}},{q="Varför kallade Qiraji platsen för ”Gudarnas land”?",a="Enligt tavlor som översatts från War of the Shifting Sands hejdades insektssvärmarna vid kraterns tröskel. Geologen Larksbane, som översatte berättelsen, kopplar namnet till teorierna om att Titans en gång bodde i kratern och undrar om Aman'Thul själv vakade över Gudarnas land.",al={"vad gudarnas land betyder","qiraji i ungoro","varför silithiderna inte kunde ta ungoro"}},{q="Vad används Un'Goro Soil till?",a="Högar av rik, kraftfull jord ligger utspridda över kraterbäckenet. När jorden samlas in kan den kombineras med Tharlendris-frön i en Evergreen Pouch för att odla Morrowgrain, en mystisk ört som forskare i Thunder Bluff, Darnassus och Cenarion Circle är mycket angelägna om.",al={"jordprov från ungoro","vad ungoro soil används till","morrowgrain och jord"}},{q="Finns det humanoida bosättningar eller grottor här?",a="I Un'Goro Crater finns en grotta, The Shaper's Terrace, för nivåerna cirka femtioåtta till sextio, men inga ursprungliga humanoida folk. Den enda permanenta bosättningen är Marshal's Refuge, en liten expeditionspost på den norra randen. Bortsett från enstaka eremitjägare eller vilsekomna upptäcktsresande är resten av calderan helt vildmark.",al={"grottor i ungoro","vem som bor i ungoro","humanoider i ungoro"}}},fp="14,269,13.410.0,18.462.0,16.490.0,35.282.0,45.336.0,56.270.0,51.330.0,30.235.0,52.287.0"}
P.entries["zone:wailing"] = {n="Wailing Caverns",s="Under Lushwater Oasis, i den torra The Barrens, ligger Wailing Caverns, ett labyrintiskt nätverk av underjordiska källor och sprickor som fått sitt namn efter den kusliga visslingen från instängd ånga. Det som började som ett ädelt druidiskt försök att återuppliva Kalimdors solblekta savann har förvandlats till en förvriden, giftig underjordisk värld. Grottorna myllrar nu av förvridet djurliv och fallna lärjungar som korrumperats av en djup, onaturlig mardröm.",h="Under Lushwater Oasis, i den torra The Barrens, ligger Wailing Caverns, ett labyrintiskt nätverk av...",kw={"deviate","druids of the fang","emerald nightmare","lady anacondra","lord cobrahn","lord pythas","lord serpentis","lushwater oasis","mutanus","naralex","verdan"},ang={["class:Druid"]="För druider av både Cenariontraditionen och taurenstammen är grottorna en tragisk varning om farorna i The Emerald Dream och en högtidlig plikt att rena sina fallna fränder, Druids of the Fang.",["race:NightElf"]="Naralex var en vördad gestalt bland nattälvdruider, och tragedin när han korrumperades av The Emerald Nightmare blev en smärtsam katastrof för hans folk på andra sidan havet.",["race:Tauren"]="De förvridna vattnen hotar de sårbara oaser som upprätthåller liv i The Barrens. Därför är det livsviktigt för stammarna i Mulgore och The Crossroads att källorna renas."},sec={{t="En ädel vision blir giftig",b="Nattälvdruiden Naralex upptäckte ursprungligen detta vidsträckta vattensystem och utformade en djärv plan: genom att öppna en kanal rakt in i The Emerald Dream skulle han leda ren, ursprunglig livsessens genom de underjordiska källorna och förvandla det uttorkade The Barrens till ett blomstrande, grönskande paradis. Djupt inne i grottorna föll Naralex i drömgemenskap, förankrad av sina lojala akolyter. Tragiskt nog berörde druidens sovande sinne The Emerald Nightmare i stället för att nå ren livskraft. Den ruttnande korruptionen tog genast över honom och förvandlade hans välmenade kanal till en ventil som pumpade gift och vansinne in i de underjordiska vattendragen."},{t="Druiderna av huggtanden",b="När mardrömmens mörka energi strålade från Naralex hjälplösa gestalt dukade hans elever under för vansinnet. De övergav Cenarion Circles fridfulla visdom och bildade den fanatiska gruppen Druids of the Fang. Ledarna tog reptilform: Lady Anacondra, Lord Cobrahn, Lord Pythas och Lord Serpentis. Nu bejakar de grottornas giftiga mutation i stället för att bekämpa den. De skyddar aktivt sin sovande mästare från all inblandning utifrån, eftersom de tror att denna förvridna tillväxt är naturens sanna utveckling."},{t="Mardrömmen blir kött",b="Att bryta Druids of the Fangs grepp räddar inte automatiskt Naralex. När hans återstående okorrumperade lärjungar inleder ritualen för att varsamt väcka honom ur transen vid Dreamer's Rock, stöter den sovande alvens vilda undermedvetna våldsamt bort sin djupaste skräck. Varelsen som bryter fram, en monstruös och förvriden murloc vid namn Mutanus the Devourer, är den fysiska manifestationen av Naralex värsta mardrömmar. Först när denna styggelse dödas kan förbindelsen till mardrömmen brytas. Då kan Naralex vakna, anta fågelform och flyga bort från de förgiftade grottorna."}},faq={{q="Varför heter platsen Wailing Caverns?",a="Grottan har fått sitt namn efter de sorgsna, tjutande rop som hörs genom gångarna. Ljuden uppstår naturligt när underjordiska ångventiler och kraftiga vindbyar pressas genom trånga sprickor i kalkstenen.",al={"varför heter det wailing caverns","namnets ursprung","varför ylar de"}},{q="Vad fick bestarna där inne att bli ”deviate”?",a="När Naralex hamnade under The Emerald Nightmares inflytande sipprade de förgiftade drömkrafterna direkt ut i de underjordiska källorna. När de naturliga rovödlorna, krokilisks och ormarna drack av och levde i det förorenade vattnet muterade de till onaturliga ”deviate”-varianter.",al={"deviate-korruption","varför muterar rovödlorna","deviate-bestarnas ursprung"}},{q="Vilka är Druids of the Fang?",a="De var en gång Naralex hängivna nattälvs- och taurenakolyter. Mardrömmen korrumperade dem tillsammans med honom, och deras sinnen bröts sönder. Deras druidiska konster förvriddes till dyrkan av ormar och gift, och de antog titlar som Cobrahn, Pythas och Anacondra.",al={"druiderna av huggtanden","lore om druiderna av huggtanden","vem är serpentis"}},{q="Varför är den sista bossen en jättelik murloc vid namn Mutanus?",a="Mutanus dyker upp under försöket att väcka Naralex. Varelsens natur och koppling till den sovande druiden avslöjas när ritualen fortskrider.",al={"varför är mutanus en murloc","vad är mutanus","lore om sista bossen"}},{q="Vad händer efter att Mutanus besegrats?",a="Lärjungens försök att väcka Naralex fortsätter efter mötet. Druidens öde avslöjas i slutet av ritualen.",al={"väcka naralex","naralex slut","vad händer med naralex"}},{q="Vem bor i grottan ovanför ingången?",a="Inne i grottans skalliknande ögonhåla sitter lojala medlemmar av Cenarion Circle, däribland Nalpak och Ebru. De söker modiga resenärer som kan samla in deviatehudar och rena bort korruptionen innan den helt uppslukar The Barrens.",al={"grottan ovanför ingången","npc:er i ormskallens ögonhåla","vilka är nalpak och ebru"}}},fx={["3386ab3f"]={q="Vad är Wailing Caverns?",a="Wailing Caverns är ett vidsträckt nätverk av underjordiska grottor under det torra Barrens, nära Lushwater Oasis. Naturliga källor under jord leder vatten flera kilometer genom marken och försörjer de sällsynta oaserna vid ytan i hela trakten. Grottorna upptäcktes av nattalven Naralex och skulle bli hjärtat i ett storslaget projekt för naturens återväxt. I stället blev de ett centrum för farlig korruption efter att en tragisk katastrof drabbade druiderna där inne.",al={"vad är wailing caverns","översikt över wailing caverns","om wailing caverns"}},e070a543={q="Vilka lever där nere?",a="Grottorna vimlar av onaturliga vilddjur och avfälliga druider. Naralex fördärvade anhängare, Druids of the Fang, har gjort tunnlarna till sitt revir tillsammans med muterade ormar, slemvarelser, rovfåglar och krokolisker. Utanför instansens ingång lurar vilddjur, slemvarelser och till och med utstötta i de fuktiga gångarna. De fördärvade druiderna vaktar de inre kamrarna och skyddar sin sovande mästare.",al={"vilka finns i wailing caverns","varelser i wailing caverns","invånare i wailing caverns"}},["49d47201"]={q="Varför skickade Horde mig hit?",a="De lokala bestarnas märkliga mutationer och den vidriga energi som bubblar upp ur Lushwater Oasis hotar hela Barrens. Horde och Cenarion-druiderna i Thunder Bluff kan inte tolerera en okontrollerad mörk kraft som förgiftar landet och vattendragen alldeles intill The Crossroads. Du skickades hit för att undersöka saken, göra slut på Fangs avfälliga ledare och hjälpa till att hejda den växande faran.",al={"varför är jag i wailing caverns","hordes uppdrag i wailing caverns","varför skickas jag till wailing caverns"}},d445bb78={q="Är det här en del av ett större problem i Barrens?",a="Ja. De underjordiska kanalerna under grottorna förser oaserna vid ytan i hela Barrens med vatten. Marans smitta som fördärvar vattnet i grottorna har börjat sprida sig ut i landskapet. Den får vilda varelser som rovfåglar och krokolisker att mutera och förvandlar Lushwater Oasis till en grogrund för märkliga avvikande livsformer.",al={"oaseproblemet i barrens","avvikande korruption i barrens","påverkar wailing caverns barrens"}},["038fd1cf"]={q="Sprider sig de avvikande varelserna utanför grottorna?",a="De gör redan det. De underjordiska källorna rinner direkt ut i oaser vid ytan, som Lushwater, och för med sig onaturlig växtlighet och muterade varelser till den öppna savannen. Märkliga varelser som Deviate Fish kan fångas i vattnen utanför, och aggressiva muterade rovdjur angriper allt oftare resenärer mellan oaserna och The Crossroads.",al={"sprider sig avvikarna","avvikande bestar i barrens","deviate fish utanför"}},["8502642f"]={q="Vem styr här nere?",a="Medan Naralex ligger fångad i sin fördärvade sömn djupt inne i grottorna, styr Ormens Druider till vardags över hålorna. De leds av Lord Serpentis, en gång Naralex främsta elev, som samlade sina förvridna bröder för att forma om landet till sitt eget förvridna paradis tillsammans med andra huggtandsfurstar som Cobrahn, Pythas och Lady Anacondra.",al={"vem leder wailing caverns","ledare för wailing caverns","boss i wailing caverns"}},["32be29c8"]={q="Vad är Emerald Dream, och hur hänger den ihop med den här grottan?",a="Emerald Dream är en vidsträckt andevärld som föreställer Azeroth orört och vilt. Den förvaltas av den gröna drakflocken och är tillgänglig för druider. Naralex trodde att han kunde leda drömmens rena, återställande krafter till Wailing Caverns underjordiska vattenådror för att återställa frodig växtlighet i The Barrens. Men när han tog kraften i anspråk snärjdes han av Emerald Nightmare, som projicerade en förvriden version av naturen in i de fysiska grottorna.",al={"koppling till emerald dream","wailing caverns och emerald dream","naralex och emerald dream"}},["38e519c2"]={q="Varför är alla så oroliga för den här platsen?",a="Källorna under grottorna förser de viktigaste oaserna som upprätthåller liv i hela det torra The Barrens. Om Emerald Nightmares smitta fortsätter att sippra ut i vattendragen utan att hejdas, kan de förvridna mutationerna och vansinnet som fördärvar grottans växt- och djurliv sprida sig över hela regionen och förvandla landet till en levande mardröm.",al={"varför oroa sig för wailing caverns","hotet från wailing caverns mot the barrens","hur farligt är wailing caverns"}},["81917ac6"]={q="Hur hamnade jag i Wailing Caverns?",a="Du reste söderut från The Crossroads till Lushwater Oasis efter rapporter om märkliga bestar och förgiftat vatten som läckte ut i The Barrens. Bakom den frodiga växtligheten och Kolkar-centaurernas läger ligger en väldig, skallformad grotta uthuggen ur berget. Lockad av rop på hjälp från Thunder Bluff, av Ratchets gobliner som sökte märkliga essenser eller av lärjungar som slagit läger i skallens ögonhåla ovanför, tog du dig ner förbi slingrande sprickor och underjordiska gejsrar som väste, till djupens stönande mörker.",al={"hur kom jag hit","hur tar jag mig till wailing caverns","var kom jag ifrån när jag kom hit"}},["28a012f3"]={q="Vad förväntas jag göra i Wailing Caverns?",a="Du är här för att rena den underjordiska källan från den korruption som har gripit tag i den. Nattelven Naralex föll i en mardrömslik sömn när han försökte återuppliva The Barrens, vilket förvrängde varelserna där inne och drev hans lärjungar till att bli de giftiga Ormens Druider. Du måste jaga rätt på de fyra huggtandsfurstarna: Lady Anacondra, Lord Cobrahn, Lord Pythas och Lord Serpentis, för att bryta deras grepp. Hjälp sedan den lärjunge som är kvar att väcka Naralex innan hans feberdröm slukar oasen helt.",al={"vad är mitt mål här","varför är jag i wailing caverns","vad gör jag här nere"}}},fp="15,278,31.501.0,22.495.0,24.481.1,37.218.0,50.226.0,31.267.0,51.127.1,39.123.1,52.229.0"}
P.entries["zone:warsonggulch"] = {n="Warsong Gulch",s="Warsong Gulch är en skogsklädd dal mellan Ashenvale och The Barrens, där Horde och Alliance utkämpar ett ständigt slag. Orcer från Warsong-klanen hugger ner Ashenvales träd åt Horde, och Night Elf-folket vid Silverwing Hold kämpar för att driva bort dem från den heliga skogen. Krigare av alla raser kommer för att bidra med svärd eller magi, medan båda sidor plundrar den andras fäste för att föra bort dess fana.",h="Warsong Gulch är en skogsklädd dal mellan Ashenvale och The Barrens, där Horde och Alliance utkämpar ett...",kw={"warsong gulch","slagfält","warsong outriders","silverwing sentinels","silverwing hold","warsong-sågverket","flagga","virke","ashenvale","grom hellscream"},ang={["faction:Alliance"]="Alliansens soldater slåss här för sina Night Elf-allierade, vars heliga skog faller träd för träd under Warsong-klanens yxor.",["faction:Horde"]="Varje stock som lämnar Warsong-sågverket blir en Horde-mur någonstans i Kalimdor. Att hålla dalen säkerställer att Horde kan fortsätta bygga.",["race:NightElf"]="Kaldorei har vandrat i dessa skogar i tiotusen år. Varje orch som drivs ut ur dalen innebär att en bit av Ashenvale återtas.",["race:Orc"]="Warsong-klanen är Grom Hellscreams egen, och i dalen gör hans krigare fortfarande skäl för sitt namn, med yxan i hand mot väktarna."},sec={{t="Virke och blod",b="Horde byggde sitt nya hem i Kalimdor av trä, och mycket av det kommer från Ashenvale. Warsong-klanen, Grom Hellscreams krigare, har huggit sig in i skogen sedan Horde först landsteg, och deras sågverk vid dalens ände förser Hordes läger och murar med virke. För Night Elf-folket är varje fällt träd ett sår i en skog de har vaktat i tiotusen år, och de har inte glömt att Groms krigare en gång dödade Cenarius i dessa skogar."},{t="Utposter och väktare",b="Hordes krigare här är Warsong Outriders, som får förnödenheter från Mor'shan Base Camp vid The Barrens norra gräns, där Kelm Hargunth ser till att de har vapen och mat. Mot dem står Silverwing Sentinels från Silverwing Hold, Night Elf-krigare som svurit att driva varje inkräktare ut ur Ashenvale. Illiyana Moonblaze förser dem med förnödenheter från Silverwing Grove. Allierade från båda sidor strömmar till dalen: dvärgar och människor ställer sig vid väktarnas sida, tauren, troll och Forsaken vid utposternas."},{t="Kampen om fanorna",b="Båda sidor har ett fäste vid varsin ände av dalen: Warsong-sågverket för Horde och Silverwing Hold för Night Elf-folket. Båda förvarar sin fana där. Striden går ut på att plundra: krigare bryter sig in i fiendens fäste, tar dess flagga och rusar tillbaka till sitt eget medan försvararna jagar dem. Varje flagga som förs hem blir ett slag mot fiendens stolthet, och sidan som erövrar flest vinner dagen."}},faq={{q="Vad är Warsong Gulch?",a="Warsong Gulch är en slagmark i en skogsklädd dal mellan Ashenvale och The Barrens. Hordes Warsong Outriders och Night Elf-folkets Silverwing Sentinels slåss där om Hordes skogsavverkning i Ashenvale, och båda sidor försöker erövra den andras flagga.",al={"vad är warsong gulch","warsong gulch slagfält","wsg"}},{q="Varför slåss Horde i Warsong Gulch?",a="Horde behöver virke från Ashenvale för att bygga och försvara sitt hem i Kalimdor. Warsong-klanens sågverk i dalen är en av Hordes viktigaste källor, och Outriders försvarar det så att Hordes läger och murar kan fortsätta växa.",al={"hordes intressen i warsong gulch","varför avverkar orcerna ashenvale","warsong outriders motiv"}},{q="Varför slåss Night Elf-folket i Warsong Gulch?",a="För Night Elf-folket är Ashenvale en helig skog som de har vaktat i tiotusen år, och Warsong-klanen dödade en gång halvguden Cenarius där. Silverwing Sentinels kämpar för att stoppa skogsavverkningen och driva ut orcerna ur sina skogar, och resten av Alliance står vid deras sida.",al={"alliansens intressen i warsong gulch","varför slåss väktarna","silverwing sentinels motiv"}},{q="Vilka är Warsong Outriders?",a="Warsong Outriders är Hordes krigare i Warsong Gulch, rekryterade från Warsong-klanen som en gång leddes av Grom Hellscream. De får förnödenheter från Mor'shan Base Camp i norra The Barrens, där Kelm Hargunth utrustar dem som slåss för dem.",al={"warsong outriders","warsong-klanens krigare","kelm hargunth"}},{q="Vilka är Silverwing Sentinels?",a="Silverwing Sentinels är Night Elf-krigare från Silverwing Hold, som har svurit att driva ut Horde ur Ashenvale. Illiyana Moonblaze vid Silverwing Grove förser Alliansens hjältar med utrustning när de slåss vid deras sida i dalen.",al={"silverwing sentinels","silverwing hold","illiyana moonblaze"}},{q="Hur vinner man slaget i Warsong Gulch?",a="Båda sidor förvarar sin flagga i sitt eget fäste. Krigare plundrar fiendens bas, tar dess flagga och för den tillbaka till sitt eget fäste medan de försvarar sin fana. Sidan som för hem flest flaggor vinner.",al={"målen i warsong gulch","erövra flaggan i warsong gulch","hur man vinner warsong gulch"}}},fp="13,291,16.424.0,23.488.0,28.315.0,22.226.0,42.201.0,46.259.0,30.223.0,33.216.0,39.193.0"}
P.entries["zone:westernplaguelands"] = {n="Western Plaguelands",s="Western Plaguelands var en gång norra Lordaerons bördiga kornbod. Nu kvävs området av giftig dimma och horder av odöda. Kel'Thuzads kittlar ödelade gårdarna och städerna, men jorden klamrar sig envist fast vid livet. Argent Dawn, Alliance, Forsaken och Scarlet Crusade för desperata fälttåg över de fördärvade fälten.",h="Western Plaguelands var en gång norra Lordaerons bördiga kornbod.",kw={"andorhal","the bulwark","caer darrow","pestkittlar","chillwind camp","hearthglen","mardenholde keep","scholomance","uther's tomb","western plaguelands"},ang={["class:Paladin"]="Lordaerons vanhelgade fält är en dyster prövning för heliga krigare. Här kan du vallfärda till Uther's Tomb och föra ett rättfärdigt krig mot fasorna i Scholomance och Hearthglens fördärvade fanatiker.",["faction:Alliance"]="Chillwind Camp är Alliance främsta garnison vid fronten. Där leder Commander Ashlam Valorfist fälttåg för att slå ut pestkittlarna och hämnas Lordaerons fallna städer.",["faction:Horde"]="The Bulwark markerar gränsen för Forsakens välde. Härifrån rycker Horde österut för att oskadliggöra befälhavare från Scourge och utmana Scarlet Crusades fanatiker längs deras utsatta flank.",["profession:Herbalism"]="Den kvardröjande smittan gör området till en av få platser där sällsynta och farliga växter som Plaguebloom och Arthas' Tears kan slå rot bland fördärvade tallskogar."},sec={{t="Lordaerons kornbod",b="Före det tredje kriget var landet en grönskande korridor av gårdar som sträckte sig österut från Tirisfal Glades mot Darrowmere Lake. Hearthglen skötte den norra förvaltningen från Mardenholde Keep, medan den vidsträckta staden Andorhal organiserade lagringen och exporten av spannmål i hela kungariket. Den viktiga jordbruksrollen gjorde området till Kel'Thuzads främsta mål. Genom att föra in odödhetens pest direkt i spannmålsleveranserna i Andorhal förvandlade The Cult of the Damned Lordaerons föda till dess undergång."},{t="Ett land under belägring",b="För att förgifta jorden för alltid reste Scourge fyra enorma pestkittlar på de största jordbruken: Felstone Field, Dalson's Tears, The Writhing Haunt och Gahrron's Withering. I dag sköter monstruösa kittelherrar dessa giftiga kar och pumpar ut giftig dimma i luften. Träden runt omkring vrider sig av svullna, tumörliknande utväxter, och fördärvat djurliv härjar i snåren. Under Caer Darrow på Darrowmere Lake utbildar Darkmaster Gandling nekromantiker i Scholomance, vilket förvärrar hotet från de odöda."},{t="Splittrade fraktioner",b="Trots att Scourge finns överallt håller flera fraktioner fast vid utsatta fästen. Scarlet Crusade kontrollerar fästningen Hearthglen i norr och renar allt de anser vara besmittat med fanatisk iver. I söder utgår Alliance-styrkor från Chillwind Camp, medan Forsaken försvarar sina gränser vid The Bulwark. Den neutrala Argent Dawn samordnar kampen mot de odöda kittlarna och vägleder den. Orden hjälper hjältar från båda fraktionerna och vaktar Uther's Tomb, den sista verkligt helgade marken i området."}},faq={{q="Varför drabbade pesten området så hårt?",a="Andorhal var norra Lordaerons knutpunkt för spannmålstransporter. Kel'Thuzad riktade avsiktligt in sig på områdets försörjning, infekterade spannmålssilor och ställde upp enorma pestkittlar på fyra stora jordbruk för att snabbt sprida odödhet genom matleveranser i hela kungariket.",al={"varför är western plaguelands pesthärjat","vad hände med andorhal","varför finns kittlar här"}},{q="Vem kontrollerar Hearthglen i norr?",a="Hearthglen och dess fästning, Mardenholde Keep, styrs av Scarlet Crusade. Platsen var ursprungligen ett regionalt förvaltningscentrum för Lordaeron, men fanatikerna avrättar nu alla utomstående som närmar sig deras gränser. De betraktar alla som inte tillhör korståget med misstänksamhet.",al={"hearthglens fraktion","vilka bor i mardenholde keep","är hearthglen vänligt"}},{q="Var hittar Alliance- och Horde-spelare säkra utposter?",a="Alliance håller till vid Chillwind Camp nära den södra gränsen mot Alterac Mountains. Där finns en flygmästare och allierade från Argent Dawn. Horde utgår från The Bulwark vid den västra gränsen, där vägen in från Tirisfal Glades går.",al={"var finns flygrutterna","hordes läger i wpl","alliances läger i wpl"}},{q="Vad har pestkittlarna på fälten för syfte?",a="The Cult of the Damned reste dessa kittlar vid Felstone Field, Dalson's Tears, The Writhing Haunt och Gahrron's Withering. De pumpar ständigt ut pestångor i luften och jorden. Agenter från Argent Dawn rekryterar äventyrare för att döda kittelherrarna och motverka de giftiga brygderna.",al={"vad är pestkittlarna","kittlarnas syfte","felstones pestkittel"}},{q="Vad är Scholomance och var ligger det?",a="Scholomance är en underjordisk nekromantiskola som drivs av Scourge och The Cult of the Damned. Den ligger gömd under ruinerna av Caer Darrow, en fästningsö i den sydöstra delen av Darrowmere Lake.",al={"scholomances plats","var ligger scholomance","caer darrow-instans"}},{q="Finns det någon del av Western Plaguelands som är ofördärvad?",a="Uther's Tomb ligger på Sorrow Hill nära områdets södra kant och är fortfarande helt helig och orörd av fördärvet. Den står som ett helgat minnesmärke över den fallne högste generalen Uther the Lightbringer och den förlorade Order of the Silver Hand.",al={"helig mark i wpl","är uthers grav orörd","är uther's tomb säker"}}},fp="19,342,28.378.0,18.438.0,16.443.0,41.268.0,37.227.0,56.233.0,58.277.0,44.206.0,51.204.0"}
P.entries["zone:westfall"] = {n="Westfall",s="Westfalls gårdar ligger oskyddade, och Defias Brotherhood kontrollerar stora delar av landsbygden. Området var en gång Stormwinds kornbod, men kämpar nu utan kronans stöd eller militära garnisoner.",h="Westfalls gårdar ligger oskyddade, och Defias Brotherhood kontrollerar stora delar av landsbygden.",kw={"the deadmines","defias","skördegolem","milis","moonbrook","saldean","sentinel hill","stoutmantle","vancleef","westfall"},ang={["class:Rogue"]="Som skurk finner du ett skuggkrig i hela Westfall, där SI:7:s spioner möter Defias Brotherhoods gatukloka spejare, tjuvar och lönnmördare.",["faction:Alliance"]="Som alliansresenär kan du se hur People's Militia håller stånd i Sentinel Hill. Utan den skulle Defias Brotherhood kontrollera de södra vägarna till Elwynn Forest.",["profession:Cooking"]="Som kock kan du lära dig hur de hårt prövade nybyggarna på Saldean's Farm klarar sig med tuffa lokala bestar och lär resenärer att tillaga Westfall Stew.",["race:Human"]="Som människa visar Westfall Stormwinds politiska förfall. Bönderna som svälter i smutsen övergavs av adeln de slet för att försörja."},sec={{t="Ett övergivet land",b="Westfall försörjde en gång kungariket Stormwind med sina betesmarker och vetefält. Efter det andra kriget sinade kungarikets finanser, och dess ledare försummade området. Stormwind skickade resurser någon annanstans och drog in sina garnisoner, så att marken låg obrukad. Nu gör karga betesmarker, hårda kustvindar, skenande skördegolemer och Riverpaw-gnoller det svårt för de få nybyggare som är kvar att överleva."},{t="Brotherhood växer sig starkt",b="Defias Brotherhoods ankomst påskyndade Westfalls sammanbrott. Banditerna bär röda masker och följer en ledare vars namn ingen på landsbygden känner till. De gjorde Westfall till sitt fäste, brände böndernas fält, saltade jorden och tog över övergivna gruvor. Från Moonbrook, en spökstad, styr Brotherhood större delen av landsbygden i allt utom namnet."},{t="Folkets milis",b="House of Nobles har ignorerat Westfalls nöd, så lokalbefolkningen har tagit sitt försvar i egna händer. I Sentinel Hill bildade Gryan Stoutmantle People's Militia, en frivillig styrka som håller stånd mot gnoller och banditer. Stormwind skickar inga reguljära soldater eller förnödenheter. Milisen är beroende av kringvandrande äventyrare för att slå tillbaka Defias och skydda de gårdar som finns kvar."},{t="Stenhuggare i röda masker",b="Edwin VanCleef leder Brotherhood. Han var gillesmästaren som återuppbyggde Stormwind City, men House of Nobles nekade hans stenhuggare deras lön, och upplopp drev bort dem. De tog på sig den röda masken i Westfall. Banditerna som bränner dess fält är samma händer som reste huvudstadens murar."},{t="Sammansvärjningen i Deadmines",b="Under Moonbrook har Edwin VanCleef samlat stråtrövare, gobliner och avfällingar i Deadmines övergivna guldgruvor. Brotherhood bygger där en väldig bepansrad best, avsedd att segla längs kusten och bombardera Stormwind City."}},faq={{q="Varför står så många gårdar övergivna i Westfall?",a="Stormwind drog in sina garnisoner när underhållet blev för dyrt och lämnade Westfall oskyddat. Defias Brotherhood tog sedan över stora delar av landsbygden, drev bort nybyggare, brände åkrar och programmerade om mekaniska skördevakter till dödliga väktare.",al={"övergivna gårdar","varför är westfall öde","varför ligger marken obrukad"}},{q="Varför skickar Stormwind inga trupper för att hjälpa Westfall?",a="Kungarikets skattkammare är ansträngd, och House of Nobles prioriterar hot i andra länder högre. Intriger vid hovet har också i det tysta berövat Westfall uppmärksamhet och förnödenheter, så invånarna får försvara sig själva.",al={"varför finns ingen stormwind-armé","var är vakterna","stormwinds hjälp"}},{q="Vad är People's Militia?",a="Gryan Stoutmantle organiserade People's Militia i Sentinel Hill för att försvara Westfall. Utan soldater från kronan anslöt sig bönder och nybyggare för att bekämpa Defias Brotherhood och Riverpaw-gnollerna.",al={"folkets milis","sentinel hills milis","gryan stoutmantles armé"}},{q="Vem leder Defias Brotherhood i Westfall?",a="Edwin VanCleef, tidigare gillesmästare i Stonemasons Guild, leder Defias Brotherhood. Han övervakade återuppbyggnaden av Stormwind City och ledde sedan sina arbetare till Westfall och beväpnade dem efter att en bitter lönetvist slutat i upplopp.",al={"defias ledare","vem leder defias","vancleef"}},{q="Vad döljer sig i Moonbrook?",a="Under en oansenlig lada i Moonbrook finns ingången till Deadmines. Defias Brotherhood gjorde den övergivna guldgruvan till en underjordisk fästning och ett skeppsvarv för sitt krig mot Stormwind.",al={"moonbrooks hemlighet","vad finns i deadmines","moonbrooks gruva"}},{q="Varför angriper de mekaniska fågelskrämmorna människor?",a="Goblinmekaniker med band till Defias tillfångatog de mekaniska skördevakterna, som ursprungligen byggdes för att sköta grödorna och skrämma bort skadedjur. De byggde om dem så att de patrullerar fälten och dödar inkräktare.",al={"skördegolemer anfaller","skördevakter","onda fågelskrämmor"}}},fx={cd1e134e={q="Vad är Westfall?",a="Westfall är det vindpinade västra territoriet i Stormwinds kungarike, väster om Elwynn Forest och söderut till havet. En gång var det kungarikets bördiga kornbod, vars böljande kullar och vida betesmarker försörjde Stormwind i generationer. I dag har landet försummats av kronan och härjats av konflikter, och förfallit till trädlösa dammslätter, förstörda gårdar och laglöst territorium.",al={"vad är det här för zon","berätta om westfall","westfalls historia"}},["44cadea7"]={q="Varför är det så tomt här ute?",a="En förvärrande blandning av torka, försummelse och banditvälde tömde landsbygden på folk. Efter det andra kriget riktade Stormwind sina soldater åt annat håll och lämnade de lokala gårdarna försvarslösa. När Defias Brotherhood gjorde uppror drev de bort bönder, brände odlingar och saltade åkrarna. Utan kungliga garnisoner som kunde skydda dem flydde eller svalt de flesta invånarna.",al={"varför är westfall öde","varför är det så tomt","varför bor det ingen här"}},["1a97e791"]={q="Var Westfall alltid så fattigt?",a="Inte alls. I generationer var Westfall Stormwinds stolta jordbrukshjärta, känt för sina gyllene vetefält, bördiga jordar och rika guldgruvor som Jangolode och The Deadmines. Maten därifrån försörjde huvudstaden och gruvorna fyllde de kungliga skattkamrarna, innan krig och oroligheter i riket lämnade landet öde.",al={"var westfall alltid fattigt","var westfall rikt förr","westfalls förflutna"}},["1d4a9481"]={q="Vilka är Defias Brotherhood?",a="Defias Brotherhood är en stor kriminell organisation bestående av avhoppade stenhuggare, tjuvar, rövare och utstötta. Under ledning av Edwin VanCleef tog de över Westfalls övergivna jordbruk och gruvor för att föra ett bittert skuggkrig mot Stormwinds kungarike. De vill utkräva hämnd för obetalda skulder och svek som de anser sig ha utsatts för.",al={"vilka är defias","vad är defias brotherhood","vilka är de här banditerna"}},b6953315={q="Varför bär Defias röda bandanas?",a="Röda bandanas är Defias Brotherhoods kännetecken, och materialet visar en medlems rang. Röda sidenbandanas bärs av medlemmar med högre rang. Scout Riell ber äventyrare samla in dem som bevis på att medlemmarna har dödats.",al={"varför röda bandanas","defias röda masker","vad betyder de röda maskerna"}},["908b4fe1"]={q="Vad vill Defias ha i Westfall?",a="De ser Westfall som sitt självständiga fäste och sin uppmarschplats. Genom att kontrollera guldgruvorna, lägga beslag på matförråd och driva bort bönder som är lojala mot kronan kan de i hemlighet bygga upp sina styrkor och sin krigsmateriel utom synhåll för Stormwind, samtidigt som de smider planer på att störta kungariket.",al={"vad vill defias ha","defias mål i westfall","varför är defias i westfall"}},d384bc2d={q="Varför skickades jag till Westfall?",a="Du skickades hit eftersom Stormwinds reguljära militär vägrar eller misslyckas med att sända trupper till Westfall, så territoriet riskerar att helt falla i banditernas händer. Myndigheterna i Elwynn skickar skickliga äventyrare västerut för att hjälpa de kämpande lokalborna, som är i desperat behov av hjälp.",al={"varför är jag i westfall","vem skickade mig till westfall","varför skickades jag hit"}},d59f010f={q="Vem är Gryan Stoutmantle?",a="Gryan Stoutmantle är en paladin av Silver Hand och född i Westfall. När han återvände hem efter striderna i Lordaeron under det tredje kriget fann han sitt hemland översvämmat av banditer och övergivet av Stormwinds militär. Som svar samlade han lokala försvarare och grundade Folkets milis vid Sentinel Hill.",al={"vem är stoutmantle","gryan stoutmantle","vem leder sentinel hill"}},af1c3ddb={q="Är Gryan Stoutmantle verkligen den som styr Westfall?",a="I praktiken, ja. Pojkkungen i Stormwind har det lagliga anspråket på Westfall, men kronan utövar knappt någon faktisk makt här. Stoutmantle och hans frivilliga milis vid Sentinel Hill utgör det enda fungerande försvaret och den enda lagupprätthållande styrkan som finns kvar i riket.",al={"vem styr westfall","är stoutmantle ledaren","vem bestämmer"}},c01912f7={q="Vad hände med Stonemasons Guild?",a="Under guildmästaren Edwin VanCleef ägnade sig Stonemasons Guild i åratal åt att återuppbygga Stormwind City efter det första kriget. När arbetet var klart vägrade Adelsrådet att betala den överenskomna summan. Efter att fredliga vädjanden misslyckats upplöstes gillet med våld, vilket utlöste rasande upplopp som drev stenhuggarna i exil.",al={"vad hände med stonemasons","stonemasons guilds historia","vilka var stenhuggarna"}},ec2fd06e={q="Vägrade Stormwind verkligen att betala stenhuggarna?",a="Ja. Adelsrådet hade dragit på sig enorma skulder genom att utöka militära expeditioner på andra håll, vilket nästan gjorde kungariket bankrutt. Påverkade av hovintriger och aristokratisk arrogans erbjöd adelsmännen bara småsmulor för ett enormt arbete och vägrade helt att hålla sig till de fullständiga avtalen.",al={"lurade stormwind stenhuggarna","varför betalade inte adelsmännen","tvisten om stenhuggarnas betalning"}},cf60f690={q="Varför finns det så många gnoller i Westfall?",a="Gnollerna i Riverpaw-flocken har tagit sig över gränsen för att utnyttja frånvaron av Stormwinds soldater. Än värre är att Defias Brotherhood aktivt anställde dem som legosoldater och placerade dem bland kullarna och slätterna, där de ligger i bakhåll för resande och trakasserar de gårdar som finns kvar.",al={"varför är gnollerna här","riverpaw-gnoller i westfall","danuvin-gnoller"}},e40fa3bd={q="Vad är Moonbrook?",a="Moonbrook var en gång den främsta marknads- och gruvstaden i södra Westfall. Staden ligger ovanför den uråldriga ingången till The Deadmines och togs helt över och tömdes av Defias Brotherhood. De använder nu de tomma byggnaderna som vaktpost runt sitt underjordiska fäste.",al={"vad är moonbrook","moonbrooks historia","berätta om moonbrook"}},["46f1c864"]={q="Vart leder utredningen av Defias?",a="Din utredning avslöjar Brotherhoods hemliga hjärta under Moonbrook, i The Deadmines. Där, djupt inne i de underjordiska grottorna, övervakar Edwin VanCleef bygget av en väldig bepansrad best avsedd att bombardera Stormwind från havet. Det leder till en direkt attack mot guildmästaren själv.",al={"vart leder defias uppdrag","hur slutar defias historia","slutet på the deadmines"}},["27471424"]={q="Hur hamnade jag i Westfall?",a="Du korsade troligen flodbron från Elwynn Forest och följde vägen västerut, dit du skickats av myndigheterna eller vänner till Sentinel Hill. Stormwind har fullt upp och kan inte avvara kungliga trupper, så ryktet har spridit sig i grannländerna att Gryan Stoutmantle och de lokala bönderna desperat behöver hjälp av dugligt folk. Oavsett om du kom till fots efter en vädjan om hjälp eller bara följde kungsvägen i jakt på arbete, har du tagit dig in i ett rike som kungarikets soldater nästan helt har övergett.",al={"hur kom jag hit","hur kom jag till westfall","hur hamnade jag här"}},["6324593c"]={q="Vad förväntas jag göra i Westfall?",a="Ditt främsta uppdrag är att hjälpa People's Militia vid Sentinel Hill att slå tillbaka de otaliga hot som plågar provinsen. Gryan Stoutmantle behöver frivilliga som gallrar bland de aggressiva vilddjuren, tystar de förrymda skördeväktarna som stryker omkring på obrukade fält och driver tillbaka Riverpaw-gnollerna. Framför allt ska du spåra upp den svårfångade Defias Brotherhood, ta reda på var de gömmer sig och bryta deras järngrepp om det som återstår av Westfalls kämpande gårdar.",al={"vad ska jag göra här","vad gör jag i westfall","varför är jag här"}}},fp="8,190,18.391.0,27.355.0,20.380.0,19.294.1,24.254.1,44.264.0,52.230.0,29.199.0,45.227.1,32.204.1,51.187.0"}
P.entries["zone:wetlands"] = {n="Wetlands",s="The Wetlands är ett vidsträckt, dimhöljt träsk mellan Khaz Modans berg och Baradin Bays stränder. Området har härjats av dvärgakrig och invasioner från orcher och fungerar som en karg buffert mellan Ironforge och Lordaerons nordliga länder. Den befästa hamnen Menethil Harbor är Alliansens främsta livlina i en blöt vildmark som översvämmas av Dragonmaw-orcher, murlocer och gnoller.",h="The Wetlands är ett vidsträckt, dimhöljt träsk mellan Khaz Modans berg och Baradin Bays stränder.",kw={"baradin bay","dragonmaw","dun algaz","dun modr","grim batol","menethil","menethil harbor","thandol span","wetlands"},ang={["faction:Alliance"]="Menethil Harbor är Alliansens främsta djupvattenhamn för färder över Great Sea och förbinder de östra kungadömena med expeditionsutposter i Kalimdor.",["profession:Mining"]="Kullarna och grottorna i Thelgen Rock rymmer rika mineralådror, däribland sällsynta fyndigheter av Incendicite Ore som dvärggruvare och ingenjörer eftertraktar.",["race:Dwarf"]="För dvärgar är Wetlands en bitterljuv plats, präglad av förlusten av Dun Modr, Grim Batols uråldriga tragedi och det ständiga arbetet med att försvara kung Magni:s handelsväg norrut."},sec={{t="Ett land av vatten och ruiner",b="Under Stonewrought Dams höga stup breder Wetlands ut sig som en kall, vattensjuk trakt, höljd i ständig dimma och grå himmel. Här fanns en gång livliga dvärgbosättningar, men nu ligger sjunkna stenruiner, blöta träsk och förrädiska kärr utspridda över området. Äventyrare som tar sig in måste färdas genom smala pass, antingen norrut genom Dun Algaz barrikaderade ravin från Loch Modan eller över Thandol Spans höga valv från Arathi Highlands."},{t="Grim Batols ärr",b="Träskets östra delar domineras av Grim Batols hotfulla närvaro, det tidigare fästet för Wildhammer. Efter att platsen skändats under hammarnas tre krig blev den Dragonmaw-klanens befästa tillflykt under andra kriget. När den röda drakflykten bröt sig fri ur orchernas fångenskap krossade deras flammande hämnd orchernas styrkor och ödelade de omgivande sluttningarna. I dag vaktar röda drakspawn och wyrmkin Dragonmaw Gates mot alla inkräktare, medan förvildade rester av Dragonmaw-klanen bor i utspridda läger i kullarna och fortsätter att trakassera resande genom träsket."},{t="Västkustens hamn",b="Menethil Harbor ligger vid Baradin Bays kant och är hjärtat i Alliansens handel och logistik i Khaz Modan. Hamnen har fått sitt namn till kung Terenas Menethil II:s ära och förbinder Eastern Kingdoms med avlägsna Kalimdor genom regelbundna transportfartyg till Theramore Isle och, via Southshore, till Auberdine. Trots sin strategiska militära betydelse och gedigna dvärgarkitektur hotas hamnen ständigt av kustnära murlocer, träskvarelser och plundrare som angriper fartyg i de klippiga farlederna."},{t="Belägrade gränstrakter",b="Wetlands är en aktiv krigszon på flera fronter. Längst i norr har Dark Iron-dvärgar under häxmästaren Balgaras the Foul saboterat Thandol Span med bomber och tagit över staden Dun Modr, vilket skurit av landvägen för förnödenheter. Samtidigt härjar Mosshide-gnoller i de centrala kärrmarkerna och hotar till och med uråldriga beskyddare som Rethiel the Greenwarden. Mellan kringströvande orchkrigare, Dark Iron-infiltratörer och förbannade skeppsvrak längs kusten kräver det ständig vaksamhet att hålla träsket."}},faq={{q="Hur tar jag mig till Wetlands till fots?",a="Äventyrare från Alliansen reser vanligtvis norrut från Loch Modan genom bergspasset Dun Algaz. Hordens resande från norr kan ta sig över Thandol Span från Arathi Highlands. Var försiktig, eftersom båda vägarna är omstridda av fientliga styrkor som Dragonmaw-orcher och Dark Iron-dvärgar.",al={"hur man tar sig till wetlands","vägen till wetlands","ta sig till wetlands"}},{q="Vart går båtarna från Menethil Harbor?",a="Däcken i Menethil Harbor har två stora färjerutter till Kalimdor. Det ena fartyget anlöper Southshore i Hillsbrad Foothills och seglar sedan över Great Sea till Auberdine vid Darkshores kust. Det andra seglar söderut till Theramore Isle i Dustwallow Marsh.",al={"menethils båtar","fartyg från menethil harbor","vart går båten i wetlands"}},{q="Vad är Grim Batol och varför vaktas det?",a="Grim Batol är en uråldrig dvärgfästning som övergavs efter hammarnas tre krig och senare ockuperades av Dragonmaw-klanen. Efter andra kriget drev den befriade röda drakflykten bort orcherna och förseglade berget. Mäktiga röda drakspawn och wyrmkin patrullerar Dragonmaw Gates för att hindra någon från att gå in i de förbannade salarna.",al={"varför finns det drakar vid grim batol","röda drakar i grim batol","dragonmaw gates"}},{q="Vad hände med Dun Modr?",a="Dun Modr var ett nordligt dvärgafäste som vaktade Thandol Span. Staden anfölls nyligen och intogs av Dark Iron-dvärgar ledda av Balgaras the Foul. De överlevande, ledda av Rhag Garmason, håller ett belägrat läger i närheten medan de kämpar för att återta staden.",al={"vem förstörde dun modr","dun modrs ruiner","dark iron i dun modr"}},{q="Vem är Rethiel the Greenwarden?",a="Rethiel är ett uråldrigt kärrvidunder som håller till i Wetlands Green Belt. Han söker hjälp från resande för att hejda de aggressiva Mosshide-gnollerna och göra slut på sjuka Fen Creepers så att kärrmarkerna kan återhämta sig.",al={"the green belt","rethiel i wetlands","vem är greenwarden"}},{q="Varifrån kommer alla orcher i träsket?",a="Orcherna tillhör Dragonmaw-klanen, som befäste sig i Grim Batol under andra kriget. Efter att den befriade röda drakflykten krossat deras styrkor flydde de överlevande orcherna ner i träsket och kullarna, där de fortfarande plundrar vägar och angriper resande.",al={"varför finns det orcher i wetlands","dragonmaw i wetlands","dragonmaw-klanen i wetlands"}}},fx={["2cd88152"]={q="Vad är Wetlands?",a="Wetlands är ett kallt och vidsträckt träskland mellan bergen i Khaz Modan och västerhavet. Regionen ligger insvept i ständigt grå dimma, strax norr om Loch Modan och söder om Arathi Highlands. En gång fanns här många dvärgbosättningar, men tidigare krig har ödelagt området. Nu är det en karg och otämjd vildmark som skiljer dvärgkungadömena från ruinerna av Lordaeron.",al={"vad är wetlands","wetlands bakgrund","berätta om wetlands"}},["4984d286"]={q="Varför är det bara träsk här?",a="Wetlands ligger i en låg sänka som omges på tre sidor av höga bergskedjor och samlar upp avrinning från höjderna ovanför. Otaliga floder, dammar och bäckar rinner ner mot Baradin Bay och håller marken ständigt vattenmättad och kall.",al={"varför är wetlands ett träsk","wetlands geografi","varför så mycket vatten i wetlands"}},["60c5b961"]={q="Vilka bor i Wetlands?",a="Alliansens främsta fäste är Menethil Harbor, där dvärgbergsmän kämpar för att hålla viktiga utposter. Men fientliga krafter dominerar vildmarken: utstötta Dragonmaw-orcher gömmer sig i de östra bergssluttningarna, Mosshide-gnoller stryker omkring i kärren, murlocker kryper längs kusterna och våldsamma Dark Iron-dvärgar tränger söderut från Dun Modr.",al={"vilka bor här","fraktioner i wetlands","invånare i wetlands"}},["8d21dccb"]={q="Vad är Menethil Harbor, och vem styr där?",a="Menethil Harbor är en kraftigt befäst hamnstad på en ö i Baradin Bay, och Alliansens främsta kustport till Khaz Modan. Staden är uppkallad efter kung Terenas Menethil II av Lordaeron och sköts av dvärgar och allierade människor. Den skyddas av Menethil Keeps bastanta stenmurar och vaktas av Captain Stoutfists garnison.",al={"menethil harbor","vem styr menethil","menethil stad"}},fd9bb568={q="Varför byggde dvärgarna en hamn här?",a="Under det andra kriget byggde Orgrim Doomhammer ett skeppsvarv här för att föra horden över Baradin Bay till Lordaeron. När orcherna hade drivits bort återtog Alliansen platsen och byggde om den till en blomstrande hamn. Därifrån kunde viktiga sjövägar förnödenheter föra mellan Khaz Modan, mänskliga allierade och avlägsna länder på andra sidan havet.",al={"varför menethil harbor","varför bygga en hamn i träsket","skälet till menethil harbor"}},["4cff40a7"]={q="Tillhör Menethil Harbor Alliansen?",a="Ja. Menethil Harbor är ett officiellt fäste för Alliansen. Det är en rå och livlig hamnstad full av sjömän, köpmän, resenärer och hårdföra hamnarbetare, men där vajar Alliansens baner och Ironforge-styrkor försvarar staden.",al={"tillhör menethil alliansen","menethil harbor fraktion","vem äger menethil harbor"}},["6dc9c02b"]={q="Vem bestämmer här omkring?",a="Det finns ingen ensam härskare över det otämjda träsklandet. Alliansens makt är samlad i Menethil Harbor, under Captain Stoutfist och garnisonen i Menethil Keep. Utanför hamnens murar är träsket en laglös gränsbygd som militära patruller, orchkrigsherrar och urtidsbestar kämpar om.",al={"vem leder wetlands","befälhavare i wetlands","vem bestämmer här"}},b8a9f96f={q="Vem är Captain Stoutfist?",a="Captain Stoutfist är dvärgarnas befälhavare för garnisonen i Menethil Harbor. Från hamnens trygghet samordnar han försvaret av träsket och ger dugliga äventyrare i uppdrag att hejda de oupphörliga räderna från de närliggande Dragonmaw-orcherna.",al={"captain stoutfist wetlands","stoutfist bakgrund","vem är stoutfist"}},["38351a9f"]={q="Vilka är Dragonmaw-orcherna, och varför är de här?",a="Dragonmaw är en brutal orchklan som använde Demon Soul för att förslava Alexstrasza och den röda drakflykten under det andra kriget. De härskade från Grim Batols höjder. När drakdrottningen befriades krossade de hämndlystna drakarna klanen och skingrade de överlevande i Wetlands träsk och berg. Där utgör de fortfarande ett våldsamt och ihållande hot.",al={"dragonmaw wetlands","varför är dragonmaw i wetlands","dragonmaw-orcher"}},ecc875bb={q="Vilka är Dark Iron-dvärgarna, och varför anfaller de Dun Modr?",a="Dark Iron är en förrädisk dvärgklan som länge varit landsförvisad från Ironforge och behärskar skuggmagi. När Alliansens styrkor skickades utomlands passade de på att slå till norrut, inta staden Dun Modr och sabotera Thandol Span. På så vis ville de kapa viktiga förbindelser och återta mark i Khaz Modan.",al={"dark iron dun modr","varför är dark iron i wetlands","dark iron anfaller wetlands"}},["0f0d7fa8"]={q="Vad är Thandol Span, och varför är det viktigt?",a="Thandol Span är ett magnifikt par väldiga stenbroar som dvärgar byggt över klyftan mellan norra Khaz Modan och Arathi Highlands. De byggdes efter de tre hammarna krig för att främja handel och gemenskap med Wildhammers. Än i dag är de den enda landförbindelsen mellan de södra kungadömena och norra Lordaeron.",al={"thandol span","thandol-bron","varför är thandol span viktigt"}},faff9f74={q="Varför vill Dark Iron spränga bron?",a="Genom att förstöra Thandol Span vill Dark Iron isolera Ironforge och Khaz Modan helt från Alliansens allierade i Lordaeron. Om livlinan över land kapas kan inga förstärkningar marschera söderut för att återta Dun Modr eller hjälpa till mot fler angrepp från Dark Iron.",al={"varför förstöra thandol span","dark irons broplan","spränga thandol span"}},eabba297={q="Hur hamnade jag i Wetlands, och vart leder vägen härifrån?",a="De flesta resenärer kommer norrut från Loch Modan genom bergspasset Dun Algaz, eller tar den långa båtresan till Menethil Harbor. Härifrån fortsätter vägen norrut över Thandol Span till Arathi Highlands, medan fartyg från hamnen för äventyrare västerut över Stora havet.",al={"vart ska man ta vägen från wetlands","nästa område efter wetlands","väg genom wetlands"}},["75fb0ece"]={q="Är det här vägen till Ironforge?",a="Ja. Följ vägen söderut ut ur träsket så kommer du rakt in i Dun Algaz smala tunnlar. Genom bergen når du Loch Modan. Därifrån går huvudvägen västerut genom North Gate Pass, direkt in i Dun Moroghs snö och vidare till Ironforge.",al={"vägen till ironforge från wetlands","hur tar jag mig till ironforge från wetlands","vägen till ironforge"}},["78aee5e0"]={q="Hur hamnade jag i Wetlands?",a="De flesta alliansresenärer når Wetlands genom att färdas norrut från Loch Modan och ta sig genom Dun Algaz smala bergstunnlar ner till de dimmiga kärren. Andra kommer med skepp över Stora havet och seglar från Kalimdors stränder till Menethil Harbor. De som färdas söderut från Arathi Highlands måste i stället ta sig över de farliga övergångarna på det förstörda Thandol Span.",al={"hur hamnade jag här","hur kom jag till wetlands","var kom jag ifrån"}},["87ca94d2"]={q="Vad förväntas jag göra i Wetlands?",a="Träsket är en hårt ansatt gränsbygd där Alliansen klamrar sig fast vid ett bräckligt fäste. Från Menethil Harbor ska du skydda viktiga handelsvägar och slå tillbaka de Dragonmaw-orcher som fortfarande härjar i låglandet. Längre österut och norrut behöver dvärgbergsmän din hjälp att hålla fientliga gnollflockar stången, bistå utsatta utgrävningsplatser och driva tillbaka Dark Iron-dvärgarna som hotar att helt kapa Thandol Span.",al={"vad ska jag göra här","varför är jag här","vad är mitt uppdrag i wetlands"}}},fp="8,284,24.340.0,23.473.0,22.380.0,18.430.0,40.227.0,41.185.0,41.317.0,26.225.0,31.198.1,46.224.0"}
P.entries["zone:winterspring"] = {n="Winterspring",s="Winterspring är en vidsträckt, snötäckt dal högt uppe på Mount Hyjals nordöstra sluttningar, precis ovanför Moonglades och Felwoods förtrollade skogar. Regionen är känd för sin bitande kyla, sina urgamla Highborne-ruiner och kringströvande toppredatorer, och kretsar kring den neutrala goblinutposten Everlook. Här finns fortfarande hårda naturfaror och rester av den blå drakflygeln, samtidigt som dalen bekämpar demonisk korruption längs de södra höjderna.",h="Winterspring är en vidsträckt, snötäckt dal högt uppe på Mount Hyjals nordöstra sluttningar, precis ovanför...",kw={"blå drakar","darkwhisper gorge","donova snowden","everlook","frostsaber","icecap","kel'theril","mazthoril","timbermaw","winterspring"},ang={["class:Druid"]="Högt ovanför Moonglade ligger Winterspring, en plats av helig betydelse där Malfurion Stormrage väckte Druids of the Talon ur deras uråldriga sömn under Tredje kriget.",["faction:Alliance"]="Alliansens hjältar besöker ofta Rivern Frostwind vid Frostsaber Rock. De arbetar oförtröttligt i den extrema kylan för att vinna de ansedda Winterspring Frostsaber-ridbestarnas lojalitet.",["profession:Herbalism"]="Winterspring är den enda kända växtplatsen för Icecap, en oumbärlig alpört som är mycket eftertraktad för avancerade alkemiska brygder. Här finns också spridda Mountain Silversage och sällsynta Black Lotus-blommor.",["profession:Mining"]="De isiga klipporna och grottväggarna i dalen är rika på värdefulla mineraler. Där hittar man ofta små och rika thoriumådror samt sällsynta fyndigheter av äkta silver.",["race:NightElf"]="Winterspring är nära knutet till alvernas historia. Här finns gravkamrarna där Druids of the Talon vilade i årtusenden, de tragiska ruinerna av Kel'Theril och blottlagda rötter från Nordrassil som skadades under slaget vid Mount Hyjal."},sec={{t="Ett rike av ständig frost",b="Winterspring ligger tusentals fot över den omgivande vildmarken, under klar bergsluft och obevekliga snöstormar. Enorma, blottlagda rötter från världsträdet Nordrassil skär genom snödrivorna som väldiga trävalv, förvridna under Tredje krigets avgörande strider. Medan stora delar av norra Kalimdor domineras av täta skogar och varmt klimat, är Winterspring ett stilla land med medelhöga alpina skogar, klippiga branter och frusna sjöar, där väldiga frostsablar, chimärer, yetier och tjockpälsade vinterbjörnar håller till."},{t="Vägar och utposter",b="För att nå denna höga platå måste du ta dig genom Timbermaw Holds urgamla, uthuggna passager. De vaktas av okorrumperade furbolger som noggrant granskar alla resenärer från Felwood eller Moonglade. Mitt i dalen ligger Everlook, en blomstrande handelsstad som drivs av Steamwheedle Cartel. Gobliner välkomnar både alliansens och hordens äventyrare med öppna register och erbjuder en oumbärlig tillflykt med ingenjörskonst, handel och varma eldar mot den bitande bergskylan."},{t="Gamla spöken och blå drakar",b="Århundraden innan dagens bosättningar uppstod byggde forntida alver staden Kel'Theril vid sjön. Efter att vårdslösa Highborne-trollkarlar krossade den förbannade Crystal of Zin-Malor greps de av vansinne, och rastlösa vålnader har vandrat bland de förstörda pelarna och det frusna vattnet ända sedan dess. Längre söderut reser sig Mazthorils grottiga höjder, den blå drakflygelns traditionella fäste i Kalimdor. Här vakar Spell-Weaver Malygos avkomma över de arkaniska strömmarna under beskydd av matriarken Haleh och bemöter lokala hot."},{t="Den hotande skuggan över ravinen",b="Wintersprings frid bryts tvärt vid den sydligaste gränsen, i Darkwhisper Gorge. Där krälar elitstyrkor av demoner, kvarlevor från Tredje krigets legioner, genom branta raviner som blockerar de höga vägarna mot Mount Hyjals topp. Samtidigt har de inhemska Winterfall-furbolgerna fallit offer för vidrig korruption, vilket fått oberoende forskare som Donova Snowden att undersöka den framryckande smittan innan hela dalens djurliv slukas."}},faq={{q="Hur tar jag mig till Winterspring?",a="Resenärer måste ta sig genom Timbermaw Hold, ett underjordiskt tunnelsystem i nordöstra Felwood. För att färdas fredligt genom grottorna måste du vinna de lokala Timbermaw-furbolgernas förtroende. De anfaller alla inkräktare som de anser vara fientliga. När du kommit ut genom den östra utgången breder Wintersprings snötäckta sluttningar genast ut sig framför dig.",al={"ta sig till winterspring","komma in i winterspring","ingång till winterspring","timbermaw-tunneln till winterspring"}},{q="Vem styr staden Everlook?",a="Everlook sköts av Steamwheedle Cartel, goblinernas handelskoalition. Tack vare goblinernas strikta vinstintresse och neutralitet kan både hordens och alliansens resenärer besöka stadens flygmästare, reparationsförsäljare, bankvalv och handelsstånd, så länge de inte stör freden innanför stadsgränsen.",al={"vem styr everlook","everlooks fraktion","är everlook neutralt"}},{q="Vilka är spökena som hemsöker Lake Kel'Theril?",a="De är andar efter Highborne-nattalver som bodde i den forntida staden Kel'Theril för tiotusen år sedan. När deras trollkarlar manipulerade den stulna Crystal of Zin-Malor utlöste dess krossande en katastrofal förbannelse. Århundraden senare drabbades även expeditioner av högalver av vansinne och dömdes att hemsöka de frusna ruinerna tillsammans med sina förfäder.",al={"spöken vid lake kel'theril","andar i ruinerna av kel'theril","vilka finns vid kel'theril"}},{q="Varför är Winterfall-furbolgerna aggressiva?",a="Winterfall-furbolgerna har dukat under för en spridande, onaturlig korruption som drivit klanen till vansinnigt raseri. Medan närliggande Timbermaw håller fast vid sitt förstånd har Winterfall fallit under mörka influenser. Det har fått forskare som Donova Snowden att studera smittan och rensa deras läger.",al={"varför är winterfall fientliga","winterfall-stammens korruption","donova snowden och furbolgerna"}},{q="Vad lever inne i Mazthoril?",a="Mazthoril är den blå drakflygelns främsta boplats och fristad i Kalimdor. Djupt inne i dess grottiga spiror vaktar wyrmkin, elitsyngel och uråldriga drakar mäktiga drakreliker och arkaniska hemligheter under den vakande blicken från Haleh, Malygos gemål.",al={"drakar i mazthoril","vad är mazthoril","blå drakar i winterspring"}},{q="Vad är Darkwhisper Gorge?",a="Darkwhisper Gorge är en förrädisk ravin längst söderut i dalen, där mäktiga elitdemoner från Tredje kriget håller till. Den fungerar som en hårt bevakad gräns längs de förrädiska stigarna som leder mot Mount Hyjals höjder.",al={"demoner i darkwhisper gorge","vad finns i darkwhisper gorge","hyjals port vid winterspring"}},{q="Kan jag träna eller tämja frostsablar här?",a="Längst norrut i dalen tar nattalven Rivern Frostwind hand om de inhemska vita katterna vid Frostsaber Rock. Äventyrare som hjälper honom att säkra förnödenheter och skydda flocken kan visa sig värdiga att lära sig hemligheterna bakom att föda upp och rida på en Frostsaber.",al={"frostsaber-riddjur","rivern frostwind och frostsaber","skaffa en frostsaber"}}},fp="12,328,26.408.0,23.361.0,26.385.0,31.374.0,29.250.0,30.220.0,45.324.0,43.293.0,28.244.0,26.191.0,39.225.0"}
P.entries["zone:zephras"] = {n="Zephras Isle",s="Zephras Isle är en svävande ö i Skywall, luftens elementarplan. Den är Skybornes urgamla hem, men deras samhälle står nu inför en existentiell kris när öns bärande magi långsamt försvagas. Kontakten med de närliggande himmelrikena har brutits, och invånarna kämpar mot elementarisk kollaps och flyktingar som anländer.",h="Zephras Isle är en svävande ö i Skywall, luftens elementarplan.",kw={"luftskepp","anvilas","elementarplan","siroccas","skyborne","skywall","valanaar","vindstenar","zephras"},ang={["class:Shaman"]="Zephras Isle ligger mitt i luftens elementarplan och visar vad som händer med elementära länder när andarna som håller dem i balans plötsligt försvinner.",["race:Skyborne"]="Zephras Isle är ditt förfädershem och din startplats, men öns kvarvarande skönhet döljer en akut kris med mark som faller sönder och elementarkraft som bleknar."},sec={{t="Ett rike i skyn",b="Zephras Isle är en isolerad landmassa som driver genom Skywalls ändlösa vindar. I generationer levde Skyborne här tillsammans med inhemska luftelementaler, som hjälpte till att bevara de magiska strömmar som höll ön svävande. Men för flera århundraden sedan försvann dessa elementarväktare helt. Utan deras närvaro och beskydd har de dolda förtrollningar som håller uppe landet långsamt börjat svikta, vilket får Zephras att spricka och bli allt mer instabil."},{t="Avskurna horisonter",b="Zephras var inte den enda tillflyktsorten för Skyborne på elementarplanet. Systeröarna Anvilas och Siroccas drev också genom Skywall, men kontakten mellan dem upphörde efter att elementalerna försvann. På senare tid har flyktingar från dessa sönderfallande grannöar lyckats ta sig till Zephras i jakt på trygghet. De för med sig dystra nyheter: de andra öarna faller sönder under deras fötter."},{t="Tröskeln till Azeroth",b="När deras egen landmassa långsamt vittrar sönder har Skyborne på Zephras börjat blicka bortom Skywalls gränser, mot Azeroth. Från Valanaars luftskeppshamnar ger sig luftskepp nu av för att upprätta sällsynta livlinor till de dödligas värld. Resorna förbinder luftdomänen direkt med platser på Azeroth, däribland utkanten av Dalaran i Alterac Mountains och Skywatcher Plateau i Mulgore."}},faq={{q="Var ligger Zephras Isle?",a="Zephras Isle ligger inne i Skywall, luftens elementarplan, och inte på Azeroths yta. Ön svävar bland de eviga molnen och vindströmmarna i detta eteriska rike.",al={"zephras isle läge","var ligger zephras","vilket plan ligger zephras på"}},{q="Varför faller Zephras Isle sönder?",a="Ön var beroende av de inhemska luftelementaler som en gång levde sida vid sida med Skyborne. För flera århundraden sedan försvann dessa elementaler, och de magiska grundvalar som förankrar och bevarar den flygande ön har sedan dess långsamt försvagats och vittrat sönder.",al={"varför kollapsar zephras","zephras isle förstörelse","döende ö"}},{q="Vad är Anvilas och Siroccas?",a="Det är närliggande flytande öar i Skywall där Skyborne också bor. Zephras Isle förlorade kontakten med båda när elementalerna försvann, och flyende flyktingar rapporterar nu att både Anvilas och Siroccas håller på att störta i avgrunden.",al={"anvilas","siroccas","andra skyborne-öar"}},{q="Hur tar man sig mellan Zephras Isle och Azeroth?",a="Skyborne driver luftskeppshamnar vid bosättningen Valanaar. Därifrån lyfter luftskepp och färdas över plangränsen till Azeroth, där de landar nära Dalaran i Alterac Mountains och vid Skywatcher Plateau i Mulgore.",al={"hur lämnar man zephras","zephras luftskepp","resa till azeroth"}},{q="Vilka är Skyborne?",a="Skyborne är invånarna som har sitt hem på Zephras Isle och dess systerriken i skyn. De har levt i Skywall i generationer och står nu inför förstörelsen av sitt flygande hemland när dess bindande magi bleknar.",al={"skyborne-folket","vem bor på zephras"}},{q="Vilka bor på Zephras Isle förutom Skyborne?",a="Förutom fridfulla byar och besökande flyktingar plågas ön av lokala banditer, nattklor som lever i grottor och vidunder i områden som Shriekling Den och Nightclaw Cavern.",al={"zephras invånare","fiender på zephras"}}},fx={b4875d06={q="Var ligger ön i förhållande till resten av Azeroth?",a="Zephras Isle ligger inte på Azeroths yta. Den driver genom Skywall, en separat dimensionell domän som titanernas skapelser utformade för att hålla kaotiska luftelementaler instängda. De enda fysiska förbindelserna mellan ön och den dödliga världen nedanför är särskilda luftskepp som lägger till vid Valanaar och färdas över gränsen till platser som Dalaran och Mulgore.",al={"var ligger zephras i förhållande till azeroth","ligger zephras i azeroth","zephras läge i förhållande till azeroth"}},["2c89f95d"]={q="Vilka är Al'Aketh?",a="Al'Aketh är en av fraktionerna som tävlar om herraväldet på Zephras Isle, tillsammans med The High Order och The Windshapers. När pylonerna som håller ön på plats sviktar och kampen för överlevnad blir allt mer desperat, kämpar Al'Aketh aktivt om överhöghet och kontroll över öns återstående mystiska resurser.",al={"vad är al'aketh","al'aketh-fraktionen","vilka är al'aketh"}},["6e14d755"]={q="Kommer jag så småningom att lämna ön?",a="Ja. Zephras Isle är ditt hem och din första träningsplats, men luftskepp lämnar skydockorna vid Valanaar och färdas genom planära rämnor till Azeroths fastland. De går direkt till Dalaran i Alterac Mountains och Skywatcher Plateau i Mulgore.",al={"kommer jag att lämna zephras","lämna zephras isle","kan vi ta oss till azeroth"}},["19470e71"]={q="Hur hamnade jag på Zephras Isle?",a="Du föddes bland Skyborne, shen'dorei som bor på denna svävande fristad högt uppe i Skywall, luftens elementarplan. För årtusenden sedan flydde dina förfäder från prins Tortheldrins utrensning i Eldre'Thalas och slöt en pakt med vindandar som lyfte denna fristad mot himlen. Medan andra systeröar som Anvilas och Siroccas faller sönder eller försvinner utom räckhåll, har Zephras Isle varit ditt hem sedan födseln. Här börjar du din resa bland ditt eget folk.",al={"hur hamnade jag här","hur tog jag mig till zephras isle","varför vaknade jag här","var kom jag ifrån"}},["5dae6f41"]={q="Vad förväntas jag göra på Zephras Isle?",a="Ditt hem rasar samman under dina fötter. För flera århundraden sedan försvann de välvilliga luftelementalerna, och de arkana pylonerna som håller Zephras Isle samman förlorar sin kraft. Flyktingar strömmar in från yttre öar som håller på att rasa samman, medan rivaliserande fraktioner, däribland The High Order, The Windshapers och Al'Aketh, grälar om det som återstår. Du måste hjälpa ditt folk, kuva inre hot och vilda bestar, hjälpa till att stabilisera den sviktande magin och till sist söka en väg ner till Azeroth innan ön faller.",al={"vad borde jag göra här","vad är mitt mål här","vad gör jag på zephras isle","varför är jag här"}},["1fd88046"]={q="Vad är Zephras Isle?",a="Zephras Isle är en svävande landmassa högt uppe i Skywall, luftens elementplan. För tusentals år sedan förhandlade nattalver som flydde förföljelse i Eldre'Thalas med de inhemska vindandarna. Andarna lyfte ön mot himlen för att hålla dem trygga. Ön är deras ättlingars, Skybornes, förfäders fristad.",al={"vad är zephras","om zephras isle","information om zephras isle"}},["7ea7c85c"]={q="Vad hände på Zephras Isle?",a="Zephras Isle lyftes upp till Skywall efter att högborne förfäder bröt sig loss från prins Tortheldrins blodiga styre i Eldre'Thalas. Skyborne levde i harmoni med luftens elementarer i tusentals år, men för flera hundra år sedan försvann deras elementära beskyddare utan förklaring. Utan deras ständiga magi började pelarna som förankrar ön förfalla. Flyktingar från närliggande öar som håller på att falla sönder har sökt sig hit, samtidigt som interna fraktioner kämpar om de sinande resurserna.",al={"zephras historia","vad hände här på zephras","zephras bakgrund"}},["70a3c6ae"]={q="Är Zephras Isle farligt?",a="Ja. Ön håller själv på att bli instabil och störta från himlen, och när de elementära beskyddarna försvann lämnades landet i kaos. Banditläger, bon av fientliga vilddjur och en våldsam politisk konflikt mellan The High Order, Windshapers och Al'Aketh gör det farligt att färdas utanför de befästa bosättningarna.",al={"är zephras farligt","hot på zephras","faror på zephras"}}},fp="12,263,13.353.0,16.350.0,20.265.0,30.156.0,34.190.0,30.197.0,54.178.0,21.180.0,47.152.0"}
